def _positive_int(s: str) -> int:
    """argparse `type=` helper. Rejects non-positive integers with the
    standard argparse error message. Used by --confidence-rounds."""
    try:
        n = int(s)
    except ValueError:
        raise argparse.ArgumentTypeError(f"{s!r} is not an integer")
    if n < 1:
        raise argparse.ArgumentTypeError(f"{s!r} is not a positive integer")
    return n


def resolve_verbosity(repo_root: Path,
                      cli_value: str | None = None) -> str:
    """Resolve the verbosity level. Order:
    --verbosity CLI flag → LEERIE_VERBOSITY env var → leerie.toml →
    VERBOSITY_DEFAULT. argparse validates `cli_value` via choices=, so
    it is trusted when set. env and file values are rejected via die()
    if not in VERBOSITY_VALUES — a bad config is caught at startup,
    not during a worker run.

    The -v/-vv/-q/-qq shortcuts are resolved separately in main()
    BEFORE this function is called — they map to one of VERBOSITY_VALUES
    and pass through as cli_value. The shortcut→level mapping is anchored
    to `normal` (the pre-streaming behavior), not to VERBOSITY_DEFAULT,
    so -v means "show me the streaming feature" rather than "bump above
    the default by one"."""
    return _resolve_enum_pref(
        repo_root, cli_value,
        env_var=VERBOSITY_ENV, file_key="verbosity",
        file_name=VERBOSITY_FILE,
        allowed=VERBOSITY_VALUES, default=VERBOSITY_DEFAULT)


def _verbosity_from_shortcuts(verbose: int, quiet: int) -> str | None:
    """Map argparse -v/-vv/-q/-qq counts to a verbosity level.

    Anchors to `normal` (NOT to VERBOSITY_DEFAULT), so -v always means
    "show me the streaming feature" and -q always means "back to the
    pre-streaming terse output", independent of what env-var / TOML
    defaults are set to. Matches the cargo / kubectl idiom of treating
    shortcuts as relative-to-baseline rather than relative-to-resolved.

    Returns None when neither shortcut was used (caller falls through
    to resolve_verbosity / env / TOML / default). Returns a value from
    VERBOSITY_VALUES when a shortcut was used. Stacking past -vv / -qq
    saturates at the endpoints rather than wrapping or raising — a
    user typing -vvvv gets debug, not an error."""
    if quiet:
        return "quiet" if quiet > 1 else "normal"
    if verbose:
        return "debug" if verbose > 1 else "stream"
    return None


def _validated_env(name: str, values: tuple[str, ...]) -> str | None:
    """Read env var `name`, die() if set but outside `values`."""
    v = os.environ.get(name, "").strip()
    if not v:
        return None
    if v not in values:
        die(f"{name}={v!r} is not one of {values}")
    return v


def _validated_toml(cfg: Path, key: str, values: tuple[str, ...]) -> str | None:
    """Read toml `key` from `cfg`, die() if set but outside `values`."""
    v = _read_toml_key(cfg, key)
    if v is None:
        return None
    if v not in values:
        die(f"{cfg}: {key}={v!r} is not one of {values}")
    return v


def resolve_models(repo_root: Path, args) -> dict[str, str]:
    """Resolve the model alias for each worker type. Per-worker
    precedence (highest first):
      1. --model-<worker> CLI flag
      2. --model CLI flag (global default for this run)
      3. LEERIE_MODEL_<WORKER> env var
      4. LEERIE_MODEL env var
      5. model_<worker> in leerie.toml
      6. model in leerie.toml
      7. MODEL_DEFAULT_PER_WORKER[<worker>] (e.g., implementer → sonnet)
      8. MODEL_DEFAULT (sonnet)
    `args` is the parsed argparse.Namespace (CLI values are already
    validated by argparse choices=). env and file values are rejected
    via die() when not in MODEL_VALUES."""
    cfg = repo_root / MODEL_FILE

    def from_env(name: str) -> str | None:
        return _validated_env(name, MODEL_VALUES)

    def from_file(key: str) -> str | None:
        return _validated_toml(cfg, key, MODEL_VALUES)

    global_cli = getattr(args, "model", None)
    global_env = from_env(MODEL_ENV)
    global_file = from_file("model")

    models: dict[str, str] = {}
    for worker in WORKER_TYPES:
        # argparse converts --model-foo to args.model_foo
        per_cli = getattr(args, f"model_{worker}", None)
        per_env = from_env(f"{MODEL_ENV}_{worker.upper()}")
        per_file = from_file(f"model_{worker}")
        # Per-worker default kicks in only when no user override applies.
        # Every worker not listed in MODEL_DEFAULT_PER_WORKER falls
        # through to the global MODEL_DEFAULT ("sonnet").
        per_worker_default = MODEL_DEFAULT_PER_WORKER.get(worker, MODEL_DEFAULT)
        models[worker] = (per_cli or global_cli or per_env or global_env
                          or per_file or global_file or per_worker_default)
    # Judge and heal use dedicated flags (--judge-model / --heal-model) and
    # dedicated env vars (LEERIE_MODEL_JUDGE / LEERIE_MODEL_HEAL) rather
    # than the --model-<W> pattern — they're post-run skill workers that don't
    # participate in the --model global-default resolution path. They still
    # fall back to the global override so `--model sonnet` applies everywhere.
    judge_cli = getattr(args, "judge_model", None)
    judge_env = from_env(MODEL_JUDGE_ENV)
    judge_file = from_file("model_judge")
    models["judge"] = (judge_cli or judge_env or global_cli or global_env
                       or judge_file or global_file
                       or MODEL_DEFAULT_PER_WORKER.get("judge", MODEL_DEFAULT))
    heal_cli = getattr(args, "heal_model", None)
    heal_env = from_env(MODEL_HEAL_ENV)
    heal_file = from_file("model_heal")
    models["heal"] = (heal_cli or heal_env or global_cli or global_env
                      or heal_file or global_file
                      or MODEL_DEFAULT_PER_WORKER.get("heal", MODEL_DEFAULT))
    pr_writer_cli = getattr(args, "pr_writer_model", None)
    pr_writer_env = from_env(MODEL_PR_WRITER_ENV)
    pr_writer_file = from_file("model_pr_writer")
    models["pr_writer"] = (pr_writer_cli or pr_writer_env
                           or global_cli or global_env
                           or pr_writer_file or global_file
                           or MODEL_DEFAULT_PER_WORKER.get(
                               "pr_writer", MODEL_DEFAULT))
    # dep_capture is env-var-only (no CLI flag, no leerie.toml key) — it is a
    # post-run worker with no argparse registration. Its sonnet default
    # comes from the global MODEL_DEFAULT fallback (it is intentionally
    # absent from MODEL_DEFAULT_PER_WORKER).
    dep_capture_env = from_env(MODEL_DEP_CAPTURE_ENV)
    models["dep_capture"] = (dep_capture_env
                             or global_cli or global_env or global_file
                             or MODEL_DEFAULT)
    return models


def resolve_efforts(repo_root: Path, args) -> dict[str, str | None]:
    """Resolve the --effort value for each worker type. Mirrors
    resolve_models() rung-for-rung. Per-worker precedence (highest first):
      1. --effort-<worker> CLI flag
      2. --effort CLI flag (global default for this run)
      3. LEERIE_EFFORT_<WORKER> env var
      4. LEERIE_EFFORT env var
      5. effort_<worker> in leerie.toml
      6. effort in leerie.toml
      7. EFFORT_DEFAULT_PER_WORKER[<worker>] (e.g., planner → "medium")
      8. EFFORT_DEFAULT (None — flag omitted from CLI invocation)
    A None value means "do not pass --effort"; claude_p's build() omits
    the flag entirely so the worker inherits Claude's default. CLI values
    are pre-validated by argparse choices=; env and file values are
    rejected via die() when not in EFFORT_VALUES."""
    cfg = repo_root / MODEL_FILE

    def from_env(name: str) -> str | None:
        return _validated_env(name, EFFORT_VALUES)

    def from_file(key: str) -> str | None:
        return _validated_toml(cfg, key, EFFORT_VALUES)

    global_cli = getattr(args, "effort", None)
    global_env = from_env(EFFORT_ENV)
    global_file = from_file("effort")

    efforts: dict[str, str | None] = {}
    for worker in WORKER_TYPES:
        per_cli = getattr(args, f"effort_{worker}", None)
        per_env = from_env(f"{EFFORT_ENV}_{worker.upper()}")
        per_file = from_file(f"effort_{worker}")
        per_worker_default = EFFORT_DEFAULT_PER_WORKER.get(worker, EFFORT_DEFAULT)
        # Explicit-None chain: every rung is either str or None, so we can
        # collapse with `or` — None falls through to the next rung; the
        # final fallback is EFFORT_DEFAULT (None), meaning "omit --effort".
        efforts[worker] = (per_cli or global_cli or per_env or global_env
                           or per_file or global_file or per_worker_default)
    # Post-run skill workers (judge, heal) are not in WORKER_TYPES so they
    # don't get per-worker --effort-<W> flags, but they still honor the
    # global override so `--effort high` applies everywhere.
    efforts["judge"] = (global_cli or global_env or global_file
                        or EFFORT_DEFAULT_PER_WORKER.get("judge", EFFORT_DEFAULT))
    efforts["heal"] = (global_cli or global_env or global_file
                       or EFFORT_DEFAULT_PER_WORKER.get("heal", EFFORT_DEFAULT))
    efforts["pr_writer"] = (global_cli or global_env or global_file
                            or EFFORT_DEFAULT_PER_WORKER.get(
                                "pr_writer", EFFORT_DEFAULT))
    efforts["dep_capture"] = (global_cli or global_env or global_file
                              or EFFORT_DEFAULT_PER_WORKER.get(
                                  "dep_capture", EFFORT_DEFAULT))
    return efforts


def _resolve_operator_str(cli_value: str | None, env_var: str,
                          default: str) -> str:
    """CLI > env > default, with no repository-file tier: for a setting that
    names a location (REPO_CONFIG_LOCATION_KEYS)."""
    if cli_value and cli_value.strip():
        return cli_value.strip()
    return os.environ.get(env_var, "").strip() or default


def resolve_judge_dir(repo_root: Path, cli_value: str | None = None) -> str:
    """Resolve the judge output directory name. Order:
    --judge-dir CLI flag → LEERIE_JUDGE_DIR env var →
    JUDGE_DIR_DEFAULT ("judge-out"). No leerie.toml tier: the value is a
    location (REPO_CONFIG_LOCATION_KEYS). It is a plain directory name (or
    relative path) appended to the run dir — not validated against the
    filesystem at resolve time."""
    return _resolve_operator_str(cli_value, JUDGE_DIR_ENV, JUDGE_DIR_DEFAULT)


def resolve_heal_dir(repo_root: Path, cli_value: str | None = None) -> str:
    """Resolve the heal output directory name. Order:
    --heal-dir CLI flag → LEERIE_HEAL_DIR env var →
    HEAL_DIR_DEFAULT ("heal-out"). No leerie.toml tier, as
    `resolve_judge_dir`."""
    return _resolve_operator_str(cli_value, HEAL_DIR_ENV, HEAL_DIR_DEFAULT)


def resolve_heal_max_rounds(repo_root: Path, cli_value: int | None = None) -> int:
    """Resolve the heal-loop max-iterations cap. Order:
    --heal-max-rounds CLI flag → LEERIE_HEAL_MAX_ROUNDS env var →
    heal_max_rounds in leerie.toml → HEAL_MAX_ROUNDS_DEFAULT (10).
    An invalid (non-positive) value in env or file is rejected via die()."""
    return _resolve_positive_int_pref(
        repo_root, cli_value,
        env_var=HEAL_MAX_ROUNDS_ENV, file_key="heal_max_rounds",
        file_name=HEAL_MAX_ROUNDS_FILE,
        default=HEAL_MAX_ROUNDS_DEFAULT)


def resolve_heal_success_threshold(repo_root: Path,
                                   cli_value: float | None = None) -> float:
    """Resolve the heal-loop success pass-rate threshold. Order:
    --heal-success-threshold CLI flag → LEERIE_HEAL_SUCCESS_THRESHOLD env var →
    heal_success_threshold in leerie.toml → HEAL_SUCCESS_THRESHOLD_DEFAULT (0.9).
    Value must be in (0, 1]; invalid values in env or file are rejected via die()."""
    if cli_value is not None:
        return cli_value
    env = os.environ.get(HEAL_SUCCESS_THRESHOLD_ENV, "").strip()
    if env:
        try:
            v = float(env)
        except ValueError:
            die(f"{HEAL_SUCCESS_THRESHOLD_ENV}={env!r} is not a float")
        if not (0.0 < v <= 1.0):
            die(f"{HEAL_SUCCESS_THRESHOLD_ENV}={env!r} must be in (0, 1]")
        return v
    cfg = repo_root / HEAL_SUCCESS_THRESHOLD_FILE
    file_val = _read_toml_key(cfg, "heal_success_threshold")
    if file_val is not None:
        try:
            v = float(file_val)
        except ValueError:
            die(f"{cfg}: heal_success_threshold={file_val!r} is not a float")
        if not (0.0 < v <= 1.0):
            die(f"{cfg}: heal_success_threshold={file_val!r} must be in (0, 1]")
        return v
    return HEAL_SUCCESS_THRESHOLD_DEFAULT


async def run_proc(cmd: list[str], *, cwd: str | None = None,
                   timeout: float | None = None,
                   env: dict[str, str] | None = None,
                   pass_fds: tuple[int, ...] = (),
                   ) -> subprocess.CompletedProcess:
    """Async equivalent of `subprocess.run(cmd, capture_output=True, text=True)`.
    On timeout, kills the process and raises `subprocess.TimeoutExpired` — same
    semantics callers already handle. One helper everywhere keeps the asyncio
    boilerplate out of the call sites.

    `start_new_session=True` isolates the child into its own POSIX
    session/process group, distinct from leerie's own. This is what lets
    `_terminate_proc_tree` send `os.killpg(proc.pid, ...)` on the
    cleanup path without accidentally signaling the orchestrator's own
    group. The flag is a no-op on Windows.

    `env` defaults to None, which inherits the orchestrator's environment
    (asyncio's own default) — so every existing call site is unchanged.
    Callers pass it to scope a variable to one command, e.g.
    `_rescue_integrator_work`'s throwaway `GIT_INDEX_FILE`. `pass_fds`: a
    confined command's refusal descriptor (`_shim_refusals`)."""
    proc = await asyncio.create_subprocess_exec(
        *cmd,
        cwd=cwd,
        env=env,
        pass_fds=pass_fds,
        # Never the orchestrator's fd 0, the operator's terminal in an
        # interactive run (DESIGN §6 *No confined process holds a
        # descriptor of the operator's terminal*).
        stdin=asyncio.subprocess.DEVNULL,
        stdout=asyncio.subprocess.PIPE,
        stderr=asyncio.subprocess.PIPE,
        start_new_session=True,
    )
    try:
        if timeout is None:
            stdout, stderr = await proc.communicate()
        else:
            stdout, stderr = await asyncio.wait_for(
                proc.communicate(), timeout=timeout)
    except asyncio.TimeoutError:
        await _terminate_proc_tree(proc)
        raise subprocess.TimeoutExpired(cmd, timeout)
    except BaseException:
        # Any other exception (CancelledError from a parent abort, an unexpected
        # OSError/BrokenPipeError from the PIPE, etc.) must still leave no
        # orphan subtree. Terminate the process group then re-raise.
        await _terminate_proc_tree(proc)
        raise
    # Success path needs no descendant sweep: `run_proc` is used for short
    # synchronous commands (git, smoke tests, cleanup helpers) that do not
    # background tool calls the way `claude -p` workers do via Claude Code's
    # Bash tool. The detached-session leak class addressed by
    # `_DescendantTracker` is specific to `_invoke`, not here.
    return subprocess.CompletedProcess(
        cmd,
        proc.returncode if proc.returncode is not None else 0,
        stdout.decode(errors="replace") if stdout else "",
        stderr.decode(errors="replace") if stderr else "",
    )


# --- the execution lock (DESIGN §6 *A held-out evaluation runs alone, in a
# world that dies with it (I3)*, the time half) ----------------------------
# Set in the context of a held-out evaluation that holds the lock exclusive:
# its own commands pass through; a worker spawned there stops the run.
_EXEC_EXCLUSIVE: contextvars.ContextVar[bool] = contextvars.ContextVar(
    "_EXEC_EXCLUSIVE", default=False)
# Set in the context of a shared holder: a command it runs inside (`mise ls`
# around a sync read, an AST script under its caller's hold) is the same
# holder, never a second reader that would wait behind a waiting evaluation
# while the first one holds the lock.
_EXEC_SHARED: contextvars.ContextVar[bool] = contextvars.ContextVar(
    "_EXEC_SHARED", default=False)


class _ExecLock:
    """The run's execution lock, on one event loop: every worker
    (`_invoke`, from its spawn until its process has exited) and every
    confined command (`_run_streaming`, `_ts_script_run`'s callers, the
    `mise ls` spawn) holds it shared; a held-out evaluation exclusive
    (`_held_out_section`), so while one runs no worker process and no other
    command on the repository's code exists. A waiting exclusive holder stops
    new shared ones, so a stream of measurements cannot starve it. Nothing
    that holds it shared waits on an evaluation — it is taken after every
    semaphore and before a host build slot, and a shared holder's commands
    pass through — so it cannot deadlock; a worker spawned inside an evaluation stops the run instead of
    waiting. It is the run's alone: no level spans runs (DESIGN §6 *There is
    no host level*). An evaluation that must wait logs both ends of its
    wait, so a stall is never silent."""

    def __init__(self) -> None:
        self.readers = 0
        self.workers = 0
        self.writer = False
        self.writers_waiting = 0
        self._waiters: list[asyncio.Future] = []

    def _wake(self) -> None:
        waiters, self._waiters = self._waiters, []
        for f in waiters:
            if not f.done():
                f.set_result(None)

    async def _wait(self) -> None:
        f = asyncio.get_running_loop().create_future()
        self._waiters.append(f)
        try:
            await f
        finally:
            with contextlib.suppress(ValueError):
                self._waiters.remove(f)

    @contextlib.asynccontextmanager
    async def shared(self, *, worker: bool = False) -> AsyncIterator[None]:
        """Hold the lock shared; `worker` for a worker's process, which may
        never run inside an evaluation."""
        if _EXEC_EXCLUSIVE.get():
            if worker:
                die("invariant: a worker spawned inside a held-out "
                    "evaluation — no worker may exist while one runs "
                    "(DESIGN §6 *A held-out evaluation runs alone, in a "
                    "world that dies with it (I3)*). Report this.")
            yield
            return
        if _EXEC_SHARED.get():
            yield
            return
        while self.writer or self.writers_waiting:
            await self._wait()
        self.readers += 1
        self.workers += worker
        token = _EXEC_SHARED.set(True)
        try:
            yield
        finally:
            _EXEC_SHARED.reset(token)
            self.readers -= 1
            self.workers -= worker
            if not self.readers:
                self._wake()

    @contextlib.asynccontextmanager
    async def exclusive(self) -> AsyncIterator[bool]:
        """Yields True to the outermost holder, False to a nested one."""
        if _EXEC_EXCLUSIVE.get():
            yield False
            return
        if _EXEC_SHARED.get():
            die("invariant: a held-out evaluation started while its own "
                "caller holds the execution lock shared — it would wait on "
                "itself (DESIGN §6 *A held-out evaluation runs alone*). "
                "Report this.")
        self.writers_waiting += 1
        t0 = time.monotonic() if (self.writer or self.readers) else None
        if t0 is not None:
            behind = ", behind another evaluation" if self.writer else ""
            log(f"  execution lock: held-out evaluation waits for "
                f"{self.readers} shared holder(s) of this run "
                f"({self.workers} worker(s)){behind}")
        try:
            while self.writer or self.readers:
                await self._wait()
        finally:
            self.writers_waiting -= 1
            self._wake()
        if t0 is not None:
            log(f"  execution lock: held-out evaluation waited "
                f"{time.monotonic() - t0:.0f}s")
        self.writer = True
        token = _EXEC_EXCLUSIVE.set(True)
        try:
            yield True
        finally:
            _EXEC_EXCLUSIVE.reset(token)
            self.writer = False
            self._wake()


# One per event loop, as `_BLT_SEMS` (a loop's futures cannot serve another).
_EXEC_LOCKS: ("weakref.WeakKeyDictionary[asyncio.AbstractEventLoop, "
              "_ExecLock]") = weakref.WeakKeyDictionary()


def _exec_lock() -> _ExecLock:
    """The execution lock of the running loop (one run per orchestrator
    process). Call from a coroutine."""
    loop = asyncio.get_running_loop()
    lock = _EXEC_LOCKS.get(loop)
    if lock is None:
        lock = _EXEC_LOCKS[loop] = _ExecLock()
    return lock


def _exec_lock_held() -> bool:
    """Whether the calling context holds the execution lock, shared or
    exclusive: what a synchronous confined spawn (`_ts_script_run`) checks,
    since it cannot wait for the lock itself."""
    return _EXEC_SHARED.get() or _EXEC_EXCLUSIVE.get()


@contextlib.asynccontextmanager
async def _held_out_section(st: object) -> AsyncIterator[None]:
    """Hold the execution lock exclusive around a held-out file's sandboxed
    run (DESIGN §6 *A held-out evaluation runs alone, in a world that dies
    with it (I3)*): no worker process and no other command on the
    repository's code exists meanwhile in the run, so nothing of the run
    observes what a namespace cannot hide — its `/proc` entries,
    its cgroup's counters, its contention. Its own commands pass through;
    nested sections are one. Then a host build slot, as every command takes
    one after the lock (DESIGN §6 *Inside an evaluation every concurrency
    gate is already the holder's*): the evaluation is one of the host's
    builds, and it holds no slot while it waits for its run's workers. What
    it leaves is the sandbox's, gone with it: nothing is inventoried or
    removed here."""
    async with _exec_lock().exclusive() as outermost, \
            _host_build_slot(st, label="held-out evaluation",
                             take=outermost):
        yield


async def _run_streaming(
    cmd: list[str],
    *,
    grants: WorkerGrants,
    cwd: str | None = None,
    env: dict[str, str] | None = None,
    timeout: float | None = None,
    log_path: Path | None = None,
    label: str | None = None,
    verbosity: str = "stream",
    line_prefix: str = "  | ",
    tail_lines: int = 40,
    cgroup_sid: str | None = None,
    sandbox: "HeldOutSandbox | None" = None,
    report_into: bytearray | None = None,
) -> tuple[int, str]:
    """Run a subprocess with stdout+stderr streamed live, persisted to a
    log file, and tailed for error reporting. Use this instead of
    `run_proc` for *long-running* commands where:

      - the user should see progress in real time (no silent multi-minute
        hangs while a buffered pipe fills),
      - the full output should land on disk regardless of verbosity, and
      - the last N lines should be available in any exception we raise.

    Returns `(returncode, tail)`. On timeout raises
    `subprocess.TimeoutExpired` (same shape `run_proc` raises) with
    `output` populated with the captured tail so callers can include it
    in their error message. On any other exception, terminates the
    process tree via `_terminate_proc_tree` (same exception-safety
    contract as `run_proc`).

    `verbosity`:
      - "quiet": no stdout echo; log file still gets every line.
      - anything else ("normal", "stream", "debug"): echo each line
        through `log()` with `line_prefix`.

    `label` is appended to the persistent log's section header — useful
    when multiple commands write to the same log file (provision.log
    accumulates `mise install`, `.leerie-setup.sh`, etc.).

    The DRY counterpart to `run_proc`: identical contract for the
    process-group/exception-safety story, different I/O shape. Pick
    `run_proc` for short captures (git plumbing, smoke tests) where
    the synchronous-collect shape is what the caller wants; pick
    `_run_streaming` for anything that might run long enough that a
    silent terminal would mislead the user.

    `cgroup_sid`: a broker cgroup the caller already created. The command
    starts held behind the spawn gate until its pid is enrolled there, so
    every process it forks is inside (DESIGN §6 *Enrollment holds the
    spawn*). The caller owns the cgroup's lifetime (`_run_contained`).
    Every command run here is the repository's, so it runs in
    `_repo_command_env` — without leerie's hooks-off git entry.

    `grants` (required, keyword-only: no call can forget it) is the
    command's measurement grant (`_measurement_grants`, DESIGN §6 *Leerie's
    runs of the repository's commands are confined too*): `cmd` is started
    through the Landlock shim with it (no grant names `/tmp`; an isolated
    command's own is the shim's), every descendant inheriting the restriction, and the grant's own variables
    are laid over `env` last. There is no unconfined path.

    `sandbox` (every run of a held-out file, DESIGN §6 *A held-out
    evaluation runs alone, in a world that dies with it (I3)*): the command
    runs in a sandbox the shim builds over `sandbox.view`, its `place`
    files copied into the overlay, never onto disk. The runner's report
    (`sandbox.report`, a path inside the sandbox) comes back through an
    unlinked file leerie opened and passed as a descriptor, and its bytes
    are appended to `report_into` once the command has exited: the report
    leerie parses is one no other process wrote, and it is never put on
    disk, where the path it named lies in a directory confined code writes
    (DESIGN §6 *Leerie never writes through a path confined code shaped*).
    """
    # A command's output never lands in a worker's transcript, where a line
    # the code under measurement prints in the shape of a tool call would be
    # read as one the worker made (DESIGN §8 *What a worker ran is read from
    # its own transcript*).
    if log_path is not None and (_in_transcripts_dir(log_path)
                                 or _is_worker_transcript(log_path)):
        die(f"leerie was about to write a command's output into {log_path}, "
            "a worker's transcript — leerie's own invariant is broken "
            "(DESIGN §8 *What a worker ran is read from its own "
            "transcript*). Report this.")
    # Every confined command holds the execution lock shared, so none runs
    # while a held-out evaluation does (`_held_out_section`), whose own
    # commands pass through. The shim ends every process the command leaves
    # before this returns (DESIGN §6 *A confined command's processes end
    # with it*).
    outside = _argv_outside_grant(list(cmd), grants)
    if outside is not None:
        die(f"leerie was about to hand {outside} to a confined command whose "
            "grant does not reach it — leerie's own invariant is broken "
            "(DESIGN §6 *Leerie's runs of the repository's commands are "
            "confined too*). Report this.")
    if (sandbox is not None and sandbox.report is not None
            and report_into is None):
        die("leerie was about to run a held-out file whose report has "
            "nowhere to go but disk — leerie's own invariant is broken "
            "(DESIGN §6 *Leerie never writes through a path confined code "
            "shaped*). Report this.")
    # The report comes back through an unlinked file in the run's own temp
    # directory, never through the sandbox's paths.
    report_fh = (tempfile.TemporaryFile()
                 if sandbox is not None and sandbox.report is not None
                 else None)
    report_fd = report_fh.fileno() if report_fh is not None else None
    # Checked in the `finally`, before the caller sees an exit status (DESIGN
    # §6 *A confinement failure stops the run; it is never a result*). A
    # held-out file the tree leaves no room for comes back on a descriptor
    # of its own: a fact about the tree, never a refusal.
    refusals = _ShimRefusals(label or " ".join(cmd))
    taken = (_ShimTaken(label or " ".join(cmd))
             if sandbox is not None and (sandbox.place or sandbox.replace
                                         or sandbox.remove) else None)
    try:
        async with _exec_lock().shared():
            spawn_cmd = _confined_argv(grants, list(cmd), sandbox=sandbox,
                                       report_fd=report_fd,
                                       refusal_fd=refusals.fd,
                                       taken_fd=(taken.fd if taken is not None
                                                 else None))
            # A command in a run's tree reads that tree's own stores
            # (`_TREE_STORE_VARS`; DESIGN §6 *Which stores an install may
            # share*).
            env = _tree_stores_for(env if env is not None else os.environ, cwd)
            # And the console scripts of whichever user base it has, on its
            # own `PATH`, last — never on the orchestrator's (DESIGN §6
            # *Which stores an install may share*).
            _with_user_scripts(env, None)
            gate_r: int | None = None
            gate_w: int | None = None
            if cgroup_sid is not None:
                spawn_cmd, gate_r, gate_w = _spawn_held_argv(spawn_cmd)
            try:
                proc = await asyncio.create_subprocess_exec(
                    *spawn_cmd,
                    pass_fds=tuple(fd for fd in (gate_r, report_fd,
                                                 refusals.fd,
                                                 taken.fd if taken is not None
                                                 else None)
                                   if fd is not None),
                    cwd=cwd,
                    env={**_repo_command_env(env), **dict(grants.env)},
                    # DESIGN §6 *No confined process holds or can open
                    # the operator's terminal*.
                    stdin=asyncio.subprocess.DEVNULL,
                    stdout=asyncio.subprocess.PIPE,
                    stderr=asyncio.subprocess.STDOUT,
                    start_new_session=True,
                )
            except BaseException:
                _close_fd(gate_r)
                _close_fd(gate_w)
                raise
            _close_fd(gate_r)
            if cgroup_sid is not None:
                try:
                    await asyncio.to_thread(_cgroup_enroll, cgroup_sid, proc.pid)
                except BaseException:
                    _release_spawn_gate(gate_w, run=False)
                    await _terminate_proc_tree(proc)
                    raise
                _release_spawn_gate(gate_w)

            tail: deque[str] = deque(maxlen=tail_lines)
            log_fh = None
            if log_path is not None:
                try:
                    log_path.parent.mkdir(parents=True, exist_ok=True)
                    log_fh = log_path.open("a", buffering=1)  # line-buffered
                    header = f"=== {label or ' '.join(cmd)} (cwd={cwd or '.'}) ==="
                    log_fh.write(header + "\n")
                except OSError:
                    log_fh = None

            echo = verbosity != "quiet"

            async def read_loop() -> None:
                # proc.stdout is guaranteed non-None because we passed
                # stdout=asyncio.subprocess.PIPE above; no runtime check needed.
                async for raw in proc.stdout:
                    line = raw.decode(errors="replace").rstrip("\r\n")
                    tail.append(line)
                    if log_fh is not None:
                        try:
                            log_fh.write(line + "\n")
                        except OSError:
                            pass
                    if echo:
                        log(f"{line_prefix}{line}")

            try:
                if timeout is None:
                    await asyncio.gather(read_loop(), proc.wait())
                else:
                    await asyncio.wait_for(
                        asyncio.gather(read_loop(), proc.wait()),
                        timeout=timeout,
                    )
            except asyncio.TimeoutError:
                if log_fh is not None:
                    try:
                        log_fh.write(f"=== TIMEOUT after {timeout}s ===\n")
                    except OSError:
                        pass
                await _terminate_proc_tree(proc)
                captured = "\n".join(tail)
                exc = subprocess.TimeoutExpired(cmd, timeout)
                # Standard TimeoutExpired exposes `output` and `stderr`; populate
                # `output` with the merged tail so callers can include it in
                # their die() message without re-reading the log file.
                exc.output = captured
                if log_fh is not None:
                    try:
                        log_fh.close()
                    except OSError:
                        pass
                raise exc
            except BaseException:
                await _terminate_proc_tree(proc)
                if log_fh is not None:
                    try:
                        log_fh.close()
                    except OSError:
                        pass
                raise

            if log_fh is not None:
                try:
                    log_fh.close()
                except OSError:
                    pass

            rc = proc.returncode if proc.returncode is not None else 0
            if report_fh is not None and report_into is not None:
                report_fh.seek(0)
                report_into += report_fh.read()
            return rc, "\n".join(tail)
    finally:
        if report_fh is not None:
            report_fh.close()
        try:
            refusals.check()
        except ConfinementRefused:
            if taken is not None:
                taken.close()
            raise
        if taken is not None:
            taken.check()


async def _gather_or_cancel(*aws):
    """Like asyncio.gather, but on the first exception cancel every other
    in-flight task and await its finalization before re-raising. Paired with
    run_proc's child-killing exception handler, this terminates in-flight
    `claude -p` subprocesses immediately on a failed-run abort instead of
    letting them burn the worker budget for up to worker_timeout_sec."""
    tasks = [asyncio.ensure_future(a) for a in aws]
    try:
        return await asyncio.gather(*tasks)
    except BaseException:
        for t in tasks:
            if not t.done():
                t.cancel()
        try:
            await asyncio.gather(*tasks, return_exceptions=True)
        except BaseException:
            # If the cleanup itself is cancelled or errors, drop that
            # secondary exception so the bare `raise` below re-raises the
            # original — the user wants the real failure cause, not noise
            # from the cleanup phase.
            pass
        raise


# Backstop for `_run_script` invocations of the bundled worktree scripts
# (cleanup.sh, finalize.sh, etc). Unbounded (`timeout=None`) previously —
# if the script itself ever hit an unbounded git/filesystem stall, the
# orchestrator would block forever. Calibrated well above the 240s
# worktree-removal ceiling used elsewhere in this file, since a script
# invocation may itself remove many worktrees sequentially.
RUN_SCRIPT_TIMEOUT = 600


async def _run_script(name: str, *args: str,
                      st: "State") -> subprocess.CompletedProcess:
    """Run one of the bundled git worktree scripts in the run's own
    repository (DESIGN §6 *The run's own repository*): every script acts on
    the repository at its working directory. The state root is passed
    absolute, since a relative `.leerie` would resolve inside that
    repository."""
    env = {**os.environ,
           "LEERIE_STATE_DIR": str(Path(st.run_dir).resolve().parent.parent),
           # Named, never discovered (safe.bareRepository=explicit): the
           # scripts' repository-level git goes through `leerie_repo_git`.
           "LEERIE_GIT_DIR": str(_run_repo(st))}
    return await run_proc(["bash", str(SCRIPTS / name), *args],
                          cwd=str(_run_repo(st)), env=env,
                          timeout=RUN_SCRIPT_TIMEOUT)


# The run's own repository (DESIGN §6 *The run's own repository*, RC4/I4):
# `<run-dir>/repo`, a bare, self-contained repository every tree a worker
# gets hangs off, so no worker's git verb reaches the user's refs, stash,
# config, `info/exclude`, hooks or worktree registry.
RUN_REPO_NAME = "repo"

# Repository-local config keys that describe where and what kind of
# repository a config file belongs to, not how git behaves in it: copied,
# they would make the run's bare repository read as the user's (measured:
# the user's `core.bare = false` made `worktree add` of the run branch
# refuse). Every other repository-local key is carried.
_RUN_REPO_UNCARRIED_KEYS = frozenset({
    "core.bare", "core.worktree", "core.repositoryformatversion"})
_RUN_REPO_UNCARRIED_PREFIXES = ("extensions.", "include.", "includeif.")


def _run_repo(st: "State") -> Path:
    """`<run-dir>/repo`: the one spelling of the run's own repository's
    path (also `State.run_repo`)."""
    return Path(st.run_dir) / RUN_REPO_NAME


class RunRepoError(RuntimeError):
    """The run's own repository could not be created or refreshed."""


def _git_sync(args: list[str], *, env: Mapping[str, str] | None = None,
             timeout: float = 300) -> subprocess.CompletedProcess:
    """One synchronous git call, output captured, never raising on a
    non-zero exit."""
    return subprocess.run(["git", *args], capture_output=True, text=True,
                          check=False, timeout=timeout,
                          env=None if env is None else dict(env))


def _git_at(path: str | Path) -> list[str]:
    """How leerie's own git names a repository it addresses: a git
    directory (the run's own bare repository) with `--git-dir`, a work
    tree with `-C`. git's `safe.bareRepository=explicit` refuses to find a
    bare repository from a working directory, so leerie never relies on
    discovery for one (DESIGN §6 *The run's own repository*, review round
    17 M3). Mechanical: a directory holding `HEAD` and `objects/` is a git
    directory."""
    p = Path(path)
    if (p / "HEAD").is_file() and (p / "objects").is_dir():
        return ["--git-dir", str(p)]
    return _tree_git_args(p)


def _is_git_dir(p: Path) -> bool:
    return (p / "HEAD").is_file() and (p / "objects").is_dir()


def _admin_dir_of(common: Path, tree: Path) -> Path | None:
    """`common`'s administrative directory for its worktree `tree`, found
    from the repository's side (each `worktrees/*/gitdir`), never from
    `tree/.git`. A tree repository is its committing worker's to write
    whole, so each record is read beneath `common` and never through a link
    or a FIFO (`_read_beneath`)."""
    want = os.path.realpath(tree)
    common = Path(common)
    try:
        dirs = [common / "worktrees" / n for n in sorted(
            _listdir_beneath(common, common / "worktrees"))]
    except OSError:
        return None
    for d in dirs:
        try:
            got = _read_text_beneath(common, d / "gitdir",
                                     errors="strict", limit=READ_LIMIT_CONFIG).strip()
        except (OSError, ValueError):
            continue
        if os.path.realpath(os.path.dirname(got)) == want:
            return d
    return None


def _run_tree_location(tree: str | Path
                       ) -> tuple[Path, Path, Path] | None | bool:
    """Where a tree in a run's `worktrees/` keeps its repository (DESIGN §6
    *Leerie's git never takes a tree's repository from the tree*), from
    leerie's own layout and never from the tree, whose `.git` file confined
    code may rewrite: `(common dir, git dir, run dir)`. A worktree of its
    tree repository (`<run>/tree-repos/<name>`) or else of the run
    repository, its git dir the administrative directory that names it, and
    whose `commondir` names that repository; a ref-less clone, the git
    directory leerie made for it (`_clone_git_dir`), never the `.git` inside
    it. None for a tree outside every run (the user's
    checkout, a test's repository); False for one inside a run that matches
    none of these (no git command may then read it)."""
    t = Path(os.path.realpath(tree))
    if t.parent.name != "worktrees":
        return None
    run_dir = t.parent.parent
    tr = run_dir / TREE_REPOS_NAME / t.name
    if _is_git_dir(tr):
        common = tr
    elif _is_git_dir(run_dir / RUN_REPO_NAME):
        common = run_dir / RUN_REPO_NAME
    else:
        return None
    # A worktree whatever its `.git` now is: the repository's own record
    # names it, so a `.git` directory put in its place makes it no clone.
    admin = _admin_dir_of(common, t)
    if admin is None:
        # A ref-less clone: its leerie-owned git directory, never the `.git`
        # inside it, which its confined worker writes.
        shadow = run_dir / CLONE_GITS_NAME / t.name
        if common == run_dir / RUN_REPO_NAME and _is_git_dir(shadow):
            return shadow, shadow, run_dir
        return False
    try:
        named = _read_text_beneath(common, admin / "commondir",
                                   errors="strict", limit=READ_LIMIT_CONFIG).strip()
    except (OSError, ValueError):
        return False
    if os.path.realpath(admin / named) != os.path.realpath(common):
        return False
    return common, admin, run_dir


def _tree_git_args(tree: str | Path) -> list[str]:
    """THE arguments after `git` of every leerie git command on a tree
    (DESIGN §6 *Leerie's git never takes a tree's repository from the
    tree*): `-C <tree>` for its paths, and for a tree in a run's
    `worktrees/` its repository named explicitly (`--git-dir <git dir>
    --work-tree <tree>`, `_run_tree_location`), so a `.git` file confined
    code rewrote is never followed; leerie's pins (`_GIT_VIEW_PINS`)
    always. A run tree that cannot be located gets a git directory that
    does not exist: git then fails, and the caller reads that as git
    unable to answer."""
    t = str(tree)
    loc = _run_tree_location(tree)
    if loc is None:
        return ["-C", t, *_GIT_VIEW_PINS]
    if loc is False:
        gd = Path(os.path.realpath(tree)).parent.parent / ".no-git-dir"
    else:
        gd = loc[1]
    return ["-C", t, "--git-dir", str(gd), "--work-tree", t,
            *_GIT_VIEW_PINS]


def _run_repo_of(run_dir: Path) -> Path | None:
    """`<run_dir>/repo` when it is a repository, else None (a run made
    before per-run repositories, or one not yet started). Read by naming
    the repository explicitly, never through a setting a worker can change
    (`core.bare`, review round 17 H1)."""
    repo = Path(run_dir) / RUN_REPO_NAME
    if not (repo / "HEAD").is_file():
        return None
    r = _git_sync(["--git-dir", str(repo), "rev-parse", "--git-dir"],
                  timeout=30)
    return repo if r.returncode == 0 else None


TREE_REPOS_NAME = "tree-repos"
# A ref-less clone's leerie-owned git directory (DESIGN §6 *Leerie's git never
# takes a tree's repository from the tree*): `<run>/clone-gits/<tree name>`.
# The clone keeps its own `.git` inside the tree, where its confined worker
# writes — config, hooks, attributes and all — so leerie never reads it: its
# reads go through this one, which borrows the run repository's objects, holds
# an index of the commit the clone was made at, and was written by leerie
# alone, in a directory no worker's grant names.
CLONE_GITS_NAME = "clone-gits"


def _clone_git_dir(tree: str | Path) -> Path:
    """Where `_ref_less_clone` keeps `tree`'s leerie-owned git directory."""
    t = Path(os.path.realpath(tree))
    return t.parent.parent / CLONE_GITS_NAME / t.name


def _common_dir_of(tree: str | Path) -> Path | None:
    """The git common directory of `tree`, absolute; None when `tree` is no
    git tree (a payload-only directory, a path that does not exist). A run
    tree's from leerie's layout (`_run_tree_location`)."""
    loc = _run_tree_location(tree)
    if loc is False:
        return None
    if loc is not None:
        return loc[0]
    try:
        r = subprocess.run(["git", *_tree_git_args(tree), "rev-parse",
                            "--path-format=absolute", "--git-common-dir"],
                           capture_output=True, text=True, check=False,
                           timeout=30)
    except (OSError, subprocess.SubprocessError):
        return None
    out = r.stdout.strip()
    return Path(out) if r.returncode == 0 and out else None


def _tree_repo_of(tree: str | Path) -> Path | None:
    """`tree`'s own repository, `<run-dir>/tree-repos/<name>` (DESIGN §6 *A
    repository per committing tree (I6)*), when `tree` is a worktree of one
    and the run has its repository; else None — a tree of the run
    repository itself, or of no run."""
    common = _common_dir_of(tree)
    if common is None or common.parent.name != TREE_REPOS_NAME:
        return None
    if _run_repo_of(common.parent.parent) is None:
        return None
    return common


def _run_repo_for_tree(tree: str | Path) -> Path | None:
    """The run repository a tree belongs to: the one its tree repository
    borrows from, or its own common directory when that is a run
    repository; None otherwise."""
    common = _common_dir_of(tree)
    if common is None:
        return None
    if common.parent.name == TREE_REPOS_NAME:
        return _run_repo_of(common.parent.parent)
    if common.name == RUN_REPO_NAME:
        return _run_repo_of(common.parent)
    return None


def _tree_branch_of(tree_repo: Path) -> str:
    """The branch leerie takes from a tree repository, by its name alone —
    never the tree's HEAD, which a worker sets: `staging` holds the run
    branch, `<run-id[:12]>-<sid>` the subtask branch. The shell half is
    `leerie_tree_branch_of`."""
    run_id = Path(tree_repo).parent.parent.name
    name = Path(tree_repo).name
    if name == "staging":
        return _compute_run_branch(run_id)
    return _compute_subtask_branch(
        run_id, name[len(_worktree_dirname(run_id, "")):])


def _take_tree_branch(tree: str | Path) -> str | None:
    """Take `tree`'s branch from its tree repository into the run repository
    (DESIGN §6 *A repository per committing tree (I6)*): its new objects
    are copied and exactly that branch moves; no other ref of the tree
    repository is read. Returns the run repository's commit of the branch;
    None for a tree of no tree repository. Raises RunRepoError when the
    fetch fails."""
    tr = _tree_repo_of(tree)
    if tr is None:
        return None
    return _take_tree_repo(tr)


def _take_tree_repo(tr: Path) -> str | None:
    """`_take_tree_branch` by the tree repository's path (its tree may be
    gone)."""
    branch = _tree_branch_of(tr)
    run_repo = tr.parent.parent / RUN_REPO_NAME
    f = _git_sync(["--git-dir", str(run_repo), "fetch", "--quiet",
                   "--no-tags", "--no-write-fetch-head",
                   "--no-auto-maintenance", str(tr),
                   f"+refs/heads/{branch}:refs/heads/{branch}"], timeout=300)
    if f.returncode != 0:
        raise RunRepoError(f"take {branch} from {tr}: "
                           f"{f.stderr.strip()[:300]}")
    r = _git_sync(["--git-dir", str(run_repo), "rev-parse", "--verify",
                   "-q", f"refs/heads/{branch}^{{commit}}"], timeout=30)
    return r.stdout.strip() or None


def _branch_commit_for_tree(tree: str | Path, name: str) -> str:
    """`name`, a branch leerie reads a tree against (the run branch), as the
    run repository's commit when `tree` is a tree of a tree repository —
    leerie never reads a name there, where the worker owns every ref (DESIGN
    §6 *A repository per committing tree (I6)*) — else `name` unchanged. The
    tree reaches the commit's objects through its alternates."""
    tr = _tree_repo_of(tree)
    if tr is None:
        return name
    r = _git_sync(["--git-dir", str(tr.parent.parent / RUN_REPO_NAME),
                   "rev-parse", "--verify", "-q",
                   f"refs/heads/{name}^{{commit}}"], timeout=30)
    return r.stdout.strip() if r.returncode == 0 and r.stdout.strip() \
        else name


async def _branch_commit_for_tree_async(tree: str | Path, name: str) -> str:
    return await asyncio.to_thread(_branch_commit_for_tree, tree, name)


def _drop_tree_repo(run_dir: Path, name: str, *, take: bool) -> bool:
    """Remove the tree repository of the tree `<run_dir>/worktrees/<name>`
    (its tree is removed by the caller), after taking its branch when
    `take` — a subtask tree pruned after integration keeps its work; one
    reset for a retry does not (its branch is deleted). False, with
    everything kept, when the take fails."""
    tr = Path(run_dir) / TREE_REPOS_NAME / name
    if not (tr / "HEAD").is_file():
        return True
    if take:
        try:
            _take_tree_repo(tr)
        except (RunRepoError, OSError, subprocess.TimeoutExpired) as e:
            log(f"  could not take {tr} before removing it ({e}); kept")
            return False
    _rmtree_owned(tr)
    return True


async def _take_tree_branch_async(tree: str | Path) -> str | None:
    return await asyncio.to_thread(_take_tree_branch, tree)


async def _take_after_worker(cwd: str | Path) -> None:
    """A worker that ran in a committing tree has its branch taken as soon
    as it exits, before anything reads what it did; a take that fails stops
    the run (the run repository would not hold the worker's work). Before
    the take, leerie's settings go back over its tree's repository (DESIGN
    §8 *The settings are leerie's*): a worker's `git config` — husky's
    install sets `core.hooksPath` — is its environment, put back and never
    counted against it. Settings that still differ stop the run: leerie
    could not then read the tree through its own."""
    try:
        done = await asyncio.to_thread(_restore_settings, cwd)
    except OSError as e:
        done = []
        log(f"  could not put leerie's git settings back in {cwd}: {e}")
    if done:
        log(f"  put leerie's git settings back in {cwd} "
            f"({', '.join(done)}): the worker changed its tree's repository")
    left = await asyncio.to_thread(_settings_dirt, cwd)
    if left:
        die(f"leerie cannot read {cwd} through its own git settings: "
            f"{'; '.join(left)} (DESIGN §8 *The settings are leerie's*)")
    try:
        await _take_tree_branch_async(cwd)
    except (RunRepoError, OSError, subprocess.TimeoutExpired) as e:
        die(f"could not take the worker's branch from {cwd} into the run's "
            f"repository: {e} (DESIGN §6 *A repository per committing tree "
            "(I6)*)")


def _bring_commit(tree: str | Path, sha: str) -> None:
    """A commit leerie made in a tree repository on no branch (a synthetic
    merge, a rescue) into the run repository, kept under
    `refs/leerie/kept/<sha>`. A no-op when the run repository has it (a tree
    of the run repository itself). Raises RunRepoError when the fetch
    fails."""
    run_repo = _run_repo_for_tree(tree)
    if run_repo is None:
        return
    at = ["--git-dir", str(run_repo)]
    if _git_sync([*at, "cat-file", "-e", f"{sha}^{{commit}}"],
                 timeout=30).returncode == 0:
        return
    tr = _tree_repo_of(tree)
    if tr is None:
        raise RunRepoError(f"{sha} is in no repository leerie can take from")
    f = _git_sync([*at, "fetch", "--quiet", "--no-tags",
                   "--no-write-fetch-head", "--no-auto-maintenance",
                   "--upload-pack",
                   "git -c uploadpack.allowAnySHA1InWant=true upload-pack",
                   str(tr), f"+{sha}:refs/leerie/kept/{sha}"], timeout=300)
    if f.returncode != 0:
        raise RunRepoError(f"bring {sha} from {tr}: "
                           f"{f.stderr.strip()[:300]}")


def _carry_repo_config(user: Path, repo: Path) -> None:
    """Copy the user's repository-local config into the run's repository
    (`repo/config`), key by key, except the keys that describe the
    repository itself and any key `git init` already wrote. Then, when the
    user sets no hooks path anywhere, point `core.hooksPath` at the user's
    hooks directory, so a worker's own commit runs the repository's hooks as
    it does in the user's checkout (DESIGN §6 *Finalization*). Read with
    leerie's hooks-off entry removed: it would otherwise be what `git
    config core.hooksPath` answers. Mechanical: key names only."""
    cfg = str(Path(repo) / "config")
    env = _git_hooks_on(os.environ)
    own = _git_sync(["config", "-f", cfg, "--list", "--name-only"])
    already = {k.strip().lower() for k in own.stdout.splitlines() if k.strip()}
    r = _git_sync([*_tree_git_args(user), "config", "--local", "--list", "-z"],
                 env=env, timeout=30)
    if r.returncode != 0:
        raise RunRepoError(f"git config --local --list in {user}: "
                           f"{r.stderr.strip()[:300]}")
    for entry in r.stdout.split("\0"):
        if not entry:
            continue
        key, sep, value = entry.partition("\n")
        low = key.lower()
        if (low in _RUN_REPO_UNCARRIED_KEYS or low in already
                or low.startswith(_RUN_REPO_UNCARRIED_PREFIXES)):
            continue
        # A key with no `=` is boolean true in git's config syntax.
        w = _git_sync(["config", "-f", cfg, "--add", key,
                      value if sep else "true"])
        if w.returncode != 0:
            raise RunRepoError(f"git config --add {key}: "
                               f"{w.stderr.strip()[:300]}")
    hp = _git_sync([*_tree_git_args(user), "config", "core.hooksPath"], env=env,
                  timeout=30)
    if hp.returncode != 0 or not hp.stdout.strip():
        hooks = _git_sync([*_tree_git_args(user), "rev-parse",
                          "--path-format=absolute", "--git-path", "hooks"],
                         env=env, timeout=30)
        if hooks.returncode == 0 and hooks.stdout.strip():
            _git_sync(["config", "-f", cfg, "core.hooksPath",
                      hooks.stdout.strip()])


# `<run-dir>/repo-settings/`: leerie's copy of the settings git reads to
# report a tree of the run (DESIGN §8 *The settings are leerie's*). `config`
# and `info/` are the run repository's own, copied once when it is made and
# compared on every read; `host.*` are the settings outside it, copied once
# per orchestrator process and read instead of the originals.
RUN_REPO_SETTINGS_NAME = "repo-settings"
_HOST_SETTINGS = ("host.config", "host.attributes", "host.exclude")
# Run directories whose host settings this process has copied.
_HOST_SETTINGS_TAKEN: set[str] = set()
# Optimisations that never change a correct answer and can each give a
# wrong one: off for every read through the run's settings.
_GIT_VIEW_PINS = ("-c", "core.fsmonitor=false",
                  "-c", "core.untrackedCache=false")


def _take_run_settings(repo: Path) -> None:
    """Copy the run repository's `config` and `info/` to its settings
    directory, once: a copy that exists is never retaken (a resume must
    not adopt a worker's change as leerie's)."""
    s = Path(repo).parent / RUN_REPO_SETTINGS_NAME
    if (s / "config").is_file():
        return
    s.mkdir(parents=True, exist_ok=True)
    _rmtree_owned(s / "info")
    if (Path(repo) / "info").is_dir():
        shutil.copytree(Path(repo) / "info", s / "info", symlinks=True)
    tmp = s / f".config.tmp-{os.getpid()}"
    shutil.copyfile(Path(repo) / "config", tmp)
    os.replace(tmp, s / "config")


def _take_host_settings(repo: Path) -> None:
    """Copy the settings outside the run repository, as git resolves them
    from it, to its settings directory, once per process: the system and
    global config flattened with their includes into `host.config`, the
    system and global attributes files concatenated into `host.attributes`
    (system first, as git reads them), and the global ignore file into
    `host.exclude`. Mechanical: config keys and file paths only."""
    s = Path(repo).parent / RUN_REPO_SETTINGS_NAME
    if str(s) in _HOST_SETTINGS_TAKEN:
        return
    s.mkdir(parents=True, exist_ok=True)
    tmp = s / f".host.config.tmp-{os.getpid()}"
    tmp.write_bytes(b"")
    for scope in ("--system", "--global"):
        r = _git_sync([*_git_at(repo), "config", scope, "--includes",
                       "--list", "-z"], timeout=30)
        if r.returncode != 0:
            continue                      # no such file
        for entry in r.stdout.split("\0"):
            if not entry:
                continue
            key, sep, value = entry.partition("\n")
            w = _git_sync(["config", "-f", str(tmp), "--add", key,
                           value if sep else "true"])
            if w.returncode != 0:
                raise RunRepoError(f"git config --add {key}: "
                                   f"{w.stderr.strip()[:300]}")
    os.replace(tmp, s / "host.config")

    def _read(path: str) -> bytes:
        try:
            return Path(os.path.expanduser(path)).read_bytes() if path else b""
        except OSError:
            return b""
    attrs = b""
    if not os.environ.get("GIT_ATTR_NOSYSTEM"):
        attrs += _read(_git_sync([*_git_at(repo), "var", "GIT_ATTR_SYSTEM"],
                                 timeout=30).stdout.strip())
    glob_attrs = _read(_git_sync([*_git_at(repo), "var", "GIT_ATTR_GLOBAL"],
                                 timeout=30).stdout.strip())
    if attrs and glob_attrs and not attrs.endswith(b"\n"):
        attrs += b"\n"
    excl = _git_sync([*_git_at(repo), "config", "--path", "--get",
                      "core.excludesFile"], timeout=30).stdout.strip()
    if not excl:
        xdg = os.environ.get("XDG_CONFIG_HOME") or os.path.join(
            os.path.expanduser("~"), ".config")
        excl = os.path.join(xdg, "git", "ignore")
    for name, data in (("host.attributes", attrs + glob_attrs),
                       ("host.exclude", _read(excl))):
        t = s / f".{name}.tmp-{os.getpid()}"
        t.write_bytes(data)
        os.replace(t, s / name)
    _HOST_SETTINGS_TAKEN.add(str(s))


def _seal_run_repo_config(repo: Path) -> None:
    """`repack.updateServerInfo=false` in a repository being made, before
    leerie copies its settings: `git gc --auto`, which any commit or fetch
    can start, writes `info/refs` otherwise, which would read as a
    worker's change to `info/`. And no pruning while the run lives (DESIGN
    §6 *A repository per committing tree (I6)*): the tree repositories
    borrow this repository's objects, so one a back-out made unreachable may
    still be one a tree reaches. After the carried config, so a user's own
    `gc.*` cannot undo it."""
    for key, value in (("repack.updateServerInfo", "false"),
                       ("gc.auto", "0"),
                       ("gc.pruneExpire", "never"),
                       ("gc.worktreePruneExpire", "never"),
                       ("maintenance.auto", "false")):
        sv = _git_sync(["config", "-f", str(Path(repo) / "config"), key,
                        value])
        if sv.returncode != 0:
            raise RunRepoError(f"git config {key}: "
                               f"{sv.stderr.strip()[:300]}")


def _take_settings(repo: Path, *, fresh: bool) -> None:
    """Leerie's copy of the run repository's settings (DESIGN §8 *The
    settings are leerie's*), the one hook `_ensure_run_repo` calls on each
    of its paths. `fresh` (a repository it just renamed into place): any
    copy a crash left is dropped first. Otherwise (a recorded or adopted
    repository) the copy is taken only when missing — a run made before
    leerie kept one, or a crash between the rename and the copy."""
    s = Path(repo).parent / RUN_REPO_SETTINGS_NAME
    if fresh:
        _rmtree_owned(s)
        _HOST_SETTINGS_TAKEN.discard(str(s))
    _take_run_settings(repo)
    _take_host_settings(repo)


def _run_settings_of(tree: str | Path) -> tuple[Path, Path] | None:
    """`(common dir, settings dir)` when `tree` is a worktree of a run's
    own repository or of one of its tree repositories, found from leerie's
    layout (`_run_tree_location`), else None: a tree of any other
    repository, a clone included, is read with its own settings."""
    loc = _run_tree_location(tree)
    if not loc:
        return None
    common = loc[0]
    if common.parent.name == TREE_REPOS_NAME:
        # A tree of a tree repository (DESIGN §6 *A repository per
        # committing tree (I6)*): its `config` and `info/` were copied from
        # the run's settings, and are read and restored against them.
        run_dir = common.parent.parent
    elif common.name == RUN_REPO_NAME:
        run_dir = common.parent
    else:
        return None
    if _run_repo_of(run_dir) is None:
        return None
    return common, run_dir / RUN_REPO_SETTINGS_NAME


def _git_view(tree: str | Path) -> tuple[list[str], dict[str, str] | None]:
    """The arguments after `git` (`-C <tree> -c …`) and the environment of
    a git command that reads `tree` through the run's settings (DESIGN §8 *The
    settings are leerie's*): outside the run repository, leerie's copies
    (`GIT_CONFIG_SYSTEM`, `GIT_CONFIG_GLOBAL`, `GIT_ATTR_NOSYSTEM`,
    `core.attributesFile`, `core.excludesFile`); `core.fsmonitor` and
    `core.untrackedCache` off. A tree of no run repository keeps its own
    settings (env None: the orchestrator's), the two optimisations off.
    The shell half is `leerie_vgit`."""
    args = _tree_git_args(tree)
    loc = _run_settings_of(tree)
    if loc is None:
        return args, None
    s = loc[1]
    env = dict(os.environ)
    env.update(GIT_CONFIG_SYSTEM=os.devnull,
               GIT_CONFIG_GLOBAL=str(s / "host.config"),
               GIT_ATTR_NOSYSTEM="1")
    return ([*args,
             "-c", f"core.attributesFile={s / 'host.attributes'}",
             "-c", f"core.excludesFile={s / 'host.exclude'}"], env)


def _same_settings_path(a: Path, b: Path) -> bool:
    """True when `a` and `b` hold the same thing: both absent, the same
    bytes, the same symlink target, or directories of the same entries,
    recursively. Never follows a symlink."""
    try:
        sa, sb = os.lstat(a), os.lstat(b)
    except FileNotFoundError:
        return not os.path.lexists(a) and not os.path.lexists(b)
    except OSError:
        return False
    if stat.S_IFMT(sa.st_mode) != stat.S_IFMT(sb.st_mode):
        return False
    if stat.S_ISLNK(sa.st_mode):
        return os.readlink(a) == os.readlink(b)
    if stat.S_ISDIR(sa.st_mode):
        try:
            na, nb = sorted(os.listdir(a)), sorted(os.listdir(b))
        except OSError:
            return False
        return na == nb and all(_same_settings_path(a / n, b / n)
                                for n in na)
    try:
        return a.read_bytes() == b.read_bytes()
    except OSError:
        return False


def _settings_dirt(tree: str | Path) -> list[str]:
    """I1's settings lines for `tree`: one per run-repository settings path
    (`config`, `info`) that differs from leerie's copy, or one when the copy
    is missing; [] for a tree of no run repository. The shell half prints
    the same lines (`leerie_settings_dirt`)."""
    loc = _run_settings_of(tree)
    if loc is None:
        return []
    common, s = loc
    if not (s / "config").is_file():
        return [f"{_SETTINGS_LINE}unknown: leerie's copy {s} of the run "
                "repository's settings is missing"]
    return [f"{_SETTINGS_LINE}changed: {common / n} differs from leerie's "
            f"copy {s / n}" for n in ("config", "info")
            if not _same_settings_path(s / n, common / n)]


def _restore_settings(tree: str | Path) -> list[str]:
    """Copy leerie's settings back over the run repository's `config` and
    `info/` where they differ (DESIGN §8 *The settings are leerie's*), and
    return the names restored; [] for a tree of no run repository, or
    when leerie's copy is missing (the checker's postcondition names
    it). The repository may be a tree repository its committing worker
    writes whole, so every write is made from its root down without
    following a link (DESIGN §6 *Leerie never writes through a path
    confined code shaped*)."""
    loc = _run_settings_of(tree)
    if loc is None:
        return []
    common, s = loc
    if not (s / "config").is_file():
        return []
    done: list[str] = []
    if not _same_settings_path(s / "config", common / "config"):
        _write_beneath(common, common / "config",
                       (s / "config").read_bytes(),
                       mode=stat.S_IMODE(os.stat(s / "config").st_mode))
        done.append("config")
    if not _same_settings_path(s / "info", common / "info"):
        if not _rmtree_owned(common / "info"):
            raise OSError(f"cannot remove {common / 'info'}")
        if (s / "info").is_dir():
            _copytree_beneath(s / "info", common, common / "info")
        done.append("info")
    return done


_USER_HEAD_REF = "refs/leerie/user-head"


def _refresh_run_repo_base(st: "State", repo: Path | None = None) -> str:
    """Fetch the working branch's tip, under its own name, from the user's
    repository into the run's repository (`repo`, default `_run_repo(st)`).
    Called wherever leerie reads the working branch's tip to (re)base
    something: the planning worktree's reset and `setup-run.sh`'s cut
    (DESIGN §12 L4). So the run still follows that tip, and a worker's
    commit onto the run repository's copy is put back. The user's HEAD is
    fetched only when the run repository has none recorded yet (its
    creation, the run's own start) or the run started detached and has no
    branch to follow; then it becomes the run repository's detached HEAD.
    A mid-run branch switch therefore brings no other branch's history in
    (review round 17 L1). Tags pointing into the fetched history come along
    (git's tag auto-follow). Returns the commit the run follows."""
    repo = Path(repo) if repo is not None else _run_repo(st)
    at = ["--git-dir", str(repo)]
    user = str(Path(st.repo_root).resolve())
    ref = _working_branch_ref(user, st)
    have_head = _git_sync([*at, "rev-parse", "--verify", "-q",
                           _USER_HEAD_REF], timeout=30).returncode == 0
    fetch_head = ref is None or not have_head
    refspecs = ([f"+HEAD:{_USER_HEAD_REF}"] if fetch_head else []) + (
        [f"+{ref}:{ref}"] if ref is not None else [])
    # `--update-head-ok`: a worker that checked out the copy of the working
    # branch in one of the run's worktrees must not stop the refresh.
    f = _git_sync([*at, "fetch", "--quiet", "--no-write-fetch-head",
                   "--no-recurse-submodules", "--update-head-ok", user,
                   *refspecs])
    if f.returncode != 0:
        raise RunRepoError(f"fetch from {user}: {f.stderr.strip()[:300]}")
    followed = _USER_HEAD_REF if ref is None else ref
    got = _git_sync([*at, "rev-parse", "--verify", "-q",
                     f"{followed}^{{commit}}"], timeout=30)
    sha = got.stdout.strip()
    if got.returncode != 0 or not sha:
        raise RunRepoError(f"{followed} did not arrive in the run's "
                           "repository")
    if fetch_head:
        head = _git_sync([*at, "rev-parse", "--verify", "-q",
                          f"{_USER_HEAD_REF}^{{commit}}"],
                         timeout=30).stdout.strip()
        u = _git_sync([*at, "update-ref", "--no-deref", "HEAD", head],
                      timeout=30)
        if u.returncode != 0:
            raise RunRepoError(f"update-ref HEAD: {u.stderr.strip()[:300]}")
    return sha


def _run_repo_commit(st: "State", sha: str, ref: str) -> bool:
    """True when commit `sha` is in the run's own repository, fetching it
    by SHA from the user's repository (kept under `ref`) when it is not —
    a commit leerie read in the user's checkout (the run's own start, a
    sibling run's start) is measured in the run's repository. Never
    raises."""
    at = ["--git-dir", str(Path(st.run_dir) / RUN_REPO_NAME)]

    def _has() -> bool:
        return _git_sync([*at, "cat-file", "-e", f"{sha}^{{commit}}"],
                         timeout=30).returncode == 0
    try:
        if _has():
            return True
        _git_sync([*at, "fetch", "--quiet", "--no-write-fetch-head",
                   "--no-recurse-submodules",
                   str(Path(st.repo_root).resolve()), f"+{sha}:{ref}"])
        return _has()
    except (OSError, subprocess.TimeoutExpired):
        return False


def _run_repo_unusable(st: "State", repo: Path) -> str:
    """Why the recorded run repository cannot be used, or "" when it can.
    Checked by naming it explicitly (`--git-dir`) and asking for the commit
    the run started from — `base_sha` once the run branch is cut, the
    user's HEAD at creation before — which no worker's git command can
    change (review round 17 H1)."""
    if not (repo / "HEAD").is_file():
        return "it is missing"
    anchor = st.data.get("base_sha") or _USER_HEAD_REF
    r = _git_sync(["--git-dir", str(repo), "rev-parse", "--verify", "-q",
                   f"{anchor}^{{commit}}"], timeout=30)
    if r.returncode != 0:
        return f"it does not hold {anchor}"
    return ""


def _ensure_run_repo(st: "State") -> Path:
    """Create the run's own repository once (DESIGN §6 *The run's own
    repository*) and return it. Once `run_repo` is recorded the repository
    is the run's only store of its commits: leerie never deletes it or
    builds it again, and a repository that fails `_run_repo_unusable`
    raises RunRepoError naming it (review round 17 H1). Built — fetched
    included — in a scratch directory and renamed into place, so a
    repository at the final path is always complete; one a crash left
    there unrecorded is adopted after the same check. Scratch directories
    a crash left behind are removed (creation holds the run's flock, so
    none is live; round 17 L2). Raises RunRepoError; the callers die()."""
    repo = Path(st.run_dir) / RUN_REPO_NAME
    if st.data.get("run_repo"):
        why = _run_repo_unusable(st, repo)
        if why:
            raise RunRepoError(
                f"the run's repository {_operator_path(repo)} is recorded "
                f"but unusable: {why}. It is the only copy of this run's "
                "commits, so leerie will not delete or rebuild it — inspect "
                f"it with `git --git-dir {_operator_path(repo)} log --all`")
        _take_settings(repo, fresh=False)
        return repo
    for stale in Path(st.run_dir).glob(f".{RUN_REPO_NAME}.tmp-*"):
        _rmtree_owned(stale)
    if repo.exists():
        why = _run_repo_unusable(st, repo)
        if why:
            raise RunRepoError(
                f"{_operator_path(repo)} exists but is not this run's "
                f"recorded repository ({why}); leerie will not delete it — "
                "move it aside to start the run's repository afresh")
        _take_settings(repo, fresh=False)
        st.data["run_repo"] = RUN_REPO_NAME
        st.save()
        return repo
    user = str(Path(st.repo_root).resolve())
    tmp = Path(st.run_dir) / f".{RUN_REPO_NAME}.tmp-{os.getpid()}"
    fmt = _git_sync([*_tree_git_args(user), "rev-parse",
                     "--show-object-format"],
                   timeout=30)
    if fmt.returncode != 0:
        raise RunRepoError(f"{user} is not a git repository: "
                           f"{fmt.stderr.strip()[:300]}")
    init = _git_sync(["init", "--quiet", "--bare",
                     f"--object-format={fmt.stdout.strip() or 'sha1'}",
                     str(tmp)], timeout=60)
    if init.returncode != 0:
        raise RunRepoError(f"git init --bare: {init.stderr.strip()[:300]}")
    try:
        _carry_repo_config(Path(user), tmp)
        _seal_run_repo_config(tmp)
        _refresh_run_repo_base(st, tmp)
        os.rename(tmp, repo)
        _take_settings(repo, fresh=True)
    except BaseException:
        _rmtree_owned(tmp)
        raise
    st.data["run_repo"] = RUN_REPO_NAME
    st.save()
    return repo


async def _ensure_run_repo_or_die(st: "State") -> Path:
    """`_ensure_run_repo` off the event loop (the first fetch copies the
    working branch's history), dying on failure."""
    try:
        return await asyncio.to_thread(_ensure_run_repo, st)
    except (RunRepoError, OSError, subprocess.TimeoutExpired) as e:
        die(f"the run's own repository under "
            f"{_operator_path(Path(st.run_dir) / RUN_REPO_NAME)}: {e}\n"
            "leerie runs every worker in a repository of the run's own, "
            "never in yours (DESIGN §6 *The run's own repository*).")
        raise  # unreachable: die() exits


async def _refresh_run_repo_base_or_die(st: "State", where: str) -> str:
    try:
        return await asyncio.to_thread(_refresh_run_repo_base, st)
    except (RunRepoError, OSError, subprocess.TimeoutExpired) as e:
        die(f"{where}: could not refresh the run's repository from yours: {e}")
        raise  # unreachable: die() exits


# The launcher's per-invocation file the orchestrator names its run in
# (DESIGN §6 *Which run the container ran*); set by the local launcher only.
RUN_ID_FILE_ENV = "LEERIE_RUN_ID_FILE"


def _record_run_id_for_launcher(run_id: str) -> None:
    """Write `run_id` to the file `LEERIE_RUN_ID_FILE` names, atomically:
    the orchestrator's own resolution (`resolve_run_id`, a bare `resume`'s
    pick included) is the one source of which run the container ran, and
    the launcher reads it after exit to bring that run's branch back. A
    no-op when the variable is unset (Fly/EC2, tests, a direct invocation).
    Never raises: a failed write is logged, and the branch then comes back
    at the run's finalize or `prune`."""
    path = os.environ.get(RUN_ID_FILE_ENV, "")
    if not path:
        return
    tmp = f"{path}.tmp-{os.getpid()}"
    try:
        with open(tmp, "w") as f:
            f.write(run_id + "\n")
        os.replace(tmp, path)
    except OSError as e:
        log(f"WARNING: could not tell the launcher this is run {run_id} "
            f"({e}); its branch comes back at finalize or `leerie prune`")
        with contextlib.suppress(OSError):
            os.unlink(tmp)


# The run-directory layout this leerie writes and reads (DESIGN §6 *A run
# directory is continued only by a leerie of its layout*). Bump it with any
# change to what a run directory holds that a later process of the run reads
# back. The layout before the field, which recorded nothing, counts as 1.
# 4: every store a tree installs from moved beside the trees, into
# `<run-dir>/worktrees/.stores/` (DESIGN §6 *The write grants on one mount
# are one mount*).
RUN_LAYOUT_VERSION = 4


def _refuse_other_run_layout(st: "State", verb: str) -> None:
    """Stop `verb` on a run directory another leerie's layout made (DESIGN §6
    *A run directory is continued only by a leerie of its layout*). `st.data`
    is the run's loaded `state.json`. Called by `main()` before anything
    writes in the directory and before the exit arms that would stamp and
    clean it, so a refused directory stays as its own leerie left it."""
    layout = st.data.get("run_layout")
    if layout == RUN_LAYOUT_VERSION:
        return
    newer = isinstance(layout, int) and layout > RUN_LAYOUT_VERSION
    made_by = st.data.get("leerie_version")
    die(f"run {st.run_id} was made by {'a newer' if newer else 'an older'} "
        f"leerie{f' (recorded as {made_by})' if made_by else ''}: its run "
        "directory has run layout "
        f"{layout if layout is not None else 'none recorded'}, and this "
        f"leerie reads only layout {RUN_LAYOUT_VERSION}, so it cannot "
        f"`{verb}` it. Finish it with the leerie that made it, or start the "
        "task again as a fresh run. `leerie list`, `leerie finalize` and "
        "`leerie prune` still work on it.")


def _stage_worktree_extras(st: "State", worktree: str) -> None:
    """Copy the things a judgment worker needs that `git worktree add` does
    not carry, because git only checks out TRACKED content.

    Two classes, both measured rather than imagined:

    1. **Untracked task-reference files.** `_preflight_repo` filters `??`
       lines out of its clean-tree gate, so untracked content is a normal
       state for a repo leerie will happily run on. Meanwhile
       `_glob_task_references` resolves the task's file references against the
       real checkout and `_format_task_file_references` emits them
       repo-relative, with an instruction to read each one — so a worker in a
       worktree would be told to read a path that is not there. This is not
       hypothetical: on the run that motivated this change, the classifier's
       very first action was reading a task document that `git status` reports
       as untracked. Losing it would have been a silent, total loss of the
       spec.
    2. **`.claude/`**, when the repo has one and does not track it. Repos
       commonly gitignore it, and `scripts/remote/seed-repo.sh` already
       force-ships it to `/work` for exactly this reason — "workers need its
       hooks/agents/skills/commands to function".

    Best-effort throughout: a copy failure degrades the worker's context but
    must never take down a run that would otherwise proceed."""
    try:
        repo_root = Path(st.repo_root)
        wt = Path(worktree)
        task = st.data.get("task") or ""
        staged = 0
        # Resolved once per call: every skip decision below compares HEAD
        # with this same ref.
        wb_ref = _working_branch_ref(repo_root, st)
        if task:
            for src in _glob_task_references(task, repo_root):
                try:
                    rel = src.resolve().relative_to(repo_root.resolve())
                except ValueError:
                    continue          # outside the repo; not ours to stage
                dst = wt / rel
                # The planning worktree is written by the workers that run
                # in it: never followed through a link one left (DESIGN §6
                # *Leerie never writes through a path confined code
                # shaped*).
                if _lexists_beneath(wt, dst):
                    continue          # tracked — the worktree already has it
                # Files committed on the branch the operator switched to
                # mid-run and absent from the run's own branch: staging one
                # would show the satisfied-probe a deliverable its tree does
                # not have. Skipped file by file, so untracked task documents
                # beside them in the same directory are still staged.
                skip = _switched_branch_only_paths(repo_root, str(rel), wb_ref)
                if str(rel) in skip:
                    log(f"WARNING: planning worktree: not staging {rel} — it "
                        "is committed only on the branch now checked out, "
                        "not on the run's working branch; workers will not "
                        "see it")
                    continue
                try:
                    if _dir_beneath_exists(repo_root, src):
                        _copytree_beneath(
                            src, wt, dst,
                            ignore=_ignore_repo_paths(repo_root, skip),
                            src_anchor=repo_root, limit=READ_LIMIT_LARGE)
                    else:
                        _copy_beneath(src, wt, dst, src_anchor=repo_root, limit=READ_LIMIT_LARGE)
                    staged += 1
                except Exception:
                    continue
        claude_src, claude_dst = repo_root / ".claude", wt / ".claude"
        if _dir_beneath_exists(repo_root, claude_src) \
                and not _lexists_beneath(wt, claude_dst):
            skip = _switched_branch_only_paths(repo_root, ".claude", wb_ref)
            try:
                _copytree_beneath(claude_src, wt, claude_dst,
                                  ignore=_ignore_repo_paths(repo_root, skip),
                                  src_anchor=repo_root, limit=READ_LIMIT_LARGE)
                staged += 1
            except Exception:
                pass
        if staged:
            log(f"planning worktree: staged {staged} untracked path(s) "
                "the worker would otherwise not see")
    except Exception as e:
        log(f"planning worktree: could not stage untracked paths "
            f"(non-fatal): {e}")


def _working_branch_ref(repo_root: str | Path, st: "State") -> str | None:
    """The full ref (`refs/heads/<name>`) of the branch the run started on,
    or None when there is none to follow (not yet recorded, a detached
    start, the branch no longer exists, or git could not be run). Tries the
    recorded name, then the name without a leading `heads/` (`git rev-parse
    --abbrev-ref HEAD` prints `heads/<name>` when a tag shares the branch's
    name), then a name already of the form `refs/heads/<name>` (printed when
    even `heads/<name>` is ambiguous). The same lookup as `setup-run.sh` /
    `planning-worktree.sh`, so all three agree on which tree the run
    follows."""
    args = _working_branch_arg(st)
    if not args:
        return None
    wb = args[0]
    candidates = [f"refs/heads/{wb}"]
    if wb.startswith("heads/"):
        candidates.append(f"refs/heads/{wb[len('heads/'):]}")
    if wb.startswith("refs/heads/"):
        candidates.append(wb)
    for ref in candidates:
        try:
            r = subprocess.run(
                ["git", *_tree_git_args(repo_root), "show-ref", "--verify",
                 "--quiet", ref],
                capture_output=True, text=True, check=False, timeout=30)
        except (OSError, subprocess.SubprocessError):
            return None
        if r.returncode == 0:
            return ref
    return None


def _switched_branch_only_paths(repo_root: Path, rel: str,
                                wb_ref: str | None) -> set[str]:
    """Repo-relative files under *rel* (a file or a directory) that are
    committed on the branch currently checked out but not on the run's
    working branch (*wb_ref*, from `_working_branch_ref`) — content of a
    branch the operator switched to mid-run (DESIGN §12 L2/L4), which must
    not be staged into the planning worktree. Untracked and
    staged-but-uncommitted files are never in it, so task documents beside
    such content are still staged. `git ls-tree` reads commits and matches
    paths literally (no pathspec globbing) — mechanical output. No branch
    to follow, or any git failure, answers the empty set: the copy then
    proceeds exactly as before."""
    if wb_ref is None:
        return set()

    def _committed(rev: str) -> set[str] | None:
        # Bytes, decoded as the filesystem does, and any failure is None: an
        # exception here would reach `_stage_worktree_extras`'s outer catch
        # and abandon every later task reference, the spec included.
        try:
            r = subprocess.run(
                ["git", "--literal-pathspecs", *_tree_git_args(repo_root),
                 "ls-tree", "-r", "-z", "--name-only", rev, "--", rel],
                capture_output=True, check=False, timeout=30)
            if r.returncode != 0:
                return None
            return {os.fsdecode(p) for p in r.stdout.split(b"\0") if p}
        except Exception:
            return None

    on_head = _committed("HEAD")
    on_wb = _committed(wb_ref)
    if on_head is None or on_wb is None:
        return set()
    return on_head - on_wb


def _ignore_repo_paths(
        repo_root: Path,
        skip: set[str]) -> Callable[[str, list[str]], set[str]]:
    """A `shutil.copytree` *ignore* callable dropping exactly the
    repo-relative paths in *skip*."""
    root = repo_root.resolve()

    def _ignore(directory: str, names: list[str]) -> set[str]:
        if not skip:
            return set()
        try:
            base = Path(directory).resolve().relative_to(root)
        except ValueError:
            return set()
        return {n for n in names
                if (base / n).as_posix() in skip}

    return _ignore


def _working_branch_arg(st: "State") -> list[str]:
    """The optional `<working-branch>` argument for `setup-run.sh` and
    `planning-worktree.sh`: the branch the run started on, so both follow its
    tip rather than whatever is checked out now. The checkout sentinel only
    warns on a mid-run change (DESIGN §12 L4), so an operator checking out
    another branch must not re-base the run onto it. Empty — the scripts then
    use the live HEAD — before the branch is recorded, or when the run
    started detached (`git rev-parse --abbrev-ref` printed `HEAD`)."""
    wb = st.data.get("working_branch") or ""
    return [wb] if wb and wb != "HEAD" else []


async def _base_tree_sha(repo_root: str, st: "State") -> str:
    """The sha of the tree the planning worktree mirrors: the working
    branch's tip when `_working_branch_ref` resolves, else the real
    checkout's HEAD — the same choice `planning-worktree.sh` makes.

    Resolved through `_working_branch_ref`, the same lookup the script
    makes. The satisfied-probe cache is keyed on this. Keyed on the live HEAD
    instead, an operator's mid-run branch switch would file verdicts about
    the working branch's tree under the other branch's sha, and a later
    advance of the working branch would never invalidate them (DESIGN §6,
    §12 L4)."""
    ref = await asyncio.to_thread(_working_branch_ref, repo_root, st)
    if ref is not None:
        try:
            r = await run_proc(["git", *_tree_git_args(repo_root), "rev-parse", "--verify", "--quiet",
                                ref], cwd=repo_root)
        except OSError:
            r = None
        if r is not None and r.returncode == 0 and r.stdout.strip():
            return r.stdout.strip()
    return await _branch_head_sha(repo_root)


def _log_working_branch_fallback(proc: subprocess.CompletedProcess,
                                 where: str) -> None:
    """Surface the scripts' `warning: working branch '<name>' not found`
    line. They exit 0 on that fallback, and both callers otherwise print
    stderr only on failure — so a deleted working branch would silently put
    the run back on whatever is checked out. Matches the scripts' own fixed
    prefix: mechanical output, not prose."""
    err = getattr(proc, "stderr", "")
    for ln in (err if isinstance(err, str) else "").splitlines():
        if ln.startswith("warning: working branch "):
            log(f"WARNING: {where}: {ln[len('warning: '):]}")


async def _ensure_planning_worktree(st: "State") -> str:
    """Create (or reset) this run's disposable judgment-worker worktree and
    return its absolute path, recording it in `st.data["planning_worktree"]`.

    Called before `phase_classify`, again by
    `_confirm_no_work_on_converged_gate` before the `no_work_judge`
    spawns, and again before the satisfied-probe
    sweep. It is NOT guarded on the state key being absent: the worktree is a
    filesystem fact, not run state, so a resume must re-establish it (an
    abnormal exit removes it) and a second call must re-reset it (the probe
    needs a clean tree — see the script's header). The state key records the
    path for the audit trail and for `_judgment_cwd`, not for a skip check.

    Fails closed. A silent fallback to the real checkout would reinstate
    exactly the exposure this exists to remove — that holds at every call
    site, which is why the later two (post-classification, pre-sweep)
    still die() despite real spend already sunk by then; the "cheapest
    possible moment to refuse" argument applies only to the first,
    pre-phase-1 call (DESIGN §13)."""
    await _ensure_run_repo_or_die(st)
    await _refresh_run_repo_base_or_die(st, "planning worktree")
    proc = await _run_script("planning-worktree.sh", st.run_id,
                             *_working_branch_arg(st), st=st)
    if proc.returncode != 0:
        die("could not create the judgment-worker worktree "
            f"(planning-worktree.sh exited {proc.returncode}).\n"
            f"{proc.stderr.strip()}\n"
            "leerie refuses to run judgment workers in your real checkout — "
            "without the worktree they would plan against, and can write to, "
            "the branch you are sitting on (DESIGN §12).\n"
            "If a previous run left a stale registration behind:\n"
            f"  bash scripts/cleanup.sh --run-id {st.run_id}\n"
            "  ./leerie prune --apply")
    _log_working_branch_fallback(proc, "planning worktree")
    # The script echoes `planning-worktree: <abs path>` as its last line.
    line = proc.stdout.strip().splitlines()[-1] if proc.stdout.strip() else ""
    path = line.split("planning-worktree:", 1)[-1].strip() if line else ""
    if not path or not os.path.isdir(path):
        die("planning-worktree.sh reported no usable path "
            f"(stdout: {proc.stdout.strip()!r}).")
    st.data["planning_worktree"] = path
    st.save()
    # After the reset, not before: `git clean -fd` would remove anything
    # staged by a previous call.
    _stage_worktree_extras(st, path)
    return path


# Paths leerie itself is entitled to write inside the user's checkout, so the
# sentinel below does not report leerie's own bookkeeping as tampering.
# `.leerie/config.toml` is the one committable file the orchestrator writes
# (DESIGN §6½ dep capture); `.leerie/` at large is the state root on the
# Fly/EC2 runtimes, where `resolve_leerie_root` falls back to `<repo>/.leerie`.
_SENTINEL_EXEMPT_PREFIXES = (".leerie/",)


async def _snapshot_repo_state(repo_root: str) -> dict:
    """Capture the user's checkout identity: HEAD, porcelain status, refs.

    Deliberately includes UNTRACKED files. `_preflight_repo` filters `??`
    lines out of its clean-tree gate, which means "clean at run start" already
    tolerates arbitrary untracked content — so a worker *creating* files is
    precisely the case that gate cannot see, and precisely what a runaway
    judgment worker does first."""
    ok = True

    async def _out(*argv: str) -> str:
        nonlocal ok
        r = await run_proc(list(argv), cwd=repo_root)
        if r.returncode != 0:
            ok = False
            return ""
        return r.stdout

    # Untracked entries from the one listing (DESIGN §8 *One ignore rule*),
    # a wholly untracked directory as `dir/`, as status would show it.
    u_args, u_env = await asyncio.to_thread(
        functools.partial(_untracked_cmd, repo_root, directory=True))
    u = await run_proc(["git", *u_args], env=u_env)
    if u.returncode != 0:
        ok = False
    # `--no-optional-locks`: status would otherwise refresh the user's
    # index, taking `index.lock` in a checkout leerie only reads (read-only
    # in the local container; DESIGN §6 *The explicit channel*).
    lines = (await _out("git", "--no-optional-locks", "status", "--porcelain",
                        "--untracked-files=no")).splitlines()
    lines += [f"?? {p}" for p in (u.stdout.split("\0")
                                  if u.returncode == 0 else []) if p]
    porcelain = [
        ln for ln in lines
        if not any(ln[3:].startswith(p) for p in _SENTINEL_EXEMPT_PREFIXES)
    ]
    head = (await _out("git", "rev-parse", "HEAD")).strip()
    refs = sorted((await _out(
        "git", "for-each-ref", "--format=%(refname) %(objectname)",
        "refs/heads")).splitlines())
    # `ok` records whether every probe actually answered. Without it a
    # transiently unreadable checkout produces head="" and refs=[], which
    # `_diff_repo_state` reads as "HEAD moved" plus "every branch deleted" —
    # a fabricated tampering report that would die() a perfectly healthy run.
    # A check that cries wolf gets disabled, which would cost the guarantee.
    return {"head": head, "porcelain": sorted(porcelain), "refs": refs,
            "ok": ok}


def _diff_repo_state(before: dict, after: dict, *,
                     porcelain_only: bool = False) -> list[str]:
    """Human-readable deltas between two `_snapshot_repo_state` results.

    Ref changes under leerie's own namespaces are expected — the run branch
    and subtask branches are created during a run — so only refs OUTSIDE
    `refs/heads/leerie/` count as tampering.

    `porcelain_only` drops the HEAD and ref comparisons, keeping only the
    working-tree one. Planning phases take minutes and the operator is
    waiting, so any movement there is suspicious; the execute phase runs for
    hours (measured p90 285 min, n=87) and an operator legitimately pulls
    their own checkout mid-run. Reporting a `git pull` on every wave is noise,
    and a guard that cries wolf gets switched off — the same reasoning that
    put the `ok` field on `_snapshot_repo_state`. File mutation is the damage
    class that matters. The execute call keeps the HEAD/ref comparison only
    under `stop_on_repo_change`, where the operator asked to halt on commits
    too (`_execute_check_porcelain_only`).
    """
    out: list[str] = []
    if not porcelain_only and before.get("head") != after.get("head"):
        out.append(f"HEAD moved: {before.get('head', '?')[:12]} -> "
                   f"{after.get('head', '?')[:12]}")
    b_files, a_files = set(before.get("porcelain", [])), set(
        after.get("porcelain", []))
    for ln in sorted(a_files - b_files):
        out.append(f"working tree changed: {ln}")
    def _own(ref_line: str) -> bool:
        return ref_line.split(" ", 1)[0].startswith("refs/heads/leerie/")
    if not porcelain_only:
        b_refs = {r for r in before.get("refs", []) if not _own(r)}
        a_refs = {r for r in after.get("refs", []) if not _own(r)}
        for r in sorted(a_refs - b_refs):
            out.append(f"ref created/moved: {r}")
        for r in sorted(b_refs - a_refs):
            out.append(f"ref deleted: {r}")
    return out


def _porcelain_path(line: str) -> str:
    """The (target) path of one `git status --porcelain` v1 line —
    mechanical git output, never prose. `XY <path>`, or `XY <old> -> <new>`
    for a rename/copy (an `R`/`C` status). Porcelain C-quotes any name with
    whitespace, a quote, a backslash or a non-ASCII byte, so ` -> ` can only
    separate two names when the status says rename/copy and the old name is
    unquoted-and-spaceless or a complete quoted string; a quoted name is
    decoded (octal escapes back to UTF-8 bytes)."""
    status, rest = line[:2], line[3:]
    if "R" in status or "C" in status:
        if rest.startswith('"'):
            k, escaped = 1, False
            while k < len(rest):
                ch = rest[k]
                if escaped:
                    escaped = False
                elif ch == "\\":
                    escaped = True
                elif ch == '"':
                    break
                k += 1
            tail = rest[k + 1:]
            if tail.startswith(" -> "):
                rest = tail[len(" -> "):]
        elif " -> " in rest:
            rest = rest.split(" -> ", 1)[1]
    if len(rest) >= 2 and rest.startswith('"') and rest.endswith('"'):
        try:
            raw = codecs.escape_decode(rest[1:-1].encode("utf-8"))[0]
        except ValueError:
            # Not a whole quoted name (e.g. a fragment a U+2028 in a name
            # split off): keep the raw text rather than raise.
            return rest
        return raw.decode("utf-8", "surrogateescape")
    return rest


def _delta_fingerprint(repo_root: Path, delta: str) -> str:
    """Change fingerprint for one `_diff_repo_state` delta, so a warned
    delta re-warns when its path changes again. Working-tree deltas are
    `working tree changed: <porcelain line>` (path from `_porcelain_path`).
    Metadata only — never file contents, so a huge untracked file costs one
    `lstat`, and symlinks are not followed: a file is its `lstat`
    (size, mtime_ns, inode); a directory (porcelain collapses an untracked
    one to `dir/`) is the sorted `lstat`s of the untracked, NOT gitignored
    entries the one listing (`_untracked_cmd`) gives under it (so ignored
    build output or a nested repo's churn inside it does not re-warn; an
    embedded repo is one entry), capped at 5000; a missing path is
    `absent`; an unreadable one `unreadable`. HEAD/ref deltas already carry
    their sha in the string, so they need none.

    Never raises: it runs inside the checkout sentinel, which must not be
    able to kill a run (a non-UTF-8 name, an odd porcelain line), so any
    failure is `unreadable`."""
    try:
        return _delta_fingerprint_unguarded(repo_root, delta)
    except Exception:
        return "unreadable"


def _delta_fingerprint_unguarded(repo_root: Path, delta: str) -> str:
    """`_delta_fingerprint` without its catch-all; see there."""
    prefix = "working tree changed: "
    if not delta.startswith(prefix):
        return ""
    rel = _porcelain_path(delta[len(prefix):]).rstrip("/")
    path = repo_root / rel
    try:
        st_ = os.lstat(path)
    except FileNotFoundError:
        return "absent"
    except OSError:
        return "unreadable"
    if not stat.S_ISDIR(st_.st_mode):
        return f"{st_.st_size}:{st_.st_mtime_ns}:{st_.st_ino}"
    args, env = _untracked_cmd(repo_root, pathspec=rel + "/")
    try:
        r = subprocess.run(["git", *args], capture_output=True, check=False,
                           env=env, timeout=30)
    except (OSError, subprocess.SubprocessError):
        return "unreadable"
    if r.returncode != 0:
        return "unreadable"
    # Bytes, decoded as the filesystem does: `-z` prints names unquoted, and
    # a non-UTF-8 name must not raise.
    names = [os.fsdecode(n) for n in r.stdout.split(b"\0") if n]
    entries: list[str] = []
    for name in sorted(names)[:5000]:
        try:
            e = os.lstat(repo_root / name)
        except OSError:
            continue
        entries.append(f"{name}\0{e.st_size}\0{e.st_mtime_ns}")
    return hashlib.sha256("\n".join(entries).encode(
        "utf-8", "surrogateescape")).hexdigest()


def _tripwire_operator_overlap(deltas: list[str]) -> bool:
    """True when EVERY delta is a newly-appeared untracked file (porcelain
    `??`) — the measured signature of the operator dropping task/report
    files into the checkout for another run while this one executes, not
    of a worker escape (the measured overlap incident added exactly one
    untracked report `.md`; escapes show tracked-file modifications).
    Mechanical string comparison on `_diff_repo_state`'s fixed delta
    prefixes and git porcelain codes only — never on prose. Deliberately
    narrow: any tracked-file delta, HEAD move, or ref delta returns False
    and keeps the full worker-escape framing (DESIGN §12 L4)."""
    return bool(deltas) and all(
        d.startswith("working tree changed: ?? ") for d in deltas)


def _execute_check_porcelain_only(st: "State") -> bool:
    """`porcelain_only` for the per-wave execute check. The execute phase
    runs for hours and an operator legitimately pulls mid-run, so by default
    only working-tree changes are compared; under `stop_on_repo_change` the
    operator asked to halt on commits too, which is what HEAD/refs cover
    (DESIGN §12 L4)."""
    return not st.data.get("stop_on_repo_change")


async def _assert_repo_unchanged(st: "State", phase: str, *,
                                 porcelain_only: bool = False) -> None:
    """The §12 guarantee: verify no worker has touched the user's checkout.

    Judgment workers no longer carry `--dangerously-skip-permissions`, which
    restores the CLI's working-directory boundary — but that boundary is
    enforced on tool *arguments*, and an allowlisted build verb runs arbitrary
    code. Measured: with permissions ON and `python3` allowlisted,
    `python3 -c "open('<outside path>','w')"` wrote outside the cwd while the
    Write tool aimed at the same path was rejected. So a residual escape
    exists by construction, and this is what covers it.

    Modelled on `check_rebaser_worktree_state`: trust the worker, then
    mechanically re-check the claim. Runs after every planning phase and after
    every execute wave rather than once at the end, so it fires within one
    worker (or one wave) of the damage instead of after the whole spend.

    By default a delta is a WARNING and the run continues; only
    `stop_on_repo_change` makes it die() (DESIGN §12 L4). Measured: 71 of 73
    halted runs carried only operator signatures and none was a confirmed
    escape, while nothing committed or pushed is built from the checkout's
    working tree. Each distinct delta is warned once, and again only if its
    content moves (`repo_change_warned`, `_delta_fingerprint`): the baseline
    is deliberately never refreshed — `_acceptance_own_start` and
    `_acceptance_report_base` read it — so every later check would otherwise
    repeat it. The operator/escape hint
    classifies each newly-warned batch, not every delta since the baseline.

    The execute-phase call passes `porcelain_only` unless the flag is set —
    see `_diff_repo_state`.
    Its known blind spot is a gitignored write: `git status --porcelain` never
    lists `node_modules/`, so the in-checkout dependency installs observed in
    the run corpus stay invisible here. That is an accepted residual, recorded
    rather than assumed away."""
    before = st.data.get("repo_state_before_planning")
    if not before:
        return
    if not before.get("ok", True):
        # The baseline itself is untrustworthy, so nothing can be concluded
        # from a comparison against it.
        return
    after = await _snapshot_repo_state(str(st.repo_root))
    if not after.get("ok", True):
        # "Could not tell" is not "tampered". Warn rather than die: the run is
        # still recoverable and the next phase re-checks.
        log(f"could not verify the checkout after {phase} "
            "(git did not answer); skipping the tamper check this round")
        return
    deltas = _diff_repo_state(before, after, porcelain_only=porcelain_only)
    if not deltas:
        return
    if not st.data.get("stop_on_repo_change"):
        warned = st.data.setdefault("repo_change_warned", {})
        root = Path(st.repo_root)
        fps = {d: await asyncio.to_thread(_delta_fingerprint, root, d)
               for d in deltas}
        if isinstance(warned, list):
            # Written by an earlier build that kept only the delta strings;
            # those were warned already, so adopt their current prints.
            warned = st.data["repo_change_warned"] = {
                d: fps.get(d, "") for d in warned}
        new: list[str] = []
        prints: dict[str, str] = {}
        for d in deltas:
            fp = fps[d]
            if warned.get(d) != fp:
                # New delta, or one already warned whose content moved since:
                # the porcelain line alone would hide a later write to a path
                # the operator had already touched.
                new.append(d + (" (changed again)" if d in warned else ""))
                prints[d] = fp
        if not new:
            return
        if _tripwire_operator_overlap(
                [d.removesuffix(" (changed again)") for d in new]):
            hint = ("every change is a newly-added untracked file — most "
                    "likely your own (a task or report file for another "
                    "run), not a worker escape")
        else:
            hint = ("a tracked file, HEAD or a branch changed — if that "
                    "was not you, a worker may have escaped its worktree; "
                    f"inspect with `git -C {st.repo_root} status`")
            if any(d.startswith(("HEAD moved", "ref ")) for d in new):
                # Mechanical delta prefixes from `_diff_repo_state`.
                hint += ("; note that commits on the run's working branch "
                         "become part of what this run builds on and pushes")
        log(f"WARNING: your real checkout changed during {phase}:\n  "
            + "\n  ".join(new)
            + f"\n  ({hint}). Continuing: nothing leerie commits or pushes "
              "is built from your working tree. Pass --stop-on-repo-change "
              "to halt instead.")
        warned.update(prints)
        st.save()
        return
    if _tripwire_operator_overlap(deltas):
        # Under --stop-on-repo-change. Same stop, different framing: the
        # measured cost of blaming a worker escape here was a from-scratch
        # re-run (full replan) because the message put resume behind a
        # restore step the operator's own files never needed (DESIGN §12 L4).
        die("your real checkout changed during " + phase + ".\n  "
            + "\n  ".join(deltas)
            + "\n\nEvery delta above is a newly-added untracked file — the "
              "signature of operator activity in this checkout (dropping a "
              "task or report file for another run) rather than a worker "
              "escape, which shows up as tracked-file modifications. The "
              "run still stops (--stop-on-repo-change), because its planning "
              "baseline moved — and it stays moved, so resuming with the "
              "flag still set stops again. If those files are yours, no "
              "restore is needed — resume without the flag (set "
              "LEERIE_STOP_ON_REPO_CHANGE=0 if leerie.toml turns it on), and "
              "the change is logged as a warning instead:\n"
              f"  ./leerie resume {st.run_id}\n"
            "If they are NOT yours, treat this as an escape:\n"
            f"  git -C {st.repo_root} status\n"
            f"  git -C {st.repo_root} clean -i")
    die("a worker modified your real checkout during " + phase + ".\n  "
        + "\n  ".join(deltas)
        + "\n\nleerie runs judgment workers in a disposable worktree "
          "precisely so this cannot happen; reaching here means a worker "
          "escaped it (most likely via a build command, which runs arbitrary "
          "code). Your checkout is the source of truth for this run, so it "
          "refuses to keep planning against a tree that moved underneath it.\n"
          "Inspect and restore, then resume:\n"
          f"  git -C {st.repo_root} status\n"
          f"  git -C {st.repo_root} checkout -- <paths>   # tracked edits\n"
          f"  git -C {st.repo_root} clean -i               # files it created\n"
          f"  ./leerie resume {st.run_id}\n"
          "If these changes are yours (a pull, a commit, your own edits), "
          "restoring cannot undo them and resuming with "
          "--stop-on-repo-change still set stops again: resume without the "
          "flag (set LEERIE_STOP_ON_REPO_CHANGE=0 if leerie.toml turns it "
          "on), and they are logged as a warning instead.")


# Each worker's own CLI configuration and temporary directories (DESIGN §6
# *Each worker's own configuration and temporary directories*): a worker
# writes hooks or settings only into its own copy, and its own `TMPDIR`.
WORKERS_DIR = "workers"
CLAUDE_CONFIG_TEMPLATE = "claude-config"
_CLAUDE_CONFIG_TEMPLATE_MARK = ".leerie-template"
# Per-session state of the operator's CLI configuration, never copied into a
# worker's: transcripts, session metadata, history, caches and backups.
_CLAUDE_CONFIG_SKIP = frozenset({
    "projects", "sessions", "session-env", "shell-snapshots", "history.jsonl",
    "todos", "tasks", "plans", "file-history", "paste-cache", "telemetry",
    "statsig", "debug", "downloads", "backups", "ide", "local",
    "stats-cache.json", ".last-cleanup"})


def _claude_config_template(run_dir: Path) -> Path:
    """`<run_dir>/claude-config/`: the run's snapshot of the operator's CLI
    configuration (`$CLAUDE_CONFIG_DIR`, else `~/.claude`, without its
    per-session state, plus `~/.claude.json`), made once — at the run's
    first worker — and kept for the run, so nothing a worker writes later
    reaches another worker's copy."""
    t = Path(run_dir) / CLAUDE_CONFIG_TEMPLATE
    if (t / _CLAUDE_CONFIG_TEMPLATE_MARK).is_file():
        return t
    env_dir = os.environ.get("CLAUDE_CONFIG_DIR")
    src = Path(env_dir) if env_dir else Path.home() / ".claude"
    tmp = Path(run_dir) / f".{CLAUDE_CONFIG_TEMPLATE}.tmp-{os.getpid()}"
    _rmtree_owned(tmp)
    if src.is_dir():
        shutil.copytree(src, tmp, symlinks=True,
                        ignore=lambda d, names: (
                            [n for n in names if n in _CLAUDE_CONFIG_SKIP]
                            if Path(d) == src else []))
    else:
        tmp.mkdir(parents=True)
    claude_json = (src / ".claude.json" if env_dir
                   else Path.home() / ".claude.json")
    if not (tmp / ".claude.json").exists() and claude_json.is_file():
        shutil.copy2(claude_json, tmp / ".claude.json")
    (tmp / _CLAUDE_CONFIG_TEMPLATE_MARK).write_text("")
    # Read-only: its directories are shared by every worker's
    # configuration (`_worker_dirs`), so nothing may write into them.
    for d, _dirs, files in os.walk(tmp):
        for f in [d, *(os.path.join(d, n) for n in files)]:
            if not os.path.islink(f):
                os.chmod(f, stat.S_IMODE(os.lstat(f).st_mode) & ~0o222)
    _rmtree_owned(t)
    os.rename(tmp, t)
    return t


def _resumed_wid(run_dir: Path, session: str | None) -> str | None:
    """The `workers/<wid>` whose configuration holds `session`'s transcript,
    so a `--resume` runs where the CLI finds it; None when none does."""
    if not session:
        return None
    for hit in sorted((Path(run_dir) / WORKERS_DIR).glob(
            f"*/config/projects/*/{session}.jsonl")):
        return hit.parents[3].name
    return None


def _worker_tmp(base: Path) -> Path:
    """The worker's private temp directory, `/tmp/l/<id>/` (`<id>`: 16 hex
    digits of the hash of the realpath of its `<run_dir>/workers/<wid>/`),
    a pure function of the worker's directory, so whoever removes that
    directory can remove it too (DESIGN §6 *A confined command's scratch is
    short and private*): its length never depends on the run's id or the
    worker's name, so a socket in it fits `sun_path`."""
    key = os.path.realpath(base)
    return PRIVATE_TMP_ROOT / hashlib.sha256(key.encode()).hexdigest()[:16]


def _worker_dirs(run_dir: Path, sid: str, resume_session: str | None,
                 private_tmp: bool = True) -> tuple[Path, Path]:
    """`(config, tmp)` of the worker: `<run_dir>/workers/<wid>/`, `<wid>`
    the directories that hold the resumed session, else `sid`. `config` is
    made when absent (in a sibling and renamed, so a crash never leaves
    half of one): a writable copy of each of the run template's top-level
    files (the settings, credentials and account state a worker may
    rewrite) and a link to each of its directories (plugins, skills and the
    like, read-only and shared rather than copied per worker). `tmp` is
    made empty: the short private `_worker_tmp(<wid dir>)`, or with
    `private_tmp` False (the host-side seam, which is not confined and runs
    on the operator's host) `<wid dir>/tmp`."""
    wid = _resumed_wid(run_dir, resume_session) or sid
    base = Path(run_dir) / WORKERS_DIR / wid
    config = base / "config"
    if not config.is_dir():
        template = _claude_config_template(run_dir)
        part = base / f".config.tmp-{os.getpid()}"
        _rmtree_owned(part)
        _mkdir_private(part, Path(run_dir))
        for entry in template.iterdir():
            dst = part / entry.name
            if entry.name == _CLAUDE_CONFIG_TEMPLATE_MARK:
                continue
            if entry.is_symlink():
                os.symlink(os.readlink(entry), dst)
            elif entry.is_dir():
                os.symlink(entry, dst)
            else:
                shutil.copy2(entry, dst)
                os.chmod(dst, stat.S_IMODE(os.lstat(dst).st_mode) | 0o600)
        os.rename(part, config)
    if private_tmp:
        tmp = _worker_tmp(base)
        _rmtree_owned(tmp)
        _own_private_dir(PRIVATE_TMP_ROOT)
        _own_private_dir(tmp)
        # This process's until it exits, as `_private_tmp`'s are; a process
        # that hands it to another (`worker-guard.py`) gives it up.
        if not _PRIVATE_TMPS:
            atexit.register(_remove_private_tmps)
        _PRIVATE_TMPS[str(tmp)] = os.getpid()
    else:
        tmp = base / "tmp"
        _rmtree_owned(tmp)
        _mkdir_private(tmp, Path(run_dir))
    return config, tmp


def _confined_cli_env(run_dir: Path, sid: str,
                      resume_session: str | None = None,
                      private_tmp: bool = True) -> dict[str, str]:
    """The one builder of a confined CLI's own directories (DESIGN §6
    *Every confined CLI is given its own directories, by one builder*):
    `_worker_dirs`' pair, named by every `_WORKER_ENV_DIRS` variable, to
    lay over the spawn's environment before its grant is derived from it.
    Every one is named, not only those the caller happens to have set: an
    inherited value (the orchestrator's `<run-dir>/tmp/`) lies outside the
    grant, and the CLI's first act is to make `$TMPDIR/claude-<uid>`.
    `private_tmp` as `_worker_dirs`'."""
    config, tmp = _worker_dirs(Path(run_dir), sid, resume_session,
                               private_tmp)
    return {var: str(config if var == "CLAUDE_CONFIG_DIR" else tmp)
            for var in _WORKER_ENV_DIRS}


def _remove_worker_dirs(run_dir: Path) -> bool:
    """Remove every worker's directories and the template they were made
    from (they hold copies of the credentials). True when both are gone; a
    survivor is logged by name. Called by `_release_run_dir` at the exit of
    the process that owns the run, and by the reap and prune of a run no
    process owns."""
    gone = True
    # Each worker's private temp directory first: it is named by its
    # worker's directory, which goes next (`_worker_tmp`).
    with contextlib.suppress(OSError):
        for base in (Path(run_dir) / WORKERS_DIR).iterdir():
            if base.is_dir() and not base.is_symlink():
                _rmtree_owned(_worker_tmp(base))
    for name in (WORKERS_DIR, CLAUDE_CONFIG_TEMPLATE):
        path = Path(run_dir) / name
        if not _rmtree_owned(path):
            gone = False
            log(f"cleanup: could not remove {_operator_path(path)}; it may "
                "hold a copy of your credentials — remove it by hand")
    return gone


# What a run's process makes in the run directory for its own use and no
# later process reads: the measurement directories, the trees' own stores,
# the run's stores and the ref-less clones' git directories (DESIGN §6 *No
# copy of the credentials outlives its run's process*).
# realpath(run_dir) -> (the `State` that holds its lock, by weak reference,
# or None; the pid that registered it: a forked child that exits is not the
# run's process).
_OWNED_RUN_DIRS: dict[str, tuple[Callable[[], object] | None, int]] = {}


def _run_scratch_names() -> tuple[str, ...]:
    # The ref-less clones' git directories (`CLONE_GITS_NAME`) too: each
    # belongs to a disposable checkout a later process makes again.
    # The run's stores too: a resumed process installs again, cold, rather
    # than every finished run keeping a store until it is pruned (DESIGN §6
    # *The stores a view installs from are leerie's*).
    # A self-check's copies too: one outlives only a killed call.
    return (MEASURE_DIRNAME, f"worktrees/{STORES_HOME_NAME}",
            f"worktrees/{SELFCHECK_COPIES_NAME}", CLONE_GITS_NAME)


def _release_run_dir(run_dir: Path) -> bool:
    """Remove what the run's process made in `run_dir` for its own use: the
    workers' directories and the template (`_remove_worker_dirs`) and the
    run's scratch (`_run_scratch_names`). True when all are gone."""
    gone = _remove_worker_dirs(run_dir)
    # The measured trees' private temp directories go with their
    # measurement directories (DESIGN §6 *A confined command's scratch is
    # short and private*), whose sidecars name them.
    _remove_trees_private_tmps(Path(run_dir) / MEASURE_DIRNAME)
    for name in _run_scratch_names():
        path = Path(run_dir) / name
        if not _rmtree_owned(path):
            gone = False
            log(f"cleanup: could not remove {_operator_path(path)}")
    return gone


def _release_owned_run_dirs() -> None:
    """At this process's exit, whatever the exit — a return, `sys.exit`,
    `die`, an unhandled exception, an interrupt — release every run
    directory it registered (DESIGN §6 *No copy of the credentials outlives
    its run's process*), under the run's lock: the lock its `State` still
    holds, else the lock taken now. A run directory whose lock another
    process holds is that process's, and is left. Never raises: it runs at
    interpreter exit."""
    for d, (state, pid) in list(_OWNED_RUN_DIRS.items()):
        _OWNED_RUN_DIRS.pop(d, None)
        if pid != os.getpid():
            continue
        fd: int | None = None
        try:
            st = state() if state is not None else None
            if getattr(st, "_lock_fd", None) is None:
                fd = os.open(d, os.O_RDONLY)
                fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            _release_run_dir(Path(d))
        except (BlockingIOError, FileNotFoundError):
            pass
        except BaseException as e:  # at exit: report, never raise
            with contextlib.suppress(BaseException):
                log(f"cleanup: releasing {d} failed: {type(e).__name__}")
        finally:
            if fd is not None:
                with contextlib.suppress(OSError):
                    os.close(fd)


def _own_run_dir_until_exit(run_dir: Path, state: object = None) -> None:
    """Register `run_dir` for release at this process's exit
    (`_release_owned_run_dirs`), with the `State` that holds its lock when
    there is one. A later registration with a `State` replaces one
    without. Only the run's owner registers: a process that makes copies
    for another one to use (`scripts/worker-guard.py`, for the collection's
    integrator) leaves them to that one."""
    if not _OWNED_RUN_DIRS:
        atexit.unregister(_release_owned_run_dirs)
        atexit.register(_release_owned_run_dirs)
    key = os.path.realpath(run_dir)
    have = _OWNED_RUN_DIRS.get(key)
    if have is None or (state is not None and have[0] is None):
        _OWNED_RUN_DIRS[key] = (
            weakref.ref(state) if state is not None else None, os.getpid())


def _payload_only_cwd(st: object) -> str:
    """An empty run-private directory for a worker whose whole input is its
    payload (`PAYLOAD_ONLY_TOOLS`): never the user's checkout."""
    d = Path(getattr(st, "run_dir")) / "payload-only"
    d.mkdir(parents=True, exist_ok=True)
    return str(d)


def _exe_from_root(name: str) -> str:
    """`name` as PATH finds it from `/`, as an absolute path; `name` itself
    when it holds a `/` or PATH has no such program. A relative or empty
    PATH entry names a directory below the working directory, so it is
    anchored at `/`, never at the directory a host program would start in
    (DESIGN §6 *The host never runs a program the checkout chose*, part 4)."""
    if "/" in name:
        return name
    entries = os.environ.get("PATH", os.defpath).split(os.pathsep)
    found = shutil.which(name, path=os.pathsep.join(
        os.path.join("/", d) for d in entries))
    return os.path.abspath(found) if found else name


def _host_worker_cwd(*trees: str | Path) -> Path:
    """A fresh, empty, private directory for a host-side worker to start in
    (DESIGN §6 *The host never runs a program the checkout chose*, part 4):
    never a checkout or a tree, nor a directory in one, so no shim chooses
    its CLI and the CLI reads no project settings from them. The trees it
    works on are named to it by `--add-dir`. Raises OSError when the system
    temporary directory is one of `trees` or lies beneath one."""
    d = Path(tempfile.mkdtemp(prefix="leerie-host-cwd-"))
    real = Path(os.path.realpath(d))
    for t in trees:
        rt = Path(os.path.realpath(t))
        if real == rt or real.is_relative_to(rt):
            _rmtree_owned(d)
            raise OSError(errno.EINVAL,
                          f"the temporary directory {real} is inside {rt}")
    return d


def _judgment_cwd(st: "State") -> str:
    """The cwd every judgment worker runs in.

    Raises rather than falling back to the real checkout. `claude_p` also
    refuses a judgment worker whose cwd is the checkout, so a fallback here
    would only convert a clear failure into a confusing one two frames later.
    """
    path = st.data.get("planning_worktree")
    if path:
        return str(path)
    # Fall back to the conventional location rather than raising. The fallback
    # CANNOT violate the §12 guarantee: it is derived from the run directory,
    # so it is never the user's checkout, and `claude_p` independently refuses
    # any judgment worker whose cwd resolves to `st.repo_root`. The enforcement
    # therefore does not rest on this lookup, which makes raising here pure
    # diagnostics bought at the price of a precondition every caller that
    # constructs a `State` by hand must now know about — ~30 test files, none
    # of which spawn a real worker. If this fires in production the worker
    # spawns against a directory that does not exist and fails loudly at exec
    # time, which is the same signal one frame later.
    run_dir = getattr(st, "run_dir", None)
    if run_dir is None:
        raise RuntimeError(
            "cannot derive a judgment-worker cwd: state has neither "
            "`planning_worktree` nor `run_dir`")
    return str(Path(run_dir) / "worktrees"
               / _worktree_dirname(Path(run_dir).name, "planning"))


# =========================================================================
# deterministic enforcement — no LLM involvement
#
# Prompts are advisory; code enforces. Every rule that can be checked
# mechanically lives here, not in a prompt. The LLM handles: understanding
# intent, writing code, decomposing tasks, resolving semantic conflicts.
# Code handles: counting, hashing, graph invariants, file existence, running
# test suites, enforcing structural rules.
# =========================================================================

def _disk_free_ratio(path: Path) -> float:
    """Free-space fraction (0.0-1.0) of the filesystem holding `path`
    (N30). Uses `shutil.disk_usage`, which resolves to whatever
    filesystem `path` (or its nearest existing ancestor) actually lives
    on — the state-dir filesystem, at both call sites below."""
    p = path
    while not p.exists():
        p = p.parent
    usage = shutil.disk_usage(p)
    return usage.free / usage.total


def _disk_headroom_message(path: Path, ratio: float) -> str:
    p = path
    while not p.exists():
        p = p.parent
    usage = shutil.disk_usage(p)
    free_gb = usage.free / (1024 ** 3)
    total_gb = usage.total / (1024 ** 3)
    return (f"only {ratio:.1%} free ({free_gb:.1f} GB of {total_gb:.1f} GB) "
            f"on the filesystem holding {path} — below the "
            f"{DISK_MIN_FREE_RATIO:.0%} minimum")


async def _preflight_repo() -> None:
    """Repo-state checks that must run BEFORE any irreversible state exists.

    Split out of `preflight()` because of WHEN they run, not what they check.
    `main()` constructs `State(...)` -- which mints `<state-root>/runs/<run-id>/`,
    takes its flock and writes `state.json` -- and only then calls `_run_phases`,
    which calls `preflight()`. So a refusal here used to leave a permanent run
    directory behind for a run that never started: four of them accumulated on
    one host from a single afternoon's dirty-tree refusals
    (tests/test_irreversible_before_valid.py).

    These three need nothing but the checkout, so they run first and the run
    directory is only created once the repo is fit to run against. Everything
    else in `preflight()` (subprocess machinery, disk headroom, CLI version,
    the live smoke test) stays there.
    """
    # 1. git user identity — missing config causes implementer commits to fail
    for key in ("user.email", "user.name"):
        r = await run_proc(["git", "config", key])
        # rc=255 is asyncio's "could not read the child's exit status"
        # sentinel, not git's verdict — git exits 0 (set) or 1 (unset), never
        # 255. Without this branch the check below misreports a broken
        # subprocess as a misconfigured identity and sends the operator to
        # "fix" a git config that is already correct.
        #
        # Deliberately does NOT also require empty stdout: `git config <key>`
        # succeeds and *prints the value*, and `communicate()` drains the pipe
        # before the status is lost — so the real failure carries rc=255 WITH
        # output. An earlier `and not r.stdout` conjunct here never fired and
        # let this fall through to the "not configured" die() below.
        if r.returncode == 255:
            die(f"cannot read the exit status of `git config {key}` "
                "(rc=255) — the child process was reaped before its status "
                "could be read. This is NOT a git configuration problem; the "
                "subprocess machinery is broken. Most likely a stray reaper "
                "`waitpid`ing asyncio's children (DESIGN §6 *Zombie "
                "reaping*), or an inherited SIGCHLD disposition.")
        if r.returncode != 0 or not r.stdout.strip():
            die(f"git {key} is not configured. "
                f"Run: git config --global {key} \"<value>\"")

    # 2. working tree must be clean — a dirty tree produces ambiguous diffs
    r = await run_proc(["git", "--no-optional-locks", "status", "--porcelain",
                        "--untracked-files=no"])
    dirty = [l for l in r.stdout.splitlines() if not l.startswith("??")]
    if dirty:
        # Name them. "2 modified/staged file(s)" sends the operator to
        # `git status` to find out what leerie is objecting to, and in the
        # measured case both files were leerie's OWN tracked config
        # (`leerie.toml`, `.leerie/config.toml`) — so tuning leerie dirtied the
        # tree leerie then refused to run in, with nothing in the message
        # connecting the two (tests/test_irreversible_before_valid.py).
        _shown = [l[3:] for l in dirty[:10]]
        _own = [f for f in _shown
                if f == "leerie.toml" or f.startswith(".leerie/")]
        die(f"working tree has {len(dirty)} modified/staged file(s). "
            "Commit or stash before running leerie.\n  "
            + "\n  ".join(_shown)
            + ("" if len(dirty) <= 10 else
               f"\n  … and {len(dirty) - 10} more")
            + ("\n(" + ", ".join(_own) + " belong to leerie itself — editing "
               "leerie's own config dirties the tree it refuses to run in.)"
               if _own else ""))

    # 3. external 'leerie' branch — a bare branch named 'leerie' occupies
    #    the ref path that leerie's namespaced branches (leerie/runs/*,
    #    leerie/subtasks/*) need as a directory in git's loose ref store.
    r = await run_proc(["git", "show-ref", "--verify", "--quiet",
                        "refs/heads/leerie"])
    if r.returncode == 0:
        die("a branch named 'leerie' exists in this repository. "
            "This conflicts with leerie's internal branch namespace "
            "(leerie/runs/*, leerie/subtasks/*) — git cannot create "
            "branches under 'leerie/' while 'leerie' exists as a branch.\n"
            "Rename or delete it:\n"
            "  git branch -m leerie leerie-old    # rename (preserves commits)\n"
            "  git branch -D leerie               # delete (if fully merged)")


# --- Reaping idle runs' worktrees (DESIGN §6 *Idle runs' worktrees are
# reaped at preflight*) ------------------------------------------------------

# A run nobody has touched for this long is not about to resume; its
# worktrees are rebuilt from its branches if it ever does.
WORKTREE_REAP_IDLE_DAYS = 7
# Files whose mtime says a run is still being worked (besides its directory,
# `logs/` and `worktrees/` entries).
_RUN_ACTIVITY_FILES = ("state.json", "run.json", "orchestrator.log",
                       "calls.ndjson", "memory.ndjson",
                       "orchestrator.exit_code")
_REAP_TRASH_PREFIX = ".worktrees.reap-"


def _run_last_activity(run_dir: Path) -> float:
    ts = [run_dir.stat().st_mtime]
    for f in _RUN_ACTIVITY_FILES:
        with contextlib.suppress(OSError):
            ts.append((run_dir / f).stat().st_mtime)
    for p in (run_dir / "logs", _transcripts_dir(run_dir / "logs"),
              run_dir / "worktrees"):
        with contextlib.suppress(OSError):
            ts.append(p.stat().st_mtime)
            with os.scandir(p) as it:
                for e in it:
                    with contextlib.suppress(OSError):
                        ts.append(e.stat(follow_symlinks=False).st_mtime)
    return max(ts)


def _tree_bytes(root: Path) -> int:
    """Bytes under `root`, each inode once (pnpm hard-links one file into
    many worktrees), symlinks not followed."""
    seen: set[tuple[int, int]] = set()
    total = 0
    for dirpath, _dirs, files in os.walk(root):
        for f in files:
            try:
                st_ = os.lstat(os.path.join(dirpath, f))
            except OSError:
                continue
            key = (st_.st_dev, st_.st_ino)
            if key in seen:
                continue
            seen.add(key)
            total += st_.st_size
    return total


def _reap_idle_worktrees(runs_dir: Path, self_id: str,
                         idle_days: float = WORKTREE_REAP_IDLE_DAYS,
                         now: float | None = None) -> dict:
    """Delete `<run>/worktrees/` of every run that is neither this one, nor
    live, nor touched within `idle_days`, and its workers' directories and
    configuration template (copies of the credentials: DESIGN §6 *No copy
    of the credentials outlives its run's process*). State, logs and
    branches stay, so the run can still resume (its scripts rebuild every
    worktree from its branches, and its first worker makes the template
    again; uncommitted edits are lost, as on any abnormal exit).

    The directory is renamed to `<run>/.worktrees.reap-<pid>` while holding
    the run's flock, then deleted after releasing it: a resume taking the
    lock a moment later never sees a half-deleted tree. A run whose flock
    cannot be taken is live and skipped (fail closed). Leftover
    `.worktrees.reap-*` from an interrupted reap are deleted too. Every
    removal is owner-aware and checked (`_rmtree_owned`). Never raises;
    errors are counted in the report."""
    cutoff = (time.time() if now is None else now) - idle_days * 86400
    report: dict = {"reaped": [], "skipped_live": [], "skipped_recent": [],
                    "bytes": 0, "errors": 0}
    try:
        entries = sorted(runs_dir.iterdir())
    except OSError:
        return report
    for d in entries:
        try:
            if not d.is_dir() or d.is_symlink() or d.name == self_id:
                continue
            for trash in d.glob(_REAP_TRASH_PREFIX + "*"):
                if trash.is_dir() and not trash.is_symlink():
                    report["bytes"] += _tree_bytes(trash)
                    if not _rmtree_owned(trash):
                        report["errors"] += 1
            wt = d / "worktrees"
            has_wt = (wt.is_dir() and not wt.is_symlink()
                      and any(wt.iterdir()))
            has_creds = any(os.path.lexists(d / n) for n in
                            (WORKERS_DIR, CLAUDE_CONFIG_TEMPLATE))
            if not has_wt and not has_creds:
                continue
            if _run_last_activity(d) >= cutoff:
                report["skipped_recent"].append(d.name)
                continue
            fd = os.open(str(d), os.O_RDONLY)
            trs: list[Path] = []
            trash = None
            try:
                try:
                    fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
                except OSError:
                    report["skipped_live"].append(d.name)
                    continue
                # Each tree repository's branch taken into the run's own
                # repository first (DESIGN §6 *A repository per committing
                # tree (I6)*): a run that died mid-worker may hold work only
                # there. One that cannot be taken keeps the run as it is.
                trs = sorted(p for p in (d / TREE_REPOS_NAME).glob("*")
                             if (p / "HEAD").is_file())
                try:
                    for tr in trs:
                        _take_tree_repo(tr)
                except (RunRepoError, subprocess.TimeoutExpired):
                    report["errors"] += 1
                    continue
                if has_wt:
                    trash = d / f"{_REAP_TRASH_PREFIX}{os.getpid()}"
                    os.rename(wt, trash)
                if not _remove_worker_dirs(d):
                    report["errors"] += 1
            finally:
                os.close(fd)
            for gone in ([trash] if trash is not None else []) + trs:
                report["bytes"] += _tree_bytes(gone)
                if not _rmtree_owned(gone):
                    report["errors"] += 1
            # The deleted worktrees' admin entries in the shared `.git`,
            # scoped to this run directory.
            _prune_leerie_worktrees(d)
            report["reaped"].append(d.name)
        except OSError:
            report["errors"] += 1
    return report


# A launcher's own logs in the state root, by name (the launcher's
# `leerie-$$.log` default and its piped `.runlog-$$`): mechanical file names.
_LAUNCHER_LOG_RE = re.compile(r"(?:leerie-\d+\.log|\.runlog-\d+)")


def _reap_launcher_logs(state_root: Path,
                        idle_days: float = WORKTREE_REAP_IDLE_DAYS,
                        now: float | None = None) -> dict:
    """Remove the launchers' logs (`logs/leerie-<pid>.log`, `.runlog-<pid>`)
    not written for `idle_days` (DESIGN §6 *A launcher's logs go with the
    same retention*): a copy of a run's own `orchestrator.log`, which a
    live launcher appends to whenever its run prints. Regular files only,
    never through a link. `{removed, bytes, errors}`; never raises."""
    cutoff = (time.time() if now is None else now) - idle_days * 86400
    report = {"removed": 0, "bytes": 0, "errors": 0}
    for d in (state_root / "logs", state_root):
        try:
            entries = list(os.scandir(d))
        except OSError:
            continue
        for e in entries:
            if not _LAUNCHER_LOG_RE.fullmatch(e.name):
                continue
            try:
                st_ = e.stat(follow_symlinks=False)
                if not stat.S_ISREG(st_.st_mode) or st_.st_mtime >= cutoff:
                    continue
                os.unlink(e.path)
                report["removed"] += 1
                report["bytes"] += st_.st_size
            except OSError:
                report["errors"] += 1
    return report


async def preflight(leerie_dir: Path, verbosity: str = VERBOSITY_DEFAULT,
                    skip_smoke: bool = False, no_push: bool = False,
                    model: str = MODEL_DEFAULT) -> None:
    """Hard checks before any LLM work. Fails fast rather than wasting workers."""

    # 0. subprocess machinery must be able to report exit statuses at all.
    # Under SIGCHLD=SIG_IGN the kernel auto-reaps our children, so every
    # asyncio result is rc=255/empty — indistinguishable from a genuinely
    # failed command, which makes every check below report a false negative.
    # main() resets the disposition; this gate catches one set afterwards.
    if _sigchld_is_ignored():
        die("SIGCHLD is set to SIG_IGN, so the kernel auto-reaps this "
            "process's children and their exit statuses are unreadable. "
            "Every subprocess would report a bogus failure. This is an "
            "environment problem, not a leerie configuration problem.")

    # Landlock and the held-out sandbox are not checked here: `main()` has
    # already run `_require_confinement` for every invocation that can start
    # a confined process, a resumed one included (DESIGN §6 *Fail closed, on
    # every entry*).

    # 0.4. reap idle runs' worktrees (DESIGN §6 *Idle runs' worktrees are
    # reaped at preflight*), before the headroom check reads free space.
    # Nothing else reaps them: a paused or died run keeps a full checkout
    # plus node_modules per subtask for as long as its directory exists.
    try:
        reap = await asyncio.to_thread(
            _reap_idle_worktrees, leerie_dir.parent, leerie_dir.name)
        if reap["reaped"] or reap["bytes"]:
            log(f"preflight: reaped the worktrees of {len(reap['reaped'])} "
                f"run(s) idle >= {WORKTREE_REAP_IDLE_DAYS}d, freed "
                f"{reap['bytes'] / 1048576:.1f} MiB (skipped "
                f"{len(reap['skipped_live'])} live, "
                f"{len(reap['skipped_recent'])} recent"
                + (f"; {reap['errors']} delete error(s)"
                   if reap["errors"] else "") + ")")
    except Exception as e:  # housekeeping must never stop a run
        log(f"preflight: worktree reap skipped ({type(e).__name__}: {e})")
    # The launchers' logs, by the same idle bound (DESIGN §6 *A launcher's
    # logs go with the same retention*). Never raises.
    logs = await asyncio.to_thread(_reap_launcher_logs,
                                   leerie_dir.parent.parent)
    if logs["removed"] or logs["errors"]:
        log(f"preflight: removed {logs['removed']} launcher log(s) idle >= "
            f"{WORKTREE_REAP_IDLE_DAYS}d, freed "
            f"{logs['bytes'] / 1048576:.1f} MiB"
            + (f" ({logs['errors']} error(s))" if logs["errors"] else ""))

    # 0.5. disk headroom (N30) — a run writes state.json/logs/calls.ndjson/
    # worktrees continuously, and the first failing write under a full disk
    # was previously an unhandled `OSError: [Errno 28] No space left on
    # device` from whatever line happened to be writing. Checked on the
    # state-dir filesystem (leerie_dir is under <state-root>/runs/<id>)
    # before any worker spawns, so a disk that is already too full to
    # safely run refuses cleanly instead of dying mid-run.
    ratio = _disk_free_ratio(leerie_dir)
    if ratio < DISK_MIN_FREE_RATIO:
        die(f"insufficient disk space to start a run: "
            f"{_disk_headroom_message(leerie_dir, ratio)}. "
            "Free up space (`leerie prune` lists what old run state it "
            "would reclaim; `leerie prune --apply` deletes it) and retry.")

    # 4. claude CLI version is recent enough for `--json-schema` in -p mode.
    #    Runs even when --skip-smoke is set: --skip-smoke is for skipping the
    #    *live* model call (auth + a turn), not for skipping local CLI sanity
    #    checks. Without this, a stale CLI fails the smoke test with a cryptic
    #    'unknown option' that tells the user nothing actionable.
    _check_claude_cli_version()

    # 5. gh CLI preflight moved to the host launcher (DESIGN §6
    #    *Finalization*). The launcher checks `gh auth status` + origin
    #    remote presence before spinning up this container; if they
    #    fail, the container never starts.

    # 6. live smoke-test: auth + --output-format stream-json + --json-schema inline.
    #    Catches auth failures before a 40-worker run starts. Streams so a slow
    #    Opus / heavy-context startup is visible — the previous max_turns=1
    #    failure was invisible in the non-streaming mode until exit.
    if not skip_smoke:
        log("preflight: smoke-testing claude -p…")
        # Its own configuration and temp directories, as every confined
        # CLI's (DESIGN §6 *Every confined CLI is given its own
        # directories, by one builder*): the orchestrator's own `TMPDIR`
        # (`_use_run_tmp`) is outside its grant, and the CLI stops at
        # start when it cannot make `$TMPDIR/claude-<uid>`.
        smoke_env = _confined_cli_env(leerie_dir, "smoke")
        cmd = _contained_claude_argv(
            schema=SMOKE_SCHEMA, allowed_tools=SMOKE_TOOLS,
            max_turns=SMOKE_MAX_TURNS, model=model, prompt=SMOKE_PROMPT,
            # Confined below, so its settings are a confined worker's,
            # from the run's template its configuration was made from.
            settings=_confined_cli_settings(None, run_dir=leerie_dir,
                                            repo_root=None),
            settings_only=True)
        # An EMPTY cwd, not the repo. This validates the CLI, not the
        # repository, and a single-exchange `claude -p` conversation is the
        # one shape the CLI's own recovery path cannot rescue: when its
        # prompt crosses the reactive-compaction trigger it tries to compact,
        # finds fewer than two message groups, fails `too_few_groups`, and
        # refuses the turn itself with a synthetic "Prompt is too long" and
        # no API call. Workers compact fine because they are multi-turn.
        # Measured on this repo with one argv held constant: the repo cwd
        # costs ~108,800 tokens of CLAUDE.md/skills/commands the smoke test
        # never reads (126,022 in the repo vs 17,222 in an empty dir), and
        # CLAUDE.md only grows — so staying an order of magnitude below the
        # trigger has to be structural, not a margin someone re-tunes later.
        # Auth resolves from ~/.claude/.credentials.json /
        # CLAUDE_CODE_OAUTH_TOKEN rather than cwd, so nothing about the
        # credential path changes.
        #
        # Two constraints, and they pull in different directions.
        #
        # OUTSIDE ANY REPOSITORY. Claude Code resolves project context by
        # walking UP from cwd to the project root, so what matters is not that
        # the directory is empty but that it has no repo ancestor. A path
        # under the state root looks safe and is not: `resolve_leerie_root`
        # falls back to `<repo>/.leerie` whenever LEERIE_STATE_DIR is unset
        # (the direct-Python path its own docstring describes), which would
        # put the cwd back inside the checkout and reload the very CLAUDE.md
        # this exists to escape — silently, since the directory would still
        # be empty and still differ from os.getcwd().
        #
        # STABLE ACROSS RUNS. The CLI keys its session store on cwd
        # (~/.claude/projects/<encoded-cwd>/) and deleting the cwd does not
        # remove that entry, so a fresh mkdtemp per run leaves one orphan per
        # run. Harmless on the local runtime (the container's ~/.claude is a
        # bind mount of the launcher's per-run $STAGE, wiped by its EXIT trap)
        # but not on a --runtime fly/ec2 machine, which persists across runs.
        #
        # The system temp dir satisfies the first; keying the name on the
        # state root satisfies the second while keeping two repos, and the
        # test suite, on separate paths.
        import tempfile  # noqa: PLC0415
        smoke_cwd = str(
            Path(_system_temp_dir())
            / ("leerie-smoke-" + hashlib.sha256(
                str(leerie_dir.parent.parent).encode()).hexdigest()[:12]))
        try:
            os.makedirs(smoke_cwd, mode=0o700, exist_ok=True)
        except OSError as e:
            die(f"cannot create the smoke-test working directory "
                f"{smoke_cwd}: {e}")
        # The name is deterministic and the parent is world-writable, and
        # `exist_ok=True` accepts whatever is already there — including a
        # symlink someone else planted. A symlink into a checkout would put
        # the cwd back inside a repository and silently reload the CLAUDE.md
        # this whole mechanism exists to escape, which is the same
        # fails-quietly shape the comment above rejects the state root for.
        # So verify what we actually got rather than trusting the name.
        if os.path.realpath(smoke_cwd) != smoke_cwd:
            die(f"the smoke-test working directory {smoke_cwd} is a symlink "
                f"(to {os.path.realpath(smoke_cwd)}); refusing to run the "
                "smoke test in it. Remove it and re-run.")
        try:
            envelope = await _invoke(cmd, cwd=smoke_cwd, timeout=90,
                                     sid="smoke",
                                     leerie_dir=leerie_dir,
                                     verbosity=verbosity,
                                     env_extra=smoke_env,
                                     grants=_worker_grants(
                                         run_dir=leerie_dir, state={},
                                         schema_key="smoke", cwd=smoke_cwd,
                                         allowed_tools=SMOKE_TOOLS,
                                         env={**os.environ, **smoke_env}))
        except subprocess.TimeoutExpired:
            die("claude -p smoke test timed out — auth issue or network problem")
        except WorkerError as e:
            die(f"claude -p smoke test failed: {e}")
        finally:
            _rmtree_owned(Path(smoke_env["TMPDIR"]))
        # No cleanup: the directory is empty by construction (SMOKE_TOOLS
        # allows only Read, and four real probe runs left theirs empty), and
        # two runs sharing one state root share this path — an rmtree here
        # would unlink a concurrent run's live cwd, which surfaces as a
        # spurious smoke-test failure diagnosed as an auth or network problem.
        #
        # Classify BEFORE the generic arm. A client-side context refusal
        # carries api_error_status=None, so it would otherwise print as the
        # bare string "Prompt is too long" — the wording CLAUDE.md records
        # costing three successive misdiagnoses on 2026-08-06. ContextOverflow
        # names the remedy and routes to a resumable EXIT_LOCKED pause —
        # state.json already holds a valid task at this point, so the run is
        # recoverable rather than lost. (`resume` does NOT skip preflight for
        # this shape: a run that dies here has no waves/categories, which is
        # the demotion predicate in _run_phases, so it restarts from its
        # recorded task and re-runs the smoke test. That is the right
        # behaviour once the operator has dropped the offending flag.)
        if _is_context_overflow(envelope):
            raise ContextOverflow(str(envelope.get("result") or ""),
                                  from_worker=False)
        if envelope.get("is_error"):
            die(f"claude -p smoke test returned an error: "
                f"{envelope.get('api_error_status') or envelope.get('result')} "
                f"(terminal_reason={envelope.get('terminal_reason')!r}); "
                f"full stream: {leerie_dir / 'logs' / 'smoke.log'}")
        log("preflight: ok")


_ID_PREFIXES = frozenset(f"{v}-" for v in CATEGORY_ABBREV.values())


_VALID_EXTENTS = frozenset({"in_plan", "external"})


# ---- Mechanical-check functions (CRITIC-pattern feedback) -------------- #
# Each returns a list[str] of issue descriptions.  Empty = clean.
# Pure Python, no LLM — the orchestrator injects these as external
# feedback on re-invocation.  See _run_checked_loop.


# What counts as evidence that a category's subject matter lives in this repo,
# used by `CATEGORY_NO_DIR`. Measured origin: across 468 recorded runs the
# advisory fired 27 times, every one of them for `infrastructure` on a repo
# that is a conventional CDK project — `cdk.json` at the root and stacks under
# `src/infrastructure/`. The previous rule tested only for DIRECTORIES NAMED
# infra/cdk/terraform/pulumi AT THE ROOT, which that layout satisfies neither
# way, so the advisory was wrong 27 times out of 27. It never changed a
# classification (the classifier held `infrastructure` in all 13 runs where it
# could have folded), but it gates — `CATEGORY_NO_DIR` is absent from
# `_ADVISORY_ISSUE_LABELS` — so each firing cost a re-classify round: within
# that one repo, 4.36 mean classifier calls when it fired against 1.39 when it
# did not.
#
# Three kinds of evidence, because a repo may carry any one of them:
#   `dirs`   directory names, matched case-insensitively at the root AND one
#            level down (`src/infrastructure/`);
#   `files`  root file names, matched case-insensitively by stem, so `README`,
#            `readme.md` and `Readme.rst` all count;
#   `globs`  root patterns for ecosystems that use a file extension rather
#            than a directory (`*.tf`).
#
# `fly.toml` and `Dockerfile` are deliberately absent: adding them would
# satisfy `infrastructure` for this very repo, and leerie's own 3 firings are
# correct — it has no infrastructure-as-code.
CATEGORY_EVIDENCE: dict[str, dict[str, list[str]]] = {
    "infrastructure": {
        "dirs": ["infra", "infrastructure", "cdk", "terraform", "pulumi"],
        "files": ["cdk.json", "pulumi.yaml", "serverless.yml",
                  "template.yaml"],
        "globs": ["*.tf", "*.bicep"],
    },
    "documentation": {
        "dirs": ["docs", "doc"],
        "files": ["readme", "changelog"],
        "globs": [],
    },
}


def _category_evidence_found(repo_root: Path, cat: str) -> bool:
    """Whether `repo_root` carries any evidence for `cat` (CATEGORY_EVIDENCE).

    Case-insensitive throughout: a rule keyed to `README` but not `readme`
    flags a correct classification, and `judge_confirmed` is empty on the
    initial `phase_classify`, so suppression cannot cover that — the signal
    itself has to be right on the first call."""
    spec = CATEGORY_EVIDENCE.get(cat)
    if not spec:
        return True
    # `.get` on every key, matching `_category_evidence_summary`. The two read
    # the same table and must tolerate the same entries: a category added with
    # only `dirs` used to raise KeyError here while the summary returned fine,
    # so a maintainer sanity-checking the message saw it work. This runs
    # inside a gating check, and KeyError is not WorkerError, so
    # `_run_checked_loop` abandons rather than retrying — it takes the run
    # down.
    wanted_dirs = set(spec.get("dirs", []))
    wanted_files = spec.get("files", [])
    try:
        # `os.scandir` rather than `iterdir()` + `is_dir()`: it carries the
        # entry type from the directory read, so it costs one syscall instead
        # of one `stat` per child. Measured on a repo with a 40k-file
        # directory one level down, 693 ms → 23 ms. No repo in the run corpus
        # has that shape — the real trees cost 2-27 ms either way — so this is
        # insurance against `data/`-style layouts, not a fix for an observed
        # slowdown. Semantics are unchanged; the direct `(child / name)` probe
        # is faster still but drops case-insensitivity one level down, which
        # is the defect this predicate exists to remove.
        with os.scandir(repo_root) as entries:
            for entry in entries:
                name = entry.name.lower()
                if entry.is_dir(follow_symlinks=False):
                    if name in wanted_dirs:
                        return True
                    # One level down, for `src/infrastructure/`-style
                    # layouts. Skipped for dot-dirs and vendored trees, where
                    # a coincidental match says nothing about what this repo
                    # authors.
                    if (name.startswith(".")
                            or name in ("node_modules", "vendor")):
                        continue
                    try:
                        with os.scandir(entry.path) as children:
                            for child in children:
                                if (child.is_dir(follow_symlinks=False)
                                        and child.name.lower() in wanted_dirs):
                                    return True
                    except OSError:
                        continue
                elif any(name == f or name.startswith(f + ".")
                         for f in wanted_files):
                    return True
    except OSError:
        # An unreadable or absent repo root is not evidence of absence.
        return True
    return any(_glob_beneath(repo_root, pat) for pat in spec.get("globs", []))


def _category_evidence_summary(cat: str) -> str:
    """Human-readable list of what would satisfy `cat`, for the advisory text.

    Derived from `CATEGORY_EVIDENCE` rather than written out, so the message
    cannot drift from the rule it describes — the previous text named only the
    directories and so misreported the remedy on every one of the 27 recorded
    firings."""
    spec = CATEGORY_EVIDENCE.get(cat, {})
    parts = [f"{'/'.join(spec.get('dirs', []))} as a directory at the root or "
             "one level down"]
    if spec.get("files"):
        parts.append(f"{'/'.join(spec['files'])} at the root")
    if spec.get("globs"):
        parts.append(f"{'/'.join(spec['globs'])} at the root")
    return "; ".join(parts)


def check_classifier_output(
        result: dict, repo_root: Path,
        judge_confirmed: frozenset[str] = frozenset()) -> list[str]:
    """Thin mechanical checks on the classifier's category selection.

    `judge_confirmed` (default empty — no behavior change for the first
    classify call or any caller other than `phase_classification_gate`'s
    re-classify loop): categories the independent `classification_judge`
    has already vetted as required for this task, across every round of
    the current gate call (see `phase_classification_gate`'s
    accumulation), minus any the judge has since retracted with an
    evidenced `spurious_category`. Three advisories yield to it, under two
    different rules, because the independent judge is the authoritative
    signal (DESIGN §8) and re-flagging what it has vetted undoes its
    finding on the very next re-classify round — the tug-of-war that let a
    3-category task (bug-fixing + feature-implementation + testing)
    oscillate indefinitely without ever holding all three at once:

    - `SAME_WORK_RISK` / `TEST_OWNERSHIP_RISK` flag a PAIR, so they yield
      only when BOTH categories are judge-confirmed.
    - `CATEGORY_NO_DIR` flags ONE category, so it yields on that category
      alone."""
    issues: list[str] = []
    cats = result.get("categories", [])

    for cat in CATEGORY_EVIDENCE:
        # Yields to the independent judge for the same reason the two RISK
        # advisories below do: `phase_classification_gate` re-invokes this
        # whole function on every re-classify round, so an unconditional
        # advisory strips a category the judge just confirmed and the two
        # pull against each other until the budget runs out (DESIGN §8).
        if (cat in cats and cat not in judge_confirmed
                and not _category_evidence_found(repo_root, cat)):
            issues.append(
                f"CATEGORY_NO_DIR: classified as {cat!r} but this repo "
                f"carries none of: {_category_evidence_summary(cat)}")

    for q in result.get("questions", []):
        if not (q.get("why_underivable") or "").strip():
            issues.append(
                f"EMPTY_WHY: question {q.get('id', '?')!r} has "
                "empty why_underivable")

    prescribed = result.get("prescribed_procedure") or {}
    if prescribed.get("is_prescribed") and not (
            prescribed.get("evidence") or "").strip():
        issues.append(
            "EMPTY_EVIDENCE: prescribed_procedure.is_prescribed is true "
            "but evidence is empty")

    if result.get("likely_already_satisfied") and not (
            result.get("likely_already_satisfied_evidence") or "").strip():
        issues.append(
            "EMPTY_EVIDENCE: likely_already_satisfied is true but "
            "likely_already_satisfied_evidence is empty")

    if len(cats) > 4:
        issues.append(
            f"MANY_CATEGORIES: {len(cats)} categories — typical "
            "tasks span 1–3")
    _SAME_WORK_RISK_PAIRS = [
        ("bug-fixing", "feature-implementation"),
        ("bug-fixing", "refactoring"),
        ("feature-implementation", "refactoring"),
    ]
    cats_set = set(cats)
    for a, b in _SAME_WORK_RISK_PAIRS:
        if a in cats_set and b in cats_set and not (
                a in judge_confirmed and b in judge_confirmed):
            issues.append(
                f"SAME_WORK_RISK: {a!r} and {b!r} both selected — "
                "these categories often describe the same intent "
                "under different labels (e.g. 'complete translations' "
                "as both bug-fix and feature). Apply the same-work "
                "test: would planners in each category modify the same "
                "files for the same reason? If yes, keep only the "
                "best-fitting category. If they produce genuinely "
                "different deliverables, keep both."
            )
    # A distinct risk from the same-intent overlaps above: a code category
    # (bug-fixing / feature-implementation / refactoring) selected alongside
    # `testing` does NOT describe one intent under two labels — the
    # deliverables genuinely differ (a fix vs. its test). The collision is on
    # *test-file ownership*: the code planner and the testing planner, running
    # blind to each other, can both author or rewrite the SAME test file with
    # contradictory contracts, which the plan-overlap judge then correctly
    # refuses as unresolvable (the barnacle fake-timer incident). Advisory:
    # nudge the classifier to keep the source fix and the test assertions in
    # separate, non-overlapping file surfaces.
    _TEST_OWNERSHIP_RISK_CODE_CATS = (
        "bug-fixing", "feature-implementation", "refactoring")
    if "testing" in cats_set:
        for code_cat in _TEST_OWNERSHIP_RISK_CODE_CATS:
            if code_cat in cats_set and not (
                    code_cat in judge_confirmed and "testing" in judge_confirmed):
                issues.append(
                    f"TEST_OWNERSHIP_RISK: {code_cat!r} and 'testing' both "
                    "selected — the two planners run blind to each other and "
                    "can both author/rewrite the SAME test file with "
                    "incompatible contracts, which the plan-overlap judge "
                    "refuses as unresolvable (a real prior incident). Ensure "
                    "the code planner owns the source change and the testing "
                    "planner owns the assertions, on non-overlapping files."
                )
    # The classifier's `classification` self-score is NO LONGER a gating axis
    # (DESIGN §8 *Independent adversarial verification*): a worker grading its
    # own output cannot find its own blind spot, so the authoritative gate is
    # the independent `classification_judge` (phase_classification_gate). The
    # `confidence` object is still emitted and schema-required (the §8
    # falsifier/gap discipline record), just not read as a gate here.
    return issues


# ---------------------------------------------------------------------------
# Migration-surface completeness (DESIGN §5)
# ---------------------------------------------------------------------------

_MIGRATION_SURFACE_THRESHOLD = 5


def _grep_old_pattern(pattern: str, repo_root: Path) -> set[str]:
    """Grep *repo_root* for *pattern*, return set of relative file paths."""
    search_dir = repo_root / "src" if (repo_root / "src").is_dir() else repo_root
    try:
        cp = subprocess.run(
            ["grep", "-rl", "--include=*.ts", "--include=*.tsx",
             "--include=*.js", "--include=*.jsx", "--include=*.py",
             "--include=*.rb", "--include=*.go", "--include=*.java",
             "--include=*.rs", "--include=*.cs",
             pattern, str(search_dir)],
            capture_output=True, text=True, timeout=30,
        )
    except (subprocess.TimeoutExpired, FileNotFoundError):
        return set()
    files: set[str] = set()
    for line in cp.stdout.splitlines():
        line = line.strip()
        if line:
            try:
                files.add(str(Path(line).relative_to(repo_root)))
            except ValueError:
                files.add(line)
    return files


def _check_migration_surface(
    subtasks: list[dict], repo_root: Path,
) -> list[str]:
    """UNCOVERED_MIGRATION_SURFACE check (DESIGN §5)."""
    issues: list[str] = []
    all_touched: set[str] = set()
    for s in subtasks:
        all_touched.update(s.get("files_likely_touched") or [])

    for s in subtasks:
        sid = s.get("id", "?")
        # The planner declares what it replaces in `migration_targets`;
        # Python greps for a symbol it was HANDED, never one inferred from
        # the subtask's prose (CLAUDE.md *Language-to-JSON*).
        #
        # This used to regex `intent` + `investigation_notes` for phrases
        # like "replaces direct X". Because the pattern captured whatever
        # token followed the verb, it mined ordinary English out of
        # sentences that merely described replacement: measured on run
        # 19a70d96, all 27 extractions were stopwords — 'with' (grepping
        # to 332 files), 'both' (178), 'task' (168), 'when', 'that',
        # 'only', 'selection' — and not one was a real symbol. Every
        # resulting UNCOVERED_MIGRATION_SURFACE issue was false. The
        # failure mode is worst on exactly the tasks that talk about
        # replacing things.
        for target in s.get("migration_targets") or []:
            if not isinstance(target, dict):
                continue
            old_pattern = (target.get("old_pattern") or "").strip()
            if not old_pattern:
                continue
            # Whether `old_pattern` is a real, grep-pastable identifier is
            # the planner's own judgment call, self-attested in this
            # required field — never a shape Python infers by regexing the
            # LLM's response (CLAUDE.md *Language-to-JSON*). A missing/
            # falsy attestation is treated the same as an explicit `false`:
            # skip it, preserving the false-positive protection this field
            # replaced without trusting an absent value as consent.
            if not target.get("is_real_identifier"):
                continue
            grep_hits = _grep_old_pattern(old_pattern, repo_root)
            if not grep_hits:
                continue
            uncovered = grep_hits - all_touched
            if len(uncovered) > _MIGRATION_SURFACE_THRESHOLD:
                sample = sorted(uncovered)[:10]
                issues.append(
                    f"UNCOVERED_MIGRATION_SURFACE: {sid} introduces "
                    f"replacement for {old_pattern!r} but {len(uncovered)} "
                    f"of {len(grep_hits)} files containing the old pattern "
                    f"are not in any subtask's files_likely_touched. "
                    f"Uncovered sample: {sample}")
    return issues


def _check_migration_targets_declared(subtasks: list[dict]) -> list[str]:
    """MIGRATION_TARGETS_MISSING check.

    Same-worker, same-call mechanical contradiction check: a subtask that
    self-reports `performs_replacement: true` but declares no
    `migration_targets` gives `_check_migration_surface` nothing to grep
    for, so a real migration silently produces zero
    UNCOVERED_MIGRATION_SURFACE signal. This closes the "planner forgot to
    fill the optional field" case.

    It is NOT an independent witness (unlike `task_coverage_judge` or the
    other adversarial-verifier gates DESIGN §8 documents) — both signals
    are self-reported by the same planner call, so a planner that is wrong
    on `performs_replacement` and `migration_targets` in the same
    direction (false + omitted, for a subtask that truly replaces
    something) defeats this check too. It only catches the inconsistent
    case, not the consistently-wrong one.
    """
    issues: list[str] = []
    for s in subtasks:
        if not s.get("performs_replacement"):
            continue
        targets = s.get("migration_targets") or []
        if targets:
            continue
        sid = s.get("id", "?")
        issues.append(
            f"MIGRATION_TARGETS_MISSING: {sid} declares "
            "performs_replacement=true but names no migration_targets — "
            "UNCOVERED_MIGRATION_SURFACE has nothing to check coverage "
            "against for this subtask's replacement")
    return issues


# ---------------------------------------------------------------------------
# P1 recursive decomposition (DESIGN §5½ (P1))
# ---------------------------------------------------------------------------

def _partition_files(files: list[str], chunk_size: int) -> list[list[str]]:
    """Partition *files* into non-overlapping chunks of at most *chunk_size*.

    100% coverage + 0 overlap guaranteed by construction: every element of
    *files* appears in exactly one chunk, and no element appears in more than
    one chunk. The last chunk may be smaller than *chunk_size*.

    Used by _recursive_decompose() for migration sweeps — the exhaustive file
    list comes from P6 / _grep_old_pattern; the splitter LLM only labels the
    pre-computed chunks rather than deciding which files go where (the
    measured LLM-drops-14/29 correction from F1-build-measure.md)."""
    if not files or chunk_size < 1:
        return [list(files)] if files else []
    chunks: list[list[str]] = []
    for i in range(0, len(files), chunk_size):
        chunks.append(files[i: i + chunk_size])
    return chunks


def _partition_lines(lo: int, hi: int, max_span: int) -> list[tuple[int, int]]:
    """Tile the inclusive line range ``[lo, hi]`` into contiguous windows of at
    most *max_span* lines each (DESIGN §5½ (P1) *Sub-file* — tier 2).

    100% coverage + 0 overlap by construction (the ``_partition_files`` guarantee
    on line numbers instead of files): every line in ``[lo, hi]`` falls in exactly
    one window, the last window may be shorter. Used to sub-split a single
    function whose span alone exceeds the cap (function boundaries can't break it)
    and as the whole-file fallback when tree-sitter yields no symbol ranges.
    Degenerate guards mirror ``_partition_files``: an empty range (``hi < lo``)
    returns ``[]``; ``max_span < 1`` returns the whole range as one window."""
    if hi < lo:
        return []
    if max_span < 1:
        return [(lo, hi)]
    windows: list[tuple[int, int]] = []
    start = lo
    while start <= hi:
        windows.append((start, min(start + max_span - 1, hi)))
        start += max_span
    return windows


def _partition_symbols_by_line(
    ranges: list[tuple[str, int, int]], total_lines: int, max_span: int,
) -> list[tuple[int, int]]:
    """Tile ``[1, total_lines]`` into contiguous regions on function boundaries
    (DESIGN §5½ (P1) *Sub-file* — tier 1).

    *ranges* is ``_extract_symbol_ranges``' output: ``(name, start, end)`` for the
    file's top-level symbols, sorted by start line. Regions are built so that:

    - the union is exactly ``[1, total_lines]`` with no gaps or overlap — an
      inter-symbol gap (blank lines, imports, a comment block) attaches to the
      *preceding* region, and the final region extends to ``total_lines``, so the
      tiling stays exhaustive by construction (the ``_partition_files`` guarantee);
    - a region grows by absorbing whole adjacent symbols until adding the next
      would push it past *max_span*, then a new region starts;
    - a **single symbol whose own span exceeds *max_span*** still becomes its own
      region rather than being force-merged — function boundaries cannot break it,
      so it is handed back oversized on purpose. ``_recursive_decompose`` re-enters
      that region and tier 2 (``_partition_lines``) sub-splits it. This is the
      1,733-line-function case (run 5d488583).

    Returns ``[(1, total_lines)]`` when there are no usable ranges — the caller
    then falls back to tier-2 line-windows over the whole file."""
    if total_lines < 1:
        return []
    usable = [r for r in ranges if 1 <= r[1] <= r[2] <= total_lines]
    if not usable:
        return [(1, total_lines)]

    regions: list[tuple[int, int]] = []
    cur_start = 1
    cur_end = 0  # exclusive-of-nothing sentinel; first symbol sets the real end
    for _name, _s, e in usable:
        if cur_end == 0:
            # First symbol: region opened at line 1 absorbs any leading gap.
            cur_end = e
            continue
        # Would absorbing this symbol keep the region within the cap? The region
        # spans cur_start..e if we absorb. A region already at/over the cap, or
        # one that would exceed it, closes first — unless it holds a single
        # oversized symbol, which we intentionally let stand alone (handled by
        # the close-then-open below producing a >max_span region for tier 2).
        if (e - cur_start + 1) > max_span and (cur_end - cur_start + 1) > 0:
            regions.append((cur_start, cur_end))
            cur_start = cur_end + 1
        cur_end = e
    # Final region extends to EOF so the union is exhaustive.
    regions.append((cur_start, total_lines))
    return regions


def _check_intra_file_surface(
    regions: list[tuple[int, int]], total_lines: int,
) -> list[str]:
    """Zero-tolerance coverage/overlap backstop for an intra-file partition
    (DESIGN §5½ (P1) *Sub-file*) — the analog of ``_check_migration_surface``.

    Returns a list of issue strings (empty when the partition is exact). The
    tiling helpers guarantee this by construction, so a non-empty result means a
    real bug in the partitioner, not a tolerable slack — unlike the file-level
    check's slack of 5, this demands the region union equal ``[1, total_lines]``
    exactly and be pairwise-disjoint."""
    issues: list[str] = []
    if total_lines < 1:
        return issues
    covered: set[int] = set()
    overlaps = 0
    for lo, hi in regions:
        for ln in range(lo, hi + 1):
            if ln in covered:
                overlaps += 1
            covered.add(ln)
    expected = set(range(1, total_lines + 1))
    missing = expected - covered
    extra = covered - expected
    if missing:
        issues.append(
            f"INTRA_FILE_UNCOVERED: {len(missing)} line(s) not owned by any "
            f"region (e.g. {sorted(missing)[:10]})")
    if extra:
        issues.append(
            f"INTRA_FILE_OUT_OF_RANGE: {len(extra)} region line(s) outside "
            f"[1, {total_lines}] (e.g. {sorted(extra)[:10]})")
    if overlaps:
        issues.append(
            f"INTRA_FILE_OVERLAP: {overlaps} line(s) owned by more than one "
            "region")
    return issues


# Sentinel introducing the new-file-ownership clause in a child's
# `success_criteria_seed`. Load-bearing for RE-ENTRY: a child's criteria is built
# by appending to its parent's, and a re-split child's parent criteria already
# carries a clause. Without replacing it, a non-owner's child receives its
# parent's "create no new files" AND its own "you are the owner" — directly
# contradictory, and it breaks the one-owner invariant across the tree (measured:
# run 719c2a26 re-entered three times, at r8/r12/r14, so it would have produced
# four claimed owners instead of one).
#
# Splitting on this marker is string surgery on a string THIS MODULE generated,
# which is what makes it legitimate: CLAUDE.md *Language-to-JSON* bars reading
# meaning out of prose or a worker's response, not slicing our own mechanical
# output at a delimiter we emit. The neighbouring `Scope:` clauses stack instead
# of replacing, which is fine for them (each narrows the last) and exactly wrong
# for this one (each would negate the last).
_NEWFILE_CLAUSE_MARKER = "\nNEW-FILE OWNERSHIP: "


def _apply_newfile_clause(criteria: str, *, is_owner: bool,
                          owner_id: str) -> str:
    """Return `criteria` with exactly one new-file-ownership clause, replacing
    any clause inherited from a parent split (DESIGN §5½ (P1) *Sub-file*)."""
    base = criteria.split(_NEWFILE_CLAUSE_MARKER)[0].rstrip()
    if is_owner:
        body = ("you are this split's designated new-file owner. If the "
                "criteria above require a file that does not exist yet, create "
                "it here. No sibling will.")
    else:
        body = (f"create no new files. If the criteria above require a file "
                f"that does not exist yet, it belongs to {owner_id}; leave it "
                f"to that subtask rather than creating your own copy.")
    return f"{base}{_NEWFILE_CLAUSE_MARKER}{body}"


def _newfile_designation(subtask: dict, first_child_id: str) -> tuple[str, bool]:
    """Resolve (owner_id, parent_is_owner) for a split's children.

    A non-owner's ENTIRE subtree must contain no owner: if a child that was told
    "leave new files to X" is itself split, none of its own children may claim
    ownership, and they must keep naming X rather than a fresh sibling. Only an
    owner (or an undesignated top-level subtask) passes ownership down, to its
    first child. That is what keeps exactly one leaf owner in the whole tree.

    Read from a structural field rather than by re-reading the criteria text —
    the same discipline as `_cofile_cluster`."""
    if subtask.get("_newfile_owner") is False:
        return subtask.get("_newfile_owner_id") or first_child_id, False
    return first_child_id, True


def _inherited_subtask_fields(subtask: dict) -> dict:
    """Fields copied verbatim from a parent subtask into every child, shared
    between `_migration_child` and `_subfile_child`. `requires` is deep-copied
    (its entries are dicts); the list fields are shallow-copied. See
    `_migration_child`'s docstring for why copying (not aliasing) matters."""
    return {
        "scope_note": subtask.get("scope_note", ""),
        "depends_on": list(subtask.get("depends_on", []) or []),
        "requires": copy.deepcopy(subtask.get("requires", []) or []),
        "provides": list(subtask.get("provides", []) or []),
        "size": "medium",
        "investigation_notes": subtask.get("investigation_notes", ""),
        # Load-bearing for the migration path: `_peel_oversized_file` builds a
        # migration child for the dense file, and that child re-enters
        # `_subfile_split`, whose `change_shape` gate reads this field.
        # Dropping it here routes the dominant dense-file shape (a file
        # bundled with its test file) straight past the gate.
        "change_shape": subtask.get("change_shape"),
        # The rest of the split gate travels with it (DESIGN §5½ (P1)
        # *Sub-file*): a child is gated, and site-limited, as its parent was.
        "independent_sites": subtask.get("independent_sites"),
        "sweep_sites": list(subtask.get("sweep_sites") or []),
        **_site_claim_fields(subtask),
        **_inherited_verify(subtask),
    }


def _inherited_verify(subtask: dict) -> dict:
    """The parent's `verify` entries, for a child built by code (DESIGN §8
    *A no-op the base already carries*): its criteria are the parent's seed
    copied verbatim plus a scope clause, so the commands that decide the
    parent's criteria decide the child's. Without them every split child
    lost settle-by-execution. `verification_only` is never inherited: a
    child of a subtask that was split has work to do, and absence means
    false. Absent when the parent has no `verify`."""
    entries = subtask.get("verify")
    if not isinstance(entries, list) or not entries:
        return {}
    return {"verify": copy.deepcopy(entries)}


def _split_children_missing_verify(parent: dict,
                                   children: list[dict]) -> list[str]:
    """The ids of splitter-made children that carry no `verify` entry under
    a parent whose `verify` had an executable argv — a plan defect (DESIGN
    §8 *A no-op the base already carries*): each such child loses the
    settle-by-execution its parent had. Logged, never repaired: which of
    the parent's commands decides a child's own criterion is the
    splitter's reading, not code's."""
    if not _subtask_verify_argvs(parent):
        return []
    return [str(c.get("id")) for c in children
            if isinstance(c, dict) and not (
                isinstance(c.get("verify"), list) and c["verify"])]


def _inherit_split_fields(parent: dict, children: list[dict]) -> None:
    """In-place: give LLM-splitter children the parent's split-gate fields.
    The splitter schema does not carry them, and a child without them would
    never be tiled however its parent was declared — or, before the gate
    refused absence, always be (DESIGN §5½ (P1) *Sub-file*)."""
    for child in children:
        if isinstance(child, dict):
            child["change_shape"] = parent.get("change_shape")
            child["independent_sites"] = parent.get("independent_sites")
            child["sweep_sites"] = list(parent.get("sweep_sites") or [])
            # Planner-only (DESIGN §8 *A no-op the base already carries*):
            # a split child has work to do, whatever the splitter wrote.
            child.pop("verification_only", None)


def _site_claim_fields(subtask: dict) -> dict:
    """The parent's `change_kind` and `claims`, for every child a split
    makes (DESIGN §5 *Every `fix` site is claimed*). Claims are recorded on
    the first-pass plan; a split re-homes the subtask, so a child that lost
    them would leave its parent's sites claimed by an id no longer in the
    plan. Every child carries the parent's claims — which child edits a site
    is not known when the split is made, and a claim duplicated across
    siblings still says the site is claimed. Absent keys stay absent (a
    non-bug-fixing plan's subtask has none)."""
    out: dict = {}
    if "change_kind" in subtask:
        out["change_kind"] = subtask["change_kind"]
    if "claims" in subtask:
        out["claims"] = copy.deepcopy(subtask["claims"])
    return out


def _migration_child(subtask: dict, chunk: list[str], cid: str,
                     title: str, criteria: str,
                     newfile_owner_id: str | None = None,
                     verify: list | None = None) -> dict:
    """Build one migration-chunk child subtask from its (code-fixed) file
    partition plus a title + success_criteria_seed. Inherits the parent's
    graph edges/intent; the files are the pre-computed chunk, never re-decided.

    The edge lists are *copied*, not aliased. Handing every child the parent's
    list object is safe only while no one mutates one in place, and someone
    does: `_apply_overlap_drop` unions the dropped subtask's tags into the
    survivor with `surv_provides.append(tag)`. With a shared list that tag
    lands on every sibling, and `_build_predecessor_graph` turns each into a
    real predecessor edge for every consumer that `requires` it — a subtask
    silently gaining dependencies it never declared. Copying here makes the
    invariant structural instead of asking every future caller to remember to
    rebind rather than mutate. `requires` entries are dicts, so the copy is
    deep enough to give each child its own entry dicts too.

    `migration_targets`/`performs_replacement` are carried forward the same
    way: `check_planner_output` (and its `_check_migration_surface`/
    `_check_migration_targets_declared` checks) runs on the planner's raw
    sample before expansion, so these fields are inert for that gate's
    purposes here — but a leaf child is still a subtask that replaces the
    same pattern its parent did, and dropping the fields would silently
    make that fact unrecoverable for anything that reads a leaf in
    isolation later (a human reviewing the plan, or a future consumer)."""
    # Same one-owner rule as `_subfile_child`, for the same reason: every child
    # here also inherits the parent's `success_criteria_seed`, so a parent
    # criterion demanding a file that does not exist yet ("A new runtime e2e
    # test ...") is handed to all of them at once. Measured on run 719c2a26,
    # `bugfix-001-f2` — a peel child, not a region child — carries the same
    # criteria hash (8b372445) as all 12 region children, so the peel pair is
    # the identical collision shape at 2-way instead of 14-way.
    #
    # UNLIKE the region children, there is NO mechanical backstop here: these
    # children carry no `owned_region`, so `OWNED_REGION_FILE_ESCAPE` cannot
    # see them and the criteria clause is the whole mechanism. Applied in
    # `_migration_child` rather than in each label helper so it reaches the
    # peel pair, the deterministic chunk-label fallback, AND the labels the
    # label-only splitter writes — that last one composes its own criteria per
    # chunk and would otherwise carry no clause at all.
    #
    # `None` means "no designation" and leaves `criteria` untouched, so a
    # caller that has no sibling set to speak of keeps the previous behaviour.
    is_owner = newfile_owner_id is not None and cid == newfile_owner_id
    if newfile_owner_id is not None:
        criteria = _apply_newfile_clause(
            criteria, is_owner=is_owner, owner_id=newfile_owner_id)
    # `verify`, when given, is the label-only splitter's own entries for
    # this chunk's rewritten criteria; it replaces the parent's.
    own_verify = ({"verify": copy.deepcopy(verify)}
                  if isinstance(verify, list) and verify else {})
    return {
        "id": cid,
        "title": title,
        "success_criteria_seed": criteria,
        "files_likely_touched": chunk,
        "intent": subtask.get("intent", ""),
        **_inherited_subtask_fields(subtask),
        "migration_targets": copy.deepcopy(
            subtask.get("migration_targets", []) or []),
        "performs_replacement": subtask.get("performs_replacement", False),
        # Structural record of the clause above, so a re-split of this child
        # resolves ownership from a field instead of re-reading its criteria
        # prose (`_newfile_designation`). A non-owner's whole subtree stays
        # ownerless and keeps naming the original owner.
        "_newfile_owner": is_owner if newfile_owner_id is not None else None,
        "_newfile_owner_id": newfile_owner_id,
        **own_verify,
    }


def _deterministic_chunk_label(subtask: dict, chunk: list[str],
                               idx: int, total: int) -> tuple[str, str]:
    """Fallback title + criteria for a migration chunk when the splitter
    label-only worker is unavailable or returns a mismatched set. Distinct
    per chunk BY CONSTRUCTION (idx + file list) so children never collide."""
    parent_title = subtask.get("title", "migration")
    title = f"{parent_title} (part {idx + 1}/{total})"
    files_txt = ", ".join(chunk)
    criteria = (
        f"{subtask.get('success_criteria_seed', '')}\n"
        f"Scope: only these files — {files_txt}."
    ).strip()
    return title, criteria


def _subfile_child(subtask: dict, file: str, region: tuple[int, int],
                   symbols: list[str], cid: str, cluster: str,
                   idx: int, total: int, newfile_owner_id: str,
                   is_owner: bool) -> dict:
    """Build one sub-file child owning a *region* (``(start, end)`` lines) of a
    single *file* (DESIGN §5½ (P1) *Sub-file*). The analog of ``_migration_child``
    for intra-file splitting.

    Same deep-copy edge discipline as ``_migration_child`` (see its docstring —
    aliased lists leak dependencies via `_apply_overlap_drop`). Differences:

    - ``files_likely_touched`` is the *single* parent file — every region child
      co-owns it, which is legitimate downstream (_schedule ignores files;
      `git merge` reconciles; the overlap judge is told to exclude same-file/
      different-region collisions via the region-scoped ``intent`` below plus
      the ``_cofile_cluster`` marker it's shown — DESIGN §5 *Cross-domain
      surface overlap*).
    - ``owned_region`` records the code-computed line range + the symbols it
      contains, so the implementer's prompt scopes it to that span.
    - ``_cofile_cluster`` marks the child as part of an *intentional* same-file
      cluster, so ``check_planner_output`` suppresses its advisory
      INTRA_DOMAIN_OVERLAP warning ("consider merging or splitting" — the opposite
      of what we want here).
    - No sibling ``depends_on``: region children edit disjoint line ranges of one
      file and are independently implementable, so they stay in the same wave
      (the parent's own inbound/outbound edges are inherited by every child, as on
      the migration path)."""
    lo, hi = region
    parent_title = subtask.get("title", "file change")
    sym_txt = ", ".join(symbols) if symbols else "(no named symbols in range)"
    title = f"{parent_title} (region {idx + 1}/{total}: lines {lo}-{hi})"
    # New-file ownership is a SEPARATE constraint from the line range, not a
    # corollary of it: the parent's criteria may demand a new file, and "do not
    # edit outside lines X-Y" does not constrain creating one. In run 719c2a26
    # every region child inherited a criterion opening "A new runtime e2e test
    # ... reproduces ...", three near-synonymous files were invented for it, and
    # two children independently chose the SAME new path — an add/add conflict
    # on a path absent from the merge base, which has no resolution that keeps
    # both sides. Exactly one child may create files; the rest are told which
    # sibling owns that work, by id, so they can declare an edge instead of
    # racing it. Which child is arbitrary; that there is exactly one is the
    # point (DESIGN §5½ (P1) *Sub-file*).
    # `is_owner` comes from the CALLER, not from `idx == 0`: on a re-split the
    # parent may itself be a non-owner, and then no child of it may own new
    # files however it is indexed (`_newfile_designation`).
    criteria = _apply_newfile_clause(
        (
            f"{subtask.get('success_criteria_seed', '')}\n"
            f"Scope: only lines {lo}-{hi} of {file} "
            f"(symbols: {sym_txt}). Do not edit outside this range; a sibling "
            f"subtask owns the rest of the file."
        ).strip(),
        is_owner=is_owner, owner_id=newfile_owner_id)
    # Region-scoped, not a verbatim parent copy (unlike _migration_child,
    # where verbatim inheritance is safe because chunks own disjoint files).
    # Region children co-own the SAME file, so an unscoped intent gives
    # plan_overlap_judge no textual signal to distinguish N children each
    # claiming to implement the parent's complete feature — the direct
    # cause of a real false-positive "unresolvable surface collision"
    # incident (DESIGN §5 *Cross-domain surface overlap*). Mechanically
    # derived, no LLM call, matching this function's "Pure + deterministic"
    # guarantee.
    intent = (
        f"{subtask.get('intent', '')} This subtask's slice: only lines "
        f"{lo}-{hi} of {file} (symbols: {sym_txt}). A sibling subtask "
        f"owns the rest of the file."
    ).strip()
    return {
        "id": cid,
        "title": title,
        "success_criteria_seed": criteria,
        "files_likely_touched": [file],
        "owned_region": {"file": file, "start": lo, "end": hi,
                         "symbols": list(symbols)},
        "_cofile_cluster": cluster,
        "intent": intent,
        **_inherited_subtask_fields(subtask),
        # See `_migration_child`'s copy of these two: a re-split resolves
        # ownership from here, never by re-reading the criteria text.
        "_newfile_owner": is_owner,
        "_newfile_owner_id": newfile_owner_id,
    }


async def _call_splitter(
    system_prompt: str, user_prompt: str, sid: str, st: "State", caps: dict,
    models: dict[str, str], efforts: dict[str, str | None],
) -> dict:
    """Shared claude_p() invocation shape for the two splitter call sites in
    _label_migration_chunks and _recursive_decompose — identical kwargs apart
    from the prompt content and sid. Each caller keeps its own try/except and
    result-handling around this call."""
    return await claude_p(
        system_prompt=system_prompt,
        user_prompt=user_prompt,
        schema_key="splitter",
        cwd=_judgment_cwd(st),
        allowed_tools=INSPECT_TOOLS,
        max_turns=30,
        autonomous=False,
        caps=caps,
        st=st,
        model=models.get("splitter", MODEL_DEFAULT),
        effort=efforts.get("splitter"),
        sid=sid,
    )


async def _label_migration_chunks(
    subtask: dict, chunks: list[list[str]], base_id: str, depth: int,
    st: "State", caps: dict, models: dict[str, str],
    efforts: dict[str, str | None], repo_root: Path,
    wrap_repo_map: Callable[[str], str],
) -> list[dict]:
    """LABEL-ONLY splitter pass for migration chunks (DESIGN §5½ — "the LLM
    only labels"). The file→chunk partition is fixed by _partition_files();
    this asks the splitter to write a distinct title + success_criteria_seed
    per chunk (keyed by its pre-assigned id) so children are not identical
    parent-copies. §12 code-enforces coverage: if the worker returns a
    mismatched or incomplete label set, every chunk falls back to a distinct
    deterministic label rather than crashing or shipping identical titles."""
    ids = [f"{base_id}-{i + 1}" for i in range(len(chunks))]
    # Deterministic labels are the guaranteed-distinct baseline; the worker
    # only upgrades them.
    labels: dict[str, tuple[str, str]] = {
        cid: _deterministic_chunk_label(subtask, chunk, i, len(chunks))
        for i, (cid, chunk) in enumerate(zip(ids, chunks))
    }

    chunk_spec = [{"id": cid, "files_likely_touched": chunk}
                  for cid, chunk in zip(ids, chunks)]
    # The splitter's `verify` per relabelled chunk; a chunk it gave none
    # keeps the parent's (`_inherited_verify`).
    verifies: dict[str, list] = {}
    try:
        _bump_decompose_workers(st, caps)
    except DecompositionBudgetExceeded:
        # Decomposition's share of the worker budget is spent (N3+N4) --
        # skip the label-only call entirely and keep the deterministic
        # labels (already guaranteed-distinct; the worker only upgrades
        # them). Not a WorkerError degrade: no call was ever spawned.
        log(f"_recursive_decompose: decomposition budget exceeded before "
            f"label-only splitter for {base_id}; using deterministic "
            "chunk labels")
        owner_id, _ = _newfile_designation(subtask, ids[0])
        return [
            _migration_child(subtask, chunk, cid, *labels[cid],
                             newfile_owner_id=owner_id)
            for cid, chunk in zip(ids, chunks)
        ]
    sys_prompt = _load_prompt("splitter")
    user_prompt = wrap_repo_map(
        "LABEL PRE-PARTITIONED MIGRATION CHUNKS (label-only mode).\n"
        "The file partition below is FIXED — do NOT move, add, or drop files. "
        "For each chunk id, write a concise distinct `title`, a "
        "`success_criteria_seed`, and `verify`: one entry per criterion with "
        "the argv that decides it on that chunk alone. Return one child per "
        "id, preserving ids and files_likely_touched exactly.\n\n"
        "PARENT SUBTASK:\n"
        f"{json.dumps(subtask, indent=2)}\n\n"
        "CHUNKS TO LABEL:\n"
        f"{json.dumps(chunk_spec, indent=2)}"
    )
    try:
        result = await _call_splitter(
            sys_prompt, user_prompt, f"splitter-label-{base_id}-d{depth}",
            st, caps, models, efforts,
        )
        for child in (result.get("children") or []):
            cid = child.get("id")
            title = (child.get("title") or "").strip()
            crit = (child.get("success_criteria_seed") or "").strip()
            if cid in labels and title and crit:
                labels[cid] = (title, crit)
                if isinstance(child.get("verify"), list):
                    verifies[cid] = child["verify"]
    except (WorkerError, subprocess.TimeoutExpired):
        # Worker crashed — keep the distinct deterministic labels (§12: a
        # split must never silently produce identical children).
        log(f"_recursive_decompose: label-only splitter failed for "
            f"{base_id}; using deterministic chunk labels")

    owner_id, _ = _newfile_designation(subtask, ids[0])
    return [
        _migration_child(subtask, chunk, cid, *labels[cid],
                         newfile_owner_id=owner_id,
                         verify=verifies.get(cid))
        for cid, chunk in zip(ids, chunks)
    ]


# Declared `change_shape` values that must NOT be tiled intra-file. The enum's
# third member, "sweep", is the only shape the sub-file split exists for
# (DESIGN §5½ (P1) *Sub-file*). Kept as a frozenset rather than inlined so the
# gate and its test name the same object.
_NON_SWEEP_CHANGE_SHAPES = frozenset({"point", "localized"})


def _subfile_split_gate(subtask: dict) -> str | None:
    """None when `subtask` may be tiled intra-file, else why not (DESIGN
    §5½ (P1) *Sub-file* *Gating condition*): only a typed `change_shape:
    "sweep"` with `independent_sites: true`. A missing field refuses — the
    reversed default (Q5/E1: the absence-means-split default was the main
    path of harmful tilings)."""
    shape = subtask.get("change_shape")
    if shape != "sweep":
        return (f"change_shape={shape!r}" if shape is not None
                else "no change_shape declared")
    if subtask.get("independent_sites") is not True:
        return ("independent_sites not declared true"
                if subtask.get("independent_sites") is not None
                else "no independent_sites declared")
    return None


def _sweep_site_lines(subtask: dict, repo_root: Path, file: str) -> set[int]:
    """The 1-based lines of `file` holding one of the subtask's typed
    `sweep_sites`, located with `git grep --no-index -n -w -F` — a fixed,
    whole-word string the planner named, never a pattern derived from prose.
    An identifier with whitespace or a path separator is skipped; a grep that
    fails finds nothing."""
    lines: set[int] = set()
    for site in subtask.get("sweep_sites") or []:
        if (not isinstance(site, str) or not site.strip()
                or any(c.isspace() for c in site) or "/" in site):
            continue
        try:
            r = subprocess.run(
                ["git", "--literal-pathspecs", "grep", "--no-index", "-n",
                 "-w", "-F", "-e", site, "--", file], cwd=str(repo_root),
                capture_output=True,
                text=True, check=False, timeout=60)
        except (OSError, subprocess.TimeoutExpired):
            continue
        if r.returncode not in (0, 1):
            continue
        for row in r.stdout.splitlines():
            # `<file>:<line>:<text>` — the file is the one we named.
            rest = row[len(file) + 1:] if row.startswith(file + ":") else ""
            num = rest.split(":", 1)[0]
            if num.isdigit():
                lines.add(int(num))
    return lines


def _subfile_split(subtask: dict, repo_root: Path,
                   max_span: int) -> list[dict]:
    """Split a single-file subtask *within* the file into region-owning children
    (DESIGN §5½ (P1) *Sub-file*). Pure + deterministic — no LLM decides
    membership. Returns ``[]`` when the subtask is not a sub-file split candidate
    or cannot be split further (the caller then treats the node as a leaf).

    Two entry shapes, both routed here from ``_recursive_decompose``:

    - **First entry** — a whole single-file subtask with no ``owned_region``. Tier
      1: tile the file on function-boundary spans (`_partition_symbols_by_line`).
      A region that is itself over the cap comes back oversized and re-enters
      recursion, hitting the second shape below.
    - **Re-entry** — a child carrying ``owned_region`` whose span still exceeds the
      cap (a single function larger than the cap, e.g. the 1,733-line
      `executeStepWithHealing`). Tier 2: contiguous line-windows over that region
      (`_partition_lines`), which needs no symbol ranges.

    Coverage/overlap is guaranteed by construction and re-asserted by
    `_check_intra_file_surface`; a backstop failure logs and returns ``[]`` (fall
    back to a leaf) rather than emitting a broken partition."""
    files = subtask.get("files_likely_touched") or []
    if len(files) != 1:
        return []
    file = files[0]
    base_id = subtask.get("id", "split")
    cluster = subtask.get("_cofile_cluster") or base_id
    owned = subtask.get("owned_region")

    if owned:
        # Re-entry: tier-2 line-windows over the already-owned region.
        lo, hi = owned.get("start", 1), owned.get("end", 1)
        if (hi - lo + 1) <= max_span:
            return []  # small enough — leaf
        windows = _partition_lines(lo, hi, max_span)
        surface_total = hi - lo + 1
        # shift windows into a 1-based frame only for the backstop check
        shifted = [(w0 - lo + 1, w1 - lo + 1) for w0, w1 in windows]
        issues = _check_intra_file_surface(shifted, surface_total)
        regions = windows
        symbols_per = [[] for _ in regions]
    else:
        # First entry: tier-1 function-boundary tiling of the whole file.
        #
        # Gate on the parent's declared change shape BEFORE looking at the
        # file at all (DESIGN §5½ (P1) *Sub-file* *Gating condition*). Size
        # alone is the wrong trigger: tiling is for an edit-DENSE sweep, and a
        # point fix in a large file yields N children that each inherit a
        # whole-file mandate only one of them can satisfy in region. Measured
        # on run 719c2a26 — a one-expression fix in a 9,140-line file tiled
        # into 14 regions — 11 of 12 children touched a file outside their
        # region and 7 of 12 edited lines outside their range; exactly one
        # complied.
        #
        # Absence IS a refusal (DESIGN §5½ (P1) *Sub-file*): the earlier
        # absence-means-split default let splitter and peel children with no
        # declared shape be tiled, the main path of harmful tilings on fresh
        # data (Q5/E1: region children ended blocked 66 of 86 times). Only a
        # typed independent sweep is tiled; children inherit the fields.
        refusal = _subfile_split_gate(subtask)
        if refusal is not None:
            log(f"_recursive_decompose: {subtask.get('id', '?')}: {refusal} "
                f"— not tiling {file!r} intra-file (sub-file split is for "
                "independent-site sweeps; see DESIGN §5½ (P1) *Sub-file*)")
            return []
        abs_path = repo_root / file
        try:
            total_lines = _read_text_beneath(
                repo_root, abs_path, limit=READ_LIMIT_TEXT).count("\n") + 1
        except OSError:
            return []  # file unreadable — can't region-split; leave as leaf
        if total_lines <= max_span:
            return []  # whole file already within the cap — leaf
        ranges = _extract_symbol_ranges(repo_root, abs_path)
        regions = _partition_symbols_by_line(ranges, total_lines, max_span)
        if len(regions) <= 1:
            # No usable boundaries (or one span covers the file): tier-2 fallback
            # over the whole file so a range-less large file still gets split.
            regions = _partition_lines(1, total_lines, max_span)
        issues = _check_intra_file_surface(regions, total_lines)
        # Attach the symbols that fall inside each region for the child's prompt.
        symbols_per = []
        for lo, hi in regions:
            symbols_per.append(
                [n for (n, s, e) in ranges if lo <= s and e <= hi])

    if issues:
        log(f"_recursive_decompose: intra-file partition of {file!r} failed its "
            f"coverage backstop ({issues}); accepting as leaf")
        return []
    # Site-limited tiling (DESIGN §5½ (P1) *Sub-file*): a region holding none
    # of the sweep's located sites has nothing to change, and a child for it
    # would only invent work. The full tiling passed the backstop above; the
    # children are the regions that hold a site.
    sites = _sweep_site_lines(subtask, repo_root, file)
    keep = [i for i, (lo, hi) in enumerate(regions)
            if any(lo <= n <= hi for n in sites)]
    if len(keep) < len(regions):
        log(f"_recursive_decompose: {base_id}: {len(keep)} of {len(regions)} "
            f"region(s) of {file!r} hold a typed sweep site — tiling only "
            "those")
    regions = [regions[i] for i in keep]
    symbols_per = [symbols_per[i] for i in keep]
    if len(regions) <= 1:
        return []  # nothing gained — leaf

    total = len(regions)
    # Index 0's id, derived the same way its own cid is, so the designation is
    # stable across a resume — but only when this subtask is entitled to hand
    # ownership down at all. Re-entering a NON-owner must not mint a new owner.
    owner_id, parent_owns = _newfile_designation(subtask, f"{base_id}-r1")
    return [
        _subfile_child(subtask, file, region, symbols_per[i],
                       f"{base_id}-r{i + 1}", cluster, i, total,
                       owner_id, parent_owns and i == 0)
        for i, region in enumerate(regions)
    ]


def _peel_oversized_file(subtask: dict, repo_root: Path,
                         max_span: int, chunk_size: int) -> list[dict]:
    """Peel a single oversized file out of a small multi-file subtask so it can
    reach `_subfile_split`'s intra-file tiling (DESIGN §5½ (P1) *Sub-file*).

    `_subfile_split` only tiles a subtask whose `files_likely_touched` is exactly
    one file. But the dominant real shape of a dense-file subtask is the file
    bundled with its test file (`[flow-runner.ts, flow-runner.test.ts]` — the
    exact shape of feat-005, which is why its first sub-file fix never engaged).
    For such a subtask this peels it into two children: a single-file child
    scoped to the oversized file (which re-enters recursion and gets tiled) and a
    sibling owning the remaining file(s).

    Fires only when **exactly one** file exceeds `max_span` lines and the set is
    small (`1 < len(files) <= chunk_size`). Returns `[]` (fall through unchanged)
    when: the set is a single file (`_subfile_split` already handles it) or too
    large (a migration sweep the file-count fork owns); zero files are oversized
    (nothing to peel); or >=2 are oversized (genuinely coupled multi-file work the
    LLM splitter should own). A file whose line count can't be read is treated as
    not-oversized (a leaf-safe default), mirroring `_subfile_split`.

    Children are built with `_migration_child` (same edge-copy discipline; the
    dense-file child re-enters `_subfile_split` on recursion, so it needs no
    `owned_region` here — the tiling assigns regions)."""
    files = subtask.get("files_likely_touched") or []
    if not (1 < len(files) <= chunk_size):
        return []

    def _line_count(f: str) -> int:
        try:
            return _read_text_beneath(
                repo_root, repo_root / f, limit=READ_LIMIT_TEXT).count("\n") + 1
        except OSError:
            return 0  # unreadable → treat as not-oversized (leaf-safe)

    oversized = [f for f in files if _line_count(f) > max_span]
    if len(oversized) != 1:
        return []  # nothing to peel, or genuinely coupled — LLM splitter owns it

    dense = oversized[0]
    rest = [f for f in files if f != dense]
    base_id = subtask.get("id", "split")
    parent_title = subtask.get("title", "file change")
    seed = subtask.get("success_criteria_seed", "")
    # f1 owns new files rather than an arbitrary child: it holds the dense file
    # the work is actually about, while f2 exists only to carry the leftovers.
    # Unless this subtask is itself a non-owner, in which case the resolved id
    # is an ancestor's and no child's cid can match it — so neither peel child
    # claims ownership, and both keep naming the real owner.
    newfile_owner, _ = _newfile_designation(subtask, f"{base_id}-f1")
    dense_child = _migration_child(
        subtask, [dense], f"{base_id}-f1",
        f"{parent_title} (dense file: {dense})",
        (f"{seed}\nScope: only {dense}. A sibling subtask owns the "
         f"remaining file(s).").strip(),
        newfile_owner_id=newfile_owner)
    rest_child = _migration_child(
        subtask, rest, f"{base_id}-f2",
        f"{parent_title} (remaining: {', '.join(rest)})",
        (f"{seed}\nScope: only these files — {', '.join(rest)}. A sibling "
         f"subtask owns {dense}.").strip(),
        newfile_owner_id=newfile_owner)
    # A test child runs after the code child it was peeled from (DESIGN §5½
    # *Oversized-file peel*): by leerie's own test-file classification of
    # the paths, never the prose. Run c33bef9e's f2 (the end-to-end test)
    # ran beside f1 (the generator it tests) and blocked `upstream_missing`.
    # Both children holding tests, or neither, is no signal: no edge.
    globs = resolve_test_file_globs(repo_root)
    dense_tests = _is_test_case_file(dense, globs)
    rest_tests = any(_is_test_case_file(f, globs) for f in rest)
    if rest_tests and not dense_tests:
        rest_child["depends_on"] = [*rest_child["depends_on"],
                                    dense_child["id"]]
    elif dense_tests and not rest_tests:
        dense_child["depends_on"] = [*dense_child["depends_on"],
                                     rest_child["id"]]
    return [dense_child, rest_child]


def _bump_decompose_workers(st: "State", caps: dict) -> None:
    """Reserve one decomposition call against `decompose_budget_share *
    max_total_workers` and bump the shared worker budget (N3+N4 --
    partition the budget so recursive decomposition cannot starve
    execution).

    Checks the decomposition-specific ceiling BEFORE bumping anything: a
    refused call must not touch `worker_count` or `decompose_worker_count`
    -- every recursion node still visits this function once even after the
    share is exhausted (each sibling/child in the tree independently
    reaches its own fit_judge/splitter spawn site), and if refusal still
    incremented the counters, those phantom bumps would themselves eat
    into the execution budget the partition exists to protect, and
    `decompose_worker_count` would grow unbounded past the share instead
    of holding at it.

    Called instead of a bare `st.bump_workers(caps)` at every fit_judge /
    splitter spawn site in `_recursive_decompose`. Once the share is
    available, `st.bump_workers` still runs and can still raise the
    pre-existing global-budget WorkerError -- this only adds an earlier,
    decomposition-specific ceiling in front of it."""
    share = caps.get("decompose_budget_share",
                     DEFAULT_CAPS["decompose_budget_share"])
    cap = caps["max_total_workers"]
    spent = st.data.get("decompose_worker_count", 0)
    if spent >= share * cap:
        raise DecompositionBudgetExceeded(
            f"decomposition budget exceeded ({spent} calls, "
            f"{share:.0%} share of {cap} reached); accepting as leaf to "
            "preserve execution budget."
        )
    st.bump_workers(caps)
    st.data["decompose_worker_count"] = spent + 1
    st.save()


async def _recursive_decompose(
    subtask: dict,
    depth: int,
    st: "State",
    caps: dict,
    models: dict[str, str],
    efforts: dict[str, str | None],
    repo_root: Path,
    *,
    repo_map: dict | None = None,
    _parent_score: float | None = None,
    _noprogress_count: int = 0,
) -> list[dict]:
    """Recursively decompose *subtask* until leaves pass the P1 fit threshold.

    Algorithm (DESIGN §5½ (P1)):
      1. Judge the subtask's Task-Context Fit via the fit_judge worker.
      2. If score >= decompose_fit_threshold or depth >= decompose_max_depth:
         return [subtask] (leaf).
      3. Split using _partition_files (migration) or the splitter worker
         (coupled minority). Every judge/split call goes through
         _bump_decompose_workers, which enforces decompose_budget_share
         (N3+N4) on top of the shared st.bump_workers budget.
      4. No-progress guard: if decompose_noprogress_rounds consecutive rounds
         produce no child whose score exceeds the parent's, accept as leaf with
         a warning.
      5. Recurse into each child at depth+1; return flattened leaves.

    *repo_map* is the pre-built (once, in phase_plan) global symbol graph;
    when present, each fit_judge/splitter call is grounded with a per-node
    personalized-PageRank subgraph ranked to *this* subtask's files (DESIGN
    §5½ P6 — "feed the same to the splitter, re-ranked to each node's files").
    ``None`` when skip_repo_map is set or the map could not be built — the
    workers then run on the raw subtask spec (graceful degrade).

    Returns a flat list of leaf subtasks ready for _schedule()."""
    max_depth = caps.get("decompose_max_depth",
                         DEFAULT_CAPS["decompose_max_depth"])
    threshold = caps.get("decompose_fit_threshold",
                         DEFAULT_CAPS["decompose_fit_threshold"])
    noprogress_max = caps.get("decompose_noprogress_rounds",
                              DEFAULT_CAPS["decompose_noprogress_rounds"])
    max_span = caps.get("subfile_split_max_span",
                        DEFAULT_CAPS["subfile_split_max_span"])

    # Sub-file region re-entry (DESIGN §5½ (P1) *Sub-file*, tier 2): a child that
    # already owns a code-computed line region needs no fit_judge — the split
    # decision is mechanical (its span vs the cap), and an LLM cannot sub-split a
    # single region anyway. Deciding here, before the worker spawn, both keeps the
    # decision code-enforced (§12) and saves a fit_judge call per region. A region
    # over the cap (a single function larger than the cap, e.g. the 1,733-line
    # executeStepWithHealing) is tier-2 line-window split even if it would have
    # scored well-fit; one within the cap is a leaf. Depth cap still bounds it.
    if subtask.get("owned_region") and depth < max_depth:
        region_children = _subfile_split(subtask, repo_root, max_span)
        if region_children:
            leaves: list[dict] = []
            for child in region_children:
                leaves.extend(await _recursive_decompose(
                    child, depth + 1, st, caps, models, efforts, repo_root,
                    repo_map=repo_map))
            return leaves
        return [subtask]  # region within span (or unsplittable) → leaf

    # Per-node P6 grounding: re-rank the global repo-map to this subtask's
    # files so the fit_judge/splitter see the local structural neighborhood
    # (DESIGN §5½). Empty seed_symbols — subtasks carry files, not symbols;
    # mirrors phase_plan's planner-ctx _rank_repo_map(rm, seeds, []) call.
    node_map_text = ""
    if repo_map is not None:
        try:
            node_files = [str(Path(f)) for f in
                          (subtask.get("files_likely_touched") or [])]
            node_map_text = _rank_repo_map(repo_map, node_files, [])
        except Exception:
            node_map_text = ""  # degrade silently; worker runs without it

    def _with_repo_map(prompt: str) -> str:
        if not node_map_text:
            return prompt
        return (
            f"{prompt}\n\nRANKED REPO-MAP SUBGRAPH (structural context for "
            f"this subtask's files):\n{node_map_text}"
        )

    # --- judge step ----------------------------------------------------------
    try:
        _bump_decompose_workers(st, caps)
    except DecompositionBudgetExceeded as exc:
        # Decomposition's share of the worker budget is spent (N3+N4) --
        # accept as a leaf without spawning the fit_judge call, the same
        # disposition a WorkerError degrade below reaches. Logged
        # separately from the crash message so the budget cap is visible
        # in run logs rather than reading as a worker failure.
        log(f"_recursive_decompose: {exc}")
        return [subtask]
    sys_prompt = _load_prompt("fit_judge")
    user_prompt = _with_repo_map(
        "SUBTASK TO JUDGE:\n"
        f"{json.dumps(subtask, indent=2)}\n\n"
        "Score this subtask's P1 Task-Context Fit (0–1) and return your verdict."
    )
    try:
        judge_result = await claude_p(
            system_prompt=sys_prompt,
            user_prompt=user_prompt,
            schema_key="fit_judge",
            cwd=_judgment_cwd(st),
            allowed_tools=INSPECT_TOOLS,
            max_turns=30,
            autonomous=False,
            caps=caps,
            st=st,
            model=models.get("fit_judge", MODEL_DEFAULT),
            effort=efforts.get("fit_judge"),
            sid=f"fit-judge-{subtask.get('id', 'x')}-d{depth}",
        )
    except (WorkerError, subprocess.TimeoutExpired):
        # Worker crashed mid-judgment (auth failure, killed session, PID
        # exhaustion) — degrade to leaf, the same disposition the depth cap
        # and no-progress guard below already reach when they cannot
        # establish a confident split. Without this, one WorkerError here
        # would propagate and discard every fit/split decision already paid
        # for elsewhere in the tree (DESIGN §6 *Credential strategy*).
        log(f"_recursive_decompose: fit_judge crashed for "
            f"{subtask.get('id', '?')}; accepting as leaf")
        return [subtask]
    # Range re-imposed in Python: grammar compilation cannot express
    # `minimum`/`maximum`, and the comparison below has no bound of its
    # own — an out-of-range score would read as well-fit (DESIGN §7).
    score: float = _bounded_or_conservative(
        judge_result.get("score", 0.0), 0.0, 1.0, 0.0,
        f"fit_judge {subtask.get('id', '?')} score")

    # --- leaf check ----------------------------------------------------------
    if score >= threshold or depth >= max_depth:
        if depth >= max_depth and score < threshold:
            log(
                f"_recursive_decompose: depth cap ({max_depth}) reached for "
                f"{subtask.get('id', '?')} (score={score:.2f}); accepting as leaf"
            )
        return [subtask]

    # --- no-progress guard ---------------------------------------------------
    if _parent_score is not None and score <= _parent_score:
        new_noprogress = _noprogress_count + 1
    else:
        new_noprogress = 0

    if new_noprogress >= noprogress_max:
        log(
            f"_recursive_decompose: no-progress guard triggered for "
            f"{subtask.get('id', '?')} after {noprogress_max} rounds "
            f"(score={score:.2f}); accepting as leaf with warning"
        )
        return [subtask]

    # --- split step ----------------------------------------------------------
    files = subtask.get("files_likely_touched") or []
    chunk_size = 8
    # Oversized-file peel (DESIGN §5½ (P1) *Sub-file* → *Oversized-file peel*):
    # a small multi-file subtask (e.g. a dense file + its test file) where
    # exactly one file is over the span cap is peeled into a single-file child
    # (which re-enters _subfile_split on recursion below and gets tiled) and a
    # sibling owning the rest. Checked before _subfile_split because that
    # function's len(files)==1 guard skips the dominant impl+test shape.
    # Deterministic — no worker spawn. Returns [] (falls through) when not a
    # peel candidate.
    peeled_children = _peel_oversized_file(
        subtask, repo_root,
        caps.get("subfile_split_max_span",
                 DEFAULT_CAPS["subfile_split_max_span"]),
        chunk_size)
    # Sub-file path (DESIGN §5½ (P1) *Sub-file*): a single dense file (or a
    # single oversized region re-entering) is split WITHIN the file, since the
    # whole-file splitter below cannot break one file. Checked first; falls
    # through to the file-count fork when it returns no children (not a
    # candidate, or already small enough). Deterministic — no worker spawn.
    subfile_children = _subfile_split(
        subtask, repo_root,
        caps.get("subfile_split_max_span",
                 DEFAULT_CAPS["subfile_split_max_span"]))
    if peeled_children:
        children = peeled_children
    elif subfile_children:
        children = subfile_children
    # Migration path (dominant case, ~84%): code-partitions, LLM only labels.
    # Coupled-minority path: LLM-splitter decides the partition.
    elif len(files) > chunk_size:
        # Migration sweep: _partition_files guarantees 100% coverage + 0 overlap
        # BY CONSTRUCTION (the code owns the partition — DESIGN §5½). The
        # splitter worker is then invoked in LABEL-ONLY mode: it titles and
        # writes success criteria per pre-computed chunk; it must NOT move
        # files. This is the plan's "LLM only labels" rule — a bare parent-copy
        # gives every chunk an identical, useless title.
        chunks = _partition_files(files, chunk_size)
        base_id = subtask.get("id", "split")
        children = await _label_migration_chunks(
            subtask, chunks, base_id, depth, st, caps, models, efforts,
            repo_root, _with_repo_map)
    else:
        # Coupled minority: LLM splitter decides the partition using
        # structural seams from the repo-map; backstopped by
        # _check_migration_surface at the plan level.
        try:
            _bump_decompose_workers(st, caps)
        except DecompositionBudgetExceeded as exc:
            # Decomposition's share of the worker budget is spent (N3+N4)
            # -- accept as a leaf without spawning the splitter call, the
            # same disposition a WorkerError degrade below reaches.
            log(f"_recursive_decompose: {exc}")
            return [subtask]
        sys_prompt_s = _load_prompt("splitter")
        user_prompt_s = _with_repo_map(
            "SUBTASK TO SPLIT:\n"
            f"{json.dumps(subtask, indent=2)}\n\n"
            "Split this subtask along real structural seams. Return child subtasks."
        )
        try:
            split_result = await _call_splitter(
                sys_prompt_s, user_prompt_s,
                f"splitter-{subtask.get('id', 'x')}-d{depth}",
                st, caps, models, efforts,
            )
        except (WorkerError, subprocess.TimeoutExpired):
            # Worker crashed mid-split (auth failure, killed session, PID
            # exhaustion) — degrade to leaf, the same disposition the depth
            # cap and no-progress guard above already reach when they cannot
            # establish a confident split. Without this, one WorkerError here
            # would propagate and discard every fit/split decision already
            # paid for elsewhere in the tree (DESIGN §6 *Credential strategy*).
            log(f"_recursive_decompose: splitter crashed for "
                f"{subtask.get('id', '?')}; accepting as leaf")
            return [subtask]
        children = split_result.get("children") or []
        _inherit_split_fields(subtask, children)
        missing = _split_children_missing_verify(subtask, children)
        if missing:
            log(f"  plan defect SPLIT_CHILD_NO_VERIFY: "
                f"{subtask.get('id', '?')} had verify commands, but split "
                f"child(ren) {', '.join(missing)} carry none — they lose "
                "settle-by-execution (DESIGN §8 *A no-op the base already "
                "carries*)")
        # The splitter's schema carries no claims; the code stamps the
        # parent's, as `_inherited_subtask_fields` does for code-built
        # children.
        for child in children:
            if isinstance(child, dict):
                child.update(_site_claim_fields(subtask))
        if not children:
            # Splitter produced no children; accept the subtask as a leaf.
            log(
                f"_recursive_decompose: splitter returned no children for "
                f"{subtask.get('id', '?')}; accepting as leaf"
            )
            return [subtask]

    # --- recurse into children -----------------------------------------------
    leaves: list[dict] = []
    # A child that splits further vanishes its own id mid-tree. The splitter is
    # allowed to give a child `depends_on` on a *sibling* child, so that edge
    # would dangle — and this is the only frame that can see it: phase_plan
    # receives fully-flattened leaves and never learns the intermediate id
    # existed. Empty on the migration path (code-built children can't name a
    # sibling), so the remap below is a no-op there.
    expansion: dict[str, list[str]] = {}
    for child in children:
        child_leaves = await _recursive_decompose(
            child, depth + 1, st, caps, models, efforts, repo_root,
            repo_map=repo_map,
            _parent_score=score,
            _noprogress_count=new_noprogress,
        )
        cid = child.get("id")
        leaf_ids = [c.get("id") for c in child_leaves if c.get("id")]
        if cid and cid not in leaf_ids:
            expansion[cid] = leaf_ids
        leaves.extend(child_leaves)
    _remap_vanished_deps(leaves, expansion)
    return leaves


def _remap_vanished_deps(subtasks: list[dict],
                         mapping: dict[str, list[str]]) -> None:
    """In-place: rewrite `depends_on` refs to ids that vanished from the plan.

    DESIGN §5 *Id-vanishing operations*. `mapping` is
    `{vanished_id: [successor_ids]}`; fan-out (expansion — a parent becomes N
    leaves) and prune (a drop — id maps to `[]`) are the same operation over it.

    Fan-out targets *every* successor, not a representative one: the tag channel
    already behaves this way (each leaf inherits `provides`, and
    `_build_predecessor_graph` resolves a tag to every provider), so the id
    channel matching it keeps scheduling independent of whether the planner
    expressed the edge by id or by tag. It costs no extra waves when the
    successors are mutually independent — they occupy the wave the parent would
    have.

    Mirrors `_apply_overlap_merge`'s rewrite discipline: dedup after the rewrite
    (a subtask may already depend on one successor) and skip self-references.
    `mapping.get(dep, [dep])` routes an untouched dep through the same path, so
    there is no separate branch to keep in sync.

    Single pass, which requires `mapping` to be *flat*: no successor may itself
    be a vanished key, or the substitution would leave a dangling id behind
    (`{A: [B], B: [C]}` rewrites `A` to `B` and stops). Both callers satisfy
    this by construction — `_recursive_decompose` returns fully-flattened leaves,
    so a generation's map only ever names terminal ids, and `phase_plan`'s map
    is keyed by first-pass parent ids whose successors are suffixed leaf ids
    that no other plan can name as a parent. A future caller that can build a
    chained map must resolve it to a fixpoint before calling."""
    if not mapping:
        return
    for s in subtasks:
        sid = s.get("id")
        deps = s.get("depends_on") or []
        if not any(d in mapping for d in deps):
            continue
        new_deps: list[str] = []
        for dep in deps:
            for repl in mapping.get(dep, [dep]):
                if repl not in new_deps and repl != sid:
                    new_deps.append(repl)
        s["depends_on"] = new_deps


def _prune_orphaned_requires(plans: list[dict],
                             dropped_provides: set[str]) -> None:
    """In-place: drop `requires` tags whose only provider was a dropped subtask.

    DESIGN §5 *Id-vanishing operations* — the drop half. `_remap_vanished_deps`
    handles the id (`depends_on`) channel; this handles the tag channel. A drop
    is *not* symmetric with an expansion here: an expansion's successors inherit
    the vanishing subtask's `provides`, so a tag edge self-heals; a drop has no
    successor, so its `provides` are gone and any survivor whose `requires` names
    a tag only the dropped subtask provided is now orphaned — which dies at
    `_validate_plan` (`requires 'X' but nothing provides it`) after the full
    planner spend.

    Operates over **all plans at once**, not per-plan, because capability tags
    are cross-domain: `requires` in one domain's plan is resolved by a `provides`
    that may live in another domain's plan (DESIGN §5 *Cross-domain capability
    tags*), and `_validate_plan` computes provider-existence globally over the
    merged plan. A per-plan prune would wrongly drop a tag a surviving subtask in
    a *different* plan still provides.

    The prune set is gated on `dropped_provides` (the union of the dropped
    subtasks' `provides`, captured *before* the survivor-filter removed them): a
    tag still provided by a surviving subtask (in any plan) is kept, and a tag no
    subtask ever provided is left intact so `_validate_plan` still surfaces it as a
    genuine planner error rather than silently masking it. Pruning "any
    requires-tag not in surviving provides" would swallow that never-provided
    case — hence the `dropped_provides` gate.
    """
    surviving_provides: set[str] = set()
    for plan in plans:
        for s in plan.get("subtasks", []):
            surviving_provides.update(s.get("provides") or [])
    orphaned = dropped_provides - surviving_provides
    if not orphaned:
        return
    for plan in plans:
        for s in plan.get("subtasks", []):
            req = s.get("requires") or []
            s["requires"] = [
                r for r in req
                if not (isinstance(r, dict) and r.get("tag") in orphaned)
            ]


_STOPWORDS = frozenset({
    "the", "a", "an", "to", "and", "or", "of", "in", "on", "for", "with",
})

# Fire threshold for phase_adherence_gate's adherence_judge score
# (0-10 scale). Corpus-validated (21 real runs, see the adherence_judge
# calibration writeup in prompts/adherence_judge.md): the incident plan
# scored <= 3.0, every legitimate plan >= 8.5 — a threshold anywhere in
# 4-6 cleanly separates the two with zero false positives on the tested
# corpus. Only consulted when `is_prescribed=true` (two-stage gate).
_ADHERENCE_GATE_THRESHOLD = 5.0


def _command_token_list(command: str) -> list[str]:
    """Lowercased, stopword-filtered token LIST (order preserved) for a
    single command string. The single owner of the normalization rule —
    `_command_tokens` and both arms of the declared-command matcher derive
    from it, so a stopword or punctuation change lands everywhere at once
    (a duplicated rule drifts exactly the way a duplicated list does)."""
    return [tok for tok in command.lower().split() if tok not in _STOPWORDS]


def _command_tokens(command: str) -> frozenset[str]:
    """Lowercased, stopword-filtered token set for a single command string."""
    return frozenset(_command_token_list(command))


def check_prescribed_command_coverage(
    prescribed_procedure: dict | None, subtasks: list[dict],
) -> list[str]:
    """Deterministic JSON→verdict floor for the instruction-adherence gate.

    PRIMARY, model-independent enforcement layer (DESIGN: instruction-
    adherence is code-enforced, sibling to §12 "prompts advisory, code
    enforces"). Computes prescribed.commands − ⋃(subtask.runs_commands)
    under normalized (lowercased, stopword-filtered token-SUBSET) matching
    — B4-validated: the planner emits `runs_commands` as a paraphrase that
    wraps the prescribed command's own tokens in extra words (e.g.
    "barnacle recon browser" for "recon browser"), never byte-identical, so
    exact string equality would false-positive on every honored command. A
    prescribed command is "covered" when some subtask's `runs_commands`
    entry's salient (non-stopword) token set is a SUPERSET of the
    prescribed command's own salient tokens — i.e. the paraphrase still
    contains every meaningful word of the prescribed command. (A weaker
    any-overlap rule would falsely mark an unrelated command "covered" by a
    single shared word, e.g. two different `recon ...` subcommands sharing
    only the token "recon".) Pure JSON→JSON set logic, no NL parsing.

    Short-circuits to `[]` (free) when `prescribed_procedure` is absent or
    `is_prescribed` is falsy, and when `commands` is empty (a goal-only task
    has nothing to check coverage against — 0 false positives by
    construction).
    """
    prescribed = prescribed_procedure or {}
    if not prescribed.get("is_prescribed"):
        return []
    commands = prescribed.get("commands") or []
    if not commands:
        return []

    run_token_sets = [
        _command_tokens(rc)
        for s in subtasks
        for rc in (s.get("runs_commands") or [])
        if isinstance(rc, str) and rc.strip()
    ]

    issues: list[str] = []
    for cmd in commands:
        if not isinstance(cmd, str) or not cmd.strip():
            continue
        cmd_tokens = _command_tokens(cmd)
        covered = bool(cmd_tokens) and any(
            cmd_tokens <= run_tokens for run_tokens in run_token_sets)
        if not covered:
            issues.append(
                f"PRESCRIBED_CMD_UNRUN: prescribed command {cmd!r} is not "
                "covered by any subtask's runs_commands")
    return issues


def _executed_bash_commands(log_path: Path) -> list[str]:
    """Every Bash command a worker actually invoked, in order, from its
    per-worker JSONL log (via `_iter_log_tool_use` — structured `tool_use`
    JSON, never prose). Empty when the log is missing or holds no Bash
    invocations."""
    return [
        (inp.get("command") or "")
        for kind, inp, _result in _iter_log_tool_use(log_path)
        if kind == "Bash" and (inp.get("command") or "").strip()
    ]


def check_declared_commands_executed(
    subtask: dict, executed: list[str],
) -> list[str]:
    """Settle-time half of the declared-command contract (DESIGN §"A
    declared command must also have been executed"): every `runs_commands`
    entry on a subtask claiming `complete` must match some Bash command
    its worker actually ran. `check_prescribed_command_coverage` above
    only proves a subtask *declares* each prescribed command; measured
    (barnacle 2026-09-22), a subtask declared the task's one empirical
    acceptance command, never issued it, and settled `complete` across
    ten runs.

    Normalized token matching per shell segment (`_BLT_SEG_RE` split +
    `_BLT_SEG_LEAD_RE` prefix strip), accepted in EITHER direction because
    `runs_commands` legitimately takes two shapes:

    - **literal declared** (the barnacle incident shape): the entry is the
      command itself, possibly executed wrapped — declared token SET ⊆
      segment token set, so `cd x && pnpm run build | tail` covers a
      declared "pnpm build";
    - **paraphrase declared** (the planner shape the plan-level floor's
      one corpus sample shows — the entry WRAPS the command's tokens in
      extra words, e.g. "run pnpm test to verify" for `pnpm test`): the
      segment's salient token LIST must appear as a length-≥2 CONTIGUOUS
      ordered sublist of the declared entry's salient token list.

    That contiguity rule is the settled endpoint of a measured
    three-round oscillation, and both of its neighbors are known-bad:
    a bare-SUBSET reverse rule let any ≥2-token fragment of a wordy
    paraphrase count as executed ("pnpm run", "make test" — non-adjacent
    words reassembled); a SUFFIX-only rule then false-alarmed on every
    paraphrase with words AFTER the command ("run pnpm test to verify"
    vs an exactly-executed `pnpm test`), which loops the re-drive
    deterministically into the blocked terminal — where accept-blocked
    silently drops a correct subtask's commits, strictly worse than any
    near-miss pass. No token rule can separate "ran the command
    mid-paraphrase" from "ran an adjacent fragment of the paraphrase";
    contiguity resolves the undecidable remainder toward keeping work.

    The gate's honest contract is therefore: it catches "never touched
    the declared command", NOT "ran a variant of it". The accepted
    near-miss residual class (documented in DESIGN §"A declared command
    must also have been executed"): a parent sub-command
    (`barnacle recon` for "barnacle recon browser"), a flag-dropped
    variant (`pnpm lint` for "pnpm lint --fix" — its mirror, adding
    `--dry-run`, already passed the forward arm), `--help`-probing a
    declared literal, and a deliberately-typed adjacent word pair
    ("test suite") — the same §9 concession that declines to gate on
    test content a stuck worker could weaken. Still rejected: bare
    single tokens, non-adjacent fragments, and tokens scattered across
    different segments (NO cross-segment union — `pnpm install && ls
    test` never covers "pnpm test"). Glued punctuation (a declared
    entry quoting the command as `` `pnpm test` ``) still false-alarms;
    worst case is the re-drive then the blocked terminal, adjudicated
    by accept-blocked. Pure JSON→JSON list/set logic, no NL parsing.
    Free (empty) when the subtask declares nothing — the ~95% case."""
    declared = [
        rc for rc in (subtask.get("runs_commands") or [])
        if isinstance(rc, str) and rc.strip()
    ]
    if not declared:
        return []
    exec_sets: list[frozenset[str]] = []
    exec_lists: list[list[str]] = []
    for cmd in executed:
        for raw in _BLT_SEG_RE.split(cmd):
            seg = _BLT_SEG_LEAD_RE.sub("", raw.strip())
            if not seg:
                continue
            toks = _command_token_list(seg)
            if toks:
                exec_sets.append(frozenset(toks))
                exec_lists.append(toks)

    def _contiguous_sublist(needle: list[str], hay: list[str]) -> bool:
        n = len(needle)
        return n >= 2 and any(
            hay[i:i + n] == needle for i in range(len(hay) - n + 1))

    issues: list[str] = []
    for rc in declared:
        rc_tokens = _command_tokens(rc)
        rc_list = _command_token_list(rc)
        covered = bool(rc_tokens) and any(
            rc_tokens <= es or _contiguous_sublist(el, rc_list)
            for es, el in zip(exec_sets, exec_lists))
        if not covered:
            issues.append(
                f"DECLARED_CMD_UNRUN: this subtask declared it runs {rc!r} "
                "(runs_commands), but no Bash command its worker actually "
                "executed matches it. Run the command and act on its real "
                "output; if it cannot run in this environment, return "
                "status 'blocked' naming what it needs instead of "
                "'complete'.")
    return issues


def check_planner_output(
    result: dict, repo_root: Path, domain: str,
) -> list[str]:
    """Rich mechanical checks on a single planner domain's output."""
    issues: list[str] = []
    subtasks = result.get("subtasks", [])
    prefix = CATEGORY_ABBREV.get(domain, "") + "-"

    for s in subtasks:
        sid = s.get("id", "?")
        for f in s.get("files_likely_touched", []):
            full = repo_root / f
            if not full.exists() and not full.parent.exists():
                has_ancestor = False
                ancestor = full.parent.parent
                while ancestor != repo_root and ancestor != ancestor.parent:
                    if ancestor.exists():
                        has_ancestor = True
                        break
                    ancestor = ancestor.parent
                if not has_ancestor:
                    issues.append(
                        f"PHANTOM_PATH: {sid} lists {f!r} in "
                        "files_likely_touched but no ancestor "
                        "directory exists under the repo root")

    all_ids = {s["id"] for s in subtasks}
    for s in subtasks:
        sid = s.get("id", "?")
        for dep in s.get("depends_on", []) or []:
            if dep.startswith(prefix) and dep not in all_ids:
                issues.append(
                    f"DANGLING_DEP: {sid} depends_on {dep!r} which "
                    "does not exist in this plan")

    for s in subtasks:
        if not (s.get("success_criteria_seed") or "").strip():
            issues.append(
                f"EMPTY_CRITERIA: {s.get('id', '?')} has empty "
                "success_criteria_seed")

    for s in subtasks:
        if s.get("size") == "large":
            issues.append(
                f"OVERSIZED: {s.get('id', '?')} has size='large' "
                "— split it")

    # Track each file's owners as (id, cofile_cluster) so a *deliberate* sub-file
    # split (DESIGN §5½ (P1) *Sub-file*) does not trip the advisory: region
    # children of one file all carry the same `_cofile_cluster` marker, and their
    # same-file overlap is intentional co-ownership, not a planning smell. The
    # warning still fires when the owners are NOT a single coherent cluster — an
    # accidental overlap between unrelated subtasks, or two different clusters on
    # one file.
    file_owners: dict[str, list[tuple[str, str | None]]] = {}
    for s in subtasks:
        for f in s.get("files_likely_touched", []):
            file_owners.setdefault(f, []).append(
                (s.get("id", "?"), s.get("_cofile_cluster")))
    for f, owners in file_owners.items():
        if len(owners) <= 1:
            continue
        clusters = {c for (_sid, c) in owners}
        # A single non-None cluster shared by every owner is a deliberate split.
        if len(clusters) == 1 and None not in clusters:
            continue
        issues.append(
            f"INTRA_DOMAIN_OVERLAP: {f!r} touched by "
            f"{[sid for (sid, _c) in owners]} — consider merging or splitting")

    for s in subtasks:
        bad = [f for f in (s.get("files_likely_touched") or [])
               if isinstance(f, str) and _is_protected_path(f)]
        if bad:
            issues.append(
                f"PROTECTED_PATH: {s.get('id', '?')} lists "
                f"protected path(s) {bad}")

    # Intra-domain cycle via simple DFS.
    deps: dict[str, list[str]] = {}
    for s in subtasks:
        sid = s.get("id", "?")
        deps[sid] = [
            d for d in (s.get("depends_on") or [])
            if d.startswith(prefix) and d in all_ids]
    WHITE, GRAY, BLACK = 0, 1, 2
    color: dict[str, int] = {sid: WHITE for sid in all_ids}
    cycle_found = False
    for start in all_ids:
        if color[start] != WHITE:
            continue
        stack = [start]
        while stack and not cycle_found:
            node = stack[-1]
            if color[node] == WHITE:
                color[node] = GRAY
                for dep in deps.get(node, []):
                    if color.get(dep) == GRAY:
                        cycle_found = True
                        break
                    if color.get(dep) == WHITE:
                        stack.append(dep)
            else:
                color[node] = BLACK
                stack.pop()
    if cycle_found:
        issues.append(
            "INTRA_DOMAIN_CYCLE: dependency cycle detected within "
            f"this domain ({domain})")

    issues.extend(_check_migration_surface(subtasks, repo_root))
    issues.extend(_check_migration_targets_declared(subtasks))

    # `decomposition_quality` and `task_understanding` are retained in the
    # planner schema as advisory self-reports, but neither is a gating axis
    # here anymore (DESIGN §5½, §8): the independent `fit_judge` in
    # _recursive_decompose is the authoritative decomposition gate, and the
    # independent `task_coverage_judge` (phase_planning_coverage_gate) is the
    # authoritative coverage gate — both remove the self-grading bias of
    # letting the planner grade its own decomposition/coverage.
    return issues


_TAG_OP_TARGET = {
    "add_provide": "added_provides",
    "drop_require": "dropped_requires",
    "unresolvable": "unresolvable",
    "conditional_drop": "conditional_drops",
}


def _expand_reconciler_output(out: dict) -> dict:
    """Fan the flattened worker output back into leerie's nine-array shape.

    The wire schema is flattened so it compiles under
    `--dangerously-force-strict-output` (see `SCHEMAS["reconciler"]`), but every
    consumer downstream — `check_reconciler_output`, `_apply_reconciler_output`,
    `_validate_must_include`, the cycle diagnostics — was written against the
    nine arrays and stays that way. This is the only seam that knows both.

    Two structural facts the flattening gives up, restored here:

    * **`tag_ops` is discriminated, not typed.** One array with an `op` enum
      replaced four isomorphic `{sid, tag, reason}` object shapes. An
      unrecognised `op` is dropped rather than guessed — silently misfiling a
      resolution action would mutate the plan in a way the operator never sees.
    * **`added_requires` is no longer nested inside its subtask.** The binding
      is by `sid` now, so an entry naming a subtask that does not exist in this
      output has nothing to attach to. Those are dropped and counted; the
      caller logs the count, because a dangling requires means the worker
      believed in a subtask it did not emit.

    Returns a NEW dict; the input is not mutated (the raw worker output is
    persisted as telemetry and must stay as-emitted).
    """
    expanded: dict = {
        "renames": list(out.get("renames") or []),
        "dependency_edges": list(out.get("dependency_edges") or []),
        "merged_subtasks": list(out.get("merged_subtasks") or []),
        "added_provides": [],
        "dropped_requires": [],
        "unresolvable": [],
        "conditional_drops": [],
        "added_subtasks": [],
        "confidence": out.get("confidence") or {},
    }

    for entry in out.get("tag_ops") or []:
        if not isinstance(entry, dict):
            continue
        # Case-insensitive: constrained decoding does not guarantee the
        # capitalisation of an enum value, and it fails silently when it drifts.
        target = _TAG_OP_TARGET.get(str(entry.get("op", "")).strip().lower())
        if target is None:
            continue
        row = {"sid": entry.get("sid", ""), "reason": entry.get("reason", "")}
        if target != "conditional_drops":
            row["tag"] = entry.get("tag", "")
        expanded[target].append(row)

    # Re-bind requires to their subtask by sid.
    by_sid: dict[str, dict] = {}
    for sub in out.get("added_subtasks") or []:
        if not isinstance(sub, dict) or not sub.get("id"):
            continue
        copy_of = dict(sub)
        copy_of["requires"] = []
        by_sid[str(sub["id"])] = copy_of
        expanded["added_subtasks"].append(copy_of)

    dangling: list[str] = []
    for req in out.get("added_requires") or []:
        if not isinstance(req, dict):
            continue
        sub = by_sid.get(str(req.get("sid", "")))
        if sub is None:
            dangling.append(f"{req.get('sid')!r}:{req.get('tag')!r}")
            continue
        item = {"tag": req.get("tag", ""),
                "extent": str(req.get("extent", "")).strip().lower()}
        if req.get("reason"):
            item["reason"] = req["reason"]
        sub["requires"].append(item)
    expanded["_dangling_requires"] = dangling
    return expanded


# The three build/lint/test axis names, in the spelling the conformer's
# structured output and the base-health baseline both use ("tests", plural).
# `resolve_blt` keys the test axis "test" (singular); `_AXIS_CMD_KEY` bridges
# the two and is the only place that mapping should live.
_BLT_AXES: frozenset[str] = frozenset({"build", "lint", "tests"})

# `resolve_blt` keys the test axis "test" (singular); the conformer's
# structured output and the base-health baseline key it "tests" (plural).
# This is the ONE place that mapping lives — a bare `blt.get("tests")` is
# always None and silently skips the test suite, which is the bug this map
# exists to prevent.
_AXIS_CMD_KEY: dict[str, str] = {"build": "build", "lint": "lint",
                                 "tests": "test"}


def _expand_conformer_output(out: dict) -> dict:
    """Fan the flattened conformer wire output back into the four arrays
    every consumer (`_validate_conformance_result`, `_summarize_residuals`,
    `_final_conformance_payload`) was written against.

    `SCHEMAS["conformer"]` is flattened for grammar compilation (N29): the
    isomorphic `rule_violations_fixed`/`rule_violations_residual` pair
    collapses to one `rule_violations` array keyed by `status`, and
    `docs_updates`/`tests_updates` collapses to one `file_updates` array
    keyed by `kind`. An entry with an unrecognised discriminator is dropped
    rather than guessed, same discipline as `_expand_reconciler_output`'s
    `tag_ops` handling.

    Returns a NEW dict; the input is not mutated (the raw worker output is
    persisted as telemetry and must stay as-emitted). Non-dict/non-list
    input for either flattened array degrades to an empty expansion rather
    than raising, matching `_expand_reconciler_output`'s `or []` tolerance.
    """
    expanded = dict(out)
    fixed: list[dict] = []
    residual: list[dict] = []
    for item in out.get("rule_violations") or []:
        if not isinstance(item, dict):
            continue
        status = str(item.get("status", "")).strip().lower()
        if status == "fixed":
            fixed.append({"rule": item.get("rule", ""),
                          "fix": item.get("fix", ""),
                          "evidence": item.get("evidence", "")})
        elif status == "residual":
            row = {"rule": item.get("rule", ""),
                   "why_not_fixed": item.get("why_not_fixed", "")}
            # `axis` is carried through only when the worker supplied a
            # valid enum value. This rebuild is by-key, so a field omitted
            # here is silently dropped no matter what the schema declares —
            # which is how a declared-but-dead field ships (CLAUDE.md: the
            # conformer's evidence copy "must be READ, not merely
            # declared"). Normalising here rather than at the read site
            # keeps `_conformance_clean` a pure set comparison.
            axis = str(item.get("axis", "")).strip().lower()
            if axis in _BLT_AXES:
                row["axis"] = axis
            residual.append(row)
    expanded["rule_violations_fixed"] = fixed
    expanded["rule_violations_residual"] = residual

    docs: list[dict] = []
    tests: list[dict] = []
    for item in out.get("file_updates") or []:
        if not isinstance(item, dict):
            continue
        kind = str(item.get("kind", "")).strip().lower()
        row = {"path": item.get("path", ""), "reason": item.get("reason", "")}
        if kind == "docs":
            docs.append(row)
        elif kind == "tests":
            tests.append(row)
    expanded["docs_updates"] = docs
    expanded["tests_updates"] = tests
    return expanded


def check_reconciler_output(
    output: dict, plans: list[dict],
) -> list[str]:
    """Mechanical checks on the reconciler's output beyond the existing
    acyclicity / size / unresolved gates."""
    issues: list[str] = []

    all_provides: set[str] = set()
    for plan in plans:
        for s in plan.get("subtasks", []):
            all_provides.update(s.get("provides", []) or [])

    for r in output.get("renames", []) or []:
        if r.get("to") and r["to"] not in all_provides:
            issues.append(
                f"RENAME_TO_NOWHERE: rename on {r.get('sid', '?')} "
                f"from {r.get('from', '?')!r} to {r['to']!r} but "
                "no subtask provides that tag")

    for s in output.get("added_subtasks", []) or []:
        sid = s.get("id", "")
        if sid and not any(sid.startswith(p) for p in _ID_PREFIXES):
            issues.append(
                f"BAD_PREFIX: added subtask {sid!r} does not start "
                "with a valid prefix")
        if sid and sid in (s.get("depends_on") or []):
            issues.append(
                f"SELF_DEP: added subtask {sid!r} depends on itself")

    # The reconciler's `reconciliation` self-score is NO LONGER a gating axis
    # (DESIGN §8 *Independent adversarial verification*): the authoritative
    # wiring gate is the deterministic `check_plan_wiring` plus the independent
    # `wiring_judge` (phase_wiring_gate). The `confidence` object stays emitted
    # and schema-required (the §8 discipline record), just not gated on here.
    return issues


def _normalize_artifact_path(path: str) -> str:
    """Canonicalize a planner- or judge-authored repo-relative path for
    comparison: native separators to `/`, leading `./` and `/` stripped.

    Deliberately no case folding — the repos leerie runs against are
    checked out on case-sensitive filesystems in the container, so
    folding would make genuinely distinct paths compare equal."""
    normalized = path.strip().replace(os.sep, "/")
    while normalized.startswith("./"):
        normalized = normalized[2:]
    return normalized.lstrip("/")


def _paths_designate_same_file(a: str, b: str) -> bool:
    """True when two independently-authored repo-relative paths name the same
    file even though one carries a repo-root prefix the other omits.

    Both sides are authored without coordination — by two planners, or by a
    planner and `git diff --name-only`. When the repo leerie is pointed at is
    itself a subdirectory of the enclosing checkout, one side writes
    `fema-demo/server/x.ts` and the other `server/x.ts`. Plain set
    intersection reads those as disjoint. That is what let run `bfba2c88`
    implement the same five subtasks twice: its overlap judge recorded that
    the duplication was real but "undetected by design of the input data",
    because no `files_likely_touched` entry literally matched its twin.

    Compared on whole path components, never as a raw string suffix, so
    `server/x.ts` matches `fema-demo/server/x.ts` but never
    `other-server/x.ts` and `x.ts` never matches `prefix-x.ts`."""
    pa = _normalize_artifact_path(a).split("/")
    pb = _normalize_artifact_path(b).split("/")
    if not pa[-1] or not pb[-1]:
        return False
    n = min(len(pa), len(pb))
    return pa[-n:] == pb[-n:]


def _declared_path_covers(declared: str, touched: str) -> bool:
    """True when a planner's `files_likely_touched` entry designates a real
    diff path — the same file (modulo a repo-root prefix, via
    `_paths_designate_same_file`), or a DIRECTORY-shaped declaration
    containing it.

    The directory arm is not hypothetical: run `5fa2052b`'s `config-005`
    ("run biome once across the whole tree") declared `['scripts', 'server']`,
    and a file-only comparison reads a tree-wide reformat as touching nothing
    it declared."""
    if _paths_designate_same_file(declared, touched):
        return True
    d = [p for p in _normalize_artifact_path(declared).split("/") if p]
    t = [p for p in _normalize_artifact_path(touched).split("/") if p]
    if not d:
        return False
    # A repo-root prefix can sit on the DECLARATION (`fema-demo/src` vs a diff
    # path of `src/pages/y.tsx`), on the diff path (`server` vs
    # `fema-demo/server/routes/x.ts`), or on neither — so drop leading
    # components from the declaration and look for what remains as a
    # contiguous component run in the diff path. Matching loosely is the safe
    # direction for an advisory: a missed match costs a warning nobody needed,
    # a spurious one trains the operator to ignore the channel.
    for start in range(len(d)):
        tail = d[start:]
        if len(tail) >= len(t):
            continue
        if any(t[i:i + len(tail)] == tail
               for i in range(len(t) - len(tail) + 1)):
            return True
    return False


def _coverage_citation_clears(defect: dict, repo_root: Path) -> str | None:
    """DESIGN §8 *Location is not coverage*. Returns the accepted citation as
    `"<file>: <assertion>"` when a `dropped_change` defect proves the dropped
    behavior still lives in the merged tree, or `None` when the defect gates.

    A merge that drops a *duplicate* is textually identical to one that drops
    the only copy — both remove content present in a parent — so the parent
    diffs cannot distinguish them. Measured: this gate killed a run at wave 3
    with 28 subtasks complete over a dropped `describe` block whose assertions
    were a strict subset of a separate file written 4h45m earlier.

    Only `dropped_change` is eligible: the other four kinds
    (`reintroduced_conflict`, `call_site_mismatch`, `semantic_regression`,
    `incomplete_resolution`) describe breakage *introduced* by the merge, which
    coverage living elsewhere cannot excuse.

    The file-existence test is mechanical and deliberate — the citation is the
    only thing standing between a real lossy merge and a silent downgrade on
    the one gate with no operator bypass, so a hallucinated path must not buy
    one. `searched` is not consulted: a judge that sets it without supplying a
    usable file/assertion has shown nothing."""
    if defect.get("kind") != "dropped_change":
        return None
    cite = defect.get("coverage_elsewhere")
    if not isinstance(cite, dict):
        return None
    rel = _normalize_artifact_path(str(cite.get("file") or ""))
    assertion = str(cite.get("assertion") or "").strip()
    if not rel or not assertion:
        return None
    try:
        resolved = (repo_root / rel).resolve()
        # A `..` segment survives _normalize_artifact_path (it only strips
        # leading `./` and `/`), so confine the citation to the merged tree.
        resolved.relative_to(repo_root.resolve())
    except (ValueError, OSError):
        return None
    if not resolved.is_file():
        return None
    return f"{rel}: {assertion}"


def _partition_integration_defects(
        judge_result: dict, repo_root: Path) -> tuple[list[str], list[str]]:
    """Split an `integration_judge` result's defects into
    `(gating_issues, advisory_notes)`.

    **Pure, and it must stay pure.** Its adapter inside `integrate_wave`
    (`_check_integration`) is invoked TWICE per judge result: once by
    `_run_checked_loop` as its `check=`, and again after the loop to decide the
    repair. Any side effect on this path therefore fires at least twice per
    defect, and up to `judgment_check_rounds` + 1 times when a `WorkerError`
    retry re-invokes the judge. So the advisory text is *returned*, and the
    caller logs it exactly once.

    Both filters live here so neither is duplicated across the two call sites:
    the pre-existing anti-gaming rule (a defect gates only with a concrete
    scenario and a location named) and the DESIGN §8 *Location is not coverage*
    citation downgrade."""
    gating, advisory = _integration_defect_records(judge_result, repo_root)
    return [_integration_defect_label(d) for d in gating], advisory


def _integration_defect_records(judge_result: dict, repo_root: Path
                                ) -> tuple[list[dict], list[str]]:
    """`(gating_defects, advisory_notes)` of an `integration_judge` result —
    the typed form `_partition_integration_defects` labels. The same two
    filters: a defect gates only with a concrete scenario and a location
    named, and a cited equivalent coverage downgrades it to advisory."""
    gating: list[dict] = []
    advisory: list[str] = []
    for d in judge_result.get("defects") or []:
        if not isinstance(d, dict):
            continue
        scenario = (d.get("concrete_scenario") or "").strip()
        location = (d.get("location") or "").strip()
        if not scenario or not location:
            continue
        cleared = _coverage_citation_clears(d, repo_root)
        if cleared:
            advisory.append(
                f"({d.get('kind')}) {location}: {scenario} — "
                f"equivalent coverage cited at {cleared}")
            continue
        gating.append({"kind": d.get("kind", "behavioral_defect"),
                       "location": location, "concrete_scenario": scenario,
                       "why_broken": d.get("why_broken", "")})
    return gating, advisory


def _integration_defect_label(d: dict) -> str:
    return (f"INTEGRATION_DEFECT ({d.get('kind', 'behavioral_defect')}) "
            f"{d.get('location', '')}: {d.get('concrete_scenario', '')} — "
            f"{d.get('why_broken', '')}")


def check_overlap_judge_output(
    output: dict, plans: list[dict], repo_root: Path,
) -> list[str]:
    """Mechanical checks on the overlap judge's collision list."""
    issues: list[str] = []
    collisions = output.get("collisions", []) or []

    by_id: dict[str, dict] = {}
    for plan in plans:
        for s in plan.get("subtasks", []):
            by_id[s["id"]] = s

    # Files the plan intends to create or rewrite count as real
    # artifacts alongside the ones already on disk. The judge's charter
    # is subtasks that both *create* the same exported artifact
    # (`prompts/plan_overlap_judge.md`), so a not-yet-existing path is
    # its canonical subject rather than evidence of a hallucination —
    # a repo-only existence test rejects the primary case and, because
    # the prompt ties the confidence floor to artifact verifiability,
    # also pushes the judge to self-downgrade below the
    # LOW_CONFIDENCE threshold on findings that were correct.
    planned_files: set[str] = set()
    for plan in plans:
        for s in plan.get("subtasks", []):
            for f in s.get("files_likely_touched", []) or []:
                planned_files.add(_normalize_artifact_path(f))

    for c in collisions:
        # `artifact` is a LOGICAL name the prompt asks for in prose ("the
        # colliding exported artifact, e.g. 'WidgetFrame component'"), so
        # Python must not mine paths out of it. The judge names the paths
        # itself in `artifact_paths` and this check does plain set
        # membership on already-structured data — CLAUDE.md's
        # language-to-JSON rule ("never regex or hand-parsing in Python...
        # never on an LLM's response").
        #
        # History: this used to path-check `artifact` directly, which
        # false-positived every descriptive name — run e2882da6 emitted 6
        # spurious issues on an otherwise-valid emission, and the retry
        # they forced produced the duplicate-pair emission that killed the
        # run. Tokenizing the string fixed the false positives but was
        # still hand-parsing an LLM's prose; this replaces it.
        #
        # An empty `artifact_paths` is legitimate, not a defect: a purely
        # logical artifact has no path, and there is then nothing to
        # verify.
        paths = c.get("artifact_paths") or []
        if not paths:
            continue
        if any(_normalize_artifact_path(p) in planned_files
               or (repo_root / p).exists() for p in paths):
            continue
        issues.append(
            f"PHANTOM_ARTIFACT: collision "
            f"{c.get('a_sid', '?')} <-> {c.get('b_sid', '?')} "
            f"names artifact path(s) {sorted(paths)!r} which do not "
            "exist in the repo and are not in any subtask's "
            "files_likely_touched")

    # DUPLICATE_PAIR — the same pair emitted twice with *different*
    # effects (see `_collision_effect`). Reported here, inside the retry
    # loop, rather than at `_validate_overlap_judge_output`, which sits
    # outside it and can only die(). Effect-identical repeats are the
    # legitimate multi-artifact shape and are coalesced by the validator,
    # so they are deliberately not flagged.
    effects_by_pair: dict[tuple, list[dict]] = {}
    for c in collisions:
        pair = tuple(sorted(
            s for s in (c.get("a_sid"), c.get("b_sid")) if s))
        if len(pair) == 2:
            effects_by_pair.setdefault(pair, []).append(c)
    for pair, rows in sorted(effects_by_pair.items()):
        if len(rows) < 2:
            continue
        effects = {_collision_effect(r) for r in rows}
        if len(effects) < 2:
            continue
        # `LABEL: subject — detail`, matching every other issue string:
        # `_issue_signature` splits on the first em dash to build the
        # oscillation-guard key, so everything that can vary between
        # rounds (the row count, the effect list) must sit AFTER it or a
        # recurrence of the same conflict reads as a new issue.
        issues.append(
            f"DUPLICATE_PAIR: collision {pair[0]} <-> {pair[1]} — "
            f"emitted {len(rows)} times with conflicting effects "
            f"{sorted(str(e) for e in effects)}. A pair may appear more "
            "than once ONLY when every row resolves the same way (one "
            "row per overlapping artifact); rows that drop different "
            "sids, or mix a drop with a merge, cannot all hold. Emit a "
            "single resolution for this pair, or `unresolvable`")

    for c in collisions:
        a = by_id.get(c.get("a_sid", ""), {})
        b = by_id.get(c.get("b_sid", ""), {})
        # Normalized: both sides are planner-authored strings, so
        # `./src/x.ts` and `src/x.ts` must not read as disjoint.
        a_files = {_normalize_artifact_path(f)
                   for f in (a.get("files_likely_touched", []) or [])}
        b_files = {_normalize_artifact_path(f)
                   for f in (b.get("files_likely_touched", []) or [])}
        # A SHARED `provides` TAG IS ITS OWN GROUNDING, so this check must not
        # reject a collision that has one. Two subtasks declaring the same tag
        # are a defect whether or not their paths intersect (see
        # `check_duplicate_providers`'s no-overlap tier) — and for a file
        # neither subtask has created yet, each planner invents the path, so
        # they essentially never intersect. Requiring intersection here
        # actively suppressed correct findings: run `3e65e793`'s judge saw
        # feat-007/bugfix-006/test-003 all declare
        # `captcha-inject-submit-primitive-tested` and recorded that it was
        # "withdrawing these per the NO_FILE_OVERLAP signal". Three workers
        # then wrote three tests for one primitive, and the next run deleted
        # one as vacuous and folded another.
        shared_tags = ({t for t in (a.get("provides") or []) if t}
                       & {t for t in (b.get("provides") or []) if t})
        # Path comparison is component-wise so a repo-root prefix on one side
        # does not read as disjoint (`_paths_designate_same_file`).
        files_intersect = any(_paths_designate_same_file(fa, fb)
                              for fa in a_files for fb in b_files)
        if a_files and b_files and not files_intersect and not shared_tags:
            issues.append(
                f"NO_FILE_OVERLAP: collision "
                f"{c.get('a_sid', '?')} <-> {c.get('b_sid', '?')} "
                "but they share no files_likely_touched")

    all_requires_tags: set[str] = set()
    for plan in plans:
        for s in plan.get("subtasks", []):
            for r in s.get("requires", []) or []:
                tag = r.get("tag", "") if isinstance(r, dict) else ""
                if tag:
                    all_requires_tags.add(tag)
    for c in collisions:
        dropped_sid = None
        if c.get("resolution") == "drop_a":
            dropped_sid = c.get("a_sid")
        elif c.get("resolution") == "drop_b":
            dropped_sid = c.get("b_sid")
        if dropped_sid and dropped_sid in by_id:
            dropped_provides = set(
                by_id[dropped_sid].get("provides", []) or [])
            # A tag another SURVIVING subtask still provides is not orphaned
            # by this drop. Without this subtraction the check fires hardest
            # on the case it should permit: dropping one half of a
            # duplicate-provider pair, where the survivor provides the
            # identical tag BY DEFINITION. Measured over the two runs in the
            # 0.28.0 corpus that carried duplicate producers, 3 of 8
            # candidate drops were flagged purely this way — run `bfba2c88`
            # withdrew its findings and shipped five subtasks implemented
            # twice, recording "Reversed course" after the graph check
            # rejected the correct resolution.
            #
            # The remaining flags are genuine and still fire: `3e65e793`'s
            # bugfix-002 provides `submit-step-transition-poll-fixed`, which
            # no other subtask provides, so dropping it really does orphan
            # bugfix-007. That case needs a merge-and-rewire resolution, not
            # a weaker check.
            still_provided: set[str] = set()
            for sid, s in by_id.items():
                if sid == dropped_sid:
                    continue
                still_provided |= {t for t in (s.get("provides") or []) if t}
            orphaned = (dropped_provides & all_requires_tags) - still_provided
            if orphaned:
                issues.append(
                    f"DROP_BREAKS_GRAPH: dropping {dropped_sid!r} "
                    f"would remove provides tags {orphaned} that "
                    "other subtasks require and no surviving subtask "
                    "provides")

    # Code-enforced backstop for a real incident (DESIGN §5½ *Sub-file*):
    # two subtasks sharing the same non-null `_cofile_cluster` are, by
    # construction, disjoint-region siblings of one deliberate P1 sub-file
    # split — their line ranges are pre-verified non-overlapping and their
    # union covers the whole file (`_check_intra_file_surface`). The judge
    # is told this in its prompt ("What is NOT a collision"), but a prompt
    # rule is advisory (§12) — an `unresolvable` verdict between cluster
    # siblings is always wrong regardless of what the judge's free-text
    # reasoning says, so it's flagged here as a mechanical issue and fed
    # back through the existing retry loop (`phase_overlap_judge` passes
    # `make_feedback_prompt`, unlike the single-pass gates) rather than
    # trusted to self-correct only from prompt wording.
    for c in collisions:
        if c.get("resolution") != "unresolvable":
            continue
        a = by_id.get(c.get("a_sid", ""), {})
        b = by_id.get(c.get("b_sid", ""), {})
        a_cluster = a.get("_cofile_cluster")
        b_cluster = b.get("_cofile_cluster")
        if a_cluster and a_cluster == b_cluster:
            issues.append(
                f"SPURIOUS_COFILE_COLLISION: {c.get('a_sid', '?')} <-> "
                f"{c.get('b_sid', '?')} share _cofile_cluster "
                f"{a_cluster!r} — same-file/different-region siblings of "
                "a deliberate sub-file split can never collide; retract "
                "this finding")

    # The overlap judge's `judgment` self-score is NO LONGER a gating axis
    # (DESIGN §8 *Independent adversarial verification*): this worker IS an
    # adversarial judge grading its own judgment, the purest self-scoring
    # case, and a self-score cannot substitute for an independent check. The
    # authoritative gate is the deterministic PHANTOM_ARTIFACT /
    # NO_FILE_OVERLAP / DROP_BREAKS_GRAPH / DUPLICATE_PAIR checks above
    # plus `_validate_overlap_judge_output`'s merge-feasibility backstop
    # and keep-and-delete gate. The
    # `confidence` object stays emitted and schema-required, just not gated
    # on here.
    return issues


def check_provision_output(
    result: dict, repo_root: Path,
) -> list[str]:
    """Mechanical checks on the provision LLM fallback's recipe."""
    issues: list[str] = []
    recipe = result.get("recipe", []) or []

    _LOCKFILE_TO_PM: dict[str, str] = {
        "pnpm-lock.yaml": "pnpm", "yarn.lock": "yarn",
        "package-lock.json": "npm", "bun.lockb": "bun",
        "bun.lock": "bun", "uv.lock": "uv",
        "poetry.lock": "poetry", "Pipfile.lock": "pipenv",
    }
    detected_pms: set[str] = set()
    for lf, pm in _LOCKFILE_TO_PM.items():
        if (repo_root / lf).exists():
            detected_pms.add(pm)

    for i, entry in enumerate(recipe):
        wd = entry.get("working_dir", ".")
        if wd != "." and not (repo_root / wd).is_dir():
            issues.append(
                f"MISSING_WORKDIR: recipe[{i}] working_dir="
                f"{wd!r} does not exist")
        cmd = entry.get("command", [])
        if cmd and cmd[0] in ("npm", "yarn", "pnpm", "bun"):
            if detected_pms and cmd[0] not in detected_pms:
                issues.append(
                    f"WRONG_PM: recipe uses {cmd[0]!r} but repo "
                    f"has lockfile(s) for {detected_pms}")

    has_lockfiles = any(
        (repo_root / lf).exists() for lf in _LOCKFILE_TO_PM)
    if not recipe and has_lockfiles:
        issues.append(
            "EMPTY_RECIPE: recipe is empty but repo has lockfile(s)")

    # The provision worker's `recipe_correctness` self-score is NO LONGER a
    # gating axis (DESIGN §8 *Independent adversarial verification*): the
    # authoritative gate is the independent `provision_judge`
    # (phase_provision_gate), which attacks the recipe against the actual
    # image/runtime. The deterministic MISSING_WORKDIR / WRONG_PM / EMPTY_RECIPE
    # checks above stay (mechanical, not self-graded). The `confidence` object
    # stays emitted and schema-required, just not gated on here.
    return issues


def check_integrator_output(result: dict) -> list[str]:
    """Mechanical checks for the integrator.

    The resolution self-score gate was removed — integration_judge is the
    authoritative behavioral-integration gate (DESIGN §8). The confidence
    object is still emitted (§8 falsifier/gap discipline record)."""
    # No checks — integration_judge is the gate. This function remains as
    # the check callback slot for _run_checked_loop in integrate_wave.
    return []


# Mechanical-check labels that are reported but must NOT drive a re-drive.
# Matching leerie's OWN label prefixes is set membership over strings this
# module authored, not interpretation of a worker response, so it sits outside
# the *Language-to-JSON* prohibition -- `phase_finalize` already partitions
# `symptom_findings` the same way.
_ADVISORY_ISSUES = ("NO_PLANNED_FILES_TOUCHED",)


def _gating_issues(issues: list[str]) -> list[str]:
    """The subset of `check_implementer_output` labels that justify a retry."""
    return [i for i in issues if not i.startswith(_ADVISORY_ISSUES)]


def check_implementer_output(
    result: dict, subtask: dict, actual_files: set[str],
) -> list[str]:
    """Mechanical checks on an implementer's complete result.

    `subtask` is required to be a dict and the contract is enforced rather
    than accommodated. The tempting accommodation — `subtask = subtask or {}`
    — is measurably worse than the crash: an empty dict yields an empty
    `planned`, so `NO_PLANNED_FILES_TOUCHED` can never fire and a caller's
    mistake silently disables a check instead of announcing itself. That is
    the inert-mechanism failure class DESIGN §9 exists to prevent, so this
    raises early with a message naming the parameter rather than throwing an
    incidental `AttributeError` further down (cf.
    `tests/test_phase_planning_coverage_gate.py::TestProgrammingErrorsPropagate`:
    a programming error must not be reported as an advisory degrade).
    """
    if not isinstance(subtask, dict):
        raise TypeError(
            f"check_implementer_output: subtask must be a dict, got "
            f"{type(subtask).__name__} — do NOT 'fix' this by defaulting to "
            f"{{}}, which silently disables NO_PLANNED_FILES_TOUCHED")
    issues: list[str] = []
    planned = set(subtask.get("files_likely_touched", []) or [])

    if planned and actual_files:
        if not (actual_files & planned):
            # ADVISORY, not gating. `files_likely_touched` is a planner GUESS,
            # and `_clobbered_owned_files` already documents it as "advisory
            # and NOT used because the implementer may commit outside it" --
            # which is exactly as true here. Re-driving on it asks a worker to
            # match a prediction rather than to do the work: measured,
            # 1b9b52f5/test-007 was re-driven into a pure-rename commit
            # (+$0.49, 2.3 min) whose only content was moving a test from the
            # repo convention to the planner path
            # (tests/test_advisory_signals_match_their_status.py). The label is still emitted
            # so the operator sees it; `_ADVISORY_ISSUES` keeps it out of the
            # retry decision.
            issues.append(
                f"NO_PLANNED_FILES_TOUCHED: none of the planned "
                f"files were modified — planned: "
                f"{sorted(planned)[:5]}")

    # OWNED_REGION_FILE_ESCAPE — GATING, unlike NO_PLANNED_FILES_TOUCHED above.
    # The distinction is the provenance of the expectation, not its shape:
    # `files_likely_touched` is a planner GUESS, so re-driving on it asks a
    # worker to match a prediction. `owned_region["file"]` is computed by
    # `_subfile_split` from a tree-sitter tiling of one file the subtask was
    # deliberately confined to — there is no false-positive surface, because a
    # region child touching another path is by construction outside its
    # mandate.
    #
    # Corrective, never fatal. The caller routes a gating issue through
    # `_format_check_feedback` -> `note` -> `continuation=True`, bounded by
    # `implementer_confidence_retries`, after which it degrades to advisory.
    # It must NOT be moved into `check_diff_scope`'s fatal return, whose string
    # reaches `fail("broken", ...)` and is non-retryable: replayed against run
    # 719c2a26 a fatal rule kills 11 of 12 subtasks, converting a coverage gap
    # into a total run kill — and those violations were children OBEYING an
    # inherited criterion they could not satisfy in region (DESIGN §5½ (P1)
    # *Sub-file*).
    owned_region = subtask.get("owned_region") or {}
    owned_file = owned_region.get("file")
    if owned_file and actual_files:
        escaped = sorted(f for f in actual_files if f != owned_file)
        if escaped:
            # The count is reported alongside the sample, not implied by it.
            # `NO_PLANNED_FILES_TOUCHED` above truncates to 5 bare, which is
            # fine for an ADVISORY nobody acts on; this string is fed back to
            # the implementer as the list to revert, so a silent cap tells a
            # worker that escaped into ten files to revert five and burn
            # another retry on the rest.
            sample = escaped[:5]
            more = "" if len(escaped) == len(sample) else \
                f" (showing {len(sample)} of {len(escaped)})"
            issues.append(
                f"OWNED_REGION_FILE_ESCAPE: this subtask owns only lines "
                f"{owned_region.get('start', '?')}-{owned_region.get('end', '?')} "
                f"of {owned_file}, but the commit touches "
                f"{len(escaped)} other path(s){more}: {sample} — revert them; "
                f"a sibling region subtask owns them")

    if result.get("status") == "complete":
        for cr in result.get("criteria_results", []) or []:
            # A criterion the implementer was never responsible for is not an
            # unmet one, and the worker declares that in `not_applicable` —
            # the structured channel the schema previously lacked.
            #
            # There was briefly a second channel here: substring-matching the
            # repo's resolved build/lint/test commands inside the criterion
            # text, as a backstop for a worker that forgot the flag. It is
            # gone. `criterion` is planner-authored prose, and the
            # *Language-to-JSON* rule is that Python never reads meaning out of
            # prose — its prescribed remedy being exactly "the owning worker
            # must surface it as a JSON field", which `not_applicable` is. A
            # spec sentence had been written asserting the match was "against
            # resolved config values, not worker prose"; the needle was config,
            # the haystack was prose, and the sentence authorised the code
            # rather than deriving from it.
            #
            # The residual risk is one re-drive when a worker omits the flag —
            # the behaviour before any of this existed, so not a regression.
            # `prompts/implementer.md` states the requirement plainly instead.
            if cr.get("not_applicable") is True:
                continue
            if cr.get("met") is False:
                issues.append(
                    f"UNMET_CRITERION: claims complete but "
                    f"criterion {cr.get('criterion', '?')!r} "
                    "is not met")
        issues.extend(check_production_evidence(result))

    return issues


def check_symptom_evidence(result: dict, sid: str,
                           fixes_reported_symptom: bool) -> list[str]:
    """DESIGN §9 *A stale finding is not a bug* — advisory.

    Run `fa979580`'s N18 subtask "fixed" a leak that #190 had already fixed
    before the run began, and shipped an event-loop stall doing it. Nothing
    asked whether the reported symptom still happened.

    **Advisory, deliberately.** These strings are logged and recorded, never
    fed to `check_implementer_output` — two differences from
    `check_production_evidence`, each with a reason. A retry does not
    surface a stale finding, it just asks the same worker again; and a
    second *gating* evidence field would stack retry pressure on top of the
    production-evidence gate, which is the cost this repo has already
    measured once (`_confidence_schema`'s docstring).

    **Scoped by the planner's declaration, not by the subtask id.** This used
    to read `sid.startswith("bugfix-")`, which is *Language-to-JSON* violated
    on an identifier rather than on prose — Python inferring the nature of the
    work from a string. Two mechanisms mint that prefix onto work that fixes
    no reported symptom: `_repair_prescribed_commands` synthesises
    `{prefix}{900+n:03d}` from the HOST subtask's domain (hence `bugfix-901`,
    a verification-only subtask), and a duplicate-provider / overlap merge
    re-homes a `feat-` subtask under a surviving `bugfix-` id. Measured across
    the run corpus, **10 of 10 findings were false positives** — every one of
    them a test, coverage or verification subtask that never had a symptom
    (tests/test_no_id_prefix_dispatch.py). A warning at that rate is one nobody
    reads, which costs more than the check is worth.

    `fixes_reported_symptom` is optional on the subtask schema and its absence
    means "no", so a plan that never fills it makes this check silent. That is
    the right trade for an ADVISORY check whose measured true-positive count is
    zero: silence beats noise, and the signal returns as soon as planners fill
    the field. Requiring it instead would risk the validity-rate collapse a
    required `severity` caused on `wiring_judge`.

    Takes the **orchestrator's** `sid`, not the worker's echoed
    `result["subtask_id"]`, which nothing in this module ever cross-checks
    against the real id. `sid` is now used only for message text; the scope
    decision comes from the caller's structured field, which is why that field
    is a required positional rather than something read off a subtask dict
    this function would then have to guard against being `None`.

    Plain "the tests fail on base" is NOT this and is worthless: measured on
    that run, all four findings' new tests already failed on base (9 of 13
    for one), because a new test against code that does not exist yet
    trivially fails. The claim wanted here is behavioural.
    """
    # No coercion on either argument, deliberately. Both are required
    # positionals on the only call site, so a wrong type is a contract
    # violation — and swallowing it would return `[]`, silently disabling this
    # check. That is the same shape as the `subtask or {}` this function's
    # sibling refuses (see `check_implementer_output`), and it would be
    # inconsistent to condemn it there and practise it here.
    if not isinstance(fixes_reported_symptom, bool):
        raise TypeError(
            "check_symptom_evidence requires an explicit bool for "
            f"fixes_reported_symptom, got {type(fixes_reported_symptom).__name__}"
        )
    if not fixes_reported_symptom:
        return []

    ev = result.get("symptom_evidence")
    if not isinstance(ev, dict):
        return ["NO_SYMPTOM_EVIDENCE: a subtask declared as fixing a reported "
                "symptom did not record whether that symptom actually "
                "reproduces on the base tree — a finding that no longer "
                "reproduces may already be fixed"]

    reproduced = ev.get("reproduced")
    if reproduced is False:
        detail = str(ev.get("not_reproduced_reason") or "").strip()
        return ["SYMPTOM_DID_NOT_REPRODUCE: the reported symptom could not be "
                "reproduced on the base tree — the finding may already be "
                "fixed, and this subtask may be re-fixing it"
                + (f": {detail}" if detail else "")]
    if reproduced is not True:
        return [f"MALFORMED_SYMPTOM_EVIDENCE: `reproduced` must be a boolean, "
                f"got {type(reproduced).__name__}"]
    return []


def check_production_evidence(result: dict) -> list[str]:
    """DESIGN §9 *Evidence must be production-grounded*.

    Every other check here asks whether the code matches its specification.
    This one asks whether the worker ever ran the path it wrote against the
    repo as it actually is. On run `fa979580` a heap resolver ticked every
    criterion against a `.leerie/config.toml` fixture — a shape 0 of the 5
    managed repos use — and returned `None` on both repos that motivated
    the finding. Nothing in the run could see that.

    Pure JSON→verdict set logic over already-structured fields (no prose is
    read), per CLAUDE.md's *Language-to-JSON* rule.

    Gates on ABSENCE deliberately (DESIGN §8 *Findings carry a severity* —
    the default is gating): the field is optional in the schema so that a
    worker omitting it loses one judgment rather than the whole payload,
    which is what requiring it would cost (`_confidence_schema`'s docstring
    records the measured 40.9%-valid outcome of that mistake). Gating on
    absence is what keeps optional from meaning ignorable.

    Not a proof of correctness — a fixture can be right and a real repo
    still take another branch. It converts "I could not make this fire
    here" from silence into a recorded, reviewable outcome.
    """
    issues: list[str] = []
    ev = result.get("production_evidence")

    if not isinstance(ev, dict):
        return ["NO_PRODUCTION_EVIDENCE: the result does not record whether "
                "the new code path was ever exercised against real repo "
                "state — run it and report `production_evidence`"]

    exercised = ev.get("exercised")
    if exercised is True:
        # `how`/`observed` are optional in the schema (decoder-safety), but
        # an exercised claim with neither is indistinguishable from the bare
        # assertion this check exists to replace.
        if not str(ev.get("how") or "").strip() and \
                not str(ev.get("observed") or "").strip():
            issues.append(
                "UNSUPPORTED_PRODUCTION_EVIDENCE: exercised=true but neither "
                "`how` nor `observed` is recorded — name the command you ran "
                "and what it returned")
        return issues

    if exercised is False:
        if not str(ev.get("unexercisable_reason") or "").strip():
            issues.append(
                "UNEXERCISED_PRODUCTION_PATH: the new code path was not run "
                "against real repo state and no `unexercisable_reason` is "
                "given — either exercise it or say why it cannot be")
        return issues

    issues.append(
        f"MALFORMED_PRODUCTION_EVIDENCE: `exercised` must be a boolean, "
        f"got {type(exercised).__name__}")
    return issues


# The kinds that enter the register: every `RISK_KINDS` value but
# `process_note`, which is excluded at ingestion (DESIGN §9).
_RISK_KINDS = frozenset(RISK_KINDS) - {"process_note"}
_RISK_DISPOSITIONS = frozenset({"confirmed_defect", "mitigated", "accepted"})
# Ingestion caps for worker-authored risk text. Enforced here rather than
# by schema maxLength: a length bound on the wire makes an honest 301-char
# disclosure cost the WHOLE payload a validation retry, the exact outcome
# `_production_evidence_schema`'s decoder-safety doctrine exists to avoid —
# honesty must not cost a retry, so the schema accepts and Python trims.
_RISK_DETAIL_MAX = 300
_RISK_WHERE_MAX = 120


def _normalize_risk_text(value: object, cap: int) -> str:
    """One line, bounded. Collapses all whitespace runs (including
    newlines) so a disclosure can never inject markdown structure — a
    `\\n## ` heading — into the PR body's risk section, on any of the
    renderers at once; tier-1's `unexercisable_reason` has no schema
    bound at all, so this is the only bound it gets."""
    return " ".join(str(value or "").split())[:cap]


def _typed_risks(result: dict | None, source: str) -> list[dict]:
    """One result's risk entries, both tiers, as normalized dicts.

    Tier 1 is the already-typed `production_evidence.exercised == false`
    signal — measured across 2,627 implementer calls on three repos it
    fires on 3.2% of results, and on the motivating run (a separate
    corpus) it flagged exactly the defect-bearing subtasks. Tier 2 is the
    explicit `self_reported_risks` array. Pure JSON→dict set logic, no
    prose interpreted (CLAUDE.md Language-to-JSON); malformed entries are
    dropped rather than guessed.
    """
    if not isinstance(result, dict):
        return []
    out: list[dict] = []
    ev = result.get("production_evidence")
    if isinstance(ev, dict) and ev.get("exercised") is False:
        # The worker could not exercise the path here. External only when it
        # names the resource no in-container step can supply; otherwise the
        # changed lines' coverage measurement settles or re-drives it (DESIGN
        # §9: on the 0.43.0 barnacle runs 36 of 39 such entries named none —
        # "docs-only change", "only ran the changed tests").
        resource = _normalize_risk_text(ev.get("unexercisable_resource"),
                                        _RISK_WHERE_MAX)
        entry = {
            "kind": "unexercised_behavior",
            "detail": _normalize_risk_text(
                ev.get("unexercisable_reason"), _RISK_DETAIL_MAX)
            or "path not exercised against real repo state",
            "source": source,
            "gap": "unverified_external" if resource else "test_missing",
            "where_paths": [],
        }
        if resource:
            entry["resource"] = resource
        out.append(entry)
    for item in result.get("self_reported_risks") or []:
        if not isinstance(item, dict):
            continue
        kind = item.get("kind")
        detail = _normalize_risk_text(item.get("detail"), _RISK_DETAIL_MAX)
        # `process_note` (and any unknown kind) is dropped here, so neither
        # the register nor the conformer's challenge block ever carries it.
        if kind not in _RISK_KINDS or not detail:
            continue
        # A result from before the typed fields carries no gap: `none`, so
        # it is kept in state but routes nowhere.
        gap = item.get("gap") if item.get("gap") in RISK_GAPS else "none"
        paths = item.get("where_paths")
        entry = {"kind": kind, "detail": detail, "source": source,
                 "gap": gap,
                 "where_paths": [p for p in (
                     _normalize_risk_text(x, _RISK_WHERE_MAX)
                     for x in (paths if isinstance(paths, list) else [])
                     if isinstance(x, str)) if p][:10]}
        where = _normalize_risk_text(item.get("where"), _RISK_WHERE_MAX)
        if where:
            entry["where"] = where
        if item.get("settle_by") in RISK_SETTLE_BY:
            entry["settle_by"] = item["settle_by"]
        resource = _normalize_risk_text(item.get("resource"), _RISK_WHERE_MAX)
        if resource:
            entry["resource"] = resource
        elif gap == "unverified_external":
            # External names what a human must supply; naming nothing, it is
            # a gap leerie's own checks settle (DESIGN §9).
            entry["gap"] = "test_missing"
        if item.get("simulated_interleaving") is True:
            entry["simulated_interleaving"] = True
        out.append(entry)
    return out


def _verify_risk_paths(entries: list[dict], worktree: str | Path
                       ) -> list[dict]:
    """Keep each entry's `where_paths` only where it names a file inside
    `worktree` (relative, no `..`, an existing file); the rest move to
    `where_paths_unverified` (DESIGN §9: exact repository paths, which code
    verifies exist). A mechanical path check — never a guess at what a
    path meant."""
    root = Path(worktree)
    for e in entries:
        kept: list[str] = []
        dropped: list[str] = []
        for p in e.get("where_paths") or []:
            rel = p.replace("\\", "/").removeprefix("./")
            ok = (not rel.startswith("/")
                  and ".." not in rel.split("/")
                  and (root / rel).is_file())
            (kept if ok else dropped).append(rel if ok else p)
        if "where_paths" in e:
            e["where_paths"] = kept
        if dropped:
            e["where_paths_unverified"] = dropped
    return entries


def _collect_subtask_risks(impl_res: dict | None,
                           conf_res: dict | None) -> list[dict]:
    """DESIGN §9 *Self-reported risk is routed, not read*: the pure routing
    helper that turns worker-disclosed risk into `risk_register` entries.

    The conformer's positional `risk_dispositions` answers the
    implementer-side entries in order (entry i answers risk i — the same
    order `_format_self_reported_risks` presented them in). The ONE
    disposition that can mark an entry `addressed` is "mitigated", and
    only with the repair recorded in a structured field: a `fixed: true`
    `solution_defects` entry or a `kind: "tests"` `file_updates` entry
    (the two records a conformer repair can leave; a docs update is not
    a mitigation; a record neutralized via `conformer_repair_rolled_back`
    — rollback arms, uncommitted tests path, a cited path absent from
    the phase's own commits, or a result the honesty validator
    rejected — does not count). "confirmed_defect"
    NEVER sets `addressed`, by design, not oversight: its act is the
    filed defect, owned by the completeness gate, and an entry that then
    SURVIVES to a finalized PR is a case where that channel did not fix
    it — `--skip-completeness-check` demoted it, or the conformer
    confirmed while filing no actionable entry (advisory-warned at
    settle); rendering it "addressed" there would be anti-correlated
    with reality. (Gate exhaustion blocks the subtask instead, and an
    `accept-blocked`ed sid's entries never render — the PR section skips
    work the PR does not contain.) "accepted", an unanswered
    tail, a non-string or unrecognised item, or a mitigation with no
    recorded repair all stay unaddressed — the fail-safe union: ignoring
    a risk cannot clear it (A/B-measured: handing a reviewer the
    disclosure with no typed way to answer it suppressed defect-reporting
    to 0/3, against 2/3 with no disclosure at all — disclosure anchors
    unless the answer is a recorded act). The mitigation act is
    co-occurrence, not per-risk linkage — DESIGN §9 names the residual
    class that leaves and why linkage was rejected (grammar budget;
    Language-to-JSON).

    Addressed entries are kept (annotated), not dropped: the PR section
    shows the reviewer the full picture. Risks never gate — the gating
    robustness kinds live on `solution_defects` and ride the existing
    completeness channel.
    """
    impl_risks = _typed_risks(impl_res, "implementer")
    dispositions = (conf_res or {}).get("risk_dispositions") \
        if isinstance(conf_res, dict) else None
    if not isinstance(dispositions, list):
        dispositions = []
    defects = (conf_res.get("solution_defects") or []) \
        if isinstance(conf_res, dict) else []
    file_updates = (conf_res.get("file_updates") or []) \
        if isinstance(conf_res, dict) else []
    # `conformer_repair_rolled_back` is orchestrator-set, not worker
    # output: _run_conformance_phase marks the result when its own
    # rollback arms reverted the round's commits, a tests file_update
    # points at an uncommitted path, or the result failed the honesty
    # validator — so repair records that no longer exist on the branch,
    # or come from a rejected result, can never count as the act.
    repair_lost = bool(isinstance(conf_res, dict)
                       and conf_res.get("conformer_repair_rolled_back"))
    has_mitigation_act = not repair_lost and bool(
        any(isinstance(d, dict) and d.get("fixed") is True for d in defects)
        or any(isinstance(u, dict) and u.get("kind") == "tests"
               for u in file_updates))
    out: list[dict] = []
    for i, risk in enumerate(impl_risks):
        entry = dict(risk)
        disp = dispositions[i] if i < len(dispositions) else None
        # isinstance guard is load-bearing, not defensive decoration: a
        # dict/list item would raise TypeError on the frozenset membership
        # test, and this runs on _settle_subtask's success path OUTSIDE
        # the advisory conformance try/except — a malformed disposition
        # must degrade to "unanswered", never kill the settle.
        if isinstance(disp, str) and disp in _RISK_DISPOSITIONS:
            entry["disposition"] = disp
        entry["addressed"] = bool(
            entry.get("disposition") == "mitigated" and has_mitigation_act)
        out.append(entry)
    # The conformer's own schema carries no self_reported_risks (grammar
    # budget — see SCHEMAS["conformer"]), so normally only its
    # production_evidence tier lands here; if a worker emits the field
    # anyway (extra keys pass non-strict validation), the entries ride
    # fail-safe to the register too. Never challenged, so never addressed.
    for risk in _typed_risks(conf_res, "conformer"):
        entry = dict(risk)
        entry["addressed"] = False
        out.append(entry)
    return out


def _format_self_reported_risks(impl_res: dict | None) -> str | None:
    """The conformer-facing challenge block for an implementer's disclosed
    risks, in the exact order `_collect_subtask_risks` will read the
    positional `risk_dispositions` back. None when there is nothing to
    challenge (the common case — no block beats an empty block)."""
    risks = _typed_risks(impl_res, "implementer")
    if not risks:
        return None
    lines = [
        "SELF_REPORTED_RISKS — the implementer disclosed these risks about "
        "its own diff. Answer EACH, in order, via `risk_dispositions` "
        "(entry i answers risk i): \"confirmed_defect\" (the risk is a real "
        "outstanding defect — also file it as an actionable "
        "`solution_defects` entry so it gates; the register entry stays "
        "visible either way), \"mitigated\" (you resolved it in this pass, "
        "recorded as a `fixed: true` `solution_defects` entry or a "
        "`kind: \"tests\"` `file_updates` entry — the only answer that "
        "marks the risk addressed), or \"accepted\" (tolerable; it stays "
        "on the run's risk register for the reviewer). An entry you leave "
        "unanswered stays on the register — silence does not clear it, "
        "and neither does \"mitigated\" without its recorded repair:",
    ]
    for i, r in enumerate(risks):
        where = f" ({r['where']})" if r.get("where") else ""
        lines.append(f"  {i}. [{r['kind']}]{where} {r['detail']}")
    return "\n".join(lines)


# ---- Task-referenced file extraction (CRITIC correlated-error breaker) - #
# When the task string references files (glob patterns or explicit paths),
# the orchestrator mechanically resolves the paths and names them for the
# planner and task_coverage_judge, which read the files themselves and
# judge coverage as substance rather than string overlap. This breaks the
# correlated-error ceiling identified by "The Specification as Quality
# Gate" (Mar 2026, arxiv 2603.25773). Naming the files is mechanical;
# judging whether their requirements are met is a judgment about meaning,
# which used to be done here via regex-harvested headings substring-
# matched against plan text — see docs/DESIGN.md "Task-referenced file
# extraction" for why that mechanism was deleted (the 2026-07-19 freeze).

_GLOB_CHARS = frozenset("*?[{")
_BRACE_RE = re.compile(r'\{([^}]+)\}')


def _expand_braces(pattern: str) -> list[str]:
    """Expand shell-style ``{a,b}`` brace groups into multiple patterns.

    Python's ``glob.glob`` does not support brace expansion, but task
    strings commonly use it (e.g. ``spec-*.{md,yaml}``).  Recursive
    so nested braces work."""
    m = _BRACE_RE.search(pattern)
    if not m:
        return [pattern]
    prefix, suffix = pattern[:m.start()], pattern[m.end():]
    expanded: list[str] = []
    for alt in m.group(1).split(","):
        expanded.extend(_expand_braces(prefix + alt.strip() + suffix))
    return expanded


def _repo_rel(path: Path, repo_root: Path) -> str:
    """Repo-relative string for *path*, falling back to its name when it
    resolves outside *repo_root*. Pure path arithmetic."""
    try:
        return str(path.resolve().relative_to(repo_root.resolve()))
    except (ValueError, OSError):
        return path.name


def _format_task_file_references(
    files: list[Path], repo_root: Path,
) -> str | None:
    """Name the files the task references so the planner reads them.

    Deliberately just a list of paths. leerie used to harvest headings and
    YAML keys out of these files with regex and inject them as a coverage
    checklist — parsing prose to decide what a document requires, which is
    the planner's job and, for the plan as a whole, `task_coverage_judge`'s
    (CLAUDE.md *Language-to-JSON*). Returns None when the task names no
    files, so the section is omitted rather than empty."""
    if not files:
        return None
    listing = "\n".join(f"- {_repo_rel(f, repo_root)}" for f in files)
    return (
        "FILES THIS TASK REFERENCES\n"
        "Read each one before decomposing — they carry requirements the "
        "task text only gestures at:\n" + listing
    )


def _is_same_document(root: Path, path: Path, text_len: int,
                      text: str) -> bool:
    """True when `path` holds exactly `text` (modulo surrounding whitespace).

    Used to keep a task file out of its own reference list. The planner is
    already handed the task verbatim, so listing the file again asks it to
    re-read content it has — ~71K tokens of pure duplication on the measured
    incident (185,565 B at the measured 2.6 B/token). `resolve_task_argument` returns the file's stripped contents and
    discards the path, so identity is re-established by content rather than by
    plumbing the path through every caller. The size pre-check keeps this from
    reading large candidates: only a file already within a few bytes of the
    task's length is opened at all. `text_len` is the task's encoded length,
    passed in rather than recomputed because this runs once per candidate and
    the task can be hundreds of KB."""
    try:
        if abs(path.lstat().st_size - text_len) > 8:
            return False
        return _read_text_beneath(root, path, limit=READ_LIMIT_TEXT).strip() == text
    except (OSError, ValueError):
        return False


def _glob_task_references(task: str, repo_root: Path) -> list[Path]:
    """Find file references in the task string via glob expansion.

    Scans for tokens that look like file paths or glob patterns (contain
    a dot + extension, or glob characters).  Brace groups like
    ``{md,yaml}`` are pre-expanded before globbing since Python's
    ``glob`` module does not handle them.  Returns deduplicated matched
    paths sorted alphabetically.  Returns empty list when nothing
    matches — the feature is a no-op for tasks that don't reference
    files."""
    import glob as _glob
    candidates: list[str] = []
    for token in task.split():
        # Markdown emphasis is stripped before classification because `*` is
        # in _GLOB_CHARS: an unstripped bare `*` globs to EVERY file in the
        # repo root. Measured on a 185 KB markdown task carrying 134 bare `*`
        # and 217 `**`, that pulled in 18 files / 1.86 MB — LICENSE,
        # .claude.json and a prior run's 847 KB log among them — all of which
        # `_format_task_file_references` then told the planner to read.
        token = token.strip("\"'(),;:").strip("*_`")
        if not token:
            continue
        # After de-emphasis a reference must still look like a path: some
        # alphanumeric content, plus an extension or a separator. DESIGN §6
        # scopes this feature to "files the user explicitly pointed to", and a
        # stray emphasis marker is not that. `**`, `**Root` and `**log**` fail
        # here; `spec.md`, `spec-*.md`, `tests/*.py` and `docs/DESIGN.md` pass.
        if not any(c.isalnum() for c in token):
            continue
        # Absolute paths are never repo references, and `repo_root / "/etc/x"`
        # silently discards the root (pathlib lets an absolute right-hand side
        # win), so admitting them would reach outside the repo entirely — a
        # task mentioning `/bin/bash` matched a 1.4 MB binary before this guard.
        if token.startswith("/"):
            continue
        has_ext = "." in token and not token.startswith(".")
        has_sep = "/" in token
        if has_ext or has_sep:
            candidates.append(token)
    matched: list[Path] = []
    seen: set[str] = set()
    root = repo_root.resolve()
    task_stripped = task.strip()
    task_len = len(task_stripped.encode())
    for cand in candidates:
        for expanded in _expand_braces(cand):
            for m in sorted(_glob.glob(str(repo_root / expanded))):
                p = Path(m)
                # A match reached through a link — the match itself, or a
                # linked directory on the way — names what the link points
                # at, not the repository's own file (DESIGN §6 *Leerie never
                # reads through a link a repository holds*).
                if not _no_link_beneath(repo_root, p):
                    continue
                # Containment re-check, independent of the token-level guard
                # above: `../` segments survive the startswith("/") test and
                # would otherwise escape the same way. `resolve()` follows
                # symlinks deliberately — an in-repo symlink whose target sits
                # outside the repo is an escape by another name, and dropping
                # it is the conservative reading of "files the user explicitly
                # pointed to" (DESIGN §6 *Task-referenced file extraction*).
                try:
                    if not p.resolve().is_relative_to(root):
                        continue
                except (OSError, ValueError):
                    continue
                if _regular_file_beneath(repo_root, p) and str(p) not in seen:
                    if _is_same_document(repo_root, p, task_len,
                                         task_stripped):
                        continue
                    seen.add(str(p))
                    matched.append(p)
    return matched


def _unreachable_task_references(task: str, repo_root: Path) -> list[str]:
    """Flag task tokens that point outside the repo and resolve to nothing.

    A task that delegates its operative content to a path the planner can
    never read (e.g. ``~/.claude/plans/foo.md``) is silently dropped by
    `_glob_task_references` exactly like ordinary prose — that guard
    deliberately excludes absolute paths from candidates (see its
    startswith("/") check) and pathlib never expands `~`, so a `~`-prefixed
    reference never even reaches that guard. This is advisory only: it
    never touches `_glob_task_references`'s return value or candidate
    filtering, it only surfaces what would otherwise vanish without a
    trace.

    Covers three shapes, all invisible to the planner for different
    mechanical reasons: absolute (`/…`, excluded as a candidate), `~`-
    prefixed (never expanded — and only where the token is home-*shaped*,
    `~/…` or `~name/…`, since a bare `~` before a digit is approximation
    notation in prose, not a path), and **parent-relative (`../…`)**. The last
    one survives the token-level guard and is dropped later, by
    `_glob_task_references`'s `is_relative_to(root)` containment re-check —
    so it needs `repo_root` to be recognised here, and it is the shape most
    likely to mislead, since the file often really does exist on the host
    and the operator has no reason to suspect the planner cannot see it.
    A `../` reference that resolves back INSIDE the repo is reachable and is
    only flagged if it resolves to nothing."""
    tokens: list[str] = []
    for token in task.split():
        token = token.strip("\"'(),;:").strip("*_`")
        # Sentence punctuation trailing a reference, stripped from the RIGHT
        # only. A reference ending a sentence, or wrapped in backticks inside
        # one, otherwise reaches the operator warning as "`~/plans/x.md`." —
        # the mangled form they then go looking for. The two strips above
        # cannot do it: they run in a fixed order, so the backtick in
        # "`x.md`." is unreachable behind the period.
        #
        # rstrip, never strip: a LEADING dot is meaningful (`.env`,
        # `.github/workflows/ci.yml`) and a leading `./` or `../` is a real
        # relative path. Measured on the sibling `_parse_touched_file_line`
        # defect, a two-sided strip mangled all three.
        token = token.rstrip("`.,;:!?)]}\"'")
        if not token:
            continue
        if not any(c.isalnum() for c in token):
            continue
        has_ext = "." in token and not token.startswith(".")
        has_sep = "/" in token
        if not (has_ext or has_sep):
            continue
        if token.startswith("~") and not (
                token.startswith("~/") or token[1:2].isalpha()
                or token[1:2] == "_"):
            # A `~` in task prose is far more often approximation notation
            # than a home reference: `~17.9 MB`, `~2.5/subtask`, `~9/10`,
            # `~14GB/64GB`. A real home reference is either `~/…` or
            # `~name/…`, so a token whose second character is neither a
            # separator nor the start of a username is prose. Measured over
            # 518 real task strings: 32 of the 62 distinct `~`-prefixed
            # path-shaped tokens were prose, and every one of them raised
            # RuntimeError out of the expanduser() probe below. A
            # separator-only test is NOT enough — three of those 32 carry
            # a `/` (`~2.5/subtask`, `~9/10`, `~14GB/64GB`).
            continue
        if (token.startswith("/") or token.startswith("~")
                or token.startswith("../")):
            tokens.append(token)
    root = repo_root.resolve()
    unreachable: list[str] = []
    for token in tokens:
        if token.startswith("../"):
            # Resolved against the repo root, mirroring how
            # `_glob_task_references` globs (`repo_root / token`) and then
            # re-checks containment. Flagged when it escapes the root — the
            # planner cannot read it even though it may well exist — or when
            # it escapes nothing but resolves to no file at all.
            try:
                resolved = (root / token).resolve()
                if resolved.is_relative_to(root) and resolved.is_file():
                    continue
            except (OSError, ValueError):
                pass
            unreachable.append(token)
        else:
            # Guarded like the `../` branch above, and for the same reason.
            # `expanduser()` raises RuntimeError — not OSError — for
            # `~name/…` when `name` is absent from the password database,
            # and the token comes from user prose. Falling through to the
            # append is the right outcome: such a reference really is one
            # the planner cannot read; it simply must not abort the run.
            try:
                if Path(token).expanduser().is_file():
                    continue
            except (OSError, RuntimeError, ValueError):
                pass
            unreachable.append(token)
    return unreachable


def _log_unreachable_task_references(task: str, repo_root: Path) -> list[str]:
    """Advisory-only wrapper around `_unreachable_task_references`.

    The check gates nothing — it emits one operator warning — so a raise
    out of it must never cost a run. It did twice: a `~`-approximation
    token in task prose (`(~17.9 MB)`) reached `expanduser()` and killed
    phase 2 after classify and the artifact registry had already been paid
    for. `_unreachable_task_references` no longer has a raise path, and
    this wrapper keeps that true for the caller regardless of what a later
    edit does to it — the same posture `phase_artifact_registry` already
    takes one phase earlier ("Best-effort — never die()s and returns []
    on any failure")."""
    try:
        refs = _unreachable_task_references(task, repo_root)
    except Exception as exc:  # advisory only — never gate on it
        log(f"  unreachable-reference advisory skipped "
            f"({type(exc).__name__}: {exc})")
        return []
    if refs:
        log(f"  task references {len(refs)} path(s) outside the "
            f"repo that leerie cannot read: {', '.join(refs)}")
    return refs


def _walk_calls(node: "object") -> list[str]:
    """Collect identifier names from call-expression function positions.

    Walks the tree-sitter CST recursively.  For each `call` node, extracts
    the function's identifier if the callee is a bare name or the first
    component of an attribute access (e.g. ``foo(...)`` → ``"foo"``,
    ``obj.method(...)`` → ``"obj"`` is skipped, only bare-name callees become
    reference edges).  This approximates cross-file ref edges without requiring
    a scope resolver."""
    results: list[str] = []

    def _visit(n: "object") -> None:
        if n.type == "call":  # type: ignore[attr-defined]
            func = n.child_by_field_name("function")  # type: ignore[attr-defined]
            if func and func.type == "identifier":  # type: ignore[attr-defined]
                text = func.text  # type: ignore[attr-defined]
                if text:
                    results.append(
                        text.decode() if isinstance(text, bytes) else text)
        for child in n.children:  # type: ignore[attr-defined]
            _visit(child)

    _visit(node)
    return results


def _parse_repo_file(root: Path, path: Path) -> tuple[list[str], list[str]]:
    """Parse one source file and return ``(defs, refs)``.

    *defs* — list of defined symbol names (functions, classes, methods).
    *refs* — list of symbol names called/referenced in the file body.

    Uses ``tree_sitter_language_pack.process()`` for definitions (structure)
    and tree-sitter's CST for call-site references.  Returns ``([], [])``
    when the language is unsupported or an error occurs (graceful degrade —
    the file is simply absent from the graph). On an actual exception (not a
    plain unsupported-extension miss), stashes a short diagnostic in the
    module-level ``_last_parse_error`` (type + message) — not used to alter
    this function's own silent-degrade contract, but read by
    ``_tree_sitter_extraction_works()``'s caller so a broken/incompatible
    parser leaves an actual cause behind instead of a bare guess."""
    global _last_parse_error
    try:
        import tree_sitter_language_pack as tslp  # noqa: PLC0415
        from tree_sitter import Parser  # noqa: PLC0415
    except ImportError as e:
        _last_parse_error = f"{type(e).__name__}: {e}"
        return [], []
    try:
        lang = tslp.detect_language(str(path))
        if not lang:
            return [], []
        source = _read_text_beneath(root, path, limit=READ_LIMIT_TEXT)
        proc_result = tslp.process(
            source,
            tslp.ProcessConfig(language=lang, structure=True, imports=False),
        )
        defs: list[str] = []

        def _collect_defs(items: list) -> None:
            for item in items:
                if item.name:
                    defs.append(item.name)
                _collect_defs(item.children)

        _collect_defs(proc_result.structure)
        py_lang = tslp.get_language(lang)
        parser = Parser(py_lang)
        tree = parser.parse(source.encode())
        refs = _walk_calls(tree.root_node)
        _last_parse_error = None
        return defs, refs
    except Exception as e:  # graceful degrade; tree-sitter parse errors, IO, etc.
        _last_parse_error = f"{type(e).__name__}: {e}"
        return [], []


def _extract_symbol_ranges(root: Path,
                           path: Path) -> list[tuple[str, int, int]]:
    """Return the top-level symbols of *path* as ``(name, start_line, end_line)``,
    sorted by ``start_line`` — the ordered, exhaustive span sequence the sub-file
    splitter tiles into regions (DESIGN §5½ (P1) *Sub-file*).

    Deliberately separate from ``_parse_repo_file`` / ``_build_repo_map``: the
    repo-map graph stores bare symbol *names* (no positions) and is pinned by
    ~10 tests plus an mtime cache whose shape those tests fix. Reading ranges
    through a dedicated function keeps that contract — and its cache — untouched,
    at the cost of a second ``tslp.process`` call on the one file being split
    (rare, and only when a single-file subtask is over-scoped).

    Only **top-level** symbols are tiled: nested defs live inside their parent's
    span, so including them would double-count lines. ``item.span`` is a ``Span``
    whose ``start_line``/``end_line`` are **0-based**; this function normalizes to
    the 1-based, inclusive line numbers the partitioner, prompts, and editors use.
    Returns ``[]`` when the language is unsupported or extraction fails — the
    caller falls back to tier-2 line-windows over the whole file
    (``_partition_lines``)."""
    try:
        import tree_sitter_language_pack as tslp  # noqa: PLC0415
    except ImportError:
        return []
    try:
        lang = tslp.detect_language(str(path))
        if not lang:
            return []
        source = _read_text_beneath(root, path, limit=READ_LIMIT_TEXT)
        proc_result = tslp.process(
            source,
            tslp.ProcessConfig(language=lang, structure=True, imports=False),
        )
        ranges: list[tuple[str, int, int]] = []
        for item in proc_result.structure:
            span = getattr(item, "span", None)
            if item.name and span is not None:
                # tree-sitter Span line numbers are 0-based; normalize to the
                # 1-based line numbers the partitioner, prompts, and editors use.
                ranges.append(
                    (item.name, span.start_line + 1, span.end_line + 1))
        ranges.sort(key=lambda r: r[1])
        return ranges
    except Exception:  # graceful degrade — caller uses the line-window fallback
        return []


# Source-code extensions used only to detect the G6 "repo has code but the
# symbol graph is empty" condition (tree-sitter unavailable/incompatible).
# Not an allow-list for parsing — _parse_repo_file/detect_language own that.
_SOURCE_EXTS = frozenset({
    ".py", ".pyi", ".js", ".jsx", ".ts", ".tsx", ".mjs", ".cjs",
    ".go", ".rs", ".rb", ".java", ".kt", ".c", ".h", ".cc", ".cpp",
    ".hpp", ".cs", ".php", ".swift", ".scala", ".sh", ".lua",
})

_repo_map_empty_warned = False

# Diagnostic for the last exception _parse_repo_file swallowed (None if its
# last call succeeded or hit a plain unsupported-extension miss). Read by
# _warn_repo_map_empty_once() right after the probe call below, so it always
# reflects that call — never a stale error from an earlier real-file parse
# during _build_repo_map's walk (see the reset at the top of
# _tree_sitter_extraction_works()).
_last_parse_error: str | None = None


def _tree_sitter_extraction_works() -> bool:
    """True only if the tree-sitter stack can actually extract a symbol.
    Parses a trivial snippet through _parse_repo_file so an installed-but-
    incompatible parser (imports fine, extracts nothing) is caught. Used to
    distinguish a broken parser (warn) from a legitimately symbol-less repo
    (stay quiet) in _build_repo_map's empty-graph check. Resets
    _last_parse_error before probing so the result reflects only this call."""
    global _last_parse_error
    import tempfile  # noqa: PLC0415

    _last_parse_error = None
    try:
        with tempfile.TemporaryDirectory() as d:
            f = Path(d) / "_probe.py"
            f.write_text("def _probe_sym():\n    return 1\n")
            defs, _refs = _parse_repo_file(Path(d), f)
        return "_probe_sym" in defs
    except Exception as e:
        _last_parse_error = f"{type(e).__name__}: {e}"
        return False


def _warn_repo_map_empty_once(source_candidates: int) -> None:
    """Emit at most one warning per process when _build_repo_map produces an
    empty graph despite the repo containing source files AND a functional
    probe confirms tree-sitter cannot extract symbols — the signal that
    tree-sitter is unavailable or its API is incompatible and P6 has silently
    become a no-op (DESIGN §12). If the probe *works* (so the empty graph is a
    legitimately symbol-less repo), no warning is emitted. When the probe
    failed via a caught exception (as opposed to a silent empty-result
    degrade), appends that exception's type+message so the warning leaves an
    actual diagnosable cause instead of a bare "unavailable or incompatible"
    guess."""
    global _repo_map_empty_warned
    if _repo_map_empty_warned:
        return
    if _tree_sitter_extraction_works():
        return  # parser is fine; the repo just has no extractable symbols
    _repo_map_empty_warned = True
    detail = f" Probe failure: {_last_parse_error}" if _last_parse_error else ""
    log(
        f"WARNING: repo-map is empty despite {source_candidates} source "
        "file(s) — tree-sitter is unavailable or incompatible; P6 structural "
        "context is disabled and planning degrades to grep/glob only. Check "
        "the tree-sitter-language-pack install (see requirements.txt pin)."
        f"{detail}"
    )


def _build_repo_map(
    repo_root: Path,
    leerie_root: Path,
) -> dict:
    """Build (or update) the repo-map symbol/reference graph for *repo_root*.

    Walks all source files under *repo_root* (skipping ``node_modules``,
    ``.git``, ``__pycache__``, virtualenvs, and build outputs), parses each
    with tree-sitter, extracts definition and call-site symbols, and builds a
    two-sided graph:

    - ``files``   : ``{file_path: [def_symbol, ...]}``
    - ``refs``    : ``{def_symbol: {file_path, ...}}``

    Parse results are mtime-cached under
    ``<leerie_root>/repo-map-cache/<sha256(path)>.pkl`` so that only files
    whose mtime changed since the last call are re-parsed (the Aider diskcache
    pattern).  The cache directory is created on first use.

    Returns the ``RepoMap`` dict (always; never raises)."""
    import pickle  # noqa: PLC0415
    import hashlib  # noqa: PLC0415

    cache_dir = leerie_root / REPO_MAP_CACHE_DIR
    try:
        cache_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        cache_dir = None  # cache unavailable; proceed without

    _SKIP_DIRS = frozenset({
        ".git", "node_modules", "__pycache__", ".venv", "venv", "env",
        ".tox", "dist", "build", ".mypy_cache", ".pytest_cache",
        ".ruff_cache", "target", "vendor", ".bundle",
        # `.leerie` is the STATE ROOT on the Fly/EC2 runtimes: only the local
        # nerdctl arm exports LEERIE_STATE_DIR, so `resolve_leerie_root` falls
        # back to `<repo>/.leerie` there and every worktree (staging, per
        # subtask, and now the judgment worktree) materializes inside the repo.
        # Without this the map walks N full copies of the tree — every current
        # worktree plus every prior run's leftovers — indexing each file
        # repeatedly and spending the token budget on worktree paths. `.git` is
        # already pruned by name, but a worktree's `.git` is a FILE, not a
        # directory, so its contents were walked in full.
        ".leerie",
    })

    def _cache_path(abs_path: Path) -> Path | None:
        if cache_dir is None:
            return None
        digest = hashlib.sha256(str(abs_path).encode()).hexdigest()
        return cache_dir / f"{digest}.pkl"

    def _load_cache(abs_path: Path) -> tuple[list[str], list[str]] | None:
        cp = _cache_path(abs_path)
        if cp is None or not cp.exists():
            return None
        try:
            with open(cp, "rb") as fh:
                entry = pickle.load(fh)  # noqa: S301
            if entry.get("mtime_ns") == abs_path.lstat().st_mtime_ns:
                return entry["defs"], entry["refs"]
        except Exception:
            pass
        return None

    def _save_cache(
        abs_path: Path,
        defs: list[str],
        refs: list[str],
    ) -> None:
        cp = _cache_path(abs_path)
        if cp is None:
            return
        try:
            with open(cp, "wb") as fh:
                pickle.dump({
                    "mtime_ns": abs_path.lstat().st_mtime_ns,
                    "defs": defs,
                    "refs": refs,
                }, fh, protocol=4)
        except Exception:
            pass

    files_map: dict[str, list[str]] = {}
    refs_map: dict[str, set[str]] = {}
    source_candidates = 0  # files with a source-code extension we tried to parse

    for dirpath, dirnames, filenames in os.walk(repo_root):
        # Prune skip dirs in-place so os.walk doesn't descend into them
        dirnames[:] = [d for d in dirnames if d not in _SKIP_DIRS]
        for fname in filenames:
            abs_path = Path(dirpath) / fname
            if abs_path.suffix.lower() in _SOURCE_EXTS:
                source_candidates += 1
            rel = str(abs_path.relative_to(repo_root))
            cached = _load_cache(abs_path)
            if cached is not None:
                defs, file_refs = cached
            else:
                defs, file_refs = _parse_repo_file(repo_root, abs_path)
                _save_cache(abs_path, defs, file_refs)
            if not defs and not file_refs:
                continue
            files_map[rel] = defs
            for sym in file_refs:
                if sym not in refs_map:
                    refs_map[sym] = set()
                refs_map[sym].add(rel)

    # G6 — make silent P6 degradation visible (DESIGN §12 "no silent
    # under-coverage"): if the repo has source files but the graph came back
    # empty, tree-sitter is unavailable/incompatible (e.g. a language-pack
    # version without the process() API) and the whole P6 layer just became a
    # no-op the planner cannot detect. Warn ONCE per process so an operator
    # sees it instead of a silently degraded plan. A genuinely empty/non-code
    # repo (source_candidates == 0) stays quiet — that degrade is legitimate.
    if source_candidates and not files_map:
        _warn_repo_map_empty_once(source_candidates)

    return {"files": files_map, "refs": refs_map}


def _pagerank(
    graph: dict[str, set[str]],
    personalization: dict[str, float],
    damping: float = 0.85,
    max_iter: int = 100,
    tol: float = 1e-6,
) -> dict[str, float]:
    """Personalized PageRank on a directed graph (stdlib-only, no networkx).

    *graph*           : node → set of outgoing neighbors.
    *personalization* : node → preference weight (unnormalized).

    Returns node → rank score (higher = more task-relevant)."""
    # Collect all nodes (including those only appearing as targets)
    nodes: set[str] = set(graph.keys())
    for neighbors in graph.values():
        nodes.update(neighbors)
    if not nodes:
        return {}

    n = len(nodes)
    total_pref = sum(personalization.values()) or 1.0
    pref: dict[str, float] = {
        nd: personalization.get(nd, 0.0) / total_pref for nd in nodes
    }
    rank: dict[str, float] = {nd: 1.0 / n for nd in nodes}
    dangling: set[str] = {
        nd for nd in nodes if nd not in graph or not graph[nd]
    }

    for _ in range(max_iter):
        dangling_sum = damping * sum(rank[nd] for nd in dangling) / n
        new_rank: dict[str, float] = {}
        for nd in nodes:
            in_score = sum(
                rank[src] / len(graph[src])
                for src in nodes
                if src in graph and nd in graph[src] and graph[src]
            )
            new_rank[nd] = (
                damping * in_score
                + dangling_sum
                + (1.0 - damping) * pref.get(nd, 0.0)
            )
        err = sum(abs(new_rank[nd] - rank[nd]) for nd in nodes)
        rank = new_rank
        if err < tol:
            break
    return rank


def _render_repo_map_subgraph(
    repo_map: dict,
    ranked_files: list[tuple[str, float]],
    max_files: int,
) -> str:
    """Render the top *max_files* files from *ranked_files* as a compact
    text block: one line per file listing its defined symbols.

    Symbols are shown as a comma-separated list.  The format is:

        path/to/file.py: SymA, SymB, SymC

    Files with no defs are omitted.  Top-ranked files appear first (highest
    score → most task-relevant); per the recency-bias principle, the most
    relevant entries appear at the beginning of the block."""
    files_map: dict[str, list[str]] = repo_map["files"]
    lines: list[str] = []
    for rel, _score in ranked_files[:max_files]:
        syms = files_map.get(rel)
        if not syms:
            continue
        lines.append(f"{rel}: {', '.join(syms[:30])}")
    return "\n".join(lines)


def _count_tokens_approx(text: str) -> int:
    """Approximate token count: ~4 bytes per token (GPT/Claude typical)."""
    return max(1, len(text.encode()) // 4)


def _rank_repo_map(
    repo_map: dict,
    seed_files: list[str],
    seed_symbols: list[str],
    token_budget: int | None = None,
) -> str:
    """Run personalized PageRank on *repo_map* biased toward *seed_files* and
    *seed_symbols*, and return a compact ranked-subgraph text string that fits
    within *token_budget* tokens.

    The subgraph is binary-searched to fit the budget: start with all ranked
    files, halve max_files until the rendered text fits, then return the
    largest budget-fitting slice.

    When *token_budget* is ``None``, uses ``DEFAULT_CAPS["repo_map_tokens"]``.

    Returns an empty string when the repo-map is empty or no seed is given
    and the whole map is empty."""
    if token_budget is None:
        token_budget = DEFAULT_CAPS["repo_map_tokens"]

    files_map: dict[str, list[str]] = repo_map.get("files", {})
    refs_map: dict[str, set[str]] = repo_map.get("refs", {})

    if not files_map:
        return ""

    # Build a file→file edge graph via shared symbols:
    # file A → file B when a symbol defined in A is referenced in B
    # (A is a callee; B is a caller).  This direction means high-in-degree
    # nodes are widely-used utilities — biasing toward them surfaces the
    # structural backbone of the task neighborhood.
    graph: dict[str, set[str]] = {}
    def_to_file: dict[str, str] = {}
    for rel, syms in files_map.items():
        for sym in syms:
            def_to_file[sym] = rel

    for sym, referencing_files in refs_map.items():
        definer = def_to_file.get(sym)
        if definer is None:
            continue
        if definer not in graph:
            graph[definer] = set()
        for ref_file in referencing_files:
            if ref_file != definer:
                graph[definer].add(ref_file)

    for rel in files_map:
        if rel not in graph:
            graph[rel] = set()

    pref: dict[str, float] = {}
    seed_set = set(seed_files)
    for rel in files_map:
        if rel in seed_set:
            pref[rel] = pref.get(rel, 0.0) + 1.0
    for sym in seed_symbols:
        definer = def_to_file.get(sym)
        if definer and definer in files_map:
            pref[definer] = pref.get(definer, 0.0) + 1.0
        for ref_file in refs_map.get(sym, set()):
            if ref_file in files_map:
                pref[ref_file] = pref.get(ref_file, 0.0) + 0.5

    if not pref:
        pref = {rel: 1.0 for rel in files_map}

    ranks = _pagerank(graph, pref)

    ranked_files: list[tuple[str, float]] = sorted(
        ((rel, ranks.get(rel, 0.0)) for rel in files_map),
        key=lambda x: -x[1],
    )

    total = len(ranked_files)
    if total == 0:
        return ""

    lo, hi = 1, total
    best = ""
    while lo <= hi:
        mid = (lo + hi) // 2
        candidate = _render_repo_map_subgraph(repo_map, ranked_files, mid)
        if _count_tokens_approx(candidate) <= token_budget:
            best = candidate
            lo = mid + 1
        else:
            hi = mid - 1

    return best


def check_plan_wiring(subtasks: dict) -> list[str]:
    """Deterministic wiring re-check on the fully-merged post-drop plan
    (DESIGN §5 *A wiring re-check on the fully-merged plan*, §8). Pure Python,
    no LLM — returns a list of dangle messages ([] when clean).

    Replays exactly `_validate_plan`'s two id/tag-channel dangle checks:
      - every `depends_on` id resolves to a surviving subtask, and
      - every `requires` tag with `extent: in_plan` has some subtask's
        `provides` matching it.

    The point is not to duplicate `_validate_plan` for its own sake — it is to
    run these checks *and give a wiring-specific, actionable message* on the
    merged plan produced AFTER every id/tag-vanishing operation (reconciler
    merge/rename/drop, both phase-3 soft-drop filters, P1 expansion). Each of
    those ops owes the plan a rewrite of inbound references; each is an
    independent opportunity to leave a dangle that only surfaces at
    `_validate_plan` — after the full planner/reconciler spend, whose generic
    `die()` throws that spend away. Running this first `die()`s earlier with a
    message that names the wiring failure (and, when derivable, whether the
    provider vanished via a drop/merge). `_validate_plan` stays the backstop:
    it re-checks the same invariants and catches anything this misses.

    `subtasks` is the sid→subtask dict `_schedule()` returns (same shape
    `_validate_plan` consumes). `extent: external` requires are deliberately
    NOT checked (declared out-of-graph, per `_validate_plan`)."""
    issues: list[str] = []
    all_ids = set(subtasks.keys())
    all_provides: set[str] = set()
    for s in subtasks.values():
        all_provides.update(s.get("provides", []) or [])

    for sid, s in subtasks.items():
        for dep in s.get("depends_on", []) or []:
            if dep not in all_ids:
                issues.append(
                    f"{sid}: depends_on '{dep}' which no surviving subtask "
                    "provides — an id vanished (a merge/rename/drop or "
                    "expansion) without its inbound depends_on being rewritten "
                    "(DESIGN §5 *Id-vanishing operations*)")
        for entry in s.get("requires", []) or []:
            if not isinstance(entry, dict):
                continue  # shape errors are _validate_plan's job, not wiring's
            tag = entry.get("tag", "")
            extent = entry.get("extent", "")
            if not tag or not isinstance(tag, str):
                continue
            if extent == "in_plan" and tag not in all_provides:
                issues.append(
                    f"{sid}: requires '{tag}' but no surviving subtask "
                    "provides it — the only provider vanished (a drop/merge) "
                    "without its inbound requires being rewritten (DESIGN §5 "
                    "*A drop is not symmetric with an expansion*)")
    return issues


def _validate_plan(subtasks: dict) -> None:
    """Structural validation of the merged plan — pure Python set operations.

    `requires` entries are objects `{tag, extent, reason?}` per DESIGN §5
    `requires.extent`. The JSON schema (`_REQUIRES_ITEM`) enforces the
    shape; this function enforces the conditional invariants that
    vanilla JSON Schema cannot express, and verifies the in-plan
    producer-side of cross-domain dependencies. `extent: external`
    entries are deliberately *not* checked for a provider — they are
    declared out-of-graph by the planner and surface in `plan.json`'s
    `preconditions` section."""
    errors: list[str] = []

    # all provides tags across every subtask — used for requires resolution
    all_provides: set[str] = set()
    for s in subtasks.values():
        all_provides.update(s.get("provides", []))

    all_ids = set(subtasks.keys())
    for sid, s in subtasks.items():
        if not any(sid.startswith(p) for p in _ID_PREFIXES):
            errors.append(f"{sid}: id must start with one of "
                          f"{sorted(_ID_PREFIXES)} — cross-domain collisions "
                          "and audit-trail ambiguity otherwise")
        if s.get("size") == "large":
            # Name the actual author. Reconciler-added subtasks carry
            # `_added_by_reconciler: true` (stamped in
            # `_apply_reconciler_output`). The phase 2½ size gate catches
            # reconciler-authored `large` upstream with a structured
            # retry; if one reaches this validator, the size-retry
            # exhausted and the message should say so. For planner-
            # authored `large`, the planner prompt already states the
            # rule (`prompts/planner.md`: "Never emit `size: large`") so
            # the message blames the planner directly.
            if s.get("_added_by_reconciler"):
                errors.append(
                    f"{sid}: size='large' — reconciler must split it "
                    "further (size-retry exhausted)")
            else:
                errors.append(
                    f"{sid}: size='large' — planner must split it further")
        if not (s.get("success_criteria_seed") or "").strip():
            errors.append(f"{sid}: success_criteria_seed is empty — "
                          "implementer has no starting point for criteria")
        for dep in s.get("depends_on", []):
            if dep not in all_ids:
                errors.append(
                    f"{sid}: depends_on '{dep}' which does not exist — an "
                    "id vanished from the plan without its inbound "
                    "references being rewritten (DESIGN §5 *Id-vanishing "
                    "operations*); _schedule() already dropped this edge")
        for entry in s.get("requires", []):
            # Defensive: the JSON schema rejects bare strings before this
            # function runs, but the planner output gets mutated downstream
            # (rename / promotion) so re-check shape here.
            if not isinstance(entry, dict):
                errors.append(f"{sid}: requires entry must be an object "
                              f"{{tag, extent, reason?}}, got {entry!r}")
                continue
            tag = entry.get("tag", "")
            extent = entry.get("extent", "")
            reason = (entry.get("reason") or "").strip()
            if not tag or not isinstance(tag, str):
                errors.append(f"{sid}: requires entry has empty or non-string "
                              f"tag: {entry!r}")
                continue
            if extent not in _VALID_EXTENTS:
                errors.append(f"{sid}: requires '{tag}' has unknown extent "
                              f"{extent!r} — must be one of "
                              f"{sorted(_VALID_EXTENTS)}")
                continue
            if extent == "external" and not reason:
                # Deliberately does NOT ask "why could no in-repo subtask
                # produce it?" — that was the wording here, and it is the
                # discriminating test DESIGN §5 forbids. The test is "is it
                # in THIS RUN's graph?", not "could any code produce it?": a
                # capability owned by another run, or sitting on a surface
                # the task fences off, is producible by code and still
                # external. Demanding the old justification tells a planner
                # that classified either of those correctly to defend it by
                # the criterion that causes the abort.
                errors.append(f"{sid}: requires '{tag}' with extent=external "
                              "must include a non-empty `reason` naming the "
                              "owner — another repo/ops runbook/manual step, "
                              "the run or phase document the task assigns it "
                              "to, or the surface the task fences off")
                continue
            if extent == "in_plan" and tag not in all_provides:
                errors.append(f"{sid}: requires '{tag}' but nothing provides it — "
                              "dependency is unresolvable and will be silently dropped")
        # DESIGN §5 *Artifact passing between subtasks*: the planner
        # must not name protected meta-directories (.leerie/, .git/, or
        # top-level .claude/) in files_likely_touched. The implementer's
        # check_diff_scope would reject any commit that touched them,
        # and the worker can't even `git add` such paths (the worktree
        # gitignore excludes .leerie/). Catching this at plan-
        # validation time avoids burning an implementer invocation on
        # an impossible deliverable and gives the planner a corrective
        # retry round. For coordination artifacts (research specs,
        # design summaries) the right channel is the implementer's
        # `artifacts` result field routed via provides/depends_on.
        bad_paths = [
            f for f in (s.get("files_likely_touched") or [])
            if isinstance(f, str) and _is_protected_path(f)
        ]
        if bad_paths:
            errors.append(
                f"{sid}: files_likely_touched names protected meta-"
                f"directory path(s) {bad_paths} — implementers cannot "
                "commit there (.leerie/, .git/, and top-level .claude/ "
                "are off-limits). For coordination artifacts (research "
                "specs, design summaries) use the implementer's "
                "`artifacts` result field with provides/depends_on "
                "instead of files_likely_touched (DESIGN §5 *Artifact "
                "passing between subtasks*).")

    if errors:
        bullet = "\n".join(f"  • {e}" for e in errors)
        die(f"plan validation failed ({len(errors)} issue(s)):\n{bullet}")
    log(f"plan validation: {len(subtasks)} subtasks ok")


def _warn_cross_planner_file_overlap(plans: list[dict]) -> None:
    """Log a warning when subtasks from different planner outputs both list
    the same path in `files_likely_touched`. Two planners decomposing the
    same surface produces contradictory criteria the integrator can't
    reconcile — surface that risk at plan-validation time so the user can
    re-frame the task before workers start.

    Empirically (n=3 historical runs in May 2026): a successful run had 0
    cross-planner overlaps; two failed runs had 9 and 10 respectively. The
    naive cross-prefix overlap signal had zero false positives in that
    data. This is a warning, not a hard fail — same-file overlap is
    sometimes legitimate (one planner adds scaffolding the other consumes)
    and the integrator is still the backstop. The future-work item is to
    extend the reconciler to resolve overlaps automatically (DESIGN §5)."""
    file_owners: dict[str, list[tuple[str, str]]] = {}
    for plan in plans:
        domain = plan.get("domain") or "?"
        for s in plan.get("subtasks", []):
            sid = s.get("id", "?")
            for f in s.get("files_likely_touched", []):
                file_owners.setdefault(f, []).append((domain, sid))
    overlaps = {f: owners for f, owners in file_owners.items()
                if len({d for d, _ in owners}) > 1}
    if not overlaps:
        return
    log(f"⚠  cross-planner file overlap: {len(overlaps)} file(s) claimed by "
        "multiple planners. Two planners decomposing the same surface "
        "produces contradictory subtask criteria the integrator may not "
        "be able to reconcile. Review the plan before proceeding.")
    for f, owners in sorted(overlaps.items()):
        per = ", ".join(f"{d}({sid})" for d, sid in sorted(owners))
        log(f"     {f}: {per}")


def _flatten_plans_to_subtasks(plans: list[dict]) -> dict[str, dict]:
    """Flatten a list of planner-output dicts into one dict of subtasks
    keyed by id, last write wins on a duplicate id (matching every prior
    inline occurrence of this loop). Skips any subtask missing an id."""
    subtasks: dict[str, dict] = {}
    for plan in plans:
        for s in plan.get("subtasks", []) or []:
            sid = s.get("id")
            if sid:
                subtasks[sid] = s
    return subtasks


def _warn_provider_subset_subtasks(plans: list[dict]) -> list[str]:
    """Advisory plan-time warning (DESIGN §5): flag a subtask whose ENTIRE
    `files_likely_touched` surface is owned by an ordered predecessor it
    depends on (via `depends_on` or a `requires`→`provides` tag match).

    Such a subtask is at high risk of being a mid-run no-op: if the
    predecessor commits the shared deliverable — common when a code subtask
    bundles the matching test-file edit in its own commit and a later
    test-only subtask's whole surface is that same file — the dependent
    subtask reaches its worker with nothing left to commit. That case is
    caught and settled `complete` at settle time by the mid-run satisfied
    rescue (DESIGN §8 *The mid-run sibling case*); this warning surfaces the
    same redundancy one phase earlier so the operator can re-frame the plan
    before workers run.

    Returns the flagged sids so `_settle_subtask` can re-probe those subtasks
    against the run branch BEFORE spawning their implementer, rather than
    only after one has run and produced nothing (DESIGN §8 *Probing a
    flagged subtask before it spends*). The rescue's own ordering is the
    waste: measured across the corpus, every one of run `1b9b52f5`'s three
    flagged subtasks ran a full implementer and committed nothing.

    Warning only, never a drop — a subtask may make a genuinely distinct edit
    to a shared file, and dropping it would silently delete real work (the
    same safe-direction reasoning as `_filter_satisfied_subtasks`'s
    conservative default). Pure function; mirrors
    `_warn_cross_planner_file_overlap`. Reuses `_build_predecessor_graph` so
    the notion of "predecessor" cannot drift from the scheduler's.

    Scope note: uses **direct** predecessors only (`preds[sid]` from
    `_build_predecessor_graph`), not the transitive closure. A subtask whose
    files are owned only by a *transitive* (indirect) predecessor is not
    flagged here — deliberately, to keep this advisory signal specific and
    low-noise; the mid-run satisfied rescue (DESIGN §8) still catches the
    transitive case at settle time regardless."""
    subtasks = _flatten_plans_to_subtasks(plans)
    if not subtasks:
        return []
    preds, _providers, _edge_sources = _build_predecessor_graph(subtasks)

    flagged: list[tuple[str, list[str], list[str]]] = []
    for sid, s in subtasks.items():
        own_files = {f for f in (s.get("files_likely_touched") or []) if f}
        if not own_files:
            continue  # nothing to be a subset of
        pred_ids = preds.get(sid, set())
        if not pred_ids:
            continue
        pred_files: set[str] = set()
        for p in pred_ids:
            pred_files.update(
                f for f in (subtasks[p].get("files_likely_touched") or []) if f)
        if own_files <= pred_files:
            flagged.append((sid, sorted(pred_ids), sorted(own_files)))

    if not flagged:
        return []
    log(f"⚠  provider-subset subtask(s): {len(flagged)} subtask(s) whose "
        "entire file surface is already owned by a predecessor they depend "
        "on. If the predecessor commits the shared files, the dependent "
        "subtask becomes a no-op (settled complete by the mid-run satisfied "
        "rescue, DESIGN §8) — review whether it is redundant.")
    for sid, pred_ids, files in sorted(flagged):
        preds_str = ", ".join(pred_ids)
        files_str = ", ".join(files)
        log(f"     {sid}: files [{files_str}] ⊆ predecessor(s) "
            f"[{preds_str}]")
    return sorted(sid for sid, _preds, _files in flagged)


def _sid_domain_map(plans: list[dict]) -> dict[str, str]:
    """Map every subtask id to the domain of the plan that owns it.

    The structured answer to "what kind of work is this subtask", replacing
    `sid.startswith("<abbrev>-")`. An id prefix is set once, from
    `CATEGORY_ABBREV`, and then survives operations that change what the
    subtask IS: a duplicate-provider or overlap merge folds one subtask into
    another and keeps the *survivor's* id, and `_repair_prescribed_commands`
    mints its verification subtask's id from the HOST subtask's domain. Reading
    the owning plan's domain is invariant under both
    (tests/test_no_id_prefix_dispatch.py)."""
    out: dict[str, str] = {}
    for plan in plans:
        domain = plan.get("domain") or ""
        for s in plan.get("subtasks", []) or []:
            sid = s.get("id")
            if isinstance(sid, str) and sid:
                out[sid] = domain
    return out


def _warn_test_subtask_missing_producer_edge(plans: list[dict]) -> None:
    """Advisory plan-time warning (DESIGN §5): flag a `test-`-domain subtask
    that declares NO cross-subtask edge at all (`requires` and `depends_on`
    both empty) while the plan contains code subtasks that produce artifacts.

    Scope note (2026-08-01): widening this past the `test-` prefix was tried
    and reverted. It does not catch the wiring-gate deaths it looks like it
    should — run 6146bd2f's under-wired subtask, `refactor-005`, declared 3
    `requires` and 3 `depends_on`; it was missing four *specific* edges, not
    all of them, so the both-empty condition never held regardless of prefix.
    Widening only added noise, flagging legitimate root producers that
    correctly depend on nothing. The missing-specific-edge case is the
    wiring gate's repair path, not this advisory's.

    This is the dominant real defect behind the two 2026-07-29 wiring-gate
    deaths: a testing planner, running blind to the code planners, authored a
    test whose success genuinely depends on a not-yet-created source file, but
    declared no `requires`/`depends_on` on the producer. The scheduler may then
    run the test before its producer, and the wiring gate correctly die()s.

    Why this is an ADVISORY warning and not a deterministic auto-add: the
    missing dependency is SEMANTIC, not structural. Measured against the real
    failures, the test file and the producer file share no path (the test owns
    `foo.test.ts`; the producer creates `foo-impl.ts` under a different dir, or
    the code site lives inside a large shared module), so no `files_likely_
    touched`-overlap predicate can recover the edge — and raw file overlap is
    explicitly an unreliable dependency signal (see
    `_warn_provider_subset_subtasks`). §12 assigns such prose-only facts to a
    worker: the `wiring_judge` remains the enforcer. This warning only surfaces
    the high-risk shape one phase earlier, and the `planner.md` rule reduces how
    often planners emit it.

    Heuristic (deliberately broad but low-noise): a test subtask with zero
    declared edges is almost always under-wired — a test tests *something*, and
    in a multi-subtask plan that something is usually another subtask's output.
    We do not attempt to name the producer (that requires the semantic judgment
    we are explicitly deferring); we flag the missing declaration. Silent when
    the test declares any edge, when there are no other producing subtasks, or
    on a single-subtask plan. Pure function; mirrors
    `_warn_provider_subset_subtasks`."""
    all_subtasks: list[dict] = [
        s for plan in plans for s in (plan.get("subtasks", []) or [])
    ]
    if len(all_subtasks) < 2:
        return
    # A "producer" is any subtask that declares provides or touches files —
    # i.e. something a test could depend on. Excludes the test itself below.
    def _is_producer(s: dict) -> bool:
        return bool((s.get("provides") or []) or
                    (s.get("files_likely_touched") or []))

    domains = _sid_domain_map(plans)
    flagged: list[str] = []
    for s in all_subtasks:
        sid = s.get("id", "?")
        # The owning plan's domain, not the id prefix — see `_sid_domain_map`.
        if domains.get(sid) != "testing":
            continue
        has_edge = bool((s.get("requires") or []) or (s.get("depends_on") or []))
        if has_edge:
            continue
        # Only warn if some OTHER subtask is a plausible producer.
        others_produce = any(
            o.get("id") != sid and _is_producer(o) for o in all_subtasks)
        if others_produce:
            flagged.append(sid)

    if not flagged:
        return
    log(f"⚠  under-wired test subtask(s): {len(flagged)} `test-` subtask(s) "
        "declare no requires/depends_on while the plan has producing subtasks. "
        "A test that needs a not-yet-created source file but declares no edge "
        "will be scheduled before its producer. The wiring gate repairs this "
        "when the tag has exactly one in-plan provider and dies when it is "
        "ambiguous, so this is an early warning, not a failure (DESIGN §5).")
    for sid in sorted(flagged):
        log(f"     {sid}: requires=[] depends_on=[]")


def check_duplicate_providers(plans: list[dict]) -> list[str]:
    """Deterministic duplicate-work floor beneath `phase_overlap_judge`
    (DESIGN §5 *A deterministic floor underneath the judge*). Returns a list
    of `DUPLICATE_PROVIDER` messages ([] when clean). Pure function, no
    state, no LLM.

    TWO TIERS, both decidable by set logic over already-structured planner
    fields — no prose is read (CLAUDE.md *Language-to-JSON*), which is what
    makes this a floor rather than a second opinion:

      - `DUPLICATE_PROVIDER` — same `provides` tag AND intersecting
        `files_likely_touched`: the same work to the same file. Routed into
        the M11 auto-merge by `_duplicate_provider_merge_collisions`.
      - `DUPLICATE_PROVIDER_NO_OVERLAP` — same tag, no shared file. Advisory
        only, never auto-merged: folding is right for duplicate work and
        wrong for a mis-declared tag, and set logic cannot tell them apart.

    The second tier exists because the first one's file requirement
    suppresses the most common real shape. When neither subtask has created
    the artifact yet each planner INVENTS the path, so two subtasks authoring
    one file essentially never share a `files_likely_touched` entry — which is
    why the residue this floor exists to stop is test- and changelog-shaped.
    Run `3e65e793` had three subtasks all declaring
    `captcha-inject-submit-primitive-tested` under three different invented
    test filenames; all three were implemented, and the next run deleted one
    as vacuous and folded another.

    Why a floor at all, when the `plan_overlap_judge` above it has 100% recall
    on the corpus: recall *when the judge runs* is not coverage of the class.
    The judge is cheap-skipped on single-planner runs, skippable via
    `--skip-overlap-judge`, and — before the re-plan repair in DESIGN §5 — was
    bypassable entirely by a downstream gate re-planning after it had passed.
    In each of those cases nothing checked this class at all. So the §12 split
    applies as it does at every other gate: judgment keeps the semantic call,
    a mechanical check catches the shape that needs no judgment.

    THREE EXCLUSIONS, ALL LOAD-BEARING, NOT OPTIMIZATIONS. Each names a
    structure that makes "same tag" true by CONSTRUCTION rather than by
    defect (enforced in `_iter_duplicate_provider_pairs`):

    1. `_cofile_cluster` — deliberate sub-file region splits of one file
       (DESIGN §5½ (P1) *Sub-file*): same tag and same path by construction.
       Without the exclusion this rule matches 3571 pairs across the run
       corpus; with it, 9 — falling in exactly two runs, both of which were
       destroyed by duplicate work (`392b5e7f` died at the phase-3 wiring
       gate; `19a70d96` executed both duplicates and was refused at the
       integration gate after 4.7 hours and 164 workers). The other 50 corpus
       runs produce no flags.
    2. `_newfile_owner_id` — deliberate MULTI-file splits. `_migration_child`
       copies the parent's `provides` to every chunk verbatim while the chunks
       own disjoint files, and only `_cofile_child` sets `_cofile_cluster`, so
       exclusion 1 does not reach this shape. Without it the no-overlap tier
       flags run `5fa2052b`'s `config-002-{1,2,3}` — one deliberate three-way
       split — as three duplicate pairs.
    3. Ordering by `depends_on`/`requires` — **NO-OVERLAP TIER ONLY.** For the
       file-overlap tier this exemption was measured across the corpus and
       correctly rejected (ZERO flagged pairs were ordered), and it stays
       rejected there. For the tag-only tier it is required: an ordered chain
       whose links each declare a shared umbrella tag is the dominant
       LEGITIMATE shape, and this repo's own three-layer rule generates it —
       corpus run `3a4abba3` pairs docs/DESIGN.md with docs/IMPLEMENTATION.md,
       both providing `nl-regex-migration-spec`, the second depends_on the
       first. Resolved through `_build_predecessor_graph(quiet=True)` so the
       definition of "edge" cannot drift from the scheduler's.

    With all three, the 0.28.0 corpus yields 10 flags across 3 of 66 plans,
    all adjudicated true positives, and the pinned false-positive corpus
    (`tests/fixtures/wiring_repair_corpus`) stays clean.

    Advisory as shipped — the caller logs these rather than gating on them,
    pending confirmation across live runs (DESIGN §5)."""
    issues: list[str] = []
    for sid_a, sid_b, tag, shared, kind in _iter_duplicate_provider_pairs(
            plans):
        if kind == "overlap":
            issues.append(
                f"DUPLICATE_PROVIDER: {sid_a} and {sid_b} both "
                f"provide {tag!r} and both touch "
                f"{', '.join(sorted(shared))} — two subtasks doing the "
                "same work to the same file. One should be dropped or "
                "merged into the other, or they should be sequenced with "
                "an explicit depends_on and given distinct surfaces "
                "(DESIGN §5 *Cross-domain surface overlap*)")
        else:
            issues.append(
                f"DUPLICATE_PROVIDER_NO_OVERLAP: {sid_a} and {sid_b} both "
                f"provide {tag!r} but share no file. One tag with two "
                "producers is a plan defect either way: either they are the "
                "same work under two independently invented paths (the "
                "usual shape for a new test or changelog file, where each "
                "planner names the file itself), or one of them consumes "
                "the tag and mis-declared it as `provides`. Fold them into "
                "one subtask, or correct the mis-declared tag "
                "(DESIGN §5 *A deterministic floor underneath the judge*)")
    return issues


def _transitive_predecessors(
        preds: dict[str, set[str]]) -> dict[str, set[str]]:
    """Transitive closure of `_build_predecessor_graph`'s DIRECT-predecessor
    map. Pure, and deliberately cycle-tolerant: the acyclicity gate is a
    separate phase (2½), so this can be handed a graph that still has a
    cycle and must terminate anyway rather than recursing forever. The
    `seen` set does that — a cycle simply yields "everything reachable",
    which is the right answer for an ordering question."""
    out: dict[str, set[str]] = {}
    for sid in preds:
        seen: set[str] = set()
        stack = list(preds.get(sid, ()))
        while stack:
            cur = stack.pop()
            if cur in seen:
                continue
            seen.add(cur)
            stack.extend(preds.get(cur, ()))
        out[sid] = seen
    return out


def _iter_duplicate_provider_pairs(
        plans: list[dict]) -> Iterator[tuple[str, str, str, set[str], str]]:
    """Shared detection loop behind `check_duplicate_providers` and
    `_duplicate_provider_merge_collisions`: builds the tag->providers map,
    then yields `(sid_a, sid_b, tag, shared_files, kind)` for every pair of
    subtasks declaring the same `provides` tag, where `kind` is:

      - `"overlap"`    — they also share a file (`shared_files` non-empty);
      - `"no_overlap"` — only the tag is shared (`shared_files` empty).

    File comparison is `_paths_designate_same_file` (component-wise), so a
    repo-root prefix on one side does not read as disjoint.

    Three exclusions, each naming a structure that makes "same tag" true by
    construction rather than by defect — all LOAD-BEARING, not optimizations;
    see `check_duplicate_providers`'s docstring for the corpus measurements
    they rest on: `_cofile_cluster` (sub-file region splits),
    `_newfile_owner_id` (multi-file splitter chunks), and — for the
    `no_overlap` tier ONLY — an existing `depends_on`/`requires` ordering.

    Callers differ only in what they do with a found pair (an advisory issue
    string vs. a merge-collision dict), and only the `overlap` tier is
    auto-merged."""
    subtasks = _flatten_plans_to_subtasks(plans)

    providers: dict[str, list[str]] = {}
    for sid, s in subtasks.items():
        for tag in s.get("provides", []) or []:
            if isinstance(tag, str) and tag.strip():
                providers.setdefault(tag, []).append(sid)

    def _files(s: dict) -> set[str]:
        # `_normalize_artifact_path`, not `os.path.normpath`: both sides are
        # planner-authored repo-relative strings, which is exactly what that
        # helper is for, and it is what the sibling NO_FILE_OVERLAP check in
        # `check_overlap_judge_output` already uses. It additionally strips a
        # leading `/`, which normpath keeps — so `/src/x.ts` and `src/x.ts`
        # read as the same file instead of as a missed duplicate.
        return {
            _normalize_artifact_path(f)
            for f in (s.get("files_likely_touched") or [])
            if isinstance(f, str) and f.strip()
        }

    # Transitive predecessors, for the no-overlap tier's ordering exclusion
    # below. `_build_predecessor_graph` is the one definition of "edge" every
    # consumer of the subtask DAG shares (depends_on plus requires/provides
    # tag matches), so this cannot drift from what the scheduler believes.
    #
    # It is handed a NULL-NORMALIZED view, not `subtasks` directly. This
    # floor is documented total — it runs on every path, above every skip
    # flag, on raw planner output that `_validate_plan` has not seen yet —
    # and its own reads are all `or []`-guarded for exactly that reason.
    # `_build_predecessor_graph`'s are not (`s.get("depends_on", [])` returns
    # None for a present-but-null key), so calling it unguarded would make a
    # `provides`/`depends_on`/`requires` of `null` raise TypeError out of a
    # function that previously tolerated it, killing the run at phase 2¾.
    # Normalizing here rather than inside the shared builder keeps eleven
    # other DAG consumers untouched by a duplicate-detection change.
    _ordering_view = {
        sid: {**s,
              "provides": s.get("provides") or [],
              "depends_on": s.get("depends_on") or [],
              "requires": s.get("requires") or []}
        for sid, s in subtasks.items()
    }
    preds = _transitive_predecessors(
        _build_predecessor_graph(_ordering_view, quiet=True)[0])

    for tag in sorted(providers):
        sids = sorted(providers[tag])
        for i in range(len(sids)):
            for j in range(i + 1, len(sids)):
                a, b = subtasks[sids[i]], subtasks[sids[j]]
                cluster = a.get("_cofile_cluster")
                if cluster and cluster == b.get("_cofile_cluster"):
                    continue  # deliberate sub-file split of one file
                # SECOND LOAD-BEARING EXCLUSION, and for the same reason as
                # `_cofile_cluster` above: a MULTI-FILE splitter chunk
                # (`_migration_child`) copies the parent's `provides` to every
                # child verbatim, so same-tag is guaranteed by construction
                # while the chunks own deliberately disjoint files. Only
                # `_cofile_child` sets `_cofile_cluster`, so the sub-file
                # exclusion does not cover this shape. Both child builders do
                # set `_newfile_owner_id` to the one designated owner, which
                # is what makes it a sound sibling marker. Measured: without
                # this, widening the rule below flags run `5fa2052b`'s
                # config-002-{1,2,3} — one deliberate three-way split — as
                # three duplicate pairs; with it, the widened rule produces
                # zero false positives across the 66-plan corpus.
                owner = a.get("_newfile_owner_id")
                if owner and owner == b.get("_newfile_owner_id"):
                    continue
                # THIRD EXCLUSION, and it applies ONLY to the no-overlap tier
                # below. `check_duplicate_providers`'s docstring records that
                # an "already ordered by depends_on" exemption was measured
                # against the corpus and deliberately left out — that finding
                # is about the FILE-OVERLAP tier, where zero flagged pairs
                # were ordered, and it still stands there.
                #
                # For the tag-only tier the same shape is the dominant
                # LEGITIMATE one: an ordered chain whose links each also
                # declare a shared umbrella tag for the capability they
                # jointly deliver. This repo's own three-layer rule generates
                # it constantly — corpus run 3a4abba3 has docs-001
                # (docs/DESIGN.md) and docs-002 (docs/IMPLEMENTATION.md) both
                # providing `nl-regex-migration-spec`, with docs-002
                # depends_on docs-001. Two subtasks an explicit edge already
                # sequences are not racing to author one artifact.
                #
                # The cost is honest and bounded: a consumer that mis-declares
                # a tag it merely uses (run `c1f45fd0`'s feat-007 declares
                # `agent-chat-client`, which feat-003 produces and it
                # depends_on) is structurally identical to the legitimate
                # shape and is no longer flagged. That is the cheaper error —
                # a mis-declared tag on an already-ordered pair produces no
                # duplicate work, which is what this floor exists to stop.
                ordered = (sids[j] in preds.get(sids[i], set())
                           or sids[i] in preds.get(sids[j], set()))
                shared = {
                    fa for fa in _files(a)
                    if any(_paths_designate_same_file(fa, fb)
                           for fb in _files(b))
                }
                # Two tiers. Sharing a file is the historical rule. Sharing
                # only the TAG is the shape that let three subtasks in run
                # `3e65e793` each write the same test under a different
                # invented filename: the judge saw all three declare
                # `provides=captcha-inject-submit-primitive-tested`, and
                # withdrew the finding anyway because no path literally
                # matched. One tag with two producers is a plan defect either
                # way — genuine duplicate work, or a mis-declared tag (run
                # `c1f45fd0`'s feat-007 declares the tag it CONSUMES) — so it
                # is surfaced, with the kind carried so callers can treat the
                # weaker signal more conservatively.
                if not shared and ordered:
                    continue
                yield (sids[i], sids[j], tag, shared,
                       "overlap" if shared else "no_overlap")


def _duplicate_provider_merge_collisions(plans: list[dict]) -> list[dict]:
    """Synthesize `merge` collisions for every pair `check_duplicate_providers`
    would flag, shaped for `_apply_overlap_collisions` (M11 DECISION: the
    duplicate-provider floor's detections are routed into a merge resolution
    rather than left purely advisory).

    Shares `_iter_duplicate_provider_pairs` with `check_duplicate_providers`
    so the two cannot drift in what counts as a duplicate; they differ only in
    what they do with a found pair (an advisory issue string vs. a
    merge-collision dict).

    ONLY THE FILE-OVERLAP TIER IS AUTO-MERGED. A `no_overlap` pair is a real
    defect too, but its RESOLUTION is ambiguous in a way this synthesizer
    cannot decide: folding is right when the pair is duplicate work, and wrong
    when one side merely mis-declared a tag it consumes, where the fix keeps
    both subtasks. Auto-merging that case would delete a live subtask, so it
    stays advisory and the judge — which reads intent — owns the call.

    Every returned collision has `resolution: "merge"`, so the N-way case
    (three or more subtasks sharing one tag, pairwise) is not a separate
    code path: `_apply_overlap_collisions` already folds a connected
    cluster of merges into one survivor via its anchor + transitive
    `survivor_of` resolution — safe specifically because a merge's intent
    assembly carries the absorbed subtask's full intent forward (unlike a
    `drop`, where the analogous transitive chase silently discards a live
    subtask — see `_apply_multidrop`'s docstring). The closing edge of such
    a cluster (e.g. pair (B, C) once A↔B and A↔C have already collapsed
    both to the same survivor) is recorded as `skipped_redundant` by that
    helper rather than double-applied."""
    collisions: list[dict] = []
    for sid_a, sid_b, tag, shared, kind in _iter_duplicate_provider_pairs(
            plans):
        # Only the file-overlap tier is auto-merged. A `no_overlap` pair is a
        # real defect (see `check_duplicate_providers`) but its RESOLUTION is
        # ambiguous in a way this synthesizer cannot decide: folding two
        # subtasks is right when they are duplicate work, and wrong when one
        # merely mis-declared a tag it consumes — where the fix is to correct
        # the tag and keep both. Auto-merging that case would delete a live
        # subtask. It stays advisory, and the judge (which reads intent) owns
        # the call.
        if kind != "overlap":
            continue
        collisions.append({
            "a_sid": sid_a, "b_sid": sid_b,
            "resolution": "merge",
            "artifact": tag,
            "merge_feasibility": (
                f"deterministic duplicate-provider floor: both "
                f"subtasks declare provides={tag!r} and both touch "
                f"{', '.join(sorted(shared))} — merged rather than "
                "left as duplicate work (DESIGN §5 *A deterministic "
                "floor underneath the judge*, M11 DECISION)"),
            "reason": "DUPLICATE_PROVIDER",
        })
    return collisions


# Domains whose subtasks WRITE the code a test subtask would assert against.
# Compared against each subtask's own plan domain, never against its id: ids are
# re-homed when a duplicate-provider/overlap merge folds one subtask into
# another, and `_repair_prescribed_commands` synthesises ids from a *host*
# subtask's domain — so an id prefix is not evidence of what the work is
# (tests/test_no_id_prefix_dispatch.py).
_TEST_OWNERSHIP_CODE_DOMAINS = frozenset(
    {"bug-fixing", "feature-implementation", "refactoring"})


def check_test_ownership_overlap(plans: list[dict]) -> list[str]:
    """Deterministic floor beneath `TEST_OWNERSHIP_RISK`
    (`check_classifier_output`, leerie.py:5798) and `phase_overlap_judge`
    (DESIGN §5 *Cross-domain surface overlap*). Returns a list of
    `TEST_OWNERSHIP_OVERLAP` messages ([] when clean). Pure function, no
    state, no LLM — mirrors `check_duplicate_providers` above.

    `TEST_OWNERSHIP_RISK` correctly identifies that a code category
    (bug-fixing / feature-implementation / refactoring) and `testing`
    running blind to each other can both author the same test file — but
    that check only nudges the classifier at classify time; nothing
    mechanically catches the case where the classifier proceeds anyway (or
    a re-plan reintroduces the overlap downstream, the same "bypassed a
    passed gate" shape `check_duplicate_providers`'s own docstring
    documents). This is that mechanical catch, applied to
    `files_likely_touched` instead of `provides` tags, since the collision
    here is on file OWNERSHIP, not on a declared capability: a testing-
    domain subtask and a code-domain subtask both listing the same file is
    exactly the shape that made the plan-overlap judge refuse as
    unresolvable in the barnacle fake-timer incident this check exists for.

    Domain is read off the `CATEGORY_ABBREV` id prefix (`test-` for
    `testing`; `bugfix-`/`feat-`/`refactor-` for the three
    `_TEST_OWNERSHIP_RISK_CODE_CATS` categories), the same convention
    `_warn_test_subtask_missing_producer_edge` already relies on for the
    testing side. Paths are compared via `_normalize_artifact_path`, per
    that function's own docstring recommendation and matching the sibling
    `check_duplicate_providers`/`NO_FILE_OVERLAP` checks.

    Advisory as shipped — logged, never gating, matching this repo's
    disposition for `check_duplicate_providers` (DESIGN §5)."""
    subtasks = _flatten_plans_to_subtasks(plans)

    def _files(s: dict) -> set[str]:
        return {
            _normalize_artifact_path(f)
            for f in (s.get("files_likely_touched") or [])
            if isinstance(f, str) and f.strip()
        }

    # Domain, not id prefix — see `_sid_domain_map`.
    domains = _sid_domain_map(plans)
    test_sids = sorted(sid for sid in subtasks
                       if domains.get(sid) == "testing")
    code_sids = sorted(
        sid for sid in subtasks
        if domains.get(sid) in _TEST_OWNERSHIP_CODE_DOMAINS)

    issues: list[str] = []
    for test_sid in test_sids:
        test_files = _files(subtasks[test_sid])
        if not test_files:
            continue
        for code_sid in code_sids:
            shared = test_files & _files(subtasks[code_sid])
            if not shared:
                continue
            issues.append(
                f"TEST_OWNERSHIP_OVERLAP: {test_sid} (testing) and "
                f"{code_sid} (code) both touch "
                f"{', '.join(sorted(shared))} — running blind to each "
                "other, both can author or rewrite the same test file with "
                "incompatible contracts (DESIGN §5 *Cross-domain surface "
                f"overlap*). {code_sid} should own the file unless the "
                f"plan gives {test_sid} an explicit depends_on/requires "
                "edge on it."
            )
    return issues


# "credential" was removed 2026-08-14. This heuristic is about env-FILE
# plumbing -- does anything update .env.example when a subtask provides an env
# contract -- and "credential" matches the domain concept instead, which is a
# different thing entirely. Measured, both of its firings in one run were false:
# `credential-field-docurl-support` (adding a docUrl to a form field spec) and
# `passare-credential-check-helper` (a client-side API ping), neither touching
# env files or wanting to (tests/test_advisory_signals_match_their_status.py). The remaining
# keywords name configuration plumbing rather than a subject area.
_ENV_TAG_KEYWORDS = frozenset({"env", "bootstrap", "secret", "config-key"})


def _warn_layer_gaps(plans: list[dict]) -> None:
    """Advisory cross-domain layer-gap warnings (DESIGN §5).

    Runs on the reconciled plan before scheduling. Two heuristics:
    1. schema.prisma touched but no seed/migration files in any subtask.
    2. provides tags with env/bootstrap/secret keywords but no .env.example
       touched."""
    all_files: set[str] = set()
    all_provides: list[tuple[str, str]] = []
    for plan in plans:
        for s in plan.get("subtasks", []):
            sid = s.get("id", "?")
            all_files.update(s.get("files_likely_touched") or [])
            for tag in s.get("provides") or []:
                all_provides.append((sid, tag))

    # Heuristic 1: DB schema without seed/migration
    touches_schema = any(
        "schema.prisma" in f for f in all_files)
    touches_seed = any(
        "seed.ts" in f or "seed.js" in f or "seed.py" in f
        for f in all_files)
    touches_migration = any("migrations/" in f for f in all_files)
    if touches_schema and not (touches_seed or touches_migration):
        log("⚠  LAYER_GAP: schema.prisma modified but no subtask "
            "touches seed or migration files — database initialization "
            "may be incomplete")

    # Heuristic 2: env-contract provider without env docs
    env_provider_sids = [
        sid for sid, tag in all_provides
        if any(kw in tag.lower() for kw in _ENV_TAG_KEYWORDS)]
    touches_env_template = any(
        ".env.example" in f or ".env.local.example" in f
        or ".env.template" in f for f in all_files)
    if env_provider_sids and not touches_env_template:
        log(f"⚠  LAYER_GAP: subtasks {env_provider_sids} provide "
            "env/bootstrap/secret capabilities but no subtask updates "
            ".env.example or env documentation")


def _resolves_under(path_str: str, root: Path) -> bool:
    """True iff `path_str` (relative or absolute) resolves under `root`.
    Resolves symlinks so a planner cannot sneak a path through with a
    symlinked decoy. Returns False on any OSError or ValueError —
    treated by the caller as "not under root," which fails the check
    and triggers a drop (the safe direction)."""
    try:
        candidate = Path(path_str)
        if not candidate.is_absolute():
            candidate = root / candidate
        return candidate.resolve().is_relative_to(root.resolve())
    except (OSError, ValueError):
        return False


def _apply_subtask_drop_propagation(
    plans: list[dict], dropped: dict[str, dict], st: "State") -> None:
    """Shared 'apply an id-vanishing subtask drop' tail (DESIGN §5
    *Id-vanishing operations*) for `_filter_offtree_subtasks` and
    `_filter_satisfied_subtasks`. `dropped` maps sid -> drop-record dict
    (each carrying at least a `"provides"` list); the caller has already
    removed the dropped subtasks from `plan["subtasks"]` before calling
    this. Prunes dangling `depends_on` references to the vanished ids,
    prunes orphaned `requires` tags only the dropped subtasks provided,
    and persists the drop record to `st.data["dropped_subtasks"]`.

    Logging is deliberately NOT done here — the two callers' log wording
    differs and stays caller-specific. `st.save()` here is each caller's
    own final checkpoint write for this drop; its position in the existing
    call sequence must not change (see CLAUDE.md's checkpoint-ordering
    discipline)."""
    # A dropped id can no longer satisfy any dependent, so prune every inbound
    # `depends_on` reference to it (DESIGN §5 *Id-vanishing operations*).
    # Without this the edge dangles: _schedule() drops it silently and
    # _validate_plan then die()s the run.
    pruned = {sid: [] for sid in dropped}
    dropped_provides = {t for info in dropped.values()
                        for t in info.get("provides", [])}
    for plan in plans:
        _remap_vanished_deps(plan.get("subtasks", []), pruned)
    # A drop also orphans the tag channel — the dropped subtasks' provides are
    # gone, so prune any inbound `requires` naming a tag only they provided
    # (DESIGN §5 *Id-vanishing operations*, the drop half). Called once over all
    # plans (NOT per-plan): capability tags are cross-domain, so a tag provided
    # by a surviving subtask in another plan must not be pruned.
    _prune_orphaned_requires(plans, dropped_provides)
    st.data.setdefault("dropped_subtasks", {}).update(dropped)
    st.save()


def _filter_offtree_subtasks(plans: list[dict], repo_root: Path,
                            inspect_dirs: list[str], st: "State") -> None:
    """Mutate `plans` in place: drop any subtask whose `files_likely_touched`
    contains a path that does not resolve under `repo_root`. Record drops
    in `st.data["dropped_subtasks"]` and log a per-subtask warning. Soft
    drop — the run continues with the surviving subtasks, `_schedule()`
    runs after this and sees a clean plan.

    Motivation: cross-repo `--inspect-dir` runs let the planner read
    files in mounts like `/inspect/api/...`, and the planner sometimes
    names those paths in `files_likely_touched` for an implementer that
    can only modify the run's primary worktree. The implementer either
    fails outright or clones the inspected repo into `/tmp` and edits
    there — those edits never reach the subtask branch, and
    `check_branch_has_commits` correctly fails the subtask.

    Why a soft drop and not `die()`: a hard fail here is unrecoverable
    via `resume`. The resume branch in `_run_phases` does not re-run
    `phase_plan` or this filter, and `state.json["waves"]` is only
    written by `_write_plan` which runs after `_schedule()`. Soft drop
    matches the existing `_warn_cross_planner_file_overlap` pattern at
    the same pre-_schedule layer."""
    inspect_roots = [Path(d).resolve() for d in (inspect_dirs or [])]
    dropped: dict[str, dict] = {}
    for plan in plans:
        survivors = []
        for s in plan.get("subtasks", []):
            sid = s.get("id", "?")
            offtree_paths = [
                f for f in (s.get("files_likely_touched") or [])
                if not _resolves_under(f, repo_root)
            ]
            if not offtree_paths:
                survivors.append(s)
                continue
            reasons = []
            for f in offtree_paths:
                leaked = next((str(r) for r in inspect_roots
                               if _resolves_under(f, r)), None)
                if leaked:
                    reasons.append(
                        f"{f!r} resolves under inspect-dir {leaked!r} "
                        "(read-only; implementer cannot modify)")
                else:
                    reasons.append(
                        f"{f!r} does not resolve under repo root "
                        f"{str(repo_root)!r}")
            # Capture provides here, before the survivor-filter below drops
            # the subtask object — needed to prune the tag channel (DESIGN §5).
            dropped[sid] = {"reasons": reasons, "files": offtree_paths,
                            "provides": list(s.get("provides") or [])}
        plan["subtasks"] = survivors
    if not dropped:
        return
    log(f"⚠  _filter_offtree_subtasks: dropped {len(dropped)} subtask(s) "
        "with off-tree files_likely_touched:")
    for sid, info in sorted(dropped.items()):
        for r in info["reasons"]:
            log(f"     {sid}: {r}")
    _apply_subtask_drop_propagation(plans, dropped, st)


def _probe_drop_reason(verdict: dict) -> str | None:
    """Map a satisfied_probe verdict to a soft-drop reason, or None to keep.

    Pure typed-field logic (Language-to-JSON): `satisfied: true` drops as
    `"already_satisfied"`; a not-satisfied verdict drops as
    `"equivalent_coverage"` only when ALL THREE typed fields agree —
    `unsatisfied_reason == "artifact_missing"` (the planner-named artifact
    is absent), `equivalent_coverage_exists is True` (the criteria's
    substance is already met on the tree under another artifact name), and
    `sibling_invalidation_risk is False` (an EXPLICIT false — the probe
    affirmed no surviving sibling's pending work would break the
    criteria). Any other combination, or any field absent, keeps the
    subtask — absence defaults to the safe direction, and the explicit-
    false requirement keeps the sibling-invalidation channel keep-only by
    construction rather than by prompt (DESIGN §8 *A "not satisfied"
    verdict carries a typed reason*).
    """
    if verdict.get("satisfied") is True:
        return "already_satisfied"
    if (verdict.get("unsatisfied_reason") == "artifact_missing"
            and verdict.get("equivalent_coverage_exists") is True
            and verdict.get("sibling_invalidation_risk") is False):
        return "equivalent_coverage"
    return None


def _satisfied_falsifier_item(s: dict) -> dict:
    """The item the base-tree falsifier checks for subtask `s` (DESIGN §8
    *A subtask is dropped as already satisfied only when the falsifier
    cannot show its criterion unmet on the base*): its `intent` as the
    item and its `success_criteria_seed` as the item's one part — the
    seed alone is often "these tests pass", which cannot show the gap —
    or the seed alone when the intent is blank."""
    intent = str(s.get("intent") or "").strip()
    seed = str(s.get("success_criteria_seed") or "").strip()
    ref = f"subtask {s.get('id', '?')}"
    if not intent:
        return {"item": seed, "source_ref": ref}
    return {"item": intent, "parts": [seed] if seed else [],
            "source_ref": ref}


async def _falsify_satisfied_drops(
        st: "State", caps: dict, models: dict[str, str],
        efforts: dict[str, str | None], base_sha: str,
        subtasks: dict[str, dict], dropped: dict[str, dict],
        cache: dict[str, dict]) -> None:
    """Take out of `dropped` every `already_satisfied` drop whose criterion
    the falsifier shows unmet on the base tree `base_sha` (DESIGN §8 *A
    subtask is dropped as already satisfied only when the falsifier cannot
    show its criterion unmet on the base*). A subtask whose cache entry
    already records the falsifier's outcome is decided from it; the rest
    go to one `_falsify_items` call, and each outcome is cached under the
    verdict's base sha. A falsifier that cannot run, or records nothing for
    a subtask, leaves its drop as the probe decided, uncached."""
    todo: list[str] = []
    for sid in sorted(dropped):
        if dropped[sid].get("reason") != "already_satisfied":
            continue
        rec = (cache.get(sid) or {}).get("falsifier")
        if isinstance(rec, dict) and "confirmed" in rec:
            if rec["confirmed"]:
                dropped.pop(sid)
                log(f"  satisfied-probe {sid}: kept — the falsifier showed "
                    "its criterion unmet on the base (cached)")
            continue
        if sid in subtasks:
            todo.append(sid)
    if not todo:
        return
    log(f"phase 3: falsifier on {len(todo)} subtask(s) the satisfied-probe "
        "found already met — a drop stands only when no probe shows the "
        "criterion unmet on the base (DESIGN §8)")
    normalized = [_delivery_norm_item(_satisfied_falsifier_item(subtasks[sid]))
                  for sid in todo]
    progress: dict = {"items": {}}
    try:
        meta = await _falsify_items(
            st, caps, models, efforts, sha=base_sha, normalized=normalized,
            indices=list(range(len(todo))), parts_by_idx={},
            progress=progress, base_claim=True,
            names={i: f"base-{sid}" for i, sid in enumerate(todo)},
            probes_root=st.run_dir / "satisfied-probe" / "probes",
            persist=None)
    except WorkerError:
        # Budget exhaustion is the hard backstop: it stops the run.
        raise
    except Exception as e:
        log(f"  satisfied-probe: falsifier raised {type(e).__name__}: {e} — "
            "the probe's drops stand")
        return
    if meta.get("skipped"):
        log(f"  satisfied-probe: falsifier not run — {meta['skipped']}; the "
            "probe's drops stand")
    for i, sid in enumerate(todo):
        fi = (progress.get("items") or {}).get(str(i))
        if not isinstance(fi, dict):
            continue
        confirmed = bool(fi.get("confirmed"))
        if sid in cache:
            cache[sid]["falsifier"] = {"confirmed": confirmed,
                                       "samples": fi.get("samples") or []}
        if confirmed:
            dropped.pop(sid, None)
            s_ = next((x for x in fi.get("samples") or []
                       if isinstance(x, dict) and x.get("confirmed")), {})
            log(f"  satisfied-probe {sid}: kept — a falsifier probe of "
                f"\"{_scope_norm(str(s_.get('item_span_quote') or ''))[:160]}\" "
                "fails under B* on the base")
    st.save()


async def _filter_satisfied_subtasks(
    plans: list[dict], repo_root: Path, st: "State", caps: dict,
    models: dict[str, str], efforts: dict[str, str | None],
    protect: set[str] | None = None,
) -> dict[str, str] | None:
    """Mutate `plans` in place: drop any subtask whose success criteria
    are already met on the base tree (DESIGN §8 *Already-satisfied
    subtask elimination*). Spawns one read-only `satisfied_probe` worker
    per surviving subtask (bounded by `max_parallel`), each judging that
    subtask's `success_criteria_seed` against the current checkout, and
    soft-drops the ones the probe marks `satisfied`. Recorded in
    `st.data["dropped_subtasks"]` with `reason: "already_satisfied"` plus
    the probe's evidence — the same audit shape as
    `_filter_offtree_subtasks` — unless the falsifier shows its criterion
    unmet on the base first (`_falsify_satisfied_drops`, DESIGN §8 *A
    subtask is dropped as already satisfied only when the falsifier cannot
    show its criterion unmet on the base*). A not-satisfied verdict whose typed
    fields agree (`unsatisfied_reason == "artifact_missing"`,
    `equivalent_coverage_exists`, and an explicit
    `sibling_invalidation_risk: false`) drops the same way with
    `reason: "equivalent_coverage"` — see `_probe_drop_reason` and
    DESIGN §8 *A "not satisfied" verdict carries a typed reason*.

    Returns a `no_work_map` (`domain → basis`) IFF the drop empties every
    `status == "ready"` plan (so the caller routes to
    `_finish_no_work_run`, the same terminal state as the native
    cleared-but-empty case, DESIGN §8). Returns None otherwise — the run
    proceeds to `_schedule()` with the surviving subtasks. A `status ==
    "blocked"` plan with zero subtasks does NOT trigger the no-work route
    (it must still fall to `_schedule()`'s all-blocked `die`), mirroring
    `_detect_no_work`'s ready-only guard.

    Soft drop, not `die()`: same resume-safety reasoning as
    `_filter_offtree_subtasks` — the drop happens on the plan→_schedule
    path that `resume` does not re-run, and `state.json["waves"]` is
    only written by `_write_plan` after `_schedule()`, so a surviving-only
    plan is what gets persisted. The gate is advisory and subordinate to
    the mechanical `check_branch_has_commits` backstop (§12): a
    false-negative (probe says "still needed" when it was done) costs one
    implementer round the backstop already tolerates; the probe is tuned
    to prefer that over a false-positive that would silently delete real
    work. The probe runs with `SATISFIED_PROBE_TOOLS` (a base-tree-only
    subset of INSPECT_TOOLS — no history-spanning git, see that
    constant's rationale).

    Ids in `protect` are never probed, so never dropped: the caller passes
    the symptom-fixing subtasks while the held-out acceptance sets fail on
    HEAD (`_fix_ids_held_out_sets_protect`, DESIGN §8 — executed evidence
    outranks the probe's reading)."""
    if st.data.get("skip_satisfied_check"):
        log("phase 3: satisfied-check skipped (--skip-satisfied-check / "
            "LEERIE_SKIP_SATISFIED_CHECK)")
        return None

    # Flatten to (plan, subtask) pairs so the probe results can be applied
    # back to the owning plan. Only subtasks carrying a non-empty success
    # criterion are probeable — without a criterion there is nothing to
    # judge "already met" against, so such a subtask always survives.
    probeable: list[dict] = []
    total = 0
    protect = protect or set()
    for plan in plans:
        for s in plan.get("subtasks", []) or []:
            total += 1
            if s.get("id") in protect:
                continue
            if (s.get("success_criteria_seed") or "").strip():
                probeable.append(s)
    if protect:
        log(f"phase 3: {len(protect)} subtask(s) fixing the reported symptom "
            "kept out of the satisfied-probe — the held-out acceptance sets "
            f"fail on HEAD: {', '.join(sorted(protect))}")
    if not probeable:
        return None

    log(f"phase 3: satisfied-probe over {len(probeable)} subtask(s) "
        f"(base-tree already-satisfied check, DESIGN §8)")
    st.data["current_phase"] = "phase 3: satisfied-probe"
    st.save()

    # base_sha scopes the cache to the current tree identity (DESIGN §6
    # "Correctness-critical: the cache is scoped to the base-tree commit
    # sha"). A cached verdict recorded under a different sha describes a
    # tree that no longer exists (HEAD moved between a pause and a resume
    # — e.g. a sibling run merged its own PR) and must be treated as
    # absent, never trusted stale. It names the tree the probe judges (the
    # working branch's tip, see `_base_tree_sha`), not the live HEAD.
    base_sha = await _base_tree_sha(str(repo_root), st)
    cache: dict[str, dict] = st.data.setdefault("satisfied_probe_cache", {})

    sys_prompt = _load_prompt("satisfied_probe")
    sem = asyncio.Semaphore(caps["max_parallel"])
    # sid → drop record; only satisfied subtasks land here.
    dropped: dict[str, dict] = {}

    # Sibling-invalidation context (DESIGN §8 *The sibling-invalidation case*).
    # A subtask can be satisfied on the base tree NOW yet be broken mid-run by
    # another subtask in the same plan (e.g. a parity/coverage test dropped as
    # already-satisfied while a feature subtask adds the keys/files it guards).
    # The base-tree-only probe is structurally blind to this, so we hand it the
    # other subtasks' declared surface (provides + files_likely_touched) as
    # context for a *keep* decision only — never a substitute for judging the
    # tree. This is a static snapshot of ALL other subtasks taken before the
    # sweep runs (drops are decided concurrently as probes return, so we do not
    # yet know which siblings will themselves be dropped — that is fine: the
    # snapshot only ever drives the safe direction, a keep). Computed once
    # (plan-static); each probe sees every OTHER subtask's surface (keyed by sid
    # so a subtask never counts itself as its own sibling).
    all_subtasks: list[dict] = [
        s for plan in plans for s in (plan.get("subtasks", []) or [])
    ]
    sibling_surface: dict[str, list[dict]] = {}
    for s in all_subtasks:
        sid_s = s.get("id", "?")
        others = []
        for o in all_subtasks:
            if o.get("id", "?") == sid_s:
                continue
            prov = list(o.get("provides") or [])
            files = list(o.get("files_likely_touched") or [])
            if prov or files:
                others.append({
                    "id": o.get("id", "?"),
                    "title": o.get("title", ""),
                    "provides": prov,
                    "files_likely_touched": files,
                })
        sibling_surface[sid_s] = others

    async def probe_one(s: dict) -> None:
        sid = s.get("id", "?")
        cached = cache.get(sid)
        if cached is not None and cached.get("base_sha") == base_sha:
            # Resume fast path: this subtask was already judged against
            # the SAME base tree — skip the semaphore and claude_p
            # entirely (DESIGN §6 "The satisfied-probe sweep needs
            # finer-than-phase granularity").
            cached_reason = _probe_drop_reason(cached)
            if cached_reason is not None:
                dropped[sid] = {
                    "reason": cached_reason,
                    "evidence": cached.get("evidence", ""),
                    "checked": list(cached.get("checked", []) or []),
                    "provides": list(s.get("provides") or []),
                }
            return
        payload = {
            "id": sid,
            "title": s.get("title", ""),
            "intent": s.get("intent", ""),
            "success_criteria_seed": s.get("success_criteria_seed", ""),
            "files_likely_touched": list(
                s.get("files_likely_touched", []) or []),
            # Other subtasks' declared surface — context for the
            # sibling-invalidation keep decision (DESIGN §8). Not read for the
            # base-tree judgment itself; only to decline a drop when a sibling
            # would break the criteria. (A pre-sweep snapshot of every other
            # subtask; which of them will themselves be dropped is not yet
            # known, and does not matter — the field only drives keeps.)
            "surviving_siblings": sibling_surface.get(sid, []),
        }
        user_prompt = (
            "SUBTASK:\n" + json.dumps(payload, indent=2) +
            "\n\nReturn only the JSON object per your schema. Judge the "
            "CURRENT working tree / HEAD only — never other branches or "
            "history. Default satisfied=false on any uncertainty. Also default "
            "satisfied=false if any entry in surviving_siblings would "
            "invalidate these criteria once its work lands (e.g. a sibling "
            "adds keys/files this subtask's test or check guards)."
        )
        async with sem:
            # bump_workers is OUTSIDE the try: its WorkerError signals
            # budget exhaustion (worker_count > max_total_workers), which
            # is the hard backstop — it must propagate so _gather_or_cancel
            # aborts the run, not be swallowed into a silent subtask-keep.
            # Only a claude_p failure is caught below as the fail-safe.
            st.bump_workers(caps)
            try:
                out = await claude_p(
                    user_prompt=user_prompt, system_prompt=sys_prompt,
                    schema_key="satisfied_probe", cwd=_judgment_cwd(st),
                    allowed_tools=TREE_READER_TOOLS, max_turns=20,
                    autonomous=False, caps=caps, st=st,
                    model=models["satisfied_probe"],
                    effort=efforts["satisfied_probe"],
                    sid=f"satisfied_probe-{sid}",
                )
            except (WorkerError, subprocess.TimeoutExpired) as e:
                # A probe crash (e.g. claude_p schema failure twice) must
                # NOT drop the subtask — fail safe toward keeping the work.
                # Log and let the subtask survive. Deliberately NOT cached:
                # no verdict was actually reached, so caching this would
                # wrongly skip re-probing a subtask that was never judged.
                log(f"  satisfied-probe {sid}: crashed "
                    f"({_brief_worker_exc(e)}); keeping "
                    "subtask (fail-safe — no drop on probe failure)")
                return
        # Persist the verdict as soon as it returns — for BOTH satisfied
        # and not-satisfied outcomes — rather than only in aggregate after
        # the whole sweep's gather completes. This is the resume gap: a
        # pause mid-sweep must not re-probe subtasks already decided. The
        # in-memory write alone is not enough — st.data only reaches disk
        # via st.save(), so without the save below a pause between this
        # probe and the sweep-final flush (~7 lines down, after
        # _gather_or_cancel) discards every since-flush verdict and resume
        # re-probes them. The single-event-loop invariant (CLAUDE.md) means
        # this data-write / save pair never interleaves with another
        # coroutine, so the per-verdict save is safe here.
        cache[sid] = {
            "satisfied": bool(out.get("satisfied") is True),
            "evidence": out.get("evidence", ""),
            "checked": list(out.get("checked", []) or []),
            # Typed not-satisfied fields (DESIGN §8 *A "not satisfied"
            # verdict carries a typed reason*) — cached so a resume
            # replays the same equivalent-coverage decision without
            # re-probing. Absent on old-shaped verdicts; None is the
            # keep direction in _probe_drop_reason.
            "unsatisfied_reason": out.get("unsatisfied_reason"),
            "equivalent_coverage_exists": out.get(
                "equivalent_coverage_exists"),
            "sibling_invalidation_risk": out.get(
                "sibling_invalidation_risk"),
            "base_sha": base_sha,
        }
        st.save()
        fresh_reason = _probe_drop_reason(out)
        if fresh_reason is not None:
            dropped[sid] = {
                "reason": fresh_reason,
                "evidence": out.get("evidence", ""),
                "checked": list(out.get("checked", []) or []),
                # Capture provides now, before the survivor-filter below drops
                # the subtask object — needed to prune the tag channel.
                "provides": list(s.get("provides") or []),
            }

    await _gather_or_cancel(*(probe_one(s) for s in probeable))
    st.save()

    if dropped and base_sha:
        await _falsify_satisfied_drops(
            st, caps, models, efforts, base_sha,
            {s.get("id", "?"): s for s in probeable}, dropped, cache)

    if not dropped:
        return None

    # Apply the drops: rewrite each plan's subtasks to survivors only.
    for plan in plans:
        plan["subtasks"] = [
            s for s in (plan.get("subtasks", []) or [])
            if s.get("id") not in dropped
        ]

    log(f"phase 3: satisfied-probe dropped {len(dropped)}/{total} "
        "subtask(s) (already satisfied, or equivalent coverage exists):")
    for sid, info in sorted(dropped.items()):
        log(f"     {sid} [{info['reason']}]: {info['evidence'][:160]}")
    _apply_subtask_drop_propagation(plans, dropped, st)

    # If every ready plan is now empty, this is the per-subtask analogue
    # of the cleared-but-empty terminal state. Build a no_work_map from
    # the drop evidence (NOT from plan confidence.basis, which is the
    # planner's original "I found work" rationale — misleading here) and
    # signal the caller to route to _finish_no_work_run. A blocked plan
    # with 0 subtasks must still fall through to _schedule()'s all-blocked
    # die, so guard on ready-only exactly like _detect_no_work.
    for plan in plans:
        if plan.get("status") != "ready":
            return None
        if plan.get("subtasks"):
            return None
    # The basis names both drop reasons when both occurred — this string
    # reaches run.json/no_work_reasons, and "already satisfied" alone
    # would misdescribe an equivalent-coverage exit to the operator.
    reasons_seen = sorted({i["reason"] for i in dropped.values()})
    basis = (
        "all subtasks already satisfied on HEAD, or their substance "
        "covered under another artifact name "
        if "equivalent_coverage" in reasons_seen else
        "all subtasks already satisfied on HEAD "
    ) + "(satisfied-probe, DESIGN §8)"
    no_work_map: dict[str, str] = {}
    for plan in plans:
        domain = plan.get("domain") or "<unknown>"
        no_work_map[domain] = basis
    return no_work_map


async def _probe_criteria_satisfied_on_head(
    subtask: dict, worktree: str, st: "State", caps: dict,
    models: dict[str, str], efforts: dict[str, str | None],
    label: str = "head", *, executed: dict | None = None,
    verdict: dict | None = None, claimed: list[dict] | None = None,
) -> dict | None:
    """Run-branch-HEAD analogue of `_filter_satisfied_subtasks`'s per-subtask
    probe, asked before a plan-time-flagged provider-subset subtask spawns
    its implementer (DESIGN §8 *Probing a flagged subtask before it spends*);
    it no longer overrides a post-execution claim, which settle-by-execution
    decides (§8 *Settled by execution*). Runs one read-only
    `satisfied_probe` against the subtask's `success_criteria_seed` on the
    *current worktree HEAD* — the run branch's integration state, which may
    now contain a sibling subtask's commit of this subtask's deliverable (or
    already have satisfied it on the seeded base). The probe judges *whether*
    the criteria are met, not *who* met them, so both cases resolve here — a
    subtask whose criteria are met on HEAD is legitimately complete regardless
    of provenance (DESIGN §8 *Scope*).

    Returns a drop record (`{reason, evidence, checked}`) if the probe judges
    the criteria already met, else None. Fails safe to None on any error or
    uncertainty: this only *rescues* a no-op whose deliverable is already
    present — it must never mask a real lazy/broken no-op, so a probe crash
    keeps the subtask on the retryable path. §12-compliant: the mechanical
    `check_branch_has_commits` gate still fires first and unchanged; the probe
    only rescues, and "are the criteria semantically met on this tree?" is the
    judgment §12's complementary half assigns to a worker.

    Unlike the pre-_schedule probe (base tree at plan time), this probes HEAD —
    but still HEAD-only, never history-spanning git, via the same
    `SATISFIED_PROBE_TOOLS` scope. HEAD here is the same ref the mechanical
    commit-presence gate measures against, so the probe cannot false-positive
    on code present only on an unrelated branch.

    `executed`, a `pass` record of `_settle_by_execution`, tells the probe
    which criteria leerie's own execution decided, so it judges substance
    and never re-runs them in its read-only tree (DESIGN §8 *A no-op a
    sibling already delivered is settled on evidence*). `verdict`, when
    given, receives the probe's raw output for the caller to type.
    `claimed`, the implementer's per-criterion evidence for a no-op claim
    (`_no_op_claim_evidence`), is shown as a claim to check, never as a
    finding (DESIGN §8 *A no-op the base already carries*)."""
    sid = subtask.get("id", "?")
    seed = (subtask.get("success_criteria_seed") or "").strip()
    if not seed:
        # No criterion to judge "already met" against — nothing to rescue.
        return None
    payload = {
        "id": sid,
        "title": subtask.get("title", ""),
        "intent": subtask.get("intent", ""),
        "success_criteria_seed": seed,
        "files_likely_touched": list(
            subtask.get("files_likely_touched", []) or []),
    }
    # The subtask's own per-criterion list, when the planner typed one:
    # each must be met too, not only the seed's summary of them. Each has an
    # id the verdict names it by (the seed's is `seed`).
    criteria = [{"id": cid, "criterion": v["criterion"]}
                for cid, v in _probe_criteria(subtask)]
    if criteria:
        payload["criteria"] = criteria
    decided = _criteria_decided_by_execution(subtask, executed)
    if decided:
        payload["decided_by_execution"] = decided
    if claimed:
        payload["implementer_claim"] = claimed
    user_prompt = (
        "SUBTASK:\n" + json.dumps(payload, indent=2) +
        "\n\nReturn only the JSON object per your schema. Judge the "
        "CURRENT working tree / HEAD only — never other branches or "
        "history. Default satisfied=false on any uncertainty."
        + (" `satisfied` means the seed AND every entry of `criteria` are "
           "met." if criteria else "")
        + (" Each entry of `decided_by_execution` is a criterion whose "
           "command the orchestrator itself just ran on this HEAD, exiting "
           "0: that command passes. Do not run it again — your tree is "
           "read-only, and a test that writes fails there for that reason "
           "alone. Judge only what a passing command cannot show: that the "
           "substance the criterion describes is on this tree. On "
           "`cannot_verify`, list in `unverifiable` the id of every "
           "criterion (`seed` included) you could not check by reading "
           "this tree, and in `covered_by_execution` the id of every "
           "criterion (`seed` included) that one passing command exercises "
           "in full: every file, case and behaviour the criterion names, "
           "not only some of them."
           if decided else "")
        + (" `implementer_claim` is the implementer's own account of why "
           "nothing needs changing: per criterion, what it says it saw and "
           "the files and lines it says it read. It is a claim to check, "
           "not evidence: read every location it cites, judge each "
           "criterion yourself, and look past the cited lines for what the "
           "criterion asks that they do not show. For every gap you find, "
           "add an entry to `gaps` naming the criterion id, the file and "
           "lines, and what is missing."
           if claimed else "")
    )
    # bump_workers OUTSIDE the try, same as _filter_satisfied_subtasks: a
    # budget-exhaustion WorkerError must propagate to abort the run, not be
    # swallowed into a silent no-rescue.
    st.bump_workers(caps)
    try:
        out = await claude_p(
            user_prompt=user_prompt,
            system_prompt=_load_prompt("satisfied_probe"),
            schema_key="satisfied_probe", cwd=worktree,
            # 40, not the pre-schedule probe's 20 — justified by
            # consequence, not workload shape: both sites judge the same
            # single criterion, and either can exhaust its cap when the
            # criterion is met or audit-shaped on the judged tree
            # (confirming costs a verify-every-part pass). A cap-out HERE
            # had no recovery below the run level: every HEAD-probe
            # attempt for a genuine no-op (an audit-shaped subtask whose
            # implementer correctly committed nothing) — two pre-spawn
            # and four rescue attempts — died at error_max_turns
            # turns=21, the fail-safe declined to rescue, and the retry
            # cap turned a correct no-op into "wave has unresolved
            # subtasks". A pre-schedule cap-out, by contrast, is retried
            # and at worst fail-safe-keeps the subtask, whose no-op then
            # lands back on this larger-capped site (DESIGN §8 *The
            # judge's turn budget scales with the item count*).
            allowed_tools=TREE_READER_TOOLS, max_turns=40,
            autonomous=False, caps=caps, st=st,
            model=models["satisfied_probe"],
            effort=efforts["satisfied_probe"],
            # `label` distinguishes the two call sites' worker logs. Both can
            # fire for one subtask in a single run — the pre-spawn probe
            # declines, the implementer commits nothing, the post-execution
            # rescue probes again — and a shared name would leave the second
            # overwriting the first's log, losing the reason for the decline.
            sid=f"satisfied_probe-{label}-{sid}",
        )
    except (WorkerError, subprocess.TimeoutExpired) as e:
        # A probe crash must NOT rescue the subtask — fail safe toward the
        # existing retryable no-op path.
        log(f"  satisfied-probe (HEAD) {sid}: crashed "
            f"({_brief_worker_exc(e)}); not rescuing "
            "(fail-safe — no-op stays retryable)")
        return None
    if verdict is not None and isinstance(out, dict):
        verdict.update(out)
    if out.get("satisfied") is True:
        return {
            "reason": "already_satisfied_mid_run",
            "evidence": out.get("evidence", ""),
            "checked": list(out.get("checked", []) or []),
        }
    return None


# --- per-repo dependency provisioning ----------------------------------------
# See DESIGN.md §6½ "Per-repo dependency provisioning" and IMPLEMENTATION.md
# §6½ for the layered design (.leerie-setup.sh → mise install → table → LLM
# fallback → worktree replay).

# argv[0] allowlist for any provision command — both table-emitted commands
# and the LLM-fallback recipe. Validated by _validate_provision_recipe().
# Anything outside this set is rejected; the §12 carve-out (the LLM
# fallback worker) is mechanically contained by this list.
_PROVISION_ARGV0_ALLOW = frozenset({
    "pnpm", "npm", "yarn", "pip", "pip3", "uv", "poetry", "pipenv",
    "go", "cargo", "bundle", "gem", "mvn", "gradle", "gradlew", "make",
    "composer", "dotnet",
})

# Shell metacharacters that must not appear anywhere in a command argv.
# A command emitted as a true argv list cannot legitimately need any of
# these — the executor invokes it directly with no shell, and any
# metacharacter is a sign the recipe was malformed or smuggling shell
# semantics through the validator.
_PROVISION_SHELL_METACHARS = frozenset(set("|&;$`><\n\r"))


_NODE_LOCKFILES = ("pnpm-lock.yaml", "yarn.lock", "package-lock.json")
_NODE_LOCKFILE_INSTALL = {
    "pnpm-lock.yaml": ["pnpm", "install", "--frozen-lockfile"],
    "yarn.lock": ["yarn", "install", "--frozen-lockfile"],
    "package-lock.json": ["npm", "ci"],
}
# A repo with more nested roots than this is not a shape the table should
# guess at; the extra roots are left to the worker's own install.
_NESTED_NODE_ROOTS_MAX = 16


def _git_z_output(argv: list[str], *, timeout: float | None = None,
                  env: Mapping[str, str] | None = None
                  ) -> subprocess.CompletedProcess:
    """`argv` (a git command with `-z` path output) run in bytes, `stdout`
    decoded as the filesystem does (`os.fsdecode`, surrogateescape) so a
    non-UTF-8 file name neither raises nor stops naming its file; `text=True`
    decoded strictly and raised `UnicodeDecodeError` (review r2 L2). `env`
    None inherits the orchestrator's environment (`_git_view`'s, for a read
    through the run's settings)."""
    r = subprocess.run(argv, capture_output=True, check=False,
                       timeout=timeout,
                       env=None if env is None else dict(env))
    err = r.stderr or b""
    return subprocess.CompletedProcess(
        r.args, r.returncode, os.fsdecode(r.stdout or b""),
        err.decode(errors="replace") if isinstance(err, bytes) else err)


def _node_lockfile_paths(repo_root: Path) -> list[str]:
    """Repo-relative POSIX paths of every Node lockfile below the root:
    the tracked ones when `repo_root` is a git work tree (an untracked
    lockfile is not part of the project), else a walk that skips
    `node_modules` and dot-directories."""
    try:
        r = _git_z_output(
            ["git", *_tree_git_args(repo_root), "ls-files", "-z", "--",
             *[f":(glob)**/{lf}" for lf in _NODE_LOCKFILES]], timeout=30)
        if r.returncode == 0:
            return sorted(p for p in r.stdout.split("\0") if p)
    except (OSError, subprocess.TimeoutExpired):
        pass
    out: list[str] = []
    for dirpath, dirnames, filenames in os.walk(repo_root):
        dirnames[:] = sorted(d for d in dirnames
                             if d != "node_modules" and not d.startswith("."))
        for lf in _NODE_LOCKFILES:
            if lf in filenames:
                out.append(Path(dirpath, lf).relative_to(repo_root).as_posix())
    return sorted(out)


def _workspace_globs(repo_root: Path) -> list[str]:
    """The root's workspace member globs: `packages:` in pnpm-workspace.yaml
    and `workspaces` in package.json (a list, or npm/yarn's
    `{"packages": [...]}`). Both are mechanical config files; a `!` glob is
    an exclusion and is kept with its `!`."""
    globs: list[str] = []
    ws = repo_root / "pnpm-workspace.yaml"
    if _regular_file_beneath(repo_root, ws):
        try:
            in_packages = False
            for line in _read_text_beneath(repo_root, ws,
                                           errors="strict", limit=READ_LIMIT_CONFIG).splitlines():
                bare = line.split("#", 1)[0].rstrip()
                if not bare.strip():
                    continue
                if not bare[0].isspace():
                    in_packages = bare.strip() == "packages:"
                    continue
                item = bare.strip()
                if in_packages and item.startswith("-"):
                    g = item[1:].strip().strip("'\"")
                    if g:
                        globs.append(g)
        except (OSError, UnicodeDecodeError):
            pass
    try:
        pkg = json.loads(_read_text_beneath(
            repo_root, repo_root / "package.json", errors="strict", limit=READ_LIMIT_CONFIG))
        w = pkg.get("workspaces") if isinstance(pkg, dict) else None
        if isinstance(w, dict):
            w = w.get("packages")
        if isinstance(w, list):
            globs += [g for g in w if isinstance(g, str) and g]
    except (OSError, ValueError, UnicodeDecodeError):
        pass
    return globs


def _workspace_glob_matches(path: str, glob: str) -> bool:
    """A workspace glob against a repo-relative directory: `*` stays within
    one path segment, `**` spans segments."""
    g = glob.strip().rstrip("/")
    while g.startswith("./"):
        g = g[2:]
    rx = ""
    i = 0
    while i < len(g):
        if g.startswith("**", i):
            rx += ".*"
            i += 2
            if g.startswith("/", i):
                rx += "/?"
                i += 1
        elif g[i] == "*":
            rx += "[^/]*"
            i += 1
        elif g[i] == "?":
            rx += "[^/]"
            i += 1
        else:
            rx += re.escape(g[i])
            i += 1
    return re.fullmatch(rx, path) is not None


def _nested_node_roots(repo_root: Path) -> list[tuple[str, str]]:
    """(directory, lockfile) for every Node project root below the repo root
    that is not a member of the root's workspace: a directory holding its
    own lockfile (DESIGN §6½ *One install per independent package root*).
    pnpm > yarn > npm within one directory, as at the root."""
    by_dir: dict[str, list[str]] = {}
    for rel in _node_lockfile_paths(repo_root):
        d, _, name = rel.rpartition("/")
        if not d or "node_modules" in d.split("/"):
            continue
        by_dir.setdefault(d, []).append(name)
    globs = _workspace_globs(repo_root)
    include = [g for g in globs if not g.startswith("!")]
    exclude = [g[1:] for g in globs if g.startswith("!")]
    out: list[tuple[str, str]] = []
    for d in sorted(by_dir):
        if (any(_workspace_glob_matches(d, g) for g in include)
                and not any(_workspace_glob_matches(d, g) for g in exclude)):
            continue
        lf = next(f for f in _NODE_LOCKFILES if f in by_dir[d])
        out.append((d, lf))
    return out[:_NESTED_NODE_ROOTS_MAX]


def _lockfile_table_entries(repo_root: Path) -> list[dict]:
    """The deterministic lockfile → install-command table. Returns a list of
    recipe entries (possibly empty) — polyglot repos like Rails-with-frontend
    emit ALL matching commands, not first-match-wins. See IMPLEMENTATION.md
    §6½ for the full table.

    Each entry is the minimal recipe shape: {kind, command, working_dir,
    timeout_s}. Callers compose them into a full recipe and persist to
    st.data["provision"]["recipe"].
    """
    entries: list[dict] = []

    # --- Node.js: pnpm > yarn > npm precedence ---
    # The precedence is documented at the pnpm and yarn sites: a repo that
    # commits multiple lockfiles is rare, but when it happens the most-
    # specific one wins. pnpm-lock.yaml means the team has chosen pnpm even
    # if package-lock.json was left behind from a prior tool.
    has_pnpm = (repo_root / "pnpm-lock.yaml").is_file()
    has_yarn = (repo_root / "yarn.lock").is_file()
    has_npm = (repo_root / "package-lock.json").is_file()
    if has_pnpm:
        entries.append({
            "kind": "install",
            "command": ["pnpm", "install", "--frozen-lockfile"],
            "working_dir": ".",
            "timeout_s": 1800,
        })
    elif has_yarn:
        entries.append({
            "kind": "install",
            "command": ["yarn", "install", "--frozen-lockfile"],
            "working_dir": ".",
            "timeout_s": 1800,
        })
    elif has_npm:
        entries.append({
            "kind": "install",
            "command": ["npm", "ci"],
            "working_dir": ".",
            "timeout_s": 1800,
        })
    # One entry per independent Node root below the top (a `worker/` or
    # `infra/` with its own lockfile, outside the root's workspace). A root
    # install never reaches them, and the provision judge rejected the
    # one-entry recipe as missing their dependencies: 7 run deaths across 5
    # chains (`_nested_node_roots`).
    for d, lf in _nested_node_roots(repo_root):
        entries.append({
            "kind": "install",
            "command": list(_NODE_LOCKFILE_INSTALL[lf]),
            "working_dir": d,
            "timeout_s": 1800,
        })

    # --- Python: uv > poetry > pipenv. Bare requirements.txt and bare
    # pyproject.toml (without a lockfile) deliberately do NOT match — they
    # are the ambiguous tail that goes to the LLM fallback (verified
    # against Django, which uses `pip install -e .`).
    if (repo_root / "uv.lock").is_file():
        entries.append({
            "kind": "install",
            "command": ["uv", "sync"],
            "working_dir": ".",
            "timeout_s": 1800,
        })
    elif (repo_root / "poetry.lock").is_file():
        entries.append({
            "kind": "install",
            "command": ["poetry", "install"],
            "working_dir": ".",
            "timeout_s": 1800,
        })
    elif (repo_root / "Pipfile.lock").is_file():
        entries.append({
            "kind": "install",
            "command": ["pipenv", "install"],
            "working_dir": ".",
            "timeout_s": 1800,
        })

    # --- Go ---
    if (repo_root / "go.mod").is_file() and (repo_root / "go.sum").is_file():
        entries.append({
            "kind": "install",
            "command": ["go", "mod", "download"],
            "working_dir": ".",
            "timeout_s": 1800,
        })

    # --- Rust ---
    if (repo_root / "Cargo.lock").is_file():
        entries.append({
            "kind": "install",
            "command": ["cargo", "fetch"],
            "working_dir": ".",
            "timeout_s": 1800,
        })

    # --- Ruby ---
    if (repo_root / "Gemfile.lock").is_file():
        entries.append({
            "kind": "install",
            "command": ["bundle", "install"],
            "working_dir": ".",
            "timeout_s": 1800,
        })

    # --- PHP ---
    if (repo_root / "composer.lock").is_file():
        entries.append({
            "kind": "install",
            "command": ["composer", "install", "--no-interaction"],
            "working_dir": ".",
            "timeout_s": 1800,
        })

    # --- C# / .NET ---
    if (repo_root / "packages.lock.json").is_file():
        entries.append({
            "kind": "install",
            "command": ["dotnet", "restore"],
            "working_dir": ".",
            "timeout_s": 1800,
        })

    return entries


def _detect_recipe_from_lockfiles(repo_root: Path) -> list[dict]:
    """Public entry point for the deterministic detection layer. Returns
    a list of recipe entries (possibly empty). An empty list means the
    table abstained and the caller should fall back to the LLM worker.
    """
    return _lockfile_table_entries(repo_root)


def _normalize_pip_installs(recipe: list[dict]) -> list[dict]:
    """Add `--break-system-packages` to every `pip`/`pip3`/`python -m pip`
    *install* command that lacks it. Returns a new recipe list (entries
    are shallow-copied only when rewritten).

    Why this is code, not a prompt rule: the container's system Python is
    Debian-13 externally-managed (PEP 668) — a bare `pip install` exits
    non-zero with "externally-managed-environment" (the same failure the
    Dockerfile already works around at its own `pip3 install
    --break-system-packages`). The LLM provision worker generates recipes
    by mirroring the repo's CI, which runs in a venv/runner and needs no
    such flag, so it never emits one. That gap silently breaks every
    recipe consumer — most visibly `_capture_conformance_baseline`, whose
    `pip install` then fails and leaves the base-tree test axis recording
    `command not found` instead of a real pass/fail. Normalizing here, at
    the single point every consumer reads the recipe as data, fixes all
    of them at once (§12: prompts advisory, code enforces).

    The flag is safe unconditionally: on a non-externally-managed
    interpreter (e.g. a mise-managed Python) it is a harmless no-op; on
    the apt system Python it is required.
    """
    out: list[dict] = []
    for entry in recipe:
        cmd = entry.get("command") or []
        if _is_pip_install(cmd) and "--break-system-packages" not in cmd:
            i = cmd.index("install")
            new_cmd = cmd[:i + 1] + ["--break-system-packages"] + cmd[i + 1:]
            out.append({**entry, "command": new_cmd})
        else:
            out.append(entry)
    return out


# N22: Next.js/Turbopack's Rust/Tokio build tooling sizes its thread pool to
# the host's full core count — nothing in the worker cgroup constrains
# *detected* parallelism (only pids.max bounds how many of those threads/forks
# the cgroup will actually admit). A build that spawns one worker thread per
# host core can exhaust the per-worker `pids.max` cap (measured spiking to
# 972/2048), and the resulting EAGAIN surfaces as a `build-failed` defect of
# the diff rather than what it actually is: a resource-limit collision.
# UV_THREADPOOL_SIZE caps libuv's pool (Node's fs/crypto/zlib workers, which
# Next's build pipeline uses); RAYON_NUM_THREADS caps the rayon-based
# parallelism SWC (Next's Rust compiler, which underlies Turbopack) uses for
# its transform passes. Both are inert (fall back to their own default) when
# a given command doesn't use that runtime, so setting both unconditionally
# on every Node install/build command is safe.
_NODE_THREADPOOL_CAP_ENV: dict[str, str] = {
    "UV_THREADPOOL_SIZE": "4",
    "RAYON_NUM_THREADS": "4",
}

_NODE_PACKAGE_MANAGERS = frozenset({"pnpm", "npm", "yarn"})


def _normalize_node_threadpool(recipe: list[dict]) -> list[dict]:
    """Inject `_NODE_THREADPOOL_CAP_ENV` into every Node/pnpm/npm/yarn
    install-or-build entry's `env` dict, unless the entry already sets that
    var (an entry-supplied value wins — this only fills gaps). Returns a new
    recipe list (entries are shallow-copied only when rewritten).

    Why this is code, not a prompt rule: nothing in the worker cgroup caps
    a build tool's *detected* core count (§12: prompts advisory, code
    enforces) — a Rust/Tokio or libuv thread pool sized to `nproc` will size
    itself the same way whether or not a prompt asks it not to. Normalizing
    here, at the single point every consumer reads the recipe as data, means
    every execution path (the base-tree baseline's direct `_run_streaming`
    call, and the advisory PROVISION_RECIPE text handed to implementer/
    conformer workers) gets the cap.
    """
    out: list[dict] = []
    for entry in recipe:
        cmd = entry.get("command") or []
        if (entry.get("kind") in ("install", "build")
                and cmd and cmd[0] in _NODE_PACKAGE_MANAGERS):
            env = dict(entry.get("env") or {})
            changed = False
            for k, v in _NODE_THREADPOOL_CAP_ENV.items():
                if k not in env:
                    env[k] = v
                    changed = True
            out.append({**entry, "env": env} if changed else entry)
        else:
            out.append(entry)
    return out


def _is_pip_install(cmd: list[str]) -> bool:
    """True iff `cmd` (an argv list) is a pip *install* invocation — bare
    `pip`/`pip3 …` or `python[3] -m pip …` — where the pip subcommand is
    `install`. The subcommand is the first token after the pip prefix that
    is not a global option (`pip -v install …` → install), so a leading
    global flag doesn't hide it. A non-install subcommand (`pip list`)
    returns False."""
    if not cmd:
        return False
    if cmd[0] in ("pip", "pip3"):
        rest = cmd[1:]
    elif cmd[0] in ("python", "python3") and cmd[1:3] == ["-m", "pip"]:
        rest = cmd[3:]
    else:
        return False
    for tok in rest:
        if tok.startswith("-"):
            continue  # global option before the subcommand
        return tok == "install"  # first non-option token is the subcommand
    return False


def _validate_provision_recipe(recipe: list[dict]) -> None:
    """Mechanically bound the provision recipe. Raises ValueError on any
    violation. Called for BOTH the table-emitted recipe and the LLM-
    fallback recipe — the §12 carve-out for the LLM worker is contained
    here, not in the prompt.

    Invariants enforced:
      - command is a non-empty argv list (no shell strings).
      - command[0] is in _PROVISION_ARGV0_ALLOW (or the entry is kind: none).
      - No shell metacharacters anywhere in the argv (no piping, no
        redirection, no command substitution).
      - No `sudo` anywhere.
      - working_dir is "." or a relative path with no ".." segments and
        no leading "/" (worker cannot reach outside the repo).
      - kind is one of {install, build, none}.
    """
    if not isinstance(recipe, list):
        raise ValueError(f"recipe must be a list, got {type(recipe).__name__}")
    for i, entry in enumerate(recipe):
        if not isinstance(entry, dict):
            raise ValueError(f"recipe[{i}] is not a dict: {entry!r}")
        kind = entry.get("kind")
        if kind not in ("install", "build", "none"):
            raise ValueError(
                f"recipe[{i}].kind={kind!r} must be one of install|build|none")
        if kind == "none":
            # `none` entries are bypass markers; no command required.
            continue
        cmd = entry.get("command")
        if not isinstance(cmd, list) or not cmd:
            raise ValueError(
                f"recipe[{i}].command must be a non-empty argv list")
        if any(not isinstance(a, str) for a in cmd):
            raise ValueError(
                f"recipe[{i}].command must be a list of strings")
        if cmd[0] not in _PROVISION_ARGV0_ALLOW:
            raise ValueError(
                f"recipe[{i}].command[0]={cmd[0]!r} is not in the allowed "
                f"package-manager set {sorted(_PROVISION_ARGV0_ALLOW)}")
        for j, arg in enumerate(cmd):
            if arg == "sudo":
                raise ValueError(
                    f"recipe[{i}].command contains 'sudo' at position {j}")
            bad = _PROVISION_SHELL_METACHARS & set(arg)
            if bad:
                raise ValueError(
                    f"recipe[{i}].command[{j}]={arg!r} contains shell "
                    f"metacharacters {sorted(bad)}")
        wd = entry.get("working_dir")
        if not isinstance(wd, str) or not wd:
            raise ValueError(
                f"recipe[{i}].working_dir must be a non-empty string")
        if wd.startswith("/"):
            raise ValueError(
                f"recipe[{i}].working_dir={wd!r} must be relative, not absolute")
        # ".." anywhere in the path — split on both `/` and `\` so a
        # Windows-style smuggling attempt is also caught.
        parts = wd.replace("\\", "/").split("/")
        if ".." in parts:
            raise ValueError(
                f"recipe[{i}].working_dir={wd!r} contains '..' "
                "(must not traverse outside the repo)")


# Section-header regex for the README extractor. Matches install/setup-
# adjacent words. Verified against 15 real OSS READMEs (DESIGN §6½ + the
# verification corpus in tests/test_readme_extractor.py): catches 13/15.
# The two known misses (Supabase, esbuild) are marketing-style READMEs
# that delegate install to external docs — those repos route through
# .leerie-setup.sh.

# Byte budget for the dep_capture command extraction. Extracted Bash
# commands from logs/*.log (deduped, newest-first) are admitted until this
# ceiling; any truncation is noted in the worker prompt. Sized to admit
# the full command set for essentially every run (~50–80k tokens undeduped,
# ~66k worst-case) while bounding the LLM input. Mirrors the
# _FIXTURE_TOTAL_BUDGET idiom in _gather_provision_fixtures.
#
# This is an LLM-context token budget, not an argv-size constraint: the
# dep_capture worker's user_prompt (this text plus _gather_dep_manifests'
# output) travels to `claude -p` over stdin, not argv (see claude_p's
# `build()` and IMPLEMENTATION.md §3 "User prompt transport — stdin, not
# argv"), so combining this with _DEPCAP_MANIFEST_TOTAL_BUDGET never risks
# Linux's per-argument MAX_ARG_STRLEN (131,071 bytes) the way an
# argv-passed payload would.
_DEPCAP_TOTAL_BUDGET = 307200  # 300KB ≈ 75k tokens at 4 bytes/token

# Manifests-first dep_capture (DESIGN §6½). The worker's PRIMARY corpus is the
# repo's dependency-manifest files; the install-filtered command list is only a
# SECONDARY hint for system/native (apt) deps that appear in no manifest. This
# replaced an earlier design that fed the worker the *complete* command corpus —
# overwhelmingly noise (git/grep/pytest/`python3 -c`), which let the model
# degenerate into emitting prose as package names.

# Dependency manifests to gather, primary corpus. Bounded per file and in total
# so a giant lockfile can't blow the budget. Order is display order.
_DEP_MANIFEST_NAMES = (
    "requirements.txt", "requirements-dev.txt", "requirements-test.txt",
    "pyproject.toml", "Pipfile", "Pipfile.lock", "setup.py", "setup.cfg",
    "package.json", "pnpm-lock.yaml", "package-lock.json", "yarn.lock",
    "go.mod", "Cargo.toml", "Cargo.lock", "Gemfile", "Gemfile.lock",
    "composer.json", "composer.lock",
)
_DEPCAP_MANIFEST_FILE_BUDGET = 16384    # 16 KB per manifest file
_DEPCAP_MANIFEST_TOTAL_BUDGET = 131072  # 128 KB across all manifests

# Install-verb matcher for the SECONDARY command hint. A command is kept only
# when it invokes a package-manager install verb at a command boundary (start of
# string, or after ; & | ( or `sudo`). Commands whose leading word is a
# text-scanning tool (grep/git/…) are dropped even if the verb appears inside a
# quoted pattern — that is how prose ("grep 'apt-get install intents'") leaked in.
_DEPCAP_INSTALL_RE = re.compile(
    r"(?:^|[\s;&|(])(?:sudo\s+)?(?:"
    r"apt-get\s+install|apt\s+install|yum\s+install|dnf\s+install|apk\s+add|"
    r"pip3?\s+install|pipx\s+install|poetry\s+add|uv\s+(?:add|pip\s+install)|"
    r"npm\s+(?:install|i|ci|add)|pnpm\s+(?:add|install|i)|yarn\s+(?:add|install)|"
    r"cargo\s+(?:install|add)|go\s+(?:install|get)|"
    r"gem\s+install|bundle\s+(?:add|install)|composer\s+require|dotnet\s+add"
    r")(?:\s|$)"
)
# Leading command words that scan text: their args routinely contain install
# verbs inside quoted patterns, so drop them from the hint corpus.
_DEPCAP_TEXT_TOOLS = frozenset(
    {"grep", "rg", "git", "sed", "awk", "echo", "cat", "printf", "ag", "ack"}
)
# Shell separators between commands. A single logged Bash call is often several
# commands (newlines from a `python3 -c` heredoc, `&&`/`|` chains). Splitting on
# these lets the text-tool gate apply per-command, so `echo hi\npip install x`
# keeps the install segment instead of being dropped by the leading `echo`.
_DEPCAP_SEGMENT_RE = re.compile(r"[\n;]|&&|\|\||[|&]")


def _is_install_command(cmd: str) -> bool:
    """True if `cmd` invokes a package-manager install verb (SECONDARY hint).

    Evaluates each shell segment independently: keep the command if ANY segment
    whose leading word is NOT a text-scanning tool (grep/git/…) matches an
    install verb. Per-segment evaluation matters because a single logged Bash
    call may chain commands (`echo hi; pip install x`) — the whole-string first
    word would otherwise let a leading `echo`/`grep` drop a genuine install on a
    later segment. The text-tool gate still suppresses the leak that motivated it
    (`grep "apt-get install …"`), because there the verb lives *inside* the text
    tool's own segment."""
    for seg in _DEPCAP_SEGMENT_RE.split(cmd):
        words = seg.split()
        if not words:
            continue
        first = words[0]
        # Strip a leading sudo so `sudo grep …` is still treated as a grep.
        if first == "sudo":
            first = words[1] if len(words) > 1 else ""
        if first in _DEPCAP_TEXT_TOOLS:
            continue
        if _DEPCAP_INSTALL_RE.search(seg):
            return True
    return False


def _gather_dep_manifests(repo_root: Path) -> str:
    """Read the repo's dependency-manifest files (PRIMARY dep_capture corpus).

    Returns a labeled text block (one section per manifest found), bounded per
    file and in total. Absent manifests are skipped. This is deterministic
    corpus selection (DESIGN §6½ / §12): the model decides content, code decides
    what it is shown."""
    blocks: list[str] = []
    total = 0
    for name in _DEP_MANIFEST_NAMES:
        p = repo_root / name
        try:
            text = _read_text_beneath(repo_root, p, limit=READ_LIMIT_CONFIG)
        except OSError:
            continue
        if len(text.encode()) > _DEPCAP_MANIFEST_FILE_BUDGET:
            text = text.encode()[:_DEPCAP_MANIFEST_FILE_BUDGET].decode(
                errors="ignore") + "\n… (truncated)"
        block = f"### {name}\n```\n{text}\n```"
        encoded = len(block.encode())
        if total + encoded > _DEPCAP_MANIFEST_TOTAL_BUDGET:
            break
        blocks.append(block)
        total += encoded
    return "\n\n".join(blocks)


def _normalize_setup_packages(pkgs: list[str]) -> str:
    """Render a package list in the canonical persisted form: order-preserving
    dedup, space-joined. Shared by _merge_setup_packages (union) and the
    replace path so both emit byte-identical TOML values."""
    return " ".join(dict.fromkeys(p for p in pkgs if p))


def _split_setup_packages(value: str) -> list[str]:
    """The items of a `setup_packages` value (comma- or space-separated)."""
    return [p for p in re.split(r"[,\s]+", value.strip()) if p]


def _merge_setup_packages(existing: str, captured: list[str]) -> str | None:
    """Union existing setup_packages with newly-captured packages.

    Returns the merged string only when the set grew (new packages
    discovered); returns None when captured is a subset of existing.
    Preserves user-narrowed lists — never removes packages.
    """
    existing_list = _split_setup_packages(existing) if existing else []
    existing_set = dict.fromkeys(existing_list)  # preserves first-seen order
    new_pkgs = [p for p in captured if p not in existing_set]
    if not new_pkgs:
        return None
    merged = list(existing_set) + new_pkgs
    # Deduplicate while preserving order (existing_set already dedups existing).
    return _normalize_setup_packages(merged)


def _dump_language_installs(entries: list[dict]) -> str:
    """JSON-encode `language_installs` for TOML persistence, single-quote-safe.

    The value is stored as a JSON string inside `.leerie/config.toml`.
    `_toml_value` wraps a `"`-containing value in a TOML *literal* (`'...'`)
    string, which cannot itself contain a `'`. A captured install command may
    carry single quotes (e.g. `pip install 'requests[security]'`,
    `gem install -v '~> 7.0'`), which would otherwise break the literal wrapper
    and yield invalid TOML. Escaping them as the JSON escape `\\u0027` keeps the
    value free of literal `'` while `json.loads` (both readers) recovers the
    original quote — so the round-trip is lossless and the file is valid TOML."""
    return json.dumps(entries, separators=(",", ":")).replace("'", "\\u0027")


def _toml_value(val: str) -> str:
    """Render `val` as a TOML string literal.

    A value containing `"` — notably the JSON-encoded `language_installs`
    (`[{"manager":"pip",...}]`) — would terminate a basic (`"..."`) string
    early and produce invalid TOML. TOML *literal* strings (`'...'`) process no
    escapes, so wrap such values in single quotes. This requires the value to
    contain no literal `'` — guaranteed for `language_installs` by
    `_dump_language_installs` (which escapes `'`→`\\u0027`) and trivially true
    for `setup_packages` (apt names have no quotes). Both readers (`_read_toml_key`
    and the launcher's flat-TOML regex) already `.strip("'")`, so this
    round-trips cleanly with no unescaping. Plain values keep the `"..."` form."""
    if '"' in val and "'" not in val:
        return f"'{val}'"
    return f'"{val}"'


def _write_config_toml_keys(cfg_path: Path, updates: dict[str, str]) -> None:
    """Minimal deterministic TOML upsert for a set of key-value pairs.

    Creates cfg_path with a standard header if absent. For each key in
    updates: replaces the first uncommented `key = ...` line if present,
    otherwise appends. Never touches commented lines. Written as a new
    file renamed into place (mirrors State.save discipline).

    The file is the checkout's (`<root>/.leerie/config.toml`), whose content
    a merged run may have committed: it is read and written beneath the
    checkout without following a link (`_read_beneath`, `_write_beneath`) —
    a link there is replaced, never read or written through, and a link at
    `.leerie` refuses the write (DESIGN §6 *Leerie never reads through a
    link a repository holds*).
    """
    cfg_path = Path(cfg_path)
    root = cfg_path.parent.parent if cfg_path.parent.name == ".leerie" \
        else cfg_path.parent
    try:
        lines = _read_text_beneath(root, cfg_path, limit=READ_LIMIT_CONFIG).splitlines(keepends=True)
    except OSError as e:
        # Absent, or a link at the file itself, which the write below
        # replaces; a link on the way (ENOTDIR, or ELOOP at `.leerie`)
        # refuses the write there.
        if not (isinstance(e, FileNotFoundError) or (
                e.errno == errno.ELOOP
                and not _link_on_the_way(root, cfg_path))):
            raise
        lines = [
            "# leerie per-repo configuration — commit this file to version-control.\n",
            "# Generated by: leerie capture\n",
            "# See: https://leerie.enric.ai/docs/config\n",
        ]
    remaining = dict(updates)
    out: list[str] = []
    for line in lines:
        stripped = line.strip()
        if stripped.startswith("#"):
            out.append(line)
            continue
        matched_key = None
        for k in list(remaining):
            if re.match(rf"^\s*{re.escape(k)}\s*=", line):
                matched_key = k
                break
        if matched_key is not None:
            val = remaining.pop(matched_key)
            out.append(f'{matched_key} = {_toml_value(val)}\n')
        else:
            out.append(line)
    # Append any keys that were not found in the file.
    for k, v in remaining.items():
        out.append(f'{k} = {_toml_value(v)}\n')
    _write_beneath(root, cfg_path, "".join(out).encode())


def _extract_depcap_commands(log_dir: Path) -> tuple[str, bool]:
    """Install-shaped Bash commands from worker logs (SECONDARY dep_capture hint).

    Dedup, newest-first, bounded to _DEPCAP_TOTAL_BUDGET bytes. Only commands that
    invoke a package-manager install verb are kept (`_is_install_command`); the
    other ~96% (git/grep/pytest/`python3 -c`) is noise that let the worker
    degenerate into echoing prose as packages. This is the SECONDARY hint —
    manifests (`_gather_dep_manifests`) are the primary corpus (DESIGN §6½)."""
    seen: dict[str, None] = {}  # ordered set, dedup
    # Registered transcripts only, never a command's output (DESIGN §8 *What
    # a worker ran is read from its own transcript*): an install line the
    # code under measurement prints would otherwise become a package.
    for _sid, log_path in _worker_transcripts(log_dir):
        for kind, inp, _result in _iter_log_tool_use(log_path):
            if kind != "Bash":
                continue
            cmd = inp.get("command", "")
            if cmd and _is_install_command(cmd):
                seen[cmd] = None
    total_bytes = 0
    hit_ceiling = False
    lines: list[str] = []
    for cmd in seen:
        encoded = (cmd + "\n---\n").encode()
        if total_bytes + len(encoded) > _DEPCAP_TOTAL_BUDGET:
            hit_ceiling = True
            break
        lines.append(cmd)
        total_bytes += len(encoded)
    return "\n---\n".join(lines), hit_ceiling


def resolve_capture_deps(repo_root: Path) -> bool:
    """Resolve the capture_deps preference (DESIGN §6½).

    Order: LEERIE_CAPTURE_DEPS env → capture_deps in .leerie/config.toml → True.
    Default is True (capture enabled); set to 0/false to opt out.
    """
    env = os.environ.get(CAPTURE_DEPS_ENV, "").strip()
    if env:
        try:
            parsed = _parse_bool_envtoml(env)
        except ValueError:
            parsed = None
        if parsed is not None:
            return parsed
    cfg = repo_root / CAPTURE_DEPS_CONFIG
    val = _read_toml_key(cfg, "capture_deps")
    if val is not None:
        try:
            parsed = _parse_bool_envtoml(val)
        except ValueError:
            parsed = None
        if parsed is not None:
            return parsed
    return True  # default: enabled


# Node subcommands that install from an existing lockfile. `add`/`remove`/
# `up`/`dlx` are deliberately absent: they change what is installed, so they
# are never the per-worktree relink residual however they are flagged.
_NODE_INSTALL_SUBCOMMANDS = frozenset({"install", "i", "ci"})


def _filter_residual_deps(language_installs: list[dict]) -> list[dict]:
    """Filter language_installs to only the residual that cannot be baked.

    Per DESIGN §6½ and the out-of-repo bake redesign: Python/Ruby/Rust/Go deps
    bake entirely to /opt/venv, /opt/bundle, CARGO_HOME, GOMODCACHE — workers
    resolve them with zero install. Node/pnpm's store is baked read-only, but
    the in-repo node_modules symlink tree must be recreated per worktree
    (irreducible ~223ms offline-relink). So config.toml holds ONLY that Node
    offline-relink residual; everything else is filtered out.

    Returns a filtered copy; the input is unchanged.
    """
    # Managers whose installs bake entirely (no residual)
    BAKEABLE_MANAGERS = frozenset([
        "pip", "pip3", "uv",        # Python → /opt/venv
        "bundle", "gem",             # Ruby → /opt/bundle
        "cargo",                     # Rust → CARGO_HOME/CARGO_TARGET_DIR
        "go",                        # Go → GOMODCACHE/GOCACHE
    ])
    # Node managers: keep only offline-relink commands
    NODE_MANAGERS = frozenset(["pnpm", "npm", "yarn"])

    residual = []
    for entry in language_installs:
        manager = entry.get("manager", "")
        command = entry.get("command", "") or ""  # Guard against explicit None

        # Filter out bakeable managers entirely
        if manager in BAKEABLE_MANAGERS:
            continue

        # For Node managers, keep only offline-relink commands
        if manager in NODE_MANAGERS:
            # The irreducible residual is the offline/frozen-lockfile relink
            # of an *install* — e.g. "pnpm install --offline
            # --frozen-lockfile". Two independent conditions, both needed:
            #
            #   subcommand  the flags alone are not enough. "pnpm add
            #               left-pad --frozen-lockfile" carries a pinned
            #               flag but mutates the dependency set over the
            #               network; re-running it per worktree is the
            #               opposite of a relink. Same for remove/up/dlx.
            #   flag        OR, not AND: the three managers spell this
            #               differently (pnpm wants both, "npm install
            #               --offline" and "yarn install --frozen-lockfile"
            #               each stand alone), so requiring both would
            #               drop two of the three.
            #
            # Token membership, not substring: "--offline" appearing
            # inside a package name or a path must not count.
            try:
                toks = shlex.split(command)
            except ValueError:      # unbalanced quotes in a captured line
                continue
            if len(toks) < 2 or toks[1] not in _NODE_INSTALL_SUBCOMMANDS:
                continue
            if "--offline" in toks or "--frozen-lockfile" in toks:
                residual.append(entry)
            continue

        # Any other manager: leerie bakes only `BAKE_INSTALL_COMMANDS`,
        # each with its own command, so nothing else is ever recorded
        # (DESIGN §6½ *A capture names packages and managers, never
        # commands*).
        if manager in BAKE_INSTALL_COMMANDS:
            residual.append(entry)

    return residual


def _capture_problems(setup_packages: object, language_installs: object
                      ) -> list[str]:
    """Why a capture cannot be recorded or applied, each named; [] when it
    can (DESIGN §6½ *A capture names packages and managers, never
    commands*): every `setup_packages` item a Debian package name, every
    `language_installs` entry a manager leerie bakes and plain relative
    input paths. The same rules as `SCHEMAS["dep_capture"]`, here because a
    capture file is read back and the schema is not the only writer."""
    out: list[str] = []
    if not isinstance(setup_packages, list):
        out.append("setup_packages is not a list")
        setup_packages = []
    for p in setup_packages:
        if not (isinstance(p, str)
                and re.fullmatch(DEBIAN_PACKAGE_PATTERN, p)):
            out.append(f"setup_packages item {p!r} is not a Debian "
                       "package name")
    if not isinstance(language_installs, list):
        out.append("language_installs is not a list")
        language_installs = []
    for e in language_installs:
        if not isinstance(e, dict):
            out.append(f"language_installs entry {e!r} is not an object")
            continue
        m = e.get("manager")
        if not (isinstance(m, str) and m in BAKE_INSTALL_COMMANDS):
            out.append(f"language_installs manager {m!r} is not one leerie "
                       f"bakes ({', '.join(sorted(BAKE_INSTALL_COMMANDS))})")
        ins = e.get("copy_inputs", [])
        if not isinstance(ins, list):
            out.append(f"language_installs copy_inputs {ins!r} is not a list")
            continue
        for ci in ins:
            if not (isinstance(ci, str)
                    and re.fullmatch(CAPTURE_INPUT_PATTERN, ci)
                    and ".." not in ci.split("/")):
                out.append(f"language_installs input {ci!r} is not a plain "
                           "relative path")
    return out


def _table_installs(language_installs: list[dict]) -> list[dict]:
    """Each entry as leerie records it: its manager, the command leerie's
    table gives that manager (never the capture's own), and its inputs."""
    return [{"manager": e["manager"],
             "command": BAKE_INSTALL_COMMANDS[e["manager"]],
             "copy_inputs": list(e.get("copy_inputs") or [])}
            for e in language_installs]


CAPTURED_DEPS_FILE = "captured-deps.json"
CAPTURED_DEPS_APPLIED_FILE = "captured-deps.applied.json"


def _merge_capture_into_config(cfg_path: Path, setup_packages: list[str],
                               language_installs: list[dict],
                               replace: bool) -> dict[str, str]:
    """Merge one capture into `cfg_path` as it is now (DESIGN §6½): union /
    never-clobber, or wholesale replace for `--recapture --force`. Returns
    the keys written. A capture `_capture_problems` refuses writes nothing:
    refused whole, never trimmed to what passes."""
    problems = _capture_problems(setup_packages, language_installs)
    if problems:
        log("capture: refused, nothing written to "
            f"{cfg_path}: " + "; ".join(problems))
        return {}
    language_installs = _table_installs(language_installs)
    updates: dict[str, str] = {}
    if setup_packages:
        if replace:
            # Wholesale replace: drop packages no longer captured. Gate on the
            # *rendered* value, not list truthiness — a schema-valid empty-item
            # capture ([""]) is a truthy list but renders to "", which would
            # blank a good config. Only write a non-empty value.
            norm = _normalize_setup_packages(setup_packages)
            if norm:
                updates["setup_packages"] = norm
        else:
            existing = _read_toml_key(cfg_path, "setup_packages") or ""
            merged = _merge_setup_packages(existing, setup_packages)
            if merged is not None:
                updates["setup_packages"] = merged
    if language_installs:
        # JSON-in-TOML because TOML has no inline array type compatible with
        # the flat _read_toml_key/_write_config_toml_keys surface.
        if replace:
            # Wholesale replace: the fresh capture is authoritative — drop
            # managers no longer present. Filter empty-manager junk (mirrors the
            # union path below) and gate on the filtered list being non-empty so
            # an empty-item capture never blanks a good config.
            kept = [e for e in language_installs if e.get("manager")]
            if kept:
                updates["language_installs"] = _dump_language_installs(kept)
        else:
            existing_raw = _read_toml_key(cfg_path, "language_installs") or ""
            try:
                existing_list: list[dict] = json.loads(existing_raw) if existing_raw else []
            except (json.JSONDecodeError, ValueError):
                existing_list = []
            existing_managers = {e.get("manager") for e in existing_list if e.get("manager")}
            new_entries = [e for e in language_installs
                           if e.get("manager") and e["manager"] not in existing_managers]
            if new_entries:
                merged_list = existing_list + new_entries
                updates["language_installs"] = _dump_language_installs(merged_list)
    if updates:
        _write_config_toml_keys(cfg_path, updates)
        pkg_note = f" setup_packages={updates['setup_packages']!r}" if "setup_packages" in updates else ""
        li_note = f" language_installs({len(language_installs)} entries)" if "language_installs" in updates else ""
        log(f"capture: dep_capture wrote{pkg_note}{li_note} to {cfg_path}; "
            "run `git add .leerie/ && git commit` to bake next run")
        return updates
    elif replace:
        # Under --force, an empty capture must not blank a good config.
        log("capture: dep_capture captured no deps — leaving existing config unchanged")
    else:
        log("capture: dep_capture found no new deps to write")
    return updates


def _record_capture(record_in: Path, from_run: str, setup_packages: list[str],
                    language_installs: list[dict], replace: bool) -> None:
    """Append one capture to `<record_in>/captured-deps.json` for the
    operator to apply (`apply_captured_deps`). Nothing is recorded for an
    empty one, nor for one `_capture_problems` refuses."""
    if not setup_packages and not language_installs:
        log("capture: dep_capture found no deps to record")
        return
    problems = _capture_problems(setup_packages, language_installs)
    if problems:
        log("capture: refused, nothing recorded: " + "; ".join(problems))
        return
    language_installs = _table_installs(language_installs)
    path = record_in / CAPTURED_DEPS_FILE
    try:
        entries = json.loads(path.read_text()) if path.is_file() else []
    except (OSError, ValueError):
        entries = []
    if not isinstance(entries, list):
        entries = []
    entries.append({"from_run": from_run,
                    "setup_packages": list(setup_packages),
                    "language_installs": list(language_installs),
                    "replace": bool(replace)})
    tmp = path.with_name(f"{path.name}.tmp.{os.getpid()}")
    tmp.write_text(json.dumps(entries, indent=1) + "\n")
    os.replace(tmp, path)
    log(f"capture: recorded {len(setup_packages)} setup_packages and "
        f"{len(language_installs)} language installs in {path}; review and "
        f"apply them with `leerie config --apply-capture {record_in.name}`")


def _config_capture_problems(cfg: Path) -> list[str]:
    """`_capture_problems` of what `cfg` holds now: its `setup_packages`
    items and its `language_installs`, which must be a JSON list."""
    pkgs = _split_setup_packages(_read_toml_key(cfg, "setup_packages") or "")
    raw = _read_toml_key(cfg, "language_installs") or ""
    try:
        installs = json.loads(raw) if raw else []
    except ValueError:
        return (_capture_problems(pkgs, [])
                + [f"language_installs {raw!r} is not a JSON list"])
    return _capture_problems(pkgs, installs)


def apply_captured_deps(run_dir: Path, repo_root: Path) -> int:
    """The operator's `leerie config --apply-capture <run>` (DESIGN §6½ *The
    operator applies a capture*): apply the captures that run recorded
    (`_record_capture`) to `repo_root/.leerie/config.toml`, each merged
    against the file as it is now, and log the change as a diff. Nothing
    else applies a capture: a run never chooses what the next run's image
    runs. Every entry is checked first (`_capture_problems`); one that
    fails refuses the whole file, which is kept. The applied entries move
    to `captured-deps.applied.json`, so a second call is a no-op. Returns
    how many were applied; a file that cannot be read is logged and
    kept."""
    path = Path(run_dir) / CAPTURED_DEPS_FILE
    if not path.is_file():
        log(f"capture: {path} does not exist; nothing to apply")
        return 0
    try:
        entries = json.loads(path.read_text())
        if not isinstance(entries, list):
            raise ValueError("not a list")
    except (OSError, ValueError) as e:
        log(f"capture: could not read {path} ({e}); kept for a later apply")
        return 0
    problems = [p for e in entries
                for p in (_capture_problems(e.get("setup_packages") or [],
                                            e.get("language_installs") or [])
                          if isinstance(e, dict) else [f"{e!r}"])]
    if problems:
        die(f"capture: {path} is refused, nothing was applied: "
            + "; ".join(problems))
    cfg = Path(repo_root) / ".leerie" / "config.toml"
    root = Path(repo_root)
    # A merge keeps what the file holds, so the merged value is valid only
    # when that is: check it too (review round 29, execution L4).
    if any(not (isinstance(e, dict) and e.get("replace")) for e in entries):
        held = _config_capture_problems(cfg)
        if held:
            die(f"capture: {path} is refused, nothing was applied: the "
                f"merged value would keep what {cfg} already holds, and "
                "that is not a capture leerie bakes: " + "; ".join(held)
                + ". Fix or remove those entries in .leerie/config.toml "
                "and apply again.")
    try:
        before = _read_text_beneath(root, cfg, limit=READ_LIMIT_CONFIG)
    except OSError:
        before = ""
    for e in entries:
        _merge_capture_into_config(
            cfg, list(e.get("setup_packages") or []),
            list(e.get("language_installs") or []), bool(e.get("replace")))
    try:
        after = _read_text_beneath(root, cfg, limit=READ_LIMIT_CONFIG)
    except OSError:
        after = ""
    for line in difflib.unified_diff(
            before.splitlines(), after.splitlines(),
            fromfile=".leerie/config.toml", tofile=".leerie/config.toml",
            lineterm=""):
        log(f"  {line}")
    done = path.with_name(CAPTURED_DEPS_APPLIED_FILE)
    try:
        prior = json.loads(done.read_text()) if done.is_file() else []
    except (OSError, ValueError):
        prior = []
    tmp = done.with_name(f"{done.name}.tmp.{os.getpid()}")
    tmp.write_text(json.dumps((prior if isinstance(prior, list) else [])
                              + entries, indent=1) + "\n")
    os.replace(tmp, done)
    path.unlink()
    return len(entries)


async def capture_repo_deps(
        repo_root: Path,
        st: object,
        caps: dict | None = None,
        models: dict[str, str] | None = None,
        efforts: dict[str, str | None] | None = None,
        replace: bool = False,
        record_in: Path | None = None,
) -> None:
    """Invoke the dep_capture LLM worker and record what it captured (non-fatal).

    record_in (the current run's directory in the container; the target
    run's for the host's `run_recapture_deps`): the capture is recorded in
    `<record_in>/captured-deps.json`, and only the operator's `leerie config
    --apply-capture <run>` writes `.leerie/config.toml`
    (`apply_captured_deps`; DESIGN §6½ *The operator applies a capture*).
    Nothing is recorded without it.

    replace=False (default, every automatic seam): union / never-clobber —
    only new packages/managers are added, existing entries are preserved.
    replace=True (only the operator-driven `--recapture --force` path):
    wholesale-replace the persisted setup_packages + language_installs from the
    fresh capture. A capture that yields nothing under replace leaves the
    existing values untouched (never blanks a good config with an empty run).
    """
    if not resolve_capture_deps(repo_root):
        return
    if caps is None or models is None or efforts is None:
        log("capture: skipped dep_capture worker (caps/models/efforts not "
            "available at finalize time)")
        return
    log_dir = getattr(st, "run_dir", None)
    if log_dir is None:
        return
    log_dir = Path(log_dir) / "logs"
    if not log_dir.is_dir():
        return
    # Manifests-first corpus (DESIGN §6½): manifest files are primary ground
    # truth; install-filtered commands are only a hint for system/native deps.
    manifests_text = _gather_dep_manifests(repo_root)
    commands_text, hit_ceiling = _extract_depcap_commands(log_dir)
    if not manifests_text.strip() and not commands_text.strip():
        log("capture: no dependency manifests and no install commands found — "
            "skipping dep_capture")
        return
    wc = st.data.get("worker_count", 0) if hasattr(st, "data") else 0
    if wc >= caps["max_total_workers"]:
        log(f"capture: skipped dep_capture worker (worker budget exhausted at "
            f"{wc}/{caps['max_total_workers']})")
        return
    sys_prompt = _load_prompt("dep_capture")
    model = models.get("dep_capture", MODEL_DEFAULT)
    effort = efforts.get("dep_capture")
    truncation_note = (
        "\n\n[NOTE: command list was truncated at the byte budget ceiling — "
        "the most recent commands are shown first]"
        if hit_ceiling else ""
    )
    manifests_section = (
        manifests_text if manifests_text.strip()
        else "(No dependency manifest files found in the repo.)"
    )
    commands_section = (
        f"{commands_text}{truncation_note}" if commands_text.strip()
        else "(No package-manager install commands observed during the run.)"
    )
    user_prompt = (
        "## Dependency manifest files found in the repo (PRIMARY):\n\n"
        f"{manifests_section}\n\n"
        "## Install commands observed during the run "
        "(SECONDARY hint, filtered):\n\n"
        f"{commands_section}"
    )
    if hasattr(st, "bump_workers"):
        st.bump_workers(caps)
    result = await claude_p(
        user_prompt=user_prompt,
        system_prompt=sys_prompt,
        schema_key="dep_capture",
        cwd=_payload_only_cwd(st),
        allowed_tools=PAYLOAD_ONLY_TOOLS,
        max_turns=10,
        autonomous=False,
        caps=caps,
        st=st,
        model=model,
        effort=effort,
        sid="dep-capture",
    )
    setup_packages: list[str] = result.get("setup_packages") or []
    language_installs_captured: list[dict] = result.get("language_installs") or []

    # Filter to residual-only (DESIGN §6½): the worker captures everything, but
    # config.toml holds only deps that cannot be baked (Node offline-relink).
    # Python/Ruby/Rust/Go bake entirely; their installs are filtered out.
    language_installs = _filter_residual_deps(language_installs_captured)

    # Log what was captured vs. what will be written (makes filtering observable)
    if language_installs_captured:
        filtered_count = len(language_installs_captured) - len(language_installs)
        if filtered_count > 0:
            log(f"capture: captured {len(language_installs_captured)} language installs, "
                f"filtered {filtered_count} bakeable (writing {len(language_installs)} residual)")
        else:
            log(f"capture: captured {len(language_installs_captured)} language installs "
                f"(all residual, none filtered)")
    if setup_packages:
        log(f"capture: captured {len(setup_packages)} setup_packages")

    if record_in is not None:
        _record_capture(Path(record_in), Path(str(log_dir)).parent.name,
                        setup_packages, language_installs, replace)
    else:
        log("capture: no run directory to record the capture in; "
            "nothing recorded")
    # Write idempotency sentinel. Both a state field (for in-run readers)
    # and a lightweight file (for the next-run backstop, which reads past
    # run dirs without constructing a full State).
    run_dir_path = getattr(st, "run_dir", None)
    if run_dir_path is not None:
        try:
            (Path(run_dir_path) / "dep_capture.done").write_text("1\n")
        except Exception:
            pass
    if hasattr(st, "data"):
        try:
            st.data["dep_capture_done"] = True
        except Exception:
            pass


async def _backstop_capture_prior_runs(
        leerie_root: Path,
        repo_root: Path,
        caps: dict,
        models: dict[str, str],
        efforts: dict[str, str | None],
        record_in: Path,
) -> None:
    """Cover SIGKILL/crash: run dep_capture over prior runs with logs/ but no
    sentinel, recording each capture in `record_in` (the current run's
    directory) for the host to apply after this run's container exits."""
    runs_dir = leerie_root / "runs"
    if not runs_dir.is_dir():
        return
    for run_dir in sorted(runs_dir.iterdir(), reverse=True):
        if not run_dir.is_dir():
            continue
        log_dir = run_dir / "logs"
        if not log_dir.is_dir():
            continue
        # An EMPTY logs/ is a skeleton, not a run: `main()` mkdirs the run
        # subtree before several startup resolvers that can die() (a bad
        # --worker-memory-max, a declared heap that cannot fit the slice),
        # so a rejected launch leaves a dir with logs/ and no sentinel.
        # Without this it draws a dep_capture worker on every later run,
        # forever, over a directory that never produced a single log line.
        # `iterdir()` scandirs lazily inside `any()`, so unlike the `is_dir`
        # guards above — which swallow OSError and return False — this line
        # RAISES. A concurrent `cleanup.sh` removing a run dir in the window
        # since `log_dir.is_dir()`, or a dir that is simply unreadable,
        # would then propagate out of a function its call site documents as
        # "Non-fatal: any error is logged and ignored" and abort the run at
        # startup. Treat an unreadable logs/ as an empty one: both mean
        # there is nothing here to capture.
        try:
            if not any(log_dir.iterdir()):
                continue
        except OSError:
            continue
        sentinel = run_dir / "dep_capture.done"
        if sentinel.is_file():
            continue
        log(f"backstop: running dep_capture for prior run {run_dir.name}")
        try:

            class _BackstopState:
                pass

            bst = _BackstopState()
            bst.run_dir = run_dir  # type: ignore[attr-defined]
            bst.data = {}  # type: ignore[attr-defined]
            bst.bump_workers = lambda _caps: None  # type: ignore[attr-defined]
            await capture_repo_deps(
                repo_root, bst,
                caps=caps, models=models, efforts=efforts,
                record_in=record_in,
            )
        # TerminalAuthFailure / RateLimitedExit subclass BaseException (so they
        # propagate through asyncio.gather and worker `except Exception` blocks);
        # capture_repo_deps -> claude_p can raise them, and a bare
        # `except Exception` would let them escape this best-effort call and
        # abort the backstop loop (or, in main()'s exit handlers, skip the
        # EXIT_LOCKED pause). Catch them here so capture stays non-fatal.
        except (Exception, TerminalAuthFailure, RateLimitedExit,
                ContextOverflow, DiskLowSpace,
                ConfinementRefused) as exc:
            log(f"backstop: non-fatal error capturing {run_dir.name}: {exc}")


def _resolve_host_seam_settings(
        repo_root: Path,
) -> tuple[dict, dict, dict]:
    """Shared host-seam settings resolver for host-side, non-interactive
    entrypoints (`run_recapture_deps`, `run_rebaser`) that have no argparse
    Namespace of their own. Returns `(caps, models, efforts)` with
    `worker_timeout_sec`/`worker_timeout_explicit` applied on `caps`, so env
    vars and `leerie.toml` are still honoured even though there is no CLI —
    without this the per-worker table pins these entrypoints at their
    hardcoded timeouts (rebaser 1371s, dep_capture 600s) with no way to
    raise it. Marks the caps as the host-side seam (`HOST_SEAM_CAP`): its
    workers run on the user's host, are not run workers, and macOS has no
    Landlock, so they are not confined (DESIGN §6 *Outside the
    container*)."""
    caps = dict(DEFAULT_CAPS)
    caps[HOST_SEAM_CAP] = True

    # Minimal args namespace so resolve_models/efforts can read env vars and
    # TOML but have no CLI overrides (this is a host-side non-interactive call).
    class _MinimalArgs:
        model = None
        pr_writer_model = None
        effort = None

    _args = _MinimalArgs()
    models = resolve_models(repo_root, _args)
    efforts = resolve_efforts(repo_root, _args)
    caps["worker_timeout_sec"] = resolve_worker_timeout_sec(repo_root)
    caps["worker_timeout_explicit"] = resolve_worker_timeout_explicit(
        repo_root)
    return caps, models, efforts


def run_recapture_deps(
        leerie_root: Path,
        repo_root: Path,
        force: bool = False,
        run_id: str | None = None,
) -> None:
    """Host-side recapture entrypoint (DESIGN §6½) — consolidates dep_capture across runs."""
    caps, models, efforts = _resolve_host_seam_settings(repo_root)

    if run_id is not None:
        target_run_dir = leerie_root / "runs" / run_id
        if not target_run_dir.is_dir():
            die(f"recapture: run {run_id!r} not found under {leerie_root / 'runs'}")
        target_dirs: list[Path] = [target_run_dir]
    else:
        runs_dir = leerie_root / "runs"
        if not runs_dir.is_dir():
            die(f"recapture: no runs directory at {runs_dir}; nothing to recapture")
        finished: list[Path] = []
        for d in runs_dir.iterdir():
            if not d.is_dir():
                continue
            rj = d / "run.json"
            if not rj.is_file():
                continue
            try:
                rdata = json.loads(rj.read_text())
            except (OSError, ValueError):
                continue
            if rdata.get("finished_at") and (d / "logs").is_dir():
                finished.append(d)
        if not finished:
            die("recapture: no completed run with logs found; nothing to recapture")
        # Process newest-first so the most recent installs inform the decision.
        target_dirs = sorted(finished, reverse=True)

    ran_any = False
    for target_run_dir in target_dirs:
        sentinel = target_run_dir / "dep_capture.done"
        if force:
            # Drop sentinel so the worker fires unconditionally on this run.
            try:
                sentinel.unlink(missing_ok=True)
            except Exception:
                pass
        elif sentinel.is_file():
            continue

        # Flock the run dir (refuse to race a live orchestrator). --phase judge
        # pattern: construct State → catch StateLockedError → skip (not fatal
        # for multi-run consolidation; we still capture the others).
        try:
            target_st = State(leerie_root, target_run_dir.name, repo_root=repo_root)
        except StateLockedError as e:
            log(f"recapture: skipping {target_run_dir.name!r}: another "
                f"orchestrator owns the run (holding flock on {e.run_dir}).")
            continue
        target_st.load()  # non-fatal if state.json is missing (older runs)

        # Same host-seam wiring gap as run_rebaser (see there): this
        # entrypoint runs in its own process, never through
        # _orchestrate()'s CLI-arg resolution or _STRICT_PROXY setup, so
        # capture_repo_deps's claude_p() call always ran unconstrained
        # regardless of the flag. Read the per-run value _orchestrate()
        # already resolved and persisted into THIS run's own state (each
        # target_run_dir may have been run with a different setting).
        run_caps = dict(caps)
        run_caps["force_strict_output"] = (
            target_st.data["dangerously_force_strict_output"]
            if "dangerously_force_strict_output" in target_st.data
            else resolve_dangerously_force_strict_output(repo_root, False))

        async def _capture_with_strict_output() -> bool:
            async with _strict_output_proxy(run_caps, "recapture"):
                try:
                    await capture_repo_deps(
                        repo_root, target_st,
                        caps=run_caps, models=models, efforts=efforts,
                        replace=force, record_in=target_run_dir,
                    )
                    return True
                # See the backstop guard above: TerminalAuthFailure /
                # RateLimitedExit are BaseException subclasses that a bare
                # `except Exception` misses. This must stay the innermost try
                # DIRECTLY wrapping capture_repo_deps() —
                # tests/test_capture_swallows_exit_signals.py AST-scans for
                # exactly that shape and fails loudly if the guard and the
                # call it guards ever drift apart.
                except (Exception, TerminalAuthFailure, RateLimitedExit,
                        ContextOverflow, DiskLowSpace,
                        ConfinementRefused) as exc:
                    log(f"recapture: error during dep_capture for "
                        f"{target_run_dir.name}: {exc}")
                    return False

        log(f"recapture: scanning {target_run_dir / 'logs'} ...")
        # The guard inside the coroutine covers the capture call itself; this
        # one covers everything around it (proxy construction, a non-OSError
        # from start(), asyncio.run itself). Without it a setup failure would
        # abort the whole multi-run consolidation, breaking this function's
        # "per-run errors are logged and skipped" contract.
        try:
            if asyncio.run(_capture_with_strict_output()):
                ran_any = True
        except (Exception, TerminalAuthFailure, RateLimitedExit,
                ContextOverflow, DiskLowSpace,
                ConfinementRefused) as exc:
            log(f"recapture: error during dep_capture for "
                f"{target_run_dir.name}: {exc}")

    if not ran_any and not force:
        log("recapture: all eligible runs already captured (use --force to re-run)")


def run_rebaser(
        leerie_root: Path,
        repo_root: Path,
        run_id: str,
        worktree: Path,
        run_branch: str,
        working_branch: str,
        pr_base_branch: str,
) -> dict:
    """Host-side entrypoint for the `rebaser` worker (DESIGN §6 *Finalization*
    "Rebase-onto-base before push"). Same host-seam shape as
    `run_recapture_deps` above: `scripts/host-finalize.sh` invokes this via
    the `python3 -` heredoc pattern used by `./leerie config --recapture`
    (leerie:1121-1163) — see that call site for the exact bash side.

    `worktree` is a worktree of the rebaser's own repository (DESIGN §6
    *The run's own repository*) checked out on `run_branch`,
    created by the caller (`host-finalize.sh`) BEFORE this runs and removed
    by the caller AFTER — this function only operates on it: the `rebaser`
    worker is told its path and given it by `--add-dir`, and starts in an
    empty directory of leerie's (`_host_worker_cwd`), never in the worktree,
    which holds the run branch's content (DESIGN §6 *The host never runs a
    program the checkout chose*, part 4).

    This is a scoped, fully-agentic exception to §12 ("prompts are advisory,
    code enforces"): the worker performs the entire rebase workflow itself —
    fetch, rebase, per-hunk conflict resolution preserving both branches'
    intent, and the abort-if-irreconcilable judgment call — rather than each
    mechanical step being coded with only conflict-resolution *content*
    delegated to a worker (contrast `integrator`, whose merge mechanics are
    driven by `integrate_wave` in Python). Returns the worker's
    schema-validated verdict dict (`status` / `final_branch_state` /
    `resolution_summary` / `diagnosis` / `confidence`) UNVERIFIED — the
    caller (`host-finalize.sh`) is responsible for the mechanical
    post-hoc check (no conflict markers / not mid-rebase on a "rebased"
    claim; worktree tip unchanged on an "irreconcilable"/"failed" claim)
    before trusting this result, per the same "don't trust the self-report"
    discipline used for `integrator`.

    Runs `check_rebaser_worktree_state` itself before returning — the caller
    can trust the returned `status`, it does not need to re-verify.

    Never raises for an ordinary worker failure — swallows to a
    `{"status": "failed", ...}` result — so the caller's push path is never
    blocked by this being best-effort (DESIGN §6 hard requirement: never
    pause/block finalize over the rebase)."""
    caps, models, efforts = _resolve_host_seam_settings(repo_root)

    try:
        st = State(leerie_root, run_id, repo_root=repo_root)
    except StateLockedError as e:
        return {
            "status": "failed",
            "final_branch_state": "skipped",
            "resolution_summary": "",
            "diagnosis": f"run dir locked by another orchestrator: {e.run_dir}",
            "confidence": {"resolution": 0.0},
        }
    st.load()

    # This entrypoint runs in its own fresh python3 process
    # (host-finalize.sh's heredoc), so it never goes through
    # _orchestrate()'s CLI-arg resolution or _STRICT_PROXY setup — without
    # this, claude_p() below always ran unconstrained regardless of the
    # flag. Read the value _orchestrate() already resolved and persisted
    # into this run's own state as the source of truth (the CLI flag
    # itself never reaches this process); fall back to a fresh resolve
    # only for old state.json files that predate this field.
    caps["force_strict_output"] = (
        st.data["dangerously_force_strict_output"]
        if "dangerously_force_strict_output" in st.data
        else resolve_dangerously_force_strict_output(repo_root, False))

    # Worker-budget pre-check (mirrors capture_repo_deps's identical guard
    # above): the run has already spent its budget across the whole
    # _orchestrate loop by the time finalize runs, so a rebaser call must
    # respect the same max_total_workers ceiling — CLAUDE.md "Caps are real
    # Python counters," not a worker that bounds itself.
    wc = st.data.get("worker_count", 0)
    if wc >= caps["max_total_workers"]:
        return {
            "status": "failed",
            "final_branch_state": "skipped",
            "resolution_summary": "",
            "diagnosis": (
                f"rebaser skipped: worker budget exhausted "
                f"({wc}/{caps['max_total_workers']})"
            ),
            "confidence": {"resolution": 0.0},
        }

    # Leerie's own git names the worktree and starts from `/`; the worker's
    # CLI starts in a directory of leerie's (DESIGN §6 *The host never runs
    # a program the checkout chose*, part 4): the worktree is the run
    # branch, which no operator has merged.
    pre_rebase_sha_r = asyncio.run(
        run_proc(["git", *_tree_git_args(worktree), "rev-parse", "HEAD"], cwd="/"))
    if pre_rebase_sha_r.returncode != 0:
        return {
            "status": "failed",
            "final_branch_state": "could not resolve worktree HEAD",
            "resolution_summary": "",
            "diagnosis": "git rev-parse HEAD failed in the disposable worktree",
            "confidence": {"resolution": 0.0},
        }
    pre_rebase_sha = pre_rebase_sha_r.stdout.strip()

    # The rebaser's own repository (`host-finalize.sh`'s
    # `_host_finalize_rebase_repo`, DESIGN §6 *The run's own repository*)
    # takes the user's repository-local config — its `origin`, which the
    # rebaser fetches, and the hooks its commits run. Never written into the
    # user's own repository: skipped when the worktree belongs to it.
    def _common(path: str | Path) -> str:
        r = _git_sync([*_tree_git_args(path), "rev-parse", "--path-format=absolute",
                       "--git-common-dir"], timeout=30)
        return os.path.realpath(r.stdout.strip()) if r.returncode == 0 else ""
    own_common, user_common = _common(worktree), _common(repo_root)
    if own_common and user_common and own_common != user_common:
        try:
            _carry_repo_config(Path(repo_root), Path(own_common))
        except (RunRepoError, OSError, subprocess.TimeoutExpired) as e:
            log(f"rebaser: the user's repository config was not carried "
                f"({e}); the rebase runs without it")

    # The run's own commits by the commit the run branch was cut from: it is
    # an ancestor of the run branch, so the rebaser's single-branch
    # repository holds it, while the working branch's name may not resolve
    # there (review round 17 M1). A run from before `base_sha` keeps the
    # name, best-effort as before.
    run_base = st.data.get("base_sha") or working_branch
    sys_prompt = _load_prompt("rebaser")
    user_prompt = (
        f"The disposable worktree: {worktree}\n"
        f"Current branch (this worktree's checkout): {run_branch}\n"
        f"Base branch to rebase onto: {pr_base_branch}\n"
        f"Only replay commits unique to {run_branch} — i.e. the range "
        f"{run_base}..{run_branch} — onto the fresh tip of "
        f"{pr_base_branch}. Do not touch any other branch."
    )

    async def _call_with_strict_output(cwd: Path) -> dict:
        async with _strict_output_proxy(caps, "rebaser"):
            return await claude_p(
                user_prompt=user_prompt,
                system_prompt=sys_prompt,
                schema_key="rebaser",
                cwd=str(cwd),
                add_dirs=[str(worktree)],
                allowed_tools=ACT_TOOLS,
                max_turns=60,
                autonomous=True,
                caps=caps,
                st=st,
                model=models.get("rebaser", MODEL_DEFAULT),
                effort=efforts.get("rebaser"),
                sid=f"rebaser-{run_id}",
            )

    neutral: Path | None = None
    try:
        neutral = _host_worker_cwd(repo_root, worktree)
        st.bump_workers(caps)
        result = asyncio.run(_call_with_strict_output(neutral))
    # See run_recapture_deps's identical guard above: TerminalAuthFailure /
    # RateLimitedExit are BaseException subclasses a bare `except Exception`
    # would miss, and this call must never propagate past host-finalize.sh's
    # best-effort rebase step.
    except (Exception, TerminalAuthFailure, RateLimitedExit,
            ContextOverflow, DiskLowSpace) as exc:
        return {
            "status": "failed",
            "final_branch_state": "worker invocation error",
            "resolution_summary": "",
            "diagnosis": str(exc),
            "confidence": {"resolution": 0.0},
        }
    finally:
        if neutral is not None:
            _rmtree_owned(neutral)
    # claude_p() returns the already schema-validated structured_output dict
    # directly (not an envelope) — it raises WorkerError, never returns a
    # dict missing required fields, so `result` here is always well-formed
    # per SCHEMAS["rebaser"].
    structured = result
    claimed_status = structured.get("status")
    mismatch = asyncio.run(check_rebaser_worktree_state(
        worktree, claimed_status, pre_rebase_sha,
        base_ref=f"origin/{pr_base_branch}"))
    if mismatch is not None:
        # The worker's self-report doesn't match observable git state —
        # per §12, do not trust the claim. Downgrade to "failed" so the
        # caller's push path treats this exactly like any other rebase
        # failure (push the original branch, leave working_branch alone).
        return {
            "status": "failed",
            "final_branch_state": structured.get("final_branch_state", ""),
            "resolution_summary": structured.get("resolution_summary", ""),
            "diagnosis": (
                f"rebaser mechanical checkpoint failed: {mismatch}"
            ),
            "confidence": structured.get("confidence", {"resolution": 0.0}),
        }
    return structured


def _split_readme_headers(text: str) -> list[tuple[int, str, str]]:
    """Return [(line_index, header_text, body_until_next_header), ...] for
    text. Supports three header styles:
      - ATX: lines starting with `#`, `##`, etc.
      - Setext: a line followed by `===` or `---` of equal length.
      - Asciidoc: lines starting with `==`, `===`, etc. (no `#`).

    Returns sections in document order. The first section's header text
    is "" if the file does not start with a header (the "intro").
    """
    lines = text.split("\n")
    n = len(lines)
    # Find header line indices first.
    headers: list[tuple[int, str]] = []  # (line_index, header_text)
    i = 0
    while i < n:
        line = lines[i]
        stripped = line.strip()
        # ATX (`# Foo`, `## Foo`, etc.). Asciidoc level markers (`==
        # Foo`) are picked up too — the leading `=` group reads as
        # header decoration once we strip it for keyword matching.
        if stripped.startswith("#") or stripped.startswith("=="):
            headers.append((i, stripped))
            i += 1
            continue
        # Setext: `Foo\n=====` (h1) or `Foo\n-----` (h2). The underline
        # must be at least 3 chars of `=` or `-` and roughly the length
        # of the line above (RST conventions are looser than Markdown's
        # but we accept any underline ≥3 chars).
        if i + 1 < n and stripped:
            nxt = lines[i + 1].strip()
            if len(nxt) >= 3 and (set(nxt) == {"="} or set(nxt) == {"-"}):
                headers.append((i, stripped))
                i += 2
                continue
        i += 1

    if not headers:
        return [(0, "", text)]

    sections: list[tuple[int, str, str]] = []
    # Intro before the first header.
    if headers[0][0] > 0:
        intro_body = "\n".join(lines[: headers[0][0]])
        sections.append((0, "", intro_body))
    for k, (start, hdr) in enumerate(headers):
        end = headers[k + 1][0] if k + 1 < len(headers) else n
        body = "\n".join(lines[start: end])
        sections.append((start, hdr, body))
    return sections


# Size budgets for the provision-worker README fixture. The worker
# decides which parts describe installation; these only bound how much it
# sees (DESIGN §6½).
# 12KB, not 8: measured against this repo's own 75KB / 89-section README,
# an 8KB slice cut `### Manual container-runtime setup` (byte 8701) and the
# `brew install colima` prerequisite (9009) — content the keyword filter this
# replaced would have reached at any depth. 16KB was tried and rejected: it
# pushes the fixture set past `_FIXTURE_TOTAL_BUDGET` and silently drops
# CONTRIBUTING, which is a higher-signal install source than a README's tail.
_README_EXTRACT_BUDGET = 12288  # per-README slice handed to the worker
_FIXTURE_TOTAL_BUDGET = 24576   # 24KB hard ceiling per repo


def _extract_readme_sections(text: str) -> str:
    """Return the leading slice of a README, cut at a section boundary.

    Size-bounding only. WHICH parts of a README describe installation is a
    judgment about prose, so the provision worker makes it — this function
    just decides how much text it gets to see.

    It used to pre-select "install-ish" sections by keyword-matching each
    header against `_README_SECTION_RE` (`install|setup|usage|build|…`),
    which is regex over prose to classify it — CLAUDE.md
    *Language-to-JSON*. The keyword list was also a permanent maintenance
    tax: every project that names the section something the list had not
    anticipated silently fell through to a cruder fallback.

    The cut is section-aware so the worker never receives a header with
    its body sheared off mid-sentence, but that is presentation, not
    selection: nothing here reads what a header *means*. A README longer
    than the budget is truncated from the bottom, and
    `_gather_provision_fixtures` flags that through `hit_ceiling`; the
    worker also sees manifests, workflows and CONTRIBUTING, which is
    where install facts usually live when a README is that long.
    """
    if not text:
        return ""
    if len(text) <= _README_EXTRACT_BUDGET:
        return text

    cut = text[:_README_EXTRACT_BUDGET]
    # Back up to the last section boundary, but never discard more than a
    # quarter of the budget chasing one — a README with no headers in its
    # first three-quarters of the budget should still get that much.
    floor = int(_README_EXTRACT_BUDGET * 0.75)
    boundary = -1
    for start, _hdr, _body in _split_readme_headers(cut):
        offset = len("\n".join(cut.split("\n")[:start]))
        if floor <= offset < len(cut):
            boundary = max(boundary, offset)
    return cut[:boundary] if boundary > 0 else cut


def _read_file_safely(root: Path, path: Path, budget: int) -> str:
    """Read a file of the repository at `root` with a character ceiling,
    swallowing missing-file and decode errors, and refusing a link. Only the
    start is read (`_read_head_beneath`): `budget` characters of UTF-8 lie
    within `4 * budget` bytes. Used by _gather_provision_fixtures to
    assemble the fixture dict from optional repo files."""
    try:
        return _read_head_beneath(root, path, limit=4 * budget).decode(
            "utf-8", "replace")[:budget]
    except (OSError, UnicodeError):
        return ""


# Manifest file groups for the fixture gatherer.
_PROVISION_ROOT_MANIFESTS = (
    "package.json", "pyproject.toml", "go.mod", "Cargo.toml",
    "Gemfile", "Makefile", "pom.xml",
    "build.gradle", "build.gradle.kts",
)
_PROVISION_WORKFLOW_PREFERRED_RE = re.compile(r"(?i)\b(ci|test|build|release)\b")
_PROVISION_WORKFLOW_SKIP_RE = re.compile(r"(?i)\b(codeql|stale|dependabot)\b")


def _sample_workspace_manifests(repo_root: Path, pkg_json_text: str,
                                 per_file_budget: int,
                                 max_files: int) -> list[tuple[str, str]]:
    """For a monorepo whose root package.json declares `workspaces`,
    return up to `max_files` sampled child manifests as (rel_path, text)
    pairs. Returns [] if no workspaces are declared or no children are
    found."""
    try:
        pkg = json.loads(pkg_json_text)
    except (ValueError, TypeError):
        return []
    workspaces = pkg.get("workspaces")
    if isinstance(workspaces, dict):
        # npm/yarn shape: {"packages": [...]}
        workspaces = workspaces.get("packages")
    if not isinstance(workspaces, list) or not workspaces:
        return []

    sampled: list[tuple[str, str]] = []
    seen: set[Path] = set()
    for pattern in workspaces:
        if len(sampled) >= max_files:
            break
        if not isinstance(pattern, str):
            continue
        # glob via Path.glob (handles `packages/*` style).
        try:
            for child in _glob_beneath(repo_root, pattern + "/package.json"):
                if len(sampled) >= max_files:
                    break
                if child in seen:
                    continue
                seen.add(child)
                rel = child.relative_to(repo_root).as_posix()
                sampled.append((rel, _read_file_safely(
                    repo_root, child, per_file_budget)))
        except (OSError, ValueError):
            continue
    return sampled


def _gather_provision_fixtures(repo_root: Path) -> dict:
    """Assemble the LLM-fallback worker's input set. Returns a dict with
    keys:
      - readme: leading slice of the README (≤_README_EXTRACT_BUDGET);
        the worker decides which parts are install-relevant
      - readme_bytes_unseen / readme_sections_unseen: how much of the
        README fell outside that slice, so the worker knows when to lean
        on the manifests instead
      - manifests: dict[rel_path -> text] of root manifest files present
      - workspace_manifests: list[(rel_path, text)] sampled child
        manifests for monorepos (≤3 files, 1KB each)
      - workflows: list[(filename, text)] up to 2 GitHub Actions files
        preferring ci/test/build/release names
      - contributing: text of CONTRIBUTING.md or docs/DEVELOPMENT.md
        (≤4KB) or empty
      - total_bytes: int — actual size after assembly
      - hit_ceiling: bool — True if any section was truncated by the
        24KB total budget

    See DESIGN.md §6½ "Provision-worker input fixtures."
    """
    out: dict = {
        "readme": "",
        "readme_bytes_unseen": 0,
        "readme_sections_unseen": 0,
        "manifests": {},
        "workspace_manifests": [],
        "workflows": [],
        "contributing": "",
        "total_bytes": 0,
        "hit_ceiling": False,
    }

    def add_bytes(n: int) -> bool:
        """Return True if we have budget for `n` more bytes; flip
        hit_ceiling otherwise."""
        if out["total_bytes"] + n > _FIXTURE_TOTAL_BUDGET:
            out["hit_ceiling"] = True
            return False
        out["total_bytes"] += n
        return True

    # --- README ---
    readme_paths = [
        repo_root / "README.md",
        repo_root / "README.rst",
        repo_root / "README",
        repo_root / "README.txt",
        repo_root / "README.adoc",
    ]
    for rp in readme_paths:
        if _regular_file_beneath(repo_root, rp):
            raw = _read_file_safely(repo_root, rp, _README_EXTRACT_BUDGET * 4)
            extract = _extract_readme_sections(raw)
            if add_bytes(len(extract)):
                out["readme"] = extract
                # How much of the README the worker is NOT seeing. The
                # slice is the head of the file, so anything past the
                # budget is invisible — and on a long README that is
                # exactly where a late "Prerequisites" or "Troubleshooting"
                # section lives. Reporting the size of the gap (not
                # guessing at its contents, which would be back to
                # classifying prose) lets the worker weight the manifests
                # and workflows accordingly.
                try:
                    full = rp.lstat().st_size
                except OSError:
                    full = len(raw)
                out["readme_bytes_unseen"] = max(0, full - len(extract))
                # Header count must come from the WHOLE file, not `raw`
                # (itself capped at 4x the extract budget) — otherwise any
                # section past that cap is invisible to the count, not
                # merely "unseen." `readme_bytes_unseen` above already
                # gets this right via `rp.stat().st_size`; mirror it here
                # rather than deriving from the same truncated buffer used
                # for the extract itself.
                try:
                    full_text = _read_text_beneath(repo_root, rp, limit=READ_LIMIT_TEXT)
                except (OSError, UnicodeError):
                    full_text = raw
                out["readme_sections_unseen"] = max(
                    0, len(_split_readme_headers(full_text))
                    - len(_split_readme_headers(extract)))
            break

    # --- Root manifests ---
    pkg_json_text = ""
    for name in _PROVISION_ROOT_MANIFESTS:
        if out["hit_ceiling"]:
            break
        p = repo_root / name
        if not _regular_file_beneath(repo_root, p):
            continue
        text = _read_file_safely(repo_root, p, 8192)
        if not add_bytes(len(text)):
            break
        out["manifests"][name] = text
        if name == "package.json":
            pkg_json_text = text

    # --- Workspace child manifests (monorepo) ---
    if pkg_json_text and not out["hit_ceiling"]:
        children = _sample_workspace_manifests(
            repo_root, pkg_json_text, per_file_budget=1024, max_files=3)
        for rel, text in children:
            if not add_bytes(len(text)):
                break
            out["workspace_manifests"].append((rel, text))

    # --- Workflows ---
    if not out["hit_ceiling"]:
        wf_dir = repo_root / ".github" / "workflows"
        if _dir_beneath_exists(repo_root, wf_dir):
            try:
                candidates = [
                    p for p in (wf_dir / n for n in sorted(
                        _listdir_beneath(repo_root, wf_dir)))
                    if p.suffix in (".yml", ".yaml")
                    and _regular_file_beneath(repo_root, p)
                    and not _PROVISION_WORKFLOW_SKIP_RE.search(p.name)]
            except OSError:
                candidates = []
            # Prefer files whose names match ci/test/build/release.
            preferred = [p for p in candidates
                         if _PROVISION_WORKFLOW_PREFERRED_RE.search(p.name)]
            others = [p for p in candidates if p not in preferred]
            ordered = preferred + others
            for p in ordered[:2]:
                text = _read_file_safely(repo_root, p, 4096)
                if not add_bytes(len(text)):
                    break
                out["workflows"].append((p.name, text))

    # --- CONTRIBUTING / DEVELOPMENT ---
    if not out["hit_ceiling"]:
        for cand in (repo_root / "CONTRIBUTING.md",
                     repo_root / "docs" / "DEVELOPMENT.md",
                     repo_root / "DEVELOPMENT.md"):
            if _regular_file_beneath(repo_root, cand):
                text = _read_file_safely(repo_root, cand, 4096)
                if add_bytes(len(text)):
                    out["contributing"] = text
                break

    return out


# --- checkpoint validation ---------------------------------------------------

_CHECKPOINT_SECTIONS = [
    "## Frozen success criteria",
    "## Current status",
    "## Files touched",
    "## Decisions made",
    "## Evidence gate status",
    "## Next action",
    "## Open unknowns",
]

# Sections where "nothing to report" is a legitimate answer — a worker that
# made no decisions yet, or has no open unknowns, should be able to say so.
# Every other section must carry real content for the successor to pick up.
_CHECKPOINT_SECTIONS_ALLOW_NONE = {"## Decisions made", "## Open unknowns"}

# Single-token substitutes for content. A required section that contains
# only one of these is not a checkpoint, it's a placeholder — the
# successor would learn nothing from it. `_normalize_for_noise()` strips
# trailing punctuation and collapses repeated `?` before the membership
# check, so `None.`, `TBD!`, and `???` are caught alongside the bare
# tokens.
_NOISE_TOKENS = {
    "none", "n/a", "na", "tbd",
    "nothing", "unknown", "todo", "pending",
    "—", "--", "-", "?",
}


def _split_checkpoint_sections(content: str) -> dict[str, list[str]]:
    """Split a checkpoint file by `## ` headers into {header: lines}.
    Lines are stripped; blanks dropped. Returns one bucket per header
    found, in the order they appeared."""
    sections: dict[str, list[str]] = {}
    current: str | None = None
    for raw in content.splitlines():
        if raw.startswith("## "):
            current = raw.rstrip()
            sections.setdefault(current, [])
            continue
        if current is None:
            continue
        stripped = raw.strip()
        if stripped:
            sections[current].append(stripped)
    return sections


def _validate_checkpoint(path: str,
                        worktree_root: Path | None = None,
                        notes_dir: Path | None = None) -> str | None:
    """Return an error description if the checkpoint is structurally incomplete,
    None if it looks good. A missing section produces a confused successor;
    so does a section that contains only a placeholder.

    `worktree_root`, when supplied, enables the freshness check on
    `## Files touched`: every path listed there must either exist in the
    worktree or carry a `[deleted]` annotation in its bullet line. Skip the
    freshness check when the worktree is gone (e.g. cleaned up already).

    `notes_dir`: the subtask's own notes directory, where its checkpoint
    lives (`_checkpoint_path`). The path is the worker's to name, so it is
    read only beneath that directory and never through a link
    (`_read_beneath`; DESIGN §6 *Leerie never reads through a link a
    repository holds*) — a path elsewhere is not this subtask's checkpoint.
    None: the directory holding `path`."""
    p = Path(path)
    if not p.exists():
        return f"checkpoint file does not exist: {path}"
    try:
        content = _read_text_beneath(
            p.parent if notes_dir is None else Path(notes_dir), p,
            errors="strict", limit=READ_LIMIT_CONFIG)
    except (OSError, ValueError) as e:
        return (f"checkpoint {path} is not a readable regular file of at "
                f"most {READ_LIMIT_CONFIG} bytes in this subtask's notes "
                f"directory: {e}")

    missing = [s for s in _CHECKPOINT_SECTIONS if s not in content]
    if missing:
        return (f"missing {len(missing)} required section(s): "
                f"{', '.join(missing)}")

    sections = _split_checkpoint_sections(content)
    for header in _CHECKPOINT_SECTIONS:
        lines = sections.get(header, [])
        if not lines:
            return f"section '{header}' has no content"
        # Reject single-token noise placeholders in the sections that MUST
        # carry real handoff context. Allow them only in the two sections
        # where "nothing to report" is a legitimate answer.
        if header in _CHECKPOINT_SECTIONS_ALLOW_NONE:
            continue
        if all(_normalize_for_noise(l) in _NOISE_TOKENS for l in lines):
            return (f"section '{header}' contains only placeholder tokens "
                    f"({lines!r}) — successor cannot resume from this")

    # Freshness check: paths under `## Files touched` must still exist in
    # the worktree (or be explicitly marked [deleted]). A stale checkpoint
    # naming a file the successor cannot find produces wasted re-discovery.
    if worktree_root is not None and worktree_root.exists():
        for line in sections.get("## Files touched", []):
            path_str, is_deleted = _parse_touched_file_line(line)
            if path_str is None:
                continue  # not a path-shaped line; skip narration
            if is_deleted:
                continue
            if not (worktree_root / path_str).exists():
                return (f"`## Files touched` lists '{path_str}' but the file "
                        "does not exist in the worktree and is not flagged "
                        "[deleted] — checkpoint is stale")

    return None


def _normalize_for_noise(line: str) -> str:
    """Reduce a checkpoint line to its comparison key for `_NOISE_TOKENS`.
    Strips the bullet marker, lowercases, collapses a pure run of `?` to a
    single `?`, then peels off trailing `.`/`!`/`…` — so `None.`, `TBD!`,
    and `???` all match their bare-token forms. The `?`-collapse runs
    before the trailing-punctuation strip; otherwise `???` would be
    eaten down to the empty string and miss the `?` token entirely."""
    s = _strip_bullet(line).lower().strip()
    if s and set(s) == {"?"}:
        s = "?"
    while s and s[-1] in ".!…":
        s = s[:-1].rstrip()
    return s


def _strip_bullet(line: str) -> str:
    """Strip leading markdown bullet markers (`-`, `*`, `1.`) before noise
    comparison. `- none` should be rejected the same as bare `none`."""
    stripped = line.lstrip()
    for prefix in ("- ", "* ", "+ "):
        if stripped.startswith(prefix):
            return stripped[len(prefix):].strip()
    # numbered list: `1. `, `2. `, …
    if len(stripped) >= 3 and stripped[0].isdigit():
        i = 1
        while i < len(stripped) and stripped[i].isdigit():
            i += 1
        if stripped[i:i+2] == ". ":
            return stripped[i+2:].strip()
    return stripped


def _parse_touched_file_line(line: str) -> tuple[str | None, bool]:
    """Extract a file path from a `## Files touched` line and detect the
    `[deleted]` annotation. Returns (path, is_deleted) or (None, False)
    if the line doesn't look like a path entry. Conservative: only treats
    a line as path-shaped if its first whitespace-delimited token looks
    like a relative path (contains `/`, `.`, or ends with a common code
    extension). Narration lines without a path token are skipped."""
    body = _strip_bullet(line)
    if not body:
        return (None, False)
    is_deleted = "[deleted]" in body.lower()
    # The first token is the candidate path; strip backticks and trailing
    # punctuation that often surrounds paths in markdown.
    first = body.split()[0].strip("`,:;()[]")
    if not first or first.startswith("#"):
        return (None, False)
    # A truthful "None." sentinel carries a trailing sentence period that
    # would otherwise survive the strip set above and read as path-shaped
    # (it contains a "."). Check the sentinel set against the token with
    # a bare trailing period removed, without adding "." to the general
    # strip set — that breaks './x', '../x', and '.github/...' parsing.
    sentinel_candidate = first[:-1] if first.endswith(".") and not first.endswith("..") else first
    if sentinel_candidate.lower() in {"none", "n/a", "na", "-", "nothing"}:
        return (None, False)
    # Only treat as a path if it has a separator or a dot — a bare word
    # like "refactored" is narration, not a path.
    if "/" in first or "." in first:
        return (first, is_deleted)
    return (None, False)


# Tool-call wire syntax a model can leak into a structured-output string
# field (DESIGN §7 *Forcing constrained decoding*, §12 *Language-to-JSON*:
# protocol tokens are mechanical strings, not prose). A closing tag named
# after one of the worker's own schema properties is matched too — that is
# how the observed leak reads (`…</defect_shape><parameter name="sites">`).
_PROTOCOL_MARKUP_TOKENS = (
    "antml:", '<parameter name="', "</parameter>", '<invoke name="',
    "</invoke>",
)
# Quoted code — fenced blocks and inline backtick spans — is something the
# worker is quoting (a repo that is itself about this protocol, an HTML
# snippet in a PR body), not leaked syntax; the one legitimate hit in a
# 120-sample corpus audit was exactly that shape.
_QUOTED_CODE_SPAN_RE = re.compile(
    r"^[ \t]*```[^\n]*\n.*?^[ \t]*```|`[^`\n]*`", re.S | re.M)


def _schema_property_names(schema: object) -> frozenset[str]:
    """Every property name declared anywhere in a JSON schema."""
    names: set[str] = set()
    stack = [schema]
    while stack:
        node = stack.pop()
        if isinstance(node, dict):
            props = node.get("properties")
            if isinstance(props, dict):
                names.update(props)
            stack.extend(node.values())
        elif isinstance(node, list):
            stack.extend(node)
    return frozenset(names)


def _closing_tag_leak(text: str, prop_names: frozenset[str]) -> bool:
    """A closing tag named after one of the worker's own schema properties
    counts only where leaked tool-call syntax sits: at the end of the value,
    or directly before another parameter/invoke tag or another of the
    schema's own tags. A schema property that is also an ordinary markup
    name (`summary`, `title`, `name`) inside running text is not a leak
    (one that ends the value still is) — measured 2026-10-04, it dropped
    none of the 2,395 hits in 26,673 recorded responses."""
    for p in prop_names:
        start = 0
        tag = f"</{p}>"
        while (i := text.find(tag, start)) != -1:
            rest = text[i + len(tag):].lstrip()
            if (not rest or rest.startswith(("<parameter", "<invoke"))
                    or any(rest.startswith((f"</{q}>", f"<{q}"))
                           for q in prop_names)):
                return True
            start = i + len(tag)
    return False


def _find_protocol_markup(value: object,
                          prop_names: frozenset[str] = frozenset()
                          ) -> str | None:
    """Recursively scan a JSON-shaped value for a string carrying leaked
    tool-call markup. Returns the offending string on the first hit, None
    if clean. Structured recursion (dict/list), not a top-level-only check
    — the corruption lands in arbitrary nested fields (e.g. inside
    `clarification_question`)."""
    if isinstance(value, str):
        bare = _QUOTED_CODE_SPAN_RE.sub("", value)
        if any(t in bare for t in _PROTOCOL_MARKUP_TOKENS):
            return value
        if "</" in bare and _closing_tag_leak(bare, prop_names):
            return value
        return None
    if isinstance(value, dict):
        for v in value.values():
            hit = _find_protocol_markup(v, prop_names)
            if hit is not None:
                return hit
        return None
    if isinstance(value, list):
        for v in value:
            hit = _find_protocol_markup(v, prop_names)
            if hit is not None:
                return hit
        return None
    return None


# --- result cross-field validation -------------------------------------------

def _validate_result(result: dict) -> tuple[str, str] | None:
    """Cross-field invariant checks that JSON Schema cannot express.
    Returns `(failure_kind, message)` if the result is self-contradictory,
    None if ok. `failure_kind` is the structured discriminator
    `_retryable_failure` dispatches on; `message` is the human-readable
    diagnostic surfaced to the user.

    Per DESIGN §8, the §8 confidence gate is the only load-bearing
    discipline; the criteria file is informational (DESIGN §9). A
    `complete` status is accepted regardless of what `criteria_results`
    carries — empty, missing, or with `met:false` entries are all
    valid. The unmet entries are recorded on the result for telemetry
    and surface as conformance warnings, but do not affect terminal
    status. The other branches (handoff, blocked, failed, clarification)
    still enforce the mechanical-precondition fields their next-step
    consumers require.

    Checked before anything else: literal `antml:`-shaped markup inside
    any string field value. Upstream anthropics/claude-code#64690 is a
    model-side token-generation bug that can leak tool-call markup
    (`antml:parameter`, `antml:invoke`, …) into a structured-output
    field's own string value. No legitimate worker output contains this
    substring, so its presence is an unambiguous corruption signal — the
    underlying work may well have succeeded, so this is retryable rather
    than the terminal `"broken"` the status dispatch below would
    otherwise assign it via a coincidentally-matching shape (e.g. a
    corrupted `checkpoint_path`)."""
    if _find_protocol_markup(
            result, _schema_property_names(SCHEMAS["implementer"])) is not None:
        return ("corrupted_envelope",
                "result contains leaked tool-call markup in a string field "
                "— upstream anthropics/claude-code#64690 token-generation "
                "corruption")
    status = result.get("status")
    if status == "incomplete-handoff":
        cp = result.get("checkpoint_path")
        if not cp:
            return ("broken",
                    "status='incomplete-handoff' but checkpoint_path is null")
        if not Path(cp).exists():
            # "empty_handoff" — the Claude Code session-limit / rate-limit no-op
            # case and the --max-turns-with-no-checkpoint case both land here.
            # Both are corrective-note retryable: a fresh worker can plausibly
            # do better. See _RETRYABLE_FAILURE_KINDS.
            return ("empty_handoff",
                    f"checkpoint_path '{cp}' does not exist on disk")
    elif status == "blocked":
        if not (result.get("blocker") or "").strip():
            return ("broken", "status='blocked' but blocker field is empty")
    elif status == "failed":
        # A `failed` result without a summary is a worker contract violation:
        # the prompt requires a diagnosis. Without it, the user sees a canned
        # placeholder rather than a real explanation of what went wrong.
        if not (result.get("summary") or "").strip():
            return ("broken",
                    "status='failed' but summary is empty — no diagnosis provided")
    elif status == "needs-clarification":
        # DESIGN §11 mid-execution clarification: the question and the
        # work-in-progress checkpoint MUST both be present. The question
        # is what gets surfaced to the user; the checkpoint is what
        # carries the partial work forward to the re-spawned implementer.
        # The why_underivable field inside the question is required by
        # the schema and re-checked here as a content (not just shape)
        # gate against the worker drifting toward "ask instead of
        # research."
        cq = result.get("clarification_question")
        if not cq:
            return ("broken",
                    "status='needs-clarification' but clarification_question "
                    "is null — see DESIGN §11")
        for field in ("id", "question", "why_underivable"):
            if not (cq.get(field) or "").strip():
                return ("broken",
                        f"status='needs-clarification' but "
                        f"clarification_question.{field} is empty — "
                        "see DESIGN §11")
        cp = result.get("checkpoint_path")
        if not cp:
            return ("broken",
                    "status='needs-clarification' but checkpoint_path is "
                    "null — the work-in-progress must survive the question")
        if not Path(cp).exists():
            return ("broken",
                    f"status='needs-clarification' but checkpoint_path "
                    f"'{cp}' does not exist on disk")
    return None


# --- post-implementation diff scope check ------------------------------------

async def check_diff_scope(sid: str, worktree: str, subtask: dict,
                           st: State) -> str | None:
    """Check the implementer's diff for violations.
    Returns a fatal error string if protected paths were touched.
    Logs a non-fatal warning for unexpected scope. Returns None when clean.

    The diff is computed against the run branch (`leerie/runs/<run-id>`)
    — the base every subtask branched off of. Hardcoding `leerie/staging`
    here used to silently disable the check after the per-run refactor
    (the branch doesn't exist), so the protected-path enforcement was off."""
    run_branch = await _branch_commit_for_tree_async(
        worktree, _compute_run_branch(st.run_id))
    # NUL-separated: git quotes a name holding a byte outside ASCII, and the
    # quoted form matched no protected prefix (DESIGN §6 *A path is the file
    # it names, not its spelling*).
    r = await run_proc(
        ["git", *_tree_git_args(worktree), "diff", "--name-only", "-z",
         f"{run_branch}..HEAD"],
        cwd=worktree,
    )
    if r.returncode != 0:
        return None
    touched = [f for f in r.stdout.split("\0") if f]
    if not touched:
        return None

    # fatal: any changes to protected meta-directories are out of bounds.
    # `.claude/{agents,commands,skills}/` are exempt (documented Claude
    # Code user-deliverable locations); top-level `.claude/` files
    # (settings.json, settings.local.json) stay protected. See
    # _is_protected_path() for the rule.
    protected = [f for f in touched if _is_protected_path(f)]
    if protected:
        return (f"{sid}: diff touches protected path(s): {protected} — "
                "implementers must not modify meta-directories")

    # fatal: a second spelling of a path or directory the tree already had
    # (DESIGN §6 *A path is the file it names, not its spelling*, part 3).
    # A pair both of whose spellings the run branch already had is not this
    # subtask's; when git cannot list the run branch the check is skipped,
    # like the diff above.
    base = await run_proc(
        ["git", *_tree_git_args(worktree), "ls-tree", "-r", "-z",
         "--name-only", run_branch], cwd=worktree)
    if base.returncode == 0:
        ours = await run_proc(
            ["git", *_tree_git_args(worktree), "ls-tree", "-r", "-z",
             "--name-only", "HEAD"], cwd=worktree)
        head = {f for f in ours.stdout.split("\0") if f} \
            if ours.returncode == 0 else set()
        collisions = _fold_collisions(
            [f for f in touched if f in head], head,
            before=[f for f in base.stdout.split("\0") if f])
        if collisions:
            return (f"{sid}: diff adds a second spelling of a path in the "
                    f"tree: {collisions} — on a case- or normalization-"
                    "insensitive filesystem each pair is one file")

    # non-fatal: log a warning for radically unexpected scope
    expected = subtask.get("files_likely_touched", [])
    over_ratio = bool(expected) and len(touched) > max(len(expected) * 3, 5)
    over_volume = len(touched) > 15
    if over_ratio or over_volume:
        reason = f"touched {len(touched)} files, expected ~{len(expected)}"
        log(f"  ⚠  scope warning {sid}: {reason}")
        st.data.setdefault("scope_warnings", {})[sid] = {
            "touched": touched, "expected": expected, "reason": reason,
        }
        st.save()

    # non-fatal: the INVERSE direction. The over-scope warning above has
    # always had `touched` in hand; only "committed real work, but none of it
    # to any file it said it would touch" was missing. Measured across the
    # 0.28.0 corpus: 5 of 131 completed subtasks landed none of their declared
    # files, three of them independently redone by a later run. Run
    # `c1f45fd0`'s `feat-005` reported `complete` and self-checked "[x] Router
    # mounted as app.use('/api/parcel', parcelRouter) in server/index.ts"
    # while `server/routes/parcel.ts` did not exist anywhere in the tree; a
    # later run created it from scratch.
    #
    # ADVISORY, and that is deliberate. `files_likely_touched` is a planner
    # ESTIMATE, not a contract: a subtask may satisfy its criteria in a file
    # nobody predicted, or legitimately no-op because a sibling landed the
    # deliverable first. Gating on it would resurrect exactly the bar DESIGN
    # §9 retired. What makes it worth checking anyway is that it reads no
    # prose — it is set logic over already-structured planner fields, so it
    # is not gameable the way per-criterion satisfaction was: a worker cannot
    # weaken a test to make a declared path appear in a diff.
    # `or []`, matching every other reader of this field: `.get(k, [])`
    # returns None when the key is present and null, which the over-scope
    # check above survives only because `bool(None)` short-circuits it.
    declared = [f for f in (expected or [])
                if isinstance(f, str) and f.strip()]
    if declared and not any(_declared_path_covers(d, t)
                            for d in declared for t in touched):
        reason = (f"touched {len(touched)} file(s), none of the "
                  f"{len(declared)} declared in files_likely_touched")
        log(f"  ⚠  under-scope warning {sid}: {reason}")
        st.data.setdefault("under_scope_warnings", {})[sid] = {
            "touched": touched, "declared": declared, "reason": reason,
        }
        st.save()

    return None


# --- post-integrator commit check --------------------------------------------

async def check_merge_committed(staging: Path) -> str | None:
    """Return an error if the staging worktree is still mid-merge.

    An integrator that returns status 'resolved' must have completed the merge
    commit. If `MERGE_HEAD` still exists, the merge was never concluded — the
    worker claimed success while leaving the worktree in a broken mid-merge
    state. This is the integrator-side analogue of `check_branch_has_commits`:
    it catches a worker lying about having finished."""
    r = await run_proc(
        ["git", *_tree_git_args(staging), "rev-parse", "--verify", "--quiet", "MERGE_HEAD"],
        cwd=str(staging),
    )
    if r.returncode == 0:
        return ("the staging worktree is still mid-merge (MERGE_HEAD exists) — "
                "the integrator did not complete the merge commit")
    # also reject a worktree left with staged-but-uncommitted conflict edits
    s = await run_proc(
        ["git", *_tree_git_args(staging), "diff", "--cached", "--name-only"],
        cwd=str(staging),
    )
    if s.returncode == 0 and s.stdout.strip():
        return ("the staging worktree has staged but uncommitted changes — "
                "the integrator did not complete the merge commit")
    return None


async def check_integrator_commit(staging: Path) -> str | None:
    """Return an error if the integrator's merge commit touched .leerie/ files.
    The integrator should only touch project files, never coordination artifacts."""
    r = await run_proc(
        ["git", *_tree_git_args(staging), "show", "--name-only", "-z",
         "--format=", "HEAD"],
        cwd=str(staging),
    )
    if r.returncode != 0:
        return None
    bad = [f for f in r.stdout.strip("\n").split("\0")
           if f and (_path_fold(f) + "/").startswith(".leerie/")]
    if bad:
        return f"integrator commit touched coordination files: {bad}"
    return None


async def _rebase_state_dirs(worktree: Path) -> list[str] | None:
    """Names of git's in-progress-rebase dirs present for `worktree`, or
    `None` when git cannot say. Resolved via `git rev-parse --git-path`
    because in a `git worktree add` checkout `.git` is a file and the rebase
    state lives under `<common-dir>/worktrees/<name>/`, not
    `<worktree>/.git/`."""
    present = []
    for name in ("rebase-merge", "rebase-apply"):
        r = await run_proc(["git", *_tree_git_args(worktree), "rev-parse", "--git-path", name],
                           cwd="/")
        if r.returncode != 0:
            return None
        if (worktree / r.stdout.strip()).exists():
            present.append(name)
    return present


def _is_conflict_marker(line: str, size: int) -> bool:
    """git's `is_conflict_marker` (diff.c): `size` copies of one of `<=>|`,
    then whitespace or end of line."""
    return (len(line) >= size and line[0] in "<=>|"
            and line[:size] == line[0] * size
            and (len(line) == size or line[size] in " \t\r\n"))


async def _conflict_marker_size(worktree: Path, path: str) -> int:
    r = await run_proc(
        ["git", *_tree_git_args(worktree), "--literal-pathspecs", "check-attr", "-z",
         "conflict-marker-size", "--", path],
        cwd="/")
    fields = r.stdout.split("\0") if r.returncode == 0 else []
    value = fields[2] if len(fields) > 2 else ""
    return int(value) if value.isdigit() and int(value) > 0 else 7


async def _introduced_conflict_markers(
        worktree: Path, since: str) -> set[tuple[str, int]] | None:
    """`(path, line)` of every conflict marker in `worktree`'s working tree
    on a line absent from `since`, or `None` when git cannot diff against
    `since`.

    `git diff --check` applies git's own marker rule (including diff3's
    `|||||||` and the `conflict-marker-size` attribute) but skips every path
    diff treats as binary — and a `-diff` attribute, the usual lockfile
    setting, makes a text file binary to diff while merge still writes
    markers into it. Those paths (`-\t-\t` in `--numstat`) are diffed again
    with `--text` and the same rule applied here, except real binaries (a NUL
    in the first 8000 bytes, merge's own test), which merge never writes
    markers into."""
    check = await run_proc(
        ["git", *_tree_git_args(worktree), "-c", "core.quotePath=off", "diff", "--no-color",
         "--no-renames", "--check", since, "--"],
        cwd="/")
    # 0 clean, 2 markers or whitespace errors; anything else is git failing
    if check.returncode not in (0, 2):
        return None
    found = {(m.group(1), int(m.group(2))) for m in re.finditer(
        r"^(.+):(\d+): leftover conflict marker$", check.stdout,
        re.MULTILINE)}

    numstat = await run_proc(
        ["git", *_tree_git_args(worktree), "diff", "--numstat", "-z", "--no-renames", since, "--"],
        cwd="/")
    if numstat.returncode != 0:
        return None
    unchecked = [entry[4:] for entry in numstat.stdout.split("\0")
                 if entry.startswith("-\t-\t")]
    for path in unchecked:
        try:
            if b"\0" in _read_head_beneath(worktree, worktree / path,
                                            limit=8000):
                continue
        except OSError:  # deleted by the rebase, or a link
            continue
        size = await _conflict_marker_size(worktree, path)
        diff = await run_proc(
            ["git", *_tree_git_args(worktree), "--literal-pathspecs", "diff", "--text", "--no-textconv",
             "--no-ext-diff", "--no-color", "--no-renames", "-U0", since,
             "--", path],
            cwd="/")
        if diff.returncode != 0:
            return None
        lineno = None
        for line in diff.stdout.split("\n"):
            hunk = re.match(r"^@@ -\S+ \+(\d+)", line)
            if hunk:
                lineno = int(hunk.group(1))
            elif lineno is not None and line.startswith("+"):
                if _is_conflict_marker(line[1:], size):
                    found.add((path, lineno))
                lineno += 1
    return found


async def check_rebaser_worktree_state(
        worktree: Path, status: str, pre_rebase_sha: str,
        base_ref: str | None = None) -> str | None:
    """Mechanically verify the `rebaser` worker's claimed outcome (DESIGN §6
    *Finalization* "Rebase-onto-base before push"). Returns an error string
    on a mismatch, `None` if the claim checks out.

    Per §12 ("the orchestrator does not trust an integrator's 'resolved'
    claim; it confirms the merge was actually completed"), applied to
    rebaser: a "rebased" claim requires a not-mid-rebase tree carrying no
    conflict marker that the rebase itself produced; an
    "irreconcilable"/"failed" claim requires the worktree's tip to be
    byte-identical to its pre-rebase sha (the abort must have actually
    happened, restoring the original state). This does not re-judge whether
    the *resolution itself* was semantically correct — only that the claimed
    git-level outcome is real, mirroring `check_integrator_commit`'s
    state-not-content discipline above. Anything git cannot answer is a
    mismatch, never a pass."""
    if status == "rebased":
        # A marker the rebase produced is on neither side it combined: absent
        # from the pre-rebase tip and from the base it replayed onto. A
        # marker-shaped line either side already carries (a `=====…` divider,
        # a setext heading) is content. A missing or stale `base_ref` only
        # drops that second filter, leaving the stricter pre-tip scan.
        markers = await _introduced_conflict_markers(worktree, pre_rebase_sha)
        if markers is None:
            return ("could not scan for conflict markers after rebaser "
                    "claimed 'rebased'")
        if markers and base_ref:
            off_base = await _introduced_conflict_markers(worktree, base_ref)
            if off_base is not None:
                markers &= off_base
        if markers:
            return (f"rebaser claimed 'rebased' but conflict markers remain "
                    f"in: {sorted({path for path, _ in markers})}")
        in_progress = await _rebase_state_dirs(worktree)
        if in_progress is None:
            return ("could not verify the worktree is not mid-rebase after "
                    "rebaser claimed 'rebased'")
        if in_progress:
            return (f"rebaser claimed 'rebased' but worktree is still "
                    f"mid-rebase ({in_progress[0]} present)")
        return None

    # irreconcilable / failed: the worktree must be back to its pre-rebase
    # tip — nothing left mid-rebase, nothing partially applied.
    in_progress = await _rebase_state_dirs(worktree)
    if in_progress is None:
        return (f"could not verify the worktree is not mid-rebase after "
                f"rebaser claimed {status!r}")
    if in_progress:
        return (f"rebaser claimed {status!r} but worktree is still "
                f"mid-rebase ({in_progress[0]} present) — abort did not "
                f"complete")
    r = await run_proc(["git", *_tree_git_args(worktree), "rev-parse", "HEAD"], cwd="/")
    if r.returncode != 0:
        return f"could not verify worktree HEAD after rebaser claimed {status!r}"
    current_sha = r.stdout.strip()
    if current_sha != pre_rebase_sha:
        return (f"rebaser claimed {status!r} but worktree HEAD "
                f"({current_sha}) differs from its pre-rebase sha "
                f"({pre_rebase_sha}) — abort did not restore original state")
    return None


# --- branch-has-commits verification -----------------------------------------

async def _branch_has_commits_ahead(worktree: str,
                                   parent_branch: str) -> bool:
    """True iff the subtask branch has ≥1 commit ahead of `parent_branch`.

    Positive-polarity, unambiguous: returns True ONLY when the worktree
    exists, `git log parent..HEAD` succeeds, AND its output is non-empty.
    A missing worktree or a failed git command returns False — "can't
    prove commits exist" is treated as "no commits," so no caller mistakes
    an indeterminate state for real committed work. `check_branch_has_commits`
    (the no-op gate) and the `empty_handoff` rescue in `_settle_subtask` both
    key on this: the rescue keeps committed work only when it can *prove* the
    commit exists, never on a bare `None`/indeterminate result."""
    if not Path(worktree).exists():
        return False  # worktree gone — can't determine, treat as no commits
    base = await _branch_commit_for_tree_async(worktree, parent_branch)
    try:
        r = await run_proc(
            ["git", *_tree_git_args(worktree), "log", f"{base}..HEAD", "--oneline"],
            cwd=worktree,
        )
    except OSError:
        return False
    if r.returncode != 0:
        return False
    return bool(r.stdout.strip())


async def check_branch_has_commits(sid: str, worktree: str,
                                   parent_branch: str
                                   ) -> tuple[str, str] | None:
    """Return `(failure_kind, message)` if the implementer's subtask
    branch has no commits ahead of the run branch (`parent_branch` —
    typically `leerie/runs/<run-id>`), else None. An empty diff means the
    worker produced schema-valid JSON claiming success while doing
    nothing — a silent no-op that wastes an integration attempt. The
    `"no_commits"` kind is retryable per `_RETRYABLE_FAILURE_KINDS`.

    Note the deliberate asymmetry with `_branch_has_commits_ahead`: an
    indeterminate state (worktree gone / git failed) returns None here —
    "don't block" — because this is a *gate* on a `complete` claim, where
    the safe default is to let it through rather than fail a subtask on an
    unverifiable git error. The rescue path uses `_branch_has_commits_ahead`
    instead, whose safe default is the opposite (don't rescue unless proven)."""
    if not Path(worktree).exists():
        return None  # worktree gone — can't determine, don't block
    base = await _branch_commit_for_tree_async(worktree, parent_branch)
    try:
        r = await run_proc(
            ["git", *_tree_git_args(worktree), "log", f"{base}..HEAD", "--oneline"],
            cwd=worktree,
        )
    except OSError:
        return None
    if r.returncode != 0:
        return None
    if not r.stdout.strip():
        return ("no_commits",
                f"subtask branch for {sid} has no commits ahead of the run "
                f"branch ({parent_branch}) — implementer claimed complete "
                "without making any changes")
    return None


# --- conflict marker scan post-integration -----------------------------------

async def _scan_conflict_markers(staging: Path) -> str | None:
    """Return error if unresolved conflict markers remain in the staging tree.
    git grep exit 0 = matches found (bad); exit 1 = clean (good)."""
    if not staging.exists():
        return None
    try:
        r = await run_proc(
            ["git", *_tree_git_args(staging), "grep", "-l", "^<<<<<<< ", "HEAD"],
            cwd=str(staging),
        )
    except OSError:
        return None
    if r.returncode == 0:
        files = [f for f in r.stdout.strip().splitlines() if f]
        sample = files[:5]
        tail = "…" if len(files) > 5 else ""
        return (f"conflict markers in {len(files)} file(s) after integration: "
                f"{sample}{tail}")
    return None


# --- resume state integrity check --------------------------------------------

def _validate_resume_state(data: dict) -> None:
    """Assert the structure of a loaded state.json before resuming. A corrupt
    or hand-edited file produces wrong behavior; fail fast rather than run
    silently. Only `task` is strictly required here — it is the one input a
    resume needs (DESIGN §6 *The first phase is a phase like any other*): a
    run interrupted before scheduling has no `waves` yet, and one interrupted
    inside classification no `categories` either, and both re-enter at their
    first unpersisted phase."""
    if "task" not in data or not str(data.get("task", "")).strip():
        die("state.json has no usable 'task' — cannot resume. "
            "Inspect the run's state.json manually "
            "(under <state-root>/runs/<run-id>/).")

    # waves is optional (absent if interrupted before scheduling); if present
    # it must be well-formed, and completed_waves must be in range.
    if "waves" in data:
        waves = data["waves"]
        if not isinstance(waves, list) or not all(isinstance(w, list)
                                                  for w in waves):
            die("state.json: 'waves' must be a list of lists")
        completed = data.get("completed_waves", 0)
        if not isinstance(completed, int) or not (0 <= completed <= len(waves)):
            die(f"state.json: 'completed_waves' ({completed!r}) is out of range "
                f"(expected 0..{len(waves)})")

    # subtask_status, if present, must be a dict
    if "subtask_status" in data and not isinstance(data["subtask_status"], dict):
        die("state.json: 'subtask_status' must be an object")


# =========================================================================
# the single point where LLM work happens: a `claude -p` invocation
# =========================================================================
class WorkerError(RuntimeError):
    pass


def _save_state_best_effort(st: "State", where: str) -> None:
    """Persist run state from inside an exception handler, never raising.

    Every terminating arm in `main()` opens by saving so the run stays
    resumable — and an unguarded `st.save()` there is a trap, because a raise
    from inside an `except` block is caught by no sibling arm of the same
    `try`. It escapes `main()` entirely, skipping the cleanup, the dep
    capture, and the `exit_code` assignment: a resumable pause becomes an
    exit-1 traceback. In the catch-all `except BaseException` arm it is worse
    still — the new exception REPLACES the unhandled one, leaving the real
    bug reachable only as `__context__`, which nothing prints.

    Both failure modes are real, not theoretical. `State.save()` converts an
    out-of-space errno to `DiskLowSpace`, so on a full disk it re-raises
    exactly where these arms fire; and on a read-only run dir it raises
    `PermissionError` (measured), which no conversion touches.

    The failure is logged rather than swallowed: the previous on-disk
    `state.json` is still the last good one, so the run stays resumable, but
    an operator who is about to be told "resume when you have freed space"
    deserves to know the pause itself could not be recorded.

    The caught set is this file's existing "everything that is not a real
    interrupt" tuple, used at ten other sites — NOT a bare `BaseException`.
    `except Exception` alone would not do, because `DiskLowSpace` and its
    siblings deliberately subclass `BaseException` to survive broad handlers.
    But `KeyboardInterrupt` must still propagate: in `main()`'s own
    `except KeyboardInterrupt` arm a second Ctrl-C during this save would
    otherwise be absorbed, and the handler would carry on into cleanup and a
    fresh `asyncio.run(capture_repo_deps(...))` — the long operation the
    operator was trying to escape. Protecting a best-effort write at the cost
    of an interrupt inverts the priority.
    """
    try:
        st.save()
    except (Exception, TerminalAuthFailure, RateLimitedExit,
            ContextOverflow, DiskLowSpace) as exc:
        log(f"warning: could not persist state at {where} "
            f"({type(exc).__name__}: {exc}); the last saved state.json "
            "stands and `leerie resume` still works from it")


def _capture_failure_note(exc: BaseException) -> str:
    """How a best-effort dependency capture's failure is logged. A refusal
    of the confinement shim is named as one: the capture is the one
    confined step that never stops a run (DESIGN §6½), and a refused one
    recorded nothing, so a later `leerie config --recapture` still
    captures it (DESIGN §6 *A confinement failure stops the run; it is
    never a result*)."""
    if isinstance(exc, ConfinementRefused):
        return "not run — the confinement shim refused it, nothing recorded,"
    return "non-fatal error"


async def _best_effort_capture_deps(
        repo_root: Path,
        st: "State",
        caps: dict | None,
        models: dict[str, str] | None,
        efforts: dict[str, str | None] | None,
        context_label: str,
) -> None:
    """Run dep_capture best-effort from a `main()` terminal exception arm.

    Every terminating arm in `main()` attempts `capture_repo_deps` on its way
    out (DESIGN §6½) and must swallow the same exception family:
    `TerminalAuthFailure` / `RateLimitedExit` / `ContextOverflow` /
    `DiskLowSpace` deliberately subclass `BaseException`, so a bare `except
    Exception` would let a re-raise (e.g. the auth-locked arm is *guaranteed*
    to re-hit its own TerminalAuthFailure inside `capture_repo_deps ->
    claude_p`) escape `main()` entirely, skipping the `exit_code` assignment
    and crashing a resumable pause with exit 1. `KeyboardInterrupt` is IN the
    tuple for the same reason: a terminal arm exists to record a disposition,
    so a second Ctrl-C during this best-effort capture must not escape and
    skip the exit_code/cleanup that arm was reached to set
    (tests/test_irreversible_before_valid.py).

    `context_label` is interpolated into the non-fatal log line only — it
    names which pause this capture attempt belongs to (e.g. "disk-low
    pause", "cancel-arm capture").
    """
    try:
        await capture_repo_deps(
            repo_root, st,
            caps=caps, models=models, efforts=efforts,
            record_in=st.run_dir,
        )
    except (Exception, KeyboardInterrupt, TerminalAuthFailure,
            RateLimitedExit, ContextOverflow, DiskLowSpace,
            ConfinementRefused) as _cap_exc:
        log(f"capture: {_capture_failure_note(_cap_exc)} during "
            f"{context_label} ({_cap_exc})")


def _brief_worker_exc(exc: BaseException) -> str:
    """Render a worker-spawn failure for a log line, WITHOUT the argv.

    `str(subprocess.TimeoutExpired)` interpolates `cmd` — for leerie that is
    the entire `claude -p` command line, which on the inline-system-prompt
    path carries a whole system prompt. `_run_implementer`'s own handler
    documents the result as a 50 KB traceback dumped to the operator's
    terminal, and avoids it by never binding the exception at all.

    Every site that catches TimeoutExpired alongside WorkerError and wants to
    say something about it goes through here instead. `exc.timeout` is the
    ceiling that actually applied, so the message stays specific without the
    payload.
    """
    if isinstance(exc, subprocess.TimeoutExpired):
        return f"killed at its {exc.timeout}s wall-clock ceiling"
    return str(exc)


class DecompositionBudgetExceeded(WorkerError):
    """Recursive decomposition (fit_judge/splitter) has spent its share of
    the worker budget (N3+N4, DEFAULT_CAPS["decompose_budget_share"]).

    Subclasses WorkerError for classification only. **The base is inert on
    every shipped path**: each of the three spawn sites in
    `_recursive_decompose` wraps its `_bump_decompose_workers` call in its
    own `try/except DecompositionBudgetExceeded` that closes before the
    `claude_p` call, so the generic `except WorkerError:` barriers below
    them can never see this type. An earlier revision of this docstring
    claimed the opposite -- that the base "already degrades the node to a
    leaf without any new control-flow" -- which was never true of the code
    as written, and is worth stating plainly because it is a live trap: a
    future refactor that let this propagate would have it silently
    classified as a worker crash by `_retryable_failure`.
    """


class WorktreeSetupError(WorkerError):
    """`new-worktree.sh` could not produce the subtask's worktree.

    A distinct type because the retry classifier dispatches on a kind tagged
    at the PRODUCER, never on prose (see `_RETRYABLE_FAILURE_KINDS`). Raised
    before any worker runs, so it is infrastructure, not a broken or
    dishonest worker — the distinction `_retryable_failure` turns on.
    """


class PidExhaustedError(WorkerError):
    """The worker's cgroup exhausted its PID table (fork denials climbing or
    `pids.current` at `pids.max`) — every shell-spawning tool call then fails
    with EAGAIN.

    A distinct type because the retry classifier dispatches on a kind tagged
    at the PRODUCER, never on prose (see `_RETRYABLE_FAILURE_KINDS`). The
    worker did not misbehave in a way a corrective note can address — a
    fresh worker gets a clean PID table, which is exactly the remedy.
    """


class OomKilledError(WorkerError):
    """The worker's tool subtree (a build/test command) overshot
    `memory.max` and was killed by the kernel mid-turn.

    A distinct type because the retry classifier dispatches on a kind tagged
    at the PRODUCER, never on prose (see `_RETRYABLE_FAILURE_KINDS`). Not a
    broken or dishonest worker — a resource limit killed it — so a
    corrective note has nothing to correct; a fresh attempt is the remedy.
    """


def _api_error_category(status: int | None) -> str | None:
    """Map a `claude -p` `api_error_status` to a coarse failure category.

    401→auth (subscription / credential rejection), 429→quota (rate limit),
    529→overload (transient gateway). None for any other or absent status.
    `api_error_status` on the result envelope is always a JSON number or null
    (SDK type `api_error_status?: number | null`), so this numeric set is
    exhaustive — no string forms ever reach here.

    Single source of truth for the status→category mapping, shared by
    `_is_auth_or_quota_failure` (which needs the bool) and
    `_classify_failure_kind` (which needs the category string)."""
    return {401: "auth", 429: "quota", 529: "overload"}.get(status)


def _is_context_overflow(envelope: dict) -> bool:
    """True when Claude Code refused the prompt itself as too long.

    The CLI enforces a context ceiling client-side: it emits a synthetic
    assistant message (`model=<synthetic>`, usage all zeros) and ends the
    session with no API call. Retrying identical input is therefore
    guaranteed to fail the same way, which is why claude_p() raises
    `ContextOverflow` on a match instead of spending its 2-attempt loop.

    Measured envelope (reproduced twice, arms B and C of the 2026-08-06
    probe): `is_error: true`, `terminal_reason: "blocking_limit"`,
    `api_error_status: null`, `result: "Prompt is too long"`, and —
    misleadingly — `subtype: "success"`, so do NOT key on subtype, the
    same trap `_is_transient_transport_failure` documents.

    BOTH signals are required. `terminal_reason` alone is insufficient:
    it is shared with other blocking limits, and the sibling arms of the
    same probe ended `max_turns` while a healthy run ended `completed`.
    The text alone is insufficient too — a worker could legitimately
    discuss the phrase in its own output — so, mirroring
    `_is_terminal_auth_failure`, this is gated on `is_error` (a
    successful, schema-valid envelope never matches) and exempts
    `_leerie_synthetic` envelopes, whose `result` interpolates the
    worker's raw stderr and could carry the phrase without the CLI having
    refused anything."""
    if not envelope.get("is_error"):
        return False
    if envelope.get("_leerie_synthetic"):
        return False
    if envelope.get("terminal_reason") != "blocking_limit":
        return False
    return "prompt is too long" in str(envelope.get("result") or "").lower()


def _is_terminal_auth_failure(envelope: dict) -> bool:
    """True when auth cannot recover without a human running `claude
    /login` (or a fresh `CLAUDE_CODE_OAUTH_TOKEN`).

    Distinct from the 401/429 rolling-cap case `_is_auth_or_quota_failure`
    covers: Claude Code sends no request at all in this state (it already
    failed to renew the login and cleared the credential), so routing it
    through that classifier's backoff loop burns the whole
    `auth_retry_max_sec` budget and still fails identically every time.
    claude_p() must check this classifier BEFORE
    `_is_auth_or_quota_failure` so the terminal case is caught first.

    Measured over 611 historical is_error envelopes: these markers match
    215 true positives, 0 false positives. Worker prose cannot reach
    `result` on a successful envelope — only the `_leerie_synthetic`
    stderr path can, and it is exempted below; max observed is_error
    result length is 162 chars.

    Do NOT shorten "oauth session expired" to "oauth": that substring
    appears 2919 times in worker tool_result blocks and would false-match
    a worker legitimately discussing OAuth in its own correct output.

    Gating discipline mirrors `_is_auth_or_quota_failure` verbatim (see
    its docstring for the rationale): gated on `is_error` — a successful,
    schema-valid envelope must never match no matter what its `result`
    text says — and `_leerie_synthetic` envelopes are exempt, since the
    no-result-event envelope interpolates the worker's raw stderr into
    `result`, which can legitimately contain any of these markers without
    the session's login actually having expired."""
    if not envelope.get("is_error"):
        return False
    if envelope.get("_leerie_synthetic"):
        return False
    msg = str(envelope.get("result") or "").lower()
    return ("failed to authenticate" in msg
            or "oauth session expired" in msg
            or "session expired and could not be refreshed" in msg
            or "not logged in" in msg)


def _is_auth_or_quota_failure(envelope: dict) -> bool:
    """True if the `claude -p` envelope looks like a 401/429/529/
    auth-message rejection from the Anthropic gateway.

    These need backoff, not the immediate corrective retry that the
    schema-error path uses — the request was rejected before reaching
    a model and a fresh request will be rejected too until the user's
    Claude Code subscription window clears (401/429) or the gateway's
    transient overload (529) subsides. The auth/quota retry loop in
    claude_p() consults this classifier; non-matching envelopes fall
    through to the existing 2-attempt schema loop unchanged.

    Gated on `is_error`: a successful, schema-valid envelope must never
    match, no matter what its `result` text says. Without this gate, a
    worker whose task legitimately talks about API rate limiting or auth
    (e.g. planning a rate-limited endpoint) trips the text markers below
    on its own correct output — the orchestrator then burns the full
    backoff budget re-running an already-successful worker and can
    eventually raise a false "subscription capped" WorkerError.

    Synthetic envelopes are exempt from the text markers for the same
    reason. The markers exist to sniff a *gateway* message out of an
    envelope whose provenance is unknown; leerie synthesizes its own
    envelopes (`_leerie_synthetic`) and knows exactly what they mean, so
    text-matching them is wrong by construction. The no-result envelope
    interpolates the worker's raw stderr into `result` — stderr that can
    legitimately contain "invalid authentication" or "rate limit" without
    the request having been auth-rejected — which would otherwise divert
    the retry into the backoff loop and burn the whole budget.
    """
    if not envelope.get("is_error"):
        return False
    if _api_error_category(envelope.get("api_error_status")) is not None:
        return True
    if envelope.get("_leerie_synthetic"):
        return False
    # No numeric status matched — fall back to text markers on the result
    # body. This path is specific to the retry classifier (not shared with
    # `_classify_failure_kind`, which reads only the numeric status).
    msg = str(envelope.get("result") or "").lower()
    return ("invalid authentication" in msg
            or "rate limit" in msg
            or "rate-limit" in msg)


# Connection-drop markers for _is_transient_transport_failure. Kept narrow
# and specific to a *transport-level* disconnect (the connection carrying the
# stream dropped), not a generic "error" — a broad match would false-positive
# on a worker legitimately discussing networking in its own output, which the
# is_error gate mostly but not perfectly guards against. "connection reset" /
# "timeout while waiting for response" are the sibling shapes already
# enumerated as non-terminal-auth in tests/test_terminal_auth_failure.py.
_TRANSPORT_DROP_MARKERS = (
    "connection closed",
    "connection reset",
    "connection error",
    "mid-response",
    "timeout while waiting for response",
)


def _is_transient_transport_failure(envelope: dict) -> bool:
    """True when the `claude -p` envelope is a mid-stream **transport
    disconnect** — the network connection carrying the streaming response
    dropped mid-answer, e.g. "API Error: Connection closed mid-response."

    Same family as the 529 overload case `_is_auth_or_quota_failure` covers:
    the session is fine, the request just never completed, so a fresh session
    after backoff has a real chance of succeeding. Distinct from a schema
    mistake (the immediate corrective-note retry) and from an expired session
    (terminal auth). Routed through the *same* auth/quota tenacity backoff loop,
    checked AFTER `_is_terminal_auth_failure` so an expired session is never
    mistaken for a transport blip.

    The measured envelope shape (from a real drop): `is_error: true`,
    `subtype: "success"` (misleading — do NOT key on subtype), `terminal_reason:
    "api_error"`, `api_error_status: null` (the drop preceded any HTTP status),
    result text "API Error: Connection closed mid-response. …". So the primary
    signal is `terminal_reason == "api_error"` with no numeric `api_error_status`
    (401/429/529 keep the auth/quota path); the text markers are a secondary
    catch for drop shapes that arrive without that terminal_reason.

    Gating discipline mirrors the two auth classifiers verbatim (see their
    docstrings): gated on `is_error` — a successful, schema-valid envelope must
    never match no matter what its `result` text says — and `_leerie_synthetic`
    envelopes are exempt, since the no-result envelope interpolates the worker's
    raw stderr into `result`, which can legitimately contain these markers
    without a real transport drop. A numeric 401/429/529 status also excludes
    the envelope here (it belongs to `_is_auth_or_quota_failure`), keeping the
    two classifiers cleanly partitioned."""
    if not envelope.get("is_error"):
        return False
    if envelope.get("_leerie_synthetic"):
        return False
    # 401/429/529 are auth/quota, not a transport drop — let that classifier
    # own them so the two partition cleanly.
    if _api_error_category(envelope.get("api_error_status")) is not None:
        return False
    if (envelope.get("terminal_reason") == "api_error"
            and envelope.get("api_error_status") is None):
        return True
    msg = str(envelope.get("result") or "").lower()
    return any(m in msg for m in _TRANSPORT_DROP_MARKERS)


def _classify_failure_kind(envelope: dict, parsed_ok: bool) -> str | None:
    """Categorize *why* a captured `claude -p` call failed, for the
    `failure_kind` field on the calls.ndjson record. Returns None on
    success (the caller writes null).

    Reads only fields present on the returned result envelope — `is_error`,
    `api_error_status` (numeric 401/429/529 or null, per the SDK type),
    `terminal_reason`, and the caller's already-computed `parsed_ok`:

    - "api_error"        — gateway rejected the request. Split by
      `_api_error_category` (401→auth, 429→quota, 529→overload — the same
      map the auth/quota retry path uses); a mid-stream transport disconnect
      (`_is_transient_transport_failure` — `terminal_reason=api_error`, null
      status, "Connection closed mid-response") is tagged
      "api_error:transport" so the telemetry taxonomy matches the retry
      taxonomy that now backs it off; a bare is_error with no matching
      numeric status and no transport signal stays "api_error".
    - "incomplete"       — the worker stopped mid-work (e.g. --max-turns);
      `terminal_reason` set and not "completed". leerie already warns on
      this at the capture site.
    - "schema_parse_failed" — the worker returned but its output did not
      validate against the call_type schema (`not parsed_ok`, no is_error).
      This is the dominant real-world failure mode.
    - "malformed_tool_call" — a sub-case of the above: the worker's
      StructuredOutput tool call itself was malformed (the CLI's own
      `InputValidationError: ... could not be parsed as JSON` diagnostic, or
      a raw `__unparsedToolInput` capture), not merely schema-content-invalid
      JSON. This is a known, unfixed CLI bug
      (anthropics/claude-code#49747): a JSON tool-call payload intermittently
      switches mid-blob into legacy XML `<parameter name="...">` tags,
      correlated with the length of a single string argument — see
      `_confidence_schema`'s `maxLength` comment. Usually self-corrects
      within the same worker session (the CLI retries the tool call
      internally) and so never reaches this classifier; this tag exists for
      the rarer case where it surfaces all the way to a captured envelope,
      so the resulting `WorkerError`/die() message doesn't read like a
      leerie schema-authoring defect. Detected on fixed CLI diagnostic
      text (CLAUDE.md's regex carve-out for mechanical strings), never on
      worker-authored content.
    - None               — success (is_error false and parsed_ok true).

    KNOWN GAP (see the capture-site comment and DESIGN §14): the richest
    failures — RateLimitedExit (out-of-credits / rate-limit) and WorkerError
    (nonzero exit, no-result-event, 10 MiB overlong line) — are raised as
    exceptions inside `_read_stream` and propagate *past* the capture block,
    so no record is written for them at all and `failure_kind` cannot cover
    them. Tagging those would require threading a capture call into the raise
    sites; deferred."""
    if not envelope.get("is_error") and parsed_ok:
        return None
    if envelope.get("is_error"):
        # Same status→category map the auth/quota retry path keys on
        # (`_api_error_category`); a bare is_error with no matching numeric
        # status stays "api_error", except a transport disconnect (which the
        # retry path now backs off as its own class) gets an "api_error:transport"
        # sub-tag. Reuse `_is_transient_transport_failure` so the telemetry and
        # retry taxonomies can never drift.
        cat = _api_error_category(envelope.get("api_error_status"))
        if cat:
            return f"api_error:{cat}"
        if _is_transient_transport_failure(envelope):
            return "api_error:transport"
        return "api_error"
    term = envelope.get("terminal_reason") or ""
    if term and term != "completed":
        return "incomplete"
    # Reaching here means is_error is false and (is_error false, parsed_ok true)
    # already returned None above — so parsed_ok is necessarily false here.
    if _is_malformed_tool_call(envelope):
        return "malformed_tool_call"
    return "schema_parse_failed"


# Fixed diagnostic strings the `claude` CLI itself emits when a tool call
# (specifically StructuredOutput here) cannot be parsed as JSON at all —
# distinct from a schema-CONTENT mismatch, where the JSON parses fine but a
# required field is wrong/missing. Mechanical CLI-output matching per
# CLAUDE.md's regex carve-out, not NL interpretation of worker content.
_MALFORMED_TOOL_CALL_MARKERS = (
    "could not be parsed as json",
    "__unparsedtoolinput",
)


def _is_malformed_tool_call(envelope: dict) -> bool:
    """True if the envelope's result text carries the CLI's own
    tool-call-parse-failure diagnostic (see _classify_failure_kind's
    "malformed_tool_call" docstring paragraph and
    anthropics/claude-code#49747), as opposed to an ordinary schema-content
    validation miss. Currently only called after the `not parsed_ok, no
    is_error` guard already narrows to a failure case, but this function
    carries its own `is_error` guard anyway — mirroring
    `_is_terminal_auth_failure`/`_is_auth_or_quota_failure` (a successful,
    schema-valid envelope must never match no matter what its `result`
    text says) — so the invariant holds regardless of caller ordering,
    not just under the one call site that exists today."""
    if envelope.get("is_error"):
        return False
    msg = str(envelope.get("result") or "").lower()
    return any(m in msg for m in _MALFORMED_TOOL_CALL_MARKERS)


def _extract_tool_result_text(block: dict) -> str:
    """Tool-result `content` is either a string or a list of content
    blocks (`{type: "text", text: "..."}`). Normalize to a plain
    string so summaries / file output don't have to branch."""
    content = block.get("content")
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts = []
        for c in content:
            if isinstance(c, dict) and c.get("type") == "text":
                parts.append(c.get("text") or "")
        return " ".join(parts)
    return ""


# libc's EAGAIN ("Resource temporarily unavailable") / shell fork-failure
# strings. When a worker has exhausted its cgroup pids.max, further forks
# are denied and shells cannot launch. This text SURVIVES into the
# tool-result only for commands that emit output before the shell dies;
# trivial commands (`echo`, `true`) surface a bare "Exit code 1" instead.
# So this is a cheap *fast-path* confirmation — the authoritative signal is
# the cgroup `pids.events` read (DESIGN §6 *Detecting PID exhaustion*).
_FORK_EAGAIN_MARKERS = (
    "resource temporarily unavailable",
    "cannot fork",
    "cannot allocate memory",
    "fork: retry",
)


def _is_fork_exhaustion(text: str) -> bool:
    """True if `text` carries a shell fork-failure signature. Advisory —
    absence does NOT rule out PID exhaustion (see marker list above)."""
    low = text.lower()
    return any(m in low for m in _FORK_EAGAIN_MARKERS)


def _tool_result_outcome(event: dict) -> bool | None:
    """Classify a stream event for `_read_stream`'s PID-exhaustion window:

    - `True`  — the event is a tool_result and it errored,
    - `False` — the event is a tool_result and it succeeded,
    - `None`  — the event is NOT a tool_result (assistant / system /
      rate_limit / result).

    The detector appends only non-None outcomes to its window, so the
    events *between* tool-results (which are the majority of the stream,
    and which always separate one tool-result from the next) neither count
    as errors nor reset the window. This is the crux of the window design:
    a *consecutive* tool-result counter could never exceed one, because two
    tool-results are never adjacent in the stream (the model's assistant
    turn always sits between them). Not tool-specific — under PID
    exhaustion every shell-spawning tool fails, so the fraction of recent
    tool-results that errored, plus the authoritative cgroup probe, is what
    separates exhaustion from an ordinary single failing command."""
    if event.get("type") != "user":
        return None
    for b in (event.get("message", {}) or {}).get("content", []) or []:
        if b.get("type") == "tool_result":
            return bool(b.get("is_error"))
    return None


# Cap on the rejected-payload diagnostic (`_format_payload_for_log`). Large
# enough that a truncated planner submission — the shape this exists to
# diagnose — is shown whole, since the useful signal is precisely WHICH fields
# are absent, and a mid-cut payload cannot answer that. Small enough that a
# complete 100-subtask plan does not flood the inline log; the per-worker .log
# file carries the raw stream regardless.
_REJECTED_PAYLOAD_LOG_MAX = 4000

# Cap on the blocked-planner gap shown inline by `phase_plan`. Much smaller
# than the payload cap above because this is one line inside a per-category
# summary rather than a standalone diagnostic dump, and because the value it
# renders (`confidence.basis`) is prose: measured across real planner
# submissions it runs a median of ~1.1k characters and up to 4.3k. Enough to
# see what the planner was missing; the full text is in the per-worker log.
_BLOCKED_GAP_LOG_MAX = 400


def _format_payload_for_log(payload: object) -> str | None:
    """Render a `StructuredOutput` submission for the rejection diagnostic.

    Returns None for an absent payload so the caller's `and` guard skips the
    log line entirely rather than printing "None". Serialisation is
    best-effort: `json.dumps` on an arbitrary worker payload can raise, and a
    diagnostic that crashes the stream reader would convert a recoverable
    schema failure into a dead run — so any failure degrades to `repr`."""
    if payload is None:
        return None
    try:
        text = json.dumps(payload, sort_keys=True)
    except Exception:
        text = repr(payload)
    if len(text) > _REJECTED_PAYLOAD_LOG_MAX:
        text = (text[:_REJECTED_PAYLOAD_LOG_MAX]
                + f"… [truncated at {_REJECTED_PAYLOAD_LOG_MAX} chars]")
    return text


def _format_blocked_gap(confidence: object) -> str:
    """Render a blocked planner's stated gap for `phase_plan`'s summary line.

    The gap lives in `confidence.basis` — `gap_to_close` was removed from the
    schema (DESIGN §8) and the prompts now direct a blocked planner to state
    the missing artifact there instead.

    Two transforms, both because `basis` is free prose rather than the compact
    dict this line used to render. Whitespace is collapsed so an embedded
    newline cannot break a one-line per-category summary into several, and the
    result is truncated with a visible marker — never a silent cut, matching
    `_format_payload_for_log` above. Measured across real planner submissions,
    `basis` runs a median of ~1.1k characters and up to 4.3k, so an
    untruncated line would put multiple KB on one row of the operator's
    terminal; the full text stays in the per-worker log.

    Returns `""` (not None) for absent, empty or malformed input, so the
    caller interpolates an empty gap rather than the string "None"."""
    if not isinstance(confidence, dict):
        return ""
    gap = " ".join((confidence.get("basis") or "").split())
    if len(gap) > _BLOCKED_GAP_LOG_MAX:
        gap = gap[:_BLOCKED_GAP_LOG_MAX] + "… [truncated; see log]"
    return gap


# --- forced constrained decoding (--dangerously-force-strict-output) --------
#
# `claude -p --json-schema` is VALIDATED, not constrained: the CLI injects the
# schema as a synthetic `StructuredOutput` tool with no `strict: true` and no
# `output_config` (confirmed from a captured outbound request, 2026-08-04), then
# checks the result and re-prompts on mismatch. Measured across the run corpus,
# 2,861 of 9,924 submissions (28.8%) are malformed as a result. Setting
# `strict: true` compiles the schema into a sampling grammar, which makes those
# shapes unrepresentable rather than merely rarer. See DESIGN §7 *Forcing
# constrained decoding*.

# Keywords grammar compilation cannot express. Present in leerie's own schemas
# 21 times (15 minLength, 1 maxLength, 3 minimum, 2 maximum), so stripping them
# is not hypothetical. The five numeric bounds are the ones whose loss matters —
# their consumers compare against a threshold with no range check of their own —
# so those are re-imposed in Python via `_bounded_or_conservative`.
_STRICT_UNSUPPORTED_KEYWORDS = frozenset({
    "minLength", "maxLength", "minimum", "maximum", "multipleOf", "pattern",
    "oneOf", "not", "if", "then", "else", "dependentSchemas",
    "patternProperties", "propertyNames", "uniqueItems", "maxItems",
    "contains", "minProperties", "maxProperties",
})

# The name Claude Code gives the tool it synthesises from `--json-schema`.
# Private, unversioned, and may change in any release — which is why every
# transform below is fail-open rather than assertive.
_STRICT_OUTPUT_TOOL_NAME = "StructuredOutput"

# Upstream read timeout for the proxy. Matched to `worker_timeout_sec` so the
# proxy is never the component that gives up first — a shorter bound would kill
# requests the worker is still legitimately waiting on, converting a slow call
# into an unexplained worker failure.
_STRICT_PROXY_TIMEOUT_SEC = DEFAULT_CAPS["worker_timeout_sec"]

# The run's proxy, or None when --dangerously-force-strict-output is off (the
# default). Module-level because `claude_p` builds each worker's env deep in
# the call stack and threading it through every caller would touch far more
# surface than the feature warrants. One per run, owned by `_orchestrate`.
_STRICT_PROXY: "_StrictOutputProxy | None" = None

# Model aliases with a 1M-token context window. Haiku is absent: it has no 1M
# variant, so the suffix would be rejected rather than ignored.
_ONE_M_CONTEXT_MODELS = frozenset({"sonnet", "opus"})


def _model_arg(model: str) -> str:
    """The `--model` value, restoring the 1M window behind the strict proxy.

    Owning `ANTHROPIC_BASE_URL` — which is how `--dangerously-force-strict-output`
    reaches workers — makes the CLI treat the session as gateway-routed. It then
    applies a conservative client-side context ceiling instead of the model's
    native window and refuses an oversized prompt *itself*, emitting a synthetic
    `Prompt is too long` assistant message (`model=<synthetic>`, usage all zeros)
    with no API call at all. `[1m]` is the documented way to select the 1M window
    behind a gateway; on the direct path it is a no-op, since `sonnet` already
    resolves to Sonnet 5's native 1M.

    Measured on one 225 KB worker payload, same model/tools/cwd, varying only
    `ANTHROPIC_BASE_URL` (5 arms): direct sustained 235,805 tokens over 20
    requests with no refusal. Through a *passthrough* proxy that rewrites
    nothing the CLI refused after 224,127, and through the real strict proxy
    after 224,247 — two reproductions 120 tokens apart, so the refusal comes
    from the base-URL override alone, not the schema rewriting. Adding `[1m]`
    cleared it both times: 261,014 tokens passthrough, 276,579 through the
    strict proxy, zero refusals. The rewrite is unaffected — rewritten/
    passed_through/fell_back counters are identical under both aliases, so the
    suffix does not suppress `StructuredOutput` injection.

    Applied automatically rather than admitted to `MODEL_VALUES`: the suffix is
    inert whenever the proxy is off, so an operator gains nothing by setting it
    by hand — and could set it on `haiku`, where the CLI rejects it.
    """
    if _STRICT_PROXY is None or model not in _ONE_M_CONTEXT_MODELS:
        return model
    return f"{model}[1m]"


# How many upstream error responses get their body echoed before the proxy
# falls back to counting them. A rejected rewrite is systematic — every worker
# call fails the same way — so the first few carry all the diagnostic value and
# the rest would bury the run log they share with every other leerie line.
_STRICT_PROXY_ERROR_LOG_MAX = 3
_STRICT_PROXY_ERROR_BODY_MAX = 400


def _bounded_or_conservative(value: object, low: float, high: float,
                             conservative: float, what: str) -> float:
    """Re-impose a numeric bound that grammar compilation cannot express.

    Strict mode drops `minimum`/`maximum`, and the consumers that read those
    values compare them against a threshold with no range check of their own —
    `if score >= threshold` reads an out-of-range score as well-fit. They
    therefore fail *permissively*, which is the wrong direction for a gate, so
    the bound moves into Python rather than being lost.

    An out-of-range value returns `conservative`, it is **not clamped to the
    nearest bound**. Clamping was tried and rejected: on a 0–1 axis it maps 5.0
    to 1.0, which still clears every threshold and so preserves exactly the
    permissive failure this exists to prevent. The corpus shows the confusion is
    real — `fit_judge` emitted `"fit": 8.5` on an axis declared 0–1 — and while
    that plausibly *meant* 0.85, inferring intent from a malformed number is
    guessing. A gate must not be cleared by a value it cannot interpret, so the
    caller passes the safe end of its own range and the run pays a split or a
    re-plan instead of shipping on a reading nobody can justify.

    Applied unconditionally rather than only under the flag: a value outside the
    declared range was always a worker bug, and distrusting it is right either
    way.
    """
    try:
        num = float(value)  # type: ignore[arg-type]
    except (TypeError, ValueError):
        return conservative
    if num != num or num in (float("inf"), float("-inf")):  # NaN / ±inf
        return conservative
    if num < low or num > high:
        log(f"  {what}: value {num!r} outside [{low}, {high}] — treating as "
            f"{conservative} (untrusted, not clamped)")
        return conservative
    return num


def _strictify_schema(node: object) -> tuple[int, int]:
    """In-place: make one schema acceptable to grammar compilation.

    Returns `(objects_hardened, keywords_stripped)`.

    Two edits. Every object node gains `additionalProperties: false`, which
    strict mode requires — the API rejects the request otherwise, naming the
    offending path. And keywords the grammar cannot express are removed;
    `minItems` survives only at 0 or 1.

    **"Object node" means three shapes**, not just `{"type": "object"}`: a
    *union* type containing it (`["object", "null"]`) and a bare `properties`
    with no declared type also count, and the API requires the same of both.
    Leaving that term undefined is what let the first implementation ship an
    equality test against the string — see the comment at the check itself.

    Recurses through `items` as well as `properties`, because leerie nests
    objects inside arrays (`collisions[]`, `subtasks[]`, `wiring_defects[]`)
    and a top-level-only pass would leave those unhardened.
    """
    hardened = stripped = 0
    if isinstance(node, dict):
        for key in list(node):
            if key in _STRICT_UNSUPPORTED_KEYWORDS:
                del node[key]
                stripped += 1
                continue
            if key == "minItems" and node[key] not in (0, 1):
                node[key] = 1
                stripped += 1
        # An "object node" is not only `{"type": "object"}`. JSON Schema also
        # allows a *union* type (`["object", "null"]` — leerie's own
        # `implementer.clarification_question` is exactly that) and a bare
        # `properties` with no declared type. The API requires
        # `additionalProperties: false` on all three, and an equality test
        # against the string "object" silently skips the last two.
        #
        # Measured, not theorised: the equality test shipped, and a live sweep
        # of all 23 schemas against the real API rejected `implementer` —
        # "tools.0.custom: For 'object' type, 'additionalProperties' must be
        # explicitly set to false". That would have 400'd every implementer
        # call, surfacing only as the retry storm this flag exists to remove.
        declared = node.get("type")
        is_object = (
            declared == "object"
            or (isinstance(declared, list) and "object" in declared)
            or (declared is None and "properties" in node))
        if is_object and node.get("additionalProperties") is not False:
            node["additionalProperties"] = False
            hardened += 1
        # Every optional property becomes required — on the wire only.
        #
        # Strict mode must admit every *subset* of a node's optional properties
        # in any order, so a node with k optionals costs ~2^k grammar paths,
        # multiplied per array element. That is what made `planner`
        # uncompilable: 11 optionals in one `subtasks[]` item. Requiring them
        # collapses 2^11 paths to 1 — measured, it takes `planner` from a 400
        # ("Schema is too complex for compilation") to a 200.
        #
        # Safe because only the *wire* schema changes. The CLI still validates
        # the worker's output against leerie's ORIGINAL schema, where these
        # fields remain optional — and a field that is merely *present*
        # satisfies an optional field's type check. Audited across all 24
        # schemas (re-derived 2026-09-22): 131 optional fields, none of which
        # becomes illegal when forced (arrays admit `[]`, and no forced field
        # carries a `minLength` its trivial value would violate). One
        # BEHAVIORAL caveat, not a legality one: satisfied_probe's typed
        # not-satisfied fields rely on "absent → keep" (_probe_drop_reason),
        # and forcing makes absence unrepresentable — the prompt therefore
        # instructs inert values for the forced case, and the drop needs a
        # three-field conjunction, which bounds what grammar pressure
        # alone can cause (DESIGN's word — a probability reduction, not
        # an impossibility; the last line of defense there is the prompt)
        # (see the §2½ disclosure and DESIGN §8 *A "not satisfied" verdict
        # carries a typed reason*).
        #
        # NOT the mistake PR #153 undid. That regression was models *omitting*
        # required fields and so producing nothing schema-valid; here the
        # grammar makes omission impossible by construction.
        if is_object and isinstance(node.get("properties"), dict):
            node["required"] = sorted(node["properties"])
        for value in node.values():
            h, s = _strictify_schema(value)
            hardened += h
            stripped += s
    elif isinstance(node, list):
        for value in node:
            h, s = _strictify_schema(value)
            hardened += h
            stripped += s
    return hardened, stripped


def _strictify_request(body: bytes) -> tuple[bytes, str] | None:
    """Rewrite one outbound Messages request to force constrained decoding.

    Returns `(new_body, description)`, or None when the request should be
    forwarded byte-identical.

    Deliberately fail-open. The tool name and shape are a private interface
    with no compatibility guarantee, so anything unexpected — renamed, absent,
    duplicated, missing its schema, or a body that is not JSON at all — leaves
    the request untouched. The run then behaves exactly as it would without the
    flag: the guarantee is lost, not the run. Callers log the no-op, because a
    silent loss is the failure mode worth catching.
    """
    try:
        payload = json.loads(body)
    except Exception:
        return None
    if not isinstance(payload, dict):
        return None
    tools = payload.get("tools")
    if not isinstance(tools, list):
        return None
    hits = [t for t in tools
            if isinstance(t, dict) and t.get("name") == _STRICT_OUTPUT_TOOL_NAME]
    if len(hits) != 1:
        return None
    tool = hits[0]
    if not isinstance(tool.get("input_schema"), dict):
        return None
    tool["strict"] = True
    hardened, stripped = _strictify_schema(tool["input_schema"])
    return (json.dumps(payload).encode(),
            f"strict:true (+{hardened} additionalProperties, -{stripped} unsupported)")


def _api_error_head(payload: bytes, limit: int = 160) -> str:
    """First `limit` chars of an API error's `message`, whitespace-collapsed.

    Operates on the API's own machine-generated error envelope — a mechanical
    string, not model prose — so reading it here does not cross the
    language-to-JSON line (CLAUDE.md).
    """
    try:
        text = json.loads(payload)["error"]["message"]
    except Exception:
        text = payload[:limit].decode("utf-8", "replace")
    return " ".join(str(text).split())[:limit]


def _unexpected_structured_output_shape(body: bytes) -> bool:
    """True only when a `StructuredOutput` tool is PRESENT but unusable.

    `_strictify_request` declines for several reasons, and they are not equally
    interesting. The overwhelmingly common one is that the request simply
    carries no `StructuredOutput` tool — measured against a real 4-turn worker,
    one of its four `/v1/messages` POSTs arrives with *no tools array at all*,
    because the CLI injects the tool only on the turns where it wants
    structured output. That is ordinary traffic and says nothing about anything.

    The interesting case is a tool that IS there and is shaped wrong —
    duplicated, or missing its `input_schema`. That is the "the private
    interface changed upstream" signal, and it is what the operator warning
    exists for. Merging the two made a healthy run report 173 pass-throughs as
    a suspected upstream change.
    """
    try:
        payload = json.loads(body)
    except Exception:
        return False
    if not isinstance(payload, dict):
        return False
    tools = payload.get("tools")
    if not isinstance(tools, list):
        return False
    hits = [t for t in tools
            if isinstance(t, dict) and t.get("name") == _STRICT_OUTPUT_TOOL_NAME]
    if not hits:
        return False          # no tool at all — normal
    return len(hits) > 1 or not isinstance(hits[0].get("input_schema"), dict)


def _structured_output_fingerprint(body: bytes) -> str | None:
    """Stable id for the schema a request carries, or None if it carries none.

    Identifies "this same schema again" so a schema already proven
    un-hardenable is not re-hardened, re-rejected and re-sent on every
    subsequent call by the same worker type.
    """
    try:
        payload = json.loads(body)
        tools = payload.get("tools")
        hits = [t for t in tools
                if isinstance(t, dict) and t.get("name") == _STRICT_OUTPUT_TOOL_NAME]
        if len(hits) != 1:
            return None
        canonical = json.dumps(hits[0].get("input_schema"), sort_keys=True)
    except Exception:
        return None
    return hashlib.sha256(canonical.encode()).hexdigest()[:16]


@functools.lru_cache(maxsize=1)
def _fingerprint_to_worker_type() -> dict[str, str]:
    """Maps a schema fingerprint back to the worker type it belongs to.

    Built once from `SCHEMAS` using the exact same canonicalization
    `_structured_output_fingerprint` applies to a request's `input_schema`
    (`scripts/verify-strict-schemas.py`'s `tool_for()` confirms the CLI
    hardens `SCHEMAS[worker]` itself, unmodified) so a fallback log line can
    name which worker's schema was rejected instead of leaving it anonymous.
    """
    return {
        hashlib.sha256(json.dumps(schema, sort_keys=True).encode())
        .hexdigest()[:16]: worker
        for worker, schema in SCHEMAS.items()
    }


def _worker_type_for_fingerprint(fingerprint: str | None) -> str | None:
    """Resolves a request's schema fingerprint to its worker type, or None."""
    if fingerprint is None:
        return None
    return _fingerprint_to_worker_type().get(fingerprint)


class _StrictOutputProxy:
    """One loopback proxy per run, forcing constrained decoding.

    Workers reach it through `ANTHROPIC_BASE_URL`. Every worker is a child of
    the orchestrator process (DESIGN §6 *Worker subtree termination*), so they
    share its network namespace: a `127.0.0.1` listener needs no port mapping
    on any runtime. On abnormal death the enclosing boundary reaps the listener
    — the container locally (where the orchestrator is also PID 1), the machine
    on `--runtime fly` / `ec2`, where it is instead spawned from a bootstrap.

    Every design choice below was forced by a measured failure in a load test of
    this exact shape, not chosen on taste:

    * **Ephemeral port.** Bind `0` and read back what the OS assigned, so
      concurrent leerie runs on one host cannot collide and nothing scans.
    * **Dedicated executor.** asyncio's default pool saturates: 34 of 40
      concurrent connections survived, the rest died with
      `ConnectionResetError`. Sized to the wave width plus headroom, it is
      40/40 and 80/80.
    * **`reuse_address` + drain on shutdown.** Without closing tracked writers
      and joining the executor, the port stays unbindable afterwards and a
      second run in the same container fails to start.
    * **Client hang-ups are normal.** `ConnectionResetError` / `BrokenPipeError`
      are caught per connection and never escalate; the CLI hangs up routinely
      once it has what it needs.

    Upstream is bridged through `urllib` on that executor rather than spoken
    natively over `asyncio.open_connection`. leerie has no async HTTP dependency
    (CLAUDE.md: stdlib-preferred), and hand-rolling HTTP/1.1 — chunked encoding,
    keep-alive, partial reads — is exactly where a proxy in the path of every
    worker call would acquire subtle bugs.
    """

    _UPSTREAM = "https://api.anthropic.com"

    def __init__(self, max_parallel: int,
                 verbosity: str = VERBOSITY_DEFAULT,
                 upstream_timeout_sec: int = _STRICT_PROXY_TIMEOUT_SEC) -> None:
        # Tracks the RESOLVED worker ceiling, not the frozen default. The
        # module constant is `DEFAULT_CAPS["worker_timeout_sec"]` evaluated at
        # import, so once `--worker-timeout` could raise the cap above it the
        # proxy became able to give up first — the exact outcome the
        # constant's own comment says it exists to prevent.
        self._upstream_timeout = max(upstream_timeout_sec,
                                     _STRICT_PROXY_TIMEOUT_SEC)
        self._server: asyncio.base_events.Server | None = None
        self._writers: set[asyncio.StreamWriter] = set()
        # +8 so the pool is never the ceiling: a wave's workers plus the
        # occasional out-of-band call (token probe, smoke test) must all fit.
        self._pool = concurrent.futures.ThreadPoolExecutor(
            max_workers=max_parallel + 8, thread_name_prefix="strict-proxy")
        self._verbosity = verbosity
        self.port = 0
        self.rewritten = 0
        self.passed_through = 0
        self.fell_back = 0
        # Split deliberately. Merging these is what made a clean run describe
        # itself as suspect: `unexpected_tool_shape` is the only pass-through
        # worth warning about, and `schema_errors` the only upstream error the
        # flag can be responsible for.
        self.unexpected_tool_shape = 0
        self.schema_errors = 0
        self.transient_errors = 0
        # Schemas the API refuses to compile into a grammar. Measured: 2 of
        # leerie's 23 (`planner`, `reconciler`) — both carry 12 optional
        # properties inside array items, and strict mode must accept every
        # subset of those in any order, so grammar size multiplies per element.
        # Once a schema lands here it is never hardened again this run, so the
        # doomed round trip is paid once rather than per worker call.
        self._unhardenable: set[str] = set()

    async def start(self) -> int:
        self._server = await asyncio.start_server(
            self._handle, "127.0.0.1", 0, reuse_address=True, backlog=256)
        self.port = self._server.sockets[0].getsockname()[1]
        return self.port

    async def stop(self) -> None:
        if self._server is not None:
            self._server.close()
            with contextlib.suppress(Exception):
                await self._server.wait_closed()
        for writer in list(self._writers):
            with contextlib.suppress(Exception):
                writer.close()
        self._writers.clear()
        self._pool.shutdown(wait=False, cancel_futures=True)

    @staticmethod
    async def _read_chunked(reader: asyncio.StreamReader, rest: bytes) -> bytes:
        """Decode a chunked request body into its real bytes.

        urllib recomputes `content-length` for the upstream hop, so forwarding
        the raw framing would describe a body that is not what it says it is.
        Decoding here keeps the untested-path fallback a correct request rather
        than a differently-corrupt one.
        """
        buf = bytearray(rest)
        out = bytearray()
        while True:
            # `find` + slice rather than `bytes(buf).partition(...)`: the latter
            # copies the whole remaining buffer once per chunk, which is
            # quadratic in chunk count — and this path exists precisely for a
            # large body arriving in many small chunks.
            cut = buf.find(b"\r\n")
            while cut == -1:
                chunk = await reader.read(65536)
                if not chunk:
                    return bytes(out)
                buf += chunk
                cut = buf.find(b"\r\n")
            line = bytes(buf[:cut])
            del buf[:cut + 2]
            try:
                size = int(line.split(b";", 1)[0].strip() or b"0", 16)
            except ValueError:
                return bytes(out)
            if size == 0:
                return bytes(out)
            while len(buf) < size + 2:
                chunk = await reader.read(size + 2 - len(buf))
                if not chunk:
                    out += buf[:size]
                    return bytes(out)
                buf += chunk
            out += buf[:size]
            del buf[:size + 2]

    def _upstream(self, method: str, path: str, body: bytes,
                  headers: dict) -> tuple[int, list, bytes]:
        """Blocking round-trip, run on the dedicated pool.

        `method` is threaded through rather than assumed: only POST bodies are
        ever rewritten, but every other verb the CLI issues must reach upstream
        as itself. Replaying a GET as a POST would corrupt requests this proxy
        is supposed to pass through untouched.
        """
        req = urllib.request.Request(self._UPSTREAM + path,
                                     data=body if body else None,
                                     headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=self._upstream_timeout) as r:
                return r.status, list(r.headers.items()), r.read()
        except urllib.error.HTTPError as e:
            return e.code, list(e.headers.items()), e.read()

    def _log_exchange(self, method: str, path: str, status: int,
                      desc: str, payload: bytes) -> None:
        """Surface one proxied exchange on the orchestrator's own log stream.

        The proxy runs in the orchestrator process, so `log()` here interleaves
        with every other leerie line — no separate file to go find.

        An upstream error is logged at *every* verbosity, with its body. This
        proxy is the only thing in the path that rewrites a request, so a 4xx
        here is most likely leerie's own edit being rejected — and the response
        names the offending schema path. Without it the operator sees only
        workers retrying, which is precisely the misattribution this flag's
        whole failure mode consists of. Per-request success lines are debug-only
        (`-vv`): one per worker API call is far too much for normal output.
        """
        if status >= 400:
            # Budget PER CLASS. A shared budget is not a milder version of this
            # — it is a different, broken thing: measured live, three transient
            # 529s in the first minutes consumed the whole allowance, so a
            # later genuine 400 (carrying the API's own message naming the
            # offending schema path) would have been silently counted instead
            # of shown. Overload noise must not starve the one channel that can
            # diagnose this flag.
            schema_shaped = status == 400
            seen = self.schema_errors if schema_shaped else self.transient_errors
            if seen <= _STRICT_PROXY_ERROR_LOG_MAX:
                if schema_shaped:
                    # The body names the offending path; it is the whole
                    # diagnostic, so it is echoed rather than summarised.
                    snippet = " ".join(
                        payload[:_STRICT_PROXY_ERROR_BODY_MAX]
                        .decode("utf-8", "replace").split())
                    log(f"  strict-output proxy: upstream 400 on {method} "
                        f"{path} ({desc or 'not rewritten'}) — {snippet}")
                else:
                    # Capacity or throttling — nothing to do with the rewrite.
                    # Say so, so it is not mistaken for one.
                    log(f"  strict-output proxy: upstream {status} on {method} "
                        f"{path} — transient (not a schema rejection); "
                        "retried upstream")
                if seen == _STRICT_PROXY_ERROR_LOG_MAX:
                    kind = "schema" if schema_shaped else "transient"
                    log(f"  strict-output proxy: further {kind} errors will be "
                        "counted, not echoed (see the end-of-run summary)")
        elif self._verbosity == "debug":
            log(f"  strict-output proxy: {method} {path} -> {status} "
                f"({desc or 'forwarded unmodified'})")

    async def _handle(self, reader: asyncio.StreamReader,
                      writer: asyncio.StreamWriter) -> None:
        self._writers.add(writer)
        try:
            desc = ""
            original: bytes | None = None
            fingerprint: str | None = None
            head = b""
            while b"\r\n\r\n" not in head:
                chunk = await reader.read(8192)
                if not chunk:
                    return
                head += chunk
            raw_head, _, rest = head.partition(b"\r\n\r\n")
            lines = raw_head.split(b"\r\n")
            request_line = lines[0].decode("latin-1")
            method, _, tail = request_line.partition(" ")
            path = tail.rsplit(" ", 1)[0]
            headers = {}
            length = 0
            chunked = False
            for line in lines[1:]:
                name, _, value = line.decode("latin-1").partition(":")
                name, value = name.strip(), value.strip()
                if name.lower() == "content-length":
                    length = int(value or 0)
                if name.lower() == "transfer-encoding" and "chunked" in value.lower():
                    chunked = True
                # Host/length/encoding are recomputed by urllib for the
                # upstream hop; forwarding ours would describe the wrong body.
                # `transfer-encoding` is in this list rather than popped later
                # because header names are case-insensitive on the wire: a
                # `TRANSFER-ENCODING` that survived would reach upstream beside
                # urllib's computed content-length, and a request carrying both
                # framing headers is a smuggling shape servers reject.
                if name.lower() not in ("host", "content-length",
                                        "accept-encoding", "connection",
                                        "transfer-encoding"):
                    headers[name] = value

            # A chunked request body carries no `content-length`, so the
            # length-driven read below would take whatever landed in the first
            # packet and forward it as the whole body — a silently truncated
            # request, which reads downstream as a model error rather than a
            # proxy bug. Today's CLI always sends `content-length`, but that is
            # an observation about one client version, not a guarantee. Decode
            # the framing so the upstream hop gets the real bytes, and never
            # rewrite a body that arrived on this untested path.
            if chunked:
                body = await self._read_chunked(reader, rest)
                # Counted only for POST, matching the branch below: a GET was
                # never a candidate for constrained decoding, so counting one
                # would inflate the pass-through total for no reason.
                if method.upper() == "POST":
                    self.passed_through += 1
            else:
                body = rest
                while len(body) < length:
                    chunk = await reader.read(length - len(body))
                    if not chunk:
                        break
                    body += chunk

                if method.upper() == "POST":
                    fingerprint = _structured_output_fingerprint(body)
                    if fingerprint is not None and fingerprint in self._unhardenable:
                        # Already proven un-compilable this run. Sending it
                        # again would just buy another rejection.
                        self.passed_through += 1
                    else:
                        swap = _strictify_request(body)
                        if swap is not None:
                            original, (body, desc) = body, swap
                            self.rewritten += 1
                        else:
                            self.passed_through += 1
                            # Only a PRESENT-but-unusable tool is worth an
                            # operator warning; a request with no tool at all
                            # is ordinary multi-turn traffic.
                            if _unexpected_structured_output_shape(body):
                                self.unexpected_tool_shape += 1

            loop = asyncio.get_running_loop()
            status, up_headers, payload = await loop.run_in_executor(
                self._pool, self._upstream, method.upper(), path, body, headers)

            # Fail open on the RESPONSE, not just the request. Some schemas
            # cannot be compiled into a sampling grammar at all — measured, 2 of
            # leerie's 23: "Schema is too complex" (`planner`) and "The compiled
            # grammar is too large" (`reconciler`), both carrying 12 optional
            # properties inside array items, where strict mode must accept every
            # subset in any order and grammar size multiplies per element.
            #
            # Without this the flag 400s every call by those workers, and a run
            # that cannot plan cannot do anything — a far worse outcome than the
            # post-hoc validation the flag exists to improve on. Re-sending the
            # untouched request costs the guarantee for that one worker and
            # keeps the run, which is the same trade the request-side fail-open
            # already makes. Only 400 is retried: 401/403/429 are not schema
            # problems and the original would fail identically.
            if original is not None and status == 400:
                self._unhardenable.add(fingerprint or "")
                self.fell_back += 1
                self.rewritten -= 1
                self.passed_through += 1
                worker_type = _worker_type_for_fingerprint(fingerprint) or "unknown"
                log(f"  strict-output proxy: upstream rejected the hardened "
                    f"schema for worker={worker_type} "
                    f"({_api_error_head(payload)}) — retrying WITHOUT "
                    f"constrained decoding; this worker keeps ordinary "
                    f"post-hoc validation for the rest of the run")
                status, up_headers, payload = await loop.run_in_executor(
                    self._pool, self._upstream, method.upper(), path,
                    original, headers)
                desc = "fell back: schema will not compile"

            # Classified on the FINAL status, deliberately — after any
            # fallback, not before. A 400 the fallback absorbs ends at 200 and
            # is counted nowhere here, because `fell_back` already reports it
            # once and correctly; counting it again as an unhandled rejection
            # would send the operator to "re-run without the flag to confirm" a
            # problem the proxy just resolved itself. A 400 that survives the
            # fallback, or one on a request we never rewrote, is genuinely
            # unhandled and is ours to raise.
            if status == 400:
                self.schema_errors += 1
            elif status >= 400:
                self.transient_errors += 1
            self._log_exchange(method.upper(), path, status, desc, payload)

            out = [f"HTTP/1.1 {status} X".encode("latin-1")]
            for name, value in up_headers:
                if name.lower() in ("content-length", "transfer-encoding",
                                    "content-encoding", "connection"):
                    continue
                out.append(f"{name}: {value}".encode("latin-1"))
            out.append(f"content-length: {len(payload)}".encode("latin-1"))
            out.append(b"connection: close")
            writer.write(b"\r\n".join(out) + b"\r\n\r\n" + payload)
            await writer.drain()
        except (ConnectionResetError, BrokenPipeError, asyncio.IncompleteReadError):
            # The CLI hangs up routinely once it has what it needs. Normal.
            pass
        except Exception as e:  # noqa: BLE001 - one bad connection must not
            # take down the listener that every other worker depends on.
            log(f"  strict-output proxy: connection error ({type(e).__name__}: {e})")
        finally:
            self._writers.discard(writer)
            with contextlib.suppress(Exception):
                writer.close()


@contextlib.asynccontextmanager
async def _strict_output_proxy(caps: dict, label: str) -> AsyncIterator[None]:
    """Run the enclosed block with `_STRICT_PROXY` live iff the flag is set.

    `_orchestrate()` starts one proxy per run before its first worker and
    closes it in its own `finally` (DESIGN §7). Three entrypoints never
    reach that code and so need their own short-lived instance, or the flag
    is silently inert for every worker they invoke: `run_rebaser` and
    `run_recapture_deps` (each a separate host-seam `python3` process, where
    the module-level global starts fresh at `None` regardless of config) and
    `main()`'s `--phase heal` branch (which returns before `_orchestrate` is
    called). `_invoke` gates purely on this global being non-None, so a
    caller needs nothing beyond wrapping its own worker call in this.

    Fails soft in BOTH directions, because all three callers are best-effort
    paths that must never block a push or abort a multi-run loop: a `start()`
    `OSError` logs and proceeds unconstrained (the guarantee is lost, not the
    run — DESIGN §7 *It fails open*), and a `stop()` failure is logged and
    swallowed rather than propagated out of the `finally`, where it would
    escape past an already-successful result and be misreported as a worker
    failure. The global is reset unconditionally either way, which
    `run_recapture_deps` relies on per loop iteration: a stale non-None value
    would silently route the NEXT target run through this run's closed proxy,
    even a run whose own state has the flag off.

    `label` names the calling path in log lines only — the proxy itself is
    identical for all three.

    Deliberately NOT reused by `_orchestrate`: that one is scoped to a whole
    run rather than a single call, reports four aggregate counters at
    shutdown, and dies rather than continuing when its listener cannot bind
    (DESIGN §7 *It fails closed at startup*) — the opposite of the fail-soft
    contract these three need.
    """
    global _STRICT_PROXY
    started = False
    if caps.get("force_strict_output"):
        proxy = _StrictOutputProxy(
            caps["max_parallel"], VERBOSITY_DEFAULT,
            caps.get("worker_timeout_sec",
                     DEFAULT_CAPS["worker_timeout_sec"]))
        try:
            port = await proxy.start()
        except OSError as e:
            log(f"strict output: could not start local proxy for {label} "
                f"({e}); continuing without constrained decoding")
        else:
            # Publish to the global only after a successful bind. Assigning
            # it first would leave a never-started proxy visible to `_invoke`
            # whenever `start()` raised anything but OSError: that escapes
            # before the `finally` below is even entered, so nothing resets
            # it, and `__init__` leaves `port` at 0 — pointing every later
            # worker in the process at `127.0.0.1:0`. That is a hard failure
            # rather than the lost guarantee this is supposed to degrade to,
            # and in run_recapture_deps's loop it would hit the NEXT run.
            _STRICT_PROXY = proxy
            started = True
            log(f"strict output: rewriting worker API requests via "
                f"127.0.0.1:{port} — `strict: true` forced on the "
                f"StructuredOutput tool "
                f"(--dangerously-force-strict-output, {label})")
    try:
        yield
    finally:
        if started:
            try:
                await _STRICT_PROXY.stop()
            except Exception as e:  # noqa: BLE001 - see fail-soft note above
                log(f"strict output: error stopping local proxy for "
                    f"{label} ({e}); continuing")
            finally:
                _STRICT_PROXY = None


# --- The egress proxy: the one way a confined process reaches outside --------
# DESIGN §6 *A confined process has its own network; the outside is reached
# only through leerie's proxy*. Every confined process runs in a network
# namespace of its own, loopback only, so a listener one starts is no
# other's. A process whose grant
# carries `egress` (a worker: the API, WebFetch, the fetches its shell runs;
# an install kind: its registry) reaches the outside through this proxy only:
# an HTTP CONNECT (and plain-HTTP) proxy on a unix socket in a 0700 directory
# leerie owns under `/tmp/l/`, which the shim carries into the namespace and
# relays from the namespace's own `127.0.0.1:<port>`. It runs on its own
# thread and event loop, so a synchronous spawn on the orchestrator's loop
# never stalls it. It resolves names itself and refuses every destination
# that is inside the container — loopback, link-local, unspecified,
# multicast, the container's own addresses — so the proxy is no way back to
# a listener outside the namespace. It logs refused destinations, never
# payloads.
EGRESS_SOCKET_NAME = "egress.sock"
_EGRESS_HEAD_MAX = 64 << 10
_EGRESS_CONNECT_TIMEOUT_SEC = 30.0
_EGRESS_START_TIMEOUT_SEC = 30.0
_EGRESS_HOP_HEADERS = frozenset({"proxy-connection", "proxy-authorization",
                                 "connection", "keep-alive"})


def _own_addresses() -> set[str]:
    """The container's own addresses, from the kernel's tables: every local
    IPv4 address (`/proc/net/fib_trie`'s `/32 host LOCAL` entries) and every
    IPv6 address of an interface (`/proc/net/if_inet6`)."""
    out: set[str] = set()
    try:
        last = None
        with open("/proc/net/fib_trie", encoding="ascii",
                  errors="replace") as f:
            for line in f:
                s = line.strip()
                if s.startswith("|-- "):
                    last = s[4:]
                elif s == "/32 host LOCAL" and last:
                    out.add(last)
    except OSError:
        pass
    try:
        with open("/proc/net/if_inet6", encoding="ascii",
                  errors="replace") as f:
            for line in f:
                h = line.split()[0] if line.split() else ""
                if len(h) == 32:
                    out.add(str(ipaddress.IPv6Address(bytes.fromhex(h))))
    except (OSError, ValueError):
        pass
    return out


def _egress_refusal(addr: str, own: set[str]) -> str | None:
    """Why the proxy refuses to connect to `addr` (an IP literal), or None:
    every address that reaches into the container rather than out of it."""
    try:
        ip = ipaddress.ip_address(addr.split("%", 1)[0])
    except ValueError:
        return "not an address"
    if isinstance(ip, ipaddress.IPv6Address) and ip.ipv4_mapped:
        ip = ip.ipv4_mapped
    if ip.is_loopback:
        return "loopback"
    if ip.is_link_local:
        return "link-local"
    if ip.is_unspecified:
        return "unspecified"
    if ip.is_multicast:
        return "multicast"
    if str(ip) in own:
        return "the container's own address"
    return None


def _egress_target(text: str) -> tuple[str, int] | None:
    """`host:port` (an IPv6 literal bracketed) as `(host, port)`."""
    host, sep, port = text.rpartition(":")
    if not sep or not port.isdigit() or not 0 < int(port) < 65536:
        return None
    if host.startswith("[") and host.endswith("]"):
        host = host[1:-1]
    return (host, int(port)) if host else None


async def _egress_pipe(reader: asyncio.StreamReader,
                       writer: asyncio.StreamWriter) -> None:
    try:
        while True:
            data = await reader.read(1 << 16)
            if not data:
                break
            writer.write(data)
            await writer.drain()
    except (ConnectionError, OSError, asyncio.IncompleteReadError):
        pass
    with contextlib.suppress(Exception):
        if writer.can_write_eof():
            writer.write_eof()


class _EgressProxy:
    """The run's egress proxy (above): a unix-socket server on its own
    thread. `forward(port)` adds a socket that pipes to this container's
    `127.0.0.1:port`, for a listener of leerie's own a confined worker must
    reach (the strict-output proxy's `ANTHROPIC_BASE_URL`)."""

    def __init__(self, directory: Path) -> None:
        self.dir = Path(directory)
        self.socket_path = self.dir / EGRESS_SOCKET_NAME
        self.pid = os.getpid()
        self._loop: asyncio.AbstractEventLoop | None = None
        self._servers: list[asyncio.base_events.Server] = []
        self._forwards: dict[int, str] = {}
        self._refused: set[tuple[str, int]] = set()
        self.connections = 0
        self.refusals = 0

    def start(self) -> None:
        ready = threading.Event()
        failed: list[BaseException] = []

        def serve() -> None:
            loop = asyncio.new_event_loop()
            # A connection still open when the process exits is not an
            # error of the proxy's: its task is dropped silently.
            loop.set_exception_handler(
                lambda lp, ctx: None if "destroyed but it is pending"
                in str(ctx.get("message", ""))
                else lp.default_exception_handler(ctx))
            self._loop = loop
            try:
                srv = loop.run_until_complete(asyncio.start_unix_server(
                    self._handle, path=str(self.socket_path),
                    limit=_EGRESS_HEAD_MAX, backlog=256))
                self._servers.append(srv)
            except BaseException as e:  # noqa: BLE001 - reported to start()
                failed.append(e)
                ready.set()
                loop.close()
                return
            ready.set()
            loop.run_forever()

        threading.Thread(target=serve, name="leerie-egress",
                         daemon=True).start()
        if not ready.wait(_EGRESS_START_TIMEOUT_SEC):
            raise OSError("the egress proxy did not start")
        if failed:
            raise OSError(f"the egress proxy could not listen on "
                          f"{self.socket_path}: {failed[0]}")

    def forward(self, port: int) -> str:
        """The unix socket that pipes to `127.0.0.1:port`, made once."""
        if port in self._forwards:
            return self._forwards[port]
        path = self.dir / f"fwd-{port}.sock"

        async def make() -> None:
            async def handle(reader: asyncio.StreamReader,
                             writer: asyncio.StreamWriter) -> None:
                try:
                    ur, uw = await asyncio.wait_for(
                        asyncio.open_connection("127.0.0.1", port),
                        _EGRESS_CONNECT_TIMEOUT_SEC)
                except (OSError, asyncio.TimeoutError):
                    writer.close()
                    return
                await self._splice(reader, writer, ur, uw)
            self._servers.append(await asyncio.start_unix_server(
                handle, path=str(path), backlog=256))

        assert self._loop is not None
        asyncio.run_coroutine_threadsafe(make(), self._loop).result(
            _EGRESS_START_TIMEOUT_SEC)
        self._forwards[port] = str(path)
        return str(path)

    @staticmethod
    async def _splice(r1: asyncio.StreamReader, w1: asyncio.StreamWriter,
                      r2: asyncio.StreamReader,
                      w2: asyncio.StreamWriter) -> None:
        await asyncio.gather(_egress_pipe(r1, w2), _egress_pipe(r2, w1))
        for w in (w1, w2):
            with contextlib.suppress(Exception):
                w.close()

    async def _refuse(self, writer: asyncio.StreamWriter, code: int,
                      reason: str, why: str) -> None:
        body = f"leerie egress proxy: {why}\n".encode()
        with contextlib.suppress(Exception):
            writer.write(f"HTTP/1.1 {code} {reason}\r\nContent-Type: "
                         f"text/plain\r\nContent-Length: {len(body)}\r\n"
                         "Connection: close\r\n\r\n".encode() + body)
            await writer.drain()
            writer.close()

    async def _connect(self, host: str, port: int
                       ) -> tuple[asyncio.StreamReader,
                                  asyncio.StreamWriter] | str:
        """A connection to `host:port` on an address the proxy allows, or
        why there is none. Names are resolved here, and the connection is
        made to the address checked, never to a name resolved again."""
        loop = asyncio.get_running_loop()
        upstream = _egress_proxy(host)
        try:
            infos = await loop.getaddrinfo(host, port,
                                           type=socket.SOCK_STREAM)
        except (OSError, UnicodeError) as e:
            if upstream is None:
                return f"cannot resolve {host}: {e}"
            # Only the operator's proxy resolves it: that proxy is outside
            # the container, and no loopback of the container is its.
            infos = []
        own = _own_addresses()
        allowed, why = [], None
        for fam, _t, _p, _c, sa in infos:
            refusal = _egress_refusal(sa[0], own)
            if refusal is None:
                allowed.append(sa[0])
            else:
                why = why or refusal
        if not allowed and (infos or upstream is None):
            self.refusals += 1
            if (host, port) not in self._refused:
                self._refused.add((host, port))
                log(f"egress: refused {host}:{port} ({why}): a confined "
                    "process reaches only outside the container (DESIGN §6 "
                    "*A confined process has its own network*)")
            return f"refused {host}:{port} ({why})"
        if upstream is not None:
            return await self._via_upstream(upstream, host, port)
        last: str = "no address"
        for addr in dict.fromkeys(allowed):
            try:
                return await asyncio.wait_for(
                    asyncio.open_connection(addr, port),
                    _EGRESS_CONNECT_TIMEOUT_SEC)
            except (OSError, asyncio.TimeoutError) as e:
                last = f"{type(e).__name__}: {e}"
        return f"cannot connect to {host}:{port}: {last}"

    @staticmethod
    async def _via_upstream(upstream: tuple[str, int, str], host: str,
                            port: int
                            ) -> tuple[asyncio.StreamReader,
                                       asyncio.StreamWriter] | str:
        """A tunnel to `host:port` through the operator's own proxy (the
        container's proxy variables, `_egress_proxy`), as the worker's
        tools reached it before they had a namespace of their own."""
        phost, pport, auth = upstream
        try:
            ur, uw = await asyncio.wait_for(
                asyncio.open_connection(phost, pport),
                _EGRESS_CONNECT_TIMEOUT_SEC)
            target = f"[{host}]:{port}" if ":" in host else f"{host}:{port}"
            uw.write((f"CONNECT {target} HTTP/1.1\r\nHost: {target}\r\n"
                      + (f"Proxy-Authorization: Basic {auth}\r\n"
                         if auth else "") + "\r\n").encode("latin-1"))
            await uw.drain()
            head = await asyncio.wait_for(ur.readuntil(b"\r\n\r\n"),
                                          _EGRESS_CONNECT_TIMEOUT_SEC)
        except (OSError, asyncio.TimeoutError, asyncio.IncompleteReadError,
                asyncio.LimitOverrunError) as e:
            return f"cannot reach the proxy {phost}:{pport}: {e}"
        first = head.split(b"\r\n", 1)[0]
        status = first.split(b" ")
        if len(status) < 2 or status[1] != b"200":
            uw.close()
            return (f"the proxy {phost}:{pport} answered "
                    f"{first.decode('latin-1')!r}")
        return ur, uw

    async def _handle(self, reader: asyncio.StreamReader,
                      writer: asyncio.StreamWriter) -> None:
        self.connections += 1
        try:
            head = await reader.readuntil(b"\r\n\r\n")
        except (asyncio.IncompleteReadError, asyncio.LimitOverrunError,
                ConnectionError, OSError):
            with contextlib.suppress(Exception):
                writer.close()
            return
        lines = head.decode("latin-1").split("\r\n")
        parts = lines[0].split(" ")
        if len(parts) != 3 or not parts[2].startswith("HTTP/"):
            await self._refuse(writer, 400, "Bad Request", "bad request line")
            return
        method, target, version = parts
        if method == "CONNECT":
            dest = _egress_target(target)
            if dest is None:
                await self._refuse(writer, 400, "Bad Request",
                                   f"bad CONNECT target {target!r}")
                return
            up = await self._connect(*dest)
            if isinstance(up, str):
                await self._refuse(writer, 403 if up.startswith("refused")
                                   else 502, "Forbidden"
                                   if up.startswith("refused")
                                   else "Bad Gateway", up)
                return
            ur, uw = up
            with contextlib.suppress(Exception):
                writer.write(b"HTTP/1.1 200 Connection Established\r\n\r\n")
                await writer.drain()
            await self._splice(reader, writer, ur, uw)
            return
        u = urllib.parse.urlsplit(target)
        try:
            port = u.port or 80
        except ValueError:
            port = None
        if u.scheme != "http" or not u.hostname or port is None:
            await self._refuse(writer, 400, "Bad Request",
                               "only CONNECT and absolute http:// requests")
            return
        up = await self._connect(u.hostname, port)
        if isinstance(up, str):
            await self._refuse(writer, 403 if up.startswith("refused")
                               else 502, "Forbidden"
                               if up.startswith("refused")
                               else "Bad Gateway", up)
            return
        ur, uw = up
        path = (u.path or "/") + (f"?{u.query}" if u.query else "")
        headers = [h for h in lines[1:] if h
                   and h.split(":", 1)[0].strip().lower()
                   not in _EGRESS_HOP_HEADERS]
        # One request per connection: the next may name another host.
        out = "\r\n".join([f"{method} {path} {version}", *headers,
                           "Connection: close", "", ""])
        with contextlib.suppress(Exception):
            uw.write(out.encode("latin-1"))
        await self._splice(reader, writer, ur, uw)


_EGRESS: _EgressProxy | None = None
_EGRESS_LOCK = threading.Lock()


def _egress_server() -> _EgressProxy:
    """This process's egress proxy, started on first use (a forked child
    starts its own): every spawn with an `egress` grant names its socket."""
    global _EGRESS
    with _EGRESS_LOCK:
        if _EGRESS is None or _EGRESS.pid != os.getpid():
            # A directory this proxy made itself, never a path derived from
            # the pid: a second proxy in the same process (or one of an
            # earlier process with the same pid) would bind the same
            # `egress.sock`, unlinking the first one's while it serves.
            proxy = _EgressProxy(_new_private_tmp("egress-"))
            try:
                proxy.start()
            except OSError as e:
                die(f"{e}. Leerie gives a confined process the outside "
                    "network only through its egress proxy (DESIGN §6 "
                    "*A confined process has its own network*).")
            _EGRESS = proxy
        return _EGRESS


# Substrings that identify a *schema* rejection of a structured submission, as
# opposed to any other errored tool result. Measured against real worker
# streams: the CLI emits "Output does not match required schema: …" for a
# parseable-but-invalid payload, and "InputValidationError" when the payload
# could not be parsed as JSON at all.
_SCHEMA_REJECTION_MARKERS = (
    "does not match required schema",
    "inputvalidationerror",
)


def _is_schema_rejection(event: dict) -> bool:
    """True when this stream event is a tool_result rejecting a structured
    submission on schema grounds.

    Deliberately narrow. `_read_stream` uses this to decide whether to print
    the latched payload, and an ordinary tool failure (a failing test, a
    missing file) must never drag an unrelated structured payload into the log
    beside it."""
    if not isinstance(event, dict) or event.get("type") != "user":
        return False
    for b in (event.get("message") or {}).get("content") or []:
        # `isinstance` rather than a bare `.get`: this runs on every event of
        # a live stream, and a single malformed block would otherwise raise
        # AttributeError out of _read_stream and kill the run.
        if not isinstance(b, dict):
            continue
        if b.get("type") != "tool_result" or not b.get("is_error"):
            continue
        text = _extract_tool_result_text(b).lower()
        if any(m in text for m in _SCHEMA_REJECTION_MARKERS):
            return True
    return False


def _tag_each_line(prefix: str, content: str) -> str:
    """Prefix the first non-empty line of `content` with `prefix`;
    subsequent lines get a width-matched continuation prefix that
    preserves the `[<sid>` worker-attribution segment but drops the
    event-kind token.

    Used for tool_result summaries whose content can be multi-line
    (a Read of a source file, a Grep result, a stack trace, a
    compound command's stdout). Lines 2+ must stay attributable to
    this worker — in a parallel run with max_parallel=4, untagged
    continuation lines would be indistinguishable from another
    worker's output. The kind token (`tool-fail`, `tool-ok`)
    repeated on every line, however, is per-tool-call information
    that obscures the actual content when repeated.

    For single-line content the result is `f'{prefix} {content}'`.
    For empty content it returns the empty string so the caller's
    truthiness check naturally drops it. If `prefix` doesn't match
    the expected `<indent>[<sid> <kind>]` shape (defensive — every
    current caller does), the helper falls back to repeating
    `prefix` on every line."""
    lines = [ln for ln in content.splitlines() if ln]
    if not lines:
        return ""
    open_b = prefix.find("[")
    close_b = prefix.rfind("]")
    cont = prefix
    if open_b >= 0 and close_b > open_b:
        inside = prefix[open_b + 1 : close_b]
        sid, _, kind = inside.partition(" ")
        if sid and kind:
            keep = prefix[: open_b + 1] + sid
            pad = " " * (close_b - len(keep))
            cont = keep + pad + "]"
    return "\n".join([f"{prefix} {lines[0]}",
                      *(f"{cont} {ln}" for ln in lines[1:])])


def _summarize_tool_use(sid: str, block: dict, verbosity: str) -> str:
    """Map one `tool_use` content block to a one-line inline summary.
    `verbosity` is "stream" or "debug" by the time this is called;
    debug allows wider truncation limits."""
    name = block.get("name", "?")
    inp = block.get("input", {}) or {}
    if name == "Read":
        return f"  [{sid} read] {inp.get('file_path', '?')}"
    if name == "Grep":
        path = inp.get("path", "")
        suffix = f" in {path}" if path else ""
        return f"  [{sid} grep] {inp.get('pattern', '?')}{suffix}"
    if name == "Glob":
        return f"  [{sid} glob] {inp.get('pattern', '?')}"
    if name == "Bash":
        cmd_lines = (inp.get("command") or "").splitlines()
        cmd = cmd_lines[0] if cmd_lines else ""
        # No truncation: a mid-cut shell command loses the part you
        # actually need to read (the operands at the end of a pipeline).
        # Multi-line scripts still show only the first line; the
        # per-worker .log file has the full command.
        return f"  [{sid} bash] {cmd}"
    if name in ("Write", "Edit", "NotebookEdit"):
        # NotebookEdit names its target `notebook_path`, not `file_path`, so
        # keying only on the latter logged a bare "?" for every notebook edit.
        # This was never latent: NotebookEdit has always been in the acting
        # workers' reported tool surface, and they run with
        # --dangerously-skip-permissions, so every real notebook edit has
        # logged "?" for as long as the summarizer has existed.
        path = inp.get("file_path") or inp.get("notebook_path") or "?"
        return f"  [{sid} {name.lower()}] {path}"
    if name == "WebFetch":
        return f"  [{sid} fetch] {inp.get('url', '?')}"
    if name == "WebSearch":
        return f"  [{sid} search] {inp.get('query', '?')}"
    if name == "StructuredOutput":
        # `input` is the worker's full structured payload. Only surface
        # at debug — at stream this is noise since the `done` line
        # follows immediately. Per-worker file has it whole regardless.
        if verbosity == "debug":
            return f"  [{sid}] finalizing output {str(inp)}"
        return None
    # Unknown / MCP tool — dump the full repr of the input. The
    # tail of an MCP-tool input (a Supabase query operand, a Stripe
    # API parameter) is where the useful detail lives; mid-cut
    # loses it. Per-worker .log file matches.
    return f"  [{sid} {name}] {str(inp)}"


def _summarize_stream_event(sid: str, event: dict, verbosity: str) -> str | None:
    """Return the one-line inline-log summary for one stream event, or
    None to drop the event from the inline log. The per-worker file
    always gets the raw event regardless of verbosity — this function
    only governs what surfaces inline.

    Levels in increasing detail: quiet, normal, stream, debug. At
    quiet/normal, individual events are dropped (leerie's existing
    phase / subtask-status log lines stand alone), with the one
    exception of result-with-error which surfaces at every level
    (clig.dev "errors emit at every level")."""
    t = event.get("type")
    sub = event.get("subtype")

    # quiet/normal: drop everything except worker-level errors.
    if verbosity in ("quiet", "normal"):
        if t == "result" and event.get("is_error"):
            n = event.get("num_turns", "?")
            return f"  [{sid}] worker failed ({sub}, turns={n})"
        return None

    # stream and debug: per-event summaries.
    if t == "system":
        if sub == "init":
            model = event.get("model", "?")
            return f"  [{sid}] starting (model={model})"
        # hook_started / hook_response are noisy (every SessionStart
        # hook fires once each); surface only at debug.
        if verbosity == "debug" and sub in ("hook_started", "hook_response"):
            hook_name = event.get("hook_name", "?")
            return f"  [{sid} hook] {sub} {hook_name}"
        return None

    if t == "assistant":
        msg = event.get("message", {})
        blocks = msg.get("content", []) or []
        lines = []
        for b in blocks:
            bt = b.get("type")
            if bt == "text":
                # First, inspect the text for a Claude Code session-limit /
                # rate-limit message. Detection here is load-bearing for
                # the text path of the limit: when the subscription limit
                # is hit, claude -p returns the session-limit string as
                # assistant text and then closes the session with
                # subtype="success" — without this check, _validate_result
                # would see a synthesized incomplete-handoff and the
                # `_retryable_failure` safety net would be the only
                # remaining defense. (The protocol-level path is handled
                # below in the rate_limit_event branch.) See DESIGN §6
                # *Cleanup on abnormal exit* for the auto-resume contract.
                text = b.get("text") or ""
                if (exc := _detect_session_limit(text)):
                    raise exc
                # Emit every non-empty line of the assistant's text as
                # its own [<sid> text] entry, full-width (no
                # truncation). Mid-cut sentences in earlier versions
                # ate the part the user actually wanted to read. The
                # per-worker .log file has the same content; this just
                # surfaces it inline too.
                for ln in text.splitlines():
                    ln = ln.strip()
                    if ln:
                        lines.append(f"  [{sid} text] {ln}")
            elif bt == "tool_use":
                tool_summary = _summarize_tool_use(sid, b, verbosity)
                if tool_summary is not None:
                    lines.append(tool_summary)
        return "\n".join(lines) if lines else None

    if t == "user":
        msg = event.get("message", {})
        for b in msg.get("content", []) or []:
            if b.get("type") != "tool_result":
                continue
            content_txt = _extract_tool_result_text(b).strip()
            if b.get("is_error"):
                # No truncation: a schema-validation failure or other
                # tool error names exactly the missing fields / the
                # rejection reason — the diagnostic information a user
                # needs to act. Mid-cut error messages drop the useful
                # detail. Multi-line errors (rare but possible) get the
                # `tool-fail` tag on line 1 and a width-matched
                # continuation prefix (keeping the sid) on lines 2+
                # so attribution survives parallel runs without
                # repeating the kind token on every line — see
                # _tag_each_line.
                #
                # When the failure carries an EAGAIN/fork signature, name
                # the real cause inline so a human reading the stream isn't
                # misled by a bare "Exit code 1" (DESIGN §6 *Detecting PID
                # exhaustion*). The authoritative kill decision is made by
                # `_read_stream`'s cgroup probe; this only relabels.
                if _is_fork_exhaustion(content_txt):
                    return _tag_each_line(
                        f"  [{sid} tool-fail: PID cap reached — worker "
                        f"subtree cannot fork]", content_txt)
                return _tag_each_line(f"  [{sid} tool-fail]", content_txt)
            # Successful tool results are file-only at stream; debug
            # gets the FULL content. The user opting into debug is
            # explicitly asking for raw worker output; truncating
            # defeats the level. A worker reading a large file will
            # flood the orchestrator log at debug — that's the
            # accepted trade-off. Multi-line content (a Read of a
            # source file, a Grep of code) gets the `tool-ok` tag
            # on line 1 and a width-matched continuation prefix
            # (keeping the sid) on lines 2+ so attribution survives
            # parallel runs without repeating the kind token on
            # every line.
            if verbosity == "debug":
                return _tag_each_line(f"  [{sid} tool-ok]", content_txt)
        return None

    if t == "rate_limit_event":
        info = event.get("rate_limit_info", {}) or {}
        # The actual Claude Code stream-json schema (verified from
        # captured worker logs 2026-05-27): the payload carries
        # `status` (observed values: "allowed", "allowed_warning"),
        # `resetsAt` (Unix timestamp seconds), `rateLimitType`,
        # `utilization` (float 0..1, present on warning events),
        # `surpassedThreshold` (the *threshold value crossed*, e.g.
        # 0.9 — NOT a boolean flag), `overageStatus`,
        # `overageDisabledReason`, `isUsingOverage`. The terminal
        # status value (when the limit is actually hit) is
        # Anthropic-internal and unobserved by us; we treat any
        # status not in the known-allowed set as terminal —
        # defensive against future status strings ("exceeded",
        # "denied", "blocked", etc.) without hardcoding a guess.
        status = info.get("status")
        if status is not None and status not in _RATE_LIMIT_ALLOWED_STATUSES:
            reset_at: datetime | None = None
            resets_at_ts = info.get("resetsAt")
            rate_limit_type = info.get("rateLimitType", "?")
            if isinstance(resets_at_ts, (int, float)):
                try:
                    reset_at = datetime.fromtimestamp(
                        resets_at_ts, tz=timezone.utc)
                except (OSError, ValueError, OverflowError):
                    reset_at = None
            raw = (f"rate_limit_event status={status} "
                   f"rateLimitType={rate_limit_type} "
                   f"resetsAt={resets_at_ts}")
            raise RateLimitedExit(reset_at=reset_at, raw_message=raw,
                                  limit_type=(
                                      rate_limit_type
                                      if isinstance(rate_limit_type, str)
                                      and rate_limit_type != "?"
                                      else None))
        # Surface threshold-crossings at stream; everything at debug.
        # The boolean-or-numeric `surpassedThreshold` field is a
        # threshold value (e.g. 0.9), not a boolean flag — truthy when
        # present and non-zero, which is the right "this is a
        # threshold-crossing event" signal for surfacing the warning.
        if info.get("surpassedThreshold") or verbosity == "debug":
            util_frac = float(info.get("utilization") or 0)
            util = int(util_frac * 100)
            return f"  [{sid}] rate-limit {status or '?'} (util={util}%)"
        return None

    if t == "result":
        n = event.get("num_turns", "?")
        if sub == "success":
            cost = float(event.get("total_cost_usd") or 0)
            return f"  [{sid}] done (turns={n}, cost=${cost:.4f})"
        return f"  [{sid}] failed ({sub}, turns={n})"

    # Unknown event type — surface only at debug; otherwise drop.
    if verbosity == "debug":
        return f"  [{sid} ?] {t}/{sub}"
    return None


def _format_progress_prefix(
        prog: tuple[int, int, int, int, int] | None) -> str:
    """Render the activity prefix from a `_get_progress` tuple, or "" when
    progress is None (pre-Phase-5 workers).

    Each non-zero counter becomes its own ` · `-separated segment; zero
    counters are omitted so the prefix never reads `0 subtasks anything`.
    `done` is always last so the eye follows rising progress on the right.
    See IMPLEMENTATION.md §Verbosity & log prefix for the rendering rules."""
    if prog is None:
        return ""
    running, in_conformer, done, wave_idx, wave_total = prog

    def plural(n: int) -> str:
        return "subtask" if n == 1 else "subtasks"

    segs = [f"wave {wave_idx} of {wave_total}"]
    if running:
        segs.append(f"running {running} {plural(running)}")
    if in_conformer:
        segs.append(f"{in_conformer} {plural(in_conformer)} in conformer")
    if done:
        segs.append(f"{done} {plural(done)} done")
    return f"[{' · '.join(segs)}] "


def _get_progress(st: "State") -> tuple[int, int, int, int, int] | None:
    """Return (running, in_conformer, done, wave_idx, wave_total) for the
    inline activity prefix (see IMPLEMENTATION.md §Verbosity & log prefix).

    Only meaningful once waves are scheduled — returns None before that so
    classifier/planner workers emit no prefix. Counts are restricted to the
    *current* wave's membership (`waves[completed_waves]`) so that "running 5
    subtasks" reads as "5 of this wave's implementers are in flight," not
    "5 of all subtasks across all waves." The wave index is 1-based for
    display (`completed_waves + 1`) so that the in-flight wave reads as
    `1 of 3` while wave 1 is running, not `0 of 3`.

    A subtask is:
      - running:      `subtask_status[sid]` absent or not in _TERMINAL_STATUSES
      - in_conformer: status == "complete" but `conformance[sid]` absent
                      (_settle_subtask writes that key exactly when the
                      advisory conformer phase finishes, so absence is a
                      precise live signal — DESIGN §9)
      - done:         status in _TERMINAL_STATUSES, and (if status ==
                      "complete") `conformance[sid]` is present.
                      `failed` / `blocked` are terminal regardless of
                      conformance — the conformer only runs on the success
                      path."""
    waves = st.data.get("waves")
    if not waves:
        return None
    completed = st.data.get("completed_waves", 0)
    if completed >= len(waves):
        return None
    wave = waves[completed]
    if not wave:
        return None
    statuses = st.data.get("subtask_status", {})
    conformance = st.data.get("conformance", {})
    running = in_conformer = done = 0
    for sid in wave:
        status = statuses.get(sid)
        if status not in _TERMINAL_STATUSES:
            running += 1
        elif status == "complete" and sid not in conformance:
            in_conformer += 1
        else:
            done += 1
    return running, in_conformer, done, completed + 1, len(waves)


# --- cgroup containment for worker subtrees (via the cgroup broker) ------
# Each `claude -p` worker (and every descendant it forks: bash children,
# vitest pools, webpack workers, tsc, etc.) is enrolled in its own child
# cgroup `leerie-w-<sid>` (run-scoped; see _cgroup_worker_sid). The
# cgroup's memory.max and pids.max bound how
# much RAM / how many PIDs the worker subtree may consume. When it exceeds
# memory.max the kernel OOM-kills inside that cgroup; when it exceeds
# pids.max further fork/clone in the subtree gets EAGAIN — sshd / pid 1 /
# sibling workers are unaffected. This is the fix for the cascade in
# DESIGN §6 Worker subtree termination, AND for the thread/PID-table
# exhaustion crash (Bun EAGAIN) that motivated the broker.
#
# THE BROKER, AND WHY (reproduced live — see DESIGN §6). Cgroup enforcement
# must be done by an identity that owns (or was delegated) the relevant
# subtree, not by the dropped-privilege orchestrator (non-root leerie
# rootful; a nested-userns-remapped identity rootless):
#   1. Migrating a task into a cgroup needs write on `cgroup.procs` of the
#      destination, the source, AND their common ancestor. Workers are born
#      in the container-runtime-owned scope; moving them into `leerie.slice`
#      crosses a cgroup the leerie user doesn't own → EACCES/EIO.
#   2. In the rootful case, even inside a delegated subtree the kernel keeps
#      controller limit files (`pids.max`, `memory.max`) owned by root when
#      the subtree was merely chowned rather than created by the delegatee —
#      so the leerie user can organize processes but not set limits.
# So `scripts/cgroup-broker.py` runs at that owning identity — real root
# rootful, the rootlesskit-mapped host UID rootless (which owns the
# systemd-delegated user slice; DESIGN §6 *Rootless exception*) — launched by
# container-entry.sh at PID 1 before the privilege drop, and performs
# create/enroll/destroy on the orchestrator's behalf over a descriptor this
# process inherits — one end of a socket pair, never a pathname (DESIGN §6
# *No leerie service is reachable by a path from a process it does not
# serve*). It handles cgroup v1 (Fly Firecracker VMs are v1/hybrid) vs v2
# (Colima) transparently. The
# functions below are thin socket clients; the public names/signatures are
# unchanged so `_invoke`'s call sites are untouched, except `_cgroup_create`
# now returns the sid (str) rather than a filesystem Path.

# The variable naming the broker's descriptor in the environment this process
# was started with (`scripts/cgroup-broker.py`'s `FD_ENV`), and the socket
# `_adopt_cgroup_broker` makes of it. None: no broker was handed to this
# process (a host, a test), and every request fails as an unreachable broker.
_CGROUP_BROKER_FD_ENV = "LEERIE_CGROUP_BROKER_FD"
_CGROUP_BROKER: socket.socket | None = None
_CGROUP_PROBE_RESULT: bool | None = None
_CGROUP_HIERARCHY: str | None = None  # "v2" / "v1" — set by a passing probe
# N18: must stay >= scripts/cgroup-broker.py's own `_DESTROY_DRAIN_TIMEOUT_SEC`
# (10.0s) -- a `destroy` request's own drain-then-rmdir loop can legitimately
# run for the broker's full budget on a large worker subtree (a conformer's
# test-suite process tree), and the broker keeps working toward that rmdir
# for the whole budget regardless of whether this client is still listening.
# `_cgroup_request`'s prior 5.0s default timeout was BELOW that budget, so a
# still-legitimately-draining destroy made the client give up and swallow a
# bare socket timeout (contextlib.suppress(OSError) in `_cgroup_destroy`,
# with no log line -- unlike a broker-reported `ERR ...`, which is logged).
# The broker itself still finishes the rmdir moments later off in its own
# single-threaded accept loop -- but nothing in the orchestrator was waiting
# for that any more, so run/container teardown was free to proceed and tear
# down the broker (PID 1) mid-drain. Because workers run with
# `--cgroupns=host`, the cgroup directory lives on the HOST cgroupfs and
# outlives the container, so a broker killed mid-drain permanently orphans
# the `leerie-w-<sid>` directory instead of merely delaying its removal --
# this is the N18 leak. Keep this in sync with cgroup-broker.py's constant;
# the margin covers scheduling/socket overhead beyond the broker's own
# monotonic deadline.
_CGROUP_DESTROY_TIMEOUT_SEC = 15.0


def _adopt_cgroup_broker() -> None:
    """Take the broker descriptor this process was handed, before it starts
    anything: made non-inheritable and its variable removed, so no worker
    or command leerie starts holds it or is told its number (DESIGN §6 *No
    leerie service is reachable by a path from a process it does not
    serve*). A descriptor that is not a unix `SOCK_SEQPACKET` socket is left
    alone and not used."""
    global _CGROUP_BROKER
    raw = os.environ.pop(_CGROUP_BROKER_FD_ENV, None)
    if raw is None or _CGROUP_BROKER is not None:
        return
    try:
        fd = int(raw)
        os.set_inheritable(fd, False)
        sock = socket.socket(fileno=fd)
    except (ValueError, OSError) as e:
        log(f"  the cgroup broker descriptor {raw!r} is unusable ({e}); "
            "worker containment will be OFF")
        return
    if sock.family != socket.AF_UNIX or sock.type != socket.SOCK_SEQPACKET:
        sock.detach()
        log(f"  descriptor {raw} is not the cgroup broker's; worker "
            "containment will be OFF")
        return
    # Bounds a send to a broker whose queue is full (it serves one request
    # at a time, and a `destroy` can take its whole drain budget).
    sock.settimeout(_CGROUP_DESTROY_TIMEOUT_SEC)
    _CGROUP_BROKER = sock


def _hand_cgroup_broker_to_exec() -> Callable[[], None]:
    """Make the broker descriptor survive an `os.execv` of this process
    (`_sleep_then_reexec`): inheritable, and named in the environment the
    new image adopts it from. Returns the undo, for an exec that failed."""
    sock = _CGROUP_BROKER
    if sock is None:
        return lambda: None
    os.set_inheritable(sock.fileno(), True)
    os.environ[_CGROUP_BROKER_FD_ENV] = str(sock.fileno())

    def undo() -> None:
        os.environ.pop(_CGROUP_BROKER_FD_ENV, None)
        os.set_inheritable(sock.fileno(), False)
    return undo


def _cgroup_request(payload: str, timeout: float = 5.0) -> str:
    """Send one request to the cgroup broker and return its response line
    (without trailing newline). The request is one message on the broker's
    descriptor, carrying a fresh socket the response comes back on, so
    concurrent requests (from `asyncio.to_thread`) never share a reply and
    one that times out leaves nothing behind for the next. Raises OSError
    if the broker is unreachable or the round-trip fails."""
    ctrl = _CGROUP_BROKER
    if ctrl is None:
        raise OSError(errno.ENOTCONN,
                      "no cgroup broker descriptor was handed to this process")
    mine, theirs = socket.socketpair(socket.AF_UNIX, socket.SOCK_STREAM)
    with mine:
        try:
            socket.send_fds(ctrl, [(payload + "\n").encode()],
                            [theirs.fileno()])
        finally:
            theirs.close()
        mine.settimeout(timeout)
        return mine.recv(4096).decode(errors="replace").strip()


def _cgroup_probe() -> bool:
    """Once-per-run probe, memoized in `_CGROUP_PROBE_RESULT`: does the
    cgroup broker exist AND can it round-trip a create+enroll+destroy of a
    throwaway cgroup? This is the true test of the path workers use — the
    old direct-write probe passed on hosts where non-root enrollment
    actually fails (the bug this replaced). A passing probe records the
    hierarchy (`v2`/`v1`) in `_CGROUP_HIERARCHY` for telemetry."""
    global _CGROUP_PROBE_RESULT, _CGROUP_HIERARCHY
    if _CGROUP_PROBE_RESULT is not None:
        return _CGROUP_PROBE_RESULT
    try:
        resp = _cgroup_request("probe")
    except OSError as e:
        log(f"  cgroup broker unreachable ({e.strerror or e}); worker "
            f"containment is OFF for this run. Check that "
            f"scripts/container-entry.sh (or the remote launch wrapper) "
            f"started scripts/cgroup-broker.py and handed its descriptor "
            f"to the orchestrator ({_CGROUP_BROKER_FD_ENV}).")
        _CGROUP_PROBE_RESULT = False
        return False
    if resp.startswith("OK"):
        parts = resp.split()
        _CGROUP_HIERARCHY = parts[1] if len(parts) > 1 else "unknown"
        _CGROUP_PROBE_RESULT = True
        return True
    log(f"  cgroup broker probe failed ({resp}); worker containment is "
        f"OFF for this run. The broker found no usable cgroup hierarchy "
        f"(no cgroup-v2 unified mount, no v1 pids+memory controller "
        f"mounts, or a read-only cgroupfs).")
    _CGROUP_PROBE_RESULT = False
    return False


def _cgroup_worker_sid(run_id: str | None, sid: str) -> str:
    """Compose the run-scoped cgroup sid handed to the broker.

    The broker names the cgroup `leerie-w-<sid>` under the shared VM slice
    `leerie.slice/`. With `--cgroupns=host` (required so the broker can
    enroll worker PIDs — DESIGN §6), every concurrent run's containers share
    that one physical slice, so a bare worker `sid` (`"classifier"`,
    `"smoke"`, every conformer/judge sid — none are unique across runs) would
    make two concurrent runs create/enroll/destroy the *same* cgroup. Since
    v2 `destroy` is `cgroup.kill=1` (SIGKILLs every enrolled process), one
    run's teardown would then SIGKILL another run's worker `claude -p` leader
    mid-stream (reproduced live: DESIGN §6 *Memory containment*, run-scoped
    cgroup name). Prefixing with a run-id discriminator makes each run's
    worker cgroups unreachable by any other run's teardown.

    `run_id` may be None (callers with no run context, e.g. tests) — then the
    bare sid is returned, preserving the pre-run-scope name. The 12-char
    prefix mirrors the existing `call_id[:8]` short-id idiom and stays well
    within the broker's `^[A-Za-z0-9._-]+$` validation: live run ids are
    container/machine ids (nerdctl 64-hex cid, Fly machine id, EC2 `i-...`
    instance id) or the literal `"replay"` — all hex/instance-id grammar,
    no `..`, no leading `-`/`.`. The launcher requires `--run-id` and
    `resolve_run_id` never synthesizes one, so no unsafe value reaches here."""
    if not run_id:
        return sid
    return f"{run_id[:12]}-{sid}"


def _cgroup_create(sid: str, memory_max_bytes: int,
                   pids_max: int) -> str | None:
    """Ask the broker to create a worker cgroup and set its caps. Returns
    the sid on success (the handle passed to `_cgroup_enroll`/
    `_cgroup_destroy`), None on any failure. Idempotent — re-spawning a
    worker with the same sid re-writes the caps.

    `sid` here is the run-scoped cgroup sid (see `_cgroup_worker_sid`), not
    the bare worker sid — so the same worker type in two concurrent runs
    maps to two distinct cgroups."""
    if not _cgroup_probe():
        return None
    try:
        resp = _cgroup_request(
            f"create {sid} {memory_max_bytes} {pids_max}")
    except OSError as e:
        log(f"  [{sid}] cgroup create failed ({e.strerror or e}); "
            f"worker runs uncapped")
        return None
    if resp == "OK":
        return sid
    log(f"  [{sid}] cgroup create rejected by broker ({resp}); "
        f"worker runs uncapped")
    return None


def _cgroup_enroll(sid: str, pid: int) -> str | None:
    """Ask the broker to migrate `pid` into the worker cgroup. Called
    immediately after the worker subprocess spawns. Returns None on
    success, or the broker's rejection/error text on failure. Failure
    logs but does not abort the worker — it simply runs in the parent
    cgroup (uncapped).

    The caller (`_invoke`) stashes this string so that if the SAME
    worker later crashes (e.g. exits nonzero, or produces no result
    event), the crash message can name the enroll failure as a probable
    contributing cause instead of leaving it a separate, seemingly-
    unrelated log line — see the incident this closes: run
    870cf82cdcd4c3df2c860b94c4608b63f4debf4f211c99cb1a2c5517c62cb9b4,
    where `cgroup enroll rejected by broker ... ProcessLookupError`
    (this function) and the CLI's own 3s-stdin-timeout crash (a few
    lines later in the same worker's stream) were logged as two
    apparently-unconnected events, with no link surfaced between them."""
    try:
        resp = _cgroup_request(f"enroll {sid} {pid}")
    except OSError as e:
        reason = str(e.strerror or e)
        log(f"  cgroup enroll failed for pid={pid}: {reason}")
        return reason
    if resp == "OK":
        return None
    log(f"  cgroup enroll rejected by broker for pid={pid}: {resp}")
    return resp


def _cgroup_destroy(sid: str | None) -> None:
    """Ask the broker to tear down the worker cgroup (kill any survivors,
    rmdir). Best-effort — nothing here raises — but every failure is logged:
    a broker-reported ERR (e.g. a lingering process kept the dir busy) and,
    since N18, a socket error or client timeout too. Both were previously
    indistinguishable from success on the socket path, which is what made
    the directory leak hard to attribute. Called from `_invoke`'s cleanup path on every
    exit (success, timeout, abort).

    Uses `_CGROUP_DESTROY_TIMEOUT_SEC` (not the 5.0s client default) so this
    call blocks at least as long as the broker's own drain-then-rmdir budget
    — see that constant's comment (N18) for why a shorter client timeout
    orphans the cgroup directory rather than merely delaying its removal."""
    if sid is None:
        return
    try:
        resp = _cgroup_request(f"destroy {sid}", timeout=_CGROUP_DESTROY_TIMEOUT_SEC)
    except OSError as e:
        # Previously a bare `contextlib.suppress(OSError)` around the whole
        # block, which swallowed this path with no log line at all — so a
        # destroy that hit the client timeout was indistinguishable from a
        # clean one, while a broker-reported ERR was logged. That asymmetry
        # is what made the directory leak hard to attribute: the docstring
        # claimed errors were "logged rather than silently discarded", and
        # for the socket path that was simply untrue.
        log(f"  [{sid}] cgroup destroy did not complete "
            f"({e.strerror or e}); dir may be leaked")
        return
    parts = resp.split()
    if not parts or parts[0] != "OK":
        log(f"  [{sid}] cgroup destroy failed ({resp}); dir may be leaked")
        return
    # `OK <pid>…`: what cgroup.kill killed. They are zombies of ours now,
    # and a daemon nobody tracked (a test database under `setsid`) would
    # otherwise stay one, its PID lock file blocking every restart (DESIGN
    # §6 *Zombie reaping*).
    _mark_reapable({int(p) for p in parts[1:] if p.isdigit()})


def _cgroup_stat(sid: str | None) -> tuple[int, int, int, int] | None:
    """Read-only probe of a worker cgroup's PID + memory-OOM counters via
    the broker's `stat` verb. Returns `(pids.current, pids.max,
    pids.events.max, memory.events.oom_kill)`, or None when the sid is
    None, containment is off (no broker / uncapped run), or the broker
    errors — callers must treat None as "cannot tell" and NOT infer
    exhaustion. `pids.max` is -1 when the cgroup is uncapped/unlimited;
    `pids.events.max` counts kernel fork denials (the broker reports 0 on
    v1 — where it is not read — so v1 detection falls back to current >=
    max). `oom_kill` counts times the kernel OOM-killer fired inside this
    cgroup (present on both v1 and v2 — DESIGN §6 *Detecting memory OOM*).
    Used by `_read_stream` to distinguish a PID-exhausted worker (whose
    every Bash call fails with EAGAIN) from a worker whose commands merely
    fail (DESIGN §6 *Detecting PID exhaustion*), and by `_invoke`'s
    no-envelope path to name a memory-OOM'd build instead of surfacing a
    bare missing-checkpoint error."""
    if sid is None:
        return None
    try:
        resp = _cgroup_request(f"stat {sid}")
    except OSError:
        return None
    parts = resp.split()
    if len(parts) == 5 and parts[0] == "OK":
        try:
            return (int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4]))
        except ValueError:
            return None
    return None


def _cgroup_peak(sid: str | None) -> tuple[int, int] | None:
    """`(memory peak bytes, pids peak)` of a cgroup via the broker's `peak`
    verb, -1 for a value the hierarchy does not keep (v1 has no pids peak)
    or could not read. None when the sid is None, containment is off or the
    broker errors — "cannot tell", never a measured zero."""
    if sid is None:
        return None
    try:
        resp = _cgroup_request(f"peak {sid}")
    except OSError:
        return None
    parts = resp.split()
    if len(parts) == 3 and parts[0] == "OK":
        try:
            return (int(parts[1]), int(parts[2]))
        except ValueError:
            return None
    return None


# --- spawn-held enrollment (DESIGN §6 *Enrollment holds the spawn*) -------
#
# A child is born in its parent's cgroup at fork time, so enrolling a process
# after it is already running races its own first forks. The process is
# therefore started as this gate: it blocks reading one byte from an
# inherited pipe, and the parent writes `1` only after the broker has
# enrolled the gate's pid. `exec` keeps the pid (and so the cgroup, the
# session and every inherited fd), and nothing forked before it. Any other
# byte, or EOF (the parent closed the pipe without releasing — it was
# cancelled), exits without running the command. `-I -S`: no site, no user
# environment, nothing imported that could fork first. Before the `exec` it
# gives back the default action of every signal Python ignored at startup,
# the shim's `PYTHON_IGNORED_SIGNALS`, as the shim's own child does (DESIGN
# §6 *A command leerie runs starts with the signal dispositions it would
# have outside leerie*): an unconfined command behind the gate would
# otherwise start with SIGPIPE ignored.
_SPAWN_GATE_TEMPLATE = (
    "import os,signal,sys\n"
    "fd=int(sys.argv[1])\n"
    "b=os.read(fd,1)\n"
    "os.close(fd)\n"
    "if b!=b'1':\n"
    "    os._exit(97)\n"
    "for n in {signals!r}:\n"
    "    if hasattr(signal,n):\n"
    "        signal.signal(getattr(signal,n),signal.SIG_DFL)\n"
    "try:\n"
    "    os.execvp(sys.argv[2],sys.argv[2:])\n"
    "except OSError as e:\n"
    "    sys.stderr.write('leerie spawn gate: %s: %s\\n'%(sys.argv[2],e))\n"
    "    os._exit(127)\n")


@functools.lru_cache(maxsize=1)
def _spawn_gate_src() -> str:
    """The spawn gate's program, resetting the shim's
    `PYTHON_IGNORED_SIGNALS` (one spelling of the set)."""
    return _SPAWN_GATE_TEMPLATE.format(
        signals=tuple(_landlock().PYTHON_IGNORED_SIGNALS))


# Exit status of a gate that was never released.
_SPAWN_GATE_REFUSED_RC = 97


def _spawn_held_argv(cmd: list[str]) -> tuple[list[str], int, int]:
    """Wrap `cmd` in the spawn gate. Returns `(argv, read_fd, write_fd)`:
    pass `read_fd` to the child (`pass_fds`), close it in the parent once
    spawned, enroll the child's pid, then `_release_spawn_gate(write_fd)`."""
    read_fd, write_fd = os.pipe()
    return ([sys.executable, "-I", "-S", "-c", _spawn_gate_src(),
             str(read_fd), *cmd], read_fd, write_fd)


def _release_spawn_gate(write_fd: int | None, *, run: bool = True) -> None:
    """Let the gated child `exec` its command (`run`), or refuse it (close
    without writing — the gate sees EOF and exits). Never raises: a child
    that already died leaves a pipe with no reader."""
    if write_fd is None:
        return
    if run:
        with contextlib.suppress(OSError):
            os.write(write_fd, b"1")
    with contextlib.suppress(OSError):
        os.close(write_fd)


def _close_fd(fd: int | None) -> None:
    if fd is not None:
        with contextlib.suppress(OSError):
            os.close(fd)


def _enforce_and_record_cgroup_containment(st: "State",
                                          allow_uncapped: bool) -> None:
    """Fail-closed containment gate + state recording, run once per run
    just before the first worker spawns (DESIGN §6 *Memory containment*).

    Probes the cgroup broker end-to-end (create+enroll+destroy round-trip),
    records `{enforced, hierarchy}` into `st.data` (merges — `st.data` is
    already loaded/seeded by the time this runs), then `die()`s if
    containment can't be enabled — unless the operator explicitly waived
    it with `--dangerously-allow-uncapped`, which downgrades to a loud
    warning. A silently-uncapped run is what let a runaway conformer
    subtree exhaust the VM thread table (the Bun EAGAIN crash), and the
    direct-write probe this replaced gave false positives on exactly the
    hosts where non-root enrollment fails.

    **Why here and not in `main()`:** this must run only on paths that
    actually spawn workers. `_run_phases`' resume branch short-circuits
    (returns) before this on already-completed / no-work runs — those
    spawn zero workers (the "host launcher pushes + opens the PR" flow),
    so gating them would `die()` spuriously on a containment-incapable
    host. Called at the two worker-guaranteed points (fresh + resumable
    resume) after `st.data` is populated and before the first worker
    (`phase_classify` on a fresh run, `phase_execute` on resume).

    Recording the outcome is deliberate: the crash that motivated the
    broker left NO artifact of the silent containment failure — persisting
    it in state.json makes it visible for post-mortems."""
    enforced = _cgroup_probe()
    st.data["cgroup_containment"] = {
        "enforced": enforced,
        "hierarchy": _CGROUP_HIERARCHY,
    }
    st.save()
    if enforced:
        return
    if allow_uncapped:
        log("  ⚠  WARNING: worker cgroup containment is OFF "
            "(--dangerously-allow-uncapped). Workers run without "
            "memory/PID limits; a runaway subtree can exhaust the VM "
            "thread/PID table. See DESIGN §6 Memory containment.")
        return
    die("worker cgroup containment could not be enabled — workers would "
        "run uncapped and a runaway subtree can exhaust the VM thread/PID "
        "table (the Bun EAGAIN crash). The cgroup broker "
        "(scripts/cgroup-broker.py, launched by container-entry.sh at "
        "PID 1) is down, or this host has no usable cgroup hierarchy / "
        "read-only cgroupfs, or — rootless — a host whose systemd doesn't "
        "delegate pids+memory into the per-session user slice (non-systemd "
        "init, or an older/overridden delegation config). See "
        "docs/INSTALL.md (cgroup delegation). "
        "To run anyway without containment, pass --dangerously-allow-uncapped "
        f"(or set {DANGEROUS_ALLOW_UNCAPPED_ENV}=1).")


# --- Multi-token OAuth rotation (DESIGN §6 *Multi-token rotation*) -------
#
# Structured data in, deterministic Python out — no LLM worker (§12,
# "prompts advisory, code enforces"). Both probe endpoints are
# UNDOCUMENTED and UNSTABLE; every function here is best-effort telemetry,
# never a hard gate — a probe failure must degrade to "use the
# current/first token and react to the next 429," never fail the run.

_TOKEN_PROBE_CACHE: dict[str, tuple[dict | None, float]] = {}

_TOKEN_PROBE_DRIFT_MARKER = "token-probe: endpoint contract drift"


def _token_fingerprint(token: str) -> str:
    """Short, non-reversible identifier for a token — for logs/telemetry
    only. NEVER log or persist the raw token itself (DESIGN §6 *Multi-token
    rotation* secrets hygiene)."""
    return hashlib.sha256(token.encode()).hexdigest()[:12]


def _parse_claude_cli_version_string() -> str:
    """Best-effort `claude-code/<version>` User-Agent value for Probe A —
    omitting a real User-Agent puts the request in an aggressively
    rate-limited bucket (persistent 429s; externally corroborated, not
    merely assumed). Falls back to a fixed placeholder version on any
    failure — the exact version number is not load-bearing, only the
    presence of a `claude-code/` prefixed User-Agent is."""
    try:
        r = subprocess.run(["claude", "--version"], capture_output=True,
                            text=True, timeout=10, check=False)
        m = re.match(r"(\d+\.\d+\.\d+)", (r.stdout or "").strip())
        if m:
            return m.group(1)
    except (OSError, subprocess.TimeoutExpired):
        pass
    return "0.0.0"


def _probe_token_usage_a(token: str) -> dict | None:
    """Probe A: GET /api/oauth/usage — zero inference cost, requires
    `user:profile` scope (403 for a `user:inference`-scoped setup-token,
    which is what leerie itself uses — caller falls back to Probe B).

    Returns a dict normalized to {five_hour_util, seven_day_util,
    resets_at, seven_day_opus_util, seven_day_sonnet_util} — utilization
    as a 0.0-1.0 fraction, resets_at as a datetime — or None on any
    failure (403 scope mismatch, transient, or contract drift; the caller
    falls back to Probe B on any None result, regardless of cause)."""
    req = urllib.request.Request(
        "https://api.anthropic.com/api/oauth/usage",
        headers={
            "Authorization": f"Bearer {token}",
            "anthropic-beta": "oauth-2025-04-20",
            "User-Agent": f"claude-code/{_parse_claude_cli_version_string()}",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            body = json.loads(resp.read())
    except urllib.error.HTTPError as e:
        if e.code == 403:
            return None  # scope mismatch — caller falls back to Probe B
        log(f"  token-probe: Probe A transient failure "
            f"(HTTP {e.code}) for token {_token_fingerprint(token)}")
        return None
    except (urllib.error.URLError, TimeoutError, json.JSONDecodeError,
            OSError) as e:
        log(f"  token-probe: Probe A transient failure "
            f"({type(e).__name__}) for token {_token_fingerprint(token)}")
        return None

    def _sub(obj: dict | None) -> float | None:
        if obj is None:
            return None
        return obj.get("utilization")

    five_hour = body.get("five_hour")
    seven_day = body.get("seven_day")
    if not isinstance(five_hour, dict) or not isinstance(seven_day, dict) \
            or "utilization" not in five_hour or "resets_at" not in five_hour \
            or "utilization" not in seven_day:
        log(f"  ⚠  {_TOKEN_PROBE_DRIFT_MARKER}: Probe A response missing "
            f"five_hour/seven_day.utilization or five_hour.resets_at "
            f"for token {_token_fingerprint(token)} — the undocumented "
            "endpoint may have changed shape; probe code needs review")
        return None

    try:
        resets_at = datetime.fromisoformat(five_hour["resets_at"])
    except (ValueError, TypeError):
        log(f"  ⚠  {_TOKEN_PROBE_DRIFT_MARKER}: Probe A five_hour.resets_at "
            f"is not a parseable ISO-8601 timestamp for token "
            f"{_token_fingerprint(token)}")
        return None

    return {
        "five_hour_util": five_hour["utilization"] / 100.0,
        "seven_day_util": seven_day["utilization"] / 100.0,
        "resets_at": resets_at,
        "seven_day_opus_util": (
            lambda u: None if u is None else u / 100.0
        )(_sub(body.get("seven_day_opus"))),
        "seven_day_sonnet_util": (
            lambda u: None if u is None else u / 100.0
        )(_sub(body.get("seven_day_sonnet"))),
    }


def _probe_token_usage_b(token: str) -> dict | None:
    """Probe B fallback: a minimal (max_tokens=1) /v1/messages call, reading
    the anthropic-ratelimit-unified-* response headers. Works for
    user:inference-scoped tokens (setup-tokens) where Probe A 403s.
    /v1/messages/count_tokens does NOT carry these headers — a real
    inference call is required (~1 output token cost).

    Returns the same normalized shape as _probe_token_usage_a (utilization
    0.0-1.0 fraction, resets_at as datetime) — Probe B's own headers use a
    DIFFERENT native representation (already-fractional utilization, Unix
    epoch seconds for reset) than Probe A's JSON body (0-100, ISO-8601);
    this function normalizes before returning so callers never need to
    know which probe produced a result. No opus/sonnet sublimit
    information is available from this probe."""
    payload = json.dumps({
        "model": "claude-haiku-4-5-20251001",
        "max_tokens": 1,
        "messages": [{"role": "user", "content": "."}],
    }).encode()
    req = urllib.request.Request(
        "https://api.anthropic.com/v1/messages",
        data=payload,
        method="POST",
        headers={
            "Authorization": f"Bearer {token}",
            "anthropic-beta": "oauth-2025-04-20",
            "anthropic-version": "2023-06-01",
            "User-Agent": f"claude-code/{_parse_claude_cli_version_string()}",
            "content-type": "application/json",
        },
    )
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            headers = resp.headers
    except urllib.error.HTTPError as e:
        # A non-2xx response carries no usable rate-limit data — always
        # return None here rather than falling through to parse e.headers,
        # which (unlike a successful response) is not guaranteed to carry
        # the anthropic-ratelimit-unified-* fields at all.
        if e.code == 401:
            log(f"  token-probe: token {_token_fingerprint(token)} "
                "rejected (401) — likely dead/expired")
        elif e.code not in (429,):
            log(f"  token-probe: Probe B transient failure "
                f"(HTTP {e.code}) for token {_token_fingerprint(token)}")
        return None
    except (urllib.error.URLError, TimeoutError, OSError) as e:
        log(f"  token-probe: Probe B transient failure "
            f"({type(e).__name__}) for token {_token_fingerprint(token)}")
        return None

    five_h = headers.get("anthropic-ratelimit-unified-5h-utilization")
    seven_d = headers.get("anthropic-ratelimit-unified-7d-utilization")
    five_h_reset = headers.get("anthropic-ratelimit-unified-5h-reset")
    if five_h is None or seven_d is None or five_h_reset is None:
        log(f"  ⚠  {_TOKEN_PROBE_DRIFT_MARKER}: Probe B response missing "
            f"anthropic-ratelimit-unified-* headers for token "
            f"{_token_fingerprint(token)} — the undocumented headers may "
            "have changed; probe code needs review")
        return None

    try:
        return {
            "five_hour_util": float(five_h),
            "seven_day_util": float(seven_d),
            "resets_at": datetime.fromtimestamp(
                int(five_h_reset), tz=timezone.utc),
            "seven_day_opus_util": None,
            "seven_day_sonnet_util": None,
        }
    except (ValueError, TypeError):
        log(f"  ⚠  {_TOKEN_PROBE_DRIFT_MARKER}: Probe B header values not "
            f"parseable as expected for token {_token_fingerprint(token)}")
        return None


def _probe_token_usage(token: str, cache_sec: int) -> dict | None:
    """Probe a token's remaining runway, trying Probe A first and falling
    back to Probe B on a 403 (scope mismatch). Results are cached per
    token fingerprint for at least `cache_sec` seconds — both start-of-run
    selection and mid-run failover share this cache, so a token whose
    result is still fresh is never re-probed (Probe A rate-limits
    aggressively per access token).

    Returns None if both probes fail — callers must treat this as "no
    data," not as an error; the caller's fallback is to proceed with the
    first token and rely on react-on-429."""
    fp = _token_fingerprint(token)
    cached = _TOKEN_PROBE_CACHE.get(fp)
    if cached is not None:
        result, ts = cached
        if time.monotonic() - ts < cache_sec:
            return result

    result = _probe_token_usage_a(token)
    if result is None:
        result = _probe_token_usage_b(token)

    _TOKEN_PROBE_CACHE[fp] = (result, time.monotonic())
    return result


def _rank_tokens(tokens: list[str], cache_sec: int) -> list[str]:
    """Rank tokens by remaining runway, most runway first.

    Score: min(1 - five_hour_util, 1 - seven_day_util), accounting for the
    seven_day_opus_util sublimit when present (`pr_reviewer` defaults to
    Opus and any worker can be overridden onto it, so a token near its Opus
    weekly cap has less usable runway than its aggregate suggests) — the effective score also
    incorporates (1 - seven_day_opus_util) when that field is populated.
    A None seven_day_opus_util means "no Opus usage recorded" (full
    runway), not "unknown" — it does not penalize the score. Ties are
    broken by furthest resets_at. A token whose probe failed entirely
    (as opposed to a populated result with a None sub-field) sorts last
    but remains eligible — this is a last-resort ranking, not a filter."""
    probed = {tok: _probe_token_usage(tok, cache_sec) for tok in tokens}

    def _score(tok: str) -> tuple[float, float, datetime]:
        result = probed[tok]
        if result is None:
            return (-1.0, 0.0, datetime.min.replace(tzinfo=timezone.utc))
        runway = min(1.0 - result["five_hour_util"],
                     1.0 - result["seven_day_util"])
        opus_util = result.get("seven_day_opus_util")
        if opus_util is not None:
            runway = min(runway, 1.0 - opus_util)
        resets_at = result.get("resets_at") or datetime.min.replace(
            tzinfo=timezone.utc)
        return (0.0, runway, resets_at)

    return sorted(tokens, key=_score, reverse=True)


def _parse_oauth_token_list(raw: str | None) -> list[str]:
    """Parse CLAUDE_CODE_OAUTH_TOKENS: comma-separated, trimmed, empty
    entries dropped. Mirrors the launcher's own parsing so orchestrator
    and launcher agree on what counts as "the token list." Returns []
    when raw is None/empty/whitespace-only."""
    if not raw:
        return []
    return [tok.strip() for tok in raw.split(",") if tok.strip()]


async def _rotate_oauth_token_or_raise(
        st: "State", caps: dict, *, known_reset_at: datetime | None,
        raw_message: str, retry_fn: Callable[[], Awaitable[dict]],
) -> dict | None:
    """Shared mid-run rotation logic for BOTH surfaces the active token's
    rate-limit condition can reach `claude_p` through (DESIGN §6
    *Multi-token rotation*):
      (a) an envelope-level failure (`_is_auth_or_quota_failure`), and
      (b) a `RateLimitedExit` raised out of `_invoke`'s streaming loop for
          the protocol-level `rate_limit_event` (the two are otherwise
          independent code paths that both need identical rotation
          behavior — factored here so it is written and tested once).

    If more than one token is configured: probes/ranks the OTHER tokens
    (excluding the active one); if one has runway, switches
    `active_oauth_token` and calls `retry_fn()` to get a fresh envelope
    — returns that envelope. If every token is currently rate-limited (or
    unprobeable), raises `RateLimitedExit` with whichever reset is
    soonest across `known_reset_at` (the caller's own live signal, e.g. a
    just-caught exception's `reset_at`, preferred over — but combined
    with — any fresher cached probe data) and the cached probe data for
    every configured token, including the active one.

    Returns `None` (no exception, no rotation) when 0 or 1 tokens are
    configured, or when no probe data exists for ANY token — the caller
    falls through to its own existing behavior in either case (never
    raises purely on a probe failure)."""
    oauth_tokens = _parse_oauth_token_list(
        os.environ.get("CLAUDE_CODE_OAUTH_TOKENS"))
    if len(oauth_tokens) <= 1:
        return None

    cache_sec = caps.get("token_probe_cache_sec",
                          DEFAULT_CAPS["token_probe_cache_sec"])
    active = st.data.get("active_oauth_token")
    others = [t for t in oauth_tokens if t != active]
    ranked = await asyncio.to_thread(_rank_tokens, others, cache_sec)
    winner = ranked[0] if ranked else None
    winner_probe = (_TOKEN_PROBE_CACHE.get(
        _token_fingerprint(winner), (None, 0.0))[0]
        if winner is not None else None)

    if winner_probe is not None and min(
            1.0 - winner_probe["five_hour_util"],
            1.0 - winner_probe["seven_day_util"]) > 0:
        # Rotate and retry immediately — no re-exec, no container restart.
        log(f"  token-probe: active token rate-limited — "
            f"rotating to {_token_fingerprint(winner)}")
        st.data["active_oauth_token"] = winner
        st.save()
        return await retry_fn()

    # Every token is currently rate-limited (or unprobeable). Pick
    # whichever resets soonest — including the active token itself, whose
    # own reset time prefers a live signal (known_reset_at, e.g. a
    # just-caught exception's reset_at) over its possibly-stale-or-absent
    # cache entry, since the active token is deliberately excluded from
    # the fresh probe/rank call above.
    candidates: list[tuple[str, datetime]] = []
    if known_reset_at is not None and active is not None:
        candidates.append((active, known_reset_at))
    for t in oauth_tokens:
        if t == active and known_reset_at is not None:
            continue  # already have a live signal for the active token
        cached = _TOKEN_PROBE_CACHE.get(_token_fingerprint(t), (None, 0.0))[0]
        if cached is not None and cached.get("resets_at") is not None:
            candidates.append((t, cached["resets_at"]))

    if not candidates:
        # No probe data for any token, no live signal either — fall
        # through unchanged to the caller's own existing behavior.
        return None

    soonest_token, soonest_reset = min(candidates, key=lambda pair: pair[1])
    if soonest_token != active:
        log(f"  token-probe: all tokens rate-limited — switching to "
            f"soonest-reset token {_token_fingerprint(soonest_token)}")
        st.data["active_oauth_token"] = soonest_token
        st.save()
    raise RateLimitedExit(reset_at=soonest_reset, raw_message=raw_message)


async def _select_active_oauth_token(st: "State", caps: dict) -> None:
    """Start-of-run smart token selection (DESIGN §6 *Multi-token
    rotation*). Only runs when CLAUDE_CODE_OAUTH_TOKENS is present in the
    environment — the singular-var-only path is entirely unaffected (no
    `active_oauth_token` is ever set, so `_invoke`'s active_token stays
    None and behavior is byte-identical to before this feature).

    Best-effort: if every probe fails, the first token in the list is
    selected and the run proceeds — this function never die()s."""
    tokens = _parse_oauth_token_list(os.environ.get("CLAUDE_CODE_OAUTH_TOKENS"))
    if not tokens:
        return
    cache_sec = caps.get("token_probe_cache_sec",
                          DEFAULT_CAPS["token_probe_cache_sec"])
    ranked = await asyncio.to_thread(_rank_tokens, tokens, cache_sec)
    winner = ranked[0]
    result = _TOKEN_PROBE_CACHE.get(_token_fingerprint(winner), (None, 0.0))[0]
    if result is not None:
        runway_5h = 1.0 - result["five_hour_util"]
        runway_7d = 1.0 - result["seven_day_util"]
        log(f"  token-probe: selected token {_token_fingerprint(winner)} "
            f"(5h runway {runway_5h:.0%}, 7d runway {runway_7d:.0%})")
    else:
        log(f"  token-probe: all probes failed — selected first token "
            f"{_token_fingerprint(winner)}, relying on react-on-429")
    st.data["active_oauth_token"] = winner
    st.save()


# --- I5: a worker writes only where it is granted ---------------------------
# DESIGN §6 *A worker writes only where it is granted (I5)*. The kernel
# (Landlock) enforces it: `_invoke` starts every worker through
# `scripts/landlock_exec.py` with the grants `_worker_grants` derives.
LANDLOCK_SCRIPT = ROOT / "scripts" / "landlock_exec.py"
# DESIGN §6 *A worker's commands cannot reach its CLI*: the shell a confined
# worker's CLI runs each Bash-tool command and hook through, named to the
# CLI in this variable. It runs the command in a Landlock domain nested in
# the worker's, which may not open the CLI's `/proc/<pid>/fd/1`.
WORKER_SHELL = ROOT / "scripts" / "worker-shell.py"
SHELL_PREFIX_ENV = "CLAUDE_CODE_SHELL_PREFIX"
# DESIGN §6 *The CLI's own git runs on leerie's terms*: the directory first on
# a confined worker's CLI's `PATH`, holding only `git`, which runs the CLI's
# own git calls nested and on leerie's addressing (`scripts/cli-git.py`) and a
# worker's own commands' git — marked by `worker-shell.py` — untouched.
CLI_GIT_BIN = ROOT / "scripts" / "cli-bin"
WORKER_COMMAND_ENV = "LEERIE_WORKER_COMMAND"
CLI_GIT_ENV = "LEERIE_CLI_GIT"
REAL_GIT_ENV = "LEERIE_REAL_GIT"


def _cli_git_env(tree: str | Path, path: str) -> dict[str, str]:
    """The environment that puts a confined worker's CLI's own git on
    leerie's terms in `tree` (DESIGN §6 *The CLI's own git runs on leerie's
    terms*): `CLI_GIT_BIN` first on `path`, the real git it stands in front
    of, and the arguments leerie's own git on `tree` takes
    (`_tree_git_args`): its repository named from leerie's layout, never the
    tree's `.git`, and leerie's pins. Not `_git_view`'s copies of the
    settings: they are outside every worker's grant, and the settings they
    copy are ones no worker writes (the system and global config) or ones
    put back before the worker starts (`_ready_tree_for_worker`)."""
    args = _tree_git_args(tree)
    path = os.pathsep.join(p for p in path.split(os.pathsep)
                           if p and os.path.realpath(p)
                           != os.path.realpath(CLI_GIT_BIN))
    real = shutil.which("git", path=path) or "/usr/bin/git"
    return {"PATH": os.pathsep.join([str(CLI_GIT_BIN), path]),
            REAL_GIT_ENV: os.path.realpath(real),
            CLI_GIT_ENV: json.dumps({"args": args, "env": {}})}


def _restore_git_pointer(tree: str | Path) -> bool:
    """Put back `tree`'s `.git` file when it no longer names the
    administrative directory leerie's layout gives it (`_run_tree_location`),
    so the next worker's own git finds the tree's repository, not one a
    worker before it made (DESIGN §6 *The CLI's own git runs on leerie's
    terms*; review round 22 isolation H1). A `.git` directory or link in its
    place is removed first; nothing is written through a link. True when it
    was rewritten; False for a tree outside every run, a ref-less clone
    (its `.git` is its own worker's), one leerie cannot locate, or one
    already right."""
    loc = _run_tree_location(tree)
    if not loc:
        return False
    common, admin, _run = loc
    if os.path.realpath(common) == os.path.realpath(admin):
        return False                        # a ref-less clone
    t = Path(os.path.realpath(tree))
    dot = t / ".git"
    try:
        st = os.lstat(dot)
    except FileNotFoundError:
        st = None
    if st is not None and stat.S_ISREG(st.st_mode):
        try:
            text = _read_text_beneath(t, dot, limit=READ_LIMIT_CONFIG)
        except OSError:
            text = ""
        if (text.startswith("gitdir: ") and os.path.realpath(
                text[len("gitdir: "):].strip()) == os.path.realpath(admin)):
            return False
    if st is not None:
        _remove_beneath(t, dot)
    _write_beneath(t, dot, f"gitdir: {admin}\n".encode(), mode=0o644,
                   make=False)
    return True


def _ready_tree_for_worker(tree: str | Path) -> list[str]:
    """Before a confined worker starts in `tree`: leerie's settings back over
    its repository's (`_restore_settings`) and its `.git` naming that
    repository (`_restore_git_pointer`), so nothing a worker before it chose
    in either reaches it or its CLI. Returns what was put back."""
    done = list(_restore_settings(tree))
    if _restore_git_pointer(tree):
        done.append(".git")
    return done


@functools.lru_cache(maxsize=1)
def _landlock() -> types.ModuleType:
    """`scripts/landlock_exec.py` as a module: its `abi()` and `MIN_ABI`
    are the one spelling of the requirement."""
    spec = importlib.util.spec_from_file_location("leerie_landlock",
                                                  LANDLOCK_SCRIPT)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _require_confinement(run_dir: Path, state_root: Path,
                         checkout: Path) -> None:
    """The one entry every invocation that runs a worker or a repository
    command passes through, before it starts any (DESIGN §6 *Fail closed, on
    every entry*): the kernel confines (`_require_landlock`), no grant on the
    checkout reaches the state root by a second name
    (`_require_state_root_apart`), and the runtime builds the held-out
    sandbox and isolation (`_require_heldout_sandbox`, which turns isolation
    on). `main()` calls it for a fresh run, `resume` and `--phase` alike; a
    resumed run used to skip the checks, so nothing it spawned was
    isolated."""
    _require_landlock()
    _require_state_root_apart(state_root, checkout)
    _require_heldout_sandbox(run_dir)
    _require_worker_view()


# A file only the worker root has (the image's worker stage writes it), so a
# command that finds it at `/` runs in the worker view.
_WORKER_ENV_MARK = "/.leerie-worker-env"


def _worker_home_extras(worker_root: Path,
                        home: Path = Path("/home/leerie"),
                        limit: int = 20) -> list[str]:
    """The paths beneath the worker root's `/home/leerie` (the confined
    commands' HOME) that the container's lacks: what a repository's
    Dockerfile installed there, which the worker view hides (`/home` is a
    container entry). Names only, no
    link followed; a directory both have is descended into, but not one the
    container mounts something on (an auth or cache mount owns it). `home`
    is the container's `/home/leerie` (a test passes its own). At most
    `limit` paths, each as the view would name it."""
    found: list[str] = []
    top = worker_root / "home" / "leerie"

    def walk(rel: str) -> None:
        w = top / rel if rel else top
        c = home / rel if rel else home
        if rel and os.path.ismount(c):
            return
        try:
            names = sorted(_listdir_beneath(worker_root, w))
        except OSError:
            return
        for n in names:
            if len(found) >= limit:
                return
            r = f"{rel}/{n}" if rel else n
            cp = c / n
            if not os.path.lexists(cp):
                found.append(f"/home/leerie/{r}")
            elif (_dir_beneath_exists(worker_root, w / n) and cp.is_dir()
                  and not cp.is_symlink()):
                walk(r)

    walk("")
    return found


def _require_worker_view() -> None:
    """Fail closed (DESIGN §6 *The orchestrator's root is leerie's; a
    repository's root is only a confined process's*): where the image has a
    worker root, an isolated command must run in it — leerie never runs the
    repository's commands in its own root instead, nor its own processes in
    the repository's. Runs `test -e` on the worker stage's mark in the
    worker view; stops the run naming the shim's reason when it is not
    there. Only once the entry has turned isolation on (`_isolated()`): a
    command enters the worker view only through the isolation, and where it
    is off (a test, a host harness) nothing runs in it.

    A run the launcher started on a repository image (`REPO_IMAGE_ENV` is
    "1") whose image has no worker root stops first, whatever the
    isolation: the image was built in an older layout or not by leerie,
    and its own root is the repository's (review round 29, execution L2).
    So does one whose worker root holds anything beneath `/home/leerie` the
    container's lacks (`_worker_home_extras`): `/home` is the run's
    own, and what a repository installed there would be missing from every
    confined command (review round 29, execution L3).
    """
    if os.environ.get(REPO_IMAGE_ENV) == "1" and _worker_root() is None:
        die(f"this run was started on a repository image, but the image has "
            f"no repository root ({WORKER_ROOT}): it was built in an older "
            "layout, or not by leerie, so its own root is the repository's. "
            "Rebuild the repository image (launch again: leerie rebuilds an "
            "image whose layout or base changed; on Fly, remove its lines "
            "from ~/.cache/leerie/published-tags.txt). Leerie runs its own "
            "processes only in its own root (DESIGN §6 *The orchestrator's "
            "root is leerie's; a repository's root is only a confined "
            "process's*).")
    wr = _worker_root()
    if wr is not None:
        extras = _worker_home_extras(Path(wr))
        if extras:
            die("the repository image installs under /home/leerie, which a "
                "confined command never sees: /home is the run's own (its HOME, "
                "caches and credentials), taken from the container, not "
                "from the repository's root. Found only in the repository's "
                f"root: {', '.join(extras)}. Install these elsewhere in "
                ".leerie/Dockerfile (beneath /opt or /usr/local, with an ENV "
                "PATH entry for any binaries) and launch again (DESIGN §6 "
                "*The orchestrator's root is leerie's; a repository's root "
                "is only a confined process's*).")
    if wr is None or not _isolated():
        return
    argv = _confined_argv(WorkerGrants(rw=("/dev/null",), ro=("/",)),
                          ["test", "-e", _WORKER_ENV_MARK], refusal_fd=None)
    try:
        r = subprocess.run(argv, cwd="/", stdin=subprocess.DEVNULL,
                           capture_output=True, text=True, timeout=60,
                           check=False)
    except (OSError, subprocess.SubprocessError) as e:
        die(f"the confinement check could not run a command in the "
            f"repository's root ({type(e).__name__}: {e}).")
    if r.returncode != 0:
        err = (r.stderr or "").strip()[-600:]
        die(f"this image has a repository root ({WORKER_ROOT}), but a "
            f"confined command did not run in it (exit {r.returncode}"
            f"{': ' + err if err else ''}). Rebuild the repository image "
            "(remove it with `nerdctl --namespace leerie image rm "
            "leerie-repo/<repo>-<checkout>:<version>`"
            " and launch again). Leerie runs the repository's commands only "
            "in the repository's root, and its own only in its own (DESIGN "
            "§6 *The orchestrator's root is leerie's; a repository's root is "
            "only a confined process's*).")


MOUNTINFO = Path("/proc/self/mountinfo")


def _mountinfo_unescape(field: str) -> str:
    """A mountinfo path field, its octal escapes (`\\040` for a space)
    decoded."""
    return re.sub(r"\\([0-7]{3})", lambda m: chr(int(m.group(1), 8)), field)


def _disk_place(path: Path) -> tuple[str, str]:
    """Where `path` is on disk: the device and the path within its
    filesystem, from the `/proc/self/mountinfo` line of the mount holding
    its real path (the longest mount point at or above it; of equal ones the
    last, which is the mount on top). Two names of one directory — a bind
    mount of it, and its path under another mount of the same filesystem —
    have one place. Without a readable mountinfo the place is the real path."""
    real = os.path.realpath(path)
    best: tuple[int, str, str] | None = None
    try:
        lines = MOUNTINFO.read_text().splitlines()
    except OSError:
        return ("", real)
    for line in lines:
        f = line.split(" ")
        if len(f) < 5:
            continue
        dev, root, point = f[2], _mountinfo_unescape(f[3]), \
            _mountinfo_unescape(f[4])
        if real != point and not real.startswith(point.rstrip("/") + "/"):
            continue
        if best is None or len(point) >= best[0]:
            rest = real[len(point.rstrip("/")):]
            best = (len(point), dev, root.rstrip("/") + rest or "/")
    if best is None:
        return ("", real)
    return (best[1], os.path.normpath(best[2]))


def _nested(a: str, b: str) -> bool:
    """`a` is `b` or beneath it, or `b` beneath `a`."""
    a, b = a.rstrip("/") or "/", b.rstrip("/") or "/"
    return (a == b or a.startswith(b.rstrip("/") + "/")
            or b.startswith(a.rstrip("/") + "/"))


def _require_state_root_apart(state_root: Path, checkout: Path) -> None:
    """Stop the run when the state root has a second name through the
    checkout (DESIGN §6 *No host path comes from a repository*, part 3).
    Every grant is carved by path: `_around` takes the state root out of a
    grant whose path contains it. A state root that is the checkout's
    directory under another mount — `/leerie-state` bind-mounted from
    `<checkout>/.lstate`, which `/work` shows too — is contained by no
    grant's path, so every worker's read of `/work` reached the held-out sets
    and the credentials' copies. A state root that holds the checkout under a
    second name makes the checkout writable through it. The places on disk
    are compared (`_disk_place`), and their nesting must be the paths'."""
    s_dev, s_place = _disk_place(state_root)
    c_dev, c_place = _disk_place(checkout)
    on_disk = s_dev == c_dev and _nested(s_place, c_place)
    by_path = _nested(os.path.realpath(state_root),
                      os.path.realpath(checkout))
    if on_disk and not by_path:
        die(f"the state root {state_root} and the checkout {checkout} are "
            f"one directory tree on disk ({s_place} and {c_place}) under "
            "two names, so the checkout's mount would show every worker the "
            "run's state, or the state root's would hold the checkout "
            "writable. Keep the state root outside the checkout: set "
            "--state-dir or LEERIE_STATE_DIR to a directory neither inside "
            "nor above it (DESIGN §6 *No host path comes from a "
            "repository*).")


def _require_landlock() -> None:
    """Fail closed (DESIGN §6 *A worker writes only where it is granted*):
    no worker runs when the kernel cannot confine it."""
    lk = _landlock()
    v = lk.abi()
    if v < lk.MIN_ABI:
        die(f"this kernel cannot confine leerie's workers: its Landlock ABI "
            f"is {v or 'absent'}, and leerie needs {lk.MIN_ABI} or later "
            "(Linux 6.2+ with `landlock` in the active LSMs, "
            "/sys/kernel/security/lsm). Leerie never runs a worker "
            "unconfined (DESIGN §6 *A worker writes only where it is "
            "granted*; docs/INSTALL.md).")


# Set by `_require_heldout_sandbox` once the invocation's entry
# (`_require_confinement`) has built a sandbox in this process: from then on
# every confined spawn here, and in the processes it starts
# (`scripts/worker-guard.py`), is isolated (DESIGN §6 *Every confined process
# has its own `/tmp`, `/dev/shm` and IPC*). Unset where no entry ran (a test,
# a host harness): nothing is isolated there.
ISOLATE_ENV = "LEERIE_ISOLATED"
SANDBOX_PROBE_SCRIPT = ROOT / "scripts" / "sandbox_probe.py"
_SANDBOX_PROBE_DIRNAME = "sandbox-probe"


def _isolated() -> bool:
    return os.environ.get(ISOLATE_ENV) == "1"


# The shim's failure lines (mechanical: its own `IsolationError` steps and
# errno names), each mapped to the runtime fix that removes it.
_SANDBOX_FIXES: tuple[tuple[str, str], ...] = (
    (r"no seccomp table|no pivot_root number",
     "this machine's architecture has no seccomp table in "
     "scripts/landlock_exec.py (x86_64 and aarch64 have one)"),
    (r"unshare\(CLONE_NEWUSER\): EPERM",
     "the container's seccomp profile refuses a user namespace: run it with "
     "`--security-opt seccomp=unconfined` (the launcher passes it on every "
     "local run; the shim's own filter takes back what the profile refused)"),
    (r"unshare\(CLONE_NEWUSER\): (EINVAL|ENOSPC|EUSERS|ENOSYS)",
     "the kernel offers no unprivileged user namespaces "
     "(CONFIG_USER_NS, user.max_user_namespaces)"),
    (r"write setgroups: EACCES|write [ug]id_map: EPERM",
     "the host restricts unprivileged user namespaces "
     "(kernel.apparmor_restrict_unprivileged_userns) and this process is "
     "not under the `leerie-container` AppArmor profile, which allows them"),
    (r"unshare\(mount/IPC/net[^)]*\): (EPERM|EINVAL|ENOSPC)|bring up lo|"
     r"relay listen",
     "the runtime refuses a network namespace (or its loopback) inside the "
     "shim's user namespace: every confined process needs one (DESIGN §6 "
     "*A confined process has its own network*); on Fly, EC2 or Colima the "
     "guest kernel must offer `CONFIG_NET_NS` to unprivileged user "
     "namespaces"),
    (r"overlay .*: EINVAL",
     "the state root's filesystem cannot be an overlay's lower layer in a "
     "user namespace"),
    (r": EACCES",
     "AppArmor refuses the sandbox's mounts: the container must run under "
     "the `leerie-container` profile — load it once (`sudo install -m 0644 "
     "scripts/apparmor/leerie-container /etc/apparmor.d/leerie-container && "
     "sudo apparmor_parser -r -W /etc/apparmor.d/leerie-container`; on "
     "Colima through `colima ssh`), and the launcher passes "
     "`--security-opt apparmor=leerie-container`"),
)


def _sandbox_fix(stderr: str) -> str:
    """The runtime fix for the shim's isolation failure in `stderr`."""
    for pattern, fix in _SANDBOX_FIXES:
        if re.search(pattern, stderr):
            return fix
    return ("see the shim's message above; DESIGN §6 *A held-out evaluation "
            "runs alone* lists what the runtime must allow")


def _require_heldout_sandbox(run_dir: Path) -> None:
    """Fail closed (DESIGN §6 *A held-out evaluation runs alone, in a world
    that dies with it (I3)*): build a held-out sandbox over a probe beneath
    the run directory and check each property; stop the run naming the fix
    when one fails. On success every later confined spawn is isolated
    (`ISOLATE_ENV`)."""
    probe = Path(run_dir) / _SANDBOX_PROBE_DIRNAME
    if probe.exists():
        _rmtree_owned(probe)
    view = probe / "view"
    view.mkdir(parents=True)
    (view / "tree.txt").write_text("tree\n")
    held = probe / "set.txt"
    held.write_text("held-out\n")
    ro_file = probe / "ro.txt"
    ro_file.write_text("ro\n")
    nonce = uuid.uuid4().hex[:12]
    marks = [Path("/tmp") / f".leerie-probe-{nonce}",
             Path("/dev/shm") / f".leerie-probe-{nonce}"]
    for m in marks:
        try:
            m.write_text("outside\n")
        except OSError:
            pass
    rel = "probe/placed.txt"
    # The probe reads everything (`/`) and writes only its view and
    # /dev/null; nothing in the run directory but the probe's own directory
    # is named for writing.
    grants = WorkerGrants(rw=("/dev/null", str(view)), ro=("/",))
    r: subprocess.CompletedProcess | None = None
    raw = b""
    placed_on_disk = False
    try:
        with tempfile.TemporaryFile(dir=str(probe)) as rep:
            argv = _confined_argv(
                grants,
                [sys.executable, "-I", "-S", str(SANDBOX_PROBE_SCRIPT),
                 str(ro_file), rel, *[str(m) for m in marks]],
                sandbox=HeldOutSandbox(view=str(view),
                                       place=((str(held), rel),),
                                       report=str(view / "report.json")),
                report_fd=rep.fileno(), worker_root=False, refusal_fd=None)
            r = subprocess.run(argv, cwd=str(view), stdin=subprocess.DEVNULL,
                               capture_output=True, text=True, timeout=60,
                               pass_fds=(rep.fileno(),))
            rep.seek(0)
            raw = rep.read()
        placed_on_disk = (view / rel).exists()
    except (OSError, subprocess.SubprocessError) as e:
        _rmtree_owned(probe)
        die("the confinement check every entry runs (`_require_confinement`) "
            f"could not run the held-out sandbox probe "
            f"({type(e).__name__}: {e}); leerie never runs a held-out file "
            "outside a sandbox (DESIGN §6 *A held-out evaluation runs "
            "alone*).")
    finally:
        for m in marks:
            try:
                m.unlink()
            except OSError:
                pass
    _rmtree_owned(probe)
    runtime = os.environ.get("LEERIE_RUNTIME", "local")
    fly = (" On Fly the guest kernel must offer this; until it does, Fly "
           "runs do not start." if runtime == "fly" else "")
    if r.returncode != 0 or not raw:
        err = (r.stderr or "").strip()[-600:]
        die(f"this runtime cannot build the held-out sandbox (exit "
            f"{r.returncode}): {err or 'no report'}. Fix: "
            f"{_sandbox_fix(err)}.{fly} Leerie never runs a held-out file "
            "outside a sandbox, nor a confined process outside its "
            "isolation (DESIGN §6 *A held-out evaluation runs alone, in a "
            "world that dies with it (I3)*; docs/INSTALL.md).")
    try:
        got = json.loads(raw)
    except ValueError:
        got = {}
    failed = _sandbox_probe_failures(got, placed_on_disk)
    if failed:
        die("the held-out sandbox this runtime built is not isolated: "
            + "; ".join(failed) + f".{fly} Leerie never runs a held-out "
            "file outside a sandbox (DESIGN §6 *A held-out evaluation runs "
            "alone*).")
    _require_egress_relay()
    os.environ[ISOLATE_ENV] = "1"


def _sandbox_probe_failures(got: dict, placed_on_disk: bool) -> list[str]:
    """The properties `scripts/sandbox_probe.py` reported that a sandbox
    must have and did not, each named."""
    out = []
    try:
        own_ipc = os.readlink("/proc/self/ns/ipc")
    except OSError:
        own_ipc = None
    if not got.get("ipc_ns") or got.get("ipc_ns") == own_ipc:
        out.append("its IPC namespace is the orchestrator's")
    if got.get("interfaces") != ["lo"]:
        out.append(f"its interfaces are {got.get('interfaces')!r}, not only lo")
    if got.get("tmp_private") is not True:
        out.append("its /tmp is not its own")
    if got.get("shm_private") is not True:
        out.append("its /dev/shm is not its own")
    if got.get("erofs") is not True:
        out.append("a file in an inherited mount is writable "
                   f"({got.get('erofs')!r}, not EROFS)")
    if got.get("add_key") is not True:
        out.append(f"add_key is allowed ({got.get('add_key')!r}, not EPERM)")
    if got.get("placed") is not True:
        out.append("the placed file is not in the view")
    if placed_on_disk:
        out.append("the placed file reached the tree on disk")
    return out


# What `_require_egress_relay` runs inside an isolated namespace with
# `--egress`: ask the egress proxy (through the relay the shim set
# `HTTPS_PROXY` to) to CONNECT to a loopback address, then try the
# orchestrator's own loopback listener directly. One line of JSON.
_EGRESS_RELAY_PROBE = r"""
import errno, json, os, socket, sys
out = {}
try:
    u = os.environ["HTTPS_PROXY"].rsplit("/", 1)[-1].rsplit("@", 1)[-1]
    host, port = u.rsplit(":", 1)
    s = socket.create_connection((host, int(port)), timeout=20)
    s.sendall(b"CONNECT 127.0.0.1:" + sys.argv[1].encode()
              + b" HTTP/1.1\r\nHost: x\r\n\r\n")
    out["proxy"] = s.recv(4096).split(b"\r\n", 1)[0].decode("latin-1")
    s.close()
except Exception as e:
    out["proxy"] = "error: " + type(e).__name__ + ": " + str(e)
try:
    socket.create_connection(("127.0.0.1", int(sys.argv[1])),
                             timeout=5).close()
    out["outer_loopback"] = "reached"
except OSError as e:
    out["outer_loopback"] = errno.errorcode.get(e.errno, str(e.errno))
print(json.dumps(out))
"""


def _require_egress_relay() -> None:
    """Fail closed (DESIGN §6 *A confined process has its own network*):
    run an isolated process with `--egress` and check that it reaches the
    egress proxy through its relay, that the proxy refuses a loopback
    destination, and that a listener on the orchestrator's own loopback is
    not reachable from its namespace; stop the run naming what failed."""
    proxy = _egress_server()
    lst = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    try:
        lst.bind(("127.0.0.1", 0))
        lst.listen(1)
        port = lst.getsockname()[1]
        # The refusal the probe asks for is expected: not logged.
        proxy._refused.add(("127.0.0.1", port))
        argv = [sys.executable, "-I", "-S", str(LANDLOCK_SCRIPT), "--isolate",
                "--egress", str(proxy.socket_path), "--rw", "/dev/null",
                "--ro", "/", "--", sys.executable, "-I", "-S", "-c",
                _EGRESS_RELAY_PROBE, str(port)]
        try:
            r = subprocess.run(argv, cwd="/", stdin=subprocess.DEVNULL,
                               capture_output=True, text=True, timeout=60)
        except (OSError, subprocess.SubprocessError) as e:
            die("the confinement check every entry runs "
                "(`_require_confinement`) could not run the network probe "
                f"({type(e).__name__}: {e}); leerie never starts a confined "
                "process on the container's network (DESIGN §6 *A confined "
                "process has its own network*).")
    finally:
        lst.close()
    try:
        got = json.loads(r.stdout.strip().splitlines()[-1])
    except (ValueError, IndexError):
        got = {}
    failed = []
    if not str(got.get("proxy", "")).startswith("HTTP/1.1 403"):
        failed.append("the egress proxy was not reached through the relay, "
                      f"or did not refuse a loopback destination "
                      f"({got.get('proxy')!r})")
    if got.get("outer_loopback") != "ECONNREFUSED":
        failed.append("the orchestrator's loopback was "
                      f"{got.get('outer_loopback')!r} from a confined "
                      "process's namespace, not refused")
    if r.returncode != 0 or failed:
        err = (r.stderr or "").strip()[-600:]
        die(f"this runtime cannot give a confined process a network of its "
            f"own (exit {r.returncode}): "
            + ("; ".join(failed) or "no report") + (f" — {err}" if err
                                                    else "")
            + f". Fix: {_sandbox_fix(err)}. Leerie never starts a confined "
            "process on the container's network (DESIGN §6 *A confined "
            "process has its own network*).")


class HeldOutSandbox(NamedTuple):
    """A held-out run's sandbox (DESIGN §6 *A held-out evaluation runs
    alone*): `view` is overlaid, each `place` pair (absolute source, path
    relative to `view`) copied into the overlay, and `report` — the path
    the runner writes its report to, inside the sandbox — copied out to the
    descriptor `_confined_argv` is given. `replace` pairs are written over
    the view's own regular file and `remove` paths deleted from the overlay:
    an existing test run in its base form, in place of its final form
    (DESIGN §8 *What an existing test pins on the base holds on the tree
    that ships*)."""
    view: str
    place: tuple[tuple[str, str], ...] = ()
    report: str | None = None
    replace: tuple[tuple[str, str], ...] = ()
    remove: tuple[str, ...] = ()


class WorkerGrants(NamedTuple):
    """What a worker's processes may write (`rw`, read too) and read
    (`ro`), as absolute paths. `env`: the `(name, value)` pairs that point
    the command's temp and caches at its grants, laid over its environment
    last (a measurement's, `_measurement_grants`); a worker's is empty,
    `claude_p` names its directories itself. `/tmp` and `/dev/shm` are
    never named here but as devices: an isolated process's own are added by
    the shim (DESIGN §6 *Every confined process has its own `/tmp`,
    `/dev/shm` and IPC*). `egress`: the process reaches the outside network,
    through leerie's egress proxy only (a worker, an install kind); without
    it an isolated process has its own loopback and nothing else (DESIGN §6
    *A confined process has its own network*). `link`: the run's trees
    directory (`<run-dir>/worktrees`), whose write grants the shim binds as
    one mount so a tree links from its store; empty, every grant is bound
    apart (DESIGN §6 *The write grants on one mount are one mount*)."""
    rw: tuple[str, ...]
    ro: tuple[str, ...]
    env: tuple[tuple[str, str], ...] = ()
    egress: bool = False
    link: str = ""


# The caps key that marks the host-side seam, set only by
# `_resolve_host_seam_settings` (`run_rebaser`, `run_recapture_deps`): its
# workers run on the user's host, are not run workers, and macOS has no
# Landlock (DESIGN §6 *Outside the container*). A key of the call's own caps,
# never process state, so nothing else ever inherits it.
HOST_SEAM_CAP = "_host_seam"

# What every host-side CLI carries besides the shared containment (the
# rebaser and host recapture through `claude_p`; the launcher's
# `config --chat` the same flags, pinned equal by a test): it is handed a
# checkout or a tree by `--add-dir`, from which the CLI loads skills,
# commands and agents, and with HOST_CLI_ENV_PIN's variable set the tree's
# CLAUDE.md (DESIGN §6 *The host never runs a program the checkout chose*,
# part 4; review round 28 C1, C2). `--setting-sources user` is what stops
# the `--add-dir` loading (measured, CLI 2.1.316); the rest is a second
# layer that does not rest on that one CLI behaviour.
HOST_CLI_ARGS = ("--setting-sources", "user", "--disable-slash-commands",
                 "--strict-mcp-config")
HOST_CLI_DENIED_TOOLS = ("Agent", "Task", "Skill")
HOST_CLI_ENV_PIN = {"CLAUDE_CODE_ADDITIONAL_DIRECTORIES_CLAUDE_MD": "0"}

# The device nodes a confined process opens, and the only paths of `/dev`
# any grant names (`_reads_outside` leaves `/dev` out): never a terminal
# but `/dev/tty`, which names nothing once the shim has left its
# controlling terminal (DESIGN §6 *No confined process holds or can open
# the operator's terminal*). `/dev/shm` holds POSIX semaphores and shared
# memory (Python's multiprocessing locks and Chromium need it, measured);
# an isolated process's is its own, which the shim maps it to (DESIGN §6
# *Every confined process has its own `/tmp`, `/dev/shm` and IPC*). A
# pseudo-terminal (`/dev/ptmx`, `/dev/pts`) is granted by the shim with the
# isolated process's own `devpts`, never the container's, which holds the
# operator's pty.
_WORKER_DEVICES = ("/dev/null", "/dev/zero", "/dev/full", "/dev/random",
                   "/dev/urandom", "/dev/tty", "/dev/shm")
# Left out of every read grant `_reads_outside` makes: the container's
# `/dev` holds the operator's terminal (`/dev/console` under `nerdctl run
# -it`, its `devpts`), and a read-only descriptor of it reads keystrokes and
# sets the terminal's modes (review round 33 isolation Q1).
_DEV = Path("/dev")

# The variables that name a worker's own directories, its temp dir and CLI
# config (`_worker_dirs`). Each is granted only when it names a path beneath
# `<run-dir>/workers/` (`WORKERS_DIR`), where the run makes a worker's own
# (DESIGN §6): a variable left at a shared default (`/tmp`, `~/.claude`)
# grants nothing. The run's download caches are granted as the one
# directory a worker's set lives in (`_worker_cache_dir`, `_worker_cache_env`):
# `WORKER_CACHE_DIR` for the fixers' side, `HELD_OUT_CACHE_DIR` for the
# held-out side (`HELD_OUT_LOG_WORKERS`), never both, so nothing a held-out-side
# worker's processes leave in a cache reaches a fixer (DESIGN §8 *Nothing a
# held-out evaluation produces reaches a fixer*).
_WORKER_ENV_DIRS = ("TMPDIR", "TMP", "TEMP", "CLAUDE_CODE_TMPDIR",
                    "CLAUDE_CONFIG_DIR")
WORKER_CACHE_DIR = "cache"
HELD_OUT_CACHE_DIR = "cache-held-out"

# Workers that commit, and so write their tree's git metadata.
_COMMITTING_WORKERS = frozenset({
    "implementer", "conformer", "integrator", "acceptance_writer",
    "surrogate_fixer", "falsifier", "rebaser"})
# Workers whose prompt reads the run's subtask specs and notes.
_RUN_NOTES_READERS = frozenset({"implementer", "conformer", "integrator"})
# The files the task references, copied at plan time into `<run-dir>/task-files/`
# and read by `_RUN_NOTES_READERS` (DESIGN §6 *A report the task names is read,
# not searched for*): a worker's tree holds committed code, so an untracked
# report is in none of them, and no tree it commits from may be given one (I1).
TASK_FILES_DIRNAME = "task-files"
# Where an implementer keeps its success-criteria notes and checkpoint:
# `<run-dir>/notes/<subtask-id>/`, its own directory, so a grant can name
# it before either file exists.
NOTES_DIRNAME = "notes"
# Every log of the held-out side, under `<run-dir>/logs/held-out/` (DESIGN §8
# *Nothing a held-out evaluation produces reaches a fixer*): leerie's runs of
# set files, whose output the evaluated code writes, and the transcripts of
# the workers that read a set or run its files. Nothing that builds a
# worker's input reads this directory.
HELD_OUT_LOGS_DIRNAME = "held-out"
HELD_OUT_LOG_WORKERS = frozenset({"acceptance_writer", "set_auditor",
                                  "scope_judge", "falsifier"})


def _worker_cache_dir(run_dir: str | Path, schema_key: str) -> Path:
    """The cache set of a worker of kind `schema_key`: the held-out side's
    own for a worker that reads a set or runs one (`HELD_OUT_LOG_WORKERS`),
    else the fixers' side's, both in the stores' home beside the trees
    (`_stores_home`), so a tree links from them."""
    return (_stores_home(run_dir)
            / (HELD_OUT_CACHE_DIR if schema_key in HELD_OUT_LOG_WORKERS
               else WORKER_CACHE_DIR))


def _granted_cache_dir(grants: "WorkerGrants | None",
                       run_dir: str | Path) -> Path:
    """The cache set `grants` writes: the held-out side's when the grant
    names it, else the fixers' side's. The worker's environment is pointed
    at this one (`_invoke`), so the variables follow the grant."""
    held = _stores_home(run_dir) / HELD_OUT_CACHE_DIR
    if grants is not None and any(
            os.path.realpath(p) == os.path.realpath(held)
            for p in grants.rw):
        return held
    return _stores_home(run_dir) / WORKER_CACHE_DIR


def _held_out_logs(run_dir: str | Path) -> Path:
    return Path(run_dir) / "logs" / HELD_OUT_LOGS_DIRNAME


# Worker transcripts live in their own directory under a log directory,
# `<logs>/transcripts/<sid>.log`, where only `_invoke` writes; leerie's runs
# of the repository's commands write beside it, in `<logs>/` itself, never
# in it. So no command's output path can name a transcript, whatever the
# two names are (DESIGN §8 *What a worker ran is read from its own
# transcript*). When the two shared `<logs>/<name>.log`, the acceptance
# writer's transcript and its set's validation run were one file.
TRANSCRIPTS_DIRNAME = "transcripts"


def _transcripts_dir(log_dir: str | Path) -> Path:
    """The transcripts directory of log directory `log_dir`: `logs/` or
    `logs/held-out/`. The one place it is named."""
    return Path(log_dir) / TRANSCRIPTS_DIRNAME


def _worker_log_path(run_dir: str | Path, sid: str, schema_key: str) -> Path:
    """Where `claude_p` writes worker `sid`'s transcript."""
    return _transcripts_dir(
        _held_out_logs(run_dir) if schema_key in HELD_OUT_LOG_WORKERS
        else Path(run_dir) / "logs") / f"{sid}.log"


def _in_transcripts_dir(path: Path) -> bool:
    """Whether `path` lies in a transcripts directory — where no command's
    output may go."""
    return path.parent.name == TRANSCRIPTS_DIRNAME


# Beside a directory's transcripts, one line per spawn: which of its `*.log`
# files a worker's `claude -p` session wrote, and as which worker (DESIGN §8
# *What a worker ran is read from its own transcript*).
TRANSCRIPTS_REGISTRY = "transcripts.ndjson"


def _register_worker_transcript(log_path: Path, sid: str) -> None:
    """Record `log_path` as worker `sid`'s transcript, before `_invoke`
    writes it. A retry or a resume appends the same line again;
    `_worker_transcripts` reads each file once."""
    log_path.parent.mkdir(parents=True, exist_ok=True)
    with (log_path.parent / TRANSCRIPTS_REGISTRY).open("a") as f:
        f.write(json.dumps({"sid": sid, "log": log_path.name},
                           separators=(",", ":")) + "\n")


def _registered_transcripts(log_dir: Path) -> dict[str, str]:
    """`{log file name: sid}` of the transcripts registered in `log_dir`, a
    transcripts directory (`_transcripts_dir`)."""
    try:
        lines = (log_dir / TRANSCRIPTS_REGISTRY).read_text().splitlines()
    except OSError:
        return {}
    out: dict[str, str] = {}
    for line in lines:
        try:
            rec = json.loads(line)
        except ValueError:
            continue
        if not isinstance(rec, dict):
            continue
        name, sid = rec.get("log"), rec.get("sid")
        # A bare file name of this directory, never a path out of it.
        if (isinstance(name, str) and isinstance(sid, str)
                and name.endswith(".log") and name == Path(name).name):
            out.setdefault(name, sid)
    return out


def _worker_transcripts(log_dir: Path) -> list[tuple[str, Path]]:
    """`(sid, path)` of every worker transcript of log directory `log_dir`
    (`logs/` or `logs/held-out/`) — the files `_invoke` registered in its
    transcripts directory, never a command's log — newest first."""
    found = []
    tdir = _transcripts_dir(log_dir)
    for name, sid in _registered_transcripts(tdir).items():
        path = tdir / name
        try:
            found.append((path.stat().st_mtime, sid, path))
        except OSError:
            continue
    found.sort(key=lambda x: x[0], reverse=True)
    return [(sid, path) for _m, sid, path in found]


def _is_worker_transcript(log_path: Path) -> bool:
    return log_path.name in _registered_transcripts(log_path.parent)


# The header `_invoke` writes above a transcript line that is not a stream
# event: the CLI's stderr, and a stdout line that is not JSON (a mechanical
# string leerie itself writes).
_LOG_TEXT_HEADER_RE = re.compile(r"^\[[^\]\n]*\] (?:stderr|non-json-line)$")


def _iter_transcript_events(log_path: Path) -> Iterator[dict]:
    """The stream-json events of a worker's `claude -p` session — the ONE
    reader of a transcript's events, which every consumer of them uses
    (DESIGN §8 *What a worker ran is read from its own transcript*).

    Nothing unless `log_path` is a registered transcript
    (`_is_worker_transcript`): every other file in `logs/` is leerie's run
    of a repository command, whose output the code under measurement
    prints. Within a transcript, a line under a `[ts] stderr` or
    `[ts] non-json-line` header (`_LOG_TEXT_HEADER_RE`) is text `_invoke`
    wrote beside the stream, never an event. Malformed lines are skipped:
    the format is the CLI's, and one bad line must not hide the rest."""
    if not _is_worker_transcript(log_path):
        return
    try:
        lines = log_path.read_text(errors="replace").splitlines()
    except OSError:
        return
    prev = ""
    for line in lines:
        after, prev = prev, line
        if not line.startswith("{") or _LOG_TEXT_HEADER_RE.match(after):
            continue
        try:
            event = json.loads(line)
        except ValueError:
            continue
        if isinstance(event, dict):
            yield event


def _notes_dir(leerie_dir: str | Path, sid: str) -> Path:
    return Path(leerie_dir) / NOTES_DIRNAME / sid


def _criteria_path(leerie_dir: str | Path, sid: str) -> Path:
    return _notes_dir(leerie_dir, sid) / "criteria.md"


def _checkpoint_path(leerie_dir: str | Path, sid: str) -> Path:
    return _notes_dir(leerie_dir, sid) / "checkpoint.md"


def _beside(top: Path, root: Path) -> list[str]:
    """Every path a grant must name so that everything beneath `top` but
    outside `root` (which is beneath `top`) is granted and nothing beneath
    `root` is: at each directory from `top` down to `root`'s parent, every
    entry but the one on the way to `root`. Landlock grants beneath a path,
    so `top` itself cannot be granted."""
    out: list[str] = []
    cur = top
    for part in root.parts[len(top.parts):]:
        try:
            with os.scandir(cur) as it:
                entries = sorted((e.name, e.is_symlink()) for e in it)
        except OSError:
            entries = []
        for e, link in entries:
            if e == part:
                continue
            # A grant follows a symlink: one that resolves to `root`, an
            # ancestor of it or a path beneath it (pytest's
            # `pytest-current`, measured) would grant `root` itself. Only a
            # symlink can: any other entry here is beside `root`'s path.
            if link:
                real = Path(os.path.realpath(cur / e))
                if root.is_relative_to(real) or real.is_relative_to(root):
                    continue
            out.append(str(cur / e))
        cur = cur / part
    return out


def _reads_outside(root: Path, *, tmp: bool = True) -> list[str]:
    """Read grants for everything outside the state root `root` and the
    host directory every run on the host shares (`_HOST_DIR_ENV`, its build
    slots: `flock` needs only a read-only descriptor and Landlock does not
    handle it, so a process that could open a slot file could hold every
    slot from under the other runs — DESIGN §6 *A host-wide build
    semaphore*); with `tmp` False, outside the container's `/tmp`
    (`SHARED_TMP`) too, which no grant names: an isolated process's `/tmp`
    is its own, granted by the shim (DESIGN §6 *Every confined process has
    its own `/tmp`, `/dev/shm` and IPC*). An entry that resolves into
    `/tmp` is left out with it. `/dev` (`_DEV`), and any entry that
    resolves into it, is never in it: the devices a confined process opens
    are named by `_WORKER_DEVICES` (DESIGN §6 *No confined process holds or
    can open the operator's terminal*)."""
    if tmp:
        out = _beside(Path("/"), root)
    else:
        shared = Path(os.path.realpath(SHARED_TMP))
        if root.is_relative_to(shared):
            out = _beside(Path("/"), shared)
        else:
            out = []
            for p in _beside(Path("/"), root):
                real = Path(os.path.realpath(p))
                if not (real.is_relative_to(shared)
                        or shared.is_relative_to(real)):
                    out.append(p)
    out = [p for p in out
           if not Path(os.path.realpath(p)).is_relative_to(_DEV)]
    host = _host_dir()
    return out if host is None else _around(out, host)


def _host_dir() -> Path | None:
    """The host directory every run on the host shares (`_HOST_DIR_ENV`),
    resolved; None where there is none."""
    host = os.environ.get(_HOST_DIR_ENV, "").strip()
    return (Path(os.path.realpath(host)) if host and os.path.isdir(host)
            else None)


def _apart(paths: list[str], state_root: Path) -> list[str]:
    """`paths` with the state root and the host directory (`_host_dir`)
    taken out of each that contains one (`_around`): no grant covers
    either."""
    out = _around(paths, state_root)
    host = _host_dir()
    return out if host is None else _around(out, host)


def _around(paths: list[str], root: Path) -> list[str]:
    """`paths`, each one that contains `root` (a `TMPDIR` of `/tmp` with
    the state root beneath it) replaced by its entries beside `root`: no
    grant ever covers the state root whole."""
    out: list[str] = []
    for p in paths:
        real = Path(os.path.realpath(p))
        out += (_beside(real, root) if root.is_relative_to(real)
                else [p])
    return out


def _worker_own_dirs(env: Mapping[str, str], run_dir: Path) -> list[str]:
    """The directories `_WORKER_ENV_DIRS` names in `env` that lie beneath
    `<run_dir>/workers/`, or that are the private temp directory
    (`_worker_tmp`) of the worker whose configuration `CLAUDE_CONFIG_DIR`
    names there; any other value is shared, and granted nothing."""
    workers = (run_dir / WORKERS_DIR).resolve()
    config = env.get("CLAUDE_CONFIG_DIR")
    # Resolved, because the loop below compares `os.path.realpath(p)` against
    # it: `_worker_tmp` names `PRIVATE_TMP_ROOT`, under `/tmp`, which is a
    # directory in the image but a symlink to `private/tmp` on a macOS host.
    # Unresolved, the two spellings never matched there and the worker's own
    # temp directory was granted nothing.
    own_tmp = (os.path.realpath(_worker_tmp(
                   Path(os.path.realpath(config)).parent))
               if config and Path(os.path.realpath(config)).parent.parent
               == workers else None)
    out = []
    for var in _WORKER_ENV_DIRS:
        p = env.get(var)
        if p and (Path(os.path.realpath(p)).is_relative_to(workers)
                  or os.path.realpath(p) == own_tmp):
            out.append(os.path.realpath(p))
    return out


TREE_REPOS_DIRNAME = "tree-repos"


def _git_dirs(tree: Path) -> tuple[Path, Path] | None:
    """`(git dir, common dir)` of the worktree or clone `tree`, resolved;
    None when git cannot say."""
    r = subprocess.run(["git", *_tree_git_args(tree), "rev-parse",
                        "--path-format=absolute", "--git-dir",
                        "--git-common-dir"], capture_output=True, text=True,
                       check=False, timeout=30)
    lines = r.stdout.split("\n")
    if r.returncode != 0 or len(lines) < 2:
        return None
    return Path(lines[0]).resolve(), Path(lines[1]).resolve()


def _tree_repo_read(tree: Path, run_dir: Path) -> list[str]:
    """The tree repository (`<run>/tree-repos/<tree>/`) `tree` is a worktree
    of, for a worker that only reads `tree`; `[]` for any other tree (the
    run repository is granted read on its own)."""
    dirs = _git_dirs(tree)
    if dirs is None or dirs[0].is_relative_to(tree):
        return []
    common = dirs[1]
    if common.parent == (run_dir / TREE_REPOS_DIRNAME).resolve():
        return [str(common)]
    return []


def _tree_git_dirs(tree: Path, run_dir: Path) -> tuple[list[str], list[str]]:
    """`(write, read)`: the git metadata a commit in `tree` writes, and what
    it reads besides, when that lives in the run directory outside `tree`.
    A worktree of its tree's own repository (`<run>/tree-repos/<tree>/`,
    DESIGN §6 *A repository per committing tree (I6)*): that repository
    whole, and `<run>/repo/objects/` read (its alternates). A worktree of
    the run repository itself is no committing tree's (I6: the scripts
    remake one from a tree repository); writing it would grant the run
    repository's `refs/`, every branch, so the run stops instead.
    `([], [])` for a clone, whose `.git` is inside it."""
    dirs = _git_dirs(tree)
    if dirs is None:
        return [], []
    git_dir, common = dirs
    run_repo = (run_dir / RUN_REPO_NAME).resolve()
    if git_dir.is_relative_to(tree):
        return [], []
    if common.parent == (run_dir / TREE_REPOS_DIRNAME).resolve():
        return [str(common)], [str(run_repo / "objects")]
    if common == run_repo:
        die(f"{tree} is a worktree of the run's repository, not of its own: "
            "a committing worker there could move every branch of the run "
            "(DESIGN §6 *A repository per committing tree (I6)*). Report "
            "this; `leerie resume` remakes the tree from its own "
            "repository.")
    return [], []


def _bash_unrestricted(allowed_tools: str) -> bool:
    """True when the tool list grants bare `Bash` (an acting worker), not
    only `Bash(<verb>:*)` patterns."""
    return "Bash" in [t.strip() for t in allowed_tools.split(",")]


def _worker_grants(*, run_dir: str | Path, state: Mapping, schema_key: str,
                   cwd: str | Path, allowed_tools: str,
                   env: Mapping[str, str], notes_id: str | None = None,
                   selfcheck_dir: str | Path | None = None) -> WorkerGrants:
    """THE grant list (DESIGN §6 *A worker writes only where it is granted
    (I5)*), derived from the worker's kind. Every worker: the device nodes,
    its own directories (`_worker_own_dirs`), reads of everything outside
    the state root and of the run's staged system prompts. Then its cwd:
    written by a committing worker, with its tree's git metadata
    (`_tree_git_dirs`); otherwise written only with bare `Bash` (whose cwd
    is its own checkout) and read without — the shared planning worktree
    and the payload-only directory included —, with the run's repository
    readable. A worker whose prompt
    reads the run's specs and notes reads `subtasks/`, `task.md` and
    `notes/`; `notes_id` names its own notes directory, written. The re-drive's
    self-check directory (`selfcheck_dir`) is read, its `run/` written, and
    its copies (`_selfcheck_copies`) written."""
    run_dir = Path(run_dir).resolve()
    state_root = run_dir.parent.parent
    cwd_r = Path(cwd).resolve()
    # Its side's cache set, and only that one (`_worker_cache_dir`).
    cache = _worker_cache_dir(run_dir, schema_key)
    _mkdir_private(cache, run_dir)
    rw: list[str] = (list(_WORKER_DEVICES) + _worker_own_dirs(env, run_dir)
                     + [str(cache)])
    # The CLI the worker is, where its `PATH` finds it, and its home (the
    # git identity, a package manager's config): named for the same reason
    # as leerie's install below. A home that holds `/tmp` is not named.
    cli = shutil.which("claude", path=env.get("PATH"))
    home = os.path.realpath(env.get("HOME") or Path.home())
    if Path(os.path.realpath(SHARED_TMP)).is_relative_to(home):
        home = ""
    # The run's CLI configuration template: each worker's configuration
    # links its directories (`_worker_dirs`), read, never written.
    ro: list[str] = [str(run_dir / SYSPROMPT_DIRNAME),
                     # Leerie's own code: the CLI runs its hook and script
                     # shell (`_worker_guard`), a re-drive its self-check.
                     # Named, not left to the reads outside the state root:
                     # a checkout under `/tmp`, which no worker reads, is
                     # one leerie still runs from.
                     str(ROOT),
                     *([os.path.realpath(cli)] if cli else []),
                     *([home] if home else []),
                     str(run_dir / CLAUDE_CONFIG_TEMPLATE),
                     # What `MISE_OVERRIDE_CONFIG_FILENAMES` names in a Go
                     # repository's run: mise reads it on every call.
                     str(run_dir / MISE_OVERRIDES_NAME)]
    if schema_key in _COMMITTING_WORKERS:
        rw.append(str(cwd_r))
        git_rw, git_ro = _tree_git_dirs(cwd_r, run_dir)
        rw += git_rw
        # A clone borrows the run repository's objects (`--shared`).
        ro += git_ro or [str(run_dir / RUN_REPO_NAME / "objects")]
        if not git_ro:
            # And its CLI's own git reads the clone through leerie's git
            # directory for it (DESIGN §6 *The CLI's own git runs on
            # leerie's terms*), which only leerie writes.
            ro.append(str(_clone_git_dir(cwd_r)))
    else:
        (rw if _bash_unrestricted(allowed_tools) else ro).append(str(cwd_r))
        ro.append(str(run_dir / RUN_REPO_NAME))
        # A tree of its own repository: that repository read, never
        # written, so the worker's `git` reads the tree it is in.
        ro += _tree_repo_read(cwd_r, run_dir)
    if schema_key in _RUN_NOTES_READERS:
        ro += [str(run_dir / "subtasks"), str(run_dir / "task.md"),
               str(run_dir / NOTES_DIRNAME)]
        # Read only where it exists: a run planned before the copies were
        # made has none, and a grant names no path that is not there.
        if (run_dir / TASK_FILES_DIRNAME).is_dir():
            ro.append(str(run_dir / TASK_FILES_DIRNAME))
    if notes_id:
        own = _notes_dir(run_dir, notes_id)
        _mkdir_private(own, run_dir)
        rw.append(str(own))
    if selfcheck_dir is not None:
        sc = Path(selfcheck_dir).resolve()
        (sc / "run").mkdir(mode=0o700, parents=True, exist_ok=True)
        ro.append(str(sc))
        rw.append(str(sc / "run"))
        # Its copies, beneath the link root with the tree they copy.
        copies = _selfcheck_copies(run_dir, sc.name)
        _mkdir_private(copies, run_dir)
        rw.append(str(copies))
    # The stores of a tree leerie installed for, as the tree itself is
    # granted: the worker sees that install (DESIGN §6 *A worker started in
    # a tree leerie installed for runs on that tree's stores*).
    tree_stores = _installed_tree_stores(cwd_r)
    if tree_stores is not None:
        _mkdir_private(tree_stores, run_dir)
        (rw if str(cwd_r) in rw else ro).append(str(tree_stores))
    # No grant ever covers the state root whole, whatever a variable names
    # (`_reads_outside` never does, by construction: it is not re-checked,
    # which cost 0.3 s a call against a 2,000-entry `/tmp`, measured). Nor
    # the container's `/tmp`: an isolated worker's is its own, added by the
    # shim.
    # Every worker reaches the API (and WebFetch, and what its shell
    # fetches) through the egress proxy.
    return WorkerGrants(
        tuple(dict.fromkeys(_apart(rw, state_root))),
        tuple(dict.fromkeys(_reads_outside(state_root, tmp=False)
                            + _apart(ro, state_root))),
        egress=True, link=str(run_dir / TREES_DIRNAME))


# DESIGN §6 *The orchestrator's root is leerie's; a repository's root is
# only a confined process's*: where the repository image's stages are, in
# leerie's image (`leerie`'s `_repo_image_dockerfile`). Absent in the base
# image, and wherever no repository image was built.
WORKER_ROOT = Path("/opt/leerie-worker-root")
# Set to "1" by the launcher when the run starts on a repository image
# (`-e` locally, the launch wrapper's environment on Fly).
REPO_IMAGE_ENV = "LEERIE_REPO_IMAGE"


def _worker_root() -> str | None:
    """`WORKER_ROOT` when this image has one (a directory, not a link)."""
    try:
        st = os.lstat(WORKER_ROOT)
    except OSError:
        return None
    return str(WORKER_ROOT) if stat.S_ISDIR(st.st_mode) else None


class _ShimRefusals:
    """The shim's refusal descriptor for one confined spawn (DESIGN §6 *A
    confinement failure stops the run; it is never a result*): a pipe whose
    write end `fd` is passed to the shim (`--refusal-fd`, `pass_fds`). The
    shim writes it only when it refuses, and makes it close-on-exec, so
    the command itself never holds it: a command's own exit 126 leaves it
    empty. `check()` once the process has ended: raises
    `ConfinementRefused` when the shim wrote it."""

    def __init__(self, what: str) -> None:
        self.what = what
        self._r, self.fd = os.pipe()
        os.set_blocking(self._r, False)
        self._closed = False

    def close(self) -> bytes:
        """Close both ends; returns what the shim wrote, if anything."""
        if self._closed:
            return b""
        self._closed = True
        _close_fd(self.fd)
        raw = b""
        try:
            while True:
                chunk = os.read(self._r, 65536)
                if not chunk:
                    break
                raw += chunk
        except OSError:
            pass
        finally:
            _close_fd(self._r)
        return raw

    def check(self) -> None:
        raw = self.close()
        if raw:
            raise ConfinementRefused(
                self.what, raw.decode(errors="replace").strip())


class _ShimTaken(_ShimRefusals):
    """The shim's taken descriptor for one held-out sandbox (`--taken-fd`):
    the same pipe, written only when a held-out file could not be placed
    because the tree has its path. `check()` raises `HeldOutPathTaken`."""

    def check(self) -> None:
        raw = self.close()
        if raw:
            raise HeldOutPathTaken(
                f"{self.what}: {raw.decode(errors='replace').strip()}")


@contextlib.contextmanager
def _shim_refusals(what: str) -> Iterator[int]:
    """A `_ShimRefusals` around a spawn's whole life: yields the descriptor
    to pass to `_confined_argv` and `pass_fds`, and checks it on the way
    out, whatever the body raised — a refusal replaces the exit status or
    error the body was reading it as."""
    refusals = _ShimRefusals(what)
    try:
        yield refusals.fd
    finally:
        refusals.check()


def _confined_argv(grants: WorkerGrants, cmd: list[str], *,
                   refusal_fd: int | None = None,
                   sandbox: HeldOutSandbox | None = None,
                   report_fd: int | None = None, cli: bool = False,
                   worker_root: bool = True,
                   taken_fd: int | None = None) -> list[str]:
    """`cmd` started through the Landlock shim with `grants`. With
    `sandbox`, in a held-out sandbox (always: a held-out file never runs
    outside one, and the shim refuses where it cannot build one), its
    report copied to `report_fd`; else isolated once the confinement check
    every entry runs (`_require_confinement`) has built a sandbox
    (`_isolated()`, DESIGN §6 *Every confined process has its own
    `/tmp`, `/dev/shm` and IPC*), in a network namespace of its own: with
    an `egress` grant, the outside reached through the run's egress proxy
    (`_egress_server`), and the strict-output proxy's port relayed when it
    is live (DESIGN §6 *A confined process has its own network*). Where
    the image has a worker root (`_worker_root`) and the command is
    isolated, it runs in the worker view (`--worker-root`); a worker's CLI
    (`cli`) stays in leerie's root and its commands run there instead
    (`--cli`, `scripts/worker-shell.py`). `worker_root` False: leerie's
    root, for the sandbox probe, which checks the shim's own machinery.
    `refusal_fd`: the write end of the spawn's `_ShimRefusals`, which the
    spawn also passes in `pass_fds`. Every call in this module names it
    (a test reads every call): None only for `_require_confinement`'s own
    probes, which read the shim's exit themselves. `taken_fd` (with
    `sandbox`): the write end of the spawn's `_ShimTaken`, where the shim
    says a held-out file's path is the tree's."""
    # `-S`: the shim imports only the standard library, and `site` cost
    # ~15 ms of every worker's start (measured).
    argv = [sys.executable, "-I", "-S", str(LANDLOCK_SCRIPT)]
    if refusal_fd is not None:
        argv += ["--refusal-fd", str(refusal_fd)]
    wr = _worker_root() if worker_root else None
    if sandbox is not None:
        argv += ["--sandbox", "--view", sandbox.view]
        for src, rel in sandbox.place:
            argv += ["--place", f"{src}={rel}"]
        for src, rel in sandbox.replace:
            argv += ["--replace", f"{src}={rel}"]
        for rel in sandbox.remove:
            argv += ["--remove", rel]
        if taken_fd is not None:
            argv += ["--taken-fd", str(taken_fd)]
        if sandbox.report is not None and report_fd is not None:
            argv += ["--report", sandbox.report, "--report-fd",
                     str(report_fd)]
        if wr is not None:
            argv += ["--worker-root", wr]
    elif _isolated():
        argv.append("--isolate")
        if grants.egress:
            proxy = _egress_server()
            argv += ["--egress", str(proxy.socket_path)]
            if _STRICT_PROXY is not None and _STRICT_PROXY.port:
                # `ANTHROPIC_BASE_URL` names it on the orchestrator's
                # loopback: the same port in the namespace, relayed.
                argv += ["--forward", f"{_STRICT_PROXY.port}="
                         f"{proxy.forward(_STRICT_PROXY.port)}"]
        if wr is not None:
            argv += ["--worker-root", wr] + (["--cli"] if cli else [])
        if grants.link:
            argv += ["--link-root", grants.link]
    for p in grants.rw:
        argv += ["--rw", p]
    for p in grants.ro:
        argv += ["--ro", p]
    return argv + ["--", *cmd]


# --- I5 for leerie's runs of the repository's commands ----------------------
# DESIGN §6 *Leerie's runs of the repository's commands are confined too*.
# Whatever leerie runs on a repository's code (its build, lint, test,
# install and verify commands, a held-out set's run, CI parity, coverage,
# the AST scripts, which load the tree's own `typescript`) is the worker's
# code, and is confined like the worker: `_run_streaming` takes the grant
# as a required keyword.
MEASURE_KIND = "measure"
# The setup hook: also writes what DESIGN §6½ says a hook may install into.
SETUP_HOOK_KIND = "setup_hook"
# `mise install` / `mise ls`: also writes `MISE_DATA_DIR`, trusting nothing.
TOOLCHAIN_KIND = "toolchain"
# mise's cache, beneath `MISE_DATA_DIR`, for the kinds that write that.
MISE_CACHE_NAME = "cache"
# Every install leerie runs on a repository's code (a recipe's `install`
# entries, CI parity's prerequisites, `_install_settles`): a measurement's
# grant on disk, with the outside network through the egress proxy, so
# whatever manager the recipe names reaches its inputs (DESIGN §6 *An
# install reaches its inputs*).
INSTALL_KIND = "install"
MEASUREMENT_KINDS = (MEASURE_KIND, INSTALL_KIND, SETUP_HOOK_KIND,
                     TOOLCHAIN_KIND)
MEASURE_DIRNAME = "measure"
# Where `_tree_store_env` puts a run tree's own installer stores.
TREE_STORES_DIRNAME = "tree-stores"
# The run's own package stores (`_leerie_stores`): every command leerie runs
# in the run reads and writes them (DESIGN §6 *The stores a view installs
# from are leerie's*).
RUN_STORES_DIRNAME = "stores"
# Every store a run's tree installs from lives beside the trees, in
# `<run-dir>/worktrees/.stores/` (DESIGN §6 *The write grants on one mount
# are one mount*): the run's (`stores/`), each tree's own (`tree-stores/`)
# and each side's worker caches (`cache/`, `cache-held-out/`). A confined
# process's grants beneath `<run-dir>/worktrees` are one mount rooted
# there, so a tree hard-links from its store, and nothing of leerie's own
# record (`state.json`, the logs) is on that mount.
TREES_DIRNAME = "worktrees"
STORES_HOME_NAME = ".stores"


def _stores_home(run_dir: str | Path) -> Path:
    """`<run-dir>/worktrees/.stores`: where every store a tree installs
    from lives."""
    return Path(run_dir) / TREES_DIRNAME / STORES_HOME_NAME


# The re-drive's self-check makes its copies of a tree beside the trees, on
# their one mount, so a copy hard-links its tree's ignored files (DESIGN §8
# *The self-check's copy is a tree of its own*).
SELFCHECK_COPIES_NAME = ".selfcheck"


def _selfcheck_copies(run_dir: str | Path, label: str) -> Path:
    """`<run-dir>/worktrees/.selfcheck/<label>`: where the self-check of the
    group `label` makes its copies (its config's `snap_root`)."""
    return Path(run_dir) / TREES_DIRNAME / SELFCHECK_COPIES_NAME / label
_MEASURE_ID_FILE = "leerie-measure-id"
_MEASURE_ID_RE = re.compile(r"[0-9a-f]{16}")
_MEASURE_SUBDIRS = ("mise-state", "reports", "coverage")
# DESIGN §6 *A confined command's scratch is short and private*. Every
# measured tree's temp directory is `/tmp/l/<16 hex>/` (carried into an
# isolated command's own `/tmp` by the shim), short enough that a socket in
# it fits `sun_path` (107 bytes), and 0700 under `/tmp`'s root-owned sticky bit, so no ancestor is
# writable by another user (SWC, among others, refuses one that is).
SHARED_TMP = Path("/tmp")
PRIVATE_TMP_ROOT = SHARED_TMP / "l"
# The private temp directories this process made, removed at its exit.
_PRIVATE_TMPS: dict[str, int] = {}
# The run directory's entries no measured tree may hold or lie beneath:
# granting such a tree would grant them.
_MEASURE_PRIVATE = ("state.json", "acceptance", "logs", WORKERS_DIR,
                    f"{TREES_DIRNAME}/{STORES_HOME_NAME}", "tmp",
                    RUN_REPO_SETTINGS_NAME, TREE_REPOS_DIRNAME,
                    RUN_REPO_NAME, MEASURE_DIRNAME)


def _use_run_tmp(st: "State") -> Path:
    """Make `<run-dir>/tmp/` (0700) the orchestrator's own temp directory:
    `tempfile`'s, and `TMPDIR` for the commands it runs unconfined. Nothing
    of leerie's — a staged index, a held-out run's report — then depends on
    which `/tmp` a process sees (DESIGN §6 *A held-out evaluation runs
    alone*, *Nothing of leerie's own is in `/tmp`*)."""
    d = Path(st.run_dir) / "tmp"
    _mkdir_private(d, Path(st.run_dir))
    _SYSTEM_TEMP_DIR.setdefault("dir", tempfile.gettempdir())
    os.environ["TMPDIR"] = str(d)
    tempfile.tempdir = str(d)
    return d


# The system temp directory as it was before `_use_run_tmp`: the smoke
# test's working directory must be outside every repository, which the run
# directory is not when the state root is `<repo>/.leerie`.
_SYSTEM_TEMP_DIR: dict[str, str] = {}


def _system_temp_dir() -> str:
    return _SYSTEM_TEMP_DIR.get("dir") or tempfile.gettempdir()


# --- Leerie's own writes where confined code writes --------------------------
# DESIGN §6 *Leerie never writes through a path confined code shaped*. Every
# unconfined write leerie makes into a directory some confined process can
# write — a tree, a tree repository, a measurement directory, a worker's or
# a tree's stores — goes through these: the path is walked from an anchor no
# confined process can replace (the run directory, or a grant's own root,
# whose entry lies in a directory no grant names), one component at a time,
# never through a link, and the file is made at a fresh name in that
# directory's descriptor and renamed into place. A link confined code
# planted on the way refuses the write (`OSError`, ELOOP or ENOTDIR); one at
# the destination is replaced, never written through.
_DIR_NOFOLLOW = os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC


def _beneath_parts(anchor: Path, path: Path) -> tuple[str, ...]:
    """The components of `path` below `anchor`, lexically (`OSError`
    EINVAL when `path` is not beneath it: a write there is refused like one
    through a link)."""
    a = os.path.normpath(os.path.abspath(anchor))
    p = os.path.normpath(os.path.abspath(path))
    if p != a and not p.startswith(a.rstrip("/") + "/"):
        raise OSError(errno.EINVAL, f"{path} is not beneath {anchor}")
    return Path(p).relative_to(a).parts


def _open_dir_beneath(anchor: Path, path: Path, *, make: bool = False,
                      dir_mode: int = 0o777, replace: bool = False) -> int:
    """A descriptor of the directory `path`, reached from `anchor` without
    following a link. `make`: a missing component is made (`dir_mode`, less
    the umask). `replace`: a component that is not a directory — a link, a
    file — is removed and made a directory (only for leerie's own layout,
    never a tree's content). The caller closes the descriptor."""
    fd = os.open(anchor, os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC)
    try:
        for part in _beneath_parts(anchor, path):
            try:
                nxt = os.open(part, _DIR_NOFOLLOW, dir_fd=fd)
            except FileNotFoundError:
                if not make:
                    raise
                with contextlib.suppress(FileExistsError):
                    os.mkdir(part, dir_mode, dir_fd=fd)
                nxt = os.open(part, _DIR_NOFOLLOW, dir_fd=fd)
            except OSError as e:
                if not (replace and e.errno in (errno.ELOOP, errno.ENOTDIR)):
                    raise
                os.unlink(part, dir_fd=fd)
                os.mkdir(part, dir_mode, dir_fd=fd)
                nxt = os.open(part, _DIR_NOFOLLOW, dir_fd=fd)
            os.close(fd)
            fd = nxt
    except BaseException:
        os.close(fd)
        raise
    return fd


@contextlib.contextmanager
def _dir_beneath(anchor: Path, path: Path, *, make: bool = False
                 ) -> Iterator[int]:
    fd = _open_dir_beneath(anchor, path, make=make)
    try:
        yield fd
    finally:
        os.close(fd)


def _write_beneath(anchor: Path, path: Path, data: bytes, *,
                   mode: int | None = None, make: bool = True) -> None:
    """Write `data` to `path` beneath `anchor` as a new file renamed into
    place: made `O_EXCL|O_NOFOLLOW` at a fresh name in the directory's
    descriptor, so no link on the way or at `path` is ever written through.
    `mode`: the file's mode; by default that of the regular file it
    replaces, else 0o666 less the umask. `make`: missing directories are
    made."""
    path = Path(path)
    with _dir_beneath(anchor, path.parent, make=make) as dfd:
        keep = mode
        if keep is None:
            with contextlib.suppress(OSError):
                old = os.stat(path.name, dir_fd=dfd, follow_symlinks=False)
                if stat.S_ISREG(old.st_mode):
                    keep = stat.S_IMODE(old.st_mode)
        tmp = f".leerie-{uuid.uuid4().hex}"
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_EXCL
                     | os.O_NOFOLLOW | os.O_CLOEXEC,
                     keep if keep is not None else 0o666, dir_fd=dfd)
        try:
            with os.fdopen(fd, "wb") as f:
                f.write(data)
                if keep is not None:
                    os.fchmod(f.fileno(), keep)
            os.rename(tmp, path.name, src_dir_fd=dfd, dst_dir_fd=dfd)
        except BaseException:
            with contextlib.suppress(OSError):
                os.unlink(tmp, dir_fd=dfd)
            raise


# How much of a repository's file leerie reads, by what the file is (DESIGN §6
# *No read is unbounded*): a worker makes a terabyte sparse file at no disk
# cost, and the orchestrator is unconfined. Every read states one.
READ_LIMIT_CONFIG = 1 << 20      # configuration, manifests, pins, git admin
READ_LIMIT_TEXT = 16 << 20       # text read whole: sources, task files
READ_LIMIT_LARGE = 256 << 20     # a measurement's report; the operator's files
_READ_CHUNK = 1 << 20


def _read_regular_beneath(anchor: Path, path: Path, limit: int, *,
                          whole: bool) -> bytes:
    """At most `limit` bytes of the regular file `path` beneath `anchor`,
    reached without following a link (`OSError` otherwise, a FIFO included:
    it is opened non-blocking and refused, never waited on). `whole`: a file
    over `limit` is refused (`EFBIG`), by its size after the open and by
    what the read finds, so one that grows after the check is refused too;
    otherwise its first `limit` bytes are the answer."""
    path = Path(path)
    with _dir_beneath(anchor, path.parent) as dfd:
        fd = os.open(path.name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK
                     | os.O_CLOEXEC, dir_fd=dfd)
        with os.fdopen(fd, "rb") as f:
            st = os.fstat(f.fileno())
            if not stat.S_ISREG(st.st_mode):
                raise OSError(errno.EINVAL, f"{path} is not a regular file")
            if whole and st.st_size > limit:
                raise OSError(errno.EFBIG, f"{path} is over {limit} bytes")
            want = limit + 1 if whole else limit
            chunks: list[bytes] = []
            got = 0
            while got < want:
                b = f.read(min(_READ_CHUNK, want - got))
                if not b:
                    break
                chunks.append(b)
                got += len(b)
            if whole and got > limit:
                raise OSError(errno.EFBIG, f"{path} is over {limit} bytes")
            return b"".join(chunks)


def _read_beneath(anchor: Path, path: Path, *, limit: int) -> bytes:
    """The bytes of the regular file `path` beneath `anchor`, reached
    without following a link, refused (`OSError` `EFBIG`) over `limit`
    bytes (DESIGN §6 *No read is unbounded*)."""
    return _read_regular_beneath(anchor, path, limit, whole=True)


def _read_head_beneath(anchor: Path, path: Path, *, limit: int) -> bytes:
    """The first `limit` bytes of the regular file `path` beneath `anchor`,
    reached without following a link: for a caller that uses only the
    start of a file."""
    return _read_regular_beneath(anchor, path, limit, whole=False)


def _read_text_beneath(anchor: Path, path: Path, *, limit: int,
                       errors: str = "replace") -> str:
    """`_read_beneath`, decoded as UTF-8: a repository's file read without
    following a link (DESIGN §6 *Leerie never reads through a link a
    repository holds*), within `limit` bytes."""
    return _read_beneath(anchor, path, limit=limit).decode("utf-8", errors)


def _no_link_beneath(anchor: Path, path: Path) -> bool:
    """True when `path` beneath `anchor` exists and is reached without a
    link: neither it nor any directory on the way to it is one."""
    path = Path(path)
    if os.path.normpath(os.path.abspath(path)) == os.path.normpath(
            os.path.abspath(anchor)):
        return os.path.isdir(anchor)
    try:
        with _dir_beneath(anchor, path.parent) as dfd:
            return not stat.S_ISLNK(os.stat(path.name, dir_fd=dfd,
                                            follow_symlinks=False).st_mode)
    except OSError:
        return False


def _link_on_the_way(anchor: Path, path: Path) -> bool:
    """True when a directory on the way from `anchor` to `path` cannot be
    reached without following a link."""
    try:
        with _dir_beneath(anchor, Path(path).parent):
            return False
    except FileNotFoundError:
        return False
    except OSError:
        return True


def _dir_beneath_exists(anchor: Path, path: Path) -> bool:
    """True when `path` beneath `anchor` is a directory reached without a
    link."""
    try:
        with _dir_beneath(anchor, path):
            return True
    except OSError:
        return False


def _listdir_beneath(anchor: Path, path: Path) -> list[str]:
    """The names in the directory `path` beneath `anchor`, reached without
    a link (`OSError` otherwise). A name may itself be a link: read it with
    `_read_beneath`, which refuses one."""
    with _dir_beneath(anchor, path) as dfd:
        return os.listdir(dfd)


def _glob_beneath(anchor: Path, pattern: str) -> list[Path]:
    """`anchor.glob(pattern)`, sorted, keeping only the matches reached
    without a link (`_no_link_beneath`): a match through a linked directory
    names another tree's files, and a match that is a link names whatever it
    points at."""
    try:
        hits = sorted(Path(anchor).glob(pattern))
    except (OSError, ValueError):
        return []
    return [p for p in hits if _no_link_beneath(anchor, p)]


def _lexists_beneath(anchor: Path, path: Path) -> bool:
    """True when anything is at `path` beneath `anchor`, or a link or a
    non-directory stands on the way to it: either way the path is taken."""
    path = Path(path)
    try:
        with _dir_beneath(anchor, path.parent) as dfd:
            os.stat(path.name, dir_fd=dfd, follow_symlinks=False)
        return True
    except FileNotFoundError:
        return False
    except OSError:
        return True


def _regular_file_beneath(anchor: Path, path: Path) -> bool:
    """True when `path` beneath `anchor` is a regular file, reached
    without following a link on the way or at it."""
    path = Path(path)
    try:
        with _dir_beneath(anchor, path.parent) as dfd:
            return stat.S_ISREG(os.stat(path.name, dir_fd=dfd,
                                        follow_symlinks=False).st_mode)
    except OSError:
        return False


def _unlink_beneath(anchor: Path, path: Path) -> None:
    """Remove the file or link `path` beneath `anchor` (gone already, or a
    link on the way: nothing is removed)."""
    path = Path(path)
    try:
        with _dir_beneath(anchor, path.parent) as dfd:
            os.unlink(path.name, dir_fd=dfd)
    except FileNotFoundError:
        pass


def _remove_beneath(anchor: Path, path: Path) -> None:
    """Remove whatever is at `path` beneath `anchor` — a directory tree
    (`_rmtree_owned`), a file or a link — reached without following a link
    on the way (one there: nothing is removed)."""
    path = Path(path)
    try:
        with _dir_beneath(anchor, path.parent) as dfd:
            st_ = os.stat(path.name, dir_fd=dfd, follow_symlinks=False)
            if stat.S_ISDIR(st_.st_mode):
                # Through the descriptor's own path: the directory reached,
                # never one a link on the way names.
                _rmtree_owned(Path(f"/proc/self/fd/{dfd}") / path.name)
            else:
                os.unlink(path.name, dir_fd=dfd)
    except FileNotFoundError:
        pass
    except OSError as e:
        if e.errno not in (errno.ELOOP, errno.ENOTDIR):
            raise


def _rmdirs_beneath(anchor: Path, path: Path) -> None:
    """`os.removedirs` beneath `anchor`: remove `path` and then each parent
    up to (not including) `anchor` while each is empty, never through a
    link."""
    parts = _beneath_parts(anchor, path)
    for i in range(len(parts), 0, -1):
        try:
            with _dir_beneath(anchor, Path(anchor).joinpath(*parts[:i - 1])
                              ) as dfd:
                os.rmdir(parts[i - 1], dir_fd=dfd)
        except OSError:
            return


def _copy_beneath(src: Path, anchor: Path, dst: Path, *,
                  src_anchor: Path | None = None,
                  limit: int | None = None) -> None:
    """Copy the file `src` to `dst` beneath `anchor` (`_write_beneath`),
    with its mode. `src_anchor`: `src` lies where confined code writes too,
    and is read without following a link (`_read_beneath`), within `limit`
    bytes, which such a copy must state."""
    if src_anchor is not None:
        if limit is None:
            raise TypeError("a copy read beneath src_anchor states its limit")
        data = _read_beneath(src_anchor, src, limit=limit)
        with _dir_beneath(src_anchor, Path(src).parent) as sfd:
            m = os.stat(Path(src).name, dir_fd=sfd,
                        follow_symlinks=False).st_mode
    else:
        data = Path(src).read_bytes()
        m = os.stat(src).st_mode
    _write_beneath(anchor, dst, data, mode=stat.S_IMODE(m))


def _copytree_beneath(src: Path, anchor: Path, dst: Path, *,
                      ignore: Callable[[str, list[str]], Iterable[str]]
                      | None = None,
                      src_anchor: Path | None = None,
                      limit: int | None = None) -> None:
    """`shutil.copytree(src, dst, symlinks=True, dirs_exist_ok=True,
    ignore=ignore)` with every write beneath `anchor` (`_write_beneath`): a
    link in `src` is copied as a link, never followed on either side.
    `src_anchor`: `src` is read beneath it (`_listdir_beneath`,
    `_read_beneath`), so a link on the way to `src` refuses the copy."""
    src = Path(src)
    with _dir_beneath(anchor, dst, make=True):
        pass
    names = (_listdir_beneath(src_anchor, src) if src_anchor is not None
             else os.listdir(src))
    skip = set(ignore(str(src), names)) if ignore is not None else set()
    for name in names:
        if name in skip:
            continue
        s, d = src / name, Path(dst) / name
        if s.is_symlink():
            with _dir_beneath(anchor, d.parent) as dfd:
                with contextlib.suppress(FileNotFoundError):
                    os.unlink(name, dir_fd=dfd)
                os.symlink(os.readlink(s), name, dir_fd=dfd)
        elif s.is_dir():
            _copytree_beneath(s, anchor, d, ignore=ignore,
                              src_anchor=src_anchor, limit=limit)
        else:
            _copy_beneath(s, anchor, d, src_anchor=src_anchor, limit=limit)


def _mkdir_private(path: Path, top: Path) -> None:
    """Make `path` and every directory missing between `top` (which
    is made first when missing, as `mkdir(parents=True)` would) and it,
    each 0700: a directory leerie makes for a measurement or a worker is
    readable by its user alone (DESIGN §6 *A confined command's scratch is
    short and private*). Reached from `top` without following a link
    (`_open_dir_beneath`): every such directory is leerie's layout, so a
    link or a file confined code left in its place is removed and the
    directory made (DESIGN §6 *Leerie never writes through a path confined
    code shaped*). A `path` not beneath `top` is left alone."""
    top.mkdir(parents=True, exist_ok=True)
    try:
        _beneath_parts(top, path)
    except OSError:
        return
    os.close(_open_dir_beneath(top, path, make=True, dir_mode=0o700,
                               replace=True))


def _own_private_dir(path: Path) -> None:
    """Make `path` a 0700 directory of this user's, or stop the run: one
    that is a link, not a directory, or another user's is not private, and
    a command whose scratch it is could be read or planted."""
    with contextlib.suppress(FileExistsError):
        os.mkdir(path, 0o700)
    st_ = os.lstat(path)
    if (not stat.S_ISDIR(st_.st_mode) or st_.st_uid != os.geteuid()):
        die(f"{path} is not a directory of this user's, so leerie cannot "
            "give its commands a private temp directory there (DESIGN §6 "
            "*A confined command's scratch is short and private*). Remove "
            "it, or run leerie where /tmp is its own.")
    if stat.S_IMODE(st_.st_mode) != 0o700:
        os.chmod(path, 0o700)


def _remove_private_tmps() -> None:
    """At this process's exit: remove every private temp directory it made
    (a forked child that exits through Python leaves its parent's alone)."""
    for d, pid in list(_PRIVATE_TMPS.items()):
        if pid == os.getpid():
            _rmtree_owned(Path(d))
            _PRIVATE_TMPS.pop(d, None)


def _remove_trees_private_tmps(root: Path) -> None:
    """Remove the private temp directory every sidecar under `root` (a run's
    `measure/`) names, with the owner-aware removal."""
    try:
        sides = list(Path(root).glob("*.tree"))
    except OSError:
        return
    for side in sides:
        try:
            tmp = json.loads(side.read_text()).get("tmp")
        except (OSError, ValueError, AttributeError):
            continue
        if isinstance(tmp, str) and Path(tmp).parent == PRIVATE_TMP_ROOT:
            _rmtree_owned(Path(tmp))
            _PRIVATE_TMPS.pop(tmp, None)


def _private_tmp(key: Path) -> Path:
    """`/tmp/l/<id>/` for `key` (a measurement directory): made 0700 under
    a 0700 `/tmp/l`, the same path for the same key, removed with the key's
    tree (`_sweep_measure_dirs`) and at this process's exit."""
    _own_private_dir(PRIVATE_TMP_ROOT)
    d = PRIVATE_TMP_ROOT / hashlib.sha256(str(key).encode()).hexdigest()[:16]
    _own_private_dir(d)
    if not _PRIVATE_TMPS:
        atexit.register(_remove_private_tmps)
    _PRIVATE_TMPS.setdefault(str(d), os.getpid())
    return d


def _new_private_tmp(prefix: str) -> Path:
    """A new `/tmp/l/<prefix><random>/` that only this call can hold: made by
    `mkdtemp` (an exclusive `mkdir`, 0700, so an existing path of anyone's
    is never taken over) under the 0700 `/tmp/l` `_own_private_dir` checks,
    and removed at this process's exit like `_private_tmp`'s."""
    _own_private_dir(PRIVATE_TMP_ROOT)
    d = Path(tempfile.mkdtemp(prefix=prefix, dir=PRIVATE_TMP_ROOT))
    if not _PRIVATE_TMPS:
        atexit.register(_remove_private_tmps)
    _PRIVATE_TMPS[str(d)] = os.getpid()
    return d


def _cache_vars(env: Mapping[str, str], cache: Path) -> dict[str, str]:
    """Every `_STORE_VARS` variable at `cache/<name>` (one beneath the
    image's bake root `_BAKED_ROOT` in `env` is left out: leerie built it
    into the image) and `XDG_CACHE_HOME` at `cache/xdg`; the pnpm store and
    `xdg` are made."""
    out = {var: str(cache / name) for var, name in _STORE_VARS.items()
           if not (env.get(var) or "").startswith(_BAKED_ROOT)}
    out["XDG_CACHE_HOME"] = str(cache / "xdg")
    _with_pnpm_spellings(out)
    for d in (cache / "xdg", cache / "pnpm-store"):
        with contextlib.suppress(OSError):
            # `cache` is `<run-dir>/worktrees/.stores/cache`: everything below the run
            # directory is the workers'.
            _mkdir_private(d, cache.parent.parent)
    return out


def _git_dirs_of(tree: Path) -> tuple[Path, Path, Path] | None:
    """`(git_dir, common_dir, toplevel)` of the checkout at `tree`, resolved,
    or None when `tree` is no git checkout."""
    r = subprocess.run(["git", *_tree_git_args(tree), "rev-parse",
                        "--path-format=absolute", "--git-dir",
                        "--git-common-dir", "--show-toplevel"],
                       capture_output=True, text=True, check=False,
                       timeout=30)
    lines = r.stdout.split("\n")
    if r.returncode != 0 or len(lines) < 3 or not lines[2]:
        return None
    return (Path(lines[0]).resolve(), Path(lines[1]).resolve(),
            Path(lines[2]).resolve())


def _measured_tree_root(tree: Path, run_dir: Path,
                        dirs: tuple[Path, Path, Path] | None) -> Path:
    """The tree a grant names for a command run at `tree`: its git toplevel
    when that is one of the run's checkouts (a recipe entry's
    `working_dir`, a CI check's `cwd`), else `tree` as given."""
    if dirs is not None and dirs[2].is_relative_to(run_dir / "worktrees"):
        return dirs[2]
    return tree


def _sweep_measure_dirs(root: Path) -> None:
    """Move aside every measurement directory whose tree is gone or whose
    tree's id has changed (a tree made again at its path), then remove what
    was moved aside off the event loop: none of it is ever granted again."""
    gone = root / ".gone"
    try:
        sidecars = list(root.glob("*.tree"))
    except OSError:
        return
    moved = False
    for side in sidecars:
        own = root / side.name[:-len(".tree")]
        try:
            rec = json.loads(side.read_text())
            tree = Path(rec["tree"])
            id_file = rec.get("id_file")
            tmp = rec.get("tmp")
        except (OSError, ValueError, KeyError, TypeError):
            continue
        stale = not tree.is_dir()
        if not stale and id_file:
            try:
                stale = _read_beneath(
                    root.parent, Path(id_file), limit=READ_LIMIT_CONFIG).decode().strip() != \
                    own.name.rsplit("-", 1)[-1]
            except (OSError, ValueError):
                stale = True
        if not stale:
            continue
        with contextlib.suppress(OSError):
            gone.mkdir(mode=0o700, parents=True, exist_ok=True)
            if own.exists():
                os.rename(own, gone / f"{own.name}-{uuid.uuid4().hex[:8]}")
            # The tree's private temp directory goes with it.
            if (isinstance(tmp, str)
                    and Path(tmp).parent == PRIVATE_TMP_ROOT):
                _rmtree_owned(Path(tmp))
                _PRIVATE_TMPS.pop(tmp, None)
            side.unlink()
            moved = True
    if moved:
        threading.Thread(target=_rmtree_owned, args=(gone,),
                         daemon=True).start()


def _measure_id_dir(run_dir: Path, tree: Path,
                    dirs: tuple[Path, Path, Path]) -> Path | None:
    """The git directory that holds `tree`'s measurement id, in `run_dir`:
    for a tree in the run's `worktrees/`, the one leerie's layout names
    (`_run_tree_location`), never one the tree's `.git` names; for any other
    checkout, its git directory when that is in the run repository, which
    no grant writes. None otherwise."""
    loc = _run_tree_location(tree)
    if isinstance(loc, tuple):
        if os.path.realpath(loc[2]) != os.path.realpath(run_dir):
            return None
        try:
            _beneath_parts(loc[2], loc[1])
        except OSError:
            return None
        return Path(run_dir) / Path(loc[1]).relative_to(loc[2])
    if loc is None and dirs[0].is_relative_to(run_dir / RUN_REPO_NAME):
        return dirs[0]
    return None


def _measure_dir_at(run_dir: Path, tree: Path,
                    dirs: tuple[Path, Path, Path] | None) -> Path:
    root = run_dir / MEASURE_DIRNAME
    id_file: Path | None = None
    tid = ""
    id_dir = (_measure_id_dir(run_dir, tree, dirs) if dirs is not None
              else None)
    if id_dir is not None:
        # The tree's own git directory is made with the tree and removed
        # with it: an id kept there names this tree, not an earlier one at
        # the same path. For a committing tree it is in the tree repository
        # its worker writes, so the id is an untrusted key: read and written
        # from the run directory down without following a link (DESIGN §6
        # *Leerie never writes through a path confined code shaped*), and
        # any value names only one of this tree's own measurement
        # directories, or a fresh one.
        id_file = id_dir / _MEASURE_ID_FILE
        with contextlib.suppress(OSError, ValueError):
            tid = _read_beneath(run_dir, id_file, limit=READ_LIMIT_CONFIG).decode().strip()
        if not _MEASURE_ID_RE.fullmatch(tid):
            tid = uuid.uuid4().hex[:16]
            with contextlib.suppress(OSError):
                _write_beneath(run_dir, id_file, (tid + "\n").encode(),
                               mode=0o644, make=False)
            # A new tree at this path: its own stores (`_tree_store_env`)
            # start empty too, never with what an earlier tree's commands
            # left there.
            stale = _stores_home(run_dir) / TREE_STORES_DIRNAME / tree.name
            if stale.exists():
                gone = root / ".gone"
                _mkdir_private(gone, run_dir)
                os.rename(stale, gone / f"stores-{tree.name}-{tid}")
                threading.Thread(target=_rmtree_owned, args=(gone,),
                                 daemon=True).start()
    else:
        tid = hashlib.sha256(str(tree).encode()).hexdigest()[:16]
    own = root / f"{tree.name}-{tid}"
    _sweep_measure_dirs(root)
    for sub in _MEASURE_SUBDIRS:
        _mkdir_private(own / sub, run_dir)
    side = root / f"{own.name}.tree"
    if not side.is_file():
        side.write_text(json.dumps({
            "tree": str(tree),
            "id_file": str(id_file) if id_file is not None else None,
            "tmp": str(_private_tmp(own))}))
    return own


def _run_dir_of(st: object) -> Path:
    run_dir = getattr(st, "run_dir", None)
    if not isinstance(run_dir, (str, os.PathLike)):
        die("a repository command has no run directory to be confined in "
            "— leerie's own invariant is broken (DESIGN §6 *Leerie's runs "
            "of the repository's commands are confined too*). Report this.")
    return Path(run_dir).resolve()


def _measure_dir(st: "State", tree: str | Path) -> Path:
    """The measurement directory of `tree` (DESIGN §6 *Leerie's runs of the
    repository's commands are confined too*): `<run>/measure/<tree>-<id>/`,
    fresh for each tree and gone with it, holding the command's
    `mise-state/`, `reports/` and `coverage/`; its temp directory is the
    tree's private one under `/tmp/l/` (`_private_tmp`). With it, the one
    place a measured command's output may be written outside its tree and
    `/tmp`."""
    run_dir = _run_dir_of(st)
    t = Path(tree).resolve()
    dirs = _git_dirs_of(t)
    t = _measured_tree_root(t, run_dir, dirs)
    if dirs is not None and t != Path(tree).resolve():
        dirs = _git_dirs_of(t)
    return _measure_dir_at(run_dir, t, dirs)


def _measured_git_reads(tree: Path, run_dir: Path,
                        dirs: tuple[Path, Path, Path] | None) -> list[str]:
    """The git metadata a command in `tree` reads, read-only: a worktree of
    the run repository reads it whole; one of a tree repository reads that
    and the run repository's objects (its alternates); a clone, whose git
    directory is inside it, the run repository's objects. A repository
    elsewhere outside the run directory is its own. No measurement writes
    git metadata (measured: status, log, diff, rev-parse, ls-files and
    describe all succeed read-only)."""
    if dirs is None:
        return []
    git_dir, common, _top = dirs
    run_repo = (run_dir / RUN_REPO_NAME).resolve()
    if git_dir.is_relative_to(tree):
        return [str(run_repo / "objects")]
    if common == run_repo:
        return [str(run_repo)]
    if common.parent == (run_dir / TREE_REPOS_DIRNAME).resolve():
        return [str(common), str(run_repo / "objects")]
    if not common.is_relative_to(run_dir):
        return [str(git_dir), str(common)]
    return []


def _measurement_grants(st: "State", tree: str | Path,
                        kind: str = MEASURE_KIND) -> WorkerGrants:
    """THE grant of a command leerie runs on a repository's code (DESIGN §6
    *Leerie's runs of the repository's commands are confined too*): write
    the tree, its measurement directory (`_measure_dir`), the run's own
    stores (`<run-dir>/worktrees/.stores/stores/`, `_leerie_stores`) and the tree's own
    (`<run-dir>/worktrees/.stores/tree-stores/<tree>/`, `_tree_store_env`; DESIGN §6 *The
    stores a view installs from are leerie's*, *Which stores an install may
    share*); read its git metadata (`_measured_git_reads`), the run's mise
    overrides and everything outside the state root.
    `INSTALL_KIND` is `MEASURE_KIND` with egress.
    `SETUP_HOOK_KIND` also writes `MISE_DATA_DIR` and `~/.local/bin`,
    `TOOLCHAIN_KIND` `MISE_DATA_DIR` with its trust records
    (`MISE_STATE_DIR`) emptied first. `env` points the command's temp
    and `XDG_CACHE_HOME` at the tree's private temp directory
    (`/tmp/l/<id>/`, `_private_tmp`) and its mise state at the measurement
    directory; the store variables stay as `_leerie_stores` and
    `_tree_store_env` set them. `/tmp` itself is never granted: an isolated
    command's own is added by the shim (DESIGN §6 *Every confined process
    has its own `/tmp`, `/dev/shm` and IPC*)."""
    if kind not in MEASUREMENT_KINDS:
        raise ValueError(f"no measurement kind {kind!r}")
    run_dir = _run_dir_of(st)
    state_root = run_dir.parent.parent
    t = Path(tree).resolve()
    dirs = _git_dirs_of(t)
    root = _measured_tree_root(t, run_dir, dirs)
    if root != t:
        t, dirs = root, _git_dirs_of(root)
    for name in _MEASURE_PRIVATE:
        p = run_dir / name
        if p.is_relative_to(t) or t.is_relative_to(p):
            die(f"leerie was about to run a repository command in {t}, "
                f"which holds or lies in the run's {name}: its grant would "
                "grant that — leerie's own invariant is broken (DESIGN §6 "
                "*Leerie's runs of the repository's commands are confined "
                "too*). Report this.")
    own = _measure_dir_at(run_dir, t, dirs)
    # The run's own stores, which every command leerie runs in the run
    # writes and no other run reads.
    stores = _stores_home(run_dir) / RUN_STORES_DIRNAME
    _mkdir_private(stores, run_dir)
    rw: list[str] = list(_WORKER_DEVICES) + [str(t), str(own), str(stores)]
    if t.parent == (run_dir / "worktrees").resolve():
        # The tree's own stores (`_tree_store_env`), which no other tree
        # reads.
        tree_stores = _stores_home(run_dir) / TREE_STORES_DIRNAME / t.name
        _mkdir_private(tree_stores, run_dir)
        rw.append(str(tree_stores))
    # Leerie's install (the AST scripts) and the home, named as a worker's
    # are: `/tmp` is not in the reads outside the state root, and either
    # may lie beneath it.
    home = os.path.realpath(os.environ.get("HOME") or Path.home())
    ro: list[str] = [str(ROOT), str(run_dir / MISE_OVERRIDES_NAME),
                     *_measured_git_reads(t, run_dir, dirs)]
    if not Path(os.path.realpath(SHARED_TMP)).is_relative_to(home):
        ro.append(home)
    mise_cache: Path | None = None
    if kind in (SETUP_HOOK_KIND, TOOLCHAIN_KIND):
        tools = [Path(os.environ.get("MISE_DATA_DIR")
                      or Path.home() / ".local" / "share" / "mise")]
        # mise's install lock and its `incomplete` markers live in its
        # cache: there, they are shared as widely as the installs they
        # guard (DESIGN §6 *One toolchain install at a time on a host*).
        mise_cache = tools[0] / MISE_CACHE_NAME
        if kind == SETUP_HOOK_KIND:
            tools.append(Path.home() / ".local" / "bin")
        for d in tools:
            d = d.resolve()
            if d.is_relative_to(state_root):
                continue
            with contextlib.suppress(OSError):
                d.mkdir(parents=True, exist_ok=True)
            rw.append(str(d))
    mise_state = own / "mise-state"
    if kind == TOOLCHAIN_KIND:
        # mise keeps its trust records here: emptied, it trusts no
        # configuration, whatever the hook before it trusted.
        _rmtree_owned(mise_state)
        _mkdir_private(mise_state, run_dir)
    # Remade on every grant: the tree's own sweep may have removed it.
    tmp = str(_private_tmp(own))
    rw.append(tmp)
    state = own / "state"
    # A runtime directory holds sockets: in the short private one, like
    # the temp directory (DESIGN §6 *A confined command's scratch is short
    # and private*).
    runtime = Path(tmp) / "run"
    _mkdir_private(state, run_dir)
    with contextlib.suppress(FileExistsError):
        os.mkdir(runtime, 0o700)
    # gpg's home: mise verifies a Node download by importing Node's release
    # keys, and `~/.gnupg` is not granted. A new one per grant (`mkdtemp`,
    # 0700), so verification stays on and no key a repository's command
    # imported is one a later install trusts (DESIGN §6 *A confined
    # command's scratch is short and private*).
    gnupg = tempfile.mkdtemp(prefix="gnupg-", dir=tmp)
    env = {"TMPDIR": tmp, "TMP": tmp, "TEMP": tmp,
           "MISE_STATE_DIR": str(mise_state), "XDG_CACHE_HOME": tmp,
           "XDG_STATE_HOME": str(state), "XDG_RUNTIME_DIR": str(runtime),
           "GNUPGHOME": gnupg}
    if mise_cache is not None:
        env["MISE_CACHE_DIR"] = str(mise_cache)
    # A measurement reaches nothing outside its own loopback; the kinds
    # that fetch (an install, a toolchain, the setup hook) reach the outside
    # through the egress proxy (DESIGN §6 *A confined process has its own network*, *An install reaches its
    # inputs*).
    return WorkerGrants(
        tuple(dict.fromkeys(_apart(rw, state_root))),
        tuple(dict.fromkeys(_reads_outside(state_root, tmp=False)
                            + _apart(ro, state_root))),
        tuple(env.items()), egress=kind != MEASURE_KIND,
        link=str(run_dir.resolve() / TREES_DIRNAME))


def _heldout_grants(st: "State", tree: str | Path) -> WorkerGrants:
    """The grant of a held-out file's run in `tree` (DESIGN §6 *A held-out
    evaluation runs alone*): `_measurement_grants`. It runs only in a
    sandbox, which lays an overlay over every write grant — the run's
    stores among them — so whatever the evaluation writes there vanishes
    with it and reaches no later command."""
    return _measurement_grants(st, tree)


def _argv_outside_grant(argv: list[str],
                        grants: WorkerGrants) -> str | None:
    """The first absolute path in `argv` that exists and that `grants`
    does not reach (realpaths compared), or None: every input leerie hands
    a confined command must be inside its grant (DESIGN §6 *Leerie's runs
    of the repository's commands are confined too*)."""
    roots = [Path(os.path.realpath(g)) for g in grants.rw + grants.ro]
    for a in argv:
        if not isinstance(a, str) or not a.startswith("/") \
                or not os.path.exists(a):
            continue
        real = Path(os.path.realpath(a))
        if not any(real.is_relative_to(r) for r in roots):
            return a
    return None


async def _invoke_admitted(cmd: list[str], cwd: str, timeout: int,
                           sid: str, leerie_dir: Path, verbosity: str,
                           progress: Callable[[],
                                              tuple[int, int, int, int]
                                              | None] | None = None,
                           idle_warn_sec: float | None = None,
                           worker_memory_max_bytes: int | None = None,
                           worker_pids_max: int | None = None,
                           stdin_data: str | None = None,
                           run_id: str | None = None,
                           active_token: str | None = None,
                           max_parallel: int | None = None,
                           worker_demand_estimate_bytes: int | None = None,
                           env_extra: dict[str, str] | None = None,
                           *, grants: WorkerGrants | None,
                           log_dir: Path | None = None) -> dict:
    """Admission-gated wrapper around `_invoke`.

    This exists as a separate function purely so the memory reservation is
    released on **every** exit path. `_invoke`'s own try/finally does not
    start until ~570 lines in — after `asyncio.create_subprocess_exec`,
    which this repo has seen raise (the argv E2BIG incident) — so releasing
    there alone would strand a token whenever setup failed.

    The wrapper is the NEW name rather than `_invoke` being renamed, so that
    the five test files which `inspect.getsource(leerie._invoke)` keep
    seeing the real body, and the 23 that monkeypatch `leerie._invoke` keep
    intercepting it (the delegation below resolves through the module
    global).

    `max_parallel`, when given, arms the gate: block while the shared
    `leerie.slice` lacks measured headroom for another build. It is an
    arming signal only — "this caller has run-level context" — not an input
    to the gate's arithmetic, which reads real slice headroom. None (the
    default) skips the gate, used by callers with no run-level context,
    e.g. the startup smoke test."""
    admission_token: int | None = None
    if max_parallel is not None:
        admission_token = await _await_worker_memory_admission(
            worker_demand_estimate_bytes)
    try:
        return await _invoke(
            cmd, cwd, timeout, sid, leerie_dir, verbosity,
            progress=progress, idle_warn_sec=idle_warn_sec,
            worker_memory_max_bytes=worker_memory_max_bytes,
            worker_pids_max=worker_pids_max, stdin_data=stdin_data,
            run_id=run_id, active_token=active_token, grants=grants,
            **({"env_extra": env_extra} if env_extra else {}),
            **({"log_dir": log_dir} if log_dir is not None else {}))
    finally:
        _release_worker_memory_admission(admission_token)
        # A worker in a committing tree wrote only its tree repository;
        # leerie takes its branch now, whatever the exit (DESIGN §6 *A
        # repository per committing tree (I6)*).
        await _take_after_worker(cwd)


async def _invoke(cmd: list[str], cwd: str, timeout: int,
                  sid: str, leerie_dir: Path, verbosity: str,
                  progress: Callable[[], tuple[int, int, int, int] | None]
                  | None = None,
                  idle_warn_sec: float | None = None,
                  worker_memory_max_bytes: int | None = None,
                  worker_pids_max: int | None = None,
                  stdin_data: str | None = None,
                  run_id: str | None = None,
                  active_token: str | None = None,
                  env_extra: dict[str, str] | None = None,
                  *, grants: WorkerGrants | None,
                  log_dir: Path | None = None) -> dict:
    """Run a `claude -p` command, streaming events as they arrive.

    `grants` (required, keyword-only: no call can forget it) is where the
    worker's processes may write and read (`_worker_grants`, DESIGN §6 *A
    worker writes only where it is granted (I5)*): `cmd` is started through
    the Landlock shim with them, every descendant inheriting the
    restriction. None runs `cmd` unconfined: only `claude_p` on the
    host-side seam passes it (`HOST_SEAM_CAP`).

    `stdin_data`, when given, is written to a temp file that becomes the
    child's stdin — this is how `claude_p` hands the worker its
    (potentially 100KB+) prompt without putting it
    on argv, where a single element over Linux's MAX_ARG_STRLEN (131,071
    bytes, not raisable) raises `OSError: [Errno 7] Argument list too
    long` at exec time. A file rather than a pipe because the CLI waits a
    hard-coded 3 s for its FIRST stdin byte (`r6r(process.stdin,3000)` in
    the bundle, surfaced as "no stdin data received in 3s") and then drops
    its own `data` listener, discarding a late write. A pipe makes that
    deadline a race against the orchestrator's event loop; a file has the
    first byte readable at exec, so there is no deadline to lose. Measured
    A/B under synchronous bursts on the parent loop (the shape
    `_read_stream` produces when parsing several workers' JSON at once):
    pipe+feeder lost 20/20 prompts at both 400 ms and 900 ms bursts, file
    lost 0/20, and file stayed at 0/20 under 10x CPU oversubscription
    (load 97). Note raw CPU contention alone never reproduced it — 3x
    oversubscription cost 0/40 on BOTH transports — so the mechanism is
    loop-blocking, not a busy host. When `stdin_data` is None (e.g. the
    smoke-test caller, whose prompt is a fixed short string), stdin is closed
    immediately via DEVNULL — unchanged from the prior behavior.

    The CLI is invoked with `--output-format stream-json --verbose`; each
    line of stdout is one JSON event. The final `type: "result"` event
    is the envelope (same shape as the non-streaming `--output-format
    json` path produces). All events are appended to
    `<run-dir>/logs/transcripts/<sid>.log` (under `log_dir` instead when
    given: a held-out-side worker's, `_worker_log_path`) regardless of
    verbosity.
    Inline summaries
    surface to the orchestrator log according to `verbosity` (see
    `_summarize_stream_event`).

    `cmd` must already contain `--output-format stream-json --verbose`
    — `claude_p` adds those.

    Errors / cancellation follow `run_proc`'s contract: timeout raises
    `subprocess.TimeoutExpired`, cancellation kills the child and
    re-raises. A worker that exits without emitting any `result` event
    raises `WorkerError` — same error class callers already handle.

    `active_token`, when given, overrides `CLAUDE_CODE_OAUTH_TOKEN` in the
    child's environment (DESIGN §6 *Multi-token rotation*) — this is what
    lets `claude_p` switch which subscription token a worker authenticates
    with per-invocation, with no container restart. Passed explicitly
    rather than mutated via ambient `os.environ` because the orchestrator
    runs many `claude -p` workers concurrently (`asyncio.gather` under
    `Semaphore(max_parallel)`); mutating process-global env would race.

    **This entry point BYPASSES memory admission.** `_invoke_admitted`
    above is the gated one, and it owns the reservation's lifetime, so
    nothing in this body needs to know about it. Spawning a run worker
    through here instead would silently skip the gate — invisible, since
    the only symptom is memory pressure attributable to nothing. The one
    legitimate caller is `preflight`'s smoke test, which has no run-level
    `max_parallel` context to gate against."""
    log_path = _transcripts_dir(log_dir if log_dir is not None
                                else leerie_dir / "logs") / f"{sid}.log"
    _register_worker_transcript(log_path, sid)
    # `limit=10MB` overrides asyncio's StreamReader 64KB-per-line default.
    # A single `claude -p` event can plausibly exceed 64KB: the
    # implementer's `structured_output` tool_use carries the full
    # worker payload, and a long assistant text block is one event
    # too. Without this, a large event would crash `_read_stream`:
    # readline() (under the `async for proc.stdout` iterator) calls
    # readuntil() which raises LimitOverrunError, which readline()
    # wraps and re-raises as ValueError("Separator is not found,
    # and chunk exceed the limit"). Either name in `except` works —
    # but the user-visible exception is ValueError.
    # LEERIE_WORKER_DEBUG=1 injects DEBUG=* and ANTHROPIC_LOG=debug into the
    # worker's environment. The point: if a worker hangs before emitting
    # any stdout event, rerunning with this env var makes the CLI emit its
    # internal state to stderr (which the watchdog below surfaces), so an
    # otherwise-invisible silent stall becomes diagnosable without
    # redeploying leerie. The variable is opt-in because verbose CLI logging
    # is noisy on healthy runs.
    worker_env = None
    if os.environ.get("LEERIE_WORKER_DEBUG"):
        worker_env = os.environ.copy()
        worker_env["DEBUG"] = "*"
        worker_env["ANTHROPIC_LOG"] = "debug"
    # active_token overrides CLAUDE_CODE_OAUTH_TOKEN independently of the
    # LEERIE_WORKER_DEBUG gate above — multi-token rotation and worker
    # debug logging are orthogonal features and must compose (a debug
    # env still needs to carry the currently-selected token).
    if active_token is not None:
        if worker_env is None:
            worker_env = os.environ.copy()
        worker_env["CLAUDE_CODE_OAUTH_TOKEN"] = active_token
    # Forced constrained decoding: point the worker's API traffic at this
    # run's proxy so it can set `strict: true` on the injected
    # StructuredOutput tool (DESIGN §7). Composes with the two blocks above —
    # worker debug, token rotation and strict output are orthogonal.
    # `main()` has already refused to start if the operator set this variable
    # themselves, so there is nothing here to clobber.
    if _STRICT_PROXY is not None:
        if worker_env is None:
            worker_env = os.environ.copy()
        worker_env["ANTHROPIC_BASE_URL"] = f"http://127.0.0.1:{_STRICT_PROXY.port}"
    # A throwaway test database's URL (DESIGN §8 *Prisma repositories get a
    # real database*) — and never Prisma's AI-agent consent, which the user
    # granted for the orchestrator's own pushes alone.
    if env_extra:
        if worker_env is None:
            worker_env = os.environ.copy()
        worker_env.update(env_extra)
    if any(k.startswith("PRISMA_USER_CONSENT")
           for k in (worker_env if worker_env is not None else os.environ)):
        worker_env = {k: v for k, v in (worker_env if worker_env is not None
                                        else os.environ).items()
                      if not k.startswith("PRISMA_USER_CONSENT")}
    # Node/V8 derives its default heap ceiling (~4.2 GiB) from *host* memory,
    # not the worker's cgroup memory.max — so on a Node repo, a build can
    # abort with a V8 heap OOM while most of leerie's (larger) per-worker
    # allowance sits unused (P9).
    #
    # This is the mirror image of `resolve_worker_memory_max`'s
    # reconciliation: that one asks "given a declared heap, how big must the
    # cap be", this one asks "given a cap, how big a heap may Node have".
    # **Both subtract the same quantity** — everything else that shares the
    # cgroup, i.e. Node's non-heap RSS plus the resident `claude -p`
    # process — so both must use `_NODE_HEAP_HEADROOM_BYTES` rather than
    # re-typing a literal.
    #
    # They did not, and that was a real defect: this site kept `- 2048`
    # when the constant was re-derived to 2432, so leerie was granting a
    # heap 384 MiB larger than its own measurement says fits. Worked
    # example on the common auto path (ceiling 9677 MiB): 7629 injected +
    # ~2130 non-heap + ~328 claude = 10087 against a 9677 cap — an
    # in-cgroup OOM produced by leerie's own injection, which is the exact
    # failure class N14-16 exists to close. Referencing the shared constant
    # makes the two halves move together or not at all.
    #
    # Auto-derivation floors at 8 GiB so this is normally >= 5760, but
    # --worker-memory-max / LEERIE_WORKER_MEMORY_MAX let an
    # operator set the cap below the reserve explicitly — clamp so V8 is
    # never handed a non-positive or degenerately small ceiling.
    if worker_memory_max_bytes is not None and _is_node_repo(cwd):
        if worker_env is None:
            worker_env = os.environ.copy()
        reserve_mb = _NODE_HEAP_HEADROOM_BYTES // (1024 * 1024)
        cap_mb = max(worker_memory_max_bytes // (1024 * 1024) - reserve_mb, 256)
        worker_env["NODE_OPTIONS"] = f"--max-old-space-size={cap_mb}"
    # A worker's own git commands are the worker's: they keep the
    # repository's hooks, which leerie's own are run without (DESIGN §6½
    # *Hooks off*).
    worker_env = _git_hooks_on(worker_env if worker_env is not None
                               else os.environ)
    # Its stores and caches are its own, never leerie's (DESIGN §6 *The
    # stores a view installs from are leerie's*).
    worker_env = _worker_cache_env(
        worker_env, leerie_dir, _granted_cache_dir(grants, leerie_dir))
    # In a tree leerie installed for, its per-tree stores are the tree's,
    # chosen by the one function leerie's own commands there use (DESIGN §6
    # *A worker started in a tree leerie installed for runs on that tree's
    # stores*; review round 23 exec M1).
    if _granted_tree_stores(grants, cwd):
        _tree_store_env(worker_env, cwd)
    # Every command and hook of a confined worker runs in a domain nested in
    # its CLI's, so none can write into the stream this reads (DESIGN §6 *A
    # worker's commands cannot reach its CLI*). `claude_p` also puts it in
    # the `--settings` the CLI reads it from first.
    if grants is not None:
        worker_env = {**worker_env, SHELL_PREFIX_ENV: str(WORKER_SHELL)}
        # And its own git (DESIGN §6 *The CLI's own git runs on leerie's
        # terms*): nested, on leerie's addressing, on settings leerie put
        # back, never through a `.git` an earlier worker rewrote.
        worker_env.pop(WORKER_COMMAND_ENV, None)
        restored = await asyncio.to_thread(_ready_tree_for_worker, cwd)
        if restored:
            log(f"  [{sid}] put back {', '.join(restored)} of "
                f"{_operator_path(Path(cwd))} before the worker started")
        worker_env.update(_cli_git_env(cwd, worker_env.get("PATH", "")))
        # The same values on top of the settings the CLI reads, which it
        # applies over this environment (review round 23).
        cmd = _pin_cli_settings(list(cmd), _cli_pinned_env(worker_env))

    # The prompt is staged to a temp file BEFORE the spawn, and that file —
    # already positioned at byte 0 with the whole payload on disk — becomes
    # the child's stdin. The CLI's 3 s first-byte deadline is therefore
    # satisfied by construction: there is no writer left to be scheduled
    # late, because there is no writer at all. This replaces a concurrent
    # feeder task, which made delivery a race against the orchestrator's
    # event loop and lost that race 20/20 times under 400 ms loop bursts
    # (see this function's docstring for the full A/B).
    #
    # Closed and unlinked in the `finally` below, on every exit path, the
    # same lifecycle `_append_system_prompt_file_supported`'s temp file
    # already uses. Created per `_invoke` call, so `claude_p`'s 2-attempt
    # retry — which appends a retry note to `stdin_data` — gets a fresh
    # file for the second attempt rather than replaying the first payload.
    stdin_file = None
    stdin_path = None
    if stdin_data is not None:
        import tempfile  # noqa: PLC0415
        stdin_fd = None
        # `mkstemp` is INSIDE the guard, not above it. Measured against a real
        # loop-mounted ext4 filled two different ways:
        #
        #   blocks exhausted  -> mkstemp SUCCEEDS (an empty file needs no data
        #                        blocks); the write then fails, which the guard
        #                        below already caught.
        #   inodes exhausted  -> mkstemp itself raises ENOSPC.
        #
        # …and even on block exhaustion, creation fails once the directory
        # must grow by a block (observed: a create loop stopped with ENOSPC
        # at 1,358 files while 6,821 inodes remained). So the common
        # disk-full case is not what reaches this line — which is why the
        # earlier framing of "the last raw-OSError site" was wrong — but two
        # real conditions do, and both used to escape as a bare OSError.
        #
        # Scope: this reaps the PATH once one exists. `os.fdopen` raising
        # would leak the raw fd (verified: CPython does not close it on a
        # failed construction), but that needs an invalid mode on a
        # just-returned mkstemp fd, i.e. a programming error rather than a
        # runtime condition.
        try:
            # In the run directory, never the shared `/tmp`: another
            # worker's processes must not read or rewrite this one's prompt
            # (DESIGN §6 *A worker writes only where it is granted*).
            stage_dir = Path(leerie_dir) / "stdin"
            stage_dir.mkdir(parents=True, exist_ok=True)
            stdin_fd, stdin_path = tempfile.mkstemp(prefix="leerie-prompt-",
                                                    dir=stage_dir)
            # fdopen rather than a bare os.write: os.write returns a count and
            # is permitted to short-write, so writing a 150KB prompt with it
            # would deliver a TRUNCATED payload on the day it ever did — the
            # worker would then run on a silently incomplete prompt instead of
            # failing visibly, which is strictly worse than the bug this
            # transport replaced. The buffered writer loops internally.
            with os.fdopen(stdin_fd, "wb") as staged:
                staged.write(stdin_data.encode())
            # Opened for reading and handed to the child as its stdin. The
            # child inherits a dup of this descriptor, so closing ours in the
            # `finally` does not disturb a still-running worker.
            stdin_file = open(stdin_path, "rb")
        except BaseException as exc:
            if stdin_path is not None:
                with contextlib.suppress(OSError):
                    os.unlink(stdin_path)
            # An out-of-space failure becomes DiskLowSpace, matching
            # `State.save()`. This is the single largest disk write leerie
            # makes per worker invocation (~150 KB, once per attempt), and
            # nothing upstream converts it — `claude_p`'s try catches only
            # RateLimitedExit — so it used to reach main()'s terminal handler
            # as an unhandled crash. The proactive ratio check runs once per
            # WAVE and cannot see a disk that crosses zero mid-wave, which is
            # exactly when this fires. Converting routes it into the same
            # resumable EXIT_LOCKED pause every other exhaustion path uses.
            if isinstance(exc, OSError) and exc.errno in _OUT_OF_SPACE_ERRNOS:
                # `stdin_path` is unset when `mkstemp` ITSELF failed — the
                # inode-exhaustion case the call was moved inside this guard
                # to cover — so name the directory instead of interpolating
                # None. The location is the actionable half: staging goes to
                # the run directory's `stdin/`, on the state-dir filesystem
                # the resume hint tells the operator to free.
                _where = stdin_path or (
                    f"a new file under {Path(leerie_dir) / 'stdin'}")
                raise DiskLowSpace(
                    f"staging the worker prompt failed: "
                    f"{os.strerror(exc.errno)} writing {_where}"
                ) from exc
            raise

    # The spawn is guarded because the staged file is created BEFORE the
    # try/finally that normally reaps it, and `create_subprocess_exec` is a
    # fork: under the `pids.max` exhaustion this codebase already handles
    # elsewhere it raises, and every retry would then strand another
    # ~150KB file. Disk exhaustion is not hypothetical here either — it has
    # killed runs (hence the `_disk_free_ratio` preflight) — so a leak on
    # the failure path feeds the very condition that produced the failure.
    #
    # cgroup containment: the worker cgroup is created BEFORE the spawn and
    # the worker starts held behind the spawn gate until the broker has
    # enrolled it (DESIGN §6 *Enrollment holds the spawn*): every descendant
    # it forks then inherits the cgroup. Enrolling a free-running worker
    # leaked 71/72 build descendants on rootful. Run-scoped name so
    # concurrent runs sharing this VM's leerie.slice/ (the --cgroupns=host
    # case) cannot collide on a bare worker sid — a bare name lets one run's
    # `destroy` (v2 cgroup.kill) SIGKILL another run's worker leader
    # mid-stream (DESIGN §6 *Memory containment*, run-scoped cgroup name).
    # `run_id` is None for callers with no run context (the smoke test never
    # enters this block anyway, since it passes no memory/pids caps).
    # The broker round-trips go through `asyncio.to_thread`: inline they
    # would block the whole event loop for up to `_cgroup_request`'s 5 s.
    # A per-worker failure returns None and the worker runs without its own
    # sub-cgroup — the cgroup path never aborts the worker; enforcement was
    # gated at run start (_enforce_and_record_cgroup_containment).
    # The worker is a holder of the execution lock from before its spawn
    # until its process has exited (the `finally` below), so no held-out
    # evaluation runs while it exists, and none is running when it starts:
    # one would stop the run here (DESIGN §6 *A held-out evaluation runs
    # alone, in a world that dies with it (I3)*).
    exec_hold = contextlib.AsyncExitStack()
    try:
        await exec_hold.enter_async_context(
            _exec_lock().shared(worker=True))
    except BaseException:
        if stdin_file is not None:
            with contextlib.suppress(OSError):
                stdin_file.close()
        if stdin_path is not None:
            with contextlib.suppress(OSError):
                os.unlink(stdin_path)
        raise
    cgroup_sid: str | None = None
    try:
        if (worker_memory_max_bytes is not None
                and worker_pids_max is not None):
            cgroup_sid = await asyncio.to_thread(
                _cgroup_create, _cgroup_worker_sid(run_id, sid),
                worker_memory_max_bytes, worker_pids_max)
    except BaseException:
        await exec_hold.aclose()
        raise
    # Unconfined (the host-side seam): the CLI is found from `/`, never
    # through PATH from the directory it starts in (DESIGN §6 *The host
    # never runs a program the checkout chose*, part 4).
    # A confined worker's refusal descriptor, checked as the last step of the
    # teardown below, before the envelope or exit status is read (DESIGN §6
    # *A confinement failure stops the run; it is never a result*).
    refusals = (_ShimRefusals(f"worker {sid}") if grants is not None
                else None)
    spawn_cmd = ([_exe_from_root(cmd[0]), *cmd[1:]] if grants is None
                 else _confined_argv(grants, list(cmd), cli=True,
                                     refusal_fd=refusals.fd))
    gate_r: int | None = None
    gate_w: int | None = None
    if cgroup_sid is not None:
        spawn_cmd, gate_r, gate_w = _spawn_held_argv(spawn_cmd)
    try:
        proc = await asyncio.create_subprocess_exec(
            *spawn_cmd,
            pass_fds=tuple(fd for fd in (
                gate_r, refusals.fd if refusals is not None else None)
                if fd is not None),
            cwd=cwd,
            # The staged prompt file when the caller has a prompt to feed (the
            # normal `claude_p` path — the user prompt no longer travels on
            # argv, see `build()`'s comment); DEVNULL otherwise. Either way the
            # worker never inherits the orchestrator's stdin, which inside a
            # `nerdctl run -it` container is /dev/pts/0 — a real TTY. A CLI
            # that branches on isatty() (e.g. to prompt for permission)
            # would hang invisibly waiting for input that never arrives.
            # A regular file is not a TTY either, and it reaches EOF on its own
            # once read, so the CLI still sees the end-of-input it needs to
            # start processing — the close the old feeder had to perform.
            stdin=(stdin_file if stdin_file is not None
                   else asyncio.subprocess.DEVNULL),
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
            limit=10 * 1024 * 1024,
            # Session/PG leader so `_terminate_proc_tree` can reap the
            # tool-call grandchildren `claude -p` spawns (vitest, dev
            # servers, etc.).
            start_new_session=True,
            env=worker_env,
        )
    except BaseException:
        # Reap the staged file, then let the original failure propagate
        # unchanged — this must not mask why the spawn failed.
        _close_fd(gate_r)
        _close_fd(gate_w)
        if cgroup_sid is not None:
            # Created before the spawn, so nothing else will remove it. Empty,
            # so the broker's destroy returns at once.
            _cgroup_destroy(cgroup_sid)
        if stdin_file is not None:
            with contextlib.suppress(OSError):
                stdin_file.close()
        if stdin_path is not None:
            with contextlib.suppress(OSError):
                os.unlink(stdin_path)
        if refusals is not None:
            refusals.close()
        await exec_hold.aclose()
        raise
    _close_fd(gate_r)
    # Spawn heartbeat: surfaces *that* the worker was launched before the
    # await blocks on its first event. Without this line, the user sees
    # the phase header and then silence until the first stream-json event
    # arrives (or the 90-min `worker_timeout_sec` fires) — a silent worker
    # was the failure class that motivated the watchdog below.
    #
    # Suppressed at `quiet`: per the verbosity contract, quiet emits
    # phase boundaries + errors only. The watchdog warning below IS
    # error-class and fires at every verbosity; this spawn line is
    # operational chatter and stays gated.
    if verbosity != "quiet":
        log(f"  [{sid}] spawned (pid={proc.pid})")
    # The prompt is ALREADY on the child's stdin at this point — it was
    # staged to a file before the spawn, so nothing below can delay its
    # delivery. That ordering used to be load-bearing and fragile: the CLI
    # waits a hard-coded 3 s for its first stdin byte
    # (`r6r(process.stdin,3000)` in the bundle, surfaced as "no stdin data
    # received in 3s"), then removes its own `data` listener and proceeds
    # without it, so a late write was DISCARDED and the worker died with
    # "Input must be provided either through stdin or as a prompt
    # argument". Measured across every run on one host: 218 workers lost
    # that way, 12.4% of all invocations in the affected runs, retried up
    # to 4x each and every attempt charged to `max_total_workers`.
    #
    # A concurrent feeder task (the previous fix) narrowed that window but
    # could not close it: delivery still depended on the event loop
    # scheduling the task within 3 s, and under bursts of synchronous work
    # on the loop it lost 20/20 prompts. A file has no such dependency, so
    # the broker round-trips below — and anything else that blocks the loop
    # — are no longer able to starve a worker of its prompt.
    # Enroll the held worker, then release it (DESIGN §6 *Enrollment holds
    # the spawn*). Still before any stream reading: the gate blocks the
    # worker, not this loop. A rejected enroll still releases — the worker
    # runs uncapped, as before — but a cancellation here closes the pipe
    # instead, and the gate exits without running the worker.
    # Stashed so a later crash in THIS worker's stream (nonzero rc, or no
    # result event) can name this as a probable contributing cause instead
    # of surfacing as an apparently-unrelated log line — see _cgroup_enroll's
    # docstring for the incident this closes.
    cgroup_enroll_failure: str | None = None
    if cgroup_sid is not None:
        try:
            cgroup_enroll_failure = await asyncio.to_thread(
                _cgroup_enroll, cgroup_sid, proc.pid)
        except BaseException:
            # The closed gate exits without running the worker.
            _release_spawn_gate(gate_w, run=False)
            if refusals is not None:
                refusals.close()
            await exec_hold.aclose()
            raise
        _release_spawn_gate(gate_w)
    # Track every descendant PID that ever appears under this worker. Claude
    # Code's Bash tool uses `run_in_background: true` to fire-and-forget
    # long-running commands (test runners, builds, dev servers); those
    # subprocesses outlive `claude -p`'s exit and are orphaned to init by the
    # time leerie could PPID-walk post-exit. The tracker observes them while
    # the chain is still intact, then SIGKILLs the accumulated set at the
    # end. See DESIGN §6 *Cleanup on abnormal exit*.
    descendant_tracker = _DescendantTracker(proc.pid, cgroup_sid)
    descendant_tracker.start()
    envelope: dict | None = None
    # Latch actual credit exhaustion from `rate_limit_event`s as they
    # stream. The discriminator is `overageDisabledReason` being an
    # *exhaustion* reason (`out_of_credits` / `out_of_overage`), NOT
    # `overageStatus:"rejected"`. That distinction is load-bearing:
    # `overageStatus:"rejected"` is a *standing config state* emitted by
    # every `rate_limit_event` from an org that has overage disabled
    # (`overageDisabledReason:"org_level_disabled"`, `status:"allowed"`)
    # — it does NOT mean credits ran out, and plenty of base subscription
    # quota may remain. Keying the latch on it caused a false positive:
    # any unrelated mid-stream truncation inherited the permanently-set
    # flag and was misreported as out-of-credits. Exhaustion is fatal
    # only when it coincides with a stream that truncates *without* a
    # result event (the CLI was killed mid-turn the moment credits ran
    # out); the no-envelope branch below consults this latch to route
    # that specific case into the pause-and-surface path instead of a
    # bare WorkerError → die().
    overage_blocked = False
    stderr_chunks: list[bytes] = []
    # Watchdog state: last_event_at is updated by _read_stream on every
    # successfully-parsed stream-json event. The _idle_watchdog coroutine
    # below observes this clock and warns when no events arrive for
    # `worker_idle_warn_sec` seconds.
    last_event_at = time.monotonic()
    # PID-exhaustion detector state (DESIGN §6 *Detecting PID exhaustion*).
    # A sliding window of recent tool-result outcomes (True=errored); the
    # cgroup is probed once the window holds ≥threshold errors. A window
    # (not a consecutive counter) is required because tool-results are never
    # adjacent in the stream — see `_tool_result_outcome`.
    tool_result_window: deque[bool] = deque(maxlen=_PID_EXHAUSTION_WINDOW)
    # Baseline pids.events.max at the first probe, so we can tell "the
    # counter is climbing" (fresh denials) from a stale nonzero value.
    pids_events_baseline: int | None = None
    # Last Bash command the worker launched (first line only, mirroring
    # _summarize_tool_use's truncation). Named in the memory-OOM diagnostic
    # below — a bare `Killed` mid-build leaves no error text of its own, so
    # this is the only way to tell the operator *what* was running when the
    # kernel OOM-killed the cgroup (DESIGN §6 *Detecting memory OOM*).
    last_bash_cmd: str | None = None
    # Last payload the worker submitted to `StructuredOutput`. Latched for the
    # same reason as `last_bash_cmd`: when the submission is REJECTED, the
    # error names the offending fields but never echoes what was actually
    # sent, and the payload lives in a preceding event the error text cannot
    # reach. Without this, the commonest worker failure signature (a schema
    # mismatch) is undiagnosable from a log — the 2026-08-03 investigation had
    # to re-run workers under `--output-format stream-json` by hand to recover
    # these, which is also what disproved the leading hypothesis about their
    # cause. `InputValidationError` (unparseable JSON) already logs its
    # payload; this closes the gap for the parseable-but-invalid case.
    last_structured_payload: str | None = None
    # Whether the unexpected-tool-surface warning has already fired for this
    # worker. Latched (not re-checked per event) so a worker whose tools
    # array is inspected across multiple system/init events (unusual, but
    # not impossible) only ever warns once — the advisory exists to flag a
    # drift, not to spam the log per event.
    unexpected_tools_warned = False

    async def _read_stream():
        nonlocal envelope, last_event_at, overage_blocked
        nonlocal pids_events_baseline, last_bash_cmd
        nonlocal last_structured_payload, unexpected_tools_warned
        # `buffering=1` is line-buffered: every newline flushes to disk.
        # Without this Python text-mode files are fully buffered when not
        # connected to a TTY, so `tail -f <run-dir>/logs/transcripts/<sid>.log` would
        # show nothing until the file closed at worker end — defeating
        # the entire live-progress property of the streaming feature.
        with log_path.open("a", buffering=1) as log_file:
            try:
                async for raw in proc.stdout:
                    if not raw:
                        continue
                    # Any bytes from the worker count as liveness — refresh
                    # the watchdog clock before parsing, so a stream of
                    # non-JSON lines (which are logged and skipped below)
                    # still counts as activity.
                    last_event_at = time.monotonic()
                    line = raw.decode(errors="replace").rstrip("\n")
                    # File: always record the raw event with a timestamp
                    # header. The header lets `tail -f` users see
                    # structure without parsing JSON.
                    try:
                        event = json.loads(line)
                    except json.JSONDecodeError:
                        log_file.write(
                            f"[{now()}] non-json-line\n{line}\n\n")
                        continue
                    t = event.get("type", "?")
                    sub = event.get("subtype")
                    header = f"{t}/{sub}" if sub else t
                    log_file.write(f"[{now()}] {header}\n{line}\n\n")
                    # Track the most recent Bash command the worker launched
                    # (first line only). Named in the memory-OOM diagnostic in
                    # _invoke's no-envelope path — a bare `Killed` mid-build
                    # carries no error text of its own, so this is the only
                    # way to say *what* was running when the cgroup OOM-
                    # killed (DESIGN §6 *Detecting memory OOM*).
                    if t == "assistant":
                        for b in (event.get("message", {})
                                  .get("content", []) or []):
                            if b.get("type") != "tool_use":
                                continue
                            if b.get("name") == "Bash":
                                cmd_lines = (
                                    (b.get("input", {}) or {})
                                    .get("command") or "").splitlines()
                                if cmd_lines:
                                    last_bash_cmd = cmd_lines[0]
                            elif b.get("name") == "StructuredOutput":
                                last_structured_payload = _format_payload_for_log(
                                    b.get("input"))
                    # Latch credit-exhaustion state (see `overage_blocked`
                    # declaration above for why this keys on
                    # `overageDisabledReason`, NOT `overageStatus`).
                    # Tracked here rather than in `_summarize_stream_event`
                    # because it must survive to the post-stream
                    # no-envelope check even at quiet verbosity, where the
                    # summarizer returns None.
                    if t == "rate_limit_event":
                        _rli = event.get("rate_limit_info") or {}
                        if (_rli.get("overageDisabledReason")
                                in ("out_of_credits", "out_of_overage")):
                            overage_blocked = True
                    # Tool-surface self-reporting (DESIGN §12 central
                    # principle applied to the CLI's own tool list): a CLI
                    # upgrade shipping a new tool name, or any mcp__* tool
                    # leaking past --strict-mcp-config, should be visible
                    # rather than silently drifting. Tracked here rather
                    # than in _summarize_stream_event for the same reason as
                    # the rate_limit_event latch above — it must fire even
                    # at quiet verbosity, where the summarizer is never
                    # consulted. Advisory only: never raises, never blocks.
                    if (t == "system" and sub == "init"
                            and not unexpected_tools_warned):
                        _tools = event.get("tools") or []
                        _flagged = sorted(
                            name for name in _tools
                            if name not in KNOWN_TOOLS
                            or name.startswith("mcp__"))
                        if _flagged:
                            unexpected_tools_warned = True
                            log(f"  [{sid}] unexpected tool(s) in worker's "
                                f"tool surface: {', '.join(_flagged)}")
                    # PID-exhaustion detection (DESIGN §6 *Detecting PID
                    # exhaustion*). A worker that has exhausted its cgroup
                    # pids.max fails EVERY shell-spawning tool call with
                    # EAGAIN — including trivial ones whose bare "Exit code
                    # 1" gives the model no way to diagnose it, so it
                    # spirals to the end of the run. Track the last N
                    # tool-result outcomes in a sliding window; once it
                    # holds ≥threshold errors, probe the cgroup. If it
                    # confirms exhaustion (at cap, or the fork-denial counter
                    # is climbing), raise WorkerError — _invoke's `except
                    # BaseException` terminates the subtree + reaps, and the
                    # callers route it (implementer → retryable handoff;
                    # conformer → advisory). A window, not a consecutive
                    # counter: tool-results are never adjacent in the stream
                    # (the model's assistant turn always sits between them),
                    # so a consecutive count could never exceed one. The
                    # window still leaves an ordinary failing test (≤1 error)
                    # below the threshold — and the cgroup read is the final
                    # authority regardless.
                    # Surface the rejected payload alongside the rejection.
                    # Gated on the schema-mismatch signature specifically so
                    # ordinary tool errors (a failing test, a missing file)
                    # never drag an unrelated structured payload into the log.
                    if _is_schema_rejection(event) and last_structured_payload:
                        log(f"  [{sid} tool-fail] rejected payload was: "
                            f"{last_structured_payload}")
                        # Cleared so a later, unrelated error cannot re-print a
                        # stale payload from an earlier submission.
                        last_structured_payload = None
                    _outcome = _tool_result_outcome(event)
                    if _outcome is not None:
                        tool_result_window.append(_outcome)
                        # Probe only when THIS result errored (and the
                        # window is error-heavy): the probe is a synchronous
                        # broker round-trip, and gating on the error avoids
                        # re-probing on the interleaved successes of a
                        # healthy-but-failing worker. An exhausted worker —
                        # whose every call errors — still probes on its
                        # first qualifying error, so detection is unchanged.
                        if (_outcome is True
                                and sum(tool_result_window)
                                >= _PID_EXHAUSTION_ERROR_THRESHOLD):
                            stat = _cgroup_stat(cgroup_sid)
                            if stat is not None:
                                cur, mx, ev_max, _oom = stat
                                if pids_events_baseline is None:
                                    pids_events_baseline = ev_max
                                at_cap = mx > 0 and cur >= mx
                                denials_climbing = (
                                    ev_max > pids_events_baseline)
                                # Fast-path text confirmation strengthens
                                # the signal but is not required.
                                if at_cap or denials_climbing:
                                    log(f"  [{sid}] PID cap reached: cgroup "
                                        f"pids.current={cur}/{mx}, fork "
                                        f"denials={ev_max} — the worker "
                                        f"leaked background processes "
                                        f"(likely run_in_background test / "
                                        f"build / dev-server subprocesses) "
                                        f"until it could no longer fork a "
                                        f"shell; every Bash call now fails. "
                                        f"Terminating early so a fresh worker "
                                        f"retries with a clean PID table.")
                                    raise PidExhaustedError(
                                        f"worker {sid} exhausted its PID "
                                        f"cgroup (pids.current={cur}/{mx}, "
                                        f"fork denials={ev_max}); every "
                                        f"shell-spawning tool call fails "
                                        f"with EAGAIN")
                    # No else-reset: successes age out of the bounded window
                    # naturally as newer outcomes push them past maxlen.
                    # Inline summary (verbosity-gated). Multi-line
                    # summaries (multi-block events, multi-line text)
                    # are emitted one log() call per line so each
                    # line gets its own ISO-8601 [leerie] prefix —
                    # otherwise the timestamp only renders on line 1
                    # and lines 2+ visually disconnect from the
                    # orchestrator's timestamped log stream.
                    summary = _summarize_stream_event(sid, event, verbosity)
                    if summary:
                        # Recompute per event so siblings finishing
                        # mid-run bump the count for still-running
                        # workers. Cached for this event's splitlines
                        # loop so a multi-line summary doesn't
                        # straddle two different counts.
                        prog = progress() if progress else None
                        prog_prefix = _format_progress_prefix(prog)
                        for ln in summary.splitlines():
                            if ln:
                                log(prog_prefix + ln)
                    # Capture the final result envelope. Skip
                    # `task-notification` result events: claude -p keeps
                    # the session alive after the worker's real result if
                    # a Bash run_in_background:true subprocess is still
                    # pending, and emits a second `result` event when the
                    # background task finishes. That event has
                    # `origin: {"kind": "task-notification"}` and no
                    # `structured_output`; capturing it overwrites the
                    # genuine envelope and cascades into a fake
                    # `empty_handoff` invariant violation downstream
                    # (envelope.get("structured_output") would be None →
                    # schema-retry → WorkerError → synthesized
                    # incomplete-handoff with a checkpoint_path that does
                    # not exist on disk).
                    if t == "result":
                        if (event.get("origin") or {}).get("kind") \
                                == "task-notification":
                            continue
                        envelope = event
            except ValueError as e:
                # asyncio's StreamReader raises ValueError("Separator
                # is not found, and chunk exceed the limit") when a
                # single line exceeds the 10 MiB limit (see
                # create_subprocess_exec above). Without this catch
                # the ValueError would propagate through claude_p's
                # retry loop unhandled and surface as a Python
                # traceback. Convert to WorkerError so callers see a
                # leerie-shaped error and the retry path treats it
                # as a worker fault.
                raise WorkerError(
                    "claude -p emitted a line exceeding the 10 MiB "
                    "buffer limit — likely a runaway structured_output "
                    f"or text block: {e}") from e

    async def _drain_stderr():
        # Stream stderr live to the per-sid log file with a `[ts] stderr`
        # header so it's distinguishable from stream-json events, and
        # echo selectively to the orchestrator log at stream/debug
        # verbosity. Continues to buffer raw bytes into stderr_chunks
        # so the existing exit-time error path (line ~4195) and the
        # idle-watchdog stderr-tail flush still work unchanged.
        #
        # Solves the failure class where a worker emits a fatal message
        # to stderr (e.g. "Claude configuration file not found" from
        # the claude-code recovery-loop bug) but leerie doesn't surface
        # it until the 300s watchdog fires (or never, if the recovery
        # loop spins indefinitely with no exit).
        nonlocal last_event_at  # stderr activity counts as liveness
        with log_path.open("a", buffering=1) as log_file:
            try:
                async for raw in proc.stderr:
                    if not raw:
                        continue
                    last_event_at = time.monotonic()
                    stderr_chunks.append(raw)
                    line = raw.decode(errors="replace").rstrip("\n")
                    log_file.write(f"[{now()}] stderr\n{line}\n\n")
                    if verbosity in ("stream", "debug"):
                        log(f"  [{sid}] stderr: {line}")
            except ValueError as e:
                # Mirror _read_stream's overlong-line protection
                # (line ~4082): asyncio's StreamReader raises
                # ValueError when a single line exceeds the 10 MiB
                # buffer limit. Convert to WorkerError so callers see
                # a leerie-shaped error consistent with the stdout path.
                raise WorkerError(
                    "claude -p stderr emitted a line exceeding the "
                    f"10 MiB buffer limit: {e}") from e

    async def _idle_watchdog():
        # Observation-only stall detector. Wakes every `warn_sec` seconds
        # and warns if the worker has emitted no stdout bytes for that
        # long. Never kills the worker — the 90-min `worker_timeout_sec`
        # (per-worker via TIMEOUT_DEFAULT_PER_WORKER, else the 90-min cap)
        # remains the only kill. Surfaces the silent-hang failure class
        # that motivated this watchdog: a `claude -p` worker that gets
        # stuck before its first `system/init` event would otherwise
        # leave the user with zero feedback for up to 90 minutes.
        #
        # When the worker exits normally (success or timeout), the
        # surrounding try/finally cancels this task; CancelledError is
        # suppressed by the awaiting caller.
        # `idle_warn_sec` carries the resolved per-run cap from
        # `claude_p` (which built `caps = dict(DEFAULT_CAPS)` and then
        # honored any CLI / env / TOML override). Direct `_invoke`
        # callers — preflight smoke-test, replay paths, tests — don't
        # plumb caps and pass `None`; we fall back to `DEFAULT_CAPS`
        # so the watchdog still functions for them without forcing
        # every call site to thread the full caps dict.
        warn_sec = (idle_warn_sec if idle_warn_sec is not None
                    else DEFAULT_CAPS["worker_idle_warn_sec"])
        while True:
            await asyncio.sleep(warn_sec)
            gap = time.monotonic() - last_event_at
            # Compare in floats — truncating to int here would make a
            # sub-second `warn_sec` (e.g. in tests) compare against 0
            # and never warn.
            if gap < warn_sec:
                continue
            # Stderr tail: if the CLI is logging to stderr (e.g. when
            # LEERIE_WORKER_DEBUG=1), surface the most recent bytes
            # alongside the silence warning so the user has something
            # actionable. Truncated to the last 400 chars to keep the
            # orchestrator log readable.
            tail = b"".join(stderr_chunks[-10:]).decode(
                errors="replace").strip()
            tail_note = (f" — stderr tail: {tail[-400:]!r}"
                         if tail else "")
            log(f"  [{sid}] no stdout events in {int(gap)}s "
                f"(pid={proc.pid}, hard kill at "
                f"{timeout}s){tail_note}")

    watchdog_task = asyncio.create_task(_idle_watchdog())
    try:
        # Mark this worker as asyncio-managed so `_zombie_reaper` never
        # `waitpid`s it and steals its exit status from asyncio's child watcher.
        # Placed as the FIRST statement of this try so the `finally` discard
        # below genuinely covers it on every exit path (DESIGN §6 *Zombie
        # reaping*).
        _ASYNCIO_MANAGED_PIDS.add(proc.pid)
        try:
            await asyncio.wait_for(
                # No stdin task to await: the prompt was staged to a file
                # before the spawn, so there is nothing left to deliver by
                # the time this gather runs.
                asyncio.gather(_read_stream(), _drain_stderr(),
                               proc.wait()),
                timeout=timeout)
        except asyncio.TimeoutError:
            # Cancel the watchdog BEFORE the termination awaits so it
            # cannot wake during them and log a stale "no stdout events"
            # warning against a worker that's already being killed. The
            # `finally:` below still collects the task; cancel() is
            # idempotent.
            watchdog_task.cancel()
            await _terminate_proc_tree(proc)
            await descendant_tracker.stop_and_reap()
            raise subprocess.TimeoutExpired(cmd, timeout)
        except BaseException:
            # Same race-closing cancel as above. Then terminate the
            # worker's whole subtree (claude -p + its tool-call
            # grandchildren via PPID walk) and reap any backgrounded
            # subprocesses the tracker observed during the run. Then
            # re-raise. Leerie's _gather_or_cancel relies on this for clean
            # aborts.
            watchdog_task.cancel()
            await _terminate_proc_tree(proc)
            await descendant_tracker.stop_and_reap()
            raise
    finally:
        # Un-register the worker PID: asyncio has now finished awaiting it
        # (proc.wait() resolved inside the gather, or we terminated it), so the
        # zombie reaper may safely reap it if it lingers as a <defunct>.
        _ASYNCIO_MANAGED_PIDS.discard(proc.pid)
        # The watchdog runs for the whole worker lifetime and must be
        # cancelled on every exit path (success, timeout, abort) so it
        # doesn't outlive the worker and fire spuriously against a stale
        # `last_event_at`. The contextlib.suppress is the standard
        # asyncio pattern for awaiting a cancelled task without
        # propagating the CancelledError.
        watchdog_task.cancel()
        with contextlib.suppress(asyncio.CancelledError):
            await watchdog_task
        # Read the cgroup's final oom_kill counter BEFORE destroy tears the
        # cgroup down — destroy rmdirs it, so this is the last point a stat
        # read is possible. Feeds the no-envelope diagnostic below (DESIGN §6
        # *Detecting memory OOM*); None when containment is off or the
        # broker errors, same "cannot tell" contract as every other
        # _cgroup_stat call site.
        final_stat = _cgroup_stat(cgroup_sid)
        # Reap any backgrounded subprocesses the worker left behind BEFORE
        # destroying the cgroup. `claude -p` workers use Claude Code's Bash
        # tool with `run_in_background: true` for long-running tasks (test
        # runners, builds, dev servers — DESIGN §6). Those subprocesses are
        # spawned in detached POSIX sessions, exit-reparent to PID 1, and can
        # still be alive (and thus still cgroup members) at this point on the
        # success path — the timeout/abort paths above already reap before
        # terminating, but this success-path finally previously destroyed the
        # cgroup first. A non-empty cgroup makes the broker's rmdir fail with
        # EBUSY (measured 68-104 lingering PIDs on crash-path workers, M10),
        # so stop_and_reap must run before _cgroup_destroy here too.
        leaked = await descendant_tracker.stop_and_reap()
        if leaked:
            log(f"  [{sid}] reaped {leaked} backgrounded subprocess(es) "
                f"that survived `claude -p` exit")
        # cgroup teardown via the broker. The broker's destroy atomically
        # reaps any worker-tree process that survived _terminate_proc_tree /
        # descendant_tracker.stop_and_reap above (cgroup.kill on v2, move-to-
        # parent on v1) — a backstop for the backgrounded grandchild class —
        # then rmdirs the cgroup so we don't accumulate leerie-w-* entries
        # across a long-running orchestrator. Best-effort: socket errors are
        # logged inside _cgroup_destroy, never raised.
        #
        # Off the event loop, unlike the other _cgroup_* round-trips in this
        # coroutine. Those are bounded by _cgroup_request's 5s default and
        # return as fast as the broker can read two files; this one BLOCKS
        # FOR THE WHOLE DRAIN, which scales with the worker's process tree —
        # measured 1.67s at 1200 procs and ~5.2s at 3385, with the client
        # timeout now 15s. A conformer's teardown would otherwise stall every
        # other streaming worker on the loop for seconds at a time.
        #
        # Awaiting inside a `finally` is done cautiously here: this block
        # already contains two awaits, `_gather_or_cancel` cancels each task
        # exactly once and then waits on the cleanup gather with no timeout,
        # and this is the last statement — so a suspension here resumes
        # normally rather than re-raising. `to_thread` is not itself
        # cancellable, but the worker thread completes the round-trip
        # regardless, so the broker still receives the destroy.
        await asyncio.to_thread(_cgroup_destroy, cgroup_sid)

        # Drop the staged prompt file. The child holds its own dup of the
        # descriptor, so this neither disturbs a still-running worker nor
        # leaves the payload on disk after one exits. Best-effort for the
        # same reason every other teardown step here is: a cleanup failure
        # must not mask the worker's real outcome.
        if stdin_file is not None:
            try:
                stdin_file.close()
            except OSError:
                pass
        if stdin_path is not None:
            with contextlib.suppress(OSError):
                os.unlink(stdin_path)
        # Its process tree has ended and been reaped: the worker no longer
        # exists.
        await exec_hold.aclose()
        # Last, so every step above has run: a refusal replaces whatever
        # this worker's exit is about to be read as.
        if refusals is not None:
            refusals.check()

    if envelope is None:
        stderr_txt = b"".join(stderr_chunks).decode(errors="replace").strip()
        # Out-of-credits mid-stream kill: an exhaustion `rate_limit_event`
        # was seen (overage_blocked) and the CLI was terminated before
        # emitting a result event. This is a credit condition, not a worker
        # fault — raise RateLimitedExit(out_of_credits=True) so main()'s
        # handler pauses-and-surfaces (worktree cleanup + resume hint +
        # EXIT_LOCKED) rather than the auto-resume path: out-of-credits has
        # no reset clock, so looping a fixed backoff would spin against the
        # wall. A bare WorkerError would instead bypass the auth/quota
        # backoff (it needs an envelope to classify) and die() the run
        # non-resumably. Checked before the returncode arm because the kill
        # may exit nonzero.
        if overage_blocked:
            raise RateLimitedExit(
                reset_at=None,
                out_of_credits=True,
                raw_message=(
                    f"out of credits — claude -p ({sid}) terminated "
                    "mid-stream with no result event"))
        # Memory-OOM naming (DESIGN §6 *Detecting memory OOM*): a worker
        # whose tool subtree (a build/test command) overshoots memory.max
        # is killed by the kernel mid-turn — bare `Killed`, no error text,
        # no result event. That symptom is otherwise indistinguishable from
        # a session-limit no-op or a --max-turns exhaustion, and lands
        # downstream in _settle_subtask as a cryptic "checkpoint does not
        # exist" once the retry cap is hit. `final_stat` (read from the
        # worker's cgroup just before destroy, above) is the authoritative
        # signal — mirrors the PID-exhaustion probe's use of the same
        # broker `stat` verb.
        if final_stat is not None and final_stat[3] > 0:
            cmd_desc = f"`{last_bash_cmd}`" if last_bash_cmd else "a command"
            cap_gib = (f"{worker_memory_max_bytes / 1024**3:.1f} GiB"
                       if worker_memory_max_bytes else "unknown")
            raise OomKilledError(
                f"worker {sid} was OOM-killed on {cmd_desc} "
                f"(memory.max={cap_gib}) — raise --worker-memory-max or "
                f"lower --max-parallel")
        if proc.returncode and proc.returncode != 0:
            # Name a cgroup-enroll failure as a probable contributing cause
            # when this same worker also crashed — otherwise the two are
            # left as separate, apparently-unrelated log lines (the
            # incident _cgroup_enroll's docstring documents: enroll
            # rejected with ProcessLookupError, followed by the CLI's own
            # 3s-stdin-timeout crash, with nothing connecting them).
            enroll_note = (
                f" — cgroup enroll for this worker also failed "
                f"({cgroup_enroll_failure}); possibly related"
                if cgroup_enroll_failure else "")
            raise WorkerError(
                f"claude -p exited {proc.returncode}: "
                f"{stderr_txt or '(no stderr)'}{enroll_note}")
        # `claude -p` exited on its own (rc 0) having streamed a full
        # session but never emitting the terminal `result` event — a known
        # upstream CLI failure (anthropics/claude-code #8126, #1920, #74761;
        # all closed "not planned" or open). It is intermittent and leerie
        # cannot prevent it, so the orchestrator must *survive* it: return a
        # synthetic error envelope instead of raising, which routes into
        # claude_p's existing 2-attempt corrective loop and gives the worker
        # one fresh session. A raised WorkerError would instead propagate
        # past that loop and die() the run non-resumably (the same reasoning
        # that makes the overage branch above raise RateLimitedExit).
        #
        # Deliberately the LAST branch: every arm above (overage, OOM,
        # nonzero rc) is a named, non-retryable condition and keeps raising.
        # In particular a nonzero rc covers leerie's own deliberate kills
        # (SIGTERM/SIGKILL), which must never be retried. Leerie's timeout
        # path raises TimeoutExpired before reaching this block at all.
        #
        # The message must not contain "rate limit" / "rate-limit" /
        # "invalid authentication": `_is_auth_or_quota_failure` falls back to
        # text markers on `result`, and a false match would burn the entire
        # auth_retry_max_sec backoff budget on a non-auth failure.
        return {
            "is_error": True,
            "result": ("claude -p produced no result event "
                       f"(stderr: {stderr_txt or '(empty)'})"),
            "structured_output": None,
            "_leerie_synthetic": "no_result_event",
        }
    return envelope


def _capture_call(run_dir: Path, record: dict) -> None:
    """Append one NDJSON record to calls.ndjson with fsync-per-line durability.

    fsync ensures a hard-killed run leaves a clean, fully-written last line
    rather than a partial line that would break NDJSON parsers."""
    capture_path = run_dir / "calls.ndjson"
    line = json.dumps(record, separators=(",", ":")) + "\n"
    with capture_path.open("a") as f:
        f.write(line)
        f.flush()
        os.fsync(f.fileno())


def _collect_memory_sample(st: "State") -> dict:
    """Snapshot orchestrator RSS / current phase / worker count / open FDs /
    thread count. Stdlib only (no `psutil` dependency).

    The four axes give enough signal to distinguish "natural heavy run" from
    leak shape:
      - rss_kb grows linearly with no GC drops → RSS leak, escalate to
        `tracemalloc`.
      - open_fds grows with no decline → subprocess pipe / log handle leak,
        audit `_invoke`'s cleanup paths.
      - thread_count grows → leaked `_DescendantTracker` background threads
        not being joined.
      - phase / worker_count contextualize the other axes.

    `/proc/self/fd` is the canonical Linux FD source; leerie's orchestrator
    runs as PID 1 inside the container (Linux), so the proc-fs path is
    valid. ru_maxrss is in KB on Linux (in bytes on macOS, but the
    orchestrator never runs on bare macOS — the launcher does, and we
    don't sample it). All probes are individually exception-guarded so a
    container without /proc still produces a partial sample rather than
    crashing the orchestrator over telemetry."""
    import resource
    import threading
    rss_kb = 0
    try:
        ru = resource.getrusage(resource.RUSAGE_SELF)
        rss_kb = int(ru.ru_maxrss)
    except Exception:
        pass

    open_fds = -1
    try:
        open_fds = len(os.listdir("/proc/self/fd"))
    except Exception:
        pass

    thread_count = -1
    try:
        thread_count = threading.active_count()
    except Exception:
        pass

    return {
        "ts": now(),
        "rss_kb": rss_kb,
        "phase": st.data.get("current_phase", "<unknown>"),
        "worker_count": st.data.get("worker_count", 0),
        "open_fds": open_fds,
        "thread_count": thread_count,
    }


# Linux prctl option numbers (from <linux/prctl.h>). Set: make this process a
# "child subreaper" so orphaned descendants reparent to it instead of climbing
# to PID 1. Get: read the current flag back (used only by tests to verify Set).
_PR_SET_CHILD_SUBREAPER = 36
_PR_GET_CHILD_SUBREAPER = 37

# PIDs of the `claude -p` workers the orchestrator spawns via
# `asyncio.create_subprocess_exec` and is actively awaiting (`proc.wait()` inside
# a gather). asyncio's own child watcher owns these PIDs' exit statuses.
# `_invoke` registers a worker here at spawn and discards it after the gather.
#
# NOTE: this set is NOT what keeps the zombie reaper off asyncio's children —
# it cannot be. A child is unregistered between `fork()` and the watcher's
# `os.pidfd_open()`, so an exclusion set always has a hole (DESIGN §6 *Zombie
# reaping*; measured: excluding asyncio-known PIDs still corrupted 212/300).
# Safety comes from `_REAPABLE_PIDS` being an allowlist instead. This set
# remains for telemetry and for `_reparented_orphans`, which must not SIGKILL a
# live worker.
_ASYNCIO_MANAGED_PIDS: set[int] = set()

# The zombie reaper's allowlist: PIDs leerie itself observed and recorded as
# descendants of a worker it spawned (published by `_DescendantTracker`, which
# already accumulates exactly this population for its own SIGKILL sweep).
#
# The reaper reaps ONLY these. It must never scan /proc for zombies to reap:
# a PID in its fork→pidfd_open window is indistinguishable from a true orphan,
# so any scanning reaper eventually steals an exit status asyncio needed and
# CPython fabricates returncode 255 (`asyncio/unix_events.py` `_do_wait`:
# "may happen if waitpid() is called elsewhere"). That fabricated 255 is what
# made `preflight` report "git user.email is not configured" on machines whose
# identity was correctly seeded — deterministically, 40/40 runs, because
# preflight's `git config` is the first subprocess after the reaper starts.
#
# Correct by construction: a PID that was never recorded here can never be
# taken. The cost is deliberate — an orphan leerie never observed is not
# reaped, and the cgroup PID cap remains the backstop (DESIGN §6).
_REAPABLE_PIDS: set[int] = set()

# When `os.waitpid` raises ChildProcessError (ECHILD) for a PID still on
# `_REAPABLE_PIDS`, that means one of two things: the PID is a live
# grandchild not yet reparented to us (retry later), or it was never truly
# ours / already reaped by someone else (drop it). `/proc/<pid>` existence
# disambiguates the two cheaply and without waitpid-ing anyone else's child.
# For the "still exists but not yet reparented" case we retain the PID and
# retry on later ticks (see `_zombie_reaper`) rather than discarding it
# outright, tracking the monotonic time of the first ECHILD per pid here so
# retention is bounded (`_ECHILD_RETRY_MAX_SEC`) instead of growing forever
# on a PID that, against expectation, never reparents.
_REAPABLE_PID_FIRST_ECHILD: dict[int, float] = {}

# Bound on how long a PID may sit in `_REAPABLE_PIDS` after its first ECHILD
# before being force-discarded even though `/proc/<pid>` still exists.
# Reparenting after an orphaning fork happens on the next scheduler tick in
# practice; 60s is generous headroom while still keeping the set from
# growing unboundedly for a PID that, for whatever reason, never reparents.
_ECHILD_RETRY_MAX_SEC = 60.0


def _pid_still_exists(pid: int) -> bool:
    """True if `pid` is still a live process, per /proc.

    A tiny existence check on ONE already-known pid, not a scan for pids to
    reap — `_zombie_reaper` never discovers work this way, it only
    disambiguates an ECHILD it already got for a pid already on its
    allowlist. Kept as its own function so `_zombie_reaper`'s own source
    never literally mentions `/proc` (see
    `test_zombie_reaper_never_scans_proc_for_zombies`, which guards the
    reaper against exactly the discover-via-/proc design this is not)."""
    return os.path.exists(f"/proc/{pid}")


def _restore_sigchld_default() -> None:
    """Force SIGCHLD to SIG_DFL before this process spawns anything.

    `SIG_IGN` on SIGCHLD tells the *kernel* to auto-reap exiting children, so
    their exit status is gone before anyone can read it. asyncio's
    `PidfdChildWatcher` then `waitpid`s a pid that no longer exists, catches
    `ChildProcessError`, and invents **returncode 255 with empty stdout**
    (CPython `asyncio/unix_events.py`). Every worker and every `run_proc` call
    goes through asyncio, so an inherited SIG_IGN silently corrupts the first
    subprocess's result.

    Only the first subprocess is corrupted, which makes the symptom maximally
    misleading: whichever check happens to run first reports a bogus failure
    and every later one succeeds.

    The disposition is inherited across `exec`, so a parent we do not control
    (an SSH daemon, a shell, the launch wrapper) can hand it to us. Nothing in
    leerie sets SIG_IGN — this is defensive, and cheap.
    """
    try:
        signal.signal(signal.SIGCHLD, signal.SIG_DFL)
    except (OSError, ValueError, AttributeError):
        # Non-main thread, or a platform without SIGCHLD (Windows). asyncio's
        # watcher is POSIX-only anyway; nothing to restore.
        pass


def _sigchld_is_ignored() -> bool | None:
    """True if the kernel is auto-reaping our children (SIGCHLD ignored).

    Reads `/proc/self/status`'s SigIgn mask rather than `signal.getsignal()`:
    a disposition *inherited across exec* is not always visible to Python's
    view, and the kernel mask is the ground truth. Returns None when it cannot
    be determined (no /proc, i.e. non-Linux) — callers treat that as "unknown",
    never as "ignored".
    """
    try:
        with open("/proc/self/status") as f:
            for line in f:
                if line.startswith("SigIgn:"):
                    # Bit N-1 for signal N; SIGCHLD is 17 -> bit 16.
                    return bool(int(line.split()[1], 16) & (1 << (signal.SIGCHLD - 1)))
    except (OSError, ValueError, IndexError, AttributeError):
        return None
    return None


def _become_subreaper() -> bool:
    """Install this process as a child-subreaper so orphaned descendants
    reparent to it (DESIGN §6 *Zombie reaping*). Returns True on success.

    Why this is load-bearing: the leerie container's PID 1 is `runuser`/the
    entrypoint (or an idle `sleep infinity` on Fly), NOT a real init — it never
    `wait()`s arbitrary orphans. A worker's tool subtree routinely orphans
    short-lived subprocesses (git, ssh-agent, and their children); without a
    subreaper those reparent to PID 1 and rot as zombies, each still counting
    against the worker cgroup's `pids.max` until it fills and every `fork()`
    EAGAINs. Claiming the subreaper role routes those orphans to the
    orchestrator, where `_zombie_reaper` reaps them.

    Linux-only (`prctl` is a Linux syscall). On any other platform, or if the
    libc call fails, this is a logged no-op — the orchestrator only runs for
    real inside the Linux container, so a dev-machine no-op is harmless.
    Called once, early in `main()`, before any worker is spawned so every
    descendant inherits the reparent-to-us behavior."""
    if not sys.platform.startswith("linux"):
        return False
    try:
        libc = ctypes.CDLL(None, use_errno=True)
        rc = libc.prctl(_PR_SET_CHILD_SUBREAPER, 1, 0, 0, 0)
        if rc != 0:
            err = ctypes.get_errno()
            log(f"subreaper: prctl(PR_SET_CHILD_SUBREAPER) failed (errno "
                f"{err}); orphaned worker subprocesses may accumulate as "
                f"zombies against the cgroup PID cap")
            return False
        return True
    except OSError as e:
        log(f"subreaper: could not install child-subreaper ({e}); orphaned "
            f"worker subprocesses may accumulate as zombies")
        return False


def _mark_reapable(pids: set[int]) -> None:
    """Record PIDs the zombie reaper is allowed to `waitpid`.

    Called by `_DescendantTracker`, which already accumulates every PID it
    observes in a worker's subtree. Only PIDs that pass through here are ever
    reaped — see `_REAPABLE_PIDS` for why an allowlist is the only correct
    shape. Never register a PID asyncio spawned directly: those belong to its
    child watcher (`_ASYNCIO_MANAGED_PIDS`)."""
    _REAPABLE_PIDS.update(pids - _ASYNCIO_MANAGED_PIDS)


async def _zombie_reaper(interval_sec: float = 1.0) -> None:
    """Periodically `wait()` orphaned descendants that reparented to this
    process (after `_become_subreaper`), clearing them before they pile up as
    zombies against the worker cgroup's `pids.max` (DESIGN §6 *Zombie reaping*).

    Complements `_DescendantTracker`: the tracker SIGKILLs *live* leaked PIDs
    to relieve pressure, but a SIGKILLed orphan becomes a `<defunct>` zombie
    that still occupies a task slot until someone `wait()`s it — that someone
    is this loop. Distinct concerns: the tracker bounds live processes, this
    reaps dead ones.

    Allowlist, NOT a /proc scan: this loop `waitpid`s only PIDs the tracker
    recorded via `_mark_reapable`. It must never look for zombies to reap,
    because a PID between `fork()` and asyncio's `os.pidfd_open()` is
    indistinguishable from a true orphan — reaping one there makes CPython
    fabricate returncode 255 for a subprocess that actually succeeded. That is
    not hypothetical: the scanning design took `preflight`'s own
    `git config user.email` PID on 40/40 runs, reporting a missing git identity
    on machines that had one (DESIGN §6 *Zombie reaping*).

    `WNOHANG` keeps this non-blocking: a recorded PID that is still alive is
    skipped now and retried next tick.

    A raise does NOT by itself mean "drop it" (N36). `ChildProcessError`
    (ECHILD) on a recorded PID is ambiguous: for a live grandchild — the
    dominant case here, since these PIDs come from a *worker's* subtree — it
    means "not ours **yet**", because the worker, not this process, is still
    the parent. Treating that as "gone" dropped the PID permanently, so the
    orphan that later reparented was no longer on the allowlist and nothing
    ever waited it (measured: 779 zombies, ~90% of one container's PID
    table). The arm therefore consults `_pid_still_exists` and only discards
    a PID confirmed absent, bounding retention at `_ECHILD_RETRY_MAX_SEC` so
    a PID that never reparents cannot grow the set without limit. Any other
    `OSError` is unambiguous and still discards.

    Spawned as a background task by `_orchestrate()` and cancelled in its
    `finally`, mirroring `_memory_sampler`."""
    while True:
        try:
            for pid in list(_REAPABLE_PIDS):
                if pid in _ASYNCIO_MANAGED_PIDS:
                    continue  # became a live worker's PID — not ours to reap
                try:
                    reaped, _status = os.waitpid(pid, os.WNOHANG)
                    if reaped:
                        _REAPABLE_PIDS.discard(pid)
                        _REAPABLE_PID_FIRST_ECHILD.pop(pid, None)
                except ChildProcessError:
                    # ECHILD means "not our child" -- which for a PID a
                    # worker's subtree just forked can legitimately mean "not
                    # reparented to us YET", not "gone". Check /proc: if the
                    # pid is still alive, retain it and retry on a later
                    # tick (bounded by _ECHILD_RETRY_MAX_SEC so a PID that
                    # never reparents doesn't accumulate forever); if it's
                    # actually gone, drop it now.
                    if _pid_still_exists(pid):
                        first_seen = _REAPABLE_PID_FIRST_ECHILD.setdefault(
                            pid, time.monotonic())
                        if time.monotonic() - first_seen > _ECHILD_RETRY_MAX_SEC:
                            _REAPABLE_PIDS.discard(pid)
                            _REAPABLE_PID_FIRST_ECHILD.pop(pid, None)
                        # else: still within the retry window -- keep it on
                        # _REAPABLE_PIDS and try again next tick.
                    else:
                        _REAPABLE_PIDS.discard(pid)
                        _REAPABLE_PID_FIRST_ECHILD.pop(pid, None)
                except OSError:
                    # Any other OSError (e.g. ESRCH) means it will never be
                    # reapable by us -- stop tracking it.
                    _REAPABLE_PIDS.discard(pid)
                    _REAPABLE_PID_FIRST_ECHILD.pop(pid, None)
        except Exception:
            pass  # reaping must never crash the orchestrator
        await asyncio.sleep(interval_sec)


def _write_memory_sample(st: "State") -> None:
    """Write one `memory.ndjson` sample line. Best-effort: exceptions are
    swallowed so a failed write (disk full, run_dir gone) never propagates
    to the caller."""
    try:
        out = st.run_dir / "memory.ndjson"
        sample = _collect_memory_sample(st)
        with out.open("a", buffering=1) as f:
            f.write(json.dumps(sample, separators=(",", ":")) + "\n")
    except Exception:
        pass


async def _memory_sampler(st: "State",
                          interval_sec: float = 30.0) -> None:
    """Periodic orchestrator-memory sample for leak detection.

    Writes one ndjson line per `interval_sec` to `memory.ndjson` alongside
    `state.json`. Each line records RSS, current phase, worker count, open
    FDs, and thread count — enough to correlate growth with the phase and
    the worker concurrency in flight at that moment.

    Lifecycle: spawned as a fire-and-forget task by `_orchestrate()`, cancelled
    in the `finally` block. On cancellation, one final sample is written
    before re-raising so the on-disk trail captures the orchestrator's
    end-of-run state.

    Never crashes the orchestrator: every probe is exception-guarded, the
    sample-write is exception-guarded, and an exception thrown anywhere
    inside the loop body is swallowed (telemetry that crashes the
    orchestrator is worse than no telemetry)."""
    # Re-resolve `st.run_dir` every tick — defensive against any future
    # mutation of st.run_dir.
    while True:
        _write_memory_sample(st)
        try:
            await asyncio.sleep(interval_sec)
        except asyncio.CancelledError:
            # Final sample before exit so the trail captures the
            # last-moment state. Best-effort: if the write fails (disk
            # full, run_dir gone), the existing samples on disk are
            # still useful; don't mask the CancelledError.
            _write_memory_sample(st)
            raise


_APPEND_SYSTEM_PROMPT_FILE_SUPPORTED: bool | None = None


def _append_system_prompt_file_supported() -> bool:
    """Once-per-process probe, memoized in
    `_APPEND_SYSTEM_PROMPT_FILE_SUPPORTED`: does this `claude` CLI accept
    `--append-system-prompt-file`? The flag is UNDOCUMENTED — it appears
    only inside `--bare`'s help text ("Explicitly provide context via:
    --system-prompt[-file], --append-system-prompt[-file], ...") and has
    no entry of its own in `--help` output, so it may be renamed or
    removed in a future CLI release without notice. `claude_p` gates its
    use behind this probe with an unconditional fallback to the inline
    `--append-system-prompt` (IMPLEMENTATION.md §3).

    The probe passes the flag together with a throwaway temp file and a
    closed stdin, with no `--output-format`/model dispatch requested.
    Commander.js validates every flag before `-p` reaches "no prompt
    given" — an unrecognized flag fails with `error: unknown option
    '--append-system-prompt-file'` (checked BEFORE stdin is read), while
    a recognized flag reaches the CLI's own "Input must be provided
    either through stdin or as a prompt argument" error instead. Both
    exit non-zero and cost nothing (no auth, no model call, sub-second).
    Distinguishing them via the different stderr text is what makes the
    probe accurate rather than a bare non-zero-exit check, which would
    read as "supported" either way.
    """
    global _APPEND_SYSTEM_PROMPT_FILE_SUPPORTED
    if _APPEND_SYSTEM_PROMPT_FILE_SUPPORTED is not None:
        return _APPEND_SYSTEM_PROMPT_FILE_SUPPORTED
    import tempfile  # noqa: PLC0415
    try:
        with tempfile.NamedTemporaryFile(
                mode="w", suffix=".txt", delete=False) as f:
            f.write("leerie capability probe")
            probe_path = f.name
        try:
            r = subprocess.run(
                ["claude", "-p", "--append-system-prompt-file", probe_path],
                input="", capture_output=True, text=True, timeout=15,
                check=False,
            )
        finally:
            with contextlib.suppress(OSError):
                os.unlink(probe_path)
    except (OSError, subprocess.TimeoutExpired):
        # Can't tell either way — fail closed to the documented flag.
        _APPEND_SYSTEM_PROMPT_FILE_SUPPORTED = False
        return False
    supported = "unknown option" not in (r.stderr or "")
    _APPEND_SYSTEM_PROMPT_FILE_SUPPORTED = supported
    return supported


_denial_skipped_warned = False


def _warn_denial_skipped_once(root: Path) -> None:
    """At most one warning per process when the checkout write-denial cannot
    be applied because run state lives inside the checkout. Silent would be
    worse: the operator would believe acting workers are contained when they
    are not."""
    global _denial_skipped_warned
    if _denial_skipped_warned:
        return
    _denial_skipped_warned = True
    log(f"warning: run state lives inside the checkout ({root}), so the "
        "worker write-denial for it cannot be applied without also denying "
        "each worker its own worktree. Acting workers are NOT confined to "
        "their worktree this run; the post-wave checkout sentinel still "
        "applies. Set LEERIE_STATE_DIR outside the repo to restore it.")


SYSPROMPT_DIRNAME = "sysprompt"


def _write_system_prompt_file(run_dir: str | Path | None, text: str) -> str:
    """Stage `--append-system-prompt-file`'s file under `<run-dir>/sysprompt/`
    (DESIGN §7 *The system prompt is staged in the run directory*), not /tmp.
    The CLI reads it at each spawn of a `claude_p` call, which can span a
    90-minute worker and its retries, and anything that clears /tmp under a
    live run (a host cleanup, a lost overlay) takes every in-flight file
    with it: 5 runs died that way at their next spawn. The run directory is
    the state the run already depends on; every worker's grant reads it (its
    CLI reads its own file there). Falls back to the system temp dir
    only when the run directory cannot hold it."""
    import tempfile  # noqa: PLC0415
    d: str | None = None
    if run_dir is not None:
        try:
            p = Path(run_dir) / SYSPROMPT_DIRNAME
            p.mkdir(parents=True, exist_ok=True)
            d = str(p)
        except OSError:
            d = None
    with tempfile.NamedTemporaryFile(
            mode="w", suffix=".txt", delete=False, dir=d) as f:
        f.write(text)
        return f.name


def _repo_write_denials(repo_root: str | Path, run_dir: str | Path) -> str:
    """Path-scoped deny rules keeping every worker's file writers out of the
    user's real checkout.

    DESIGN §12 L1 is unavailable to acting workers: they must write without
    prompting, so `claude_p` gives them `--dangerously-skip-permissions`, and
    that flag erases the CLI's working-directory boundary. A deny rule is the
    one control that survives it — measured live (claude 2.1.237, ground truth
    from the filesystem, cwd a worktree, flag ON):

    | configuration        | write outside cwd | write inside cwd |
    |----------------------|-------------------|------------------|
    | no path deny         | SUCCEEDED         | succeeded        |
    | `Edit(//<root>/**)`  | blocked           | succeeded        |

    The first row is the production failure: 146 `Edit`/`Write` calls with a
    `file_path` under the checkout, across 36 runs and 4 repos — 8.8% of the
    411 runs in the state root (measured 2026-08-20; the corpus grows, so
    re-derive before citing). The second row is this function. Workers keep
    full write access to their own worktree.

    `Edit(...)` subsumes `Write`, `NotebookEdit` and `MultiEdit`, and also
    covers `sed -i` (the CLI models it as an edit) — all verified in the same
    probe. It does NOT cover a shell redirect, `rm`, `touch` or `mkdir`, which
    the same probe showed still writing; `_assert_repo_unchanged` is the
    backstop for those, which is why it now runs during execute too.

    Derived from `repo_root` rather than hard-coding `/work` so it stays
    correct if the bind-mount path ever moves. `//` is the CLI's anchor for an
    absolute filesystem path, so `/work` becomes `//work/**`. Emits one rule
    normally, and two — the given path and its realpath — when they differ,
    since the CLI matches against the path the worker was handed rather than
    its realpath (see the comment on `given`/`root` below).

    Returns `""` when `run_dir` is inside `repo_root`. Worker worktrees are
    siblings under the run dir, so in that layout a blanket deny under
    `repo_root` would deny a worker its own worktree and every implementer
    would fail — silently, since a denial is not an error. It is reachable:
    `resolve_leerie_root` falls back to `repo_root / ".leerie"` whenever
    `LEERIE_STATE_DIR` is unset, which is the direct-invocation and test path
    (the launcher always sets `/leerie-state`). A deny rule cannot carry a
    carve-out — deny wins in every mode and allow rules are inert under
    `--dangerously-skip-permissions` — so skipping is the only option, and it
    is announced rather than silent. `_assert_repo_unchanged` still covers
    that configuration.
    """
    # `.resolve()` is required for the containment comparison below — a
    # symlinked run dir must still be recognised as inside the checkout. It
    # must NOT be the only form denied, though: the CLI matches the pattern
    # against the path the MODEL passes to Edit, which is the path the worker
    # was given, not its realpath. `repo_root` is `Path(os.getcwd())` only for
    # the in-container orchestrator; `run_rebaser` and `run_recapture_deps`
    # take it as a parameter and are handed the HOST's $USER_REPO
    # (scripts/host-finalize.sh, and the launcher's `config --recapture` arm).
    # The rebaser is autonomous with ACT_TOOLS, i.e. exactly the worker class
    # this denial exists for, running against a real user checkout whose path
    # may contain a symlink. Denying both forms removes the question; a
    # pattern that matches nothing is inert, and on the common path where the
    # two are equal this emits exactly one rule.
    given = Path(str(repo_root))
    root = given.resolve()
    run = Path(str(run_dir)).resolve()
    if run == root or root in run.parents:
        _warn_denial_skipped_once(root)
        return ""
    forms = [str(given).rstrip("/")]
    if str(root).rstrip("/") not in forms:
        forms.append(str(root).rstrip("/"))
    return ",".join(f"Edit(/{f}/**)" for f in forms)


# The whole suite is orchestrator-owned (DESIGN §9 *The whole suite is
# orchestrator-owned, and code enforces it*). Everything below is mechanical
# comparison of SHELL COMMAND strings -- the canonical command and the
# `runs_commands` entries a planner declares -- never of prose.

# Matching mirrors the CLI's own (claude Bash permission rules): split into
# subcommands, drop redirections, then glob-match each one, `*` standing for
# any text and a trailing ` *` also matching the bare command. ONE rule list
# feeds the deny, the plan-time strip and the settle-time exemption, so the
# three agree by construction (the first version derived them separately and
# they disagreed). Agreement with the CLI itself is a per-shape claim, pinned
# by `tests/test_full_suite_ownership.py::LIVE_PROBED` against verdicts the
# CLI returned live -- a shape not in that list is unverified.
#
# The split is a quote-aware scan (`_shell_subcommands`), not a regex: two
# review rounds of regex splits each broke a shape the CLI denies -- operators
# alone missed `(pytest tests/)` and `echo $(pytest tests/)`, and splitting on
# brackets after dropping quotes broke `pytest -k "not (slow)" tests/`.
#
# Prefixes stripped before an ANCHORED match, each because the CLI denied the
# prefixed form live: its documented wrappers (`timeout`, including option
# arguments such as `-s KILL`; `time`, `nice`, `nohup`, `stdbuf`, `command`,
# `builtin`, `noglob`), `exec`, `sudo` and `xargs`, environment assignments
# and `env` (`PYTHONPATH=. pytest tests/`, `env X=1 pytest tests/`), and the
# shell keywords that open a compound command's body (`if true; then pytest
# tests/; fi`). The
# unanchored match tries every word instead, which covers them all.
_SUITE_ASSIGN_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=\S*\s+")
_SUITE_WRAPPER_RE = re.compile(
    r"^(?:env(?:\s+(?:-u\s+\S+|--unset\s+\S+|-\S+))*"
    r"|timeout(?:\s+(?:-[sk]\s+\S+|--(?:signal|kill-after)\s+\S+|--?\S+))*"
    r"\s+\S+"
    r"|time(?:\s+-p)?|nice(?:\s+-n\s*\S+|\s+-\d+)?|nohup"
    r"|stdbuf(?:\s+-\S+)*|command|builtin|noglob|exec|sudo(?:\s+-\S+)*"
    r"|xargs(?:\s+-\S+)*|then|do|else|!)\s+")
_SUITE_MAX_ROOTS = 16
_NPM_FAMILY_TEST_RE = re.compile(r"^(npm|pnpm|yarn|bun)(?: run)? test$")
_PYTEST_FORMS = ("pytest", "python3 -m pytest", "python -m pytest")
FULL_SUITE_NOTICE = (
    "this repo's whole test suite (`{cmd}`) is run by the orchestrator "
    "itself on the integrated tree once every wave has merged, and running "
    "it is denied to you. Any criterion or repo rule that asks for the "
    "whole suite is owned by that pass: record it `met: false, "
    "not_applicable: true` with evidence \"orchestrator's whole-tree pass "
    "owns this\" and continue with targeted test files.")


def _canonical_test_command(repo_root: str | Path,
                            declared: dict[str, str] | None = None) -> str:
    """The repo's canonical test command, with `resolve_blt`'s precedence
    (a declared `test`, even empty, wins) but without its log lines -- this
    is read once per worker spawn and once per acceptance file, where the
    provenance log would repeat on every call. `declared` is the already
    loaded `.leerie/config.toml` BLT table, when the caller has it."""
    root = Path(str(repo_root))
    if declared is None:
        declared = _load_blt_config(root) or {}
    if "test" in declared:
        return (declared.get("test") or "").strip()
    return (_infer_build_lint_test(root).get("test") or "").strip()


def _test_roots(repo_root: str | Path) -> list[str]:
    """Directories a bare runner aimed at would still run the whole suite:
    pytest `testpaths` when declared, else `tests` when it exists."""
    root = Path(str(repo_root))
    for name, sections in (("pytest.ini", ("pytest",)),
                           ("tox.ini", ("pytest",)),
                           ("setup.cfg", ("tool:pytest",))):
        f = root / name
        if not f.is_file():
            continue
        # No interpolation: a `%` in a repo's own ini is literal to pytest,
        # and ConfigParser would raise on it at `get`. Decode errors are read
        # errors here too -- this file is the target repo's, not ours.
        cp = configparser.ConfigParser(interpolation=None)
        try:
            cp.read(f, encoding="utf-8")
        except (configparser.Error, OSError, UnicodeDecodeError):
            continue
        for sec in sections:
            if cp.has_option(sec, "testpaths"):
                # A root carrying a rule metacharacter would corrupt the
                # comma-joined `--disallowedTools` value; it is dropped, not
                # escaped, since the CLI offers no escape.
                roots = [r for r in (t.strip().strip("/") for t in
                                     cp.get(sec, "testpaths").split())
                         if r and not any(ch in r for ch in ",()*")]
                if roots:
                    return roots
    return ["tests"] if (root / "tests").is_dir() else []


def _full_suite_runners(canonical: str) -> list[str]:
    """Every spelling of the canonical test runner a worker plausibly types.
    Empty when the canonical command is absent or not expressible as a
    single permission rule (a compound command, one carrying characters
    that would split the comma-joined `--disallowedTools` list, or a `*`,
    which the CLI would read as a wildcard and so deny more than the
    canonical command)."""
    c = " ".join((canonical or "").split())
    if not c or any(ch in c for ch in ",()&|;<>`$*"):
        return []
    forms = [c]
    if c in _PYTEST_FORMS or c.split()[0] == "pytest" \
            or c.startswith(("python3 -m pytest", "python -m pytest")):
        forms += [f for f in _PYTEST_FORMS if f not in forms]
    m = _NPM_FAMILY_TEST_RE.match(c)
    if m:
        forms += [f for f in (f"{m.group(1)} test", f"{m.group(1)} run test")
                  if f not in forms]
    return forms


def _full_suite_rule_patterns(repo_root: str | Path,
                              prescribed: dict | None = None) -> list[str]:
    """Bodies of the whole-suite deny rules (`R`, `R T`, `R T/`, `R T *`,
    `R T/ *`, `R * T`, `R * T/` for every runner spelling R and test root
    T), or `[]` when no deny applies.

    `[]` when the repo has no test command, AND when the user's task
    prescribed a command these rules would deny: an explicit instruction
    outranks this default, and keeping the rule would make the prescribed
    command impossible to run while the declared-command check demands it.

    Total: it is read inside every `claude_p` call from the TARGET repo's
    files, so any failure degrades to `[]` (warned once) rather than
    killing every worker spawn."""
    try:
        runners = _full_suite_runners(_canonical_test_command(repo_root))
        if not runners:
            return []
        # Bounded: every root adds rules to ONE `--disallowedTools` argv
        # element, and past ~165 roots it would exceed Linux's per-argument
        # limit (MAX_ARG_STRLEN) and fail every worker spawn. Roots beyond
        # the cap are simply not denied; the notice still covers them.
        pats = _suite_rule_bodies(runners, _test_roots(repo_root))
        # Anchored: a prescribed command lifts the deny only if it IS a
        # whole-suite run, not if a runner word merely appears in it (`pip
        # install pytest`, `-k pytest`) -- an over-match here would switch
        # the whole mechanism off for the run.
        for c in _prescribed_commands(prescribed):
            if _denied_by_full_suite_rules(c, pats, anchored=True):
                return []
        return pats
    except Exception as e:
        _warn_full_suite_deny_skipped_once(e)
        return []


def _suite_rule_bodies(runners: list[str], roots: list[str]) -> list[str]:
    """The whole-suite rule bodies for `runners` over test `roots`: `R`,
    then `R T`, `R T/`, `R T *`, `R T/ *`, `R * T`, `R * T/` per root —
    the bare runner or one aimed at a test root. Shared by the
    orchestrator-owned suite deny and a task's `whole_suite` forbid."""
    # Bounded: every root adds rules to ONE `--disallowedTools` argv
    # element, and past ~165 roots it would exceed Linux's per-argument
    # limit (MAX_ARG_STRLEN) and fail every worker spawn. Roots beyond
    # the cap are simply not denied; the notice still covers them.
    roots = list(roots)[:_SUITE_MAX_ROOTS]
    pats: list[str] = []
    for r in runners:
        pats.append(r)
        for t in roots:
            pats += [f"{r} {t}", f"{r} {t}/", f"{r} {t} *",
                     f"{r} {t}/ *", f"{r} * {t}", f"{r} * {t}/"]
    return pats


_full_suite_deny_skip_warned: bool = False


def _warn_full_suite_deny_skipped_once(e: Exception) -> None:
    global _full_suite_deny_skip_warned
    if _full_suite_deny_skip_warned:
        return
    _full_suite_deny_skip_warned = True
    log(f"WARNING: could not derive the whole-suite deny rules "
        f"({type(e).__name__}: {e}); workers run without them this process")


def _full_suite_denials(repo_root: str | Path,
                        prescribed: dict | None = None) -> str:
    """`_full_suite_rule_patterns` as `Bash(...)` rules, comma-joined for
    `deny_extra`; `""` when no deny applies.

    A deny rule is the only permission control that survives
    `--dangerously-skip-permissions`. Probed live (claude 2.1.310 on the
    host, 2.1.302 in the image, flag ON): `timeout 590 python3 -m pytest
    tests/ -q -x -n 4 2>&1 | tail -15`, `python3 -m pytest -q -p
    no:cacheprovider tests/ > f; echo` and `cd . && pytest tests/ -q` were
    denied, as is a `-k`/`-m` selection aimed at a test root; `python3 -m
    pytest tests/test_x.py -q`, a two-file run and a `for` loop over files
    still ran. Not matched (the CLI ran each live): a runner behind another
    command (`uv run`, `coverage run -m`, `xvfb-run`, `eval`, `sh -c`), a
    quoted or escaped root (`pytest "tests/"`), a flags-only bare runner
    (`pytest -q`), and an absolute-path runner. Every worker whose tools can
    reach the runner gets `FULL_SUITE_NOTICE` with it (`claude_p`): deny
    alone ended 2/2 replayed workers `blocked`."""
    return ",".join(f"Bash({p})"
                    for p in _full_suite_rule_patterns(repo_root, prescribed))


def _full_suite_notice(repo_root: str | Path,
                       prescribed: dict | None = None) -> str | None:
    """The `NOTE FROM ORCHESTRATOR:` body paired with the whole-suite deny,
    or None when no deny is in force."""
    if not _full_suite_denials(repo_root, prescribed):
        return None
    # Never None while a deny is in force -- deny without notice is the
    # measured `blocked` failure -- so a read error degrades the wording only.
    try:
        cmd = _canonical_test_command(repo_root) or "the repo's test command"
    except Exception:
        cmd = "the repo's test command"
    return FULL_SUITE_NOTICE.format(cmd=cmd)


def _tools_reach_suite_runner(allowed_tools: str, repo_root: str | Path,
                              prescribed: dict | None = None) -> bool:
    """True when a worker with `allowed_tools` could invoke the canonical
    runner: unrestricted `Bash`, or a `Bash(<runner>...)` grant such as the
    `_widen_inspect_tools` verbs."""
    tools = [t.strip() for t in (allowed_tools or "").split(",")]
    if "Bash" in tools:
        return True
    heads = {p.split()[0]
             for p in _full_suite_rule_patterns(repo_root, prescribed)}
    return any(t.startswith(f"Bash({h}") for t in tools for h in heads)


def _rule_matches(text: str, pattern: str) -> bool:
    """The CLI's Bash rule glob: `*` is any text; a trailing ` *` that is
    the pattern's only wildcard also matches the bare command."""
    if pattern.endswith(" *") and pattern.count("*") == 1:
        base = pattern[:-2]
        return text == base or text.startswith(base + " ")
    rx = ".*".join(re.escape(part) for part in pattern.split("*"))
    return re.fullmatch(rx, text, flags=re.DOTALL) is not None


# Stands in for whitespace inside quotes while a command is scanned, so a
# quoted argument stays ONE word to the prefix strip and the word-suffix
# search (`PYTEST_ADDOPTS="-x -q" pytest tests/`); turned back into a space
# before any glob match.
_QUOTED_SPACE = "\x00"  # not str.isspace(), unlike the ASCII separators


def _shell_subcommands(cmd: str, *, heredoc_body: bool = False) -> list[str]:
    """`cmd` split into the subcommands the CLI matches rules against.

    Quote-aware. Inside single quotes everything is literal. Inside double
    quotes everything is literal except a backslash escape and a command
    substitution. A substitution -- `$(...)` or backticks, quoted or not --
    is its own subcommand AND leaves the command around it whole, as the CLI
    matched both live: it denied `echo "$(pytest tests/)"` (the inner one)
    and `pytest -k "$(cat k)" tests/` (the outer one); the substitution's
    place in the outer text is held by a `$_` word. Quotes are dropped, and
    whitespace inside them is kept as `_QUOTED_SPACE` so a quoted argument
    stays one word (an unbalanced quote falls back to plain spaces). Outside
    quotes the boundaries are `;`, `|`, `&` (so `&&` and `||` too), newline,
    a subshell's `(`/`)`, and `{`/`}` only as group words (whitespace or the
    string's edge on both sides) -- brace expansion such as `tests/{a,b}.py`
    is part of a word, which is how the CLI read it live. An unclosed
    substitution still contributes its outer command. Inside a
    substitution, while a `case` clause is open, a `)` ends a pattern, not
    the substitution. A backslash escapes the next character (an escaped
    blank stays in its word, as `_QUOTED_SPACE`), and a backslash-newline is
    removed, as bash removes it. Redirections outside quotes (`> f`,
    `2>&1`, `<in`, `> "a b"`) are dropped with their target, unless the
    target holds a substitution, which runs and is scanned. Whitespace is
    collapsed per subcommand.

    A here-document (`<<word`, `<<-word`; not the here-string `<<<`) is
    input, not commands, but its body is dropped only where the scan can
    show bash reads one (DESIGN §9): `<<` in plain command context -- not
    in a comment, nor inside `${…}`, `$[…]`, `$((…))` or `((…))` -- with a
    plain delimiter (`_heredoc_delimiter`) whose terminating line is
    present. Otherwise the text is read as commands, which at worst costs a
    false denial. An unquoted delimiter's body still expands its `$(...)`
    and backtick substitutions, which run and are scanned
    (`_heredoc_substitutions`). With `heredoc_body`, `cmd` is such a body:
    only its substitutions are read."""
    s = cmd
    n = len(s)
    segs: list[str] = []
    buf: list[str] = []
    quote: str | None = None
    # Open substitutions: (closing char, quote to restore, outer text).
    subst: list[tuple[str, str | None, list[str]]] = []
    # Open `case` clauses per substitution level (index 0: top level).
    cases: list[int] = [0]
    # Here-documents whose bodies start after the next newline:
    # (delimiter, `<<-` strips leading tabs, delimiter was quoted).
    heredocs: list[tuple[str, bool, bool]] = []
    bodies: list[str] = []
    # Open expansions in which `<<` is an operator, never a here-document:
    # [closer, nesting depth, substitution level read at, index of the
    # opener's own last bracket] for `${`, `$[`, `$((` / `((`. One whose
    # substitution closed before it (the scan closes `$(( (a) ))` at the
    # first `)`, as it always has) is never popped: the rest of the command
    # then has no here-document, the safe direction.
    expans: list[list] = []
    comment = False
    i = 0

    def cut() -> None:
        seg = "".join(buf)
        first = seg.split()[:1]
        if first == ["case"]:
            cases[-1] += 1
        elif first == ["esac"] and cases[-1]:
            cases[-1] -= 1
        segs.append(seg)
        buf.clear()

    def open_subst(closer: str, width: int) -> None:
        # The outer list is parked, not copied: copying made a run of
        # substitutions quadratic.
        nonlocal buf, quote, i
        subst.append((closer, quote, buf))
        cases.append(0)
        buf = []
        quote = None
        i += width

    def word_start(at: int) -> bool:
        return at == 0 or s[at - 1] in " \t\n;|&()"

    while i < n:
        ch = s[i]
        if quote == "'":
            if ch == "'":
                quote = None
            else:
                buf.append(_QUOTED_SPACE if ch.isspace() else ch)
            i += 1
            continue
        if quote == '"':
            if ch == '"':
                quote = None
            elif ch == "\\" and i + 1 < n:
                i += 1
                buf.append(s[i])
            elif s.startswith("$(", i) or ch == "`":
                if s.startswith("$((", i):
                    expans.append(["))", 0, len(subst) + 1, i + 2])
                open_subst(")" if ch == "$" else "`", 2 if ch == "$" else 1)
                continue
            else:
                buf.append(_QUOTED_SPACE if ch.isspace() else ch)
            i += 1
            continue
        if heredoc_body and not subst:
            # A body's own text: only an escape and a substitution are read.
            if ch == "\\":
                i += 2
            elif s.startswith("$(", i) or ch == "`":
                if s.startswith("$((", i):
                    expans.append(["))", 0, len(subst) + 1, i + 2])
                open_subst(")" if ch == "$" else "`", 2 if ch == "$" else 1)
            else:
                i += 1
            continue
        if ch in "'\"":
            quote = ch
            i += 1
            continue
        if ch == "\\" and i + 1 < n:
            # As bash reads it: an escaped blank is part of the word
            # (`bash -c pnpm\ test` passes ONE argument, `pnpm test`), and
            # backslash-newline is removed entirely (`pyt\<newline>est` is
            # `pytest`).
            nxt = s[i + 1]
            if nxt != "\n":
                buf.append(_QUOTED_SPACE if nxt.isspace() else nxt)
            i += 2
            continue
        # Expansions in which `<<` is a shift or a pattern, never a
        # here-document: observed only, the text read as before.
        live = bool(expans) and expans[-1][2] == len(subst)
        if live and i != expans[-1][3]:
            closer = expans[-1][0]
            if ch == {"}": "{", "]": "[", "))": "("}[closer]:
                expans[-1][1] += 1
            elif ch == closer[0] and expans[-1][1]:
                expans[-1][1] -= 1
            elif s.startswith(closer, i):
                expans.pop()
                live = False
        if s.startswith("${", i) or s.startswith("$[", i):
            expans.append(["}" if s[i + 1] == "{" else "]", 0, len(subst),
                           i + 1])
        elif s.startswith("$((", i):
            # `$(` opens a substitution below; the expansion is read there.
            expans.append(["))", 0, len(subst) + 1, i + 2])
        elif s.startswith("((", i) and not comment and (
                i == 0 or s[i - 1] != "$"):
            expans.append(["))", 0, len(subst), i + 1])
        if live and ch in "<>":
            # An operator of the expression, never a redirect.
            buf.append(ch)
            i += 1
            continue
        if subst and ch == subst[-1][0]:
            first = "".join(buf).split()[:1]
            if ch == ")" and (cases[-1] or first == ["case"]) \
                    and first != ["esac"]:
                # A `case` pattern's `)`: the clause's commands follow.
                cut()
                i += 1
                continue
            cut()
            _closer, quote, buf = subst.pop()
            cases.pop()
            buf.append("$_")
            i += 1
            continue
        if s.startswith("$(", i) or ch == "`":
            open_subst(")" if ch == "$" else "`", 2 if ch == "$" else 1)
            continue
        if ch == "#" and word_start(i) and not expans:
            comment = True
        if ch == "\n":
            comment = False
            if heredocs:
                cut()
                i += 1
                got = _heredoc_bodies(s, i, heredocs)
                heredocs.clear()
                if got is not None:
                    i, texts = got
                    bodies += texts
                continue
        if ch in ";|&\n()":
            cut()
            i += 1
            continue
        if (ch in "{}" and (i == 0 or s[i - 1].isspace())
                and (i + 1 == n or s[i + 1].isspace())):
            cut()
            i += 1
            continue
        if (s.startswith("<<", i) and not s.startswith("<<<", i)
                and not comment and not expans):
            delim = _heredoc_delimiter(s, i)
            if delim is not None:
                # A here-document: drop the operator and its delimiter word,
                # and remember the delimiter for the body after the newline.
                word, strip, quoted, i = delim
                while buf and buf[-1].isdigit():
                    buf.pop()
                heredocs.append((word, strip, quoted))
                buf.append(" ")
                continue
        if ch in "<>":
            # Drop an fd number glued to the operator (`2>`), the operator,
            # an `&` dup, and the target word -- quoted targets included.
            while buf and buf[-1].isdigit():
                buf.pop()
            i += 1
            while i < n and s[i] in "<>&":
                i += 1
            while i < n and s[i] in " \t":
                i += 1
            while i < n and not s[i].isspace() and s[i] not in ";|&()":
                # A substitution in the target runs; leave it to the main
                # scan (`> "$(pytest tests/)"` was denied live).
                if s.startswith("$(", i) or s[i] == "`":
                    break
                if s[i] in "'\"":
                    close = s.find(s[i], i + 1)
                    body = s[i + 1:] if close < 0 else s[i + 1:close]
                    if s[i] == '"' and ("$(" in body or "`" in body):
                        break
                    i = n if close < 0 else close + 1
                else:
                    i += 1
            buf.append(" ")
            continue
        buf.append(ch)
        i += 1
    if heredoc_body:
        # The top level is the body's text, never a command.
        buf.clear()
    cut()
    # An unclosed substitution still leaves its outer command to match.
    while subst:
        segs.append("".join(subst.pop()[2]))
    if quote is not None:
        # An unbalanced quote (an apostrophe in a comment or here-doc the
        # scan does not model) must not glue everything after it into one
        # word: fall back to plain spaces, as before quoted spaces existed.
        segs = [x.replace(_QUOTED_SPACE, " ") for x in segs]
    out = [seg for seg in (" ".join(x.split()) for x in segs) if seg]
    if heredoc_body:
        out = [seg for seg in out if seg != "$_"]
    for text in bodies:
        out += _heredoc_substitutions(text)
    return out


def _heredoc_delimiter(s: str, at: int) -> tuple[str, bool, bool, int] | None:
    """`(delimiter, strip_tabs, quoted, end)` of the here-document operator
    at `s[at]` (`<<` or `<<-`) when its delimiter is one the scan can match
    as bash does: a plain unquoted word, or a word wholly in `'…'` or
    `"…"`, holding no `$`, backquote or backslash. None for any other
    (`$'X'`, `E"O"F`, `\\EOF`, none at all): the caller then reads the text
    as commands. Mechanical string handling only."""
    n = len(s)
    i = at + 2
    strip = i < n and s[i] == "-"
    i += strip
    while i < n and s[i] in " \t":
        i += 1
    if i < n and s[i] in "'\"":
        close = s.find(s[i], i + 1)
        word = s[i + 1:close] if close > 0 else ""
        end = close + 1
        if close < 0 or not word or (end < n and not s[end].isspace()
                                     and s[end] not in ";|&()<>"):
            return None
        quoted = True
    else:
        j = i
        while j < n and not s[j].isspace() and s[j] not in ";|&()<>":
            j += 1
        word, end, quoted = s[i:j], j, False
        if not word or any(c in word for c in "'\""):
            return None
    if any(c in word for c in "$`\\\n"):
        return None
    return word, strip, quoted, end


def _heredoc_bodies(s: str, at: int, pending: list[tuple[str, bool, bool]]
                    ) -> tuple[int, list[str]] | None:
    """The here-document bodies starting at `s[at]` for the `pending`
    delimiters, in order: `(index after the last terminating line, the
    unquoted-delimiter bodies)`, or None when a terminating line is missing
    -- bash then reads to the end as body, and the scan, unable to agree
    line by line, reads the text as commands instead."""
    n = len(s)
    i = at
    texts: list[str] = []
    for delim, strip, quoted in pending:
        lines: list[str] = []
        while True:
            if i >= n:
                return None
            end = s.find("\n", i)
            line = s[i:] if end < 0 else s[i:end]
            i = n if end < 0 else end + 1
            if (line.lstrip("\t") if strip else line) == delim:
                break
            lines.append(line)
        if not quoted:
            texts.append("\n".join(lines))
    return i, texts


def _heredoc_substitutions(body: str) -> list[str]:
    """The subcommands of every `$(...)` and backtick substitution in an
    unquoted-delimiter here-document's `body`, which the shell expands and
    so runs; the rest of the body is text. The same quote-aware scan, in
    its body mode (`_shell_subcommands(body, heredoc_body=True)`), so a
    quoted `)` or a `case` pattern does not end a substitution early."""
    return _shell_subcommands(body, heredoc_body=True)


def _strip_command_prefixes(seg: str) -> str:
    """`seg` without the leading wrappers and environment assignments the
    CLI strips before matching (`_SUITE_WRAPPER_RE`, `_SUITE_ASSIGN_RE`)."""
    while True:
        out = _SUITE_ASSIGN_RE.sub("", _SUITE_WRAPPER_RE.sub("", seg, count=1),
                                   count=1)
        if out == seg:
            return seg
        seg = out


def _prescribed_commands(prescribed: dict | None) -> set[str]:
    """Whitespace-normalised commands the user's task PRESCRIBED, or an empty
    set unless `is_prescribed` is set (every consumer gates on it)."""
    if not isinstance(prescribed, dict) or not prescribed.get("is_prescribed"):
        return set()
    commands = prescribed.get("commands")
    if not isinstance(commands, list):
        return set()
    return {" ".join(c.split()) for c in commands if isinstance(c, str)}


def _denied_by_full_suite_rules(cmd: str, patterns: list[str], *,
                                anchored: bool = False) -> bool:
    """True when the whole-suite deny would refuse `cmd`, or (unanchored)
    when `cmd` is a paraphrase that only such a command could satisfy.

    Per subcommand, as the CLI matches. Unanchored -- the strip and the
    settle-time exemption -- every word of a subcommand is tried as a start:
    that covers the CLI's wrapper stripping (`timeout 590 pytest tests/`) and
    a declared paraphrase ("run pytest tests/ to verify", or the command in
    backticks), which the declared-command check would accept only the
    denied command for. That errs wide on purpose: there an over-match only
    drops a declared requirement. Anchored -- the prescribed-command check,
    where an over-match would disable the mechanism -- only the subcommand's
    start after the CLI's own wrappers is tried."""
    if not patterns or not isinstance(cmd, str):
        return False
    for seg in _shell_subcommands(cmd):
        if anchored:
            # Quoted text stays quoted: the CLI ran `"pytest tests/"`.
            starts = [_strip_command_prefixes(seg)]
        else:
            # Unanchored, a quoted span reads as words again, so a declared
            # paraphrase (`Run "pytest tests/" to verify`) is still stripped.
            words = seg.split()
            starts = [" ".join(words[i:]).replace(_QUOTED_SPACE, " ")
                      for i in range(len(words))]
        if any(_rule_matches(c, p) for c in starts for p in patterns):
            return True
    return False


# --- Forbidden commands (DESIGN §9 *A command the task forbids is denied in
# every spelling*) ---------------------------------------------------------
#
# The classifier types them (`process_constraints.forbidden_commands`);
# everything below compares SHELL COMMAND strings, never prose. Three
# consumers read one matcher, `_forbidden_command_hit`: the PreToolUse hook
# (`scripts/forbidden-command-hook.py`), `_measure_axes`, and the plan strip.
# The deny rules are derived separately because a CLI rule can only be a
# literal prefix; the hook is what covers wrappers, shells and interpreters.

FORBIDDEN_COMMANDS_NOTICE = (
    "this task forbids running {cmds}. Every spelling of these commands is "
    "denied to you — through a wrapper, a shell (`sh -c`), `eval`, "
    "`npx`/`corepack`, an interpreter (`node -e`, `python3 -c`), another "
    "package manager or an absolute path alike — so do not look for another "
    "way to run them. A criterion or repo rule that needs one is recorded "
    "`met: false, not_applicable: true` with evidence \"the task forbids "
    "this command\"; continue with the rest of the work.")

# Workers that type constraints from the task text: no `NOTE FROM
# ORCHESTRATOR:` is appended to their prompt, so none can come back as a
# constraint of the task (DESIGN §9 *A command the task forbids*).
NOTICE_FREE_WORKERS = frozenset({"classifier", "forbidden_command_extractor"})


def _confined_writes_notice(grants: WorkerGrants, *, cwd: str | Path,
                            env: Mapping[str, str]) -> str:
    """What a worker with a shell is told about where its processes can
    write (DESIGN §6 *A worker writes only where it is granted (I5)*),
    rendered from its own grant (`grants.rw`), so the notice and the kernel
    cannot disagree: every granted path but the device nodes, with the
    working directory, `$TMPDIR` and `$CLAUDE_CONFIG_DIR` named as such.
    An isolated worker (`_isolated()`) also has `/tmp`, its own, which the
    shim adds to every grant: the notice names it as private scratch gone
    when the session ends (DESIGN §6 *Every confined process has its own
    `/tmp`, `/dev/shm` and IPC*). Otherwise a fixed `/tmp/<name>` path —
    measured in 155 of 310 corpus sessions — is refused, and the notice
    says so."""
    names = {os.path.realpath(cwd): "your working directory"}
    for var in ("TMPDIR", "CLAUDE_CONFIG_DIR"):
        if env.get(var):
            names.setdefault(os.path.realpath(env[var]), f"${var}")
    labels = [names.get(os.path.realpath(p), f"`{p}`") for p in grants.rw
              if p not in _WORKER_DEVICES]
    first = [n for n in ("your working directory", "$TMPDIR",
                         "$CLAUDE_CONFIG_DIR") if n in labels]
    said = list(dict.fromkeys(first + labels))
    if _isolated():
        return (f"your processes can write only these: {'; '.join(said)}; "
                "and `/tmp`, which is your own: private scratch no other "
                "process sees, gone when your session ends. Every other "
                "path is not writable.")
    return (f"your processes can write only these: {'; '.join(said)}. "
            "`/tmp` and every other path are not writable; put scratch "
            "files in $TMPDIR.")

FORBIDDEN_WHOLE_SUITE_NOTICE = (
    "this task forbids running the whole test suite ({cmds}). A whole-suite "
    "run — the bare command, flags only, or aimed at a test directory, in "
    "any spelling — is denied to you; running it on the specific test files "
    "your change touches is allowed. A criterion or repo rule that needs the "
    "whole suite is recorded `met: false, not_applicable: true` with "
    "evidence \"the task forbids this command\"; the orchestrator runs the "
    "tests coupled to the run's changes itself.")

_FORBID_MAX_DEPTH = 5
_FORBID_WRAPPERS = frozenset({
    "timeout", "nice", "nohup", "stdbuf", "time", "command", "builtin",
    "exec", "sudo", "xargs", "ionice", "setsid", "chronic", "unbuffer",
    "noglob", "env", "then", "do", "else", "!", "xvfb-run"})
# Wrapper options that consume the next word. Fixed CLI surface of each tool.
_FORBID_WRAPPER_VALUE_OPTS: dict[str, frozenset[str]] = {
    "timeout": frozenset({"-s", "--signal", "-k", "--kill-after"}),
    "nice": frozenset({"-n", "--adjustment"}),
    "ionice": frozenset({"-c", "-n", "-p"}),
    "sudo": frozenset({"-u", "-g", "-C", "-D"}),
    "env": frozenset({"-u", "--unset", "-C", "--chdir"}),
    "xargs": frozenset({"-I", "-i", "-n", "-P", "-L", "-d", "-E", "-s", "-a"}),
    # getopt `+ae:f:hn:lp:s:w:` (Debian's /usr/bin/xvfb-run)
    "xvfb-run": frozenset({
        "-e", "--error-file", "-f", "--auth-file", "-n", "--server-num",
        "-p", "--xauth-protocol", "-s", "--server-args", "-w", "--wait"}),
}
# Short letters taking a value, for wrappers parsed by getopt, whose letters
# cluster (`xvfb-run -as ARGS`: `-a`, then `-s` taking the next word).
_FORBID_WRAPPER_VALUE_LETTERS: dict[str, str] = {"xvfb-run": "efnpsw"}
_FORBID_SHELLS = frozenset({"bash", "sh", "zsh", "dash", "ksh"})
_FORBID_PROXIES = frozenset({"npx", "pnpx", "bunx", "corepack"})
_FORBID_PMS = frozenset({"npm", "pnpm", "yarn", "bun"})
# Package-manager options that consume the next word, per manager: one
# table for all of them was wrong both ways — pnpm's `-w` is the flag
# `--workspace-root`, npm's is `--workspace <name>`. From each tool's
# `--help` (pnpm 11, npm 11, yarn 1 and 4, bun 1) and checked by running
# the real pnpm/npm/yarn (tests/test_forbidden_pm_flags.py).
_FORBID_PM_VALUE_OPTS: dict[str, frozenset[str]] = {
    "pnpm": frozenset({
        "-C", "--dir", "-F", "--filter", "--filter-prod", "--loglevel",
        "--reporter", "--workspace-concurrency", "--resume-from",
        "--test-pattern", "--changed-files-ignore-pattern"}),
    "npm": frozenset({
        "-w", "--workspace", "-C", "--prefix", "--loglevel",
        "--script-shell", "--userconfig", "--globalconfig", "--cache",
        "--registry", "--include", "--omit"}),
    "yarn": frozenset({
        "--cwd", "--modules-folder", "--cache-folder", "--mutex",
        "--network-timeout", "--network-concurrency", "--registry",
        "--global-folder", "--link-folder", "--use-yarnrc", "--otp",
        # yarn 4 `workspaces foreach`
        "--from", "--include", "--exclude", "-j", "--jobs"}),
    "bun": frozenset({
        "--cwd", "-F", "--filter", "-c", "--config", "--env-file",
        "-r", "--preload", "--shell", "--elide-lines"}),
}
# pnpm options that make it run a script in the selected packages and never
# fall back to a package binary (`pnpm -r vitest`: "None of the selected
# packages has a \"vitest\" script"). Measured with the real pnpm 11.21
# (tests/fixtures/forbid_runner_options.json, "pnpm binary fallback").
_FORBID_PNPM_SCRIPT_ONLY_OPTS = frozenset({
    "-r", "--recursive", "-F", "--filter", "--filter-prod"})
# Subcommands that only select where the real one runs: `pnpm recursive
# run test` is `pnpm -r run test`, `yarn workspace web test` runs `test` in
# one workspace. The int is how many words they take (the name).
_FORBID_PM_SCOPE_SUBS: dict[str, dict[str, int]] = {
    "pnpm": {"recursive": 0, "multi": 0, "m": 0},
    "yarn": {"workspace": 1},
}
_FORBID_PM_SCRIPT_ALIASES = {"t": "test", "tst": "test"}
_FORBID_PM_BUILTIN_SCRIPTS = frozenset({"test", "start", "stop", "restart"})
# Interpreter flags whose next word is code to run.
_FORBID_INTERP_EVAL: dict[str, frozenset[str]] = {
    "node": frozenset({"-e", "-p", "--eval", "--print", "-pe"}),
    "python": frozenset({"-c"}),
    "python3": frozenset({"-c"}),
    "perl": frozenset({"-e", "-E"}),
    "ruby": frozenset({"-e"}),
    "deno": frozenset({"eval"}),
    "bun": frozenset({"-e", "--eval"}),
}
# A string literal inside interpreter code (JS/Python/Ruby/Perl source —
# program text, a mechanical string, never prose).
_FORBID_STR_LIT = re.compile(
    r"""'((?:[^'\\]|\\.)*)'|"((?:[^"\\]|\\.)*)"|`((?:[^`\\]|\\.)*)`""")
_FORBID_ASSIGN = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*=")
# The token a pnpm `--filter` value travels as beside a run's environment.
_FORBID_PNPM_FILTER = "pnpm --filter "
# JS wrappers that set an environment, then run a command (DESIGN §9 *A
# script's environment is part of what it runs*). Each is parsed as its own
# CLI parser reads it, measured with the real tool: cross-env 10.1
# (`dist/index.js` `parseCommand`: no options, leading words its setter
# regex `(\w+)=…` finds — unanchored — are assignments, empty words are
# skipped), dotenv-cli 11.1 (`cli.js`: minimist with no option table) and
# env-cmd 11.0 (`dist/parse-args.js`: commander).
_FORBID_ENV_WRAPPERS = frozenset({
    "cross-env", "cross-env-shell", "dotenv", "dotenv-cli", "env-cmd"})
_CROSS_ENV_SETTER = re.compile(r"""(\w+)=('(.*)'|"(.*)"|(.*))""")
# env-cmd's commander options: `-f`/`-r` take an optional value, `-e` a
# variadic optional one; the rest are flags. `-v`/`-h` print and exit.
_ENV_CMD_OPTS = {
    "-f": "file", "--file": "file", "-r": "rc", "--rc-file": "rc",
    "-e": "envs", "--environments": "envs", "-x": "", "--expand-envs": "",
    "--recursive": "", "--fallback": "", "--no-override": "",
    "--silent": "", "--use-shell": "shell", "--verbose": "",
    "-v": "exit", "--version": "exit", "-h": "exit", "--help": "exit"}


def _forbidden_minimist(words: list[str]
                        ) -> tuple[list[str], list[tuple[str, str | bool]]]:
    """`(positionals, [(key, value)])` as minimist 1.2 parses `words` with
    no option table (dotenv-cli): `--k=v`; `--no-k` is false; `--k` and a
    short cluster's last letter take the next word unless it starts with
    `-`; a cluster letter followed by `=`, a number or a non-word
    character takes the rest of the word; positionals are collected across
    options; `--` ends options. A port of minimist's `parseArgs` loop (a
    mechanical CLI grammar)."""
    pos: list[str] = []
    opts: list[tuple[str, str | bool]] = []
    # minimist cuts at the first `--` before parsing, so an option just
    # before it takes no value (`dotenv -c -- cmd`).
    tail: list[str] = []
    if "--" in words:
        k = words.index("--")
        words, tail = words[:k], words[k + 1:]
    i = 0
    while i < len(words):
        w = words[i]
        nxt = words[i + 1] if i + 1 < len(words) else None
        i += 1
        if re.match(r"--[^=]+=", w):
            k, v = w[2:].split("=", 1)
            opts.append((k, v))
        elif re.match(r"--no-.", w):
            opts.append((w[5:], False))
        elif re.match(r"--.", w):
            if nxt is not None and not re.match(r"(-|--)[^-]", nxt):
                opts.append((w[2:], nxt))
                i += 1
            else:
                opts.append((w[2:], True))
        elif re.match(r"-[^-]", w):
            letters = w[1:-1]
            broken = False
            for j, ch in enumerate(letters):
                rest = w[j + 2:]
                if rest == "-":
                    opts.append((ch, rest))
                    continue
                if ch.isalpha() and rest[:1] == "=":
                    opts.append((ch, rest[1:]))
                elif ch.isalpha() and re.search(
                        r"-?\d+(\.\d*)?(e-?\d+)?$", rest):
                    opts.append((ch, rest))
                elif j + 1 < len(letters) and re.match(r"\W", letters[j + 1]):
                    opts.append((ch, rest))
                else:
                    opts.append((ch, True))
                    continue
                broken = True
                break
            key = w[-1]
            if not broken and key != "-":
                if nxt and not re.match(r"(-|--)[^-]", nxt):
                    opts.append((key, nxt))
                    i += 1
                else:
                    opts.append((key, True))
        else:
            pos.append(w)
    return pos + tail, opts


def _forbidden_env_opt(a: list[str]) -> set[str]:
    """The environment tokens of `env`'s option at `a[0]` (`-u NAME`,
    `--unset=NAME`, `-i`/`-`/`--ignore-environment`, `-C DIR`,
    `--chdir=DIR`)."""
    opt = a[0]
    val = a[1] if len(a) > 1 else ""
    if opt in ("-i", "-", "--ignore-environment"):
        return {"-i"}
    for short, long_ in (("-u", "--unset"), ("-C", "--chdir")):
        if opt == short or opt == long_:
            return {f"{short} {val}"} if val else set()
        if opt.startswith(long_ + "="):
            return {f"{short} {opt[len(long_) + 1:]}"}
        if opt.startswith(short) and len(opt) > 2:
            return {f"{short} {opt[2:]}"}
    return set()


def _forbidden_env_wrapper(a: list[str]
                           ) -> tuple[list[str], set[str], bool] | None:
    """`(command argv, environment tokens, via a shell)` an env wrapper
    (`_FORBID_ENV_WRAPPERS`) runs, or None when it runs nothing (no
    command, or an option that prints and exits)."""
    head = os.path.basename(a[0])
    toks: set[str] = set()
    if head in ("cross-env", "cross-env-shell"):
        i = 1
        while i < len(a):
            m = _CROSS_ENV_SETTER.search(a[i]) if a[i] else None
            if a[i] and not m:
                break
            if m:
                val = (m.group(3) if m.group(3) is not None else
                       m.group(5) or "" if m.group(4) is None else m.group(4))
                toks.add(f"{m.group(1)}={val}")
            i += 1
        return (a[i:], toks, head == "cross-env-shell") if a[i:] else None
    if head in ("dotenv", "dotenv-cli"):
        pos, opts = _forbidden_minimist(a[1:])
        keys = {k for k, _v in opts}
        if keys & {"help", "debug", "p"} or not pos:
            return None
        files = [v for k, v in opts if k == "e" and isinstance(v, str)]
        files = files or [".env"]
        casc = [v for k, v in opts if k == "c"]
        if casc:
            c = casc[-1]
            files = [x for f in files for x in (
                [f"{f}.{c}.local", f"{f}.local", f"{f}.{c}", f]
                if isinstance(c, str) else [f"{f}.local", f])]
        toks |= {"envfile:" + _forbidden_operand(f) for f in files}
        toks |= {v for k, v in opts if k == "v" and isinstance(v, str)
                 and re.fullmatch(r"\w+=[\s\S]+", v)}
        return pos, toks, False
    # env-cmd
    r = a[1:]
    vals: dict[str, list[str]] = {"file": [], "envs": []}
    seen: set[str] = set()
    while r and r[0].startswith("-") and r[0] != "-":
        w = r.pop(0)
        if w == "--":
            break
        name, eq, val = w.partition("=") if w.startswith("--") \
            else (w[:2], "", w[2:])
        kind = _ENV_CMD_OPTS.get(name)
        if kind == "exit" or kind == "rc":
            return None
        seen.add(kind or "")
        if kind == "file":
            if not (eq or val) and r and not r[0].startswith("-"):
                val = r.pop(0)
            vals["file"].append(val)
        elif kind == "envs":
            got = [val] if (eq or val) else []
            while r and not r[0].startswith("-"):
                got.append(r.pop(0))
            vals["envs"] += [e for g in got for e in g.split(",") if e]
        elif kind == "" and not w.startswith("--") and val:
            # A flag cluster (`-xf .env`): commander splits it.
            r.insert(0, "-" + val)
    if not r:
        return None
    if vals["envs"]:
        toks |= {f"env-cmd -e {e}" for e in vals["envs"]}
    else:
        f = next((x for x in reversed(vals["file"]) if x), ".env")
        toks.add("envfile:" + _forbidden_operand(f))
    return r, toks, "shell" in seen


def _forbidden_argvs(cmd: str, depth: int = 0,
                     keep_xargs: bool = False) -> list[list[str]]:
    """Every normalised argv `cmd` runs (IMPLEMENTATION §5½ *Forbidden
    commands*): split with the whole-suite matcher's quote-aware scan, then
    each subcommand unwrapped by `_forbidden_normalize`. `keep_xargs` keeps
    an `xargs` head as a leading `"xargs"` word instead of unwrapping it
    away, so the process-kill matcher can tell `xargs kill` from `kill`."""
    return [a for a, _env in _forbidden_argvs_env(cmd, depth, keep_xargs)]


def _forbidden_argvs_env(cmd: str, depth: int = 0, keep_xargs: bool = False,
                         env: frozenset[str] = frozenset()
                         ) -> list[tuple[list[str], frozenset[str]]]:
    """`_forbidden_argvs` with the environment each argv runs in (DESIGN §9
    *A script's environment is part of what it runs*): a set of tokens —
    `NAME=value`, `-u NAME`, `-i`, `-C <dir>` (env's own options),
    `envfile:<path>` (a file an env wrapper loads), `env-cmd -e <env>` —
    collected from the words the unwrapping drops. A command's
    `export`/bare assignment/`source` statements count for every argv of
    the command, which can only over-read it."""
    if depth > _FORBID_MAX_DEPTH or not isinstance(cmd, str):
        return []
    argvs = [[w.replace(_QUOTED_SPACE, " ") for w in seg.split()]
             for seg in _shell_subcommands(cmd)]
    shared = set(env)
    for argv in argvs:
        shared |= _forbidden_env_statement(argv)
    out: list[tuple[list[str], frozenset[str]]] = []
    for argv in argvs:
        out.extend(_forbidden_normalize(argv, depth, keep_xargs,
                                        frozenset(shared)))
    return out


def _forbidden_env_statement(argv: list[str]) -> set[str]:
    """The environment tokens a shell statement sets for the commands after
    it: `export`/`declare`/`typeset`/`readonly` assignments, an
    assignment-only statement, and `source`/`.` of a file."""
    if not argv:
        return set()
    if all(_FORBID_ASSIGN.match(w) for w in argv):
        return set(argv)
    if argv[0] in ("export", "declare", "typeset", "readonly"):
        return {w for w in argv[1:] if _FORBID_ASSIGN.match(w)}
    if argv[0] in ("source", ".") and len(argv) > 1:
        return {"envfile:" + _forbidden_operand(argv[1])}
    return set()


def _forbidden_interp_head(word: str) -> str:
    """`python3.12` and `/usr/bin/python3` read as `python3` (a binary
    name — a mechanical string)."""
    head = os.path.basename(word)
    return "python3" if re.fullmatch(r"python[0-9.]*", head) else head


def _forbidden_normalize(argv: list[str], depth: int,
                         keep_xargs: bool = False,
                         env: frozenset[str] = frozenset()
                         ) -> list[tuple[list[str], frozenset[str]]]:
    a = list(argv)
    env = set(env)
    while a:
        head = os.path.basename(a[0])
        if _FORBID_ASSIGN.match(a[0]):
            env.add(a[0])
            a = a[1:]
            continue
        if head in _FORBID_ENV_WRAPPERS:
            got = _forbidden_env_wrapper(a)
            if got is None:
                return []
            a, toks, via_shell = got
            env |= toks
            if via_shell:
                return _forbidden_argvs_env(" ".join(a), depth + 1,
                                            keep_xargs, frozenset(env))
            continue
        if head in _FORBID_WRAPPERS:
            if keep_xargs and head == "xargs":
                rest = a[1:]
                vals = _FORBID_WRAPPER_VALUE_OPTS["xargs"]
                while rest and rest[0].startswith("-"):
                    rest = rest[2:] if rest[0] in vals else rest[1:]
                return [(["xargs"] + r, e) for r, e in
                        (_forbidden_normalize(rest, depth, keep_xargs,
                                              frozenset(env))
                         if rest else [([], frozenset(env))])]
            vals = _FORBID_WRAPPER_VALUE_OPTS.get(head, frozenset())
            a = a[1:]
            while a:
                opt = a[0]
                if head == "env" and opt in ("-S", "--split-string") \
                        and len(a) > 1:
                    return _forbidden_argvs_env(a[1], depth + 1, keep_xargs,
                                                frozenset(env))
                if head == "env":
                    env |= _forbidden_env_opt(a)
                letters = _FORBID_WRAPPER_VALUE_LETTERS.get(head, "")
                if opt in vals:
                    a = a[2:]
                elif letters and re.fullmatch(r"-[A-Za-z]+", opt):
                    # The first value letter takes the rest of the word, or
                    # the next word when it is last.
                    k = next((n for n, ch in enumerate(opt[1:], 1)
                              if ch in letters), 0)
                    a = a[2:] if k == len(opt) - 1 else a[1:]
                elif opt.startswith("-") or _FORBID_ASSIGN.match(opt) or (
                        head == "timeout" and opt[:1].isdigit()):
                    if _FORBID_ASSIGN.match(opt):
                        env.add(opt)
                    a = a[1:]
                else:
                    break
            continue
        if head in _FORBID_PROXIES:
            a = a[1:]
            while a and a[0].startswith("-"):
                if a[0] in ("-c", "--call") and len(a) > 1:
                    return _forbidden_argvs_env(a[1], depth + 1, keep_xargs,
                                                frozenset(env))
                a = a[2:] if a[0] in ("-p", "--package") else a[1:]
            if a:
                a = [_forbidden_package_word(a[0])] + a[1:]
            continue
        if head in _FORBID_SHELLS:
            for i, w in enumerate(a[1:], 1):
                if w.startswith("-") and not w.startswith("--") and "c" in w:
                    return (_forbidden_argvs_env(a[i + 1], depth + 1,
                                                 keep_xargs, frozenset(env))
                            if i + 1 < len(a) else [])
            break
        if head == "eval":
            return _forbidden_argvs_env(" ".join(a[1:]), depth + 1,
                                        keep_xargs, frozenset(env))
        if head in _FORBID_RUN_WRAPPERS:
            inner = _forbidden_run_wrapper(a)
            if inner is None:
                break
            a = inner
            continue
        if _forbidden_interp_head(a[0]) == "python3":
            inner = _forbidden_python_module(a[1:])
            if inner is not None:
                a = inner
                continue
        if head == "node":
            inner = _forbidden_node_script(a[1:])
            if inner is not None:
                a = inner
                continue
        flags = _FORBID_INTERP_EVAL.get(_forbidden_interp_head(a[0]))
        if flags:
            for i, w in enumerate(a[1:], 1):
                if w in flags and i + 1 < len(a):
                    code = a[i + 1]
                    fenv = frozenset(env)
                    out = _forbidden_argvs_env(code, depth + 1, keep_xargs,
                                               fenv)
                    for m in _FORBID_STR_LIT.finditer(code):
                        lit = next(g for g in m.groups() if g is not None)
                        out.extend(_forbidden_argvs_env(
                            lit, depth + 1, keep_xargs, fenv))
                    return out
        break
    if not a:
        return []
    fenv = frozenset(env)
    a[0] = os.path.basename(a[0])
    if a[0] in _FORBID_PMS:
        vals = _FORBID_PM_VALUE_OPTS[a[0]]
        scopes = _FORBID_PM_SCOPE_SUBS.get(a[0], {})

        def _opts(r: list[str]) -> list[str]:
            i = 0
            while i < len(r) and r[i].startswith("-"):
                i += 2 if r[i] in vals else 1
            return r[i:]
        raw = a[1:]
        rest = _opts(raw)
        gopts = raw[:len(raw) - len(rest)]
        if a[0] == "pnpm":
            # Which packages the script runs in (DESIGN §9 *A pnpm filter
            # that names one package of several is scoped*).
            fenv = fenv | _forbidden_pnpm_filters(raw, vals)
        script_only = any(w.split("=", 1)[0] in _FORBID_PNPM_SCRIPT_ONLY_OPTS
                          for w in raw[:len(raw) - len(rest)])
        while rest:
            if rest[0] in scopes:
                script_only = True
                rest = _opts(rest[1 + scopes[rest[0]]:])
            elif (a[0] == "yarn" and rest[0] == "workspaces"
                    and len(rest) > 1 and rest[1] in ("run", "foreach")):
                # yarn 1 `workspaces run <script>`; yarn 4 `workspaces
                # foreach [opts] <script|run script>`.
                rest = (rest[1:] if rest[1] == "run"
                        else _opts(rest[2:]))
            else:
                break
        a = [a[0]] + rest
        if len(a) > 1:
            sub = a[1]
            # `x` is exec in npm and bun; pnpm 11 has no such command and
            # runs a binary named `x` (DESIGN §9 *pnpm's binary fallback*).
            if sub in ("exec", "dlx") or (sub == "x" and a[0] != "pnpm"):
                r = a[2:]
                ended = False
                while r and r[0].startswith("-"):
                    if r[0] in ("-c", "--call") and len(r) > 1:
                        return _forbidden_argvs_env(r[1], depth + 1,
                                                    keep_xargs, fenv)
                    ended = ended or r[0] == "--"
                    r = r[1:]
                if r:
                    r = [_forbidden_package_word(r[0])] + r[1:]
                return _forbidden_normalize(
                    r if ended else _forbidden_pm_passthrough(a[0], r),
                    depth + 1, keep_xargs, fenv)
            if sub in ("run", "run-script"):
                if a[0] == "pnpm":
                    # A `-w` among the global options joins a filter among
                    # the run's own: one option list to pnpm.
                    fenv = fenv | _forbidden_pnpm_filters(gopts + a[2:],
                                                          vals)
                a = [a[0], "run"] + _opts(a[2:])
            elif sub in _FORBID_PM_SCRIPT_ALIASES:
                a = [a[0], "run", _FORBID_PM_SCRIPT_ALIASES[sub]] + a[2:]
            elif sub in _FORBID_PM_BUILTIN_SCRIPTS:
                a = [a[0], "run"] + a[1:]
            elif a[0] != "npm" and not sub.startswith("-"):
                # `pnpm vitest run`: pnpm, yarn and bun run a script of that
                # name, else the package binary — both readings are argvs.
                # pnpm reads its options' values only on the way to a
                # script: its binary is read from the words as typed, every
                # option a bare flag (DESIGN §9 *pnpm's binary fallback*).
                if a[0] == "pnpm":
                    binary = (None if script_only
                              else _forbidden_pnpm_binary(raw))
                    return [(a, fenv)] + (_forbidden_normalize(
                        _forbidden_pm_passthrough("pnpm", binary),
                        depth + 1, keep_xargs, fenv) if binary else [])
                return [(a, fenv)] + _forbidden_normalize(
                    _forbidden_pm_passthrough(a[0], a[1:]), depth + 1,
                    keep_xargs, fenv)
    return [(a, fenv)]


def _forbidden_pnpm_filters(words: list[str],
                            vals: frozenset[str]) -> frozenset[str]:
    """`pnpm --filter <value>` tokens for each `--filter`/`-F`/
    `--filter-prod` among the leading options of `words` (`=` spellings
    included), plus `pnpm --filter .` when `-w`/`--workspace-root` stands
    beside a filter: pnpm then runs the root too (measured with pnpm
    11.21, round-6 review M1). Alone, `-w` adds no token — the run is the
    root's, as an unfiltered one is."""
    out: set[str] = set()
    root = False
    i = 0
    while i < len(words) and words[i].startswith("-"):
        name, eq, val = words[i].partition("=")
        if name in ("--filter", "-F", "--filter-prod"):
            if not eq:
                val = words[i + 1] if i + 1 < len(words) else ""
            if val:
                out.add(_FORBID_PNPM_FILTER + val)
        root = root or words[i] in ("-w", "--workspace-root")
        i += 2 if words[i] in vals else 1
    if root and out:
        out.add(_FORBID_PNPM_FILTER + ".")
    return frozenset(out)


def _forbidden_filter_scoped(env: frozenset[str],
                             package_name: str | None) -> bool:
    """True when `env` carries pnpm filters and none selects the root
    package — `*`, `**`, a path glob matching `.` (`./**`, `{./**}`,
    `{**}`, `./`, `{.}`), a name pattern matching `package_name`, or
    (conservatively, the matcher reads no dependency graph) an exclusion
    `!x`, a changed-since `[ref]`, a dependency-closure selector (`...x`,
    `x...`, `^x`) or an absolute path. Measured with pnpm 11.21 (DESIGN
    §9 *A pnpm filter that names one package of several is scoped*)."""
    vals = [t[len(_FORBID_PNPM_FILTER):] for t in env
            if t.startswith(_FORBID_PNPM_FILTER)]
    if not vals:
        return False
    for v in vals:
        if (v.startswith(("!", "^", "...", "/")) or v.endswith("...")
                or "[" in v):
            return False
        sel = v
        path = sel.startswith(".")
        if sel.startswith("{") and sel.endswith("}"):
            sel, path = sel[1:-1], True
        if path:
            # A path glob selects the root when it matches `.`: only
            # `**` segments, or the root itself (`./*` matched nothing).
            norm = _forbidden_operand(sel)
            if norm == "." or set(norm.split("/")) == {"**"} \
                    or sel.startswith("/"):
                return False
            continue
        if sel in ("*", "**"):
            return False
        if package_name and fnmatch.fnmatchcase(package_name, sel):
            return False
    return True


def _forbidden_package_word(word: str) -> str:
    """The package a runner proxy (`npx`, `bunx`, `pnpm dlx`, `yarn dlx`,
    `npm exec`, `corepack`) is handed, without its version: `vitest@3`
    → `vitest`, `@scope/pkg@^1` → `@scope/pkg` (npm package-spec syntax, a
    mechanical string). The proxy runs that package's binary."""
    at = word.find("@", 1)
    return word[:at] if at > 0 else word


def _forbidden_pnpm_binary(words: list[str]) -> list[str] | None:
    """The argv pnpm runs when the word after its options is neither one of
    its commands nor a script: it reads no option's value there, so the
    binary is the first word that does not start with `-` (one `--` before
    it is dropped) and every word after it is handed on — `pnpm --dir .
    vitest` runs `.`, `pnpm -C vitest y` runs `vitest y` in `vitest/`.
    pnpm's own fallback (its run handler) strips the leading dash words of
    the original argv exactly so; measured with the real pnpm 11.21 through
    real bash (`tests/test_forbidden_pm_flags.py`)."""
    i = 0
    while i < len(words) and words[i].startswith("-") and words[i] != "--":
        i += 1
    if i < len(words) and words[i] == "--":
        i += 1
    return words[i:] or None


def _forbidden_pm_passthrough(pm: str, r: list[str]) -> list[str]:
    """The argv a package manager hands the binary `r[0]`: npm and yarn
    drop the first `--` after it (`npm exec vitest -- run` runs `vitest
    run`) unless a `--` before the binary already ended their options;
    pnpm, bun and npx pass it through. Measured with the real managers
    (`tests/test_forbidden_runner_spellings.py`)."""
    if pm in ("npm", "yarn") and "--" in r[1:]:
        i = r.index("--", 1)
        return r[:i] + r[i + 1:]
    return r


def _forbidden_prefix_match(cand: list[str], forb: list[str]) -> bool:
    if not forb or len(cand) < len(forb):
        return False
    if (cand[0] in _FORBID_PMS and forb[0] in _FORBID_PMS
            and len(forb) > 1 and forb[1] == "run"):
        # `npm test` runs the same package.json script as `pnpm run test`.
        return cand[1:len(forb)] == forb[1:]
    return cand[:len(forb)] == forb


FORBID_SCOPES = ("any", "whole_suite")


def _forbidden_spec(f: object) -> tuple[str, str, list[str]] | None:
    """`(command, scope, test roots)` of one forbidden entry: a bare string
    (the pre-scope shape, and every non-task caller such as the kill rules)
    is `scope: "any"`; a dict is a persisted `_process_constraints` entry.
    None for anything else."""
    if isinstance(f, str):
        return (f, "any", []) if f.strip() else None
    if isinstance(f, dict) and isinstance(f.get("command"), str) \
            and f["command"].strip():
        scope = f.get("scope") if f.get("scope") in FORBID_SCOPES else "any"
        roots = [r for r in (f.get("test_roots") or [])
                 if isinstance(r, str) and r.strip("/")]
        return f["command"], scope, roots
    return None


